local P = LoreForeverPacks.Begin("LoreForever_Lang_deDE")
P.entries["quest:1429"] = {n="Der Verbannte der Atal'ai",s="In Steinard schickt Fel'zerul Euch mit den Artefakten vom Tränenteich nach Norden. Findet einen verbannten Priester der Atal'ai im Hinterland und erfahrt, wozu die Artefakte dienen.",h="In Steinard schickt Fel'zerul Euch mit den Artefakten vom Tränenteich nach Norden.",kw={"verbannter der atal'ai","fel'zerul","hakkar","hinterland","jammal'an","tränenteich","shadra'alor","sümpfe des elends","witherbark"},sec={{t="Ein Urteil in Blut",b="Eine mit Blut gezeichnete Schriftrolle verurteilt einen Priester der Atal'ai zu einem Schicksal, das unter seinem eigenen Volk schlimmer als der Tod ist. Er wird fortgeschickt, um bei den Witherbark-Trollen weit im Norden im Hinterland zu leben. Fel'zerul bündelt die Artefakte und schickt Euch los, um den Verbannten zu finden, ihren wahren Verwendungszweck zu erfahren und zurückzukehren."},{t="Die Worte des Verbannten",b="Der Verbannte der Atal'ai bezeichnet die Artefakte als Beschwörungswerkzeuge, als ihm das Bündel gezeigt wird. Er sagt, Jammal'an der Prophet führe die Jünger der Kammer des Blutes ihrem auserwählten Schicksal entgegen. Der Verbannte fragt sich, ob Hakkar in den Tempel zurückgekehrt ist."}},faq={{q="Wer schickt Euch los, um den Verbannten der Atal'ai zu finden?",a="Fel'zerul in Steinard schickt Euch mit den von Euch gesammelten Artefakten nach Norden.",al={"wer vergibt verbannter der atal'ai","verbannter der atal'ai questgeber","wer beginnt die quest"}},{q="Wo befindet sich der Verbannte der Atal'ai?",a="Der Verbannte der Atal'ai lebt bei den Witherbark-Trollen am Tempel von Shadra'Alor im Hinterland.",al={"wo ist der verbannte","verbannter der atal'ai aufenthaltsort","wo ist der verbannte der atal'ai zu finden"}},{q="Welches Urteil wurde über den Priester verhängt?",a="Eine mit Blut gezeichnete Schriftrolle verurteilt den Priester zur Verbannung unter die Witherbark-Trolle im Hinterland, einem Schicksal, das unter den Atal'ai schlimmer als der Tod ist.",al={"warum wurde er verbannt","wie lautete das urteil","verbannter der atal'ai hintergrundgeschichte"}},{q="Was bringt Ihr dem Verbannten?",a="Ihr tragt Artefakte der Atal'ai bei Euch, die am Tränenteich gesammelt wurden. Fel'zerul will, dass der Verbannte ihren wahren Verwendungszweck enthüllt.",al={"welches bündel wird überbracht","was sind die artefakte","atal'ai artefakte verwendungszweck"}},{q="Was geht dieser Reise unmittelbar voraus?",a="Eure Reise folgt auf „Tränenteich“, wo Fel'zerul Euch Artefakte der Atal'ai sammeln ließ.",al={"vorherige quest","voraussetzung","was führt zu verbannter der atal'ai"}}},fp="17,167,19.274.0,17.249.1,40.69.0,35.99.0,39.142.0,35.110.0,40.85.0"}
P.entries["quest:143"] = {n="Botschaft nach Westfall",s="In Seenhain schickt Magistrat Solomon einen Hilferuf gegen die Schwarzfelsorcs und Gnolle nach Westen. Da Sturmwinds Streitkräfte fehlen, hofft er, dass Gryan Starkmantels Volksmiliz dem Rotkammgebirge helfen kann.",h="In Seenhain schickt Magistrat Solomon einen Hilferuf gegen die Schwarzfelsorcs und Gnolle nach Westen.",kw={"gryan starkmantel","seenhain","magistrat solomon","volksmiliz","rotkammgebirge","späherkuppe","solomons hilferuf","westfall"},ang={["faction:Alliance"]="Diese Depesche zeigt, wie wenig von der zentralen Verteidigung im Königreich Sturmwind übrig ist. Grenzstädte müssen sich eigenständig um gegenseitige Hilfe bemühen.",["race:Human"]="Als Mensch teilt Ihr die Nöte der Siedler im Rotkammgebirge und in Westfall. Sie verlassen sich auf Freiwillige und Söldner, während die Hauptstadt untätig bleibt."},sec={{t="Ein verzweifelter Hilferuf",b="Schwarzfelsorcs und Gnolle belagern Seenhain, doch die Armee von Sturmwind ist nicht in voller Stärke eingetroffen. Magistrat Solomon weiß, dass die Stadtwachen und Freischärler das Rotkammgebirge nicht allein halten können. Da keine königlichen Reserven in Sicht sind, verfasst er ein förmliches Hilfsgesuch. Er hat von einer Bürgerwehr gehört, die sich westlich des Waldes von Elwynn formiert, und schickt seinen Hilferuf dorthin."},{t="Hilfe über die Grenzen",b="Gryan Starkmantel ist ein erfahrener Kommandant, der freiwillige Kämpfer unter dem Banner der Volksmiliz versammelt. Solomon schickt seine Depesche quer durch das Königreich und hofft, dass Westfalls Freiwillige Seenhains Grenzen verstärken können, bis die Armeen der Krone mobilmachen. Doch Westfall führt selbst einen verzweifelten Kampf gegen die Bruderschaft der Defias."}},faq={{q="Warum bittet Magistrat Solomon Westfall um Hilfe?",a="Sturmwind hat die Verstärkung nicht geschickt, die Seenhain gegen die Orcs und Gnolle braucht. Solomon hat gehört, dass sich in Westfall eine bewaffnete Bürgerwehr sammelt, und hofft, dass Gryan Starkmantel Truppen für das Rotkammgebirge entbehren kann.",al={"warum westfall","solomons hilferuf","warum gryan bitten"}},{q="Wer ist Gryan Starkmantel?",a="Gryan Starkmantel ist ein erfahrener Soldat auf der Späherkuppe in Westfall. Da die Autorität und der Schutz der Krone fehlen, hat er die Volksmiliz gegründet und führt sie, um die örtlichen Gehöfte vor Räubern und der Bruderschaft der Defias zu schützen.",al={"wer ist gryan","starkmantels rolle","wer führt westfall"}},{q="Wohin führt diese Botenreise?",a="Ihr bringt die Nachricht vom Rathaus in Seenhain westwärts durch das Rotkammgebirge und den Wald von Elwynn zur Späherkuppe im Herzen Westfalls.",al={"wohin liefern","wo ist starkmantel","vom rotkammgebirge nach westfall"}},{q="Warum hat die Armee von Sturmwind Seenhain noch nicht entsetzt?",a="Magistrat Solomon sagt, dass bei der Armee etwas nicht stimmt, weil die versprochenen Truppen nicht eingetroffen sind. Der König ist abwesend und Hochlord Bolvar Fordragon herrscht als Regent, während die entlegenen Gebiete ohne die erwarteten Reserven auskommen müssen.",al={"warum keine armee von sturmwind","wo sind die königlichen wachen","armee von sturmwind fehlt"}},{q="Kann Westfall überhaupt Truppen für das Rotkammgebirge entbehren?",a="Nein. Als Ihr die Späherkuppe erreicht, hält Westfall dem Ansturm der Bruderschaft der Defias kaum noch stand. Die Volksmiliz kann keine Truppen entbehren und hat Mühe, ihre eigenen Grenzen zu schützen.",al={"hilft westfall","kommt die miliz","kann gryan helfen"}},{q="Was folgt auf die Übergabe des Briefes?",a="Gryan Starkmantel nimmt die Nachricht entgegen und verfasst eine Antwort, in der er Westfalls verzweifelte Lage schildert. Er schickt Euch mit seiner Antwort zu Magistrat Solomon zurück.",al={"was als nächstes","folgequest","nach botschaft nach westfall"}}},fx={dcf2b619={q="Warum schickt Magistrat Solomon einen Abenteurer anstelle seiner eigenen Wachen?",a="Die örtliche Stadtwache von Seenhain ist bis an ihre absolute Belastungsgrenze erschöpft. Gnolle, Murlocs und Schwarzfelsorks drücken an jeder Grenze und drohen, die Stadt jeden Moment zu überrennen. Solomon kann keinen einzigen Wachmann entbehren, um den langen Marsch durch den Wald von Elwynn nach Westfall zu machen, was ihn zwingt, sich auf fähige Reisende wie Euch zu verlassen, um seine verzweifelten Hilferufe zu überbringen.",al={"warum ich","warum braucht solomon einen abenteurer","warum keine wache nach westfall schicken"}}},fp="21,192,18.370.0,23.332.0,51.212.0,25.222.0,37.125.0,49.231.0,52.187.1,39.154.1"}
P.entries["quest:1430"] = {n="Frischfleisch",s="Dar braucht Kriecherbeine von der Küste für hungrige Kunden in Orgrimmar.",h="Dar braucht Kriecherbeine von der Küste für hungrige Kunden in Orgrimmar.",kw={"kriecherbeine","dar","frischfleisch","monströser kriecher","orgrimmar","sümpfe des elends"},sec={{t="Kriecherbeine für Orgrimmar",b="Dars Kunden in Orgrimmar verlangen nach Kriecherfleisch, besonders von den monströsen Kriechern. Östlich von hier huschen die Kreaturen über die Strände und in die Brandung. Bringt einige ihrer Beine zurück, und Dar verspricht Euch ein Fass Wein. Er will das Fleisch kosten, bevor es nach Orgrimmar weitergeschickt wird."},{t="Eine Kostprobe für unterwegs",b="Dar ist mit den Beinen zufrieden und stellt sich vor, wie sie über offenem Feuer gegart werden. Er drängt Euch, eine gegarte Kostprobe auf Eure Reisen mitzunehmen. Dar schwört, dass sie köstlich ist."}},faq={{q="Wer will Kriecherfleisch in den Sümpfen des Elends?",a="Dars Kunden in Orgrimmar haben großen Bedarf an Kriecherfleisch.",al={"wer vergibt frischfleisch","dar quest","wer ist dar"}},{q="Wo sind die monströsen Kriecher zu finden?",a="Die monströsen Kriecher huschen an der Küste im Osten entlang, über die Strände und in die Brandung.",al={"kriecher fundort","wo sind die kriecher","monströser kriecher küste"}},{q="Warum braucht Dar gerade diese Beine?",a="Dars Kunden verlangen nach Kriecherfleisch, besonders von den monströsen Kriechern. Die Beine sind für Orgrimmar bestimmt.",al={"warum kriecherfleisch","wofür ist das fleisch","orgrimmar kriecherfleisch"}}},fp="10,72,26.282.0,20.154.1,47.65.0,41.94.0,38.109.0"}
P.entries["quest:1431"] = {n="Allianzbeziehungen",s="Thrall sucht eine besonnene Hand, um den Frieden mit der Allianz zu wahren. In Orgrimmar schickt Craven Drok erfahrene Abenteurer der Horde zu Keldran nahe dem westlichen Ausgang. Stille Diplomatie und Aufklärung könnten helfen, Thralls zerbrechlichen Frieden zu schützen.",h="Thrall sucht eine besonnene Hand, um den Frieden mit der Allianz zu wahren.",kw={"allianzbeziehungen","craven drok","diplomatie","horde","keldran","orgrimmar","thrall"},ang={["class:Rogue"]="Als Schurke eignen sich Eure Fähigkeiten in Heimlichkeit und Wahrnehmung für Keldrans Arbeit.",["faction:Horde"]="Für die Horde zeigt diese Arbeit die Kluft zwischen traditioneller roher Stärke und Thralls bedachter, diplomatischer Staatskunst.",["race:Orc"]="Als Orc kennt Ihr die Axt vielleicht als Mittel, Konflikte beizulegen. Keldrans Vorgehen verlangt Geduld und taktisches Feingefühl."},sec={{t="Ein diplomatisches Dilemma",b="Thrall fürchtet, dass ein Krieg mit der Allianz seine junge Nation zugrunde richten könnte. In menschlicher Gefangenschaft aufgewachsen, erlernte der Kriegshäuptling menschliche Staatskunst und Militärstrategie. Deshalb hält Craven Drok nach Kriegern und Streitern Ausschau, die über rohe Gewalt hinausblicken und einen subtileren Weg wählen können."},{t="Keldrans Hütte",b="Nahe Orgrimmars westlichem Ausgang bewohnt Keldran eine bescheidene Behausung. Er übt sich in Magie und verdeckten Künsten und befasst sich mit Schein, Wahrnehmung und Staatskunst. Während die Horde ihren erbitterten Rivalen in einem angespannten Kräftemessen gegenübersteht, sucht Keldran diskrete Agenten im Dienst des Kriegshäuptlings."}},faq={{q="Wer vergibt die Quest Allianzbeziehungen?",a="In Orgrimmar bietet Craven Drok diese Arbeit Abenteurern der Horde an, die ihre dreißigste Erfahrungssaison erreicht haben.",al={"questgeber allianzbeziehungen","wer startet allianzbeziehungen","wo gibt es allianzbeziehungen"}},{q="Wo kann ich Keldran finden?",a="Keldran lebt in einer kleinen Hütte nahe Orgrimmars westlichem Ausgang, abseits des Stadtzentrums.",al={"keldran aufenthaltsort","wo ist keldran","keldran orgrimmar"}},{q="Welche Rolle spielt Keldran in Orgrimmar?",a="Keldran studiert Magie und mystische Künste. Er unterstützt Kriegshäuptling Thrall bei vertraulichen Angelegenheiten der Diplomatie, der Aufklärung und des öffentlichen Ansehens der Horde.",al={"wer ist keldran","keldran hintergrundgeschichte"}},{q="Warum liegt Thrall die Diplomatie mit der Allianz am Herzen?",a="Da Thrall unter Menschen aufwuchs, versteht er ihre Politik und ihre militärische Macht. Er weiß, dass ein offener Krieg sein junges Volk vernichten könnte, und schützt die Zukunft der Horde mit Besonnenheit und bedachter Staatskunst.",al={"thrall diplomatie","warum frieden zwischen horde und allianz","thrall und menschen"}},{q="Führt diese Quest zu weiteren Missionen?",a="Ja. Wer Keldran diese Angelegenheit vorträgt, beginnt ein eingehenderes Gespräch über das Ansehen der Horde bei anderen Fraktionen. Daraus ergeben sich weitere Aufgaben in der regionalen Diplomatie und Spionage.",al={"allianzbeziehungen folgequest","was kommt nach allianzbeziehungen"}},{q="Warum ist Diskretion bei dieser Aufgabe so wichtig?",a="Ein offener Konflikt mit der Allianz birgt die Gefahr schwerer Verluste und könnte Kalimdor destabilisieren. Thrall setzt auf diskrete Agenten, um heikle diplomatische Spannungen zu entschärfen, bevor sie in Krieg münden.",al={"warum subtilität","keldran subtilität"}}},fx={f7a9da96={q="Warum schickt Euch Craven Drok zu Keldran?",a="Craven Drok erkennt, dass das Verständnis der heiklen politischen Lage der Horde mehr als nur rohe Gewalt erfordert. Während die Orks stolz und kriegerisch sind, verfolgt Thrall einen diplomatischen Pfad, den er während seiner Zeit unter den Menschen gelernt hat. Drok beginnt die Geschichte, um Euer Interesse zu testen, verweist Euch aber an Keldran – einen Praktiker subtiler Künste –, der die diskreten Angelegenheiten überwacht, die notwendig sind, um zu steuern, wie Verbündete und Feinde die Horde wahrnehmen.",al={"motive von craven drok","warum mit keldran sprechen","warum will craven drok dies erledigt haben"}}},fp="18,230,20.263.0,15.272.0,39.118.0,25.90.0,36.149.0,55.205.0,41.172.0,45.189.0"}
P.entries["quest:1432"] = {n="Allianzbeziehungen",s="In Orgrimmar setzt der Vormarsch der Allianz durch Kalimdor die Horde unter Druck. Thralls Leute schicken Befehle nach Desolace, um Dämonen zu vernichten, bevor die Allianz ihnen erneute Verbindungen zur Brennenden Legion vorwerfen kann.",h="In Orgrimmar setzt der Vormarsch der Allianz durch Kalimdor die Horde unter Druck.",kw={"allianzbeziehungen","brennende legion","das verbrannte tal","desolace","geistwandlerposten","keldran","der kodofriedhof","takata stahlklinge"},ang={["class:Warlock"]="Soldaten wie Takata Stahlklinge betrachten dunkle Mächte mit Argwohn, doch Einsätze gegen wilde Dämonen überschneiden sich oft mit dem pragmatischen Einsatz von Hexenmeistern durch die Horde.",["faction:Horde"]="Die Mission spiegelt Kriegshäuptling Thralls Bemühen wider, die neue Horde zu legitimieren und das Erbe dämonischer Knechtschaft zu begraben, bevor feindselige Nachbarn es ausnutzen können.",["race:Orc"]="Für Orcs, die Thralls Vision der Erlösung ehren wollen, bedroht jeder verbliebene Hauch dämonischer Verderbnis in Kalimdor ihre hart erkämpfte Freiheit."},sec={{t="Eine Frage der Wahrnehmung",b="Kundschafter und Expeditionen der Allianz durchqueren Kalimdor und bringen die Horde damit in eine heikle Lage. Dämonische Überreste im zentralen Kalimdor könnten alte Verdächtigungen bestätigen, dass die Orcs und ihre Verbündeten noch immer der Brennenden Legion dienen. Mit der Billigung von Kriegshäuptling Thrall leitet Keldran den Einsatz von Orgrimmar aus. Sie müssen diese Überreste beseitigen, bevor feindselige Fraktionen der Allianz sie zur Rechtfertigung eines Krieges nutzen."},{t="Außenposten im Ödland",b="Die Befehle führen nach Süden durch das Verbrannte Tal im Steinkrallengebirge und weiter nach Desolace. Der Geistwandlerposten liegt unmittelbar nördlich des gewaltigen Kodofriedhofs. Agenten der Horde wie Takata Stahlklinge wachen über dieses Ödland. Ungezügelte Zentaurenstämme und die sich ausbreitende dämonische Verderbnis bedrohen gleichermaßen die Region."},{t="Pragmatische Bündnisse",b="Takata Stahlklinge betrachtet den Auftrag mit grimmigem Pragmatismus. Die Vernichtung der örtlichen Dämonen entlastet auch die gewalttätigen Zentaurenstämme und hilft den ansässigen Hexenmeistern der Horde. Doch die Pflicht geht vor. Die Beseitigung der Stützpunkte der Brennenden Legion schützt die Horde, ganz gleich, wer sonst von der Säuberung profitiert."}},faq={{q="Warum ist die Horde hier wegen der Allianz besorgt?",a="Die durch Kalimdor vorrückenden Streitkräfte der Allianz könnten die anhaltende Dämonenplage als Beweis dafür nutzen, dass die Horde noch immer mit der Brennenden Legion verkehrt. Durch die Vernichtung der örtlichen Dämonen hofft die Horde, diese Anschuldigungen zu entkräften.",al={"warum sorge wegen der allianz","horde allianz beziehungen desolace","anschuldigungen der allianz"}},{q="Wer ist Keldran?",a="Keldran ist ein Agent der Horde in Orgrimmar, der mit Zustimmung des Kriegshäuptlings Einsätze gegen Dämonen leitet, die das Ansehen der Horde bedrohen.",al={"keldran","wer ist keldran","keldran orgrimmar"}},{q="Wo liegt der Geistwandlerposten?",a="Der Geistwandlerposten liegt im zentralen Desolace, unmittelbar südlich des Passes vom Verbrannten Tal im Steinkrallengebirge und unmittelbar nördlich des Kodofriedhofs.",al={"geistwandlerposten lage","wo ist takata stahlklinge","geistwandlerposten finden"}},{q="Wer ist Takata Stahlklinge?",a="Takata Stahlklinge ist ein Soldat der Horde am Geistwandlerposten in Desolace. Der Kriegshäuptling hat ihn beauftragt, regionale Bedrohungen wie Dämonen und feindselige Zentauren in Schach zu halten.",al={"takata stahlklinge","wer ist stahlklinge","stahlklinge desolace"}},{q="Warum erwähnt Takata die Hilfe für die Zentauren?",a="Die Zentauren beanspruchen Desolace als ihr Gebiet, können die wachsende Bedrohung durch Dämonen jedoch nicht eindämmen. Die Dezimierung der Dämonen hilft auch den Zentauren beim Überleben, ein Kompromiss, den Takata für die Sicherheit der Horde akzeptiert.",al={"zentauren helfen","zentauren desolace","warum zentauren helfen"}},{q="Welche Rolle spielen Hexenmeister bei dieser Mission?",a="Takata bemerkt mit Abscheu, dass die Beseitigung wilder Dämonen und ihres Einflusses auch den umstrittenen Hexenmeistern hilft, die innerhalb der Horde wirken.",al={"verbindung zu hexenmeistern","warum hexenmeistern helfen","hexenmeister in der horde"}}},fp="18,208,22.384.0,21.310.0,19.298.1,51.210.0,15.146.0,35.154.0,25.177.0,43.196.0,38.139.0"}
P.entries["quest:1434"] = {n="Befouled by Satyr",s="Takata Stahlklinge in Desolace bittet Euch, Euch mehreren Arten von Hatefury-Satyrn zu stellen. Ihre Anwesenheit ist das Problem, um das Ihr Euch für ihn kümmern sollt.",h="Takata Stahlklinge in Desolace bittet Euch, Euch mehreren Arten von Hatefury-Satyrn zu stellen.",kw={"befouled by satyr","betrayer","desolace","felsworn","hatefury","hellcaller","schurke","satyr","takata stahlklinge"},sec={{t="Takatas Bitte",b="Takata Stahlklinge bittet Euch in Desolace um Hilfe. Hatefury Rogues, Felsworn, Betrayers und Hellcallers sind die Satyrn, die er nennt. Ihr sollt sieben von jeder Art töten und dann zu ihm zurückkehren."}},faq={{q="Wer bittet um Hilfe gegen die Hatefury-Satyrn?",a="Takata Stahlklinge bittet Euch, Euch den Hatefury-Satyrn in Desolace zu stellen.",al={"wer ist takata","takata stahlklinge"}},{q="Welche Hatefury-Satyrn nennt Takata?",a="Takata nennt Hatefury Rogues, Felsworn, Betrayers und Hellcallers.",al={"hatefury-arten","satyrnliste"}},{q="Wie viele von jeder Art sollt Ihr für Takata töten?",a="Takata bittet Euch, sieben von jeder Art zu töten, die er nennt.",al={"wie viele satyrn","anzahl je art"}},{q="Wohin kehrt Ihr zurück, nachdem Ihr Euch um die Satyrn gekümmert habt?",a="Takata bittet Euch, zu ihm nach Desolace zurückzukehren.",al={"wohin zurückkehren","zu takata zurückkehren"}}},fp="17,138,16.183.0,42.70.0,38.67.0,50.52.0,49.45.0"}
P.entries["quest:1435"] = {n="The Burning of Spirits",s="Maurin Knochenspalter in Desolace bittet Euch, den Burning Gem und fünfzehn Infused Burning Gems zurückzubringen.",h="Maurin Knochenspalter in Desolace bittet Euch, den Burning Gem und fünfzehn Infused Burning Gems...",kw={"burning gem","desolace","edelsteine","infused burning gems","maurin knochenspalter"},faq={{q="Wer möchte die Edelsteine?",a="Maurin Knochenspalter bittet Euch, den Burning Gem und fünfzehn Infused Burning Gems zurückzubringen.",al={"wer bat um edelsteine","maurin edelsteine"}},{q="Wohin soll ich die Edelsteine bringen?",a="Bringt den Burning Gem und fünfzehn Infused Burning Gems zu Maurin Knochenspalter nach Desolace zurück.",al={"wohin edelsteine bringen","ort der edelsteine"}},{q="Welche Edelsteine verlangt Maurin?",a="Maurin verlangt den Burning Gem und fünfzehn Infused Burning Gems.",al={"welche edelsteine","quest um den burning gem"}}},fp="22,100,19.88.0,27.91.0,31.65.0"}
P.entries["quest:1437"] = {n="Vahlarriels Suche",s="In Desolace sucht Vahlarriel Demonslayer nach zwei vermissten Adligen des Hauses Malem. Ihr Vater befürchtet das Schlimmste, und dem letzten Bericht zufolge durchquerten die Geschwister vor einigen Wochen das Steinkrallengebirge. Vahlarriel bittet Euch, ihren Wagen zu finden.",h="In Desolace sucht Vahlarriel Demonslayer nach zwei vermissten Adligen des Hauses Malem.",kw={"kiste","dalinda","darnassus","desolace","malem","steinkrallengebirge","tyranis","vahlarriel"},sec={{t="Zwei vermisste Adlige",b="Vahlarriel Demonslayer sucht nach Tyranis und Dalinda Malem. Ihr Vater hat Vahlarriel beauftragt, alles Mögliche zu tun, um sie zu finden. Die Suche hat gerade erst begonnen, und Vahlarriel hofft, dass sie sie nicht lange in Desolace halten wird. Dem letzten Bericht zufolge durchquerten die Geschwister vor einigen Wochen das Steinkrallengebirge. Ihr sollt ihren Wagen in Desolace finden und unverzüglich zurückkehren. Seine verkohlten Überreste liegen dort, mit einer Kiste dazwischen."},{t="Zwischen den Trümmern",b="Das Wrack trägt Spuren von Zaubern und Waffen. Der Kampf scheint kurz und einseitig gewesen zu sein, doch weder Blut noch Leichen sind zurückgeblieben. Wer auch immer zugeschlagen hat, ging schnell und effizient vor."}},faq={{q="Nach wem sucht Vahlarriel?",a="Vahlarriel sucht nach Tyranis und Dalinda Malem, zwei Adligen des Hauses Malem, einer darnassischen Händlerfamilie.",al={"wer wird vermisst","wer sind die adligen","haus malem vermisste kinder"}},{q="Wo gab es die letzte Nachricht von den Geschwistern?",a="Dem letzten Bericht zufolge durchquerten sie vor einigen Wochen das Steinkrallengebirge.",al={"malem geschwister zuletzt gesehen","wohin gingen sie","route des wagens"}},{q="Warum sucht Vahlarriel?",a="Ihr Vater befürchtet das Schlimmste. Er hat Vahlarriel beauftragt, alles Mögliche zu tun, um seine vermissten Kinder zu finden.",al={"wer hat vahlarriel beauftragt","wer will die geschwister finden lassen"}},{q="Was sollt Ihr für Vahlarriel finden?",a="Vahlarriel bittet Euch, den Wagen von Tyranis und Dalinda Malem in Desolace zu suchen und unverzüglich zurückzukehren, wenn Ihr ihn findet.",al={"wie beginnt vahlarriels suche","was ist der erste schritt"}}},fp="19,240,18.428.0,18.157.1,30.100.0,40.70.0,28.116.0,38.108.0"}
P.entries["quest:1438"] = {n="Vahlarriels Suche",s="An der Festung schickt Euch Vahlarriel Demonslayer los, um Dalinda und Tyranis Malem zu finden. Die Suche beginnt dort, während Vahlarriel Vorgesetzte in Darnassus benachrichtigt. Diese stellen Dalindas sichere Rückkehr an erste Stelle und hinterfragen Tyranis’ Beweggründe.",h="An der Festung schickt Euch Vahlarriel Demonslayer los, um Dalinda und Tyranis Malem zu finden.",kw={"burning blade","dalinda","darnassus","demonslayer","desolace","malem","festung donneraxt","tyranis","vahlarriel"},sec={{t="Suche an der Festung",b="Vahlarriel Demonslayer bittet Euch, an der Festung nach Dalinda und Tyranis zu suchen und mit Euren Erkenntnissen zurückzukehren. Vahlarriel wird sofort Vorgesetzte in Darnassus kontaktieren. Im Vertrauen äußern diese ihre Bedenken darüber, warum Tyranis nach Desolace gekommen ist. Vor allem wollen sie Dalinda sicher nach Hause bringen lassen. Tyranis’ Rückkehr kann warten, bis sie mehr über ihn wissen."},{t="Bericht einer Gefangenen",b="Dalinda wird im großen Gebäude gegenüber dem Eingang gefangen gehalten. Sie sagt, die Burning Blade habe sie und Tyranis ergriffen und hierhergebracht. Sie glaubt, dass der Kult sie seinen Dämonenmeistern opfern will. Dalinda sagt, die Reise sei von Anfang an ein Fehler gewesen.\n\nTyranis hatte gegen den Willen seines Volkes einen Hunger nach arkanem Wissen entwickelt und war trotz Warnungen vor Dämonen in Desolace aufgebrochen. Dalinda fürchtet, was aus ihm geworden ist."}},faq={{q="Wo ist Dalinda Malem?",a="Dalinda befindet sich im Gebiet der Festung Donneraxt in Desolace, im großen Gebäude gegenüber dem Eingang.",al={"dalinda malem fundort","wo dalinda finden","dalinda in desolace finden"}},{q="Wer schickt Euch auf die Suche nach Dalinda und Tyranis?",a="Vahlarriel Demonslayer bittet Euch, Dalinda und Tyranis an der Festung zu finden, während Vahlarriel Vorgesetzte in Darnassus informiert.",al={"wer vergibt vahlarriels suche","questgeber vahlarriel","vahlarriel demonslayer quest"}},{q="Warum liegt Darnassus mehr an Dalinda als an Tyranis?",a="Vahlarriels Vorgesetzte zweifeln an Tyranis’ Gründen für seine Reise nach Desolace, und Dalindas sichere Rückkehr ist ihnen am wichtigsten.",al={"warum wird tyranis verdächtigt","tyranis’ beweggründe","warum hat dalinda vorrang"}},{q="Was ging diesem Teil der Suche voraus?",a="Er folgt auf den zweiten Teil von Vahlarriels Suche.",al={"vorherige quest","voraussetzung vahlarriel","vahlarriels suche questreihe"}}},fp="19,228,24.343.0,19.417.1,23.99.0,46.124.0,56.124.0,41.52.0"}
P.entries["quest:1439"] = {n="Suche nach Tyranis",s="In der Festung Donneraxt wartet Dalinda Malem darauf, zu erfahren, was aus Tyranis geworden ist. Orks töteten ihre Wachen und Bediensteten, bevor sie die Geschwister dorthin brachten. Tyranis versuchte, mit seinen Entführern zu sprechen, und Dalinda bittet Euch, ihn zu finden und zurückzukehren, sobald Ihr sein Schicksal kennt.",h="In der Festung Donneraxt wartet Dalinda Malem darauf, zu erfahren, was aus Tyranis geworden ist.",kw={"burning blade","dalinda","desolace","malem","anhänger","festung donneraxt","tyranis","vahlarriel"},sec={{t="Ein verschleppter Bruder",b="Orks töteten jede Wache und jeden Bediensteten, bevor sie Dalinda und Tyranis in die Festung Donneraxt schleppten. Sie rechnete damit, dass sie beide sofort sterben würden, doch ihre Entführer hatten andere Pläne. Tyranis versuchte, mit den Orks zu sprechen, vielleicht in der Hoffnung, sein arkanes Wissen würde sie beeindrucken. Dalinda kann nicht sagen, warum. Sie wird nicht fliehen, bevor sie sein Schicksal kennt, und bittet Euch daher, ihn zu finden und zurückzukehren. Er befindet sich im Gebäude links vom Eingang der Festung."},{t="Dalindas Furcht",b="Dalinda fürchtet, Tyranis werde nach den Geheimnissen der Burning Blade suchen und sich ihnen anschließen, wenn er kann. Macht hat ihn schon immer angezogen, so wie Magie jene anzieht, die sie verführt. Für Dalindas Volk ist selbst das Studium solcher Dinge ein schweres Verbrechen. Sie bezweifelt, dass sie ihrer Familie gegenübertreten könnte, wenn sie wüsste, dass ihr Bruder mit dieser Gefahr gespielt hat."},{t="Was Dalinda erfährt",b="Als Ihr zurückkehrt, bezeichnet Dalinda das Geschehene als schrecklich, aber notwendig. Hätte Eure Hand es nicht getan, hätte es jemand aus ihrem eigenen Volk getan. Sie bittet Euch um Verzeihung, falls ihr Dank hohl klingt. Da sie Tyranis' Schicksal nun kennt, ist sie zur Flucht bereit und wird Eure Hilfe annehmen, wenn Ihr noch immer dazu gewillt seid."}},faq={{q="Wer ist Tyranis Malem?",a="Tyranis Malem ist Dalindas Bruder. Er sprach mit ihren Entführern, vielleicht in der Hoffnung, sein arkanes Wissen würde sie beeindrucken. Dalinda sagt, die Macht der Magie habe ihn schon immer angezogen.",al={"wer ist tyranis","tyranis vorgeschichte","tyranis malem"}},{q="Warum weigert sich Dalinda noch zu gehen?",a="Dalinda weigert sich zu gehen, bevor sie weiß, was mit ihrem Bruder geschehen ist. Sie bittet Euch, ihn zu finden und zurückzukehren, sobald sein Schicksal bekannt ist.",al={"warum will dalinda nicht gehen","warum bleibt dalinda","warum mit der flucht warten"}},{q="Was geschah mit den Wachen und Bediensteten?",a="Die Orks töteten alle Wachen und Bediensteten und nahmen dann Dalinda und Tyranis lebend mit, da sie andere Pläne mit ihnen hatten.",al={"was geschah mit ihren wachen","wer wurde getötet","wachen und bedienstete"}},{q="Wo ist Tyranis?",a="Tyranis befindet sich in der Festung Donneraxt in Desolace, im Gebäude auf der linken Seite, wenn Ihr die Festung betretet.",al={"wo ist tyranis","tyranis aufenthaltsort"}},{q="Was ging diesem Schritt voraus?",a="Dies folgt auf den dritten Teil von Vahlarriel's Search, in dem Vahlarriel Euch losschickte, um Dalinda zu finden.",al={"welche quest kommt davor","questabfolge","vahlarriel questreihe"}}},fp="18,260,15.423.0,14.295.0,19.304.1,21.166.0,37.130.0,41.100.0,17.89.0,27.94.0"}
P.entries["quest:144"] = {n="Botschaft nach Westfall",s="In Seenhain erhält Magistrat Solomon eine harte Antwort aus Westfall. Er bat Gryan Starkmantel um Soldaten zur Verteidigung des Rotkammgebirges, doch Westfall hat eigene Sorgen.",h="In Seenhain erhält Magistrat Solomon eine harte Antwort aus Westfall.",kw={"gryan starkmantel","seenhain","magistrat solomon","botschaft nach westfall","volksmiliz","rotkammgebirge","späherkuppe","westfall"},ang={["faction:Alliance"]="Dieser Briefwechsel zeigt die Kluft zwischen den Herrschern in Burg Sturmwind und den entlegenen Provinzen. Westfall und das Rotkammgebirge müssen sich allein durchschlagen.",["race:Human"]="Als menschlicher Reisender seht Ihr, wie isoliert die Provinzstädte sind. Einfache Bürger und Veteranen vergießen ihr Blut, um Ländereien zu verteidigen, deren Schutz die Adligen von Sturmwind verweigern."},sec={{t="Ein Hilferuf über wankende Grenzen",b="Magistrat Solomon steht im Rotkammgebirge ohne Sturmwinds königliche Garnison vor wachsenden Schwierigkeiten. Deshalb schreibt er an Gryan Starkmantel, den Kommandanten der Volksmiliz in Westfall, und bittet das südliche Grenzgebiet um Hilfe. Solomon hofft, dass die Freiwilligen auf der Späherkuppe Kämpfer entbehren können, um Seenhains Verteidigung zu stärken. Er weiß nicht, wie sehr die westlichen Ebenen unter Druck stehen."},{t="Eine bittere Absage",b="Gryan Starkmantel lehnt ab, auch wenn ihm die Antwort schwer auf dem Herzen liegt. Westfall kämpft gegen die Bruderschaft der Defias und marodierende Gnolle, weil das Haus der Adligen und die Krone die Kornkammer des Königreichs verlassen haben. Die Volksmiliz wurde gegründet, um den Menschen beim Überleben zu helfen. Ihre Reihen verlieren jeden Tag gute Männer, und Starkmantel kann keinen einzigen Kämpfer für das Rotkammgebirge entbehren."},{t="Das zerfallende Königreich",b="Als Ihr Starkmantels Antwort nach Seenhain zurückbringt, erkennt Solomon, dass die Grenzgebiete unter derselben Vernachlässigung leiden. Örtliche Magistrate und Bürgermilizen müssen sich selbst verteidigen, während die Armee von Sturmwind weiterhin zurückgehalten wird. Solomon wendet sich nach Süden, nach Dunkelhain im Dämmerwald, und hofft, dort Hilfe zu finden."}},faq={{q="Warum bat Magistrat Solomon Westfall um Hilfe?",a="Magistrat Solomon suchte Hilfe, weil Seenhain ohne Sturmwinds Armee wachsenden Bedrohungen ausgesetzt ist. Er wusste, dass Gryan Starkmantel die Volksmiliz zur Verteidigung Westfalls organisiert hatte, und hoffte, sie könne Soldaten für das Rotkammgebirge entbehren.",al={"warum westfall um hilfe bitten","solomons brief an starkmantel","warum westfalls miliz"}},{q="Warum weigert sich Gryan Starkmantel, Hilfe zu schicken?",a="Westfall kämpft bereits gegen die Bruderschaft der Defias und marodierende Gnolle. Starkmantel sagt, die Miliz bestehe, weil Sturmwind Westfall im Stich gelassen habe, und könne keine Kämpfer entbehren.",al={"warum starkmantel nein sagt","miliz verweigert seenhain hilfe","starkmantels antwort"}},{q="Wo ist die Armee von Sturmwind während dieser Krisen?",a="Die Briefe sagen nicht, warum die Armee von Sturmwind fernbleibt. Solomon und Starkmantel können sich nur fragen, was sie davon abhält, die äußeren Provinzen zu verteidigen.",al={"warum sturmwind nicht hilft","wo ist die armee","sturmwinds imstichlassen"}},{q="Was geschieht, nachdem Starkmantels Brief zu Solomon zurückgebracht wurde?",a="Nachdem Magistrat Solomon erfährt, dass Westfall nicht helfen kann, wendet er sich an den Dämmerwald. Er schickt Euch nach Dunkelhain und hofft, dass die Nachtwache von Bürgermeister Ello Ebonlocke Hilfe leisten kann.",al={"nächste quest nach botschaft nach westfall","was macht solomon als nächstes"}},{q="Was ist die Volksmiliz?",a="Die Volksmiliz ist eine von Gryan Starkmantel organisierte Freiwilligentruppe mit Sitz auf der Späherkuppe. Örtliche Bauern, Veteranen und Einwohner verteidigen Westfall ohne Truppen der Krone gegen Gesetzlose und Gnolle.",al={"wer ist die volksmiliz","westfalls miliz"}},{q="Wer ist Gryan Starkmantel?",a="Gryan Starkmantel ist ein erfahrener Soldat, der Westfalls Verteidigung anführt. Vom Turm auf der Späherkuppe aus sammelt er Freiwillige und leitet den Kampf gegen die Bruderschaft der Defias.",al={"gryan starkmantels geschichte","wer ist starkmantel"}}},fx={["84b4f9a5"]={q="Warum schickt Gryan Starkmantel Euch anstelle seiner eigenen Miliz?",a="Die The People's Militia ist bis an ihre Belastungsgrenze erschöpft, während sie die Farmen in Westfall vor The Defias Brotherhood und marodierenden Gnollen verteidigt. Starkmantel kann keinen einzigen Kämpfer entbehren, um die lange Reise nach Osten durch den Wald von Elwynn nach Rotkammgebirge zu unternehmen. Da Ihr ohnehin bereits Magistrat Solomons Anfrage überbracht habt, fungiert Ihr bereits als Kurier für Rotkammgebirge und seid am besten geeignet, die düstere Antwort zurückzubringen.",al={"warum ich","warum keinen milizläufer schicken","warum braucht gryan einen boten"}}},fp="21,170,32.385.0,16.361.0,30.296.1,49.224.0,46.180.0,48.144.0,61.158.1,29.201.0,25.177.0"}
P.entries["quest:1440"] = {n="Rückkehr nach Vahlarriel",s="In der Festung Donneraxt ist Dalinda Malem bereit aufzubrechen, sobald Ihr es entscheidet. Sie dankt Euch, dass Ihr ihr und ihrer Familie geholfen habt. Geleitet sie hinaus und sucht dann Vahlarriel Demonslayer auf.",h="In der Festung Donneraxt ist Dalinda Malem bereit aufzubrechen, sobald Ihr es entscheidet.",kw={"dalinda malem","darnassus","desolace","eskorte","die nijelspitze","festung donneraxt","tyranis","vahlarriel"},sec={{t="Abschied von der Festung",b="Dalinda Malem ist bereit, die Festung Donneraxt zu verlassen, sobald Ihr den Augenblick für richtig haltet. Sie dankt Euch für alles, was Ihr für sie und ihre Familie getan habt, falls die Dinge nicht wie erhofft verlaufen. Nichts anderes hält sie dort. Sie wird aufbrechen, sobald Ihr den Zeitpunkt bestimmt. Geleitet sie aus der Festung und sucht dann Vahlarriel Demonslayer in Desolace auf."},{t="Nachricht von Vahlarriel",b="Vahlarriel Demonslayer dankt Euch. Dalinda hat die Nijelspitze in weit besserer Verfassung erreicht, als Vahlarriel hätte hoffen können. Dass sie aus eigener Kraft ankam, war ein gutes Zeichen. Keines der beiden Geschwister ist zurückgekehrt, was Vahlarriel schmerzt. Tyranis' Entscheidungen hinterlassen ihr eine Schande, die sie bei ihrer Rückkehr nach Darnassus ertragen muss."}},faq={{q="Wer bittet Euch, sie hinauszugeleiten?",a="Dalinda Malem, die bereit ist, die Festung Donneraxt zu verlassen, sobald Ihr den Augenblick für richtig haltet.",al={"wer vergibt rückkehr nach vahlarriel","questgeber rückkehr nach vahlarriel","wer ist dalinda malem"}},{q="Wo beginnt dies?",a="Ihr beginnt in der Festung Donneraxt in Desolace, wo Dalinda Malem wartet.",al={"dalinda malem standort","wo ist dalinda malem","wo beginnt rückkehr nach vahlarriel"}},{q="Wen sucht Ihr auf, nachdem Dalinda draußen ist?",a="Nachdem Dalinda draußen ist, sucht Ihr Vahlarriel Demonslayer in Desolace auf.",al={"wo rückkehr nach vahlarriel abgeben","wer schließt rückkehr nach vahlarriel ab","rückkehr nach vahlarriel ende"}},{q="Was kam vor diesem Schritt?",a="Dies folgt auf Search for Tyranis, einen Teil der längeren Questreihe Vahlarriel's Search.",al={"voraussetzung rückkehr nach vahlarriel","rückkehr nach vahlarriel vorgängerquest","welche quest kommt vor rückkehr nach vahlarriel"}}},fp="20,170,20.330.0,20.317.1,27.90.0,22.78.0,38.67.0,27.72.0"}
P.entries["quest:1442"] = {n="Suche nach dem Koredelstein",s="Ihr überquert das Meer nach Dunkelküste, um einen Kor-Edelstein für Jordan Stillbrunn zu suchen. Thundris Windwirker schickt einen Paladinanwärter der Allianz in die Tiefschwarze Grotte, wo Naga den mächtigen Stein verderbt haben. Jordan braucht ihn für sein Handwerk.",h="Ihr überquert das Meer nach Dunkelküste, um einen Kor-Edelstein für Jordan Stillbrunn zu suchen.",kw={"auberdine","tiefschwarze grotte","dunkelküste","jordan stillbrunn","kor-edelstein","naga","paladin","test of righteousness","thundris windweaver"},ang={["class:Paladin"]="Als Paladin der Allianz steht Ihr vor einer Prüfung Eures Charakters und Eurer Ausdauer. Sie prüft Eure Bereitschaft, in Kalimdors feindselige Tiefen zu reisen und beim Schmieden einer geweihten Waffe des Lichts zu helfen.",["faction:Alliance"]="Als Mitglied der Allianz seht Ihr, wie ein menschlicher Schmied auf die Weisheit der Nachtelfen und zwergischen Stahl vertraut, um Waffen gegen die aufziehende Finsternis herzustellen.",["race:NightElf"]="Als Nachtelf seht Ihr, wie Thundris Windwirker eine zerbrechliche, doch wachsende Brücke zwischen den uralten Kaldorei und den frisch verbündeten Anhängern des Heiligen Lichts aus den Östlichen Königreichen schlägt."},sec={{t="Ein Bündnis des Vertrauens",b="Angehende Paladine reisen über das Meer nach Dunkelküste, um Materialien zu beschaffen, die Jordan Stillbrunn benötigt. In Auberdine erinnert sich der Nachtelf Thundris Windwirker mit Respekt an den menschlichen Schmied. Nachtelfen halten Abstand, und einige gefallene Menschen haben ihr Vertrauen verraten. Doch Thundris glaubt, dass Paladine weiterhin einem rechtschaffenen Pfad folgen können. Er sagt ihnen, wo uralte Edelsteine zu finden sind."},{t="In die Tiefen",b="Die Tiefschwarze Grotte liegt unter der nebligen Nordwestküste von Eschental. Kultisten des Schattenhammers und heimtückische Meeresbewohner hausen in ihren überfluteten Hallen. Nagapriesterinnen leiten verderbte Magie durch uralte Kor-Edelsteine. Der Edelstein, den Ihr sucht, liegt tief im Tempelkomplex, inmitten seiner dunklen Hallen und gefährlichen Bewohner."},{t="Die Reinigung des Steins",b="Wenn Ihr einen Verderbten Koredelstein zu Thundris Windwirker zurückbringt, muss er ihn reinigen, bevor Jordan Stillbrunn ihn in eine heilige Waffe schmieden kann. Die Naga verleihen dem Edelstein rohe magische Kraft, verkehren seine Verzauberung jedoch zum Bösen. Thundris entfernt diese Verderbnis, damit die Kraft des Edelsteins für das bevorstehende heilige Schmiederitual rein und beständig bleibt."}},faq={{q="Wer schickt Euch auf die Suche nach dem Kor-Edelstein?",a="Thundris Windwirker schickt Paladine auf die Suche nach dem Kor-Edelstein. Er ist ein Nachtelf im Küstenhafen Auberdine in Dunkelküste und handelt im Auftrag des Waffenschmieds Jordan Stillbrunn.",al={"questgeber suche nach dem koredelstein","wer vergibt suche nach dem koredelstein","thundris windweaver quest"}},{q="Wo befindet sich der Kor-Edelstein?",a="Der Kor-Edelstein liegt in der Tiefschwarzen Grotte, einem uralten unterirdischen Tempel an der Nordwestküste von Eschental. Nagapriesterinnen in den Ruinen tragen die Edelsteine bei sich.",al={"kor-edelstein fundort","wo kor-edelstein bekommen","wo ist verderbter koredelstein"}},{q="Warum braucht Jordan Stillbrunn einen Kor-Edelstein?",a="Jordan Stillbrunn benötigt die mächtige Magie des Kor-Edelsteins als Material, um während der Paladinprüfung The Test of Righteousness seine kunstvolle Waffe herzustellen.",al={"warum kor-edelstein","wofür ist kor-edelstein","stillbrunn edelstein"}},{q="Warum muss Thundris den Edelstein reinigen?",a="Naga erfüllen Kor-Edelsteine mit großer arkaner Macht, doch ihre finsteren Verzauberungen verderben sie. Thundris reinigt den Edelstein, damit seine Kraft gefahrlos in einer Waffe des Lichts wirken kann.",al={"warum kor-edelstein reinigen","verderbter koredelstein gereinigt","reinigung des edelsteins"}},{q="Warum erwähnt Thundris ein „gefallenes Volk“?",a="Thundris meint wahrscheinlich Verrat durch Menschen wie den Fall von Prinz Arthas Menethil in die Finsternis, der den Ruf der Silver Hand in ganz Azeroth befleckte. Dennoch beurteilt er jeden Paladin nach dessen eigenen Verdiensten.",al={"wer ist der gefallene","thundris gefallenes volk","anspielung gefallener paladin"}},{q="Brauche ich eine Gruppe, um den Kor-Edelstein zu beschaffen?",a="Thundris warnt Euch davor, allein aufzubrechen. Elite-Naga tief in der Tiefschwarzen Grotte tragen den Edelstein bei sich, daher wird eine eigens zusammengestellte Abenteurergruppe dringend empfohlen.",al={"kor-edelstein allein machbar","kor-edelstein allein beschaffen","tiefschwarze grotte gruppe"}}},fx={["5bec2e5c"]={q="Warum möchte Thundris Windwirker, dass dies erledigt wird?",a="Thundris Windwirker erinnert sich an Jordan Stillbrunn aus der Vergangenheit als einen Mann von bescheidenem, ehrenhaftem Charakter. Obwohl Koredelsteine gefährlich sind und von Natur aus von dunkler Magie durchdrungen sind, vertraut Thundris darauf, dass Stillbrunns Absicht edel ist. Da er Euch als einen Helden erkennt, der einen heiligen Pfad beschreitet, erklärt er sich bereit, bei der Suche und Reinigung des Artefakts zu helfen, damit Stillbrunn seine Arbeit sicher abschließen kann, und stellt sicher, dass seine faulen Energien beseitigt werden, bevor es jemals verwendet wird.",al={"motive von thundris","warum hilft thundris","warum stillbrunn helfen"}},c21b70e4={q="Wozu dient der Verderbter Koredelstein?",a="Der Verderbter Koredelstein ist ein arkaner Fokus, der durch die Naga, die in den versunkenen Ruinen der Tiefschwarze Grotte leben, mit dunkler Macht durchdrungen wurde. Jordan Stillbrunn benötigt einen Koredelstein als wesentliche Komponente für das Schmieden seiner meisterhaften Waffe. Bevor er jedoch als rechtschaffene Waffe dienen kann, muss die abscheuliche Naga-Verderbnis des Edelsteins gereinigt werden, während seine rohe innere Kraft für Stillbrunns Schmiederitual erhalten bleibt.",al={"wozu koredelstein","verwendung verdorbener koredelstein","zweck von koredelstein"}},["35f248ef"]={q="Wer hält den Koredelstein in der Tiefschwarze Grotte?",a="Der Edelstein wird von den Naga gehalten, die den versunkenen Elfenschrein der Tiefschwarze Grotte entlang der Küste von Eschental befallen haben. Diese schlangenartigen Kreaturen schätzen die Koredelsteine und durchdringen sie mit fauler, schattenhafter Macht, um ihre eigenen finsteren Riten in den gefluteten Tiefen zu befeuern.",al={"wer hat den koredelstein","ziel koredelstein","wer lässt koredelstein fallen"}}},fp="19,223,18.381.0,14.318.0,19.332.1,34.169.0,29.156.0,40.144.0,41.167.0,42.203.0,37.145.0"}
P.entries["quest:1444"] = {n="Rückkehr zu Fel'Zerul",s="Im Hinterland schickt der Verbannte der Atal'ai eine Nachricht an Fel'zerul in Steinard. Die Artefakte, die Ihr gebracht habt, sind harmlos, doch der Verbannte fürchtet, was Jammal'an the Prophet tun könnte.",h="Im Hinterland schickt der Verbannte der Atal'ai eine Nachricht an Fel'zerul in Steinard.",kw={"verbannter der atal'ai","fel'zerul","hinterland","jammal'an","steinard","beschwörungsritual","der tempel von atal'hakkar"},sec={{t="Worte eines Verbannten",b="Der Verbannte der Atal'ai hielt Jammal'an the Prophet einst des Hohepriesteramtes für würdig. Nun fürchtet der Verbannte, dessen unerschütterlicher Glaube an die Prophezeiung könnte die Atal'ai ins Verderben stürzen, falls dies nicht bereits geschehen ist. Weil er seine Bedenken äußerte, wurde der Verbannte als Ungläubiger bezeichnet und aus dem Tempel von Atal'Hakkar verbannt.\n\nDie Artefakte, die Ihr gebracht habt, sind harmlos. Doch im Beschwörungsritual könnte Gefahr lauern, denn Jammal'an könnte die richtige Fetischverzauberung gefunden haben. Die Welt könnte in großer Gefahr sein. Fel'zerul in Steinard wartet darauf zu erfahren, was der Verbannte herausgefunden hat."}},faq={{q="Wohin muss ich gehen, um mit Fel'zerul zu sprechen?",a="Fel'zerul ist in Steinard.",al={"fel'zerul standort","wo ist fel'zerul","rückkehr zu fel'zerul abgeben"}},{q="Warum wurde der Verbannte der Atal'ai verbannt?",a="Der Verbannte der Atal'ai sprach sich gegen Jammal'an the Prophets unerschütterlichen Glauben an dessen Prophezeiung aus, der seiner Befürchtung nach die Atal'ai vernichten könnte. Der Verbannte wurde als Ungläubiger bezeichnet und aus dem Tempel von Atal'Hakkar verbannt.",al={"warum wurde der verbannte der atal'ai verbannt","warum ist der verbannte im hinterland","vorgeschichte des verbannten der atal'ai"}},{q="Sind die Artefakte gefährlich, die dem Verbannten gebracht wurden?",a="Der Verbannte sagt, die Artefakte seien harmlos. Die Gefahr liegt im Beschwörungsritual und darin, ob Jammal'an die richtige Fetischverzauberung dafür gefunden hat.",al={"sind die artefakte schädlich","fetischartefakte gefahr"}}},fp="19,168,19.514.0,40.24.0,35.213.0,49.151.0"}
P.entries["quest:1447"] = {n="Der vermisste Diplomat",s="In Sturmwind sucht Ihr den vermissten Diplomaten und findet Dashel Steinfaust in der Altstadt. Ihr braucht Antworten von einem Mann, der sie lieber für sich behalten würde.",h="In Sturmwind sucht Ihr den vermissten Diplomaten und findet Dashel Steinfaust in der Altstadt.",kw={"schlägerei","verschwörung","dashel","vermisster diplomat","die altstadt","steinfaust","sturmwind","schläger"},ang={["class:Rogue"]="Als Schurke werdet Ihr mit Schlägern wie Dashel Steinfaust fertig, wenn Ihr Kontaktleuten Informationen aus den Gassen abpresst.",["faction:Alliance"]="Als Mitglied der Allianz kann Euch jede Spur zum Verschwinden des Diplomaten den Verrat enthüllen, der die Stabilität der Führung bedroht.",["race:Human"]="Als Mensch seht Ihr, wie Schläger aus Sturmwind die Suche nach dem vermissten Diplomaten behindern, was die Sicherheit des Königreichs bedroht."},sec={{t="Ein freundliches Gespräch in der Altstadt",b="In der Altstadt führt Euch Eure Suche durch die Reihen von Beutelschneidern und zwielichtigen Vermittlern, fernab des wachsamen Blicks der Kathedrale. Dashel Steinfaust ist ein örtlicher Kontaktmann mit Verbindungen zu den kriminellen Gruppierungen von Sturmwind. Er weiß von der Entführung, will sein Wissen aber nicht mit Ermittlern teilen, die heikle Fragen stellen."},{t="Schlägerei in der Gasse",b="Dashel Steinfaust weigert sich, mit Euch zusammenzuarbeiten, als Ihr an ihn herantretet. Seine treuen Schläger aus der Altstadt unterstützen ihn bei dem Versuch, Euch niederzuschlagen und die Ermittlungen zu beenden. Sobald Ihr Dashel und seine Männer bezwungen habt, schlägt er andere Töne an und weist Euch den Weg zur nächsten Spur der Verschwörung."}},faq={{q="Wer ist Dashel Steinfaust?",a="Dashel Steinfaust ist ein zwielichtiger Kontaktmann in der Altstadt mit Verbindungen zur kriminellen Unterwelt von Sturmwind. Er weiß mehr über heimliche Machenschaften in der Stadt, als er zugibt.",al={"dashel steinfaust","wer ist steinfaust","dashel"}},{q="Warum muss ich gegen Dashel kämpfen, statt einfach mit ihm zu reden?",a="Dashel hat kein Interesse daran, mit Ermittlern zusammenzuarbeiten. Als Ihr nach dem vermissten Diplomaten fragt, hält er Euch für leicht einzuschüchtern und ruft seine Schläger, um Euch zum Schweigen zu bringen. Erst eine ordentliche Tracht Prügel bringt ihn zum Reden.",al={"warum gegen dashel kämpfen","kann ich mit steinfaust reden","warum dashel verprügeln"}},{q="Muss ich Dashel Steinfaust töten?",a="Nein. Ihr müsst Dashel zur Aufgabe prügeln, ihn aber nicht töten. Wenn seine Gesundheit weit genug sinkt, gibt er auf, ruft seine Handlanger zurück und erklärt sich bereit, Eure Fragen zu beantworten.",al={"muss ich dashel töten","steinfaust am leben","ist dashel tot"}},{q="Wo findet dieser Kampf statt?",a="Der Kampf findet unter freiem Himmel in der Altstadt statt, nahe den Gassen hinter der Pig and Whistle Tavern und den örtlichen Ausbildungshallen, wo Dashel Steinfaust gewöhnlich herumlungert.",al={"steinfaust aufenthaltsort","wo ist dashel","schlägerei in der altstadt"}},{q="Was geschieht nach dem Sieg über Dashel?",a="Sobald Ihr Dashel besiegt habt, entschuldigt er sich und erklärt sich bereit, Euch zu erzählen, was er über die Verschwörung weiß. Er lenkt die Ermittlungen zum nächsten Glied in der Kette außerhalb der Hauptstadt.",al={"wie weiter nach dashel","steinfaust nächste quest","diplomatenquestreihe fortsetzung"}},{q="Worum geht es in der Questreihe „Der vermisste Diplomat“ eigentlich?",a="Die Suche nach einem verschwundenen Botschafter enthüllt ein Netz aus Täuschungen rund um die Entführung des Diplomaten und die zwielichtigen Gestalten dahinter.",al={"vermisster diplomat hintergrundgeschichte","wer ist der diplomat","vermisster könig"}}},fx={c22a58c4={q="Gegen wen kämpft Ihr in dieser Konfrontation?",a="Ihr kämpft gegen Dashel Steinfaust und ein Paar seiner bulligen Schläger aus Die Altstadt. Dashel operiert aus den rauen Gassen von Die Altstadt, umgeben von örtlichen Halunken, die seine Drecksarbeit erledigen und jeden einschüchtern, der seine Nase in Angelegenheiten steckt, die ihn nichts angehen. Anstatt Fragen über seine illegalen Verbindungen zu beantworten, ruft Dashel seine Freunde, um Euch windelweich zu prügeln, damit Ihr die Stadt niemals verlasst.",al={"gegen wen kämpfe ich fehlender diplomat","wer greift mit dashel an","ziel fehlender diplomat 8"}},["15b1a9ee"]={q="Warum greift Euch Dashel Steinfaust an?",a="Dashel möchte nicht, dass jemand Fragen über den fehlenden Diplomaten oder seine eigenen zwielichtigen Verbindungen stellt. Er operiert im Schatten von Die Altstadt und überlebt durch Geheimhaltung, Einschüchterung und Muskelkraft. Wenn Ihr ihn nach Antworten drängt, betrachtet er Euch als unerwünschten Schnüffler und leichtes Ziel und erwartet, dass seine Schläger Euch dauerhaft zum Schweigen bringen, bevor seine Verwicklung in dunklere Machenschaften ans Licht kommen kann.",al={"warum kämpft dashel steinfaust gegen dich","warum greift dashel an","motive von dashel steinfaust"}}},fp="20,149,27.304.0,18.260.1,24.173.0,61.224.0,35.163.0,33.166.0,34.164.1,50.126.2"}
P.entries["quest:145"] = {n="Botschaft nach Dunkelhain",s="In Seenhain richtet Magistrat Solomon einen dringenden Hilferuf an Dunkelhain. Schwarzfelsorcs und Gnolle bedrohen das Rotkammgebirge, und Solomon sucht militärische Unterstützung bei seinem Nachbarn. Ein Bote muss den Dämmerwald durchqueren, um den Brief an Lord Ello Schwarzhaupt, den Bürgermeister von Dunkelhain, zu überbringen.",h="In Seenhain richtet Magistrat Solomon einen dringenden Hilferuf an Dunkelhain.",kw={"dunkelhain","dämmerwald","schwarzhaupt","seenhain","bote","night watch","rotkammgebirge","solomon"},ang={["faction:Alliance"]="Solomons dringende Briefe zeigen, wie sehr die entlegenen Städte der Allianz vernachlässigt werden, während der königliche Hof von Sturmwind gelähmt bleibt.",["race:Human"]="Als Mensch teilt Ihr die Not der südlichen Menschensiedlungen, die auf örtliche Milizen angewiesen sind, seit das Königreich seine regulären Armeepatrouillen zurückgezogen hat."},sec={{t="Ein verzweifelter Hilferuf",b="Schwarzfelsorcs und Gnollrudel bedrängen das Rotkammgebirge, während Seenhains Wachen an ihre Grenzen stoßen. Der königliche Hof von Sturmwind hat die Bitten von Magistrat Solomon ignoriert, und Westfall steckt in seinem eigenen Aufstand fest. Da aus der Nähe kaum Hilfe kommt, schreibt Solomon an Bürgermeister Ello Schwarzhaupt im Dämmerwald. Er hofft, dass Dunkelhain seine Nachtwache ausleihen oder vermieten kann, um Seenhains Verteidigung zu stärken."},{t="Der Weg ins Dunkel",b="Solomons Brief reist nach Süden durch den Dämmerwald, einen Wald unter übernatürlicher Finsternis. Er warnt Euch, auf den Straßen zu bleiben, denn die Wildnis zwischen Seenhain und Dunkelhain ist gefährlich. Der Brief ist für das Rathaus bestimmt, wo Lord Schwarzhaupt ihn entgegennehmen kann. Ob der Dämmerwald überhaupt Truppen entbehren kann, bleibt ungewiss."}},faq={{q="Warum bittet Seenhain Dunkelhain um Hilfe?",a="Sturmwind hat offizielle Militärhilfe verweigert und Seenhain damit Bedrohungen wie den Schwarzfelsorcs allein überlassen. Magistrat Solomon bittet Verbündete in der Nähe um Hilfe und hofft, dass Dunkelhains Nachtwache ausgebildete Kämpfer entsenden kann.",al={"warum den dämmerwald bitten","warum dunkelhain","solomons hilferuf an dunkelhain"}},{q="Wer ist Lord Ello Schwarzhaupt?",a="Lord Ello Schwarzhaupt ist der Bürgermeister von Dunkelhain und eine führende zivile Persönlichkeit im Dämmerwald. Er leitet die Stadt vom Rathaus aus und stimmt die zivilen Angelegenheiten mit Kommandantin Althea Schwarzhaupt ab, die die Nachtwache führt.",al={"ello schwarzhaupt","wer ist schwarzhaupt","bürgermeister von dunkelhain"}},{q="Was ist die Nachtwache?",a="Die Nachtwache ist Dunkelhains unabhängige Bürgermiliz. Ohne Garnisonstruppen aus Sturmwind patrouilliert sie am Stadtrand und bekämpft Untote, Bestien und Schatten im Dämmerwald.",al={"night watch dämmerwald","wer ist die night watch"}},{q="Warum warnt Solomon mich, auf den Straßen zu bleiben?",a="In der Wildnis des Dämmerwalds lauern untote Schrecken, Spinnen und wilde Bestien. Wenn Ihr die befestigte Straße verlasst, setzt Ihr Euch Raubtieren und Hinterhalten aus.",al={"dämmerwald straßenwarnung","im dämmerwald auf den straßen bleiben"}},{q="Wo begann diese Questreihe?",a="Die dringenden Briefe von Magistrat Solomon begannen mit seinem Hilfsgesuch an Gryan Starkmantel in Westfall. Er setzt seine Bemühungen fort, Hilfe für Seenhain zu finden.",al={"vorherige quest","reihenfolge der botenquests"}},{q="Kann Dunkelhain tatsächlich Wachen entbehren?",a="Der Dämmerwald steckt in seiner eigenen Krise, mit auferstandenen Toten, umherwütenden Worgen und lauernden Monstrositäten. Die Nachtwache hat kaum genug Kämpfer, um Dunkelhain zu verteidigen, weshalb Solomons Bitte wenig Aussicht auf Erfolg hat.",al={"wird dunkelhain helfen","schickt schwarzhaupt wachen"}}},fx={["532260e8"]={q="Warum schickt Magistrat Solomon einen Abenteurer anstelle seiner eigenen Wachen?",a="Die örtliche Wache von Seenhain ist bis an ihre Belastungsgrenze erschöpft, während sie die Schwarzfelsorks und die Gnolle aus Rotkammgebirge abwehrt, die in die Stadt eindringen. Magistrat Solomon kann keinen einzigen Wachmann vom Verteidigungsring entbehren, um die gefährliche Reise nach Süden durch den Dämmerwald zu unternehmen. Da Sturmwind seine Bitten um königliche Truppen ignoriert, muss er sich auf zuverlässige Reisende wie Euch verlassen, um seine dringenden Appelle an benachbarte Städte zu überbringen.",al={"warum ich nach dunkelhain","warum schickt solomon keine wache","warum ich nachricht nach dunkelhain"}}},fp="22,269,24.368.0,23.314.0,43.219.0,27.211.0,24.179.0,46.142.0,31.141.0,45.187.0"}
P.entries["quest:1450"] = {n="Greifenmeister Talonaxe",s="In der Voliere von Nistgipfel ist Greifenmeister Talonaxe für die Flugeinteilung zuständig. Falstad Wildhammer schickt Euch dorthin, nachdem er jemanden abgewiesen hat, der für einen alten Freund aus der Forscherliga gekommen war.",h="In der Voliere von Nistgipfel ist Greifenmeister Talonaxe für die Flugeinteilung zuständig.",kw={"nistgipfel","voliere","brohann caskbelly","forscherliga","falstad wildhammer","greifenmeister talonaxe","rhapsody shindigger","uldaman"},sec={{t="Weggeschickt",b="Falstad Wildhammer hat wenig Geduld für einen Besucher, den ein altes Mitglied der Forscherliga geschickt hat. Er weiß nicht, mit wem dieser Freund einst geflogen ist, und für die Flugeinteilung ist der Greifenmeister zuständig. Ihr findet Greifenmeister Talonaxe in der Voliere von Nistgipfel. Falstad hat richtige Arbeit für jeden, der in der Nähe bleibt."},{t="Woran Talonaxe sich erinnert",b="Greifenmeister Talonaxe erinnert sich daran, einen Greifenreiter geschickt zu haben, um Brohann Caskbelly zu helfen. Die Forscherliga liegt Talonaxe schon lange am Herzen, denn Talonaxes Vater half dem ersten Ausgrabungsteam, Uldaman zu finden. Der Reiter war Rhapsody Shindigger, den Talonaxe damals für den Besten hielt."}},faq={{q="Warum schickt Falstad Wildhammer Euch zu Talonaxe?",a="Falstad Wildhammer weiß nicht, mit wem der Freund aus der Forscherliga geflogen ist. Deshalb schickt er Euch zum Greifenmeister, der für die Flugeinteilung zuständig ist.",al={"warum zu talonaxe","falstad schickt weg","wer ist talonaxe"}},{q="Wo befindet sich Greifenmeister Talonaxe?",a="Greifenmeister Talonaxe wartet in der Voliere von Nistgipfel.",al={"wo ist talonaxe","talonaxe standort","voliere von nistgipfel"}}},fp="23,189,9.313.0,23.286.1,49.147.0,41.59.0"}
P.entries["quest:1451"] = {n="Rhapsody-Shindigger",s="Bei der Voliere am Nistgipfel hat Talonaxe Neuigkeiten über einen gefallenen Flieger. Rhapsody Shindigger war einst ihr bester Flieger, doch der Schnaps kostete Rhapsody den Posten. Nun unterhält Rhapsody ein Braulager östlich der Voliere im Hinterland, wie Talonaxe gehört hat.",h="Bei der Voliere am Nistgipfel hat Talonaxe Neuigkeiten über einen gefallenen Flieger.",kw={"nistgipfel","voliere","brohann","gryphon master talonaxe","hinterland","rhapsody shindigger"},sec={{t="Ein gefallener Flieger",b="Greifenmeister Talonaxe erzählt, dass die Zwerge der Voliere alle ein gutes Bier schätzen. Rhapsody verfiel dem Schnaps so bereitwillig, wie sich ein Greif in die Lüfte schwingt. Niemand konnte so fliegen wie Rhapsody, und Talonaxe bedauert den Verlust noch immer.\n\nDer Ärger begann, als Rhapsody torkelnd von einer Reise mit Brohann zurückkehrte. Es ging rasch bergab, und die Voliere entließ Rhapsody. Nach Talonaxes letztem Kenntnisstand unterhält Rhapsody nun ein Braulager östlich vom Nistgipfel."}},faq={{q="Wer schickt Euch auf die Suche nach Rhapsody Shindigger?",a="Greifenmeister Talonaxe bei der Voliere am Nistgipfel schickt Euch auf die Suche nach Rhapsody.",al={"wer startet rhapsody shindigger","wer gibt die rhapsody-quest","wo rhapsody beginnen"}},{q="Warum wurde Rhapsody Shindigger aus der Voliere entlassen?",a="Rhapsody verfiel dem Schnaps so bereitwillig, wie sich ein Greif in die Lüfte schwingt. Der Ärger begann, als Rhapsody torkelnd von einem Flug mit Brohann zurückkehrte, dann ging es rasch bergab, bis die Voliere Rhapsody entließ.",al={"warum wurde rhapsody entlassen","was ist mit rhapsody passiert","rhapsody shindigger vorgeschichte"}},{q="Wo ist Rhapsody jetzt?",a="Talonaxe hat gehört, dass Rhapsody nun ein Braulager östlich der Voliere im Hinterland unterhält.",al={"wo ist rhapsody shindigger","rhapsodys lager fundort","wie rhapsody finden"}}},fp="19,238,14.423.0,42.76.0,51.198.0,22.94.0"}
P.entries["quest:1452"] = {n="Rhapsodys Kalimdor-Cocktail",s="Im Hinterland ist Rhapsody Shindigger bereit, Euch zu erzählen, was im Sumpf geschah, sobald er einen kräftigen Schluck getrunken hat. Sein Kalimdor Kocktail benötigt Roc-Muskelmägen aus Tanaris sowie Groddoc- und Ironfur-Lebern aus Feralas.",h="Im Hinterland ist Rhapsody Shindigger bereit, Euch zu erzählen, was im Sumpf geschah, sobald er einen...",kw={"brohann","feralas","groddoc-leber","ironfur-leber","kalimdor kocktail","rhapsody shindigger","roc-muskelmagen","tanaris"},sec={{t="Ein kräftiger Schluck",b="Rhapsody begrüßt Brohanns Boten mit einem Schluckauf. Die beiden haben ein ziemliches Abenteuer miteinander erlebt, aber Rhapsody erzählt Euch erst nach einem kräftigen Schluck, was im Sumpf geschah. Die Geschichte ist nicht schön. Er hat ein Rezept im Sinn: den Kalimdor Kocktail. Sobald er gebraut ist, verspricht er, Euch alles zu erzählen."},{t="Zutaten aus Kalimdor",b="Rhapsody braucht drei Roc-Muskelmägen aus Tanaris, drei Groddoc-Lebern aus Feralas und drei Ironfur-Lebern aus Feralas. Selbst sein feinster Malz kann ihm nicht helfen, sich der Erinnerung an jenen verhängnisvollen Flug über den Sumpf zu stellen."}},faq={{q="Was will Rhapsody für den Kalimdor Kocktail?",a="Rhapsody will drei Roc-Muskelmägen, drei Groddoc-Lebern und drei Ironfur-Lebern für den Kalimdor Kocktail. Er will einen kräftigen Schluck trinken, bevor er Euch erzählt, was im Sumpf geschah.",al={"warum kocktail","warum roc-muskelmägen","warum lebern"}},{q="Woher kommen die Zutaten?",a="Die Roc-Muskelmägen kommen aus Tanaris. Die Groddoc- und Ironfur-Lebern kommen aus Feralas.",al={"wo muskelmägen finden","cocktail zutaten fundorte","wo sind groddocs"}},{q="Wer hat Euch zu Rhapsody Shindigger geschickt?",a="Brohann hat Euch zu Rhapsody Shindigger geschickt, der Brohann einen verrückten Narren nennt. Davor hat Greifenmeister Talonaxe Euch gesagt, wo Ihr Rhapsody finden könnt.",al={"wer hat mich zu rhapsody geschickt","vorherige quest","brohan"}}},fp="28,214,13.292.0,25.213.0,50.178.0,35.85.0,36.142.0"}
P.entries["quest:1453"] = {n="Die Geschäfte der Wiederholer in Desolace",s="Roetten Steinhammer schickt Reisende von Eisenschmiede über das Meer nach Desolace, um für die Wiederholer bezahlte Arbeit zu leisten. Auf der Nijelspitze braucht Kreldig Ungor Hilfe bei der Bergung verlorener Schätze und Relikte.",h="Roetten Steinhammer schickt Reisende von Eisenschmiede über das Meer nach Desolace, um für die Wiederholer...",kw={"zentaur","desolace","eisenschmiede","kreldig ungor","die nijelspitze","wiederholer","roetten steinhammer","steinkrallengebirge"},ang={["faction:Alliance"]="Die Nijelspitze ist die wichtigste Zuflucht der Allianz im westlichen Ödland Zentralkalimdors. Feindselige Zentaurenklans umgeben sie.",["race:Dwarf"]="Als Zwerg könnt Ihr selbst in den trostlosesten Winkeln Kalimdors zwergischen Unternehmergeist finden, von der Explorers' Guild bis zu unabhängigen Bergungsgruppen wie den Wiederholern."},sec={{t="Ein Ruf ins Ödland",b="Jenseits des Meeres liegt Desolace, ein rauer Landstrich Kalimdors, beherrscht von verfeindeten Zentaurenklans. Die Wiederholer suchen in seinen vergessenen Ruinen und kargen Landen nach Gewinn. Für jene, die sich der Gefahr stellen, kann sich die Reise lohnen."},{t="Die Nijelspitze und die Wiederholer",b="Der Weg führt nach Westen durch das Steinkrallengebirge und ins nördliche Desolace. Hoch in den Klippen liegt die Nijelspitze, ein Außenposten der Allianz, wo Kreldig Ungor neue Helfer willkommen heißt. Die Wiederholer bergen Erbstücke, magische Artefakte und Familienschätze, die überall in der vom Krieg zerrütteten Welt verloren gingen. Für den richtigen Preis holen Kreldig und seine Partner diese Wertsachen aus der Wildnis zurück."}},faq={{q="Wer vergibt diese Quest?",a="Roetten Steinhammer bietet in Eisenschmiede bezahlte Arbeit an und schickt Euch über das Meer zu seinem Partner in Kalimdor.",al={"questgeber","wer startet die geschäfte der wiederholer","roetten steinhammer standort"}},{q="Wo liegt die Nijelspitze?",a="Die Nijelspitze liegt in den nordöstlichen Felsenhöhen von Desolace. Reist vom Steinkrallengebirge nach Süden nach Desolace und folgt dann den Klippen nach Osten zum fackelbeleuchteten Pfad, der zum Außenposten der Allianz hinaufführt.",al={"nijelspitze finden","wie kommt man zur nijelspitze","nijelspitze standort"}},{q="Wer sind die Wiederholer?",a="Die Wiederholer sind ein Unternehmen unter der Leitung zwergischer Agenten wie Kreldig Ungor. Für zahlende Kunden bergen sie verlorene Erbstücke, Altertümer und magische Relikte an gefährlichen Orten.",al={"was sind die wiederholer","wiederholer fraktion","wiederholer hintergrundgeschichte"}},{q="Welche Gefahren lauern in Desolace?",a="Verfeindete Zentaurenstämme, verbliebene Untote und feindselige Wildtiere bedrohen Reisende in Desolace, einem dürren Ödland jenseits des Steinkrallengebirges.",al={"desolace gefahren","was gibt es in desolace"}},{q="Wer ist Kreldig Ungor?",a="Kreldig Ungor ist ein Zwerg auf der Nijelspitze in Desolace. Er organisiert Bergungsarbeiten und Reliktsuchen in der ganzen Region und wirbt fähige Reisende an, die sich in ihre Ruinen und Zentaurenlager wagen.",al={"kreldig ungor hintergrundgeschichte","wer ist kreldig"}},{q="Ist diese Quest erforderlich, um in Desolace Quests zu erledigen?",a="Nein. Ihr könnt auch ohne Roetten Steinhammer zur Nijelspitze reisen, doch er bietet Euch Hintergrundwissen und eine Wegbeschreibung, bevor Ihr aufbrecht.",al={"ist diese quest nötig","sind die geschäfte der wiederholer erforderlich"}}},fx={["7014e979"]={q="Warum schickt Euch Roetten Steinhammer nach Desolace?",a="Roetten Steinhammer fungiert in der Sicherheit von Eisenschmiede als Verbindungsperson für die Reclaimers. Seine Partner an der Nijelspitze sehen sich in Desolace gefährlichem Boden gegenüber und benötigen ruhige, fähige Hände, um Verträge abzuwickeln. Indem Roetten fähige Abenteurer wie Euch an Kreldig Ungor verweist, stellt er sicher, dass ihre Schatzsuchergruppe trotz der feindseligen Gebiete der Zentauren personell besetzt und profitabel bleibt.",al={"grund für entsendung nach desolace","beweggrund von roetten steinhammer","grund für hilfe bei kreldig ungor"}},f82b8baa={q="Warum rekrutiert Roetten Steinhammer Abenteurer, anstatt selbst zu gehen?",a="Den Betrieb einer Bergungstruppe über Kontinente hinweg zu führen, erfordert ebenso Augen und Ohren in den großen Städten wie Muskelkraft vor Ort. Roetten bleibt in Eisenschmiede, um neue Talente zu lenken und Gelegenheiten zu vermitteln, und überlässt die strapaziöse Reise durch das Steinkrallengebirge sowie die Gefahren von Desolace abgehärteten Reisenden, die bereit sind, für Gold ihren Kopf zu riskieren.",al={"warum benötigt mich roetten","warum geht er nicht selbst","warum rekrutierung von abenteurern"}}},fp="32,193,23.222.0,32.374.0,21.113.0,23.194.0,23.181.0,31.144.0,21.181.0,44.127.0"}
P.entries["quest:1454"] = {n="Karnitols Schiffbruch",s="Nachdem Meeresriesen sein Schiff in Desolace angreifen, teleportiert sich Karnitol mit seinen Dienern in Sicherheit. Kreldig Ungor schickt Euch los, um die Truhe des Adeligen zu finden.",h="Nachdem Meeresriesen sein Schiff in Desolace angreifen, teleportiert sich Karnitol mit seinen Dienern in...",kw={"desolace","ethel rethor","karnitol","kreldig ungor","reclaimers","meeresriesen","schiffbruch","sturmwind"},sec={{t="Die Flucht eines Adeligen",b="Nach Reclaimers' Business in Desolace schickt Euch Kreldig Ungor los, um Karnitols verlorene Truhe zu finden. Karnitol ist ein Magier und eine Art Adeliger in Sturmwind. Meeresriesen griffen sein Schiff in den nordwestlichen Gewässern von Desolace an.\n\nEr und seine Diener versuchten, eine seiner kostbareren Truhen an Land zu bringen, doch die Riesen umringten sie. Karnitol ließ die Truhe zurück und teleportierte sich mit seinen Dienern fort. Findet die Truhe und ihren Inhalt und bringt beides dann zu Karnitol nach Sturmwind zurück. Sie liegt entlang der nördlichen Küste, im Abschnitt von Ethel Rethor."},{t="Was die Truhe verrät",b="Karnitols Truhe weist keine Wasserschäden auf, doch jemand hat ihren Deckel aufgebrochen. Brandspuren an den Rändern zeigen, dass ihre magischen Fallen schon vor langer Zeit ausgelöst wurden."}},faq={{q="Wer ist Karnitol?",a="Karnitol ist ein Magier und eine Art Adeliger in Sturmwind. Meeresriesen griffen sein Schiff in den nordwestlichen Gewässern von Desolace an.",al={"karnitol","wer ist karnitol","wer will die truhe"}},{q="Was geschah mit Karnitols Schiff?",a="Meeresriesen griffen Karnitols Schiff in den nordwestlichen Gewässern von Desolace an. Karnitol und seine Diener versuchten, eine wertvolle Truhe an Land zu bringen, doch die Riesen umringten sie. Er ließ sie zurück und teleportierte sich mit seinen Dienern fort.",al={"geschichte des schiffbruchs","warum sank das schiff","angriff der meeresriesen"}},{q="Wer sucht nach der Truhe?",a="Kreldig Ungor sucht nach der Truhe. Er sagt, Karnitol möchte, dass sie und ihr Inhalt gefunden und zu ihm nach Sturmwind zurückgebracht werden.",al={"wer vergibt die quest","kreldig ungors rolle"}},{q="Wo liegt die Truhe?",a="Die Truhe liegt entlang der nördlichen Küste von Desolace, im Abschnitt von Ethel Rethor.",al={"karnitols truhe fundort","wo ist karnitols truhe","ethel rethor truhe"}}},fp="22,150,16.527.0,20.148.1,16.114.0,33.217.0,29.122.0,25.80.0"}
P.entries["quest:1455"] = {n="Karnitols Schiffbruch",s="Bei Karnitols Wrack findet Ihr die Truhe offen und leer vor. Tiefe Kratzer durchziehen ihre Seiten und Oberseite, also kehrt Ihr zu Kreldig Ungor an der Nijelspitze zurück.",h="Bei Karnitols Wrack findet Ihr die Truhe offen und leer vor.",kw={"desolace","karnitol","karnitols truhe","kreldig ungor","die nijelspitze","schiffbruch"},sec={{t="Eine leere Truhe",b="Die Truhe ist leer, ihre Seiten und Oberseite sind von langen, tiefen Kratzern durchzogen. Die Spuren lassen darauf schließen, dass weder Mensch noch Riese sie aufgebrochen hat. Sie sehen nicht wie Schnitte von einem Dolch oder Schwert aus. Da es nichts weiter herauszufinden gibt, schließt Ihr die Truhe und bereitet Euren Aufbruch vor. Kreldig Ungor wird enttäuscht sein."}},faq={{q="Was befindet sich in Karnitols Truhe?",a="In Karnitols Truhe ist nichts mehr. Sie ist vollkommen leer.",al={"was war in karnitols truhe","ist karnitols truhe leer","truheninhalt"}},{q="Was hat die Spuren an der Truhe verursacht?",a="Lange, tiefe Kratzer durchziehen die Seiten und die Oberseite der Truhe. Sie lassen darauf schließen, dass weder Mensch noch Riese sie verursacht hat, und sehen nicht wie Dolch- oder Schwertschnitte aus.",al={"was hat die truhe geöffnet","wer hat die fracht genommen","klauenspuren an der truhe"}},{q="Wem erstattet Ihr Bericht?",a="Ihr erstattet Kreldig Ungor an der Nijelspitze in Desolace Bericht.",al={"bei wem abgeben","wo ist kreldig ungor","wohin als nächstes"}},{q="Was geschah zuvor?",a="Zuvor bat Kreldig Ungor Euch, nach Karnitols Truhe zu suchen.",al={"vorherige quest","karnitols schiffbruch questreihe"}}},fp="22,144,14.281.0,32.60.0,33.142.0,21.57.0,22.68.0"}
P.entries["quest:1456"] = {n="Karnitols Schiffbruch",s="Nahe der Insel Ranazjar hofft Kreldig Ungor noch immer, dass Karnitols Habseligkeiten gefunden werden können. Die Slitherblade-Naga leben in Nachtelfenruinen unter dem Meer, wo Kreldig den Ranzen am ehesten vermutet.",h="Nahe der Insel Ranazjar hofft Kreldig Ungor noch immer, dass Karnitols Habseligkeiten gefunden werden können.",kw={"desolace","karnitol","kreldig ungor","die insel ranazjar","reclaimers","ranzen","meerhexe","slitherblade","flutjäger"},sec={{t="Ruinen in der Tiefe",b="Kreldig Ungor sagt, es bestehe noch Hoffnung, Karnitols Habseligkeiten zu finden. Weiter nördlich entlang der Küste liegen nahe der Insel Ranazjar versunkene Nachtelfenruinen auf dem Meeresgrund. Die Slitherblade-Naga leben dort, und Kreldig hält dies für den wahrscheinlichsten Ort, um Karnitols Ranzen zu finden. Er gibt Euch einen Trank der Bergungstaucher."},{t="Die stärkeren Naga",b="Kreldig glaubt, dass der Spähtrupp, der so weit nach Süden gereist ist, stark gewesen sein muss. Er würde zuerst die mächtigeren Naga durchsuchen: die Flutjäger und Meerhexen."}},faq={{q="Wer bittet Euch, Karnitols Ranzen zu finden?",a="Kreldig Ungor bittet Euch, Karnitols Ranzen in Desolace zu finden.",al={"wer vergibt diese quest","questgeber karnitols ranzen","wer ist kreldig ungor"}},{q="Wo vermutet Kreldig die Habseligkeiten?",a="Kreldig glaubt, dass Karnitols Habseligkeiten in den versunkenen Nachtelfenruinen weiter nördlich entlang der Küste nahe der Insel Ranazjar liegen. Die Slitherblade-Naga haben dort ihre Heimat.",al={"wo ist karnitols ranzen","fundort des ranzens","wo sind die slitherblade-naga"}},{q="Welche Naga solltet Ihr laut Kreldig zuerst durchsuchen?",a="Kreldig schlägt vor, zuerst die Flutjäger und Meerhexen zu durchsuchen. Er folgert, dass ein Spähtrupp, der so weit nach Süden gereist ist, mächtig gewesen sein muss.",al={"wer hat den ranzen","welche naga haben ihn","flutjäger oder meerhexe"}},{q="Was kam davor?",a="Davor kam der zweite Teil der Suche nach Karnitols Schiffswrack.",al={"karnitols schiffbruch questreihe","welche quest kommt davor"}}},fp="22,202,17.318.0,17.159.0,40.62.0,44.160.0,48.150.0,22.66.0"}
P.entries["quest:1457"] = {n="Karnitols Schiffbruch",s="Karnitols Tasche wartet in Eisenschmiede auf Roetten Steinhammer, der Euch bezahlt, wenn Ihr sie dorthin bringt.",h="Karnitols Tasche wartet in Eisenschmiede auf Roetten Steinhammer, der Euch bezahlt, wenn Ihr sie dorthin...",kw={"desolace","eisenschmiede","karnitol","karnitols tasche","kreldig ungor","reclaimers","roetten steinhammer"},sec={{t="Zurück nach Eisenschmiede",b="Kreldig Ungor schickt Euch mit Karnitols Sachen zu Roetten Steinhammer in Eisenschmiede. Roetten wird Euch für die Arbeit bezahlen. Lachend sagt Kreldig, Roetten könnte so erfreut sein, dass er Euch bittet, den Reclaimers in Vollzeit beizutreten. Reist vorsichtig und ohne Verzögerung. Karnitol hat wenig Geduld, ist aber großzügig."},{t="In Eisenschmiede",b="In Eisenschmiede zeigt sich Roetten Steinhammer mit der Angelegenheit um Karnitol in Desolace zufrieden. Die Truhe wurde zerstört, doch ihr gesamter Inhalt ist hier. Roetten überlässt Karnitol das Urteil. Man verlässt sich auf die Reclaimers, um Verlorenes zu finden und nicht, um es in gutem Zustand zurückzubringen. Dann macht sich Roetten daran, Euch zu bezahlen."}},faq={{q="Wem soll ich Karnitols Tasche übergeben?",a="Übergebt Karnitols Tasche an Roetten Steinhammer in Eisenschmiede.",al={"wohin mit der tasche","karnitols schiffbruch abgeben","wer bekommt karnitols tasche"}},{q="Wer schickt mich zurück nach Eisenschmiede?",a="Kreldig Ungor schickt Euch zurück nach Eisenschmiede und lobt Eure Arbeit.",al={"wer vergibt die quest","questgeber karnitols schiffbruch teil vier"}},{q="Warum ist es wichtig, die Tasche schnell abzuliefern?",a="Kreldig sagt, Karnitol habe wenig Geduld, sei aber sehr großzügig.",al={"warum nach eisenschmiede eilen","ist karnitol geduldig"}},{q="Wer ist Roetten Steinhammer?",a="Roetten Steinhammer ist der Mann der Reclaimers in Eisenschmiede. Seine Geschäfte florieren, und kleinere Angelegenheiten überlässt er seinen Untergebenen.",al={"roetten steinhammer hintergrundgeschichte","wer ist roetten"}}},fp="22,98,17.314.0,12.292.1,39.63.0,31.64.0,51.70.0,27.134.0"}
P.entries["quest:1458"] = {n="Reagenzien für die Wiederholer AG",s="In Desolace sammelt Kreldig Ungor Reagenzien für Leftwitch, einen Gnommagier in Kharanos. Den Reclaimers fehlen Leute, also beginnt er mit Klauen und Hörnern der Hatefury-Satyren im Osten.",h="In Desolace sammelt Kreldig Ungor Reagenzien für Leftwitch, einen Gnommagier in Kharanos.",kw={"desolace","hatefury","kharanos","kreldig ungor","leftwitch","reclaimers","roetten","sargeron","satyr"},sec={{t="Leftwitchs Liste",b="Nach Reclaimers' Business in Desolace übernimmt Kreldig Ungor einen weiteren Auftrag. Er sammelt Reagenzien für Leftwitch, einen Gnommagier, der in Kharanos lebt. Roetten nennt es leicht verdientes Geld, weil die Reclaimers bereits in Desolace sind. Der Mannschaft fehlen Leute, doch Kreldig sagt, das kümmere ihn nicht."},{t="Hörner und Klauen",b="Kreldig beginnt mit zehn Klauen und zehn Hörnern der Hatefury-Satyren im Osten. Sie leben in den Ruinen von Sargeron, direkt östlich der Nijelspitze. Sobald Ihr die Klauen und Hörner habt, kann der Rest von Leftwitchs Liste angegangen werden."}},faq={{q="Wer verlangt diese Reagenzien?",a="Kreldig Ungor sammelt Reagenzien für Leftwitch, einen Gnommagier, der in Kharanos lebt. Roetten nennt es leicht verdientes Geld, weil die Reclaimers bereits in Desolace sind.",al={"wer ist leftwitch","reagenzien für die wiederholer ag questgeber","wer will die reagenzien"}},{q="Wo befinden sich die Hatefury-Satyren?",a="Die Hatefury-Satyren befinden sich in den Ruinen von Sargeron, direkt östlich der Nijelspitze.",al={"hatefury-satyren fundort","wo sind hatefury-klauen","hatefury-hörner fundort"}},{q="Was will Kreldig von den Satyren?",a="Kreldig will zehn Hatefury-Klauen und zehn Hatefury-Hörner. Damit könnt Ihr und Kreldig Euch den nächsten Gegenständen auf Leftwitchs Liste zuwenden.",al={"was muss gesammelt werden","reagenzien für die wiederholer ag gegenstände","benötigte satyrteile"}},{q="Was hält Kreldig von Satyren?",a="Kreldig nennt die Satyren verabscheuungswürdige Kreaturen. Er hat gehört, dass sie irgendwie mit den Nachtelfen verbunden sind, doch er bezweifelt es. Er glaubt, die Geschichte gehe auf den einen Elfen zurück, der sie vor einigen Jahren in den Krieg hineingezogen hat. Seiner Meinung nach ist die Welt seitdem gefährlicher und furchteinflößender geworden.",al={"kreldig satyrgeschichte","sind satyren nachtelfen"}}},fp="28,189,16.282.0,15.217.0,33.156.0,38.73.0,39.134.0,37.290.0"}
P.entries["quest:1459"] = {n="Reagenzien für die Wiederholer AG",s="In Desolace schickt Leftwitchs Liste Kreldig Ungor auf die Suche nach Scorpashigift und Häuten gealterter Kodos. Er kennt das Land kaum und kann Euch nicht sagen, wo Ihr die beiden Kreaturen findet.",h="In Desolace schickt Leftwitchs Liste Kreldig Ungor auf die Suche nach Scorpashigift und Häuten gealterter...",kw={"haut gealterter kodos","desolace","eisenschmiede","kreldig ungor","leftwitch","wiederholer ag","scorpashigift"},sec={{t="Die nächsten Gegenstände",b="Kreldig Ungor kommt zu den nächsten Gegenständen auf Leftwitchs Liste. Sie verlangt sieben Phiolen Gift von beliebigen Scorpashi und drei Häute von gealterten Kodos. Sterbende und uralte Kodos genügen nicht. Die Anweisungen sind klar, doch Kreldig sinniert darüber, dass Magier sonderbare Dinge verlangen."},{t="Unvertrautes Land",b="Kreldig kann Euch nicht sagen, wo die Kodos oder Scorpashi umherstreifen. Er kennt Desolace kaum und hatte keine Zeit, es zu erkunden."}},faq={{q="Wer verlangt diese Reagenzien?",a="Leftwitch, eine Magierin, hat die Liste erstellt, die Kreldig Ungor abarbeitet.",al={"wer will reagenzien","wer ist leftwitch","kreldigs vorgesetzte"}},{q="Warum braucht Kreldig Hilfe bei der Suche nach diesen Kreaturen?",a="Kreldig kennt Desolace kaum und hatte keine Zeit, es zu erkunden, daher kann er nicht sagen, wo die Kodos oder Scorpashi umherstreifen.",al={"warum kann kreldig sie nicht beschaffen","kreldigs gebietskenntnisse"}},{q="Können Häute von beliebigen Kodos verwendet werden?",a="Nein. Leftwitch verlangt Häute von gealterten Kodos. Sterbende und uralte Kodos zählen nicht.",al={"beliebige kodohaut","haut uralter kodos","haut sterbender kodos"}},{q="Was sind die Scorpashi?",a="Scorpashi sind Skorpione, die in ganz Desolace vorkommen. Leftwitch sagt, dass das Gift von jedem von ihnen genügt.",al={"scorpashigift","wo sind scorpashi"}},{q="Wo streifen die gealterten Kodos umher?",a="Gealterte Kodos folgen den Pfaden, vor allem im Süden und Westen. Viele landen in der Nähe des Kodofriedhofs.",al={"aufenthaltsort gealterter kodos","wo sind gealterte kodos"}}},fp="28,162,14.258.0,17.117.0,33.66.0,51.115.0,32.76.0,23.97.0,28.96.0"}
P.entries["quest:146"] = {n="Botschaft nach Dunkelhain",s="In Dunkelhain beantwortet Lord Ello Schwarzhaupt ein Hilfegesuch aus Seenhain. Schwarzfelsorcs und Gnolle bedrängen die Stadt, doch dem Gesuch kann nicht entsprochen werden.",h="In Dunkelhain beantwortet Lord Ello Schwarzhaupt ein Hilfegesuch aus Seenhain.",kw={"dunkelhain","schwarzhaupt","seenhain","bote","night watch","solomon","sturmwind"},ang={["faction:Alliance"]="Für die Allianz offenbart diese Depesche tiefe Risse im südlichen Königreich. Entlegene Siedlungen bleiben im Stich gelassen und schutzlos zurück.",["race:Human"]="Als menschlicher Reisender könnt Ihr sehen, wie isoliert die Städte des Reiches inzwischen sind, während der königliche Hof wegsieht."},sec={{t="Ein verzweifeltes Gesuch abgelehnt",b="Magistrat Solomon aus dem Rotkammgebirge bittet seinen alten Amtskollegen im Dämmerwald um Truppen. Schwarzfelsorcs und Gnolle rücken seiner Stadt immer näher. Lord Ello Schwarzhaupt antwortet voller Zorn. Dunkelhain kämpft an allen Fronten gegen die lebenden Toten, unersättliche Bestien und verfluchte Magie. Schwarzhaupt sagt, die Nachtwache existiere, weil Sturmwind den Dämmerwald im Stich gelassen habe. Ohne seine Verteidiger würde Dunkelhain fallen, bevor eine Patrouille den Wald durchqueren könnte."},{t="Ein Muster des Rückzugs",b="Magistrat Solomon liest Schwarzhaupts Antwort und erkennt im ganzen Königreich ein Muster des Rückzugs. Die Armee von Sturmwind verließ Westfall, Dunkelhain wurde sich selbst überlassen, und Seenhains Hilferufe blieben unbeantwortet. Anführer im ganzen Königreich flüstern, dahinter könnte mehr stecken als Nachlässigkeit oder Unfähigkeit. Solomon sieht sich nun ihrem Verdacht auf Verrat im Herzen von Sturmwind gegenüber."}},faq={{q="Warum schickt Lord Schwarzhaupt die Nachtwache nicht nach Seenhain, um zu helfen?",a="Dunkelhain wird von Untoten, Bestien und finsterer Zauberei bedrängt. Die Nachtwache ist eine örtliche Miliz, die nach dem Abzug von Sturmwinds Garnisonen gegründet wurde. Würde Schwarzhaupt seine Wachen ins Rotkammgebirge schicken, würde Dunkelhain fallen, bevor sie den Wald durchquert hätten.",al={"warum lehnt schwarzhaupt ab","warum keine night watch für seenhain","dunkelhain verweigert hilfe"}},{q="Was erkennt Magistrat Solomon beim Lesen der Antwort?",a="Solomon sieht Seenhains Notlage als Teil einer Krise im ganzen Königreich. Die Armee hat sich aus Westfall zurückgezogen, und Dunkelhain wurde sich selbst überlassen. Er vermutet Verrat in Sturmwinds Führung, keine bloße Vernachlässigung.",al={"solomons reaktion","was erkennt solomon"}},{q="Wer hat die Nachtwache gegründet?",a="Die bedrängten Bürger und Anführer des Dämmerwalds gründeten die Nachtwache unter Lord Ello Schwarzhaupt, nachdem Sturmwinds Truppen das Gebiet Dunkelheit und Fäulnis überlassen hatten.",al={"ursprünge der night watch","wer gründete die night watch"}},{q="Wohin wendet sich Solomon nun, um Hilfe zu erhalten?",a="Da Dunkelhain die Hilfe verweigert und Westfall von der Bruderschaft der Defias überrannt wurde, steht Seenhain allein. Solomon sucht am Palasthof von Sturmwind nach Antworten darauf, warum die Krone ihre entlegenen Gebiete nicht schützt.",al={"was tut solomon als nächstes","wer kann seenhain sonst helfen"}},{q="Hat sich Sturmwind offiziell aus dem Dämmerwald und Westfall zurückgezogen?",a="Ja. Als dunkle Magie den Dämmerwald verdarb und in Westfall Unruhen ausbrachen, zogen sich Sturmwinds reguläre Truppen zurück. Um zu überleben, stellten die Grenzstädte örtliche Milizen auf, darunter die Nachtwache und die Volksmiliz.",al={"warum zog sturmwind ab","sturmwind ließ städte im stich"}},{q="In welchem Verhältnis stehen Solomon und Schwarzhaupt zueinander?",a="Solomon und Schwarzhaupt sind langjährige Amtskollegen und Magistrate, die Grenzstädte regieren. Solomon setzte auf ihre persönliche Verbindung, als er um Truppen bat, doch die Gefahren im Dämmerwald machten es Schwarzhaupt unmöglich, dem Gesuch zu entsprechen.",al={"sind solomon und schwarzhaupt freunde","beziehung zwischen solomon und ello"}}},fx={ec08915e={q="Warum schickt Euch Lord Schwarzhaupt, um den Brief auszuliefern, anstatt seine eigenen Wachen zu schicken?",a="Lord Schwarzhaupt kann keinen einzigen Angehörigen der The Nachtwache entbehren. Dunkelhain wird von Dunkelheit und abscheulichen Schrecken belagert, und jedes Schwert wird verzweifelt benötigt, um die Stadt davor zu bewahren, überrannt zu werden. Da Ihr als Kurier von Magistrat Solomon aus Seenhain angekommen seid, kostet es Dunkelhain keinen seiner kostbaren Verteidiger, Euch mit seiner Antwort zurückzuschicken.",al={"warum die entsendung meiner person","warum nicht die night watch schicken","warum verwendung eines abenteurers"}}},fp="22,155,26.418.0,24.375.1,64.232.0,63.217.0,27.162.0,44.216.0,59.208.0,51.227.0"}
P.entries["quest:1462"] = {n="Erdsapta",s="In Camp Narache bereitet Seherin Rabenfeder einen weiteren Erdsapta für einen jungen Schamanen zu, dessen Gebräu vor Abschluss des Ritus verloren ging. Der Trank öffnet einem Novizen den Blick für die Geister des Steins, damit die Prüfung weitergehen kann.",h="In Camp Narache bereitet Seherin Rabenfeder einen weiteren Erdsapta für einen jungen Schamanen zu, dessen...",kw={"call of earth","camp narache","trank","erdsapta","elementar","mulgore","seherin rabenfeder","schamane"},ang={["class:Shaman"]="Als Schamane beginnt Ihr mit einem Sapta, der Euren Blick für die Elementarkräfte öffnet, die die Welt lenken.",["faction:Horde"]="Als Mitglied der Horde seht Ihr, wie schamanische Traditionen in Mulgore gepflegt werden, wo Stammesseher die nächste Generation geistiger Führer anleiten.",["race:Tauren"]="Als Tauren beginnt Ihr, die Earth Mother zu ehren, indem Ihr lernt, auf das Land zu hören. Die Ältesten von Camp Narache sorgen dafür, dass keinem jungen Tauren dieser heilige Pfad verwehrt wird."},sec={{t="Ein Trank der Visionen",b="Junge Schamanen lernen zunächst, Kräfte jenseits des gewöhnlichen Blicks zu spüren. Um Mulg ores Erdelementaren zu begegnen, trinkt ein Initiant einen Sapta aus natürlichen Essenzen von Stein und Erde. Der Erdsapta lüftet den Schleier zwischen der physischen und der geistigen Welt. Dann kann ein Novize die Geister des Landes sehen und mit ihnen Zwiesprache halten."},{t="Eine zweite Chance zu sehen",b="Ein Novize kann das Gebräu verlieren oder verschütten, bevor er das Steinmonument zur Zwiesprache erreicht. Seherin Rabenfeder wartet in Camp Narache und bereitet ein weiteres Gefäß zu, wenn ein Schüler eines benötigt. Mit dem Ersatztrank kann der Novize den Ritus fortsetzen und den Geistern gegenübertreten."}},faq={{q="Was ist ein Erdsapta?",a="Ein Erdsapta ist ein Gebräu, das von Schamanenältesten zubereitet wird. Trinkt ein Initiant davon, erweckt der Trank seine inneren Sinne und verleiht ihm den Geisterblick, um verborgene Erdelementare wahrzunehmen und mit ihnen Zwiesprache zu halten.",al={"was ist sapta","erdsapta hintergrund","was bewirkt das gebräu"}},{q="Warum braucht ein Initiant einen weiteren Erdsapta?",a="Ein Initiant kann den Trank in der Wildnis verlieren oder verschütten, bevor er die heilige Stätte erreicht. Seherin Rabenfeder stellt eine weitere Dosis bereit, damit ein Missgeschick die Ausbildung nicht aufhält.",al={"sapta verloren","warum einen weiteren sapta holen","erdsapta verloren"}},{q="Wer ist Seherin Rabenfeder?",a="Seherin Rabenfeder ist eine geistige Führerin der Tauren in Camp Narache in Mulgore. Sie begleitet junge Taurenschamanen durch ihre ersten Prüfungen und ihre erste Zwiesprache mit den Geistern der Erde.",al={"wer ist rabenfeder","seherin rabenfeder hintergrund","camp narache seherin"}},{q="Warum müssen Schamanen einen Sapta trinken, um Elementare zu sehen?",a="Schamanennovizen haben noch nicht gelernt, die Elemente nach Belieben wahrzunehmen. Ein Sapta hilft ihren Sinnen auf die Sprünge, bis sie lernen, aus eigener Kraft auf die Elemente zu hören und mit ihnen Zwiesprache zu halten.",al={"warum braucht man einen trank um geister zu sehen","warum sapta trinken"}},{q="Wo findet die Prüfung des Erdsaptas statt?",a="Die Prüfung findet in den Hügeln der Hochwolkenebene in Mulgore nahe Camp Narache statt. Novizen tragen den Trank zu einem heiligen Steinmonument, an dem die örtlichen Erdgeister wohnen.",al={"wo sapta verwenden","call of earth ort"}},{q="Verwenden alle Schamanen Saptas?",a="Sowohl die schamanischen Traditionen der Tauren als auch die der Orcs verwenden Saptas für die ersten Einweihungen in die Elemente. Erde, Feuer und Wasser haben jeweils einen eigenen Sapta, der die Sinne eines Schamanen auf die entsprechende Elementarebene einstimmt.",al={"verwenden orcs saptas","sind saptas nur für tauren"}}},fx={["5f71bc62"]={q="Warum gibt Euch Seherin Rabenfeder eine weitere Earth Sapta?",a="Seherin Rabenfeder hat die Aufgabe, junge Tauren-Initianden durch ihre Elementarprüfungen zu führen. Ohne das Trinken der Earth Sapta kann ein Initiand nicht mit dem Geist der Erde kommunizieren oder seine Kommunion vollenden. Sollten Ihr Euren Trank verlieren oder verschütten, stellt Rabenfeder einen weiteren zur Verfügung, damit Eure heilige Reise nicht gestoppt wird, bevor Ihr das Elementarwesen erreicht.",al={"warum gibt ravenfeather die earth sapta","beweggrund von seherin rabenfeder","grund für erneute ausgabe der sapta"}}},fp="11,221,19.318.0,24.259.0,23.225.0,47.168.0,25.185.0,48.182.0,51.169.0,25.192.0"}
P.entries["quest:1463"] = {n="Erdsapta",s="Im Tal der Prüfungen geht Erdsapta verloren, und ein Initiand kann Canaga Erdenrufer um Ersatz bitten. Der Ersatz lässt den jungen Schamanen mit den Geistern des Landes Zwiesprache halten, verbunden mit der Mahnung, heilige Tränke sorgfältig zu hüten.",h="Im Tal der Prüfungen geht Erdsapta verloren, und ein Initiand kann Canaga Erdenrufer um Ersatz bitten.",kw={"call of earth","canaga erdenrufer","trank","durotar","erdsapta","schamane","totem","das tal der prüfungen"},ang={["class:Shaman"]="Als Schamanen-Initiand lernt Ihr Disziplin, wenn Ihr das Sapta verliert. Zwiesprache mit den Elementen verlangt beständige Achtsamkeit und sorgsame Hände.",["race:Orc"]="Als Orc erlernt Ihr in Durotars kargen Felsen die uralten Wege des Schamanismus. Eure Hingabe wird an den Ahnen und der Erde unter Euren Stiefeln gemessen.",["race:Troll"]="Als Dunkelspeertroll lernt Ihr im Tal der Prüfungen, die traditionelle Loaverehrung mit der Ehrfurcht vor den Elementargeistern in Einklang zu bringen."},sec={{t="Eine zweite Chance mit den Elementen",b="Ein Initiand, der das Erdsapta verliert, verliert womöglich die Gelegenheit, mit den Geistern von Stein und Erde Zwiesprache zu halten. Rituale bereiten das elementare Gebräu zu, das den Schleier zwischen der physischen Welt und den Geistern dünner werden lässt. Geht der Trank auf Reisen durch Durotar verloren oder wird er verschüttet, bereitet Canaga Erdenrufer im guten Glauben einen weiteren zu. Er mahnt den Novizen, heilige Gaben mit größerer Sorgfalt zu hüten."},{t="Canagas Führung",b="Canaga Erdenrufer wacht über angehende Schamanen, die aus dem Den im Tal der Prüfungen hervortreten. Junge Orcs und Trolle können bei ihren ersten Prüfungen straucheln, doch Elementargeister nehmen Nachlässigkeit übel. Ein zweites Sapta anzunehmen, ist eine kleine Lektion in Demut. Die von der Erde gewährte Macht muss gehütet und respektiert werden."}},faq={{q="Was ist ein Erdsapta?",a="Das Erdsapta ist ein zeremonieller Trank, der für Schamanen-Initianden zubereitet wird. Wer ihn trinkt, erlangt geistige Sicht und kann so elementare Erdgeister wahrnehmen und mit ihnen sprechen, die gewöhnlichen Augen verborgen bleiben.",al={"was ist sapta","verwendung von erdsapta","zweck von sapta"}},{q="Warum bietet Canaga Erdenrufer diese Quest an?",a="Canaga Erdenrufer bietet ein weiteres Erdsapta an, wenn ein Initiand seines verliert oder verlegt, bevor er während der Prüfungen von Call of Earth das Zwiespracheritual vollendet. Er stellt im guten Glauben Ersatz bereit, damit der Akolyth die spirituelle Aufgabe abschließen kann.",al={"warum canaga sapta gibt","erdsapta verloren"}},{q="Wo findet dieses Ritual statt?",a="Die Übergabe findet im Tal der Prüfungen statt, einer sonnenversengten Schlucht im Südwesten Durotars. Dort beginnen junge Orcs und Trolle ihren Weg der Disziplin und Ehre.",al={"wo ist canaga","sapta fundort im tal der prüfungen"}},{q="Missbilligen die Geister den Verlust des Saptas?",a="Canaga warnt Initianden, dass ein sorgloser Umgang mit heiligen Tränken mangelnde Achtsamkeit zeigt. Ein wahrer Schamane behandelt jede Gabe der Elemente mit Ehrfurcht.",al={"hat der verlust von sapta folgen","hintergrund zum verlust von sapta"}},{q="Wer kann diese Zwiesprache halten?",a="Schamanen, die sich auf ihr erstes elementares Totem, das Erdtotem, einstimmen möchten, dürfen das Erdsapta zubereiten und trinken.",al={"wer kann erdsapta erhalten","klassen für sapta"}},{q="Was geschieht, nachdem ein Initiand das Sapta getrunken hat?",a="Das Trinken des Tranks öffnet die innere Sicht eines Initianden. Anschließend kann er eine örtliche Manifestation des Erdgeistes finden, die sich zwischen den Felsen des Tals der Prüfungen verbirgt, und mit ihr sprechen.",al={"was bewirkt sapta beim trinken","nach dem erdsapta"}}},fp="11,228,33.384.0,17.329.0,23.191.0,45.246.0,34.170.0,47.145.0,33.124.0,48.180.0"}
P.entries["quest:1465"] = {n="Vahlarriels Suche",s="In Desolace folgt Vahlarriels Suche einer Spur vom Wagen der Malems nach Süden. Dort liegt ein Anhänger, und in der Ferne steigt Rauch von einer großen Festung auf. An der Nijelspitze braucht Vahlarriel Demonslayer den Anhänger und die Nachricht, dass die Malems noch am Leben sein könnten.",h="In Desolace folgt Vahlarriels Suche einer Spur vom Wagen der Malems nach Süden.",kw={"burning blade","demonslayer","desolace","festung","malem","die nijelspitze","anhänger","vahlarriel"},sec={{t="Lebenszeichen",b="Ihr findet im Wagen der Malems einen Anhänger und Fußspuren, die nach Süden führen. In der Ferne steigt Rauch von einer großen Festung auf. Er stammt von einem geschürten Feuer, nicht von brennenden Gebäuden. Wenn die Malems noch leben, deuten die Spuren darauf hin, dass sie zur Festung verschleppt wurden."},{t="Nachricht für Vahlarriel",b="An der Nijelspitze muss Vahlarriel Demonslayer den Malem-Anhänger sehen. Erzählt ihr von den Fußspuren, die nach Süden führen."},{t="Was die Einheimischen sagen",b="Vahlarriel ist außer sich vor Wut. Die Malems wurden gewarnt, wie gefährlich Desolace ist, und nun werden beide vermisst oder Schlimmeres. Spuren zur nahen Festung bieten den besten Anhaltspunkt. Einheimische sagen, die Festung sei von der Burning Blade überrannt, Orcs, die sich dämonischen Zielen verschrieben haben. Sie sprechen nicht für den Großteil der Horde, doch sie sind böse. Jeder, der beim Ausspionieren erwischt wird, wird auf der Stelle getötet."}},faq={{q="Was habt Ihr im Wagen gefunden?",a="Ihr findet im Wagen einen Anhänger und Fußspuren, die nach Süden führen. In der Ferne steigt Rauch von einer großen Festung auf.",al={"was ist in der truhe","hinweise am wagen","malem-anhänger"}},{q="Wohin führen die Spuren?",a="Die Spuren führen nach Süden zu einer großen Festung. Der Rauch darüber stammt von einem geschürten Feuer, nicht von brennenden Gebäuden. Wenn die Malems noch leben, wurden sie möglicherweise in diese Richtung verschleppt.",al={"wohin führten die fußspuren","wo ist die festung","richtung der spuren"}},{q="Wo befindet sich Vahlarriel Demonslayer?",a="Vahlarriel Demonslayer ist an der Nijelspitze in Desolace. Bringt den Anhänger und die Nachricht von den Spuren dorthin.",al={"vahlarriels standort","wo malem-anhänger abgeben","vahlarriel demonslayer standort"}}},fp="19,255,13.248.0,19.117.0,19.361.1,31.108.0,25.166.0,40.103.0"}
P.entries["quest:1466"] = {n="Reagenzien für die Wiederholer AG",s="In Desolace hat Kreldig Ungor die letzten Gegenstände, die Leftwitch verlangt hat. Sie alle stammen von Dämonen: Gehirne, Flügel und Blut.",h="In Desolace hat Kreldig Ungor die letzten Gegenstände, die Leftwitch verlangt hat.",kw={"desolace","blut der verderberwachen","teufelshundgehirn","kreldig ungor","leftwitch","mannorocs koven","netherflügel","wiederholer ag"},sec={{t="Der Rest der Liste",b="Kreldig Ungor warnt Euch, dass die letzte Zusammenstellung eine düstere Angelegenheit ist und ihre Beschaffung länger dauert als jede zuvor. Leftwitch verlangt drei Arten von Teilen, jeweils zehn Stück. Ihr könnt Teufelshundgehirne von Manaessern, Magierjägern oder Leyjägern erbeuten. Die Flügel stammen von Nethermaiden, Schwestern oder Zauberinnen, während Hauptmänner und Fürsten der Verderberwachen das Blut liefern. Kreldig würde es verstehen, wenn Ihr diese Aufgabe auslasst."},{t="Dämonen in Desolace",b="Kreldig Ungor hatte nicht gewusst, dass diese Dämonen in Desolace lebten. Seiner Lektüre zufolge beherrschten die Zentauren den Großteil des Landes, nachdem die Nachtelfen vor Jahren abgezogen waren. Deshalb fragt er sich, wie die Dämonen hierherkamen und warum sie sich niederließen. Sie hausen nahe Mannorocs Koven im Süden von Desolace, jenseits des Kodofriedhofs."}},faq={{q="Wer verlangt diese Dämonenteile?",a="Kreldig Ungor reicht Leftwitchs Liste weiter, und die Dämonenteile sind die letzten Gegenstände, die Leftwitch verlangt hat.",al={"wer hat diese quest vergeben","wer will die dämonenteile","wer ist kreldig ungor"}},{q="Welche Kreaturen haben die benötigten Gegenstände?",a="Manaesser, Magierjäger und Leyjäger haben Teufelshundgehirne. Nethermaiden, Schwestern und Zauberinnen haben Flügel. Hauptmänner und Fürsten der Verderberwachen haben Blut.",al={"was lässt teufelshundgehirne fallen","wo gibt es netherflügel","welche verderberwachen haben blut"}},{q="Wo sind diese Dämonen zu finden?",a="Die Dämonen sammeln sich nahe Mannorocs Koven im Süden von Desolace, jenseits des Kodofriedhofs.",al={"fundort der dämonen","wo ist mannorocs koven","wo streifen die dämonen umher"}},{q="Warum überraschen die Dämonen Kreldig?",a="Kreldig hatte gelesen, dass die Zentauren Desolace beherrschten, nachdem die Nachtelfen vor Jahren abgezogen waren, deshalb verwundert ihn die Anwesenheit der Dämonen.",al={"warum sind dämonen in desolace","geschichte der zentauren in desolace"}}},fp="28,119,20.384.0,18.293.0,36.105.0,39.159.0,32.86.0,44.122.0"}
P.entries["quest:1467"] = {n="Reagenzien für die Wiederholer AG.",s="In Desolace schickt Kreldig Ungor Euch mit Leftwitchs Paket nach Eisenschmiede. Roetten Steinhammer hat Eure Bezahlung, und Kreldig will nach seiner Heimkehr ein gutes Wort für Euch einlegen.",h="In Desolace schickt Kreldig Ungor Euch mit Leftwitchs Paket nach Eisenschmiede.",kw={"desolace","eisenschmiede","kreldig ungor","leftwitchs paket","reagenzien für die wiederholer ag","roetten steinhammer"},sec={{t="Bezahlung in Eisenschmiede",b="Kreldig sagt, Roetten Steinhammer habe Eure Bezahlung in Eisenschmiede. Roetten wird sich über Leftwitchs Paket freuen, und die Übergabe sollte genügen, um zu erhalten, was Euch zusteht. Kreldig rechnet damit, nur noch kurze Zeit in Desolace zu bleiben. Sobald er wieder zu Hause ist, will er weiterhin ein gutes Wort für Euch einlegen."},{t="Roettens Dank",b="Roetten Steinhammer nimmt Leftwitchs Paket aus Desolace freudig entgegen und dankt Euch für Eure Arbeit und deren rasche Erledigung. Eure Bezahlung liegt bereit. Roetten sagt, die Wiederholer AG bezahle stets gut für eine harte Arbeitswoche."}},faq={{q="Wer schickt Euch zurück nach Eisenschmiede?",a="Nachdem die Reagenzien gesammelt sind, schickt Kreldig Ungor Euch mit Leftwitchs Paket nach Eisenschmiede.",al={"questgeber","wer gibt die quest","wer beginnt das"}},{q="Wohin muss Leftwitchs Paket gebracht werden?",a="Leftwitchs Paket geht an Roetten Steinhammer in Eisenschmiede.",al={"wohin das paket bringen","ziel des pakets","wer bekommt das paket"}},{q="Warum bringt Ihr Roetten das Paket?",a="Kreldig sagt, Roetten Steinhammer habe Eure Bezahlung, also bringt Ihr ihm das Paket nach Eisenschmiede.",al={"warum das paket bringen","warum roetten besuchen"}},{q="Bleibt Kreldig Ungor in Desolace?",a="Kreldig rechnet damit, Desolace bald zu verlassen. Sobald er wieder zu Hause ist, will er weiterhin ein gutes Wort für Euch einlegen.",al={"verlässt kreldig desolace","wohin geht kreldig"}}},fp="28,170,20.291.0,16.210.1,32.95.0,42.61.0,40.89.0,39.93.0"}
P.entries["quest:1469"] = {n="Rhapsodys Geschichte",s="Nachdem Rhapsody Shindigger seinen Kalimdor Kocktail bekommen hat, erzählt er vom Flug mit Brohann Caskbelly. Er gibt Euch ein Schrifttafelfragment der Atal'ai, das Ihr zu Brohann in Sturmwind bringen sollt.",h="Nachdem Rhapsody Shindigger seinen Kalimdor Kocktail bekommen hat, erzählt er vom Flug mit Brohann Caskbelly.",kw={"atal'ai","brohann","caskbelly","fragment","hinterlands","rhapsody","shindigger","sturmwind","schrifttafel"},sec={{t="Ein Fragment für Brohann",b="Rhapsody Shindigger erzählt Euch, was nach dem Kocktail geschah. Vor dem Flug trank er ein ganzes Fass Starkbier, während Brohann ihm durch den Himmel folgte. Rhapsody behielt ein Trollsouvenir, ein Schrifttafelfragment der Atal'ai. Nun bittet er Euch, es zu Brohann Caskbelly in Sturmwind zu bringen."},{t="Wo der Flug endete",b="Rhapsody sah aus der Luft keinen Tempel. Ein wenig zu beschwipst fiel er von seinem Reittier und stürzte ins Wasser. Die Strömung zog ihn hinab zwischen unheimliche Trolle, und er schwamm mit einem Souvenir schnell wieder hinaus. Brohanns Tempel liegt unter Wasser."}},faq={{q="Wer erhält das Schrifttafelfragment der Atal'ai?",a="Bringt das Schrifttafelfragment der Atal'ai zu Brohann Caskbelly in Sturmwind.",al={"wem das fragment geben","brohanns standort","wohin mit der schrifttafel"}},{q="Woran erinnert sich Rhapsody vom Flug mit Brohann?",a="Vor dem Flug trank Rhapsody ein ganzes Fass Starkbier, dann flog er durch den Himmel, während Brohann ihm folgte.",al={"warum flog rhapsody","brohann und rhapsody"}},{q="Was kam vor diesem Schritt?",a="Rhapsodys Kalimdor Kocktail kam zuerst. Er wollte die Geschichte erst erzählen, wenn das Getränk zubereitet war.",al={"vorherige quest","voraussetzung für rhapsodys geschichte"}}},fp="15,173,22.278.0,22.233.1,41.67.0,55.112.0,27.93.0"}
P.entries["quest:147"] = {n="Menschenjagd",s="Im Wald von Elwynn schickt Euch Marschall Dughan los, um den Collector zu finden, einen Geldeintreiber der Defias. Er arbeitet von Brackbrunns überranntem Kürbisbeet aus und schickt gestohlenes Gold aus den Minen des Waldes an die Bruderschaft.",h="Im Wald von Elwynn schickt Euch Marschall Dughan los, um den Collector zu finden, einen Geldeintreiber der...",kw={"brackbrunns kürbisbeet","collector","defias","goldhain","manhunt","marschall dughan","ring","stonemasons guild"},ang={["class:Rogue"]="Als Schurke könnt Ihr erkennen, wie die verdeckte Arbeit des Collectors das wachsende Netz von Wegelagerern und Beutelschneidern widerspiegelt, das im gesamten Wald von Elwynn Fuß fasst.",["faction:Alliance"]="Als Mitglied der Allianz helft Ihr, Sturmwinds örtliche Ressourcen zu schützen. Wenn Ihr den Collector aufhaltet, unterbindet Ihr einen illegalen Goldstrom aus dem Königreich, der eine Rebellion nahe der Hauptstadt finanzieren soll.",["race:Human"]="Als Mensch spürt Ihr womöglich, welches Gewicht die Bergung des Rings des Stonemason hat. Er erinnert an die erbitterten Arbeitskämpfe, die das Königreich nach dem Wiederaufbau von Sturmwind spalteten."},sec={{t="Gerechtigkeit im Kürbisbeet",b="Marschall Dughan schickt Euch zu Brackbrunns Kürbisbeet, nachdem bei Elwynns Gnollen ein Zeitplan für Goldabholungen gefunden wurde. Banditen der Defias und Gnolle haben das einst ruhige Gehöft übernommen. Der Collector versteckt sich zwischen den überwucherten Ranken, zweigt Erz aus den Minen des Königreichs ab und organisiert Lieferungen für die wachsende Rebellion."},{t="Das Siegel eines Handwerkers",b="Nachdem Ihr den Collector erschlagen habt, nehmt Ihr seinen Ring an Euch und bringt ihn zu Marschall Dughan. Der Marschall ist verwirrt: Der Reif trägt das Zeichen der alten Stonemasons Guild von Sturmwind, kein gewöhnliches Verbrecherwappen. Der Ring deutet darauf hin, dass die Wegelagerer, die den Wald von Elwynn im Würgegriff halten, mehr als Opportunisten sind. Einige waren Handwerker, die nach dem Wiederaufbau von Sturmwind verbitterten und zu Gesetzlosen wurden."}},faq={{q="Wo kann ich den Collector finden?",a="Der Collector versteckt sich bei Brackbrunns Kürbisbeet im Südosten des Waldes von Elwynn, gleich östlich der Weinberge der Maclures und nördlich der Flussgrenze.",al={"collector aufenthaltsort","wo ist collector","collector fundort"}},{q="Warum stiehlt der Collector Gold aus Elwynns Minen?",a="Der Collector sammelt geschmuggeltes Erz und erpresste Zahlungen aus den von Kobolden verseuchten Minen Fargodeep und Jasperlode, um die verdeckten Unternehmungen der Bruderschaft der Defias im gesamten Königreich zu finanzieren.",al={"warum gold stehlen","defias minen","was macht collector"}},{q="Welche Bedeutung hat der Ring des Collectors?",a="Der Ring ist ein Mitgliedsring der alten Stonemasons Guild, deren Handwerker Sturmwind nach dem Ersten Krieg wiederaufbauten. Marschall Dughan kann nicht erklären, warum ein einfacher Dieb, der mit den Defias zusammenarbeitet, einen Ring einer Handwerkergilde trägt, und hofft auf eine Antwort.",al={"geschichte von collectors ring","stonemason ring","was bedeutet der ring"}},{q="Findet Marschall Dughan heraus, wer hinter der Bruderschaft steckt?",a="Nicht sofort. Marschall Dughan erkennt das Handwerkerabzeichen auf dem Ring, kann aber nicht erklären, warum ein gewöhnlicher Dieb einen Siegelring einer Handwerkergilde trägt. Die größere Verschwörung bleibt in Goldhain eine offene Frage.",al={"weiß dughan bescheid","dughans reaktion","marschall dughan stonemasons"}},{q="Wer schickt Euch auf diese Menschenjagd?",a="Marschall Dughan, der Garnisonskommandant im Gasthaus \"Zur Höhle des Löwen\" in Goldhain, bietet Euch diese Arbeit an, nachdem Ihr den Abholplan der Defias sichergestellt habt.",al={"wer vergibt manhunt","questgeber manhunt","marschall dughan quest"}},{q="Was ist mit der Familie Brackwell geschehen?",a="Brackbrunns Kürbisbeet liegt in Trümmern, von seinen Besitzern verlassen und von Schurken der Defias, Banditen und vordringenden Riverpaw-Gnollen besetzt, die durch die südöstlichen Wälder streifen.",al={"brackwell geschichte","wem gehört das kürbisbeet","brackwell hof"}}},fx={["1901992d"]={q="Warum will Marschall Dughan, dass der The Collector aufgehalten wird?",a="Gold, das aus den Minen im Wald von Elwynn geplündert wurde, ist Eigentum des Königreichs Sturmwind. Indem er diesen Reichtum systematisch abzweigt, beraubt der The Collector aktiv das Reich und finanziert illegale Machenschaften. Marschall Dughan kann nicht zulassen, dass Diebe die Ressourcen der Krone ungestraft plündern, insbesondere wenn das gestohlene Gold auf eine organisierte Verschwörung hinter dem örtlichen Banditentum hindeutet.",al={"grund für stoppen des collectors","beweggrund von marschall dughan manhunt","warum interessiert sich dughan für den collector"}},["535c4316"]={q="Wer ist der The Collector und warum ist er bei Brackwells Kürbisbeet?",a="Der The Collector ist ein Agent, der mit den Dieben der Defias zusammenarbeitet, um illegales Gold, das aus den Minen im Wald von Elwynn stammt, zu sammeln und zu transportieren. Er nutzt Brackwells Kürbisbeet als abgelegenes Versteck und wartet dort gemäß dem Abholplan auf Lieferungen, bevor er den Reichtum des Königreichs aus dem Wald schmuggelt.",al={"wer ist der collector","grund für anwesenheit des collectors in brackwells kürbisbeet","ziel der menschenjagd"}},e23a6feb={q="Warum schickt Marschall Dughan einen Abenteurer anstatt der Wachen von Sturmwind?",a="Die Stadtwache von Sturmwind und die Garnison von Goldhain sind im Wald von Elwynn gefährlich dünn gestreut und durch Gnoll-Einfälle, Kobold-Befall in den Minen und grassierende Defias-Banditen festgefahren. Dughan fehlen einfach die übrigen Soldaten, um eine Menschenjagd auf ein abgelegenes Kürbisbeet auszusenden, was ihn dazu zwingt, sich auf fähige, vertrauenswürdige Abenteurer zu verlassen.",al={"warum benötigt mich dughan","warum abenteurer für manhunt entsenden","warum töten die wachen den collector nicht"}}},fp="7,198,28.325.0,17.371.1,31.145.0,55.184.0,49.271.1,61.207.1,30.143.0,38.176.0"}
P.entries["quest:1470"] = {n="Der zerrissene Schleier",s="In Todesend prüft Venya Marthand die Entschlossenheit eines angehenden Hexenmeisters. Frisch erweckte Verlassene sammeln Schädel von geistlosen Skeletten in der Nähe, um das Wissen zur Beschwörung und Bindung eines Wichtels zu erlangen.",h="In Todesend prüft Venya Marthand die Entschlossenheit eines angehenden Hexenmeisters.",kw={"todesend","wichtel","der zerrissene schleier","schädel eines klappernden skeletts","tirisfal","venya marthand","hexenmeister"},ang={["class:Warlock"]="Als Hexenmeister macht Ihr Euren ersten wahren Schritt in die Dämonologie und lernt, dass chaotische Magie sich einem eisernen Willen beugen muss.",["race:Undead"]="Als Verlassener schöpft Ihr aus Eurer Losgelöstheit von der Sterblichkeit, während Ihr in Todesends Schatten chaotische und dunkle Magie studiert."},sec={{t="Der erste Schritt eines Neulings",b="Venya Marthand lehrt frisch erwachte Hexenmeister der Verlassenen in Todesend, dass Stärke aus Wissen und der Beherrschung chaotischer Mächte erwächst. Sie schickt sie aus, um Schädel von Rattlecage Skeletons nahe Todesends verlassener Schmiede zu sammeln. Die Prüfung zeigt, ob sie sich genug konzentrieren können, um Mächte jenseits dieser Welt zu beherrschen und Wesen des Nethers zu unterwerfen."},{t="Den Nether unterwerfen",b="Venya nimmt die Schädel als Beweis an, dass ein Neuling geistlose Untote überwinden und sich den düsteren Wahrheiten der Hexenmeisterkunst stellen kann. Dann lehrt sie die Rituale zur Beschwörung und Bindung eines Wichtels. So klein er auch ist, der Dämon bringt Gerissenheit und Feuer mit und ist ein gefährlicher Verbündeter."}},faq={{q="Wer vergibt die Quest „Der zerrissene Schleier“?",a="Venya Marthand, die Hexenmeisterlehrerin der Verlassenen in Todesend, vergibt die Prüfung.",al={"wer startet der zerrissene schleier","der zerrissene schleier questgeber","venya marthand quest"}},{q="Was müsst Ihr sammeln, um diese Quest abzuschließen?",a="Ihr sammelt drei Rattlecage Skulls von Rattlecage Skeletons nahe Todesends verfallener Schmiede.",al={"der zerrissene schleier questziel","was für der zerrissene schleier sammeln","rattlecage skulls"}},{q="Warum will Venya Marthand Skelettschädel?",a="Die Jagd auf geistlose Skelette prüft Beherrschung, Entschlossenheit und magische Grundfertigkeiten eines angehenden Hexenmeisters, bevor Venya ihm gefährlichere dämonische Rituale anvertraut.",al={"warum rattlecage skulls","zweck der schädelquest"}},{q="Welche Macht oder welchen Diener lernt Ihr zu beschwören?",a="Die Lektion bereitet einen Hexenmeister darauf vor, einen Wichtel zu beschwören und zu binden, den ersten dämonischen Begleiter, den er zu befehligen lernt.",al={"der zerrissene schleier belohnungszauber","welchen dämon erhält man","wichtelbeschwörung quest"}},{q="Wo befinden sich die Rattlecage Skeletons?",a="Rattlecage Skeletons streifen am Rand von Todesend umher, besonders um die verfallende, verlassene Schmiede nordwestlich der zentralen Lichtung des Ortes.",al={"rattlecage skeleton fundort","wo sind die skelette in todesend","verlassene schmiede todesend"}},{q="Wer kann diese Quest annehmen?",a="Hexenmeister der Verlassenen, die in Todesend eine grundlegende Ausbildung erhalten haben, können sich der Prüfung stellen.",al={"wer kann der zerrissene schleier annehmen","können andere klassen das machen","nur für hexenmeister"}}},fx={["149b6242"]={q="Wozu dient der Schädel eines klappernden Skeletts?",a="Venya Marthand verwendet die Schädel als Prüfung, um Eure aufstrebende Beherrschung der dunklen Magie zu testen. Hexenmeister glauben, dass Wissen und Wille ihre größten Waffen sind, und der Beweis, dass Ihr diese Überreste von den ruhelosen Toten ernten könnt, zeigt, dass Ihr über genügend Disziplin verfügt, um einen Wichtel zu beschwören und an Euren Dienst zu binden.",al={"wozu dienen schädel eines klappernden skeletts","grund für schädel eines klappernden skeletts","zweck der schädel eines klappernden skeletts"}},d14f3c7d={q="Warum schickt Euch Venya Marthand, anstatt es selbst zu erledigen?",a="Venya Marthand ist Eure Ausbilderin für Hexenmeister, keine Auftragsvermittlerin. Das Sammeln der Schädel ist keine Aufgabe, die sie für sich selbst erledigt haben muss, sondern eine wichtige Lektion für Euch. Um den Schleier zu durchdringen und chaotische Wesen der Leere Eurem Willen zu beugen, müsst Ihr zuerst Eure Kraft und Entschlossenheit allein beweisen.",al={"warum ich bei piercing the veil","warum verlangt venya das beschaffen der schädel","warum kann venya marthand sie nicht selbst beschaffen"}},d722d37c={q="Wer sind die Rattlecage Skeletons?",a="Rattlecage Skeletons sind geistlose Untote der Geißel, die um die verlassene Schmiede in Todesend herumlungern. Wie ein Großteil von Tirisfal bleiben die Ländereien von den Überresten der Seuche und den zerrütteten Streitkräften des Lichkönigs heimgesucht, was sie zu willkommener Beute für unerfahrene Hexenmeister der Verlassenen macht, die ihre wachsende Macht erproben wollen.",al={"was sind klapperkäfigskelette","klapperkäfigskelette todesend","warum klapperkäfigskelette hier"}}},fp="17,178,21.340.0,22.255.0,38.76.0,45.94.0,45.155.0,44.107.0,43.138.0,40.83.0"}
P.entries["quest:1471"] = {n="Die Bindung",s="Im Magieviertel von Unterstadt streben Hexenmeister der Verlassenen nach Macht über einen Leerwandler, den sie für immer beschwören und befehligen können. Carendin Halgar wacht über den Ritus, der ihnen diese Macht verleiht.",h="Im Magieviertel von Unterstadt streben Hexenmeister der Verlassenen nach Macht über einen Leerwandler, den...",kw={"carendin halgar","magieviertel","runen der beschwörung","unterwerfung","die bindung","unterstadt","leerwandler","hexenmeisterquest"},ang={["class:Warlock"]="Als Hexenmeister führt Euch dieser Ritus von kleinen Tricks mit Wichteln zur Herrschaft über Wesen, die im Kampf gewaltigen körperlichen Schaden einstecken können.",["race:Undead"]="Als Angehöriger der Verlassenen erweitert die Bindung einer Schattenkreatur Eure Widerstandskraft und Eure moralische Hemmungslosigkeit im Umgang mit verbotener Magie."},sec={{t="Ein Ritus der Unterwerfung",b="Hexenmeister der Verlassenen müssen beweisen, dass sie einen Leerwandler beherrschen können, bevor sie einen beschwören dürfen. Niedere Wichtel lassen sich durch dunkle Magie leicht zu Pakten bewegen. Creature of the Void verabscheuen die Wirklichkeit und besitzen gewaltige körperliche Macht. Im Magieviertel stellt Mentor Carendin Halgar die mystischen Runen bereit, die einen Leerwandler aus dem Nether in die physische Welt reißen."},{t="Im Inneren des Kreises",b="Unterhalb von Carendin Halgars Podest ist ein leuchtender Beschwörungskreis in den Boden geritzt. Aktiviert die Runen, und ein ungebundener Leerwandler erscheint voller Zorn. Diplomatie kann ihn nicht bezwingen; arkane Macht und schierer Wille müssen ihn brechen. Erst wenn die Kreatur vollkommen zerschlagen ist, offenbart Carendin die wahre Beschwörungsformel, die ihre Essenz auf unbestimmte Zeit an Euch bindet."}},faq={{q="Welchem Zweck dient dieses Ritual?",a="Der Ritus prüft, ob Ihr eine Kreatur der Leere überwältigen könnt. Der Sieg über einen ungebundenen Leerwandler beweist, dass Euer Wille stark genug ist, ihn zu beherrschen. Dann lehrt Euch Carendin Halgar den Zauber, mit dem Ihr ihn dauerhaft beschwören könnt.",al={"warum die bindung abschließen","was bewirkt die quest die bindung","belohnung der bindung"}},{q="Wo findet die Beschwörung statt?",a="Die Beschwörung findet im violetten Kreis statt, der unterhalb von Carendin Halgars Plattform im Magieviertel von Unterstadt in den Boden geritzt ist.",al={"wo leerwandler beschwören","wo ist der beschwörungskreis","beschwörungskreis unterstadt"}},{q="Wer ist Carendin Halgar?",a="Carendin Halgar ist der oberste Hexenmeisterlehrer im Magieviertel von Unterstadt. Er beaufsichtigt die Ausbildung und die dunklen Initiationsriten frisch erweckter Verlassener, die sich dieser Kunst widmen.",al={"wer ist halgar","carendin halgar hintergrundgeschichte"}},{q="Müssen Hexenmeister jeden Dämon besiegen, den sie beschwören wollen?",a="Hexenmeister müssen ihre Herrschaft über mächtige Wesen von jenseits dieser Welt begründen, bevor sie ihnen befehlen können. Kleinere Wesen wie Wichtel werden durch einfache Verträge und Rituale gebunden, während Leerwandler körperliche und magische Überlegenheit verlangen, bevor sie sich zum Dienst unterwerfen.",al={"kämpfen hexenmeister immer gegen dämonen","warum gegen den leerwandler kämpfen"}},{q="Was geschieht, wenn ein Hexenmeister den Leerwandler nicht bezwingen kann?",a="Ein ungebundener Leerwandler schlägt unerbittlich auf jeden in seiner Nähe ein. Halgar warnt, dass es nichts bedeutet, seine Erwartungen zu enttäuschen, verglichen mit der Gefahr, von dem ungezähmten Wesen im Kreis zerrissen zu werden.",al={"was passiert beim scheitern an der bindung","hexenmeister scheitern hintergrundgeschichte"}},{q="Was ist ein Leerwandler?",a="Leerwandler sind schattenhafte Wesen aus der Leere, jenseits der physischen Welt. Sie besitzen gewaltige körperliche Widerstandskraft und einen angeborenen Drang, lebendiges Licht und Energie auszulöschen, was sie zu idealen Schutzschilden für Anwender dunkler Magie macht.",al={"was ist ein leerwandler","leerwandler hintergrundgeschichte"}}},fx={abacfa90={q="Warum möchte Carendin Halgar, dass dieses Ritual durchgeführt wird?",a="Carendin Halgar strebt danach, gewaltige Macht innerhalb der Reihen der Hexenmeister der Unterstadt zu kultivieren. Indem er Euch zwingt, ein ungebundenes Creature of the Void vollständig Eurem Willen zu unterwerfen, stellt er sicher, dass die Praktizierenden der Verlassenen echte Unterwerfung beherrschen, anstatt den außerweltlichen Wesen zum Opfer zu fallen, die sie zu befehligen versuchen.",al={"beweggrund von carendin halgar bei the binding","beweggrund von carendin halgar","grund für beschwörung des leerwandlers"}},["68d93197"]={q="Was ist das Wesen, das Ihr beschwören und besiegen sollt?",a="Ihr zieht einen ungebundenen Leerwandler direkt aus dem Wirbelnden Nether in den Beschwörungskreis. Leerwandler sind schattenhafte Dämonen, die aus reiner Leerenenergie geformt sind, feindselig und grollend gegenüber der Knechtschaft, und erfordern eine direkte magische und kriegerische Niederlage, bevor sie den Willen eines Meisters akzeptieren.",al={"gegen wen kämpft man bei the binding","ziel von the binding","wen beschwöre ich"}},["15849809"]={q="Warum müsst Ihr den Leerwandler selbst unterwerfen, anstatt es Carendin Halgar tun zu lassen?",a="Dämonologie erfordert persönliche Vorherrschaft. Ein beschworener Dämon beugt sich nur demjenigen, der die magische Autorität und physische Stärke beweist, ihn zu besiegen. Wenn Carendin oder die Stadtwachen eingreifen würden, um das Wesen zu unterwerfen, wäre der Leerwandler an ihren Willen gebunden, statt an Euren.",al={"grund für eigenen kampf","warum hilft carendin nicht","warum ich bei der quest the binding"}}},fp="11,180,21.349.0,17.351.0,35.214.0,36.137.0,23.166.0,59.261.0,57.203.0,21.240.0"}
P.entries["quest:1472"] = {n="Verschlinger der Seelen",s="Im Tempel der Verdammten lehrt Carendin Halgar Hexenmeister der Verlassenen, einen Sukkubus zu binden. Godrick Farsan weiß, wie man mit den Herzen reiner, liebender Sterblicher einen aus dem Wirbelnden Nether lockt.",h="Im Tempel der Verdammten lehrt Carendin Halgar Hexenmeister der Verlassenen, einen Sukkubus zu binden.",kw={"köder","carendin halgar","godrick farsan","hearts of the pure","sukkubus","tempel der verdammten","unterstadt"},ang={["class:Warlock"]="Als Hexenmeister macht Ihr mit der Bindung eines Sukkubus einen bedeutenden Schritt in Eurer Ausbildung. Ihr nutzt die Laster und Begierden eines Dämons, um ihn zu versklaven.",["race:Undead"]="Als Untoter lernt Ihr unter Hexenmeistern der Verlassenen im Tempel der Verdammten. Ohne moralische Bedenken nutzen sie die Reinheit und Hingabe der Lebenden als Reagenzien für Netherrituale."},sec={{t="Köder für den Nether",b="Carendin Halgar lehrt, dass ein Sukkubus über die Schwelle gelockt werden muss und nicht auf Befehl herbeigerufen werden kann. Der Dämon giert danach, Tugend zu verderben und sterbliche Essenz zu verzehren. Bietet die Herzen wahrhaft tugendhafter, liebender Männer als Köder dar. Halgar schickt Euch zu Godrick Farsan, der weiß, wo sich solch seltene Beute finden lässt."},{t="Der blinde Assistent",b="Tief im Tempel der Verdammten hilft Godrick Farsan Carendin bei den Vorbereitungen für die Bindung von Dämonen. Farsan hat sein Augenlicht verloren, sagt aber, dies habe ihm einen tieferen Blick verliehen. Er behauptet, geistige Strömungen und ferne Seelen mit unheimlicher Klarheit wahrzunehmen. Mit diesem Blick kann er Euch zu den reinen Herzen führen, die nötig sind, um den Dämon hervorzulocken."}},faq={{q="Welchen Zweck hat diese Quest?",a="Dieser Schritt führt Euch von Carendin Halgars Ruf zur Jagd, die nötig ist, um einen Sukkubus zu binden. Ihr sucht Godrick Farsan auf, der die grausigen Anforderungen des Rituals erklärt.",al={"warum verschlinger der seelen","sukkubusquest unterstadt","hexenmeisterquest stufe zwanzig"}},{q="Warum braucht es reine Herzen, um einen Sukkubus zu beschwören?",a="Carendin Halgar sagt, ein Sukkubus brauche einen unwiderstehlichen Köder, um in diese Welt hinüberzutreten. Der Dämon giert danach, Güte zu verderben, sterbliche Herzen zu verführen und tugendhafte Seelen zu verschlingen, weshalb ihn die unbefleckte Hingabe guter Männer hinüberlockt.",al={"warum hearts of the pure","sukkubusköder hintergrund"}},{q="Wer ist Godrick Farsan?",a="Godrick Farsan ist ein untoter Hexenmeisterakolyth, der Carendin Halgar im Tempel der Verdammten unterstützt. Obwohl er körperlich blind ist, helfen ihm seine mystischen Sinne, geistige Wahrheiten wahrzunehmen und geeignete Beute in den Östlichen Königreichen aufzuspüren.",al={"wer ist farsan","blinder hexenmeisterassistent"}},{q="Wo wird diese Quest abgeschlossen?",a="Ihr schließt diese Quest im Tempel der Verdammten in Unterstadt ab. Godrick Farsan wartet nur wenige Schritte von Carendin Halgar entfernt.",al={"wo ist godrick farsan","verschlinger der seelen abgeben"}},{q="Was folgt auf Verschlinger der Seelen?",a="Godrick Farsan schickt Euch als Nächstes zu Hearts of the Pure. Ihr reist ins Sumpfland und zum Greymane-Wall im Silberwald, um die Herzen zweier tugendhafter Sterblicher zu erbeuten.",al={"nächste quest nach verschlinger der seelen","hearts of the pure als nächstes"}},{q="Kann jedes Volk dieses Ritual durchführen?",a="Jeder Hexenmeister der Horde, der mithilfe der Lehrmeister in Unterstadt einen Sukkubus binden möchte, kann Halgars und Farsans Ritualschritten folgen. Praktizierende der Verlassenen lehren es in Unterstadt, doch das Ritual steht diesen Hexenmeistern offen.",al={"wer kann verschlinger der seelen machen","hexenmeisterquest nur für untote"}}},fx={["99fee797"]={q="Warum will Carendin Halgar eine Sukkubus beschwören?",a="Carendin Halgar überwacht die Entwicklung der Hexenmeister innerhalb der Unterstadt. Eine Sukkubus ist ein Wesen der Täuschung, Versuchung und Bosheit – ein mächtiges Werkzeug, um den Willen von Feinden zu brechen und Begierden in tödliche Schwächen zu verwandeln. Carendin leitet Euch durch das Ritual, damit Ihr den Dämon direkt an Euren Befehl binden könnt, was das dunkle Arsenal der Verlassenen erweitert und gleichzeitig Eure Meisterschaft über den Nether beweist.",al={"beweggrund von carendin halgar","warum succubus beschwören durch carendin","ziel von carendin bei devourer of souls"}},["2acf7f0a"]={q="Warum schickt Euch Carendin, anstatt das selbst zu erledigen?",a="Dämonische Versklavung kann nicht im Auftrag eines anderen Zauberwirkers durchgeführt werden. Eine Sukkubus antwortet nur auf den Willen, der sie direkt anlockt, bindet und beherrscht. Als Mentor leitet Carendin Halgar Eure Studien und stellt das grundlegende Wissen des Rituals zur Verfügung, aber Ihr allein müsst den Köder beschaffen, dem Dämon entgegentreten und absolute Kontrolle über seine Seele ausüben.",al={"warum benötigt mich carendin","warum ich bei devourer of souls","warum hexenmeister-spieler succubus"}}},fp="17,193,18.302.0,19.334.0,34.160.0,52.226.0,22.234.0,30.123.0,35.167.0,35.207.0"}
P.entries["quest:1473"] = {n="Kreatur der Leere",s="In Unterstadt suchen Hexenmeister der Verlassenen den Zauberfolianten, den sie zur Beschwörung eines Leerwandlers brauchen. Sie müssen Egalins Zauberfoliant vom Scharlachroten Kreuzzug im Westen von Tirisfal zurückholen, um zu lernen, wie sie einen beschwören und binden.",h="In Unterstadt suchen Hexenmeister der Verlassenen den Zauberfolianten, den sie zur Beschwörung eines...",kw={"carendin halgar","egalin","egalins zauberfoliant","perrine","scharlachroter kreuzzug","temple of the damned","tirisfal","unterstadt","leerwandler"},ang={["class:Warlock"]="Als Hexenmeister lasst Ihr das Herumexperimentieren mit Wichteln hinter Euch und lernt, mächtige Schattenwesen für die vorderste Front zu beherrschen, die gewaltigen körperlichen Schaden aushalten.",["faction:Horde"]="Als Mitglied der Horde lernt Ihr, wie die dunklen Künste Unterstadts durch strenge Gelehrsamkeit gefährliche Kräfte anderer Ebenen zu verlässlichen Mitteln in den Grenzkriegen der Horde machen.",["race:Undead"]="Als Untoter greift Ihr den Scharlachroten Kreuzzug an, um dunkles Wissen zurückzuerlangen, und vertieft den erbitterten Kampf zwischen den Verlassenen und den lebenden Eiferern, die Lordaerons Ruinen besetzen."},sec={{t="Das Vermächtnis eines Lehrers",b="Carendin Halgar unterweist Beschwörer der Verlassenen im Temple of the Damned. Wenn ein Akolyt mehr als die Macht unbedeutender Wichtel beherrschen kann, weist Halgar ihm den Weg zu einem Leerwandler. Die Kreatur ist aus reinem Schatten und Chaos geschmiedet. Hexenmeister der Verlassenen verlassen sich auf die sorgfältigen Forschungen von Egalin, Halgars früherem Meister, der die Rituale zur Unterwerfung solcher Wesen niederschrieb."},{t="Der gestohlene Zauberfoliant",b="Egalins Zauberfoliant enthält die Methoden zur Kanalisierung der unbeständigen Magie, die zur Beherrschung eines Leerwandlers nötig ist. Perrine, ein Eiferer des Scharlachroten Kreuzzugs, stahl das Buch und bewahrt es in einem Außenpostenturm im Westen auf. Der Kreuzzug betrachtet es womöglich nur als blasphemische Schmuggelware, die es zu beschlagnahmen und zu horten gilt. Seine Rückgewinnung verschafft den Verlassenen die nötigen Ritualgeheimnisse, bevor sie versuchen, den Schleier aufzureißen."}},faq={{q="Was ist Egalins Zauberfoliant?",a="Egalins Zauberfoliant ist ein magisches Handbuch, verfasst von Egalin, dem Lehrer von Carendin Halgar. Es beschreibt die Kanalisierungstechniken und Zauber, die nötig sind, um die Leere aufzubrechen und einen Leerwandler unter der Kontrolle des Zaubernden zu beschwören.",al={"egalins zauberfoliant","was ist das buch","wer war egalin"}},{q="Warum hat der Scharlachrote Kreuzzug das Buch gestohlen?",a="Der Scharlachrote Kreuzzug betrachtet dämonische Magie und Shadow Magic als verderbt. Perrine beschlagnahmte den Zauberfolianten und versteckte ihn in einem westlichen Wachturm in Tirisfal, offenbar ohne sich der darin enthaltenen Beschwörungsmacht bewusst zu sein.",al={"warum nahm der scharlachrote kreuzzug es","perrine zauberfoliant","scharlachroter turm im westen"}},{q="Wer ist Carendin Halgar?",a="Carendin Halgar ist ein meisterlicher Hexenmeisterlehrer im Temple of the Damned in Unterstadt. Er unterweist unerfahrene Hexenmeister der Verlassenen und lehrt Respekt vor unbeständigen kosmischen Kräften, wobei ihn seine eigenen früheren Beschwörungsfehler zur Vorsicht mahnen.",al={"carendin halgar","hexenmeisterlehrer unterstadt","temple of the damned lehrer"}},{q="Was geschieht, wenn ein Hexenmeister die Kontrolle über einen Leerwandler verliert?",a="Leerwandler sind Wesen aus reinem Chaos und Schatten. Carendin Halgar warnt, dass ein beschworener Leerwandler seinen Beschwörer ohne vollkommene Disziplin und einen bindenden Willen gewaltsam zerreißen wird.",al={"kann ein leerwandler seinen beschwörer töten","leerwandler gefahr","fehlgeschlagene beschwörung"}},{q="Was folgt nach der Rückgewinnung des Zauberfolianten?",a="Sobald Halgar das Buch hat, studiert er es und lehrt Euch die Ritualrunen. Dann betretet Ihr Binding, wo Ihr mithilfe des Beschwörungskreises einen Leerwandler herbeiruft und ihn im Zweikampf besiegt, um Eure Vorherrschaft zu begründen.",al={"was folgt nach dem zauberfolianten","nächste quest","bindungsritual"}},{q="Wo liegt der Außenposten des Scharlachroten Kreuzzugs?",a="Der Außenposten des Scharlachroten Kreuzzugs ist ein Wachturm im Westen von Tirisfal. Kreuzfahrer unter Perrine bewachen ihn, und der Zauberfoliant ist darin versteckt.",al={"wo ist perrine","scharlachroter turm standort","wo ist das buch"}}},fx={["4bce35a3"]={q="Warum möchte Carendin Halgar, dass dies erledigt wird?",a="Carendin Halgar erkennt Eure wachsende Stärke und hält Euch bereit, einen Leerwandler zu binden. Diese gefährliche Kunst erfordert die präzisen Rituale, die von seinem eigenen Mentor Egalin aufgezeichnet wurden. Neben Eurer Ausbildung kann Halgar nicht zulassen, dass solch dunkles, mächtiges Wissen in den Händen der The Scarlet Crusade verbleibt, deren Fanatiker den gestohlenen Text gerne benutzen oder zerstören würden.",al={"beweggrund von halgar","grund für bergung des zauberfoliants","warum benötigt halgar das buch"}},b85cee29={q="Wer hat Egalins Zauberfoliant?",a="Ein Agent der The Scarlet Crusade namens Perrine hat den Folianten gestohlen und hält ihn in einem Außenposten der Scharlachroten im Westen versteckt. Während Perrine wahrscheinlich nichts von der wahren dämonologischen Macht weiß, die in seinen muffigen Seiten enthalten ist, unterhalten die Eiferer dort eine ständige Präsenz, um die Unterstadt zu überwachen und anzugreifen.",al={"wer stahl den zauberfoliant","wer besitzt egalins zauberfoliant","ziel der scharlachroten kreuzzügler"}},["9e338ab7"]={q="Warum schickt Euch Carendin Halgar, anstatt selbst zu gehen?",a="Halgar dient als Meisterbeschwörer im Temple of the Damned, leitet angehende Hexenmeister an und überwacht das dunkle Handwerk der Verlassenen. Noch wichtiger ist, dass die Wiederbeschaffung des Folianten eine entscheidende Prüfung Eures Einfallsreichtums und Eurer Entschlossenheit ist. Ein Hexenmeister, der seine eigenen Werkzeuge nicht von eifrigen sterblichen Kreuzfahrern zurückfordern kann, wird sicherlich scheitern, wenn er versucht, ein chaotisches Wesen zu beherrschen, das aus dem Nether gerissen wurde.",al={"warum die entsendung meiner person","warum kann halgar das buch nicht selbst beschaffen","warum benötigt mich halgar"}}},fp="20,209,18.354.0,19.374.0,26.211.0,43.197.0,23.226.0,56.183.0,41.217.1,45.141.0"}
P.entries["quest:1474"] = {n="Die Bindung",s="In Unterstadt prüft Carendin Halgar, ob ein Initiand einen Sukkubus beherrschen kann. Reine Herzen locken den Dämon aus dem Wirbelnden Nether in einen Ritualkreis, wo der Hexenmeister ihn im Kampf unterwerfen muss.",h="In Unterstadt prüft Carendin Halgar, ob ein Initiand einen Sukkubus beherrschen kann.",kw={"bindung","carendin halgar","magieviertel","reine herzen","sukkubus","unterstadt","hexenmeister"},ang={["class:Warlock"]="Für Euch als Hexenmeister ist dieser Ritus ein schwieriger Schritt auf Eurem dunklen Pfad. Er prüft Eure Macht, verführerische geistige Kräfte zu beherrschen und gerissene Dämonen aus dem Nether Eurem Willen zu unterwerfen.",["race:Undead"]="Als Verlassene setzt Ihr alle dunklen Mittel ein, die nötig sind, um Überleben und Herrschaft in Lordaeron zu sichern. Dämonen zu unterwerfen, ist ein praktisches Mittel zu diesen Zwecken."},sec={{t="Eine Willensprüfung",b="Im Magieviertel von Unterstadt lernen Hexenmeister der Verlassenen, Dämonen zu befehligen. Einen Sukkubus zu beschwören, ist ein schwieriger Schritt in dieser Ausbildung. Ein Leerwandler verlässt sich auf rohe Gewalt, ein Wichtel auf geringere Bosheit. Ein Sukkubus kann verführerische und geistige Verzauberungen gegen seinen Beschwörer wenden. Deshalb verlangt Carendin Halgar von jedem Initianden den Beweis, dass Geist und Magie unerschütterlich sind, bevor er ihm dauerhafte Herrschaft über einen solchen Dämon gewährt."},{t="Unterwerfung im Kreis",b="Reine Herzen, die von unschuldigen Seelen im Sumpfland und im Silberwald gesammelt wurden, öffnen einen Weg in den Wirbelnden Nether. Der Sukkubus erscheint im Bindungskreis und greift sofort an, um den Hexenmeister zu überwältigen oder zu betören. Um die Herrschaft zu erringen und ihn nach Belieben beschwören zu können, muss der Hexenmeister seine körperliche Gestalt zerschmettern und seine Essenz in die Leere zurückbannen."}},faq={{q="Welchen Zweck hat diese Quest?",a="Der Ritus prüft, ob Hexenmeister der Verlassenen einen Sukkubus beherrschen können. Indem ein Hexenmeister im Magieviertel einen beschwört und besiegt, beweist er, dass dessen Verzauberungen ihn nicht beeinflussen können, und erlangt die Macht, einen im Kampf zu beschwören und zu befehligen.",al={"warum die bindung abschließen","welche belohnung gibt die bindung","wozu dient diese quest"}},{q="Wer ist Carendin Halgar?",a="Carendin Halgar bildet Hexenmeister im Magieviertel von Unterstadt aus und beaufsichtigt die Ausbildung und Prüfungen der Zauberwirker der Verlassenen. Er prüft ihre geistige Ausdauer und ihre dunklen Künste, bevor er ihnen gefährlichere Beschwörungsriten anvertraut.",al={"wer vergibt die bindung","carendin halgar hintergrund"}},{q="Warum wurden reine Herzen benötigt, um den Dämon zu beschwören?",a="Die zuvor gesammelten Reinen Herzen locken einen Sukkubus durch den Beschwörungskreis. Sie dienen als unwiderstehlicher Köder, der den Dämon in die Welt der Sterblichen bringt.",al={"warum reine herzen","hearts of the pure zweck"}},{q="Wo findet die Beschwörung statt?",a="Die Beschwörung findet in einem Ritualkreis im Magieviertel von Unterstadt statt, nahe Carendin Halgar und den Hexenmeisterlehrern.",al={"wo den sukkubus beschwören","beschwörungskreis in unterstadt fundort"}},{q="Warum muss der Sukkubus getötet werden?",a="Der Hexenmeister muss den Sukkubus töten, um ihn zu unterwerfen. Seine Gestalt im Kreis zu zerschmettern, zwingt seinen Geist unter den Willen des Hexenmeisters, sodass er als Diener statt als Herr zurückkehrt.",al={"warum gegen den sukkubus kämpfen","warum den beschworenen sukkubus töten"}},{q="Sind Sukkubi für die Hexenmeister von Unterstadt gefährlich?",a="Ja. Die Verzauberungen eines Sukkubus haben schon viele starke Geister gebunden, trotz der Widerstandskraft der Verlassenen gegen Furcht und Schlaf. Unachtsamkeit beim Ritual kann Tod oder Versklavung bringen.",al={"kann ein sukkubus untote betören","gefahr durch sukkubi"}}},fx={c35097a2={q="Was ist die beschworene Sukkubus und warum ist sie hier?",a="Ihr beschwört eine Sukkubus durch die Leere direkt in den Beschwörungskreis im Magieviertel. Sukkubi sind gerissene Dämonen, die darin geübt sind, sterbliche Geister zu betören, was sie zu einer der gefährlichsten Dienerinnen macht, die ein Hexenmeister binden kann. Dieser besondere Teufel wohnt hier nicht von Natur aus; er wird nur durch die Reinen Herzen, die Ihr gesammelt habt, in unsere Welt gezogen, speziell damit Ihr seinen Willen im Kampf brechen könnt.",al={"wer ist die beschworene succubus","gegen was kämpfe ich","ziel der succubus"}},["8c406b80"]={q="Warum müsst Ihr die Sukkubus selbst beschwören und besiegen?",a="Dämonische Unterwerfung ist eine persönliche Prüfung, die nicht delegiert werden kann. Carendin Halgar dient als Mentor, aber die dämonische Bindung erfordert den eigenen Verstand und die Magie des Beschwörers, um die Verteidigung des Wesens zu durchbrechen. Wenn Halgar oder die Stadtwachen eingreifen würden, um die Sukkubus für Euch zu unterwerfen, würde sich der Dämon niemals Eurem Befehl beugen, und Eure Autorität als Hexenmeister bliebe unvollständig.",al={"warum kann carendin die succubus nicht bekämpfen","warum benötigt mich carendin","warum ich bei succubus"}}},fp="11,210,14.407.0,25.345.1,34.218.0,23.227.0,48.151.0,36.124.0,39.173.0,44.171.0"}
P.entries["quest:1476"] = {n="Herzen der Reinen",s="In Unterstadt stellt Godrick Farsan Euch eine Prüfung für Carendin Halgars Bindung einer Sukkubus. Ihr sucht zwei rechtschaffene Menschenmänner, deren reine Herzen einen Dämon verlocken sollen.",h="In Unterstadt stellt Godrick Farsan Euch eine Prüfung für Carendin Halgars Bindung einer Sukkubus.",kw={"carendin halgar","comar villard","dalin forgewright","godrick farsan","der greymane-wall","herzen der reinen","sukkubus","tempel der verdammten","thandol-übergang","unterstadt"},ang={["class:Warlock"]="Als Hexenmeister lernt Ihr, neben Elend und Furcht auch den Edelmut anderer zu nutzen, um Dämonen Eurem Willen zu unterwerfen.",["faction:Alliance"]="Als Mitglied der Allianz kennt Ihr die Opfer als tragische menschliche Gestalten: Einer bewacht Flüchtlinge, die Gilneas ausgesperrt hat, während der andere die Sumpfgebiete nach seiner verschollenen Frau absucht.",["race:Undead"]="Als Untoter erlebt Ihr die erschreckende Sicht der Verlassenen, die Lordaerons Überlebende und ihre Tugenden als geeignetes Material für rituelles Abschlachten betrachten."},sec={{t="Köder für einen Dämon",b="Carendin Halgar, Meisterbeschwörer im Tempel der Verdammten, überträgt Godrick Farsan die Vorarbeit für die Bindung einer Sukkubus. Sukkubi zehren von Begierde und Verderben. Doch unbefleckte Tugend lockt sie aus dem Wirbelnden Nether, wo sie reif für die Verderbnis sind. Also durchsucht Godrick die Länder der Menschen nach Seelen, deren Güte makellos und ungebrochen geblieben ist."},{t="Die Beute",b="Godrick Farsan nennt zwei Männer, deren Tugend sie zu Opfern bestimmt. Dalin Forgewright kümmert sich um verzweifelte Flüchtlinge aus Lordaeron, denen vor dem versiegelten Greymane-Wall im südlichen Silberwald die Zuflucht verwehrt bleibt. Comar Villard durchsucht unermüdlich die gefährlichen Sumpfgebiete des Sumpflands nach jeder Spur seiner verschollenen Frau. Ihre Hingabe, ihr Mitgefühl und ihre Treue machen sie zu erstklassigen Opfern für einen Hexenmeister der Verlassenen."},{t="Aus Sicht der Verlassenen",b="Ihr jagt beide Männer durch gefährliche, von der Allianz gehaltene Gebiete und durch die Wildnis, dann schlachtet Ihr sie ab. Als Ihr ihre blutigen Herzen in den Tempel der Verdammten zurückbringt, bemerkt Carendin Halgar, dass das Herz eines guten Mannes nicht anders aussieht als die Überreste jeder anderen Leiche. Doch die geistige Reinheit, die ihrem Fleisch anhaftet, ist ein mächtiger Köder, stark genug, um eine Sukkubus in die Gefangenschaft zu locken."}},faq={{q="Warum brauchen Hexenmeister reine Herzen, um eine Sukkubus zu beschwören?",a="Sukkubi fühlen sich von der Unschuld und Tugend Sterblicher angezogen, die sie verderben wollen. Carendin Halgar nutzt die Herzen wahrhaft reiner und selbstloser Männer als unwiderstehlichen geistigen Köder, um eine Sukkubus durch den Nether zu locken und in einem Bindungskreis zu fangen.",al={"warum reine herzen","hintergrund zum sukkubusköder","warum dalin und comar töten"}},{q="Wer ist Dalin Forgewright?",a="Dalin Forgewright ist ein ehrenhafter Mensch, der zu Pferde an den geschlossenen Toren des Greymane-Walls im südlichen Silberwald patrouilliert. Er widmet sein Leben der Fürsorge und dem Schutz von Flüchtlingen aus Lordaeron, die Gilneas abgewiesen und ausgesperrt hat.",al={"dalin forgewright hintergrund","wer ist dalin","mann am greymane-wall"}},{q="Wer ist Comar Villard?",a="Comar Villard ist ein hingebungsvoller Mensch, der die nördliche Straße des Sumpflands unmittelbar südlich des Thandol-Übergangs absucht. Trauer und unerschütterliche Liebe treiben ihn an, weiter nach jeder Spur seiner vermissten Frau zu suchen.",al={"comar villard hintergrund","wer ist comar","menschenherz im sumpfland"}},{q="Wohin führt diese Questreihe?",a="Wenn Ihr Carendin Halgar die beiden Herzen überbringt, kann er den Beschwörungskreis im Tempel der Verdammten vorbereiten. Dort beschwört und unterwerft Ihr eine Sukkubus, die Euch fortan als dauerhafte Dienerin dient.",al={"what comes next","nach herzen der reinen","sukkubus questbelohnung"}},{q="Wer vergibt diese Quest?",a="Godrick Farsan, ein Gehilfe im Tempel der Verdammten im Magieviertel von Unterstadt, erteilt den Auftrag im Namen von Carendin Halgar. Er projiziert magische Illusionen von Dalin und Comar, um Euch zu zeigen, wen Ihr jagen sollt.",al={"wer startet herzen der reinen","godrick farsan quest"}},{q="Warum tut Carendin Halgar das Aussehen der Herzen ab?",a="Carendin Halgar sagt, das Herz eines guten Mannes sehe jedem anderen Stück Fleisch sehr ähnlich. Als untoter Praktiker der dunklen Künste interessiert ihn sein Nutzen als magisches Reagenz, nicht seine körperliche Moral.",al={"carendin dialog","aussehen der herzen"}}},fx={["4332c870"]={q="Warum will Godrick Farsan, dass diese Herzen gesammelt werden?",a="Godrick unterstützt Carendin Halgar bei der Ausbildung würdiger Hexenmeister der Verlassenen. Um eine Sukkubus zu beschwören und zu beherrschen, benötigt Halgar seltene Leitungen – insbesondere die Herzen wahrhaft reiner, edler Menschen, deren Tugenden einen Dämon der Versuchung in einen Bindungskreis locken können. Godrick hat geeignete Ziele ausfindig gemacht, damit Ihr deren Herzen ernten und Eure dunklen Künste beweisen könnt.",al={"warum braucht godrick herzen","godrick farsan motiv","warum reine herzen sammeln"}}},fp="18,158,16.336.0,10.395.0,22.367.1,54.239.0,25.241.0,21.191.0,33.188.1,21.219.0,62.196.0"}
P.entries["quest:1478"] = {n="Halgars Beschwörung",s="In Unterstadt ruft Halgars Beschwörung vielversprechende Hexenmeister der Verlassenen zur weiterführenden Ausbildung. Carendin Halgar erwartet jene, die die ersten Teufelskünste gemeistert haben, im Magieviertel, wo gefährliche Wesen aus dem Nether ihr Können prüfen.",h="In Unterstadt ruft Halgars Beschwörung vielversprechende Hexenmeister der Verlassenen zur weiterführenden...",kw={"ageron kargal","carendin halgar","halgars beschwörung","magieviertel","temple of the damned","unterstadt","voidwalker","hexenmeister"},ang={["class:Warlock"]="Als Hexenmeister lasst Ihr die Grundausbildung hinter Euch und stellt Euch unter Unterstadts führendem Meister der dunklen Künste der Versklavung von Wesen anderer Ebenen.",["race:Undead"]="Als Verlassene verfolgt Ihr Schatten und Teufelsmagie mit rücksichtslosem Ehrgeiz. Halgars Heiligtum spiegelt wider, wie pragmatisch Euer Volk die Vorsicht der Lebenden missachtet."},sec={{t="Die Nachricht eines Meisters",b="Die Beherrschung grundlegender Teufelsenergien durch einen Hexenmeister erregt in Brill oder der Wildnis von Tirisfal Aufmerksamkeit. Ageron Kargal, ein erfahrener Praktizierender mit einem Gespür für Talent, lässt jenen eine Nachricht zukommen, die vielversprechend erscheinen. Carendin Halgars Ruf ist ein seltenes Privileg und ein gefährlicher Schritt in der Ausbildung eines Hexenmeisters. Einfache Wichtel und geringfügige Flüche genügen nicht länger."},{t="Das Magieviertel",b="Carendin Halgar beaufsichtigt die Riten der Hexenmeister im Magieviertel von Unterstadt, nahe dem Temple of the Damned. Den Dunkelwirkern der Verlassenen fehlen die moralischen Schranken der Lebenden, doch Beschwörungen über die Grenzen der Ebenen hinweg erfordern dennoch Disziplin. Halgar duldet weder Zögern noch Sentimentalität. Von jenen, die er zu sich ruft, erwartet er Ehrerbietung und die Bereitschaft, sich den feindseligen Schrecken des Wirbelnden Nethers zu stellen."}},faq={{q="Wer ist Carendin Halgar?",a="Carendin Halgar ist der oberste Hexenmeisterlehrer von Unterstadt und befindet sich im Magieviertel. Er unterweist Beschwörer der Verlassenen in den dunklen Künsten und prüft ihre Entschlossenheit, bevor er sie lehrt, mächtige Netherkreaturen zu binden.",al={"carendin halgar","meister halgar","wer ist halgar"}},{q="Wer schickt mich zu Halgar?",a="Ageron Kargal, ein erfahrener Hexenmeisterlehrer in Brill, schickt Euch zu Halgar, nachdem er erfahren hat, dass der Meister persönlich an Euren Fortschritten interessiert ist.",al={"wer vergibt halgars beschwörung","ageron kargal","wer vergibt die quest"}},{q="Wo finde ich Carendin Halgar in Unterstadt?",a="Carendin Halgar befindet sich im Magieviertel von Unterstadt, nahe dem Temple of the Damned.",al={"halgars standort","wo ist halgar","magieviertel halgar"}},{q="Warum ist diese Vorladung wichtig?",a="Die Vorladung markiert Euren Übergang von grundlegender Zauberei zur gefährlichen Unterwerfung von Dämonen. Sie leitet die Prüfungen ein, die nötig sind, um einen Voidwalker an Euren Dienst zu binden.",al={"warum ist diese quest nötig","zweck der quest","wozu führt halgars beschwörung"}},{q="Ist Halgar bereit, jeden zu unterrichten?",a="Halgar widmet seine Aufmerksamkeit vielversprechenden Hexenmeistern. Er hat wenig Geduld für leere Höflichkeiten und erwartet von jedem Lehrling, der vor ihn tritt, bewiesenes Können im Umgang mit unberechenbaren Teufelskünsten.",al={"kann jeder mit halgar sprechen","halgar voraussetzungen"}},{q="Was geschieht, nachdem ich mich bei Halgar gemeldet habe?",a="Wenn Ihr Euch bei Halgar meldet, prüft er Eure Magie, indem er Euch die nötigen Komponenten zur Beschwörung und Bindung eines außerweltlichen Schattendieners sammeln lässt.",al={"what comes next","nach halgars beschwörung"}}},fx={["169af240"]={q="Warum schickt Euch Ageron Kargal zu Carendin Halgar?",a="Ageron Kargal dient als Hexenmeister-Mentor in Brill, aber Eure wachsende Meisterschaft erfordert eine fortgeschrittene Unterweisung, die über das hinausgeht, was ein Dorf-Tutor bieten kann. Als die Nachricht von Meister Carendin Halgar persönlich eintrifft, die Eure Anwesenheit anfordert, weist Euch Ageron pflichtbewusst in die Unterstadt. Für Ageron stärkt die Förderung vielversprechender Hexenmeister die dunklen Künste der Verlassenen und ehrt die Hierarchie unter den Praktizierenden im Magieviertel.",al={"ageron kargal motiv","warum zu halgar schicken","warum will ageron das"}},be0d43df={q="Warum beschwört Carendin Halgar ausgerechnet Euch?",a="Carendin Halgar wendet sich selten an einen beliebigen Novizen, um ihn zu unterweisen. Nachdem Ihr Eure Affinität für die dunklen Künste in Tirisfal bewiesen habt, habt Ihr eine kritische Schwelle in Eurem Handwerk erreicht, an der grundlegende Zauber nicht mehr ausreichen. Halgar beschwört Euch direkt, weil das Freischalten tieferer und flüchtigerer Kräfte – wie etwa in den Nether zu greifen, um größere Unholde zu befehligen – eine persönliche Aufsicht durch einen wahren Meister dieses Handwerks erfordert.",al={"warum braucht halgar mich","warum beschwört mich halgar","warum werde ich beschworen"}}},fp="16,231,17.327.0,17.373.0,23.201.0,25.150.0,46.79.0,30.155.0,34.189.0,39.143.0"}
P.entries["quest:148"] = {n="Lieferung aus Dunkelhain",s="Calvinius im westlichen Dämmerwald bittet Euch, einen seltenen Faden aus Dunkelhain zu holen. Er sagt, er sei zu gebrechlich, um den verwunschenen Wald zu durchqueren, und bittet um Geisterhaarfaden von Madame Eva.",h="Calvinius im westlichen Dämmerwald bittet Euch, einen seltenen Faden aus Dunkelhain zu holen.",kw={"calvinius","dunkelhain","dämmerwald","geisterhaarfaden","madame eva","lieferung aus dunkelhain","the hermit"},ang={["faction:Alliance"]="Als Abenteurer der Allianz könnt Ihr auf den gefährlichen Nebenwegen rund um Dunkelhain Nachrichten und Waren für Eremiten befördern.",["profession:Tailoring"]="Als Schneider wisst Ihr, dass für gewebte Gegenstände meist Leinen oder Seide verwendet wird. Madame Evas Arbeit, ätherisches Haar zu Faden zu spinnen, ist eine makabre Kuriosität."},sec={{t="Eine gebrechliche Bitte",b="Nördlich des Friedhofs von Rabenflucht findet Ihr Calvinius allein in einer Hütte im westlichen Dämmerwald. Alter und Gebrechlichkeit hindern ihn daran, die gefährliche Reise durch den Wald anzutreten, um Waren in Dunkelhain zu kaufen. Also bittet er Euch, zum Stadtplatz der Gemeinde zu gehen und Madame Eva um eine Spule Geisterhaarfaden zu bitten."},{t="Ein seltsames Material",b="In Dunkelhain hat Madame Eva keinen Geisterhaarfaden vorrätig. Die örtliche Wahrsagerin spinnt seltsame Artefakte, und dieser Faden ist kein gewöhnliches Nähzubehör. Um ihn herzustellen, braucht sie Geisterhaar von der blinden Mary, einem kummervollen Geist, der ein Bauernhaus südlich von Dunkelhain heimsucht. Also müsst Ihr zuerst beschaffen, was Madame Eva braucht."}},faq={{q="Wer vergibt die Quest „Lieferung aus Dunkelhain“?",a="Calvinius, ein Eremit in einer Hütte nördlich des Friedhofs von Rabenflucht im westlichen Dämmerwald, bittet Euch um Hilfe.",al={"questgeber lieferung aus dunkelhain","wer vergibt lieferung aus dunkelhain","calvinius botengang"}},{q="Mit wem muss ich in Dunkelhain sprechen, um die Vorräte zu erhalten?",a="Sprecht mit Madame Eva, die in einem Haus mit Blick auf Dunkelhains zentralen Platz wohnt.",al={"wo lieferung aus dunkelhain abgeben","lieferung aus dunkelhain abgeben","madame eva standort"}},{q="Welchen Gegenstand sucht Calvinius genau?",a="Calvinius bittet um Geisterhaarfaden, ein ungewöhnliches Material, das Madame Eva webt.",al={"was will calvinius","was sind die vorräte","calvinius gegenstand"}},{q="Hat Madame Eva den Geisterhaarfaden vorrätig?",a="Nein. Madame Eva hat keinen vorrätig, wenn Ihr ankommt. Sie erklärt sich bereit, ihn zu spinnen, wenn Ihr die benötigten geisterhaften Materialien von Geistern in der Nähe beschafft.",al={"hat eva faden","lieferung aus dunkelhain abschließen"}},{q="Welche Quest geht „Lieferung aus Dunkelhain“ voraus?",a="„The Hermit“ schickt Reisende aus Dunkelhain zu Calvinius in seiner Behausung.",al={"voraussetzung lieferung aus dunkelhain","lieferung aus dunkelhain vorquest"}},{q="Welche Quest folgt auf „Lieferung aus Dunkelhain“?",a="Das Gespräch mit Madame Eva führt direkt zu „Geisterhaarfaden“. Ihr werdet gebeten, der blinden Mary einen Spektralen Kamm zu bringen und ihr Haar zu sammeln.",al={"nächste quest nach lieferung aus dunkelhain","lieferung aus dunkelhain folgequest"}}},fx={b4c47635={q="Warum benötigt Calvinius Vorräte aus Dunkelhain?",a="Calvinius behauptet, er sei lediglich ein verarmter, gebrechlicher alter Mann, der in der gefährlichen Wildnis des Dämmerwalds lebt und nicht in der Lage ist, die lange und gefahrvolle Reise in die Stadt zu unternehmen. Er bittet speziell um Geisterhaarfaden, angeblich weil er alltägliche Schneidereibedarfsartikel von Madame Eva benötigt, um sein einsames Leben in den Wäldern zu bestreiten.",al={"warum vorräte aus dunkelhain","warum braucht abercrombie faden","abercrombie geisterhaarfaden"}},["2d5a916c"]={q="Warum bittet Calvinius Euch, anstatt den Faden selbst zu holen?",a="Calvinius beteuert, dass er viel zu alt, schwach und körperlich gebrechlich sei, um den heimgesuchten, von Bestien wimmelnden Pfaden zwischen seiner Hütte und Dunkelhain zu trotzen. Ein körperlich leistungsfähiger Reisender, der die schattenhafte Wildnis in seinem Namen durchquert, ist seine einzige offensichtliche Möglichkeit, die Materialien zu erhalten, die er sich von Madame Eva wünscht.",al={"warum kann abercrombie nicht in die stadt","warum ich vorräte aus dunkelhain","warum besorgt abercrombie die vorräte nicht"}}},fp="23,178,16.303.0,18.303.1,45.102.0,53.83.0,46.78.0,49.136.0,44.78.0,43.135.0"}
P.entries["quest:1480"] = {n="Der Verderber",s="In der Festung Donneraxt trägt ein geschundener Hautstreifen der Burning Blade rote Zeichen und ein Symbol, das einer Unterschrift ähnelt. Er riecht nach Fäulnis, lässt sich aber leicht biegen. Maurin Knochenspalter am Geistwandlerposten weiß vielleicht mehr.",h="In der Festung Donneraxt trägt ein geschundener Hautstreifen der Burning Blade rote Zeichen und ein Symbol...",kw={"burning blade","eredun","geschundene dämonenhaut","geistwandlerposten","lord azrethoc","maurin knochenspalter","der verderber","festung donneraxt"},sec={{t="Ein Streifen Haut",b="Die geschundene Haut riecht nach Fäulnis, lässt sich aber leicht biegen, obwohl sie sich trocken und brüchig anfühlt. Ausgerollt zeigt sie auf einer Seite rote Zeichen, geschrieben in irgendeiner Sprache. Ein schlichtes Symbol am unteren Ende sieht wie eine Unterschrift aus."},{t="Maurins Sicht",b="Maurin Knochenspalter am Geistwandlerposten weiß vielleicht mehr über die Haut. Maurin glaubt, dass die Burning Blade allmählich erkennen, wie schwach sie sind. Ihre Magie ist dürftig und ihre Stärke gering. Welche Macht sie auch besitzen, sie stammt von jenen, denen sie dienen, nicht aus einem Verständnis wahrer Macht oder wahren Wissens."},{t="Die Bedeutung der Zeichen",b="Maurin erkennt die Runen als eine alte Sprache, die Eredun etwas ähnelt, sich aber in ihren Einzelheiten stark davon unterscheidet. Wenn Maurin recht hat, ist die Haut eine Art Vertrag. Das Symbol am unteren Ende ist die Unterschrift eines Dämons namens Lord Azrethoc."}},faq={{q="Was steht auf der geschundenen Haut?",a="Rote Zeichen in irgendeiner Schriftsprache bedecken eine Seite der geschundenen Haut. Am unteren Ende sieht ein deutliches Symbol wie eine Unterschrift aus. Maurin Knochenspalter am Geistwandlerposten weiß vielleicht mehr.",al={"runen auf geschundener haut","was steht auf der haut","rote zeichen auf haut"}},{q="Woher stammt die Haut?",a="Die Haut wurde den Burning Blade in der Festung Donneraxt in Desolace abgenommen.",al={"fundort der haut","woher dämonenhaut bekommen","wie der verderber beginnen"}},{q="Wer ist Maurin Knochenspalter?",a="Maurin Knochenspalter befindet sich am Geistwandlerposten in Desolace, wohin die Haut gebracht wird.",al={"wo ist maurin","maurin knochenspalter standort","wer ist maurin"}},{q="Was hält Maurin von den Burning Blade?",a="Maurin hält die Burning Blade für schwach, mit dürftiger Magie und wenig Kraft. Maurin glaubt, dass jegliche Macht, die sie besitzen, von jenen stammt, denen sie dienen.",al={"maurin burning blade","macht der burning blade"}}},fp="13,202,15.210.0,13.289.0,22.230.1,35.190.0,30.78.0,27.83.0,44.145.0"}
P.entries["quest:1481"] = {n="Der Verderber",s="Maurin Knochenspalter sucht nach einem Weg, den Verderber zu finden, doch dessen Schutzzauber könnten Hellsicht vereiteln. Er braucht den Skalp eines Hatefury shadowstalker aus den alten Ruinen im Nordosten von Desolace, nahe Sargeron.",h="Maurin Knochenspalter sucht nach einem Weg, den Verderber zu finden, doch dessen Schutzzauber könnten...",kw={"desolace","hatefury shadowstalker","maurin knochenspalter","sargeron","satyr","hellsicht","skalp eines shadowstalker","der verderber"},sec={{t="Die Schutzzauber brechen",b="Maurin Knochenspalter glaubt, dass die richtigen Reagenzien den Dämonenfürsten sichtbar machen können. Wenn Maurin mit dessen Macht recht hat, müssen diese Reagenzien von tödlichen Kreaturen stammen. Er vertraut darauf, dass Ihr Euch dieser Gefahr im Namen des Kriegshäuptlings stellt.\n\nZuerst müssen die Schutzzauber des Dämonenfürsten gegen Hellsicht gebrochen werden. Maurin bittet Euch um den Skalp eines Satyrs, und nur der eines Hatefury shadowstalker wird genügen. Sucht in den alten Ruinen im Nordosten von Desolace, nahe Sargeron."},{t="Der richtige Skalp",b="Maurin warnt Euch, den richtigen Skalp zurückzubringen. Falsche Reagenzien könnten Menschen das Leben kosten, denn der Dämonenfürst könnte Eventualzauber besitzen, die jeden töten sollen, der ihn mittels Hellsicht aufzuspüren versucht. Das Schicksal habe bereits genug Schmerz verteilt, sagt er."},{t="Bei Eurer Rückkehr",b="Maurin befindet den Skalp für seinen Zauber geeignet. Während Ihr fort wart, hat er einige der anderen benötigten Reagenzien gesammelt und ist beinahe bereit. Es fehlt nur noch ein Fokus, ein Gegenstand, der das Abbild des Dämonenfürsten projiziert und seinen Aufenthaltsort offenbart."}},faq={{q="Wer schickt Euch los, den Skalp zu beschaffen?",a="Maurin Knochenspalter bittet Euch, ihm den Skalp für einen Zauber zu bringen, der den Dämonenfürsten aufspüren soll.",al={"questgeber","wer beginnt dies","maurin knochenspalter"}},{q="Warum braucht Maurin ausgerechnet den Skalp eines Hatefury shadowstalker?",a="Der Dämonenfürst könnte Schutzzauber gegen Hellsicht besitzen, und Maurin braucht den Skalp eines Satyrs, um sie zu brechen. Nur der Skalp eines Hatefury shadowstalker genügt.",al={"warum der skalp eines shadowstalker","grund für satyrskalp","warum ein satyr"}},{q="Wo sind die Hatefury shadowstalker zu finden?",a="Die Hatefury shadowstalker sind in den alten Ruinen im Nordosten von Desolace zu finden, nahe Sargeron.",al={"wo sind shadowstalker","fundort der shadowstalker","fundort der satyrn"}},{q="Welche Gefahren birgt die Verwendung falscher Reagenzien?",a="Maurin warnt, dass falsche Reagenzien Menschen das Leben kosten könnten. Der Dämonenfürst könnte Eventualzauber besitzen, die jeden töten sollen, der ihn mittels Hellsicht aufzuspüren versucht.",al={"warum der richtige skalp","risiko falscher reagenzien","eventualzauber"}},{q="Wo fügt sich dieser Schritt in die Suche nach dem Dämonenfürsten ein?",a="Dieser Schritt folgt auf den ersten Teil von Der Verderber, in dem Ihr Maurin die abgezogene Dämonenhaut gebracht habt.",al={"fortschritt der questreihe","questreihenfolge","was kommt davor"}}},fp="13,193,18.423.0,15.230.0,15.226.1,34.87.0,65.141.0,47.91.0,49.146.0,60.95.0"}
P.entries["quest:1482"] = {n="Der Verderber",s="Maurin Knochenspalter sucht einen Orakelkristall, um den Dämonenfürsten Azrethoc aufzuspüren. Nordwestlich entlang der Küste leben die Slitherblade-Naga in einem riesigen Korallenriff, und sie werden Euer Eindringen übel aufnehmen.",h="Maurin Knochenspalter sucht einen Orakelkristall, um den Dämonenfürsten Azrethoc aufzuspüren.",kw={"azrethoc","verderber","desolace","maurin knochenspalter","naga","orakelkristall","slitherblade","warchief"},sec={{t="Ein Orakelkristall",b="Maurin Knochenspalter braucht einen Orakelkristall, um den Dämonenfürsten Azrethoc aufzuspüren. Die Haut, die Ihr ihm gebracht habt, trug Azrethocs Signatur. Naga stellen diese Kristalle für ihre Orakel her, die in einem riesigen Korallenriff nordwestlich entlang der Küste leben. Die Slitherblade-Naga leben dort nahe der Küste. Sie sind tödlich und werden Euer Eindringen übel aufnehmen, daher drängt Maurin Euch, vorsichtig und rasch vorzugehen."},{t="Ein gemeinsamer Lohn",b="Maurin sagt, Fürst Azrethoc aufzuspüren und zu vernichten würde Euch beiden viel Gunst beim Warchief einbringen. Zusammenzuarbeiten und rasch vorzugehen dient Euren jeweiligen Zielen."}},faq={{q="Warum braucht Maurin Knochenspalter einen Orakelkristall?",a="Damit Maurin Knochenspalter den Dämonenfürsten Azrethoc aufspüren kann.",al={"warum orakelkristall","wozu dient der kristall","maurin kristall zweck"}},{q="Wo sind die Orakelkristalle zu finden?",a="Die Naga stellen Orakelkristalle für ihre Orakel her, die von Maurin aus nordwestlich entlang der Küste in einem riesigen Korallenriff leben.",al={"wo kristall finden","orakelkristall fundort","wo sind die slitherblade-orakel"}},{q="Wer sind die Slitherblade?",a="Die Slitherblade sind Naga, die ein riesiges Korallenriff nahe der Küste ihre Heimat nennen. Maurin nennt sie tödlich und sagt, sie würden Eindringlinge übel aufnehmen.",al={"was sind slitherblade","slitherblade-naga","wer lebt im riff"}},{q="Wer ist Azrethoc?",a="Azrethoc ist der Dämonenfürst, dessen Signatur auf der Haut war, die Ihr Maurin gebracht habt. Maurin will ihn aufspüren und vernichten.",al={"wer ist azrethoc","dämonenfürst azrethoc","welchen dämon jagt maurin"}},{q="Was treibt Maurin an, diesen Dämon zu jagen?",a="Die Gunst des Warchiefs: Maurin sagt, Fürst Azrethoc aufzuspüren und zu vernichten würde Euch beiden viel davon einbringen.",al={"maurins beweggrund","warum azrethoc jagen","gunst des warchiefs"}}},fp="13,194,17.383.0,14.160.0,52.61.0,36.119.0,25.139.0,16.116.0,41.110.0"}
P.entries["quest:1483"] = {n="Ziz Fizziks",s="Auf dem westlichen Grat der Scherwindklippe hat Ziz Fizziks die Venture Company verlassen und sich der Tinkers' Union angeschlossen. Die Ankunft eines Gnomeningenieurs trieb ihn fort, doch sein neuer Vorgesetzter lässt ihn ebenso hart arbeiten.",h="Auf dem westlichen Grat der Scherwindklippe hat Ziz Fizziks die Venture Company verlassen und sich der...",kw={"gerenzo wrenchwhistle","stotterspritter","steinkrallengebirge","tinkers' union","venture company","die scherwindklippe","ziz fizziks"},ang={["faction:Horde"]="Als Abenteurer der Horde im Steinkrallengebirge könnt Ihr Agenten der Tinkers' Union wie Stotterspritter und Ziz helfen, die Vorherrschaft der Venture Company über die Scherwindklippe zu untergraben.",["profession:Engineering"]="Als Ingenieur könnt Ihr die erbitterte Fehde zwischen Ziz und Gerenzo in der langjährigen, explosiven Rivalität zwischen goblinischen und gnomischen Ingenieursphilosophien wiedererkennen."},sec={{t="Eine Frage der Berufsehre",b="Die Venture Company stellte Gerenzo Pfeifzang ein, einen Gnomeningenieur, und Ziz Fizziks empfand das als Beleidigung. Er konnte es nicht ertragen, neben einem gnomischen Rivalen zu arbeiten, und suchte deshalb nach einem Ausweg. Ziz nahm Kontakt zu Stotterspritter auf, einem Vertreter der Tinkers' Union, und flehte um eine Versetzung, um Gerenzos Aufsicht zu entkommen."},{t="Aus der Bratpfanne",b="Die Tinkers' Union gab Ziz Fizziks eine neue Stelle, doch das erhoffte bequeme Leben blieb aus. Am westlichen Rand der Scherwindklippe stellte er fest, dass Stotterspritter ihn ebenso hart antrieb wie jeder Vorarbeiter der Venture Company. Dennoch schuftet Ziz lieber unter einem anspruchsvollen Goblinvorgesetzten, als eine Ingenieurswerkstatt mit einem Gnom zu teilen."}},faq={{q="Wer ist Ziz Fizziks?",a="Ziz Fizziks ist ein Gobliningenieur, der einst für die Venture Company im Steinkrallengebirge arbeitete. Er verließ das Unternehmen, nachdem es einen Gnomeningenieur eingestellt hatte, und schloss sich der Tinkers' Union an.",al={"wer ist ziz","ziz fizziks nsc","über ziz fizziks"}},{q="Warum verließ Ziz Fizziks die Venture Company?",a="Die Venture Company stellte Gerenzo Pfeifzang ein, einen Gnomeningenieur, und Ziz Fizziks weigerte sich, neben ihm zu arbeiten. Ziz flehte Stotterspritter um eine neue Stelle an.",al={"warum hat ziz gekündigt","warum die venture company verlassen","ziz venture company"}},{q="Wo ist Ziz Fizziks zu finden?",a="Ziz Fizziks arbeitet am westlichen Rand der Scherwindklippe im Steinkrallengebirge. Von dort überblickt er die Holzfällarbeiten und Ausgrabungen der Venture Company.",al={"ziz fizziks standort","wo ist ziz","ziz fizziks finden"}},{q="Wer ist Stotterspritter?",a="Stotterspritter ist ein Goblinagent der Tinkers' Union. Er wirbt fähige Ingenieure von der Venture Company ab, damit sie an konkurrierenden Projekten arbeiten.",al={"wer ist stotterspritter","stotterspritters rolle"}},{q="Wer ist Gerenzo Pfeifzang?",a="Gerenzo Pfeifzang ist ein Gnomeningenieur, den die Venture Company für die Arbeit an der Scherwindklippe eingestellt hat. Seine Ankunft empörte Ziz und entfachte eine erbitterte berufliche Rivalität.",al={"gerenzo wrenchwhistle","wer ist der gnomeningenieur"}},{q="Was ist die Tinkers' Union?",a="Die Tinkers' Union ist ein etablierter Berufsverband goblinischer Ingenieure. Sie konkurriert mit der Venture Company und wirbt Spitzenkräfte an oder gewinnt sie zurück.",al={"tinkers' union","goblins tinkers' union"}}},fx={["39c75067"]={q="Warum will Stotterspritter, dass Ihr nach Ziz Fizziks seht?",a="Die Venture Company wirbt routinemäßig die besten Goblin-Talente ab, aber Stotterspritter ergriff die Chance, einen Ingenieur zurückzugewinnen, als Ziz aus Protest gegen die Einstellung eines Gnom-Rivalen kündigte. Nun, da er die Tinkers' Union vertritt, hat Stotterspritter Ziz direkt zur Arbeit an der Scherwindklippe geschickt. Er möchte sicherstellen, dass ihr neu erworbener Tüftler tatsächlich Ergebnisse liefert, anstatt allein in feindlichem Gebiet zu scheitern.",al={"warum nach ziz fizziks sehen","stotterspritter motiv","warum zu ziz schicken"}}},fp="11,194,30.305.0,21.319.0,19.179.0,46.154.0,31.167.0,20.145.0,29.165.0,27.148.0"}
P.entries["quest:1484"] = {n="Der Verderber",s="Nahe Maurin Knochenspalter hat sich der Dämonenlord als gefährlicher erwiesen, als Maurin erwartet hatte. Maurin glaubt, dass Takata Stahlklinge an seinem Können zweifelt und dass es Takata entehren würde, ihm das Geschehene zu verschweigen. Deshalb schickt er Euch zu dem Schwertkämpfer in der Nähe, um mit ihm zu sprechen.",h="Nahe Maurin Knochenspalter hat sich der Dämonenlord als gefährlicher erwiesen, als Maurin erwartet hatte.",kw={"dämonenlord","desolace","der kodofriedhof","maurin knochenspalter","schwertkämpfer","takata stahlklinge","der verderber"},sec={{t="Eine Frage der Ehre",b="Der Dämonenlord hat sich als gefährlicher erwiesen, als Maurin Knochenspalter erwartet hatte. Maurin glaubt, dass Takata Stahlklinge bezweifelt, ob er der Kreatur gewachsen ist, und dass es die Ehre des Schwertkämpfers verletzen würde, ihn im Ungewissen zu lassen.\n\nMaurin bittet Euch, mit Takata zu sprechen und anzubieten, den Dämon zu erschlagen, wenn Takata es gestattet. Er warnt Euch davor, Takata zu sehr zu bedrängen, denn seiner Meinung nach sollte Takata glauben, die Idee stamme von ihm selbst."},{t="Jenseits des Pfades",b="Takata Stahlklinge befindet sich in der Nähe, von Maurin aus auf der anderen Seite des Pfades. Er steht auf einer Klippe mit Blick auf den Kodofriedhof."},{t="Takatas Antwort",b="Takata Stahlklinge wurde Zeuge dessen, was sich zwischen Maurin und dem Dämonenlord abspielte. Obwohl die Kreatur nur eine Erscheinung war, wirkte sie mächtiger als Maurin, sein Hexenmeistergefährte. Takata fragt sich, ob Maurin sie besiegen kann.\n\nTakata könnte dem Kriegshäuptling besser dienen, indem er sich dem Dämon selbst stellt. Doch seine Pflichten hier hindern ihn daran, für seine persönliche Ehre in den Kampf zu ziehen, ohne seinen Clan zu entehren."}},faq={{q="Warum will Maurin Knochenspalter, dass Takata Stahlklinge informiert wird?",a="Der Dämonenlord hat sich als weitaus gefährlicher erwiesen, als Maurin Knochenspalter erwartet hatte. Maurin glaubt, dass Takata Stahlklinge an seinen Fähigkeiten zweifelt und dass es Takatas Ehre verletzen würde, den Schwertkämpfer im Ungewissen zu lassen.",al={"warum mit takata sprechen","maurin knochenspalter grund","warum takata informieren"}},{q="Wo befindet sich Takata Stahlklinge?",a="Takata Stahlklinge befindet sich in der Nähe, von Maurin aus auf der anderen Seite des Pfades, auf einer Klippe mit Blick auf den Kodofriedhof in Desolace.",al={"takatas standort","wo ist takata","takata stahlklinge finden"}},{q="Warum rät Maurin davon ab, Takata zu sehr zu bedrängen?",a="Maurin bittet Euch, anzubieten, den Dämon zu erschlagen, wenn Takata es gestattet, ohne ihn zu sehr zu bedrängen. Seiner Meinung nach sollte Takata glauben, die Idee stamme von ihm selbst.",al={"warum takata nicht bedrängen","umgang mit takata","takatas stolz"}}},fp="13,246,17.394.0,15.110.0,15.391.1,57.201.0,35.112.0,56.143.0"}
P.entries["quest:1485"] = {n="Üble Familiare",s="Nahe The Den bedrohen Üble Familiare Hexenmeister, die nach der Macht der Dämonen streben. Ruzan fordert Euch auf, Eure Stärke zu beweisen, indem Ihr ihre Köpfe zurückbringt. Dies ist der erste gefährliche Schritt zur Beherrschung der Teufelsmacht unter den wachsamen Augen der Horde.",h="Nahe The Den bedrohen Üble Familiare Hexenmeister, die nach der Macht der Dämonen streben.",kw={"koven der brennenden klinge","durotar","wichtel","ruzan","the den","das tal der prüfungen","üble familiare","hexenmeister"},ang={["class:Warlock"]="Als Hexenmeister stellt Ihr Euch dieser ersten Prüfung, um zu beweisen, dass Ihr dämonisches Feuer bezwingen könnt, bevor Ihr das Beschwörungsritual für Euren eigenen Wichtel erlernt.",["faction:Horde"]="Als Mitglied der Horde könnt Ihr Euch in Durotar zum Hexenmeister ausbilden lassen, doch die dunklen Künste bleiben auf abgeschiedene Orte wie The Den beschränkt.",["race:Orc"]="Als Orc begegnet Ihr täglich der dunklen Geschichte Eures Volkes. Ihr müsst Eure Beherrschung und Treue in einer Gesellschaft beweisen, die sich an die Schrecken der Teufelsverderbnis erinnert."},sec={{t="Ein unsicherer Platz in der Horde",b="Hexenmeister haben einen unsicheren Platz in Thralls neuer Horde. Dämonische Verderbnis und Blutpakte brachten einst Verderben über die Orcs und hinterließen tiefe Narben und Misstrauen. Durotar duldet Teufelsmagie, doch ihre Anwender sind weder geliebt noch willkommen. Viele Hexenmeister leben abgeschieden und üben ihre Kunst an schattigen Orten wie The Den aus, fernab neugieriger Blicke. Dort unterrichten sie die wenigen Initianden, die kühn genug sind, ihrem Pfad zu folgen."},{t="Die Prüfung der Beherrschung",b="Ruzan fordert Euch auf, Eure Stärke zu beweisen, bevor er Euch die gefährlichen Riten lehrt, mit denen Ihr einen Wichtel Eurem Willen unterwerft. Üble Familiare lauern nahe einer Höhle nordöstlich von The Den und schleudern Flammengeschosse auf jene, die sich nähern. Erschlagt diese niederen Dämonen und bringt ihre Köpfe zu Ruzan zurück. Sie werden ihm zeigen, dass Ihr die feurigen Kreaturen überwältigen könnt, die Ihr zu beherrschen hofft. Erst dann könnt Ihr Euch der Gefahr jener Magie stellen, die Ihr zu beherrschen sucht."}},faq={{q="Warum schickt Ruzan Hexenmeister in den Kampf gegen Üble Familiare?",a="Ruzan schickt Euch los, damit Ihr Euch dem feurigen Wesen und der Gefahr eines Wichtels stellt, bevor Ihr versucht, einen zu beschwören. Hexenmeister sind wenige und werden misstrauisch beäugt, deshalb verlangt er einen Beweis, dass Ihr solche Kreaturen besiegen könnt, bevor er Euch die Dämonenbeschwörung lehrt.",al={"warum üble familiare töten","ruzans prüfung","wichtelprüfung"}},{q="Wo sind die Üblen Familiare zu finden?",a="Üble Familiare sammeln sich vor und in einer Höhle nordöstlich von The Den im Tal der Prüfungen, jenseits der umherstreifenden Eber und Skorpide. Die Höhle dient dem Koven der Brennenden Klinge als Lager.",al={"fundort übler familiare","wo sind familiare","ruzans höhle"}},{q="Wie steht die Horde zu Hexenmeistern in Durotar?",a="Hexenmeistern begegnet man überall in der Horde mit tiefem Misstrauen, weil dämonische Verderbnis einst die Orcs zeichnete. Thralls Regierung duldet sie und erkennt ihren Wert im Kampf, doch viele leben weiterhin abgeschieden.",al={"werden hexenmeister gehasst","hintergrund der hexenmeister der horde","warum hexenmeistern misstrauen"}},{q="Welche Belohnung bietet der Abschluss dieser Prüfung?",a="Wenn Ihr Ruzan die Köpfe erschlagener Übler Familiare bringt, beweist Ihr, dass Ihr die Stärke und Disziplin besitzt, Dämonen zu befehligen. Er kann Euch dann lehren, einen Wichtel als Diener zu beschwören.",al={"was wird erlernt","questbelohnung ruzan","wichtelzauber"}},{q="Sind Üble Familiare tatsächlich Dämonen?",a="Ja. Üble Familiare sind niedere dämonische Wichtel, die mit Teufelsmagie verbunden sind. Trotz ihrer geringen Größe sind sie gefährliche Gegner, die Feuerbälle auf ihre Feinde schleudern.",al={"was sind üble familiare","sind familiare wichtel","dämonenart der familiare"}},{q="Wer ist Ruzan?",a="Ruzan ist ein orcischer Hexenmeisterlehrer in The Den im Tal der Prüfungen. Er lehrt angehende orcische Hexenmeister, Teufelsenergie sicher zu nutzen und beschworene Diener zu beherrschen.",al={"ruzan","wer ist ruzan","tal der prüfungen hexenmeister"}}},fx={["2f864f20"]={q="Wofür sind die Köpfe der üblen Familiars?",a="Ruzan benötigt die Köpfe als physischen Beweis Eures Triumphs über die Kreaturen im Kampf. Da nur wenige Novizen den Pfad des Hexenmeisters wählen, weigert er sich, Euch die gefährliche Kunst der Dämonenbeschwörung zu lehren, bis Ihr beweisen könnt, dass Ihr die Macht und den Willen besitzt, sie zu beherrschen.",al={"verwendung der köpfe der üblen familiars","warum köpfe der üblen familiars sammeln","ruzan köpfe der üblen familiars"}},["58d905b2"]={q="Was machen die üblen Familiars im Tal der Prüfungen?",a="Diese bösartigen, wichtelartigen Kreaturen sammeln sich um eine Höhle nordöstlich von The Den, die als Koven der Brennenden Klinge bekannt ist. Angelockt durch korrupte Magie oder gebunden durch lauernde Kultisten, dienen sie als tödliches Prüfgelände für angehende Hexenmeister, um ihre Entschlossenheit gegen kleinere dämonische Schergen zu testen.",al={"warum sind üble familiars hier","üble familiars tal der prüfungen","höhle der üblen familiars"}},cca9ea14={q="Warum schickt Ruzan Euch, anstatt sich selbst um die Familiars zu kümmern?",a="Dies ist eine persönliche Prüfung der Meisterschaft, keine öffentliche Verteidigungsaufgabe. Wenn Ruzan oder die Grunzer die Familiars beseitigen würden, würde Euch das nichts lehren. Ein Hexenmeister, der einen einfachen Dämon nicht im direkten Kampf überwältigen kann, wird unweigerlich verschlungen oder vernichtet, sobald er versucht, einen zu beschwören.",al={"warum tötet ruzan sie nicht selbst","warum ich ruzan","warum prüft mich ruzan"}}},fp="14,239,31.402.0,20.419.0,53.212.0,35.186.0,44.191.0,45.158.0,33.137.0,13.155.0"}
P.entries["quest:1486"] = {n="Deviatbälge",s="Bei den Höhlen des Wehklagens sucht Nalpak einen Nutzen für die seltsamen Eigenschaften der Deviatbälge. Als Jünger von Naralex wacht er über dem Eingang, während sein Lehrer in einem verzerrten Alptraum gefangen liegt. Unter dem Brachland streifen mutierte Bestien umher, und Nalpak hofft, dass ihre Häute einem praktischen Zweck dienen können.",h="Bei den Höhlen des Wehklagens sucht Nalpak einen Nutzen für die seltsamen Eigenschaften der Deviatbälge.",kw={"brachland","deviat","deviatbälge","emerald nightmare","lederverarbeitung","nalpak","naralex","die höhlen des wehklagens"},ang={["class:Druid"]="Als Druide könnt Ihr Nalpaks Lager als die düstere Wache der überlebenden Jünger über ein schrecklich gescheitertes Vorhaben betrachten. Für andere Druiden ist die Eindämmung der Mutationen in den Höhlen eine persönliche Angelegenheit.",["profession:Herbalism"]="Als Kräuterkundiger wisst Ihr, dass das abnorme Wachstum, das die Deviatbestien nährt, mit verderbten Pflanzen und unterirdischen Quellen zusammenhängt, die sich durch das Höhlennetz winden."},sec={{t="Sichtbare Verderbnis",b="Naralex wollte die Quellen unter dem Brachland erwecken und den trockenen Ebenen wieder Leben einhauchen. Stattdessen wurden die Höhlen des Wehklagens gefährlich. Der Geist des Nachtelfendruiden glitt in einen furchterregenden Alptraum ab, und dieser Alptraum griff auf die wache Welt über. Raptoren, Krokilisken, Vipern und schlurfende Schrecken wurden bösartig und missgestaltet, verzerrt durch smaragdgrüne Verderbnis, die aus ihrem träumenden Meister sickerte."},{t="Ein pragmatischer Druide",b="Vom Felsen über dem Höhleneingang aus beobachtet Nalpak die Katastrophe mit Grauen und praktischer Neugier. Er weiß, dass die Deviatbestien bösartig und unnatürlich sind, doch ihre verderbten Körper könnten nützliche Materialien liefern. Ihre zähen, verzerrten Bälge könnten geschickten Lederverarbeitern helfen. Nalpak hofft, aus den Früchten eines tragischen Alptraums haltbare Ausrüstung herzustellen."}},faq={{q="Wo kann ich Nalpak finden?",a="Nalpak und seine Mitjünger lagern hoch oben auf dem schädelförmigen Felsen über dem Eingang zu den Höhlen des Wehklagens. Erklimmt die Hänge hinter dem Höhleneingang und lasst Euch dann vorsichtig auf den oberen Felsvorsprung in der Augenhöhle hinab, die über der Oase liegt.",al={"nalpak standort","wo ist nalpak","wie nalpak finden","questgeber deviatbälge"}},{q="Was sind Deviatkreaturen?",a="Deviatkreaturen sind einheimische Bestien, die durch den Emerald Nightmare verwandelt wurden, der aus Naralex' schlummerndem Geist entwich. Raptoren, Schlangen, Krokilisken und Windschlangen aus dem Brachland sind dunkler und bösartiger geworden, mit seltsamen magischen Eigenschaften und fleckigen, unnatürlichen Häuten.",al={"was sind deviatkreaturen","deviatbestien","warum sind tiere in den höhlen des wehklagens mutiert"}},{q="Warum will Nalpak diese Bälge?",a="Nalpak glaubt, dass die Häute der verderbten Bestien ungewöhnlich widerstandsfähig sind und sich praktisch nutzen lassen. Er hofft, dass Lederverarbeiter die Bälge untersuchen und zu strapazierfähiger Ausrüstung verarbeiten können.",al={"warum deviatbälge","wofür will nalpak bälge","zweck der deviatbälge"}},{q="Kann jede Deviatkreatur die Bälge fallen lassen?",a="Mutierte Bestien in den Tunneln und im Inneren der Höhlen des Wehklagens tragen diese Häute. Jäger und Lederverarbeiter können durch Kürschnern zusätzliche Bälge gewinnen, neben denen, die sie aus den Überresten bergen.",al={"welche gegner lassen deviatbälge fallen","wer lässt deviatbalg fallen","deviatbälge farmen"}},{q="Gehört Nalpak zur Horde oder zur Allianz?",a="Nalpak ist ein Taurendruide und einer der Jünger von Naralex. Er bleibt neutral und nimmt Hilfe von jedem fähigen Abenteurer an, ob Allianz oder Horde, der mutig genug ist, die verderbten Höhlen zu betreten.",al={"gehört nalpak zur horde","ist deviatbälge für die allianz","kann die allianz deviatbälge erledigen"}},{q="Was ist mit Naralex geschehen?",a="Naralex wollte die unterirdischen Quellen des Brachlands erwecken, indem er sein Bewusstsein mit dem Smaragdgrünen Traum verband. Stattdessen bemächtigte sich der Nightmare seines Schlummers, verwandelte die Höhlen in eine Brutstätte des Schreckens und ließ ihn tief darin im Koma zurück.",al={"wer ist naralex","naralex alptraum","was ist mit dem druiden in den höhlen des wehklagens geschehen"}}},fx={["58e10be2"]={q="Wofür ist der Deviatbalg?",a="Deviatbälge besitzen seltsame, jenseitige Eigenschaften, die aus dem Albtraum stammen, der die Höhlen korrumpiert. Obwohl die Kreaturen, von denen sie stammen, verdreht und feindselig sind, glaubt Nalpak, dass ihre ungewöhnlichen Felle durch Lederverarbeitung wiederverwendet werden können, um robuste Rüstungen und Taschen herzustellen, wodurch etwas Nützliches aus der Verderbnis hervorgeht.",al={"verwendung der deviatbälge","warum deviatbälge sammeln","zweck der deviatbälge"}}},fp="13,301,24.394.0,17.351.0,24.224.0,27.284.0,33.172.0,40.193.0,49.187.0,25.248.0"}
P.entries["quest:1487"] = {n="Ausrottung der Deviat",s="In den Höhlen des Wehklagens schickt Ebru Euch los, um die Deviatbestien zu dezimieren. Die Nachtelfendruidin wacht über die Höhlen, während andere Jünger versuchen, Naralex zu wecken. Seine verzerrte Vision hat mutierte Kreaturen hervorgebracht, deren wachsende Zahl die Verderbnis über die unterirdischen Quellen hinaus ins Brachland zu tragen droht.",h="In den Höhlen des Wehklagens schickt Ebru Euch los, um die Deviatbestien zu dezimieren.",kw={"brachland","deviatschreckenszahn","ausrottung der deviat","deviatverheerer","deviatwandler","deviatviper","ebru","naralex","die höhlen des wehklagens"},ang={["class:Druid"]="Als Druide warnt Euch das entstellte Leben in den Höhlen davor, was geschehen kann, wenn die Verbindung mit dem Smaragdgrünen Traum misslingt.",["faction:Horde"]="Als Mitglied der Horde könnt Ihr nahe gelegene Siedlungen wie das Wegekreuz schützen helfen, indem Ihr die Raubtiere in den Höhlen des Wehklagens im Herzen von Kalimdors zentralen Ebenen dezimiert.",["race:NightElf"]="Als Nachtelf fühlt Ihr Euch vielleicht verpflichtet, Euren gestrandeten Verwandten zu helfen, während Naralex' edle Hoffnung zu einem aus Albträumen geborenen Schrecken wird."},sec={{t="Ein schrecklich entgleister Traum",b="Naralex brachte seine Anhänger zu den unterirdischen Quellen des Brachlands, in der Hoffnung, den Smaragdgrünen Traum anzuzapfen und die trockenen Ebenen wieder in Waldland zu verwandeln. Stattdessen nahm ihn der Traum gefangen, und sein Schlaf wurde zum Albtraum. Die durch die Höhlen strömende Macht verwandelte heimische Pflanzen und Tiere in aggressive Mutanten, die als Deviatbestien bekannt sind."},{t="Ebrus Wacht",b="Ebru wacht mit den wenigen verbliebenen Disciples of Naralex in einer Klippenhöhle über dem Eingang. Ihre Zahl schwindet. Einige arbeiten daran, ihren gefallenen Anführer zu wecken, doch Ebru erkennt die Gefahr durch die Deviatvipern, Deviatwandler, Deviatverheerer und Deviatschreckenszähne. Sie vermehren sich rasch und könnten sich ins Brachland ausbreiten. Deshalb bittet Ebru Euch, die tiefen Tunnel zu betreten und die Monster an ihrem Ursprung zu dezimieren."}},faq={{q="Wo finde ich Ebru, um diese Aufgabe zu beginnen?",a="Ebru wartet mit einigen anderen Disciples of Naralex in einer abgelegenen Höhle hoch über dem Haupteingang der Höhlen des Wehklagens. Die Höhle liegt in etwas, das wie die rechte Augenhöhle des schädelförmigen Felsens aussieht. Klettert um den Bergkamm herum und steigt dann vorsichtig zum oberen Felsvorsprung hinab.",al={"ebru standort","wo ist ebru","wie zu ebru gelangen","höhlen des wehklagens augenhöhle"}},{q="Wodurch wurden die Tiere zu Deviatbestien?",a="Die Tiere veränderten sich, als Naralex' Versuch, das Brachland zu erneuern, fehlschlug. Er verband seinen Geist mit den unterirdischen Quellen und dem Smaragdgrünen Traum, doch ein Albtraum ergriff seine Gedanken und verdrehte die heilende Macht zu einer Kraft, die die heimische Tierwelt mutieren lässt.",al={"warum sind sie deviat","ursprung der deviatbestien","was verdarb die tiere in den höhlen des wehklagens"}},{q="Wer sind die Disciples of Naralex?",a="Die Disciples of Naralex sind Druiden, die ihm in die Höhlen des Wehklagens folgten, um bei der Wiederherstellung des Brachlands zu helfen. Nachdem der Albtraum Naralex gefangen hatte, verwilderten viele Jünger oder verloren den Verstand. Nur ein kleiner Rest ist noch bei klarem Verstand und versucht, das Unheil rückgängig zu machen.",al={"disciples of naralex","naralex anhänger","wer sind die druiden in den höhlen des wehklagens"}},{q="Können sowohl Allianz als auch Horde diese Aufgabe annehmen?",a="Ja. Ebru und die Druiden an ihrer Seite wollen die Natur bewahren und den Albtraum eindämmen. Sie nehmen Hilfe von fähigen Streitern sowohl der Horde als auch der Allianz an.",al={"ausrottung der deviat allianz oder horde","ist ausrottung der deviat neutral"}},{q="Welche Kreaturen muss man für Ebru töten?",a="Ebru bittet Euch, tief in den Höhlen vier Arten verderbter Kreaturen zu jagen: Deviatverheerer, Deviatvipern, Deviatwandler und Deviatschreckenszähne. Ihr müsst von jeder Art sieben töten.",al={"ausrottung der deviat gegner","ausrottung der deviat ziele","welche deviat töten"}},{q="Wird Naralex durch den Abschluss dieser Aufgabe geweckt?",a="Nein. Ebru bittet Euch, die gefährlichen Bestien zu dezimieren und den Schaden zu begrenzen, den sie anrichten. Um Naralex zu wecken, ist ein gesondertes Ritual tief in seinem Heiligtum im Herzen der Höhle nötig.",al={"weckt das naralex","wie naralex wecken"}}},fx={["62e049f1"]={q="Warum will Ebru, dass die Deviatbestien vernichtet werden?",a="Während andere Jünger von Naralex ihre Bemühungen darauf konzentrieren, ihren gefangenen Meister zu erwecken, sieht Ebru eine unmittelbare Bedrohung, die in den Höhlen des Wehklagens eitert. Naralex' Vision, das Brachland wieder in einen üppigen Wald zu verwandeln, hat sich in einen Albtraum verwandelt, der korrupte, unnatürliche Kreaturen durch die Tunnel speit. Ebru glaubt, dass es keine Hoffnung gibt, diese Ländereien zu heilen oder ihren Anführer zu retten, bis diese verdrehten Bestien aus den Höhlen getilgt sind.",al={"ebru motiv","warum deviatbestien töten","warum will ebru die deviatbestien tot sehen"}},b4bfe70b={q="Was sind die Deviatkreaturen in den Höhlen des Wehklagens?",a="Es handelt sich um die lokale Fauna – Vipern, Raptoren und schlurfende Pflanzen-Horrors –, die durch die dunklen Energien, die aus Naralex' Albtraum austreten, in monströse Formen verzerrt wurden. Naralex versuchte, den Smaragdgrünen Traum zu kanalisieren, um das aride Brachland wiederzubeleben, aber als sein Traum faul wurde, mutierte der umgebende magische Abfluss die Tierwelt zu aggressiven, unnatürlichen Raubtieren, die nun die Tiefen der Höhlen befallen.",al={"was sind deviatspeier","deviatbestien höhlen des wehklagens","korrupte kreaturen höhlen des wehklagens"}},ab17f40e={q="Warum können die Jünger von Naralex die Höhlen nicht selbst säubern?",a="Die Jünger sind viel zu dünn gestreut, um aus eigener Kraft einen Angriff zu starten. Ihr Orden ist seit Naralex' Gefangenschaft in seinem Albtraum erheblich geschrumpft, und die wenigen, die noch übrig sind, sind aufgeteilt zwischen der Vorbereitung eines Rituals zu seiner Erweckung und der Verteidigung des kleinen Stützpunkts, den sie noch halten. Ihnen fehlen die Anzahl und die militärische Stärke, um ohne Hilfe von außen in die Höhlen vorzudringen und die Bestien auszurotten.",al={"warum braucht ebru meine hilfe","warum können jünger die höhlen nicht säubern","jünger von naralex warum hilfe nötig"}}},fp="19,299,27.325.0,12.379.0,41.270.0,41.254.0,33.256.0,44.161.0,44.182.0,40.166.0"}
P.entries["quest:1488"] = {n="Der Verderber",s="Takata Stahlklinge steht auf Maurins Seite: Lord Azrethoc muss aufgehalten werden, besonders wenn er Einfluss auf die Burning Blade sucht. Takata vertraut darauf, dass Ihr eine Gruppe gegen den Dämonenlord und seinen Hexenmeisterdiener Jugkar Grim'rod zusammenstellt.",h="Takata Stahlklinge steht auf Maurins Seite: Lord Azrethoc muss aufgehalten werden, besonders wenn er Einfluss...",kw={"burning blade","dämon","desolace","jugkar grim'rod","lord azrethoc","maurin","takata stahlklinge","hexenmeister"},sec={{t="Eine Gruppe für den Süden",b="Takata hat noch nie von Lord Azrethoc gehört, stimmt Maurin aber zu, dass der Dämonenlord aufgehalten werden muss. Die Gefahr wächst, wenn Azrethoc versucht, die Burning Blade zu beeinflussen. Ihr habt bereits gezeigt, dass Ihr dem Kriegshäuptling helfen wollt, daher vertraut Takata darauf, dass Ihr eine Gruppe zusammenstellt und Azrethoc sowie seinen Hexenmeisterdiener Jugkar Grim'rod erschlagt. Zieht direkt nach Süden zu Mannorocs Koven, wo sich beide aufhalten."},{t="Takatas Sorge",b="Takata bezeichnet die Dämonen in Desolace als größere Bedrohung denn je. Jede neu eingetroffene abscheuliche Kreatur trübt die Aussicht auf eine Rückkehr zum Kriegshäuptling. Manchmal wünscht sich Takata, die Zentauren wären der einzige Feind."},{t="Takatas Urteil",b="Sobald die Bedrohung gebannt ist, nennt Takata dies einen gewaltigen Sieg für alle. Die Aussichten hier sind weniger düster, als Takata einst befürchtet hatte. Die Dämonen sind erschlagen, die Burning Blade ist mit ihren Bemühungen gescheitert, und ein Ort, den man Heimat nennen kann, ist wieder sicher."}},faq={{q="Wer schickt Abenteurer gegen Lord Azrethoc aus?",a="Takata Stahlklinge steht auf Maurins Seite und vertraut darauf, dass Ihr eine Gruppe gegen den Dämonenlord zusammenstellt.",al={"wer vergibt die quest der verderber","questgeber der verderber","takata stahlklinge quest"}},{q="Wer muss besiegt werden?",a="Lord Azrethoc, ein Dämonenlord, und Jugkar Grim'rod, sein Hexenmeisterdiener, müssen besiegt werden.",al={"wer muss getötet werden","ziele der verderber","azrethoc und jugkar"}},{q="Wo befinden sich die Ziele?",a="Takata sagt, Ihr sollt direkt nach Süden zu Mannorocs Koven im südlichen Desolace ziehen, wo sich beide aufhalten.",al={"wo ist azrethoc","jugkar grimrod aufenthaltsort","wohin für der verderber"}},{q="Warum stellt Lord Azrethoc eine solche Gefahr dar?",a="Takata hat noch nie von Azrethoc gehört, stimmt aber zu, dass der Dämonenlord aufgehalten werden muss, besonders wenn er versucht, die Burning Blade zu beeinflussen.",al={"warum azrethoc töten","was tut azrethoc","verbindung zur burning blade"}},{q="Was kommt davor in der Questreihe?",a="Dieser Schritt folgt auf den vierten Teil der Questreihe „Der Verderber“.",al={"vorausgesetzte quest","vorherige quest der verderber","questreihe der verderber"}},{q="Was befürchtet Takata wegen der Dämonen in Desolace?",a="Takata bezeichnet die Dämonen als größere Bedrohung denn je. Jede neu eingetroffene abscheuliche Kreatur trübt die Aussicht auf eine Rückkehr zum Kriegshäuptling, und Takata wünscht sich manchmal, die Zentauren wären der einzige Feind.",al={"takatas geschichte","warum ist takata hier","takata stahlklinges rolle"}}},fp="13,225,20.384.0,14.201.0,16.230.1,49.92.0,21.88.0,30.96.0,42.137.0,36.57.0,51.193.0"}
P.entries["quest:1489"] = {n="Hamuul Runentotem",s="Tonga Runentotem schickt Euch nach Donnerfels, während sich eine seltsame Verderbnis im Brachland ausbreitet. Er vermutet ihren Ursprung in den Höhlen des Wehklagens und sucht den Rat von Erzdruide Hamuul Runentotem.",h="Tonga Runentotem schickt Euch nach Donnerfels, während sich eine seltsame Verderbnis im Brachland ausbreitet.",kw={"die anhöhe der ältesten","hamuul runentotem","oasen","verderbnis","brachland","donnerfels","tonga runentotem","die höhlen des wehklagens"},ang={["class:Druid"]="Als Taurendruide kommt Ihr zu Erzdruide Hamuul Runentotem als Schüler jenes Mentors, der nach den Lehren von Malfurion Sturmgrimm das moderne Druidentum der Tauren begründete.",["faction:Horde"]="Als Mitglied der Horde wisst Ihr, dass das Brachland ein Knotenpunkt für die junge Horde ist. Die Untersuchung der sich ausbreitenden Verderbnis schützt die Versorgungswege zwischen Durotar, Mulgore und den nördlichen Außenposten.",["race:Tauren"]="Als Tauren erlebt Ihr, wie die Sorgen um Eure angestammten Jagdgründe im Brachland den Stammesältesten auf den heiligen Anhöhen Mulg ores vorgetragen werden."},sec={{t="Ein beunruhigender Traum",b="Nahe den Oasen des Brachlands fand Tonga Runentotem Kreaturen, die von einem seltsamen Leiden gezeichnet waren. Eine unnatürliche Verderbnis bedeckte ihre Panzer, und Tonga kam zu der Überzeugung, dass das Land selbst in einem unruhigen Traum gefangen war. Er vermutet, dass die aus den Höhlen des Wehklagens strömenden Wasser daran schuld sind. Diese Höhlen zu betreten, erfordert mehr Weisheit, als ein einzelner Naturforscher bieten kann."},{t="Rat auf der Anhöhe der Ältesten",b="Tonga schickt Euch nach Donnerfels, um den Rat seines Verwandten, Erzdruide Hamuul Runentotem, einzuholen. Hamuul ist der ranghöchste Taurendruide und ein verehrter spiritueller Anführer des Zirkels des Cenarius in Mulgore. Von der Anhöhe der Ältesten aus hält er nach Störungen in ganz Kalimdor Ausschau. Er bestätigt, dass der sich im Brachland ausbreitende Alptraum eine ernste Bedrohung ist, die die ganze Macht der Champions der Horde erfordert."}},faq={{q="Warum schickt Tonga mich zu Hamuul?",a="Tonga entdeckte ein seltsames Leiden unter den Kreaturen nahe den Oasen des Brachlands und vermutet die Wasser der Höhlen des Wehklagens als Ursprung. Er schickt Euch auf die Anhöhe der Ältesten in Donnerfels, um den Rat von Erzdruide Hamuul Runentotem einzuholen, bevor jemand die Höhlen betritt.",al={"warum hamuul","warum mit hamuul sprechen","hamuul quest zweck"}},{q="Wo befindet sich Hamuul Runentotem?",a="Hamuul Runentotem befindet sich oben auf der Anhöhe der Ältesten in Donnerfels, der Hauptstadt der Tauren in Mulgore. Andere Druiden und Schamanen leben dort mit ihm und blicken über die umliegenden Ebenen.",al={"hamuul standort","wo ist hamuul","hamuul runentotem finden"}},{q="Woher stammt die Verderbnis, die Tonga bemerkt hat?",a="Tonga vermutet, dass unterirdische Quellen in den Höhlen des Wehklagens der Ursprung der Verderbnis sind. Ihre seltsamen Wasser verderben die heimische Tier- und Pflanzenwelt und lassen das Land wirken, als sei es in einem unentrinnbaren Alptraum gefangen.",al={"was ist die verderbnis","verderbnis der oasen","höhlen des wehklagens verderbnis"}},{q="Was geschieht nach dem Gespräch mit Hamuul?",a="Hamuul heißt Euch in Donnerfels willkommen und bereitet Euch auf das vor, was Euch erwartet. Er warnt, dass es ein gefährliches Unterfangen ist, sich dem Alptraum unter dem Brachland zu stellen, und verweist Euch dann an Nara Wildmane, um Euch auf den Abstieg in die Höhlen des Wehklagens vorzubereiten.",al={"nächste quest nach hamuul","wie geht es weiter","hamuul folgequest"}},{q="Wer ist Hamuul Runentotem?",a="Hamuul Runentotem führt die Druiden der Tauren an und ist ein enger Jugendfreund und Berater von Oberhäuptling Cairne Bluthuf. Seit dem Dritten Krieg hat er die Wege der Wildnis erlernt und leitet Taurendruiden in der Verbundenheit mit der Natur und dem Zirkel des Cenarius an.",al={"wer ist hamuul","hamuul hintergrundgeschichte","erzdruide hamuul"}},{q="Ist diese Quest erforderlich, um die Höhlen des Wehklagens zu betreten?",a="Nein. Ihr könnt die Höhlen des Wehklagens ohne Zugangsberechtigung betreten, doch diese Geschichte der Horde verbindet das Geheimnis der üppigen Oasen des Brachlands mit der Expedition in die Höhlen.",al={"höhlen des wehklagens zugangsberechtigung","ist diese quest pflicht"}}},fx={a40fa735={q="Warum bittet Tonga Runentotem einen Abenteurer, zu Hamuul zu gehen?",a="Tonga Runentotem ist im Wegekreuz stationiert, um die seltsamen, verstörenden Veränderungen aktiv zu überwachen, die sich durch das Brachland und seine Oasen ausbreiten. Da er im Feld bleiben muss, um die korrupte Tierwelt aus erster Hand zu studieren, verlässt er sich darauf, dass fähige Reisende seine Berichte überbringen und direkt bei Erzdruide Hamuul Runetotem auf der Anhöhe der Ältesten in Donnerfels um Rat suchen.",al={"warum mich zu hamuul schicken","warum kann tonga nicht zu hamuul","warum ich tonga"}}},fp="16,189,18.351.0,21.378.0,33.254.0,34.167.0,46.203.0,40.239.0,24.252.0,52.162.0"}
P.entries["quest:149"] = {n="Geisterhaarfaden",s="Im Dämmerwald sucht Madame Eva Geisterhaar, um daraus Geisterhaarfaden für Calvinius zu spinnen. Sie schickt Euch südlich von Dunkelhain zur blinden Mary in einem verlassenen Bauernhaus, wo ein ätherischer Kamm Haar von dem gequälten Geist sammeln kann.",h="Im Dämmerwald sucht Madame Eva Geisterhaar, um daraus Geisterhaarfaden für Calvinius zu spinnen.",kw={"die blinde mary","dunkelhain","dämmerwald","bauernhaus","geist","geisterhaarfaden","madame eva","spektraler kamm"},ang={["class:Priest"]="Als Priester könnt Ihr in den Qualen der blinden Mary die Tragik und die anhaltenden Schatten erkennen, die die ruhelosen Toten des Dämmerwalds plagen.",["faction:Alliance"]="Als Reisender der Allianz könnt Ihr an den tragischen Geistern auf den Bauernhöfen nahe Dunkelhain erkennen, wie schnell das wohlhabende Grand Hamlet in Dunkelheit und Isolation versank.",["profession:Tailoring"]="Aus den körperlosen Überresten eines Geistes Faden zu spinnen, ist ein okkultes Handwerk, fernab gewöhnlicher Spinnräder und Webstühle."},sec={{t="Die Bitte einer Wahrsagerin",b="Madame Eva braucht Geisterhaar, um Faden für Calvinius zu spinnen. Leinen und Wolle eignen sich nicht für die Rituale des Dämmerwalds, also gibt sie Euch einen Spektralen Kamm, um Haarsträhnen eines Geistes zu sammeln. Der Kamm durchdringt den Schleier des Todes und fängt lose Geisterhaare auf, ohne Gewalt anzuwenden."},{t="Das Leid der blinden Mary",b="Südlich von Dunkelhain spukt die blinde Mary in einem verlassenen Bauernhaus. Der gequälte Geist verzweifelt am eigenen Aussehen und schreit Eindringlinge an, sie sollen wegsehen. Aus Verzweiflung darüber, was aus ihr geworden war, riss sie sich die eigenen Augen heraus. Der Spektrale Kamm spendet kurzen Trost: Sie kann ihr geisterhaftes Haar pflegen, doch ihre Qual dauert an."}},faq={{q="Wer ist die blinde Mary?",a="Die blinde Mary ist ein kummervoller Geist, der in einem verlassenen Bauernhaus in den Hügeln südlich von Dunkelhain spukt. Verzweiflung über ihre vermeintliche Hässlichkeit trieb sie dazu, sich die eigenen Augen herauszureißen, damit sie sich nie wieder sehen müsste. Obwohl sie blind ist, spürt sie noch immer schmerzlich, wenn jemand sie ansieht.",al={"geschichte der blinden mary","wer ist mary im dämmerwald","spektraler kamm frau"}},{q="Warum braucht Madame Eva Geisterhaar?",a="Madame Eva braucht Geisterhaar, um geisterhaften Faden zu spinnen. Gewöhnliche Handwerksmaterialien eignen sich nicht für die Rituale des Dämmerwalds, also greift sie für ihre Arbeit und Schutzverzauberungen auf okkulte Materialien zurück.",al={"warum geisterhaar","wozu dient geisterhaarfaden","madame eva haarfaden"}},{q="Wo findet man das Haus der blinden Mary?",a="Das verfallene Bauernhaus der blinden Mary liegt in den Hügeln südlich von Dunkelhain, hinter dem Friedhof der Stadt. Schrecken und Untote streifen durch die umliegenden Wälder.",al={"wo ist die blinde mary","standort der blinden mary","bauernhaus südlich von dunkelhain"}},{q="Wie wirkt der Spektrale Kamm bei einem Geist?",a="Der Spektrale Kamm kann Erscheinungen berühren und ihr Haar sammeln. Er gleitet durch geisterhafte Materie wie ein gewöhnlicher Kamm durch lebendiges Haar und sammelt dabei Strähnen, die ätherisch bleiben.",al={"wie funktioniert der spektrale kamm","geschichte des spektralen kamms","geisterhaar kämmen"}},{q="Ist die blinde Mary Reisenden gegenüber feindselig?",a="Nein. Die blinde Mary schreit und weint, doch lebenden Besuchern gegenüber ist sie nicht feindselig. Ihre Qual richtet sich nach innen, während aggressive Kreaturen und Untote die Wälder und nahe gelegenen Gebäude heimsuchen.",al={"greift die blinde mary an","ist die blinde mary gefährlich"}},{q="Was geschieht, nachdem Mary den Kamm erhalten hat?",a="Nachdem Mary den Kamm benutzt hat, gibt sie ihn mit ihrem darin verfangenen Geisterhaar zurück. Bringt ihn zu Madame Eva in Dunkelhain zurück, damit sie die Strähnen zu Geisterhaarfaden verspinnen kann.",al={"was kommt nach geisterhaar","return the comb quest","nach geisterhaarfaden"}}},fx={["212c26a1"]={q="Warum benötigt Madame Eva einen Abenteurer, um Die blinde Mary aufzusuchen?",a="Madame Eva bleibt in Dunkelhain, um der Stadt mit ihren Weissagungen und Ritualen zu helfen, aber um Die blinde Mary zu erreichen, muss man tief in die heimgesuchten Hügel südlich des Dorfes reisen. Die umliegenden Wälder und Marys Farmhaus wimmeln von Untoten und schattenhaften Bestien, denen sich normale Stadtbewohner nicht allein stellen können.",al={"warum mich schicken","warum geht sie nicht selbst","warum braucht eva mich"}}},fp="17,228,25.265.0,24.316.0,18.273.0,36.184.0,38.139.0,44.185.0,35.179.0,40.165.0"}
P.entries["quest:1490"] = {n="Nara Wildmähne",s="In Donnerfels hilft Nara Wildmähne der Horde, die Gefahr in den Höhlen des Wehklagens zu verstehen. Erzdruide Hamuul Runentotem sah Verderbnis im Smaragdgrünen Traum, konnte ihr aber nicht standhalten und schickte daher Reisende zu seiner jungen Schülerin. Nara sah, wie der Alptraum von ihren Verwandten Besitz ergriff.",h="In Donnerfels hilft Nara Wildmähne der Horde, die Gefahr in den Höhlen des Wehklagens zu verstehen.",kw={"brachland","druiden des giftzahns","die anhöhe der ältesten","smaragdgrüner traum","hamuul runetotem","nara wildmähne","donnerfels","die höhlen des wehklagens"},ang={["class:Druid"]="Als Druide könnt Ihr Naras Mut in den verdorbenen Gefilden des Smaragdgrünen Traums bewundern, wo selbst der erfahrene Hamuul nicht verweilen konnte.",["faction:Horde"]="Als Mitglied der Horde könnt Ihr sehen, wie Naras Wachsamkeit deren Kernland vor den dunklen Energien schützt, die das Brachland entstellen und sich nach Mulgore auszubreiten drohen.",["race:Tauren"]="Als Tauren, der sich erst kürzlich unter Hamuul dem Druidentum zugewandt hat, gehört Ihr einer jungen Generation an, die sich wie Nara unnatürlicher Verderbnis entgegenstellt."},sec={{t="Eine Vision der Verderbnis",b="Unnatürliche Zeichen breiteten sich im Brachland aus, und Erzdruide Hamuul Runentotem betrat den Smaragdgrünen Traum, um ihre Ursache zu finden. Dort fand er einen Druidenkult, der einst gehofft hatte, der trockenen Savanne neues Leben einzuhauchen. Eine abscheuliche Verderbnis hatte seine Mitglieder in den Wahnsinn getrieben.\n\nSein Alter hinderte Hamuul daran, dem Ansturm des Alptraums standzuhalten, also floh er in die wache Welt. Seine jüngere Schülerin Nara Wildmähne weigerte sich, so bald zu gehen. Ihre leidenschaftliche Entschlossenheit hielt sie in der Traumwelt, wo sie den verwandelten Kult mit eigenen Augen sah."},{t="Dem Alptraum entgegentreten",b="Nara Wildmähne weiß, was die gefallenen Druiden getan haben und was sie über Kalimdor entfesseln wollen. Als sie ihnen im Smaragdgrünen Traum begegnete, waren ihre Gesichter entstellt und schuppig wie die von Schlangen. Hamuul führt den Zirkel des Cenarius von Donnerfels aus, während Nara das nötige Wissen beisteuert, um die Verderbnis zu bekämpfen. Nun stößt die Horde in die Höhlen des Wehklagens vor, um die Anführer zu vernichten, die ihren heiligen Eiden abschworen."}},faq={{q="Wer ist Nara Wildmähne?",a="Nara Wildmähne ist eine junge Taurendruidin, die auf der Anhöhe der Ältesten in Donnerfels lebt. Sie lernt bei Erzdruide Hamuul Runentotem und stellt sich den Alpträumen, die die Natur verderben.",al={"wer ist nara","nara wildmähne hintergrundgeschichte","nara wildmähne donnerfels"}},{q="Warum schickt Hamuul Runetotem Reisende zu ihr?",a="Hamuul Runetotem schickt Reisende zu Nara, weil sein Alter und seine schwindenden Kräfte ihn daran hinderten, im verdorbenen Traum zu bleiben. Jung und fest entschlossen blieb Nara länger und erfuhr von den Druiden des Giftzahns und ihren Plänen.",al={"warum mit nara sprechen","hamuul zu nara","warum schickt hamuul reisende hierher"}},{q="Was sah Nara im Smaragdgrünen Traum?",a="Nara sah die gefallenen Druiden, die in den Höhlen des Wehklagens hausen. Ihre Gesichter waren schuppig und schlangenartig geworden, und sie erfuhr von ihren Verbrechen und finsteren Plänen gegen das Brachland.",al={"was hat nara gesehen","naras traumvision","schuppige druiden im traum"}},{q="Wo ist Nara Wildmähne zu finden?",a="Nara Wildmähne ist in einem Druidenzelt oben auf der Anhöhe der Ältesten in Donnerfels zu finden, gegenüber von Erzdruide Hamuul Runentotem.",al={"wo ist nara","nara wildmähne standort","nara wildmähne finden"}},{q="Was geschieht, nachdem man Nara Wildmähne Bericht erstattet hat?",a="Nachdem Ihr mit Nara gesprochen habt, schickt sie Euch in die Höhlen des Wehklagens, um die abtrünnigen Druiden des Giftzahns zu töten. Dies führt zu dem größeren Unterfangen namens Leaders of the Fang.",al={"nächste quest nach nara","was soll für nara getan werden","leaders of the fang folgequest"}},{q="Warum sind die Druiden in den Höhlen des Wehklagens verdorben?",a="Unter Naralex' Führung betraten die Druiden die Höhlen und hofften, mithilfe des Smaragdgrünen Traums üppiges Leben ins Brachland zu bringen. Naralex' Schlummer wurde zu einem grauenvollen Alptraum, der seine Anhänger gefangen nahm und sie in die schlangenartigen Druiden des Giftzahns verwandelte.",al={"höhlen des wehklagens kult","druiden des giftzahns warum böse","warum sind die druiden im brachland böse"}}},fx={["2cdff5a8"]={q="Warum bittet Hamuul Runetotem Euch, mit Nara zu sprechen, anstatt selbst zu gehen?",a="Erzdruide Hamuul Runetotem ist durch das hohe Alter und die Last, in das Geisterreich zu greifen, belastet. Als er in den Smaragdgrünen Traum eintrat, um die Probleme in den Höhlen des Wehklagens zu untersuchen, versagten seine Kräfte, was ihn dazu zwang, sich zurückzuziehen. Nara Wildmane ist jung und wild und verweilt noch lange im Traum, nachdem er geflohen war. Da Hamuul in Donnerfels die Taurendruiden koordiniert und es sich nicht leisten kann, seine verbleibende Vitalität mit dem Überbringen von Nachrichten oder dem alleinigen Stellen der Bedrohung zu verschwenden, betraut er fähige Reisende damit, zu erfahren, was Nara entdeckt hat.",al={"warum schickt mich hamuul zu nara","warum kann hamuul nicht mit nara sprechen","warum einen abenteurer zu nara schicken"}}},fp="13,270,22.497.0,25.408.1,21.173.0,59.226.0,39.173.0,33.123.0,46.170.0,52.251.0"}
P.entries["quest:1491"] = {n="Klugheitstränke",s="In Ratschet sucht Mebok Mizzyrix eine neue Rezeptur für sein Getränk. Sein Gebräu aus pulverisierten Hörnern von Sonnenschuppenraptoren hat ihn enttäuscht, also will er nun ektoplasmatische Rückstände aus den Höhlen des Wehklagens.",h="In Ratschet sucht Mebok Mizzyrix eine neue Rezeptur für sein Getränk.",kw={"brachland","ektoplasma","mebok mizzyrix","raptor horns","ratschet","klugheitstränke","die höhlen des wehklagens","klageessenz"},ang={["class:Druid"]="Als Druide betretet Ihr die Höhlen des Wehklagens, um den Alptraum zu vertreiben, der die smaragdgrüne Traumlandschaft verzerrt. Mebok sieht diese Verseuchung der Natur als billigen Sirup für sein Geschäft.",["faction:Horde"]="Als Mitglied der Horde könnt Ihr bei den Händlern an den Wegkreuzungen des Brachlands in Ratschet schnelles Geld verdienen. Für Meboks Geschäft sollt Ihr Monsterteile abliefern, ohne viele Fragen zu stellen.",["profession:Cooking"]="Wenn Ihr kocht, ist rohes, vom Alptraum verseuchtes Ektoplasma eine schlechte Wahl für ein Getränk. Mebok will es trotz der Gefahr für die Lebensmittelsicherheit zu einem Stärkungsmittel ansetzen."},sec={{t="Ein Rezept fürs Unheil",b="Mebok Mizzyrix verkauft Waren in Ratschet und hofft, mit einem Getränk, das den Verstand schärft, ein Vermögen zu verdienen. Seine erste Rezeptur enthielt pulverisierte Hörner von Sonnenschuppenraptoren, doch das Gebräu enttäuschte ihn. Nun setzt er auf die seltsame Essenz, die aus den Höhlen des Wehklagens sickert, und hofft, dass sie seinem Getränk zum Erfolg verhilft."},{t="Die Klageessenz",b="Seltsame Veränderungen haben das Brachland erfasst. Neue Oasen sind entstanden, und die heimische Tierwelt ist aggressiv und entstellt geworden. Mebok vermutet dahinter eine Substanz, die er Klageessenz nennt. Er schickt Euch in das Höhlenlabyrinth, um dessen triefende Ektoplasmen zu vernichten und ihre leuchtende Flüssigkeit für seine Rezeptur in Flaschen zu sammeln."}},faq={{q="Wer ist Mebok Mizzyrix?",a="Mebok Mizzyrix ist ein Goblinhändler in Ratschet. Er hofft, in ganz Kalimdor ein intelligenzsteigerndes Getränk zu verkaufen und damit ein Vermögen zu verdienen.",al={"mebok mizzyrix","wer vergibt klugheitstränke","klugheitstränke questgeber"}},{q="Warum haben die Raptorhörner nicht funktioniert?",a="Mebok dachte, pulverisierte Hörner von Sonnenschuppenraptoren würden ein intelligenzsteigerndes Gebräu ergeben, doch das Getränk enttäuschte ihn. Nun setzt er auf eine gefährlichere Zutat.",al={"warum raptorhörner versagten","raptorhorngetränk"}},{q="Was ist Klageessenz?",a="Klageessenz ist ektoplasmatische Flüssigkeit aus seltsamen Schleimen tief in den Höhlen des Wehklagens. Mebok glaubt, dass sie die ungewöhnlichen Veränderungen an Pflanzen und Tieren verursacht, die sich im Brachland ausbreiten.",al={"was ist klageessenz","essenz aus den höhlen des wehklagens"}},{q="Wo findet Ihr die Ektoplasmen, die die Essenz in sich tragen?",a="Ihr könnt die Essenz von sich entwickelnden, verschlingenden und alptraumhaften Ektoplasmen in den unterirdischen Gängen der Höhlen des Wehklagens westlich von Ratschet sammeln.",al={"wo sind ektoplasmen","klugheitstränke gegner","wer lässt klageessenz fallen"}},{q="Kann man den Klugheitstrank bedenkenlos trinken?",a="Die Essenz stammt von alptraumhaften Schleimen, die mit verderblichen Mutationen im ganzen Brachland in Verbindung stehen, sie als Stärkungsmittel abzufüllen ist also leichtsinnig. Mebok liegt mehr daran, das Getränk zu verkaufen, als seine Kunden zu schützen.",al={"ist der klugheitstrank giftig","wirkt das getränk"}},{q="Was folgt nach dem Abschluss von Klugheitstränke?",a="Nachdem Ihr Klageessenz abgeliefert habt, betrachtet Mebok sein aktuelles Getränkevorhaben als abgeschlossen. Er belohnt Euch und verspricht Euch einen Anteil an künftigen Gewinnen, falls ihm sein Stärkungsmittel ein Vermögen einbringt.",al={"klugheitstränke folgequest","was kommt nach klugheitstränke"}}},fx={b3462a0e={q="Warum will Mebok Mizzyrix die Klageessenz?",a="Mebok Mizzyrix ist ein ehrgeiziger Goblin-Unternehmer in Ratschet, der entschlossen ist, reich zu werden. Nachdem sein erster Versuch mit Raptorhörnern kein intelligenzsteigerndes Getränk hervorbrachte, verlagerte er sich auf eine weitaus flüchtigere Zutat. Da er glaubt, dass die seltsamen Mutationen, die die Flora und Fauna des Brachlands verzerren, von den potenten Energien in der Klageessenz stammen, beabsichtigt er, diese direkt in seine Gebräue zu mischen und sie als wundersame Smart Drinks für einen immensen persönlichen Gewinn zu verkaufen.",al={"mebok motiv","warum will mebok smart drinks","warum smart drinks herstellen"}},["6730f7d3"]={q="Was sind die Ektoplasmen, die die Essenz tragen?",a="Die Ektoplasmen sind seltsame, schlammartige Manifestationen, die tief in den Höhlen des Wehklagens hausen. Während flüchtige, korrupte Energien unter den Oasenspalten zusammenlaufen, gefriert die lokale unterirdische Essenz zu sich entwickelnden, verschlingenden und albtraumhaften spektralen Schleimen. Diese geistlosen Entitäten absorbieren das urzeitliche, mutagenische Summen der Höhlen und konzentrieren die seltsame Klageessenz in ihren sich verändernden Formen, bis sie geerntet werden.",al={"was für ektoplasmen","höhlen des wehklagens ektoplasma","wer hält die essenz"}}},fp="12,184,21.302.0,19.317.0,22.128.0,33.171.0,24.187.0,54.145.0,35.201.0,41.179.0"}
P.entries["quest:1492"] = {n="Werftmeister Flunkerblick",s="Am Pier von Ratschet findet Werftmeister Flunkerblick eine Passage für eine Kiste mit Alchemievorräten. Sie soll an Bord eines Schiffes zur Schwarzmeerbucht in die Alte Welt gelangen.",h="Am Pier von Ratschet findet Werftmeister Flunkerblick eine Passage für eine Kiste mit Alchemievorräten.",kw={"schwarzmeerbucht","docks","pier","ratschet","gesicherte kiste","schiffstransport","brachland","werftmeister flunkerblick"},ang={["faction:Horde"]="Als Abenteurer der Horde könnt Ihr auf Eurem Weg durch das Brachland Fracht nach Ratschet tragen und die Seewege zwischen Kalimdor und den Östlichen Königreichen kennenlernen."},sec={{t="Ein Kurier zum Hafen",b="Eine Kiste mit Tränken und Reagenzien wartet am Hafen im Brachland auf den Transport zu Kollegen in der Alten Welt. Die Karawanen, die sie hätten mitnehmen können, sind bereits abgereist. Deshalb werdet Ihr gebeten, die gesicherte Sendung ans Wasser in Ratschet zu bringen. Von dort überqueren Schiffe das große Meer zwischen Kalimdor und den Östlichen Königreichen."},{t="Die Docks von Ratschet",b="Auf den Holzstegen von Ratschet geht Fracht durch die Hände von Werftmeister Flunkerblick. Er verzeichnet jede Sendung in Hauptbüchern und Frachtmanifesten und findet dann Platz auf Schiffen, die ostwärts über das große Meer fahren. Diese Kiste ist für ein Schiff mit Kurs auf die Schwarzmeerbucht gebucht."}},faq={{q="Wer ist Werftmeister Flunkerblick?",a="Am Hauptpier von Ratschet verwaltet Werftmeister Flunkerblick den Hafen. Er kümmert sich um Schiffsmanifeste, Frachträume und Passagen zwischen Kalimdor und den Häfen jenseits des Meeres.",al={"werftmeister flunkerblick","wer ist flunkerblick","wo ist flunkerblick"}},{q="Wohin wird die Kiste geschickt?",a="Die Kiste mit Tränken und Reagenzien ist für die Alte Welt bestimmt. Sie wird an Bord des nächsten Schiffes reisen, das von Ratschet zur Schwarzmeerbucht fährt.",al={"wohin geht die kiste","schwarzmeerbucht","ziel der kiste"}},{q="Wo liegt Ratschet?",a="Ratschet liegt an der Ostküste des Brachlands, in einer geschützten Bucht direkt östlich der zentralen Wegkreuzung.",al={"lage von ratschet","wie findet man ratschet"}},{q="Warum Fracht über einen Goblinhafen verschicken?",a="Ratschet ist ein neutraler Hafen, der der Horde und unabhängigen Händlern offensteht. Seine regelmäßigen Schifffahrtsrouten führen über das große Meer und umgehen militärische Blockaden und politische Feindseligkeiten.",al={"warum ratschet","warum einen goblinhafen nutzen"}},{q="Was befindet sich in der gesicherten Kiste?",a="Die gesicherte Kiste enthält fertige Tränke, Handwerksreagenzien und andere alchemistische Waren für Kollegen in den Östlichen Königreichen.",al={"kisteninhalt","was ist in der kiste"}},{q="Wer schickt die Sendung an Flunkerblick?",a="Ein Alchemiekundiger im Brachland schickte die Sendung, nachdem er die abreisende Karawane verpasst hatte. Ein zuverlässiger Bote wird gebraucht, der den Pier vor der nächsten Flut erreicht.",al={"wer gibt die quest","questgeber"}}},fx={["14e5c3eb"]={q="Warum muss diese Kiste für Apotheker Helbrim zu Werftmeister Dizzywig gebracht werden?",a="Apotheker Helbrim am Wegekreuz muss seinen Gefährten in Old World eine Kiste mit Tränken, Reagenzien und anderen Gegenständen schicken. Er hat kaum Zeit, sie selbst zu den Docks von Ratschet zu bringen, und die letzte Karawane ist bereits aufgebrochen. Indem er Euch die Kiste übergibt, stellt er sicher, dass sie das nächste Schiff zur Schwarzmeerbucht erreicht.",al={"warum die gesicherte kiste schicken","ak'zeloth beweggrund dizzywig","warum kiste nach ratschet liefern"}},c036c897={q="Warum bittet Apotheker Helbrim einen Abenteurer, statt die Lieferung selbst zu übernehmen?",a="Apotheker Helbrim hat zu wenig Zeit, um selbst vom Wegekreuz zur Küste zu reisen. Da die letzte Karawane bereits aufgebrochen ist, kann er sich nicht auf den üblichen Transport verlassen. Einen Reisenden anzuwerben ist sein einziger verlässlicher Weg, die Kiste zu den Docks zu bringen, bevor das Schiff mit der nächsten Flut ausläuft.",al={"warum wird man zu dizzywig geschickt","warum kann ak'zeloth die kiste nicht liefern","warum geht akzeloth nicht nach ratschet"}}},fp="20,158,21.303.0,15.252.0,28.158.0,30.138.0,25.103.0,37.159.0,32.126.0,35.164.0"}
P.entries["quest:1498"] = {n="Weg der Verteidigung",s="An der Fernwacht lehrt Uzzek junge Krieger der Horde, jene zu verteidigen, die sich nicht selbst verteidigen können. Er schickt sie zum Donnergrat, um ihre Ausdauer im Kampf gegen die elektrischen Bestien dort zu prüfen.",h="An der Fernwacht lehrt Uzzek junge Krieger der Horde, jene zu verteidigen, die sich nicht selbst verteidigen...",kw={"brachland","durotar","fernwacht","weg der verteidigung","versengte schuppen","donnerechsen","donnergrat","uzzek"},ang={["class:Warrior"]="Als Krieger beginnt Ihr, die Disziplin der Verteidigung zu erlernen. Wahre Stärke im Kampf liegt darin, Eure Verbündeten vor Vernichtung zu bewahren.",["faction:Horde"]="An der Fernwacht schützen Wachen der Horde die Straße ins Brachland. Ihre Widerstandskraft ist für die Sicherheit der Horde von Bedeutung."},sec={{t="Der Schild der Horde",b="An der Fernwacht lehrt Uzzek junge Krieger, dass die Horde zur Verteidigung verpflichtet ist. Der Posten liegt an der Grenze zwischen dem Brachland und Durotar. Er sagt, die höchste Berufung eines Kriegers sei es, zwischen der Gefahr und jenen zu stehen, die sich nicht selbst verteidigen können. Sie stecken die Schläge ein, damit die Horde bestehen kann."},{t="Prüfung des Donners",b="Uzzek schickt die Novizen nach Norden über den Südstrom zum Donnergrat in Durotar, um ihre Ausdauer und Entschlossenheit zu prüfen. Donnerechsen und Blitzbälger durchstreifen die Schlucht. Die Initianden müssen die Stromstöße der Bestien ertragen und deren versengte Schuppen sammeln. Diese Prüfung zeigt, dass sie die Standhaftigkeit besitzen, die vorderste Front zu halten."}},faq={{q="Wer vergibt die Quest „Weg der Verteidigung“?",a="Veteran Uzzek vergibt die Prüfung an der Fernwacht, an der Grenze zwischen Durotar und dem östlichen Brachland.",al={"questgeber","wer startet weg der verteidigung","uzzek standort"}},{q="Wo liegt der Donnergrat?",a="Der Donnergrat liegt im Westen Durotars, nördlich der Hauptstraße und jenseits der Brücke über den Südstrom. Aggressive Donnerechsen und Blitzbälger durchstreifen seine Schlucht.",al={"donnergrat lage","wo sind donnerechsen","versengte schuppen fundort"}},{q="Warum verlangt Uzzek ausdrücklich versengte Schuppen?",a="Uzzek verlangt versengte Schuppen von den Bestien am Donnergrat, die Stromstöße austeilen. Ihre elektrischen Angriffe auszuhalten, beweist, dass ein Krieger die nötige Zähigkeit und Widerstandskraft besitzt, um fortgeschrittene Verteidigungstechniken zu erlernen.",al={"warum versengte schuppen","zweck der schuppen"}},{q="Welche philosophische Lehre steckt hinter dieser Prüfung?",a="Uzzek lehrt, dass die Pflicht eines Kriegers nicht nur darin besteht, zu töten, sondern auch darin, andere zu schützen. Den Zorn der Bestien zu überleben, hilft den Initianden dabei, schwächere Verbündete zu beschützen.",al={"kriegerphilosophie","hintergrund von weg der verteidigung","hintergrund der verteidigungshaltung"}},{q="Was folgt nach dem Abschluss von „Weg der Verteidigung“?",a="Nachdem Ihr Uzzek Eure Standhaftigkeit in der Verteidigung bewiesen habt, schickt er Euch zu Thun'grim Brandblick, um Eure Kampfausbildung fortzusetzen.",al={"nächste quest","was folgt nach weg der verteidigung","fortsetzung"}},{q="Können auch Nichtkrieger diese Prüfung ablegen?",a="Nein. Dieser Ritus ist für Krieger bestimmt. Er prüft die Rekruten und vermittelt ihnen die Grundlagen des Wachdienstes und des Verteidigungskampfes.",al={"ist das nur für krieger","wer kann diese quest machen"}}},fx={["47a57f01"]={q="Welche Kreaturen müsst Ihr am Donnergrat jagen?",a="Uzzek schickt Euch gegen die Donner-Echsen und Blitzhäuter, die am Donnergrat im Durotar hausen. Diese gewaltigen Bestien setzen knisternde elektrische Angriffe ein, die gewöhnliche Verteidigungslinien einfach durchschlagen. Wenn Ihr ihnen gegenübertritt, müsst Ihr unaufhörliche physische und elementare Angriffe überstehen, um zu beweisen, dass Eure Konstitution und Eure Entschlossenheit stark genug sind, um die Horde zu schützen.",al={"was bekämpft man am donnergrat","ziele für path of defense","donnerechsen und blitzhäuter"}},["3d8ed519"]={q="Warum prüft Uzzek Euch, anstatt die Aufgaben selbst zu erledigen?",a="Uzzek ist ein Ausbilder an der Fernwacht, dessen Pflicht es ist, angehende Krieger zu prüfen, nicht Trophäen für sich selbst zu sammeln. Die primäre Berufung eines Kriegers in der Horde besteht darin, als lebender Schild für schwächere Brüder zu dienen. Uzzek kann defensive Techniken nicht einfach jedem weitergeben, der danach fragt; Ihr müsst persönlich die Widerstandsfähigkeit demonstrieren, die erforderlich ist, um bestrafende Schläge auszuhalten, bevor er Euch seiner Lehren für würdig erachtet.",al={"warum werde ich geschickt","warum braucht uzzek mich","warum muss ich die echsen jagen"}}},fp="15,187,23.298.0,16.317.0,36.107.0,31.173.0,49.201.0,51.159.0,49.121.0,38.107.0"}
P.entries["quest:1499"] = {n="Üble Familiare",s="Im Tal der Prüfungen stellt Ruzan Hexenmeisterneulinge auf die Probe, indem er sie gegen üble Familiare antreten lässt. Nachdem Ihr sie getötet habt, erstattet Ihr Zureetha Fernblick Bericht, die den Kampf gegen die Burning Blade leitet.",h="Im Tal der Prüfungen stellt Ruzan Hexenmeisterneulinge auf die Probe, indem er sie gegen üble Familiare...",kw={"koven der brennenden klinge","durotar","wichtel","ruzan","the den","das tal der prüfungen","üble familiare","hexenmeisterquest","zureetha fernblick"},ang={["class:Warlock"]="Als Hexenmeister stellt Ihr Euch üblen Familiaren, um zu beweisen, dass Ihr wilde Teufelskreaturen beherrschen und vernichten könnt, ohne ihnen zum Opfer zu fallen.",["race:Orc"]="Als Orc wisst Ihr, dass dämonische Familiare an die dunklen Pakte erinnern, die Euer Volk einst versklavten. Sie von Durotars Boden zu vertreiben, ist für das Überleben Eures Volkes von Bedeutung.",["race:Troll"]="Als Dunkelspeertroll teilt Ihr das Tal der Prüfungen mit anderen, die dämonischer Magie zutiefst misstrauen. Ihr zeigt Eure Treue, indem Ihr Euch abtrünnigen Kultisten entgegenstellt."},sec={{t="Eine Frage der Disziplin",b="Krieger und Späher im Tal der Prüfungen unterstehen Zureetha Fernblick. Sie schickt sie aus, um den Koven der Brennenden Klinge einzudämmen. Hexenmeisterneulinge unterstehen zunächst Ruzan, ihrem schattenhaften Mentor. Er verlangt einen Beweis dafür, dass Ihr niedere Dämonen beherrschen könnt, bevor er Euch zurückschickt, um die Verteidigung der Horde zu unterstützen. Eure Arbeit hilft den Hexenmeistern und trägt zur Sicherheit von Den bei."},{t="Die Bedrohung des Kovens",b="Zureetha Fernblick beobachtet die nördliche Höhle oberhalb des Tals der Prüfungen. Darin verbergen sich üble Familiare, die schwächsten Begleiter der Kultisten der Burning Blade. Ihre Anwesenheit beleidigt die Orcs und bedroht die heiligen Ausbildungsstätten. Wenn Ihr Euren Erfolg meldet, zeigt Ihr, dass jene, die Teufelsmagie wirken, bereit sind, Durotar vor Verderbnis zu verteidigen."}},faq={{q="Warum schickt Ruzan mich zu Zureetha Fernblick, statt mich selbst zu belohnen?",a="Zureetha Fernblick leitet die Verteidigung und die Bemühungen, die Burning Blade im Tal der Prüfungen zu dezimieren. Ruzan prüft Eure Kontrolle über niedere Teufelskreaturen und schickt Euch dann zu ihr, damit sie Euren Dienst würdigen und in die Verteidigung des Tals einbeziehen kann.",al={"warum zu zureetha","ruzan zu zureetha","warum mit zureetha sprechen"}},{q="Wer sind die üblen Familiare?",a="Üble Familiare sind niedere dämonische Wichtel und Diener, die an den Koven der Brennenden Klinge gebunden sind. Sie dienen finstereren Meistern tief in der Höhle oberhalb des Tals der Prüfungen.",al={"was sind üble familiare","geschichte der üblen familiare","familiare burning blade"}},{q="Wo finde ich Zureetha Fernblick?",a="Zureetha Fernblick steht im Freien nahe dem Zentrum von Den im Tal der Prüfungen. Vom Lager der Lehrer, in dem Ruzan sich aufhält, führt ein kurzer Weg zu ihr hinauf.",al={"wo ist zureetha","zureetha fernblick standort","zureetha karte"}},{q="Warum gibt es eine weitere Quest mit genau demselben Namen?",a="Die meisten Abenteurer erhalten Üble Familiare direkt von Zureetha Fernblick und jagen die Kreaturen für sie. Hexenmeister erhalten einen eigenen Auftrag von Ruzan und erstatten Zureetha nach dessen Abschluss Bericht.",al={"zwei quests üble familiare","üble familiare doppelt","hexenmeister üble familiare"}},{q="Was macht die Burning Blade im Tal der Prüfungen?",a="Der Kult der Burning Blade agiert in geheimen Zellen in ganz Durotar und versucht, Thralls neue Horde von innen heraus zu untergraben. Von einer Höhle im Tal der Prüfungen aus machen seine Mitglieder Jagd auf unerprobte Neulinge und verbreiten unter den Augen der orcischen Aufseher dämonische Verderbnis.",al={"burning blade tal der prüfungen","warum kultisten in den"}},{q="Wird der Kult ausgelöscht, wenn diese Familiare getötet werden?",a="Nein. Üble Familiare sind Begleiter und Späher der finstereren Mächte innerhalb des Kovens. Mit ihrem Sieg beginnt die Arbeit, die tiefer verborgene Bedrohung durch die Kultisten im Tal aufzudecken und zu beseitigen.",al={"ist die burning blade besiegt","sind die kultisten verschwunden"}}},fp="14,181,22.338.0,23.341.0,75.250.0,27.166.0,34.155.0,52.189.0,56.267.0,47.175.0"}
P.entries["quest:15"] = {n="Überprüfung der Echokammmine",s="Kobolde sammeln sich in großer Zahl bei der Echokammmine, also schickt Marschall McBride Euch nach Norden. Die Mine versorgt die Abtei von Nordhain und die dort stationierte Wache von Sturmwind mit Erz und Rohstoffen.",h="Kobolde sammeln sich in großer Zahl bei der Echokammmine, also schickt Marschall McBride Euch nach Norden.",kw={"echo ridge","elwynn","kobold","koboldarbeiter","marschall mcbride","mine","nordhain","nordhaintal"},ang={["faction:Alliance"]="Kobolde sind dem geistlichen Herzen Sturmwinds in Nordhain nahe gekommen. Ihre Anwesenheit zeigt die Verwundbarkeit des Königreichs, während seine regulären Truppen an zu vielen Orten gebraucht werden.",["profession:Mining"]="Kupfer aus der Echokammmine ist für Nordhains Schmiede unverzichtbar. Die Räumung ihrer unterirdischen Stollen ist für den Lebensunterhalt der Bergleute von Bedeutung.",["race:Human"]="Als junger Mensch, der seinen Dienst im Nordhaintal beginnt, bietet Euch die Verteidigung von Echo Ridge gegen unterirdische Schädlinge eine frühe Gelegenheit, Euch vor dem Königreich zu beweisen."},sec={{t="Ein tiefer reichender Befall",b="Vereinzeltes Ungeziefer hat den bewaldeten Rand des Tals nahe Nordhain heimgesucht. Nun berichten die Späher von einer besser organisierten Ansammlung. Am Eingang stellt Ihr Euch Koboldarbeitern und seht, wie tief sie sich bereits in der Mine eingenistet haben."},{t="Bedrohter Reichtum der Abtei",b="Die Kobolde haben die Stollen besetzt und den Abbau zum Erliegen gebracht. Ihre Anwesenheit belastet die Verteidigung der Bruderschaft von Nordhain. McBride bittet Euch, zehn Arbeiter zu töten, doch der Befall reicht tiefer in die Schächte, als eine Patrouille an der Oberfläche vordringen kann."}},faq={{q="Wer schickt mich auf diese Mission?",a="Marschall McBride, Befehlshaber der Wachen von Sturmwind an der Abtei von Nordhain, schickt Euch nach Norden, nachdem Späher dort Ansammlungen von Kobolden gemeldet haben.",al={"questgeber","wer vergibt die quest","marschall mcbride"}},{q="Wo liegt die Echokammmine?",a="Die Echokammmine liegt ganz im Norden des Nordhaintals, in den Ausläufern der Berge oberhalb der Abtei und ihrer Weinberge.",al={"lage von echo ridge","wo ist die mine","echo ridge finden"}},{q="Warum sind Kobolde für Nordhain gefährlich?",a="Kobolde vermehren sich rasch und strömen in riesigen Rudeln durch unterirdische Stollen. Ihre Besetzung der Echokammmine verhindert den lebenswichtigen Bergbau und droht, das mit zu wenigen Verteidigern besetzte Tal von Nordhain zu überrennen.",al={"warum kobolde töten","was macht kobolde zur bedrohung","gefahr durch kobolde"}},{q="Was geschieht, nachdem ich die Arbeiter draußen besiegt habe?",a="Bei Eurer Rückkehr bestätigen sich Marschall McBrides schlimmste Befürchtungen: Die Mine ist völlig von Kobolden befallen. Für einen tieferen Vorstoß in die Schächte bittet er Euch in Skirmish at Echo Ridge um Hilfe.",al={"wie geht es weiter","folgequest","nächste quest"}},{q="Warum vertreibt die Armee von Sturmwind die Kobolde nicht selbst aus der Mine?",a="Da König Varian Wrynn verschwunden ist und die Mittel in Elwynn und den benachbarten Grenzgebieten knapp sind, kann Nordhains kleine Garnison keine vollständigen Patrouillen zur Schädlingsbekämpfung entbehren. Die Wachen verlassen sich auf fähige neue Rekruten.",al={"wo sind die wachen von sturmwind","warum rekruten einsetzen","garnison von sturmwind"}},{q="Welche Art von Kobolden findet man rund um den Mineneingang?",a="Koboldarbeiter schuften rund um den Mineneingang und in den oberen Gängen. Sie graben Stollen und sammeln Kerzenwachs für ihre unterirdische Kolonie.",al={"koboldarten","welche feinde töten","koboldarbeiter"}}},fx={ffd728b0={q="Warum will Marschall McBride, dass die Echokammmine untersucht wird?",a="Die Späher von Marschall McBride haben entdeckt, dass der Koboldbefall weit größer ist, als die Garnison in Nordhain ursprünglich annahm. Die Kreaturen haben ihre kleinen Lager verlassen und sich in der Nähe der Echokammmine niedergelassen, womit sie eine lebenswichtige lokale Ressource bedrohen. McBride braucht Euch, um ihre vordersten Reihen auszudünnen und einzuschätzen, ob sich eine noch größere Streitmacht tiefer in der Mine verschanzt, bevor die Verteidigung des Tals komplett überrannt wird.",al={"warum echokammmine säubern","mcbrides motiv","warum echokammmine untersuchen"}}},fp="22,180,23.217.0,28.245.0,29.132.0,37.111.0,40.183.0,48.180.1,57.216.0,56.134.0"}
P.entries["quest:150"] = {n="Murlocwilderer",s="Am Immerruhsee fischen Murlocs die Gewässer von Seenhain leer. Dockmaster Baren bittet Euch, ihre Reihen auszudünnen, bevor die Stadt ihre Hauptnahrungsquelle verliert.",h="Am Immerruhsee fischen Murlocs die Gewässer von Seenhain leer.",kw={"dockmaster baren","zwergische angelrute","der immerruhsee","seenhain","murlocflosse","poachers","rotkammgebirge"},ang={["faction:Alliance"]="Seenhain wird bereits von Schwarzfelsorcs und Gnollen stark bedrängt, sodass der Allianzstadt kaum Verteidigungskräfte bleiben, um ihre lebenswichtige Nahrungsquelle im Immerruhsee zu schützen.",["race:Human"]="Als Mensch wisst Ihr, dass das Rotkammgebirge einst ein beschauliches Urlaubsparadies für das Königreich Sturmwind war. Feindselige Murlocs überrennen nun seine unberührten Berggewässer, ein Zeichen dafür, wie weit die Ordnung bereits verfallen ist."},sec={{t="Gefahr für die Vorratskammer",b="Dockmaster Baren bittet Euch, die Fische zu schützen, die Seenhain ernähren. Der Immerruhsee versorgt die Bergstadt und ihren Markt mit frischem Fang. Große Murlocstämme drängen sich nun im flachen Wasser und durchkämmen es nach Nahrung. Wenn sie ungehindert weitermachen, könnten sie die örtlichen Fischbestände ausrotten und Seenhain seiner Hauptnahrungsquelle berauben."},{t="Seltsamer Zug ins Binnenland",b="Murlocs suchen gewöhnlich an der Küste nach Nahrung, weshalb ihre große Zahl hoch oben im Rotkammgebirge schwer zu erklären ist. Dockmaster Baren fragt sich, warum sie sich so weit vom offenen Meer entfernt haben. Vielleicht fliehen sie vor Meeresräubern, unterliegen in Revierkämpfen oder werden von den fischreichen Gewässern des Immerruhsees angelockt. Was auch immer sie ins Binnenland geführt hat, ihre Anwesenheit deutet auf Schwierigkeiten anderswo in der Region hin."}},faq={{q="Wer ist Dockmaster Baren?",a="Dockmaster Baren beaufsichtigt die Docks und den Fischereiverkehr am Ufer des Immerruhsees bei Seenhain. Er kümmert sich um Vorräte, die auf dem Wasserweg eintreffen, und heuert Euch an, die Ressourcen des Sees vor Bedrohungen aus dem Wasser zu schützen.",al={"baren","wer vergibt murlocwilderer","dockmaster baren"}},{q="Warum sind Murlocs im Rotkammgebirge?",a="Murlocs leben gewöhnlich an Küsten und in Marschen, daher ist ihre Anwesenheit am hoch gelegenen Immerruhsee ungewöhnlich. Dockmaster Baren vermutet, dass die Stämme ins Binnenland kamen, um etwas Schlimmerem an den Küsten zu entkommen.",al={"warum sind murlocs im immerruhsee","murlocs im binnenland rotkammgebirge","warum fischmenschen im see"}},{q="Welche Gefahr stellen die Murlocs für Seenhain dar?",a="Seenhain ist für seinen Fischfang und Handel auf den Immerruhsee angewiesen. Murlocstämme überfischen seine Gewässer und bedrohen damit die Hauptnahrungsquelle der Stadt und den örtlichen Handel.",al={"warum murlocs töten","murlocproblem seenhain","immerruhsee fischbestände erschöpft"}},{q="Warum sammelt Dockmaster Baren Murlocflossen?",a="Dockmaster Baren sammelt acht Murlocflossen als Beweis dafür, dass Ihr die Stämme am Ufer dezimiert und geholfen habt, ihren Vormarsch einzudämmen.",al={"warum murlocflossen","flossen kopfgeld seenhain"}},{q="Gibt es weitere Aufgaben rund um die Murlocs am Immerruhsee?",a="Ja. Dockmaster Baren bietet auch Selling Fish an, wobei Ihr ihm die berühmten Gefleckten Sonnenfische des Sees bringen sollt, geangelt oder den Murlocs abgenommen.",al={"selling fish quest zusammenhang","weitere murlocquests rotkammgebirge"}},{q="Welche Belohnung gibt Dockmaster Baren für die Beseitigung der Wilderer?",a="Nachdem Ihr ihm acht Flossen gebracht habt, gibt Euch Dockmaster Baren eine gut gearbeitete Zwergische Angelrute, um Euch zur Pflege der Gewässer des Sees anzuspornen.",al={"murlocwilderer belohnung","zwergische angelrute quest"}}},fx={["04b19c02"]={q="Warum will Dockmeister Baren, dass die Murlocs gejagt werden?",a="Baren beaufsichtigt die Docks und den Fischhandel am Immerruhsee. Die wachsenden Murloc-Rudel entlang der Ufer wildern aggressiv in den Gewässern und drohen, die primäre lokale Nahrungsquelle der Stadt zu erschöpfen, bevor jemand sie aufhalten kann.",al={"barens motiv","warum murlocs ausdünnen","warum plünderer töten"}},["38e35746"]={q="Wofür wird die Murlocflosse verwendet?",a="Die Flossen dienen als physischer Beweis für die Ausdünnung. Baren hat keine besondere Handwerkskunst oder Alchemie für sie im Sinn; das Sammeln von acht abgetrennten Flossen garantiert lediglich, dass Ihr die Plünderer zurückgeschlagen habt, welche die Fischbestände im Immerruhsee dezimieren.",al={"nutzen der murlocflosse","wofür ist die murlocflosse","warum murlocflossen"}},["4daf19f8"]={q="Wer sind die Murloc Poachers, die am Immerruhsee ins Visier genommen werden?",a="Ihr jagt die eindringenden Murlocs, die sich an den östlichen Ufern des Immerruhsees versammelt haben. Ungewöhnlich weit von den Meeresküsten entfernt, haben diese amphibischen Raubtiere begonnen, Lager zu errichten und die Süßwasserfische des Sees zu verschlingen.",al={"wer sind die plünderer","ziel der murloc plünderer","warum sind murlocs am immerruhsee hier"}}},fp="15,161,29.317.0,24.382.0,24.202.0,38.209.0,45.156.0,46.132.0,57.152.0,65.135.0"}
P.entries["quest:1501"] = {n="Kreatur der Leere",s="In Orgrimmar schickt Gan'rul Blutauge einen jungen Hexenmeister aus, um die gestohlene Schrifttafel der Verga zurückzuholen. Kultisten der Burning Blade haben sie in ihr Versteck in der Knochenhöhle gebracht, wo ihre Runen zur Beschwörung eines Leerwandlers benötigt werden.",h="In Orgrimmar schickt Gan'rul Blutauge einen jungen Hexenmeister aus, um die gestohlene Schrifttafel der Verga...",kw={"burning blade","die kluft der schatten","kreatur der leere","gan'rul blutauge","orgrimmar","die knochenhöhle","schrifttafel der verga","leerwandler","hexenmeisterquest"},ang={["class:Warlock"]="Als Hexenmeister steht Euch ein Übergangsritus bevor: Über kleine Wichtel hinauszuwachsen und einen Schattendiener an vorderster Front zu befehligen.",["faction:Horde"]="Als Mitglied von Thralls Horde gehört Ihr einem Volk an, das jenen misstraut, die Teufelsmagie wirken. Mentoren wie Gan'rul lehren Schüler der dunklen Künste, ihre Macht im Dienst des Kriegshäuptlings einzusetzen.",["race:Orc"]="Als Ork, den die Geschichte des Shadow Council verfolgt, könnt Ihr bei der Jagd auf die Burning Blade ein wenig Rache finden, deren Mitglieder sich noch immer dem dämonischen Verderben verschreiben."},sec={{t="Eine gefährliche Kunst",b="Gan'rul Blutauge bildet in der Kluft der Schatten Hexenmeister der Horde aus. Thralls neues Reich misstraut der Teufelsmagie wegen der dunklen Geschichte der orkischen Clans. Nur wenige wahre Hexenmeister seien in der Horde verblieben, sagt Gan'rul, doch ihre gefährlichen Fertigkeiten werden für ihr Überleben gebraucht. Um dem Kriegshäuptling zu dienen, muss ein Initiand mehr beherrschen als das chaotische Feuer eines Wichtels. Er muss Wesen aus reinem Schatten und purer Zähigkeit befehligen."},{t="Die gestohlene Schrifttafel",b="Die Runen zur Beschwörung eines Leerwandlers sind in die Schrifttafel der Verga gemeißelt. Die Burning Blade, ein fanatischer Schattenkult, hat das Relikt gestohlen und verbirgt sich direkt unter der Nase des Kriegshäuptlings in der Knochenhöhle. Gan'rul schickt Euch in ihren Schlupfwinkel, um es zurückzuholen und den Abtrünnigen, die den Namen jedes Hexenmeisters beschmutzen, einen blutigen Schlag zu versetzen."}},faq={{q="Wer ist Gan'rul Blutauge?",a="Gan'rul Blutauge ist ein hochrangiger Hexenmeisterlehrer in Orgrimmars Kluft der Schatten. Er lehrt junge Hexenmeister der Horde, dunkle Mächte zu beherrschen und außerweltliche Diener zu binden, ohne der Verderbnis zu verfallen.",al={"gan'rul","ganrul blutauge","wer vergibt diese quest"}},{q="Was ist die Schrifttafel der Verga?",a="Die Schrifttafel der Verga trägt die Runen, die benötigt werden, um einen Leerwandler aus dem Nether zu beschwören. Die Burning Blade hat sie gestohlen, und Gan'rul braucht sie, um den Initianden durch das Ritual zu führen.",al={"schrifttafel der verga","was ist die schrifttafel"}},{q="Wo liegt die Knochenhöhle?",a="Die Knochenhöhle liegt direkt östlich von Orgrimmar an den zerklüfteten Steilhängen Durotars. Kultisten der Burning Blade verstecken sich dort.",al={"knochenhöhle standort","wo liegt die knochenhöhle","wo ist die schrifttafel"}},{q="Warum verachtet Gan'rul Blutauge die Burning Blade?",a="Die Burning Blade dient dämonischen Meistern und arbeitet gegen Thralls Horde. Gan'rul betrachtet den Kult als Ärgernis für den Kriegshäuptling und als rücksichtslose Plage, die alle Hexenmeister in Verdacht und Verruf bringt.",al={"burning blade hexenmeister","warum burning blade hassen"}},{q="Warum müssen Hexenmeister einen Leerwandler beschwören?",a="Leerwandler sind Wesen aus dem Nether, die gewaltigen Schaden einstecken und ihren Beschwörer schützen können. Zu lernen, einen zu binden, ist für das Überleben und die Beschwörungsmacht eines Hexenmeisters unerlässlich.",al={"warum leerwandler","leerwandler zweck"}},{q="Was geschieht nach der Rückkehr mit der Schrifttafel?",a="Wenn Gan'rul die Schrifttafel der Verga erhält, gibt er dem Initianden die nötigen Runen und fordert ihn auf, das Ritual in 'The Binding' abzuschließen. Dort muss der Hexenmeister den beschworenen Leerwandler eigenhändig unterwerfen, um ihn zu beherrschen.",al={"nächste quest","what comes next"}}},fx={b65e3db1={q="Warum will Gan'rul Blutauge, dass das erledigt wird?",a="Gan'rul Blutauge spürt den akuten Druck, da es nur noch sehr wenige Hexenmeister in der Horde gibt. Er glaubt, dass es entscheidend ist, vielversprechende Akolythen wie Euch schnell reifen zu lassen, um der Horde und dem Kriegshäuptling zu dienen. Die Wiederbeschaffung der Schrifttafel der Verga fördert nicht nur Eure Ausbildung, indem sie Euch die Runen gewährt, um einen Leerwandler zu beschwören, sondern versetzt auch den Kultisten des Burning Blade, die sie gestohlen haben und ständig den Ruf aller Hexenmeister beschmutzen, einen Schlag.",al={"ganruls motiv","warum schickt euch ganrul","warum die schrifttafel bergen"}},["6701b0d8"]={q="Gegen wen werdet Ihr bei Die Knochenhöhle ausgesandt?",a="Ihr werdet gegen die Kultisten des Burning Blade ausgesandt, die sich in Die Knochenhöhle verstecken, östlich von Orgrimmar. Diese abtrünnigen Hexenmeister konspirieren gegen die Horde und haben die Schrifttafel der Verga von Gan'rul gestohlen. Sie operieren im Schatten von Durotar, nutzen dämonische Magie außerhalb des Gesetzes des Kriegshäuptlings und verursachen ständigen Ärger für die junge Nation.",al={"wer ist in der knochenhöhle","burning blade die knochenhöhle","wer hat die schrifttafel gestohlen"}},["2e9ce581"]={q="Warum schickt Gan'rul Blutauge Euch anstelle der Stadtwachen?",a="Die Dunkelfeuer-Enklave operiert unter angespannter Toleranz innerhalb von Thralls Orgrimmar. Die Stadtwache dazu aufzurufen, gestohlene okkulte Artefakte aufzuspüren, würde unerwünschte Aufmerksamkeit auf Gan'ruls verdeckte Praktiken ziehen. Noch wichtiger ist, dass die Konfrontation mit den Prüfungen von Die Knochenhöhle ein notwendiger Test Eurer wachsenden Macht ist: Ein Hexenmeister muss beweisen, dass er fähig ist, der dämonischen Verderbnis entgegenzutreten, bevor ihm vertraut wird, eine Kreatur of the Void zu beschwören und zu binden.",al={"warum einen lehrling schicken","warum keine wachen schicken","warum ich creature of the void"}}},fp="20,212,16.387.0,17.324.0,24.196.0,28.173.0,20.116.0,52.201.0,44.180.0,41.214.1"}
P.entries["quest:1502"] = {n="Thun'grim Brandblick",s="Auf dem Dornenhügel zieht eine einsame Schmiede Krieger zu Thun'grim Brandblick. Nach ihren ersten Lektionen in der Verteidigung durchqueren Krieger der Horde das Brachland auf der Suche nach Stahl, der ihrem wachsenden Können entspricht.",h="Auf dem Dornenhügel zieht eine einsame Schmiede Krieger zu Thun'grim Brandblick.",kw={"schmied","das wegekreuz","forged steel","brachland","dornenhügel","thun'grim brandblick","uzzek","kriegerwaffe"},ang={["class:Warrior"]="Als junger Krieger der Horde werdet Ihr in die Wildnis geschickt, um Thun'grim zu finden und Euch eine unverwechselbare geschmiedete Waffe als Ergänzung Eurer Kampfausbildung zu verdienen.",["faction:Horde"]="Die Horde ist auf erfahrene Handwerker angewiesen, deren hochwertiger Stahl die Frontsoldaten ausrüstet, die Kalimdor verteidigen.",["profession:Blacksmithing"]="Thun'grim folgt einer einsamen orcischen Schmiedetradition. Er erträgt Abgeschiedenheit und Blindheit, um heißes Metall zu tödlichen Werkzeugen zu formen."},sec={{t="The Hermit auf dem Kamm",b="Nachdem Ihr unter erfahrenen Ausbildern wie Uzzek Euer Können in den defensiven Künsten bewiesen habt, werdet Ihr ausgesandt, um Eure Kampfkraft mit geeignetem Stahl zu schärfen. Gewöhnliche Waffenkammern können einen Frontkämpfer nur begrenzt weiterbringen. Wahre Meisterschaft verlangt nach einer persönlichen Waffe von einem namhaften Schmied. Im Brachland ist dieser Schmied Thun'grim Brandblick, ein alternder Orc, der das Siedlungsleben für eine abgelegene Schmiede hoch über den Ebenen hinter sich ließ."},{t="Ein Leben im Schmiedefeuer",b="Thun'grim Brandblick lebt auf dem Dornenhügel, einer zerklüfteten Anhöhe östlich des Wegekreuzes. Wilde Raptoren und feindselige Borstennacken streifen dort umher, fern vom Schutz der Stadtmauern. Seine einsamen Stunden verbringt er damit, Metall zu formen. Jahrzehntelanges Starren in die sengenden Flammen der Esse hat sein Augenlicht ruiniert, doch seine Instinkte sind noch immer scharf. Wenn Ihr die Höhen erklimmt und seine Einsamkeit stört, weiß er, warum: Ein Krieger ist gekommen und sucht geschmiedeten Stahl."}},faq={{q="Wer schickt Krieger zu Thun'grim Brandblick?",a="Uzzek, ein Kriegerlehrer an der Straße nahe der Fernwacht im östlichen Brachland, schickt Euch los, nachdem Ihr Eure Ausbildung in der Verteidigung unter Beweis gestellt habt.",al={"wer vergibt diese quest","wer startet thun'grim brandblick","questgeber"}},{q="Wo befindet sich Thun'grim Brandblick?",a="Thun'grim lebt an einem abgelegenen Lagerplatz auf dem Dornenhügel, einem hohen Kamm direkt östlich des Wegekreuzes im Brachland.",al={"thun'grims standort","wo ist thun'grim","brandblick finden"}},{q="Warum lebt Thun'grim allein draußen in den Hügeln?",a="Thun'grim hat sein Leben der Metallbearbeitung gewidmet, fern von den Ablenkungen der Stadt. Er arbeitet allein an seinem Amboss auf dem Dornenhügel, trotz der gefährlichen Bestien und Borstennacken auf den umliegenden Kämmen.",al={"warum ist thun'grim ein einsiedler","brandblick einsiedler"}},{q="Was ist mit Thun'grim Brandblicks Augen geschehen?",a="Jahrzehnte unablässiger Arbeit über glühenden Kohlen und die starke Hitze der Esse haben Thun'grim Brandblicks Sehkraft weitgehend zerstört.",al={"ist thun'grim blind","brandblick augen"}},{q="Was folgt auf die Begegnung mit Thun'grim Brandblick?",a="Nachdem Ihr Euch bei Thun'grim gemeldet habt, erkennt er Euren Bedarf an Waffen und bittet Euch, Rohstoffe zu sammeln, damit er eine Waffe fertigen kann.",al={"nächste quest","was folgt nach thun'grim","forged steel folgequest"}},{q="Kann jede Klasse diese Quest annehmen?",a="Nein. Dieser Weg steht Kriegern der Horde offen, die besondere Waffen suchen.",al={"nur für krieger","wer kann thun'grim brandblick machen"}}},fx={["65de68fe"]={q="Warum schickt Uzzek Euch zu Thun'grim Brandblick?",a="Uzzek weiß, dass kampftechnisches Training allein einen Krieger ohne angemessene Bewaffnung nicht am Leben erhält. Die Waffe eines Kriegers muss nach dem höchsten Standard geschmiedet sein, und Thun'grim Brandblick ist unter der Horde für seine meisterhafte Handwerkskunst bekannt. Uzzek schickt Euch aus, damit Ihr eine Waffe verdient, die Eurer wachsenden Stärke würdig ist.",al={"warum thungrim finden","uzzeks motiv thungrim","warum thungrim firegaze aufsuchen"}}},fp="18,183,23.412.0,24.421.0,46.144.0,36.117.0,47.188.0,43.129.0,44.126.0,30.61.0"}
P.entries["quest:1503"] = {n="Geschmiedeter Stahl",s="Im östlichen Brachland wartet Thun'grim Brandblick auf den Stahl, der aus seinem Lager gestohlen wurde. Er wird dem Krieger, der ihn zurückbringt, eine Waffe schmieden.",h="Im östlichen Brachland wartet Thun'grim Brandblick auf den Stahl, der aus seinem Lager gestohlen wurde.",kw={"brachland","firegaze","geschmiedeter stahl","eisentruhe","stacheleber","razormane","stahlbarren","thun'grim","kriegerwaffe"},ang={["class:Warrior"]="Als Krieger holt Ihr gestohlenen Stahl zurück und beweist Euren Wert, bevor Thun'grim Euch eine Waffe schmiedet.",["faction:Horde"]="Als Mitglied der Horde stellt Ihr Euch den Überfällen der Razormane auf Lager und Versorgungslinien im gesamten Brachland.",["profession:Blacksmithing"]="Als Schmied erkennt Ihr, warum veredelter Stahl für die Horde im rauen Grenzland Kalimdors wichtig ist."},sec={{t="Eine Sehschwäche ausgenutzt",b="Thun'grim Brandblick betreibt eine Schmiede im östlichen Brachland, fern von Orgrimmar. Die Jahre an der Esse haben seine Sehkraft getrübt. Die benachbarten Razormane-Stacheleber nutzten diese Schwäche, um eine Eisentruhe aus seinem Lager zu stehlen. Einige schnaubten und lärmten auf einer Seite, um seinen Blick auf sich zu ziehen, während andere von der anderen Seite eindrangen und seine Schmiedestahlbarren davontrugen."},{t="Kostbares Metall, ahnungslose Diebe",b="Thun'grim ist über den Diebstahl erzürnt, bezweifelt aber, dass die Razormane den Stahl nutzen können. Stacheleber verarbeiten Stein, Hauer und dornige Wurzeln, kein veredeltes Metall. Die schwere Truhe steht noch immer nahe einem zerstörten Wagen in ihrem Lager, unberührt und für sie nutzlos. Für Thun'grim ist ihr Stahl der Vorrat, den er braucht, um Waffen für junge Krieger der Horde zu schmieden."}},faq={{q="Wer ist Thun'grim Brandblick?",a="Thun'grim Brandblick ist ein Orc-Rüstungs- und Waffenschmied im östlichen Brachland. Obwohl seine Sehkraft nachlässt, arbeitet er weiter und rüstet junge Krieger der Horde aus.",al={"thungrim firegaze","wer ist der schmied","thungrim"}},{q="Warum haben die Stacheleber den Stahl gestohlen?",a="Die Razormane-Stacheleber stahlen die Eisentruhe bei einem nächtlichen Ablenkungsmanöver aus Thun'grims Lager. Ihnen fehlt das Können, um den geschmiedeten Stahl darin zu verarbeiten.",al={"warum metall stehlen","warum stahlen die stacheleber","was wollten die razormane"}},{q="Wo werden die Schmiedestahlbarren aufbewahrt?",a="Die Schmiedestahlbarren sind in der Stolen Iron Chest nahe einem zerstörten Wagen im Revier der Grimmhauer nordwestlich von Thun'grims Lager eingeschlossen.",al={"wo ist die truhe","stolen iron chest fundort","wo sind die barren"}},{q="Welche Waffe bietet Thun'grim als Gegenleistung an?",a="Thun'grim bietet jungen Kriegern eine Auswahl frisch geschmiedeter Waffen als Gegenleistung dafür, dass sie seinen Stahl zurückholen.",al={"belohnungswaffe","was bekomme ich","geschmiedeter stahl belohnung"}},{q="Wie konnten die Razormane Thun'grim überlisten?",a="Die Razormane nutzten Thun'grims nachlassende Sehkraft aus. Einige Angreifer schnaubten und lärmten, um seine Aufmerksamkeit auf sich zu ziehen, während andere in sein Lager schlichen und die Truhe mitnahmen.",al={"wie haben sie ihn bestohlen","wie wurde thungrim bestohlen","thungrim abgelenkt"}},{q="Warum lebt Thun'grim draußen im Brachland statt in Orgrimmar?",a="Thun'grim unterhält einen einsamen Außenposten im östlichen Brachland, wo er Krieger aus Durotar bewaffnet und anleitet.",al={"warum ist thungrim hier","warum lager im brachland"}}},fx={["46a881ef"]={q="Warum will Thun'grim Brandblick, dass die Stahlbarren geborgen werden?",a="Thun'grim ist ein Meisterschmied, und fein bearbeitetes Metall wie diese Schmiedestahlbarren ist für sein Handwerk von entscheidender Bedeutung. Dass seine Vorräte ihm von stehlenden Stachelebern direkt vor der Nase weggeschnappt wurden, hat seinen Stolz verletzt, aber schlimmer noch, es hat ihn der Materialien beraubt, die er zum Schmieden von Waffen benötigt. Er weigert sich, eine seiner geschmiedeten Waffen herauszugeben, bis sein gestohlener Vorrat wiederhergestellt ist.",al={"warum forged steel bergen","thungrims motiv","warum will thungrim den stahl zurück"}},["4f2d7c31"]={q="Warum braucht Thun'grim Euch, um den Stahl zu bergen, anstatt selbst zu gehen?",a="Thun'grims Sehkraft hat sich im Alter stark verschlechtert, eine Schwäche, die die Razormane-Stacheleber ausnutzten, als sie ihn ausraubten. Da er nicht klar genug sehen kann, um sie in ihre dornigen Bauten zu verfolgen oder sie auf Augenhöhe zu bekämpfen, verlässt er sich darauf, dass ein fähiger Krieger wie Ihr sich in die Stacheleberlager wagt und die gestohlene Truhe zurückholt.",al={"warum kann thungrim den stahl nicht holen","warum schickt thungrim mich","warum braucht thungrim hilfe"}},["758f9f11"]={q="Wer sind die Razormanes, die den Stahl festhalten?",a="Die Diebe gehören zum Razormane-Stacheleberstamm, wilden, schweineartigen Humanoiden, die im Brachland beheimatet sind. Aggressiv und stark territorial, versammeln sie sich in borstigen Dornenlagern in der gesamten Ebene und überfallen häufig Reisende und einsame Lager, um Vorräte zu plündern, obwohl sie oft wenig Verständnis dafür haben, wie man raffinierte Materialien wie Forged Steel bearbeitet.",al={"wer sind die razormanes","stacheleber nordwest","wer hat die eisengeste gestohlen"}}},fp="12,143,22.341.0,33.327.0,26.156.0,37.144.0,37.133.0,43.104.0,49.167.0,64.117.0"}
P.entries["quest:1504"] = {n="Die Bindung",s="In Orgrimmar ist die Bindung das letzte Initiationsritual für junge Hexenmeister der Horde. Gan'rul Blutauge weist jeden Anwärter an, Glyphen von der Schrifttafel der Verga in Neeru Fireblades Beschwörungskreis zu verwenden.",h="In Orgrimmar ist die Bindung das letzte Initiationsritual für junge Hexenmeister der Horde.",kw={"die kluft der schatten","gan'rul blutauge","glyphe der beschwörung","neeru fireblade","orgrimmar","schrifttafel der verga","die bindung","leerwandler","hexenmeister"},ang={["class:Warlock"]="Als Hexenmeister geht Ihr vom Experimentieren mit Wichteln dazu über, Schrecken aus Schatten an vorderster Front zu befehligen. Das Ritual lehrt, dass Macht erobert und versklavt werden muss.",["faction:Horde"]="Die Horde wendet sich offiziell von der dämonischen Verderbnis der Vergangenheit ab, duldet jedoch Hexenmeistermagie unter Orgrimmar als pragmatische Notwendigkeit unter wachsamen Augen.",["race:Orc"]="Als Orc übt Ihr die dunklen Künste in verborgenen Winkeln wie der Kluft der Schatten aus, fern vom missbilligenden Blick des Kriegshäuptlings Thrall und der schamanischen Erneuerung."},sec={{t="Unterwerfung des Void",b="Ihr stellt Euch Eurer ersten wahren Willensprüfung, wenn Ihr einen Leerwandler beschwört. Ein Wichtel ist dagegen ein Kinderspiel. Hexenmeister schließen keine Pakte mit diesen Kreaturen und treten auch nicht mit ihnen in Zwiesprache. Ihr zerrt sie mit Gewalt durch die Dimensionen und bindet sie an Euren Dienst. Gan'rul Blutauge weist Euch an, Glyphen von der Schrifttafel der Verga zu verwenden und den Leerwandler in Neeru Fireblades Ritualkreis zu rufen, um ihn dort im Zweikampf zu brechen."},{t="Eine endlose Wacht",b="Den Leerwandler im körperlichen und magischen Kampf zu besiegen, ist nur die Hälfte des Ringens. Gan'rul Blutauge warnt, dass ein gebundener Leerwandler seine Versklavung niemals wirklich akzeptiert. Selbst während er seinen Meister im Kampf als widerstandsfähiges, schattenhaftes Bollwerk beschützt, wartet er darauf, dass Eure Konzentration nachlässt. Sollte Eure Kontrolle über Euren Diener jemals schwinden, wird er die Seele dessen verschlingen, der ihn gebunden hat."}},faq={{q="Was für eine Kreatur wird beschworen?",a="Ihr beschwört einen Leerwandler, ein hoch aufragendes Wesen, geformt aus kosmischen Schatten und Leerenenergien. Anders als schelmische Wichtel sind Leerwandler brutale Wesen, die dem Twisting Nether und dem Void entrissen werden. Hexenmeister setzen sie vor allem ein, um verheerende körperliche Schläge abzufangen.",al={"was wird beschworen","welcher dämon","leerwandler hintergrund"}},{q="Wo findet dieses Beschwörungsritual statt?",a="Das Ritual findet in Neeru Fireblades Zelt in der Kluft der Schatten unter Orgrimmar statt. Ein auf den Boden gezeichneter Beschwörungskreis bündelt die dimensionalen Energien, die nötig sind, um einen Leerwandler aus dem Nether zu reißen.",al={"wo beschwören","beschwörungskreis standort","ritualort"}},{q="Wozu dient die Schrifttafel der Verga?",a="Die Schrifttafel der Verga enthält uralte, spezialisierte Glyphen, mit denen ein Leerwandler Gestalt annimmt und durch das Gefüge der Wirklichkeit gerissen wird. Ihr studiert ihre Inschriften, um die Glyphe der Beschwörung anzufertigen, die zum Erstellen des Beschwörungskreises benötigt wird.",al={"schrifttafel der verga","glyphe der beschwörung"}},{q="Warum muss der Hexenmeister den Leerwandler besiegen?",a="Hexenmeister kontrollieren Wesen aus anderen Ebenen durch schiere Überlegenheit. Der Leerwandler gibt seine Essenz erst preis und gehorcht Befehlen, nachdem Ihr Eure Überlegenheit bewiesen habt, indem Ihr ihn im körperlichen und magischen Kampf besiegt.",al={"warum den leerwandler töten","warum gegen ihn kämpfen","ablauf der bindung"}},{q="Wer ist Gan'rul Blutauge?",a="Gan'rul Blutauge ist ein erfahrener Hexenmeisterlehrer der Horde in Orgrimmars Kluft der Schatten. Er beaufsichtigt die dunkle Ausbildung junger Hexenmeister der Horde und lehrt sie, mächtigere dämonische Wesen zu versklaven.",al={"wer ist ganrul","gan'rul blutauge"}},{q="Kann man einem gebundenen Leerwandler jemals völlig vertrauen?",a="Niemals. Ein Leerwandler kann jahrelang ohne Widerstand dienen und dabei darauf warten, dass sein Meister unachtsam wird. Die Bindung verlangt ständige Wachsamkeit, denn die Kreatur hegt ewigen Groll gegen denjenigen, der sie gefangen hält.",al={"wendet sich der leerwandler gegen seinen meister","ist der leerwandler treu","können dämonen rebellieren"}}},fx={["066e41c9"]={q="Warum will Gan'rul Blutauge, dass das erledigt wird?",a="Gan'rul Blutauge dient als Ausbilder für vielversprechende Hexenmeister, die sich in Die Kluft versammeln. Er testet und formt Eure Disziplin, indem er Euch dazu drängt, Euer Repertoire an dunkler Magie zu erweitern. Damit Ihr im Dienste der Horde größere Teufelskräfte befehligen könnt, müsst Ihr Eure Meisterschaft beweisen, indem Ihr einen widerstandsfähigen Leerwandler herbeiruft und beherrscht.",al={"gan'rul blutauges motiv","warum leerwandler ganrul beschwören","warum will ganrul, dass ich einen leerwandler binde"}},["3b87ecbf"]={q="Warum lässt Gan'rul Blutauge Euch den Leerwandler selbst bekämpfen?",a="Ein beschworener Diener kann nur durch die reine Willenskraft und Stärke des Hexenmeisters gebunden werden, der ihn befehligt. Weder Gan'rul Blutauge noch die Stadtwachen können den Geist des Dämons in Euren Dienst zwingen. Ihr müsst ihn durch Eure eigene magische und kampftechnische Macht bezwingen und demonstrieren, dass Euer Verstand und Euer Geist stark genug sind, um ihn versklavt zu halten.",al={"warum den leerwandler allein bekämpfen","warum kann ganrul den leerwandler nicht bekämpfen","warum ich leerwandler bindung"}}},fp="11,197,23.406.0,17.378.0,40.252.0,44.215.0,37.223.0,43.198.0,24.200.0,45.212.0"}
P.entries["quest:1505"] = {n="Veteran Uzzek",s="Knapp südlich der Fernwacht suchen Rekruten Veteran Uzzek auf, um im Kampf unterwiesen zu werden. Seine langjährige Erfahrung lehrt junge Krieger der Horde, dass Stärke Disziplin und Studium erfordert.",h="Knapp südlich der Fernwacht suchen Rekruten Veteran Uzzek auf, um im Kampf unterwiesen zu werden.",kw={"brachland","kampfunterweisung","durotar","fernwacht","horde","uzzek","veteran uzzek","krieger"},ang={["class:Warrior"]="Als Krieger lernt Ihr von Uzzek, dass rohe Gewalt nicht genügt. Wahre Stärke erwächst aus dem disziplinierten Studium des Kampfes.",["faction:Horde"]="Als Mitglied der Horde ehrt Ihr Kampfkunst und verlasst Euch auf erfahrene Kämpfer an Grenzposten, um die nächste Generation anzuleiten."},sec={{t="Der Pfad des Kriegers",b="Stärke allein macht einen Krieger der Horde noch nicht zum Champion. Die besten Kämpfer bleiben bescheidene Schüler ihres Handwerks. Durch Disziplin und Studium schärfen sie ihre Instinkte. Junge Krieger, die bereit sind, über die Grundausbildung hinauszugehen, suchen Veteranen auf, die die Prüfungen des Krieges überlebt haben."},{t="Der Veteran an der Grenze",b="Zwischen Durotar und dem Brachland suchen junge Kämpfer weiterführende Unterweisung im Kampf. Die Fernwacht bewacht die östliche Grenze. Knapp südlich der Orc-Garnison lehrt Veteran Uzzek vielversprechende Rekruten Kampf- und Überlebenstaktiken. Er hat zahllose blutige Konflikte überstanden und leitet nun die nächste Generation an."}},faq={{q="Wer ist Veteran Uzzek?",a="Nahe der Grenze zwischen Durotar und dem Brachland unterweist Veteran Uzzek junge Krieger der Horde im Kampf. In seinem Lager gibt er weiter, was er in zahllosen Konflikten gelernt hat.",al={"wer ist uzzek","uzzek hintergrundgeschichte","wer ist der veteran"}},{q="Wo ist Uzzek zu finden?",a="Uzzek befindet sich südlich der Fernwacht, der Orc-Garnison an der östlichen Grenze zwischen Durotar und dem Brachland.",al={"wo ist uzzek","uzzek standort","uzzek finden"}},{q="Was ist die Fernwacht?",a="Die Fernwacht ist eine Orc-Garnison an der östlichen Grenze des Brachlands. Sie bewacht den Übergang von Durotar und schützt die Grenze der Horde.",al={"was ist die fernwacht","zweck der fernwacht"}},{q="Warum werden junge Krieger zu Uzzek geschickt?",a="Junge Krieger suchen Uzzek auf, um im Kampf unterwiesen zu werden. Die Horde schätzt Stärke, doch ihre besten Kämpfer meistern auch Disziplin, Studium und Kampftechnik.",al={"warum uzzek aufsuchen","was lehrt uzzek","kriegerunterweisung"}},{q="Was sagt Uzzek, wenn Ihr ankommt?",a="Uzzek heißt junge Krieger an seinem Posten willkommen. Er ist bereit, ihre Entschlossenheit zu prüfen und sie die Wege des Krieges zu lehren.",al={"was geschieht beim gespräch mit uzzek","uzzek quest abgeben"}},{q="Wie sieht die Horde ihre Krieger?",a="Die Horde ehrt Krieger für ihre Stärke und ihre Hingabe an den Kampf. Ihre Traditionen lehren auch, dass Meisterschaft Disziplin und das Lernen von erfahrenen Veteranen erfordert.",al={"wer ehrt krieger","kriegerkultur der horde"}}},fp="13,180,23.273.0,25.304.0,21.158.0,25.105.0,23.136.0,37.154.0,36.113.0,37.161.0"}
P.entries["quest:1506"] = {n="Gan'ruls Beschwörung",s="Ophek überbringt jungen Hexenmeistern der Horde in Klingenhügel Gan'ruls Beschwörung. Gan'rul Blutauge ruft sie in die Kluft der Schatten, um ihre Ausbildung voranzutreiben. Dort machen sie den ersten Schritt zur Beschwörung eines Leerwandlers.",h="Ophek überbringt jungen Hexenmeistern der Horde in Klingenhügel Gan'ruls Beschwörung.",kw={"blutauge","die kluft der schatten","gan'rul","ophek","orgrimmar","beschwörung","leerwandler","hexenmeisterquest"},ang={["class:Warlock"]="Für Euch als Hexenmeister weist diese Beschwörung den Weg über die einfache Wichtelbeschwörung hinaus. Sie eröffnet Euch die Möglichkeit, über den standhaften Schutz eines Leerwandlers zu gebieten.",["faction:Horde"]="Als Mitglied der Horde wisst Ihr, dass Hexenmeister in Thralls neuer Horde einen heiklen Stand haben. Ihre pragmatische Macht wird geduldet, während sie unter Orgrimmar abgeschieden bleiben."},sec={{t="Ein Ruf in die Schatten",b="In Durotar bleiben unerfahrene Hexenmeister nicht lange unbemerkt. Sobald ein Praktizierender seinen ersten Wichtel ausreichend beherrscht, dringt die Kunde davon in die tiefen Höhlen unter Orgrimmar. Von seinem Posten in Durotar aus überbringt Ophek Nachrichten für die ranghohen dunklen Zauberwirker. Er sucht Hexenmeister auf und fordert sie dringend auf, ihre Arbeit liegen zu lassen und sich in der Kluft der Schatten zu melden."},{t="Der ranghohe Hexenmeister",b="Gan'rul Blutauge beaufsichtigt die Ausbildung junger Orc-Hexenmeister innerhalb der Horde. In den verborgenen Höhlen unter Orgrimmar verfeinert er ihre tödlichen Teufelskräfte und hält diese gefährlichen Künste vor dem missbilligenden Blick des Kriegshäuptlings verborgen. Ein Ruf in seinen Zirkel bedeutet, dass einfache Feuerzauber und Wichtel nicht mehr genügen. Der Lehrling ist bereit, eine Kreatur aus dem Wirbelnden Nether zu binden."}},faq={{q="Wer ist Ophek?",a="Ophek ist ein Vertrauter der in Durotar stationierten Hexenmeister. Er hält nach aufstrebenden Praktizierenden Ausschau und überbringt Befehle von ranghohen Mentoren wie Gan'rul Blutauge.",al={"ophek","wer vergibt diese quest","questgeber"}},{q="Wo befindet sich Gan'rul Blutauge?",a="Gan'rul Blutauge befindet sich in der Kluft der Schatten, einem dunklen Höhlensystem unter den felsigen Plateaus von Orgrimmar.",al={"wo ist ganrul","gan'ruls standort","gan'rul blutauge finden"}},{q="Warum will Gan'rul Blutauge mich sehen?",a="Gan'rul hält Euch für bereit, Eure Hexenmeisterstudien zu vertiefen und mit den gefährlichen Riten zur Beschwörung und Bindung eines Leerwandlers zu beginnen.",al={"warum die beschwörung","was will ganrul","questgrund"}},{q="Was geschieht, nachdem ich mich bei Gan'rul gemeldet habe?",a="Wenn Ihr Euch bei Gan'rul meldet, beginnt Creature of the Void. Ihr werdet losgeschickt, um die nötigen Komponenten und das Wissen zu finden, mit denen sich ein Leerenwesen nach Azeroth ziehen lässt.",al={"nächste quest","was kommt nach gan'ruls beschwörung"}},{q="Warum bleiben die Hexenmeister in der Kluft der Schatten?",a="Hexenmeister wirken unberechenbare Teufelsmagie, der Thrall und die traditionell schamanische Horde mit tiefem Misstrauen begegnen. In der Kluft der Schatten können sie ihre Rituale fernab der Öffentlichkeit vollziehen.",al={"warum die kluft der schatten","warum verstecken sich hexenmeister","hexenmeisterhöhle orgrimmar"}},{q="Kann jede Klasse diese Quest annehmen?",a="Nein. Nur Hexenmeister der Horde, die den zehnten Kreis ihrer Ausbildung erreicht haben, können die Beschwörung erhalten.",al={"nur für hexenmeister","wer erhält diese quest"}}},fx={f5421555={q="Warum schickt Ophek Euch zu Gan'rul?",a="Ophek fungiert lediglich als Laufbursche und Bote für Gan'rul Blutauge. Ältere Hexenmeister in Die Kluft wandern nicht durch Orgrimmar, um selbst nach Lehrlingen zu suchen; sie schicken Handlanger, um zu holen, wen sie brauchen. Ophek weiß, dass es besser ist, Gan'ruls Vorladung nicht zu verzögern, und warnt Euch, dass es selten gut endet, einen Hexenmeister warten zu lassen.",al={"warum schickt mich ophek","opheks motiv","warum liefert ophek die vorladung"}}},fp="17,210,24.340.0,18.373.0,13.160.0,34.100.0,41.122.0,40.142.0,48.179.0,30.100.0"}
P.entries["quest:1507"] = {n="Verschlinger der Seelen",s="In Orgrimmar schickt Gan'rul Blutauge einen aufstrebenden Hexenmeister der Horde zu Cazul, um dessen Rat einzuholen. Dort lernt der Hexenmeister, einen Sukkubus anzulocken und zu binden.",h="In Orgrimmar schickt Gan'rul Blutauge einen aufstrebenden Hexenmeister der Horde zu Cazul, um dessen Rat...",kw={"bindung","cazul","die kluft der schatten","gan'rul blutauge","orgrimmar","sukkubus","beschwörung","hexenmeister"},ang={["class:Warlock"]="Als Hexenmeister kommt Ihr der Beherrschung von Dämonen näher, die sich auf geistige Unterwerfung und Verführung verstehen. Der Ritus erfordert sowohl geistige Entschlossenheit als auch rohe Teufelsmacht.",["faction:Horde"]="Als Mitglied der Horde seht Ihr, wie Hexenmeister in den feuchten, abgelegenen Felsspalten der Kluft der Schatten gefährliche Riten vollziehen. Thralls Schamanen und Krieger üben in aller Öffentlichkeit, während Hexenmeister im Verborgenen arbeiten."},sec={{t="Ein Schritt in verführerische Schatten",b="Hexenmeister der Horde, die geringere Dämonen wie Wichtel und Leerwandler beherrschen, können sich als Nächstes um einen Sukkubus bemühen. Unter Orgrimmar wacht Gan'rul Blutauge über die dunklen Künste und beurteilt, wann ein Hexenmeister bereit ist, einen aus dem Nether zu rufen. Ein Sukkubus kann die Schwachen gegen sich selbst wenden, daher erfordert seine Bindung sowohl Feingefühl als auch Stärke."},{t="Das Wissen von Cazul",b="Ein Sukkubus nährt sich am Verlangen der Sterblichen, daher reichen bloße Beschwörungsformeln nicht aus, um einen zu rufen. Der Beschwörer muss ihn mit einem Gegenstand anlocken, der von reiner Liebe und Hingabe erfüllt ist. Gan'rul kann oder will ein solches Relikt nicht bereitstellen, also schickt er den Hexenmeister quer durch die Kluft der Schatten zu Cazul. Der uralte Hexenmeister kennt die arkanen und dämonischen Riten, die für den nächsten Teil des Rituals nötig sind."}},faq={{q="Welchen Zweck hat diese Quest?",a="Hier beginnt der Weg eines aufstrebenden Hexenmeisters der Horde, der lernen will, einen Sukkubus zu beschwören und zu befehligen. Die Quest führt Euch zu Lehrmeistern in der Kluft der Schatten, die Euch das Wesen des Dämons erklären und zeigen, wie Ihr einen aus dem Nether lockt.",al={"warum verschlinger der seelen machen","sukkubusquest beginn","was schaltet diese quest frei"}},{q="Wo finde ich Cazul?",a="Cazul befindet sich in der Kluft der Schatten, einer Höhle unter Orgrimmar, wo Schurken- und Hexenmeisterlehrer fernab der prüfenden Blicke des Kriegshäuptlings praktizieren.",al={"cazul standort","wo ist cazul","cazul in orgrimmar finden"}},{q="Warum braucht ein Hexenmeister einen Gegenstand der Liebe, um einen Sukkubus zu beschwören?",a="Sukkubi nähren sich von den Gefühlen und der Hingabe der Sterblichen sowie von deren Willensschwäche. Um einen aus dem Nether zu locken, bietet ein Beschwörer ein mächtiges Zeichen wahrer Hingabe und Zuneigung als Köder an, überwältigt und bindet dann den Dämon.",al={"sukkubus köder liebe","warum liebesgegenstand für sukkubus","hintergrund der sukkubusbeschwörung"}},{q="Wer ist Gan'rul Blutauge?",a="Gan'rul Blutauge ist ein hochrangiger Hexenmeisterlehrer der Horde in Orgrimmars Kluft der Schatten. Er leitet angehende Hexenmeister bei der Bindung immer mächtigerer dämonischer Diener an.",al={"wer vergibt verschlinger der seelen","gan'rul hintergrund","gan'rul blutauge"}},{q="Welche Stufe ist erforderlich, um diese Quest zu beginnen?",a="Ein Hexenmeister muss Stufe zwanzig erreichen, bevor Gan'rul seine magischen Fähigkeiten und seine geistige Stärke für ausreichend hält. Bei diesem Ritual muss er mit einem Sukkubus verhandeln und die Begegnung überleben.",al={"welche stufe für sukkubus","verschlinger der seelen stufe","sukkubusquestreihe benötigte stufe"}},{q="Was folgt nach dem Gespräch mit Cazul?",a="Das Gespräch mit Cazul führt zu Blind Cazul. Dabei sucht Ihr Zankaja in Orgrimmar auf, deren Gefährte Dogran nicht von seinem Dienst am Wegekreuz zurückgekehrt ist. Bei ihr beginnt die Suche nach einem geeigneten Zeichen der Liebe.",al={"nächste quest nach verschlinger der seelen","was kommt nach cazul","sukkubusquest ablauf"}}},fx={["0f1c8f0b"]={q="Warum will Gan'rul Blutauge, dass Ihr einen Sukkubus beschwört?",a="Als Mentor unter den Hexenmeistern der Horde in Die Kluft existiert Gan'rul Blutauge, um Euch in tiefere, mächtigere Künste der dunklen Magie zu führen. Er glaubt, dass Ihr über die geistige Stärke und List verfügt, die notwendig ist, um einen Sukkubus zu zähmen, anstatt seinem Reiz zu erliegen. Für ihn erweitert jeder Diener, den Ihr erfolgreich bindet, den Einfluss und die tödliche Reichweite Eurer gemeinsamen dämonischen Kunst.",al={"warum will gan'rul das","gan'rul blutauges motiv","warum sukkubus gan'rul beschwören"}},cde5d57b={q="Warum schickt Gan'rul Euch, anstatt selbst nach dem Köder zu suchen?",a="Einem Hexenmeister kann die absolute Meisterschaft über einen Dämon nicht einfach übergeben werden; die Bindung muss durch Eure persönliche Prüfung und Euren Einfallsreichtum geschmiedet werden. Gan'rul erwartet von Euch, dass Ihr Euren Wert beweist, indem Ihr das erforderliche Zeichen der Hingabe aufdeckt und den Unhold allein Eurem Willen beugt, wodurch Ihr Eure eigene Vorherrschaft etabliert, anstatt Euch auf die Macht eines anderen zu verlassen.",al={"warum ich gan'rul","warum schickt er mich für sukkubus","warum kann gan'rul das nicht tun"}}},fp="17,155,29.327.0,17.359.0,34.226.0,22.136.0,63.207.0,24.181.0,43.183.0,39.200.1"}
P.entries["quest:1508"] = {n="Der blinde Cazul",s="In der Kluft der Schatten führt der blinde Cazul einen Novizen, der eine Sukkubus beschwören will. Er weist auf einen Gegenstand hin, der mit sterblichen Gefühlen aufgeladen ist.",h="In der Kluft der Schatten führt der blinde Cazul einen Novizen, der eine Sukkubus beschwören will.",kw={"der blinde cazul","cazul","die kluft der schatten","dogran","orgrimmar","sukkubus","hexenmeister","zankaja"},ang={["class:Warlock"]="Als Hexenmeister lernt Ihr, dass Dämonenbeschwörungen neben Teufelsmagie auch von gefühlsmäßiger Resonanz abhängen. Eine Sukkubus wird durch ein Medium angelockt, das mit sterblichen Gefühlen aufgeladen ist.",["faction:Horde"]="Als Mitglied der Horde seht Ihr, wie die dunklen Künste der Kluft der Schatten unter der Hauptstadt wirken und das gewöhnliche Leben auf den Tafelbergen darüber berühren."},sec={{t="Eine Frage der Verlockung",b="Eine Sukkubus reagiert auf Sehnsucht, Trauer und Verlangen. Um eine durch den Schleier zu locken, braucht ein Beschwörer mehr als Willenskraft; der Dämon ist dafür bekannt, Seelen zu verschlingen. Der blinde Cazul versteht, was der Novize sucht. Er weiß, wo sich ein passender Köder finden lässt."},{t="Augen auf den Klippen",b="Obwohl er blind ist, spürt der blinde Cazul das Leben und die Sorgen innerhalb von Orgrimmars roten Wällen. Er schickt den Novizen zu Zankaja, einer Orcfrau, die oben auf den Klippen nahe dem Horst der Wind Rider lebt. Sie wartet voller Sorge auf die Rückkehr ihres Gefährten Dogran. Ihre Verzweiflung kann die Aufmerksamkeit eines Dämons erregen."}},faq={{q="Wer ist Cazul?",a="Cazul ist ein blinder Hexenmeister, der den Hexenmeistern der Kluft der Schatten im Stillen hilft. Er bestimmt Reagenzien und Medien für Dämonenbeschwörungen.",al={"der blinde cazul","wer ist cazul"}},{q="Warum schickt Cazul Euch zu Zankaja?",a="Ein Ritual zur Beschwörung einer Sukkubus erfordert einen Gegenstand, der von starker sterblicher Sehnsucht oder Liebe geprägt ist. Zankaja wartet verzweifelt auf ihren vermissten Gefährten Dogran, und ihre Bindung zu ihm bietet den gefühlsgetragenen Köder, den der Novize sucht.",al={"warum zankaja","was hat zankaja"}},{q="Wo ist Zankaja in Orgrimmar zu finden?",a="Zankaja lebt auf Orgrimmars hoch gelegenen Klippen, westlich des Horsts der Wind Rider. Überquert die Brücke vom Flugturm aus und sucht in den nahe gelegenen Behausungen auf der rechten Seite.",al={"zankajas standort","wo ist zankaja"}},{q="Was geschieht nach dem Gespräch mit Zankaja?",a="Zankaja ist verzweifelt, weil ihr Gefährte Dogran verschwunden ist. Nach dem Gespräch mit ihr sucht Ihr im Brachland nach Nachrichten über sein Schicksal und beginnt, ein mächtiges Zeichen der Liebe zu beschaffen.",al={"what comes next","nächster schritt nach cazul"}},{q="Auf die Beschwörung welcher Dämonenart bereitet Euch diese Quest vor?",a="Ihr bereitet Euch darauf vor, eine Sukkubus zu beschwören und zu versklaven, einen Dämon, der Verführung und seelische Qual als Waffen einsetzt.",al={"welcher begleiter","dämon als belohnung"}},{q="Warum müssen Hexenmeister persönliche Tragödien für ihre Rituale ausnutzen?",a="Eine Sukkubus wird von starken sterblichen Gefühlen angezogen, besonders von Leidenschaft, Hingabe und Liebeskummer. Hexenmeister nutzen von Trauer oder Verlangen geprägte Andenken als spirituellen Köder im Beschwörungsritual.",al={"moral der hexenmeister","warum dogran benutzen"}}},fx={a1700788={q="Warum will Cazul, dass Ihr Zankaja findet?",a="Cazul fungiert als Ausbilder und Ältester in den Schatten von Die Kluft. Wenn Gan'rul Blutauge einen angehenden Hexenmeister zu ihm schickt, ist es Cazuls Rolle, Euch zu den Zutaten zu führen, die zum Binden eines Sukkubus erforderlich sind. Die Beschwörung eines solchen Dämons erfordert ein Objekt, das mit Liebe und roher Sehnsucht durchdrungen ist. Cazul weiß, dass Zankajas Trauer und Verzweiflung über ihren verschwundenen Gefährten, Dogran, den emotionalen Anker liefern können, den Ihr benötigt, um einen Devourer of Souls auf Eure Seite zu ziehen.",al={"cazuls motiv","warum zankaja cazul helfen","cazul warum zu zankaja schicken"}},fea16628={q="Warum schickt Cazul Euch, anstatt selbst zu Zankaja zu gehen?",a="Diese Aufgabe ist Teil Eurer Initiation als Hexenmeister, keine gewöhnliche städtische Angelegenheit. Cazul ist ein alter, blinder Eremit, der in den schattigen Tiefen von Orgrimmar wohnt und still Novizen in dunklen Riten anleitet. Die Hexenmeisterausbildung erfordert, dass Ihr Eure eigenen Bindungen schmiedet und die Komponenten für Eure Dämonen persönlich sammelt. Außerdem hätten die Wachen von Orgrimmar kein Interesse daran, verbotene dämonische Rituale zu unterstützen, was bedeutet, dass die Last, dieser Spur der Trauer zu folgen, voll und ganz auf Euch fällt.",al={"warum ich cazul","warum den spieler zu zankaja schicken","warum braucht mich cazul"}}},fp="11,140,22.241.0,18.282.0,13.143.0,35.199.0,40.163.0,39.185.0,57.102.0,63.181.0"}
P.entries["quest:1509"] = {n="Neuigkeiten von Dogran",s="Zankaja wartet in Orgrimmar auf Nachricht von ihrem Gefährten Dogran, der seit Tagen fort ist. Sie schickt Euch zu Gazrog am Wegekreuz, um nachzufragen.",h="Zankaja wartet in Orgrimmar auf Nachricht von ihrem Gefährten Dogran, der seit Tagen fort ist.",kw={"brachland","cazul","das wegekreuz","dogran","gazrog","neuigkeiten von dogran","quilboar","succubus","zankaja"},ang={["class:Warlock"]="Als Hexenmeister führt Euch Euer Weg von dunklen Schriften in Orgrimmar dazu, das Leid Sterblicher zu nutzen, um einen Succubus zu gewinnen.",["faction:Horde"]="Als Mitglied der Horde seht Ihr die Gefahren, denen ihre Grunts begegnen, während sie das Wegekreuz Kalimdors gegen feindliche Bedrohungen sichern.",["race:Orc"]="Als Ork seht Ihr in Zankajas Trauer den persönlichen Preis, den die Ausbreitung und Verteidigung der Horde in Durotar und im Brachland fordert."},sec={{t="Die Verzweiflung einer Gefährtin",b="Auf den Klippen von Orgrimmar bangt Zankaja um ihren Gefährten Dogran. Nach einer ehrenvollen Beförderung ging er zum Wegekreuz, doch seine Rückkehr ist überfällig und sie hat seit Tagen nichts gehört. Deshalb bittet sie Euch, bei seinem Kommandanten Gazrog nach Neuigkeiten zu fragen."},{t="Grim Tidings im Brachland",b="Am Wegekreuz, dem zentralen Außenposten der Horde im Brachland, erzählt Euch Gazrog, was Dogran widerfahren ist. Quilboar suchen die Ebenen heim und haben Dogran gefangen genommen. Er lebt noch, doch Gazrog zögert, Zankaja die düstere Wahrheit über seine Gefangennahme zu übermitteln."},{t="Ein Werkzeug der Beschwörung",b="Die Suche nach Dogran dient auch dem Bestreben eines Hexenmeisters, einen Succubus zu beschwören und zu beherrschen. Das Bindungsritual verlangt nach Relikten, die von wahren Gefühlen berührt wurden. Dograns Leiden und seine Verbundenheit mit Zankaja geben dem Ritual die emotionale Verbindung, die es braucht."}},faq={{q="Wer ist Dogran?",a="Dogran ist ein im Brachland stationierter orkischer Grunt, der kürzlich befördert und zum Wegekreuz versetzt wurde. Er ist Zankajas Gefährte, und sie lebt in Orgrimmar.",al={"dogran hintergrundgeschichte","wer ist dogran","grunzer dogran"}},{q="Warum interessiert sich ein Hexenmeister für einen vermissten orkischen Wächter?",a="Hexenmeistermentoren in der Kluft der Schatten weisen Euch an, nach Neuigkeiten über Dogran zu suchen. Ein Ritual zur Bindung eines Succubus benötigt Relikte, die von tiefen Gefühlen Sterblicher berührt wurden, darunter Liebe, Hingabe und Leid.",al={"warum hexenmeisterquest","warum tun hexenmeister das","verbindung zum succubus"}},{q="Wo befindet sich Gazrog?",a="Gazrog ist am Wegekreuz im Brachland, wo er hilft, die Verteidigung der Horde gegen örtliche Bedrohungen zu organisieren.",al={"wo ist gazrog","gazrog aufenthaltsort","wegekreuz gazrog"}},{q="Was ist Dogran zugestoßen?",a="Dograns Rückkehr zu Zankaja ist überfällig, und sie hat seit Tagen nichts von ihm gehört. Sie bittet Euch, bei Gazrog am Wegekreuz nach Neuigkeiten zu fragen.",al={"ist dogran tot","wo ist dogran","dograns schicksal"}},{q="Wer vergibt diese Quest?",a="Zankaja gibt sie Euch auf den Klippen von Orgrimmar, nachdem der Hexenmeisterlehrer Cazul Euch zu ihr geschickt hat.",al={"questgeber","wo beginnt neuigkeiten von dogran"}},{q="Wie geht die Questreihe weiter?",a="Setzt Eure Nachforschungen im Brachland fort, um Dograns Schicksal zu erfahren und die Nachricht weiterzutragen.",al={"wie geht es weiter","nächste quest","fortsetzung der succubus-questreihe"}}},fx={["7a20ce20"]={q="Warum möchte Zankaja, dass Ihr Neuigkeiten über Dogran findet?",a="Dogran ist Zankajas Gefährte. Er war sehr stolz auf seine kürzliche Beförderung und seine Zuweisung zum Wegekreuz, aber das Brachland ist weitaus gefährlicher als die Sicherheit der Mauern von Orgrimmar. Er ist nun schon über eine Woche überfällig und sie hat überhaupt keine Nachricht von ihm erhalten. Zerrissen zwischen Angst und Hoffnung hält sie das Schweigen nicht länger aus und braucht jemanden, der seinen befehlshabenden Kontakt ausfindig macht.",al={"warum möchte zankaja das","zankajas beweggrund","warum nach dogran suchen"}}},fp="14,131,16.238.0,27.241.1,26.243.1,14.137.0,50.186.0,24.103.0,24.137.1,21.103.0,29.90.1"}
P.entries["quest:151"] = {n="Die arme Graumähne",s="An Westfalls Straße wartet die arme Graumähne bei den gestrandeten Furlbrows, erschöpft und hungrig. Ihr Wagen ging auf der Flucht zu Bruch, und Verna bittet Euch, auf nahegelegenen verlassenen Höfen Hafer für die Stute zu finden.",h="An Westfalls Straße wartet die arme Graumähne bei den gestrandeten Furlbrows, erschöpft und hungrig.",kw={"erntegolem","pferd","hafer","alte blanchy","die arme graumähne","verna brauenwirbel","wagen","westfall"},ang={["class:Hunter"]="Als Jäger wisst Ihr, dass die Fürsorge für ein entkräftetes Zugtier die Verbundenheit zwischen arbeitenden Menschen und den Tieren würdigt, die treu ihre Lasten tragen.",["faction:Alliance"]="Die gestrandeten Furlbrows zeigen, wie menschliche Untertanen auf dem Land unter Vernachlässigung leiden, während die Hauptstadt durch politischen Stillstand gelähmt bleibt."},sec={{t="Eine gestrandete Familie",b="Verna und Bauer Brauenwirbel sitzen neben Westfalls Hauptstraße fest. Banditen und außer Kontrolle geratene mechanische Erntegolems haben Familien wie die ihre aus ihren Häusern vertrieben. Die Furlbrows versuchten, ihre Habseligkeiten in Sicherheit zu bringen, doch ihr Wagen brach zusammen, sodass sie auf freiem Feld festsitzen."},{t="Trost für eine treue Stute",b="Die alte Blanchy hat viele Jahreszeiten lang für die Familie Furlbrow gepflügt und Lasten gezogen. Nun hat die Verzögerung die sanftmütige Stute erschöpft und ausgehungert zurückgelassen. Verna bittet Euch, nahegelegene überrannte Gehöfte nach Hafersäcken zu durchsuchen. Dort drohen feindselige Drescher und plündernde Gnolle, doch das Getreide könnte der treuen Stute eine anständige Mahlzeit verschaffen."}},faq={{q="Wer ist die alte Blanchy?",a="Die alte Blanchy ist das geliebte, betagte Arbeitspferd der Familie Furlbrow. Seit Jahren zieht sie deren Pflüge und Karren durch Westfall. Nun ist sie erschöpft und sitzt am Straßenrand fest, nachdem die Achse ihres Wagens gebrochen ist.",al={"wer ist blanchy","was ist die alte blanchy","blanchys geschichte"}},{q="Warum ist der Wagen der Furlbrows liegen geblieben?",a="Die Furlbrows versuchten, mit all ihren Habseligkeiten von ihrem Hof zu fliehen, doch der Wagen hielt der Belastung nicht stand. Sie sitzen an der Hauptstraße fest, Banditen und umherstreifenden Bestien schutzlos ausgeliefert.",al={"warum sitzen sie fest","wagen der furlbrows","kaputter wagen an der straße"}},{q="Woher stammt der Hafer?",a="Hafersäcke liegen verstreut auf den Feldern und in den Nebengebäuden von Westfalls überrannten Höfen. Die Siedler ließen sie zurück, als sie vor außer Kontrolle geratenen Erntemaschinen und Banditen flohen.",al={"wo ist hafer","hafer finden","hafersäcke"}},{q="Welche Gefahren lauern beim Getreide auf den Feldern?",a="Südwestlich der Straße durchstreifen außer Kontrolle geratene mechanische Erntewächter und Gruppen von Riverpaw-Gnollen verlassene Scheunen auf der Suche nach Beute.",al={"was greift auf den höfen an","gefahren auf den höfen","erntegolems hafer"}},{q="Warum hat die Familie die alte Blanchy nicht in Sicherheit gebracht?",a="Die alte Blanchy ist entkräftet und ausgehungert und kann ohne Futter weder Lasten ziehen noch weite Strecken zurücklegen. Die Furlbrows weigern sich, ihre treue Stute oder ihre Habseligkeiten zurückzulassen.",al={"warum beim wagen bleiben","kann das pferd laufen","warum nicht zur späherkuppe gehen"}},{q="Schickt Sturmwind Bauern wie den Furlbrows Hilfe?",a="Sturmwinds Königshof bietet Westfalls Siedlern kaum Schutz oder Hilfe. Die Landbevölkerung bleibt weitgehend auf sich allein gestellt oder ist auf die Volksmiliz angewiesen, die selbst zu kämpfen hat.",al={"sturmwinds hilfe für westfall","wo sind die wachen","hilfe der allianz für westfall"}}},fx={b3f21e2d={q="Warum möchte Verna Brauenwirbel, dass dies erledigt wird?",a="Der Wagen der Brauenwirbels ist unerwartet auf der Straße liegen geblieben und hat sie weit entfernt von ihrem Ziel gestrandet. Ihr treues altes Pferd, Blanchy, ist völlig erschöpft von der Reise und all der harten Arbeit, die sie ertragen musste. Verna hat sie gefüttert, bevor sie von zu Hause aufgebrochen sind, aber Blanchy ist nun am Ende ihrer Kräfte. Ohne frischen Hafer, um sie zu nähren, kann das müde Tier nicht die Kraft zurückgewinnen, die nötig ist, um weiterzumachen.",al={"warum blanchy helfen","verna brauenwirbels beweggrund","warum braucht blanchy hafer"}},c126e1f4={q="Wofür ist die Hand voll Hafer gedacht?",a="Dieser Hafer ist lebenswichtiges Futter, um Blanchy zu stärken und wiederzubeleben. Das treue Zugpferd der Brauenwirbels ist völlig erschöpft vom Ziehen ihres beladenen Wagens und hat nach ihrer plötzlichen Panne kaum noch Nahrung. Ihr handvoll Getreide zu geben, das von den umliegenden Bauernhöfen gesammelt wurde, stellt ihre Lebensgeister und ihre Kraft wieder her, während die Familie mit ihrer gebrochenen Achse zu kämpfen hat.",al={"wofür ist die hand voll hafer","nutzen der hand voll hafer","zweck des hafers"}},["3b562f8e"]={q="Warum bittet Verna Brauenwirbel Euch und sammelt den Hafer nicht selbst?",a="Die Brauenwirbels sind hilflose Reisende, die neben ihrem zerstörten Wagen am Straßenrand festsitzen und völlig ungerüstet sind, um den Gefahren der Felder von Westfall zu begegnen. Das verlassene Ackerland, auf dem noch Getreidesäcke lagern, ist von feindseligen mechanischen Erntemaschinen und umherstreifenden Raubtieren überlaufen. Verna und ihr Ehemann müssen bei ihrem beschädigten Wagen und dem geschwächten Pferd bleiben, was das gefährliche Suchen erfahrenen Abenteurern wie Euch überlässt.",al={"warum kann verna keinen hafer besorgen","warum bittet verna mich","warum brauchen die brauenwirbels hilfe"}}},fp="16,200,20.286.0,27.325.0,19.206.0,38.183.0,28.172.0,43.113.0,50.152.0,54.180.0"}
P.entries["quest:1510"] = {n="Neuigkeiten von Dogran",s="Im Steinkrallengebirge schickt Euch Neuigkeiten von Dogran in die Ausläufer, um einen Heiltrunk zu holen. Der erste Läufer kehrte nie zurück, und Ken'zigla in Malaka'jin hat womöglich noch die Arznei, die Dogran braucht.",h="Im Steinkrallengebirge schickt Euch Neuigkeiten von Dogran in die Ausläufer, um einen Heiltrunk zu holen.",kw={"camp taurajo","dogran","gazrog","ken'zigla","malaka'jin","borstennacken","steinkrallengebirge"},ang={["class:Warlock"]="Als Hexenmeister steht Ihr vor einer scheinbar militärischen Hilfsmission. Cazul und die Hexenmeister von Orgrimmar haben eine Prüfung vorbereitet, die Euch zu den Gefühlen führt, die Ihr braucht, um einen Sukkubus zu binden.",["faction:Horde"]="Als Mitglied der Horde seht Ihr, wie gefährdet die Versorgungswege zwischen Camp Taurajo und dem abgelegenen Lager in Malaka'jin sind. Borstennacken und Goblins bedrohen den Weg."},sec={{t="Ein Hilferuf über die Grenze",b="Dogran liegt schwer verwundet in Camp Taurajo im südlichen Brachland. Er wurde im Kampf gegen verschanzte Borstennacken verletzt, und die Grunzer, die ihn zurücktrugen, stellten fest, dass seine Wunden eiterten. Sie fürchteten, die Reise würde ihm noch mehr schaden, bevor er behandelt werden könnte. Also sandte Taurajo Kunde nach Norden ans Wegekreuz, um einen Heiltrunk der Dschungeltrolle von Malaka'jin zu beschaffen."},{t="Blutvergießen bei Malaka'jin",b="In Malaka'jin erfahrt Ihr, dass Goblins den ersten Kurier, der die Arznei holen sollte, töteten, bevor er sie zurückbringen konnte. Ken'zigla hat noch immer den Trunk, den Dogran braucht. Um ihn zu erreichen, müsst Ihr Euch den Gefahren entlang der Pässe des Steinkrallengebirges stellen."}},faq={{q="Wer ist Dogran und warum ist er verletzt?",a="Dogran ist ein Grunzer der Horde in Camp Taurajo. Er wurde im Kampf gegen Borstennacken im südlichen Brachland schwer verwundet, und seine Wunden eiterten, bis seine Kameraden fürchteten, ihn ohne Behandlung fortzuschaffen.",al={"wer ist dogran","warum ist dogran verletzt","dograns geschichte"}},{q="Wo liegt Malaka'jin?",a="Malaka'jin ist ein Außenposten der Dunkelspeertrolle am felsigen Fuß des Steinkrallengebirges, gleich jenseits der nordwestlichen Grenze des Brachlands.",al={"malakajin lage","wo liegt malakajin","ken'zigla finden"}},{q="Was geschah mit dem ersten Boten, der den Trunk holen sollte?",a="Goblins töteten den ersten Kurier vom Wegekreuz nahe Malaka'jin, bevor er Ken'ziglas Trunk zurückbringen konnte. Ken'zigla sagt nur, dass die Goblins ihn getötet haben.",al={"erster läufer","was geschah mit dem boten","toter kurier"}},{q="Warum interessiert die Hexenmeisterlehrer Dograns Schicksal?",a="Hexenmeisterneulinge erhalten von Blind Cazul und Gazrog einen Auftrag unter dem Vorwand, Dogran zu helfen. Die Prüfung führt sie zu einem Artefakt, das mit Liebe und Herzschmerz verbunden ist und benötigt wird, um einen Sukkubus zu beschwören und zu binden.",al={"verbindung zur hexenmeisterquest","sukkubus dogran","warum hexenmeister das tun"}},{q="Wer ist Ken'zigla?",a="Ken'zigla ist ein Alchemist und Kräuterkundiger der Dunkelspeertrolle in Malaka'jin im Steinkrallengebirge. Er weiß, wie man aus den Gaben der Wildnis kräftige Tränke braut.",al={"wer ist kenzigla","kenzigla steinkrallengebirge","ken'zigla"}},{q="Warum konnte Dogran nicht direkt in eine Stadt gebracht werden?",a="Nach dem Kampf gegen die Borstennacken eiterten Dograns Wunden stark. Seine Kameraden fürchteten, der Weg über die holprigen Straßen des Brachlands zu einem bedeutenden Heiler würde ihn töten, bevor er dort ankäme.",al={"warum dogran nicht fortschaffen","dograns wunden","warum camp taurajo ihn zurückließ"}}},fx={["643120b9"]={q="Warum möchte Gazrog, dass dies erledigt wird?",a="Gazrog ist für die Koordination der Verteidigung und der Truppen im gesamten Brachland verantwortlich. Dogran wurde im Kampf gegen Stacheleber in der Nähe von Camp Taurajo verwundet und seine eiternden Wunden machen es unmöglich, ihn ohne Hilfe zu bewegen. Da der erste Bote, der nach Malaka'jin geschickt wurde, überfällig ist, benötigt Gazrog Euch, um den Heiltrunk der Trolle zu sichern, bevor Dogran seinen Wunden erliegt.",al={"gazrogs beweggrund","warum dogran helfen gazrog","warum nach malaka'jin schicken"}},["79033db9"]={q="Warum schickt Gazrog einen Abenteurer anstelle seiner eigenen Grunzer?",a="Die Streitkräfte der Horde im Brachland sind durch die ständigen Überfälle der Stacheleber und die Sicherung der Außenpostenrouten bis zum Äußersten gefordert. Gazrog hat bereits einen Boten zu den Ausläufern des Steinkrallengebirges entsandt, der nicht zurückkehrte, sodass er keine Soldaten mehr übrig hat, die er auf eine weitere Reise schicken könnte, wenn ein fähiger Abenteurer direkt vor ihm steht.",al={"warum ich news of dogran","warum schickt gazrog keine wache","warum braucht gazrog mich"}}},fp="14,184,26.356.0,23.219.1,33.183.0,28.132.0,58.165.0,49.202.1,17.132.0,49.169.0"}
P.entries["quest:1511"] = {n="Ken'ziglas Trunk",s="Auf dem Weg nach Camp Taurajo hängt Dograns Leben von Ken'ziglas Trunk ab. Der Troll-Apotheker bereitete ihn im Steinkrallengebirge für den vermissten Agenten zu.",h="Auf dem Weg nach Camp Taurajo hängt Dograns Leben von Ken'ziglas Trunk ab.",kw={"brachland","dogran","trunk","ken'zigla","logmar","steinkrallengebirge","sukkubus","taurajo"},ang={["class:Warlock"]="Als Hexenmeister müsst Ihr auf diesem Abschnitt Eurer Reise Geduld und Einfallsreichtum beweisen. Bevor Ihr einem Wesen aus ungezügeltem Verlangen und Verführung gebieten könnt, müsst Ihr den verletzten Sterblichen heilen, der das Zeichen der Bindung trägt.",["faction:Horde"]="Als Mitglied der Horde erlebt Ihr, wie abgelegene Außenposten im Steinkrallengebirge und im Brachland auf Reisende angewiesen sind, die wichtige Nachrichten und medizinische Hilfe durch Zentralkalimdor bringen."},sec={{t="Ein lebensrettendes Gebräu",b="Nachdem der erste Kurier nicht zurückgekehrt war, bereitete Ken'zigla eine weitere Dosis zu. Der Troll-Apotheker hatte diesen Boten ausgesandt, um Medizin für den vermissten Späher Dogran zu finden. Sein Trunk ist flüchtig und mächtig. Eine halbe Dosis verleiht einem tödlich verwundeten Soldaten die Kraft, sich zu bewegen, ohne dass seine Wunden erneut bluten. Der Rest muss bis zum nächsten Tag warten, an dem er die Genesung vollendet."},{t="Treffen in Camp Taurajo",b="Ihr bringt Ken'ziglas Trunk aus den Bergen zu Grunzer Logmar in Camp Taurajo. Logmar verfügt über entscheidende Informationen zu Dograns Aufenthaltsort, doch wegen Expeditionen zur Nahrungsbeschaffung fehlen seiner Garnison Grunzer. Dogran sitzt blutend in feindlichem Gebiet fest. Mit dem Trunk in Taurajo rückt eine Rettung näher."}},faq={{q="Wozu dient Ken'ziglas Trunk?",a="Ken'ziglas Trunk ist eine wirksame Medizin für den verletzten Orc-Agenten Dogran. Die erste seiner beiden Dosen verleiht einem verwundeten Kämpfer die Kraft, sich zu bewegen, ohne dass tödliche Wunden erneut aufbrechen. Die zweite vollendet die Heilung.",al={"was ist der trunk","ken'ziglas trunk zweck","warum den trunk herstellen"}},{q="Wer ist Ken'zigla?",a="Ken'zigla ist ein Troll-Apotheker im Steinkrallengebirge. Er bereitet spezielle alchemistische Mischungen für Agenten der Horde in der Region zu.",al={"ken'zigla geschichte","wer ist ken'zigla"}},{q="Warum wartet Grunzer Logmar in Camp Taurajo?",a="Grunzer Logmar ist in Camp Taurajo im Südlichen Brachland stationiert. Er verfolgt die Bewegungen der örtlichen Späher und besitzt die letzten bekannten Informationen darüber, wo Dogran verschwand, doch ihm fehlen Grunzer für eine eigenständige Rettung.",al={"wer ist grunzer logmar","logmar taurajo","grunzer logmars aufgabe"}},{q="Wie hängt diese Quest mit der Beschwörung einer Sukkubus zusammen?",a="Hexenmeister der Horde in Orgrimmar benötigen Dograns Anhänger, ein von Leidenschaft und Hingabe durchdrungenes Artefakt, um eine Sukkubus zu beschwören und zu binden. Sie müssen Dogran finden und mit Ken'ziglas Trunk sein Leben retten, um den Anhänger zu erhalten.",al={"warum trunk für sukkubusquest","sukkubus questreihe dogran"}},{q="Warum brachte der erste Kurier den Trunk nicht?",a="Der erste ins Steinkrallengebirge entsandte Bote erfüllte seinen Auftrag nie. Ken'zigla bereitete eine Ersatzdosis für den nächsten Reisenden zu, der nach Dogran suchte.",al={"was geschah mit dem ersten boten","vorheriger kurier"}},{q="Wohin führt die Spur nach Camp Taurajo?",a="Nachdem Grunzer Logmar den Trunk erhalten hat, schickt er Euch zu Dograns Häschern im Südlichen Brachland, wo der sterbende Späher als Geisel festgehalten wird.",al={"wo ist dogran","nächster schritt nach logmar"}}},fx={["0e638b4a"]={q="Warum möchte Ken'zigla, dass dies erledigt wird?",a="Ken'zigla hat den heilenden Trank bereits vorbereitet, in der Erwartung, dass ein weiterer Kurier in Dograns Namen eintreffen würde. Als Heiler, der unter den Trollen von Malaka'jin im Steinkrallengebirge lebt, ist das Brauen wirksamer Heilmittel sein Handwerk, und er hat kein Interesse daran, einen verletzten Krieger sterben zu sehen, wenn ein einfacher Trank ihn retten könnte.",al={"ken'ziglas beweggrund","warum den trank brauen","warum hilft ken'zigla"}},ff24236d={q="Warum möchte Ken'zigla, dass Ihr den Trank ausliefert?",a="Ken'zigla ist ein Apotheker, der in Malaka'jin im Steinkrallengebirge stationiert ist, weit entfernt vom Brachland. Den Trank durch die Berge hinunter nach Camp Taurajo zu liefern, ist ein langer und gefährlicher Fußmarsch, den er nicht selbst unternehmen kann, besonders während Dograns Leben an einem seidenen Faden hängt.",al={"warum schickt er mich","warum liefert sie den trank nicht selbst","warum muss der spieler den trank liefern"}}},fp="19,162,18.374.0,26.309.1,40.211.0,17.136.0,44.214.0,52.208.0,47.144.0,43.137.1"}
P.entries["quest:1512"] = {n="Die Liebesgabe",s="In Orgrimmar wartet Gan'rul Blutauge auf einen Anhänger, um einen Sukkubus anzulocken. Im Brachland gibt Dogran ein geschätztes Andenken auf, nachdem er gefunden und wiederbelebt wurde.",h="In Orgrimmar wartet Gan'rul Blutauge auf einen Anhänger, um einen Sukkubus anzulocken.",kw={"schmutzverkrusteter anhänger","gan'rul blutauge","grunzer dogran","die liebesgabe","orgrimmar","sukkubus","brachland","zankaja"},ang={["class:Warlock"]="Als Hexenmeister lernt Ihr, dass arkane Macht allein keinen Dämon binden kann. Ihr könnt einen Sukkubus fangen, indem Ihr seinen Hunger nach sterblichen Leidenschaften wie Liebe und Trauer gegen ihn wendet.",["faction:Horde"]="Als Mitglied der Horde seht Ihr, wie Grunzer Dogran den Tod im Kampf einem Leben als Last für seine Angehörigen vorzieht."},sec={{t="Das Opfer eines Grunzers",b="Grunzer Dogran wurde von den Borstennacken-Stachelebern im Brachland gefangen gehalten und gefoltert. Ken'ziglas Trunk weckt ihn, doch sein Körper kann sich nicht mehr erholen. Er würde lieber im Kampf sterben, als kampfunfähig zu seiner Gefährtin Zankaja zurückzukehren. Dogran gibt einen Schmutzverkrusteten Anhänger auf, ein Geschenk aus Liebe, und bittet darum, dass Zankaja niemals erfährt, was er hergegeben hat."},{t="Köder für einen Dämon",b="Ein Hexenmeister braucht einen Talisman voller starker, ungetrübter Gefühle, um einen Sukkubus zu beschwören und zu beherrschen. Diese Dämonen nähren sich von den Begierden der Sterblichen und verkehren wahre Zuneigung in Qual. Dograns Anhänger birgt seine Hingabe und die Erinnerung an ihren Abschied. Bringt ihn zu Gan'rul Blutauge in den schattigen Klüften von Orgrimmar, wo er ihn reinigt und poliert. Seine strahlende Gefühlskraft kann den Seelenverschlinger durch den Wirbelnden Nether locken."}},faq={{q="Warum braucht ein Hexenmeister Dograns Anhänger?",a="Sukkuben werden von tiefen Leidenschaften der Sterblichen angezogen, die sie verdrehen und verzehren. Dograns Anhänger birgt selbstlose Liebe und Opferbereitschaft, was ihn zu einem mächtigen Köder für einen Sukkubus macht.",al={"warum anhänger","sukkubusköder","warum schmutzverkrusteter anhänger"}},{q="Wer ist Grunzer Dogran?",a="Grunzer Dogran ist ein Krieger der Horde, der von den Borstennacken-Stachelebern im Südlichen Brachland gefangen genommen und gefoltert wurde. Ein alchemistischer Trunk bringt ihn wieder zu Bewusstsein, doch seine Verletzungen hindern ihn daran, als stolzer Krieger zu leben.",al={"wer ist dogran","grunzer dogran hintergrund"}},{q="Wer ist Zankaja?",a="Zankaja ist Dograns junge Gefährtin, die voller Sorge auf Nachricht von ihm wartete. Er gibt ihr Andenken auf und wählt den Tod eines Kriegers, statt ihr mit seiner Pflege zur Last zu fallen.",al={"zankaja hintergrund","dograns gefährtin"}},{q="Warum bittet Dogran Euch, dies vor Zankaja geheim zu halten?",a="Dogran will seine junge Gefährtin nicht an einen sterbenden Invaliden binden. Er gibt ihren Anhänger auf, wohl wissend, dass er nicht zu ihr zurückkehren wird, und bittet darum, ihr Schuldgefühle über seinen Ausgang zu ersparen.",al={"warum zankaja nichts sagen","dograns geheimnis"}},{q="Wer reinigt den Anhänger und warum?",a="Gan'rul Blutauge, der Hexenmeisterlehrer in Orgrimmar, nimmt den Anhänger und entfernt den Schmutz. Sein strahlendes Aussehen und seine Gefühlskraft können dann den beschworenen Dämon anlocken.",al={"gan'rul blutauges rolle","warum den anhänger reinigen"}},{q="Was geschieht unmittelbar nach Abschluss dieser Quest?",a="Gan'rul Blutauge schickt Euch mit dem gereinigten Anhänger in den Beschwörungskreis unter Orgrimmar. Dort vollzieht Ihr das Bindungsritual und stellt Euch dem Sukkubus allein.",al={"what comes next","nächste quest nach der liebesgabe"}}},fx={["528517eb"]={q="Warum schickt Euch Grunzer Dogran mit seinem Anhänger fort?",a="Dogran weigert sich, als Invalide weiterzuleben, der an seine junge Gefährtin Zankaja gekettet ist. Anstatt gebrochen nach Hause zurückzukehren und sie mit Kummer oder Schuldgefühlen zu belasten, beabsichtigt er, einen glorreichen Kriegertod im Kampf zu suchen, anstatt als leere Hülle dahinzuwelken. Die Trennung von dem Anhänger und Euch fortzuschicken, erlaubt ihm, dieses Band zu kappen, damit er sein Ende ehrenvoll zu seinen eigenen Bedingungen finden kann.",al={"warum gibt dogran dir den anhänger","dograns beweggrund love's gift","warum den dirt-caked pendant weggeben"}},["6232e4f3"]={q="Warum möchte Dogran, dass Ihr den Anhänger ausliefert?",a="Dogran ist nicht in der Verfassung, selbst nach Orgrimmar zu reisen, da er gerade brutale Gefangenschaft und Folter durch die Borstennacken-Stacheleber erlitten hat. Zudem beabsichtigt er ausdrücklich, ein Ende als Soldat auf dem Schlachtfeld zu finden, anstatt in die Zivilisation zurückzukehren. Ihr seid der einzige vertrauenswürdige Außenstehende, der ihn erreicht hat, was Euch zu seinem einzigen Mittel macht, das Andenken an Gan'rul zu übergeben, ohne Zankaja sein Schicksal zu offenbaren.",al={"warum ich love's gift","warum braucht dogran mich","warum kann dogran den anhänger nicht mitnehmen"}}},fp="11,154,19.340.1,16.419.0,41.164.0,20.201.0,15.165.1,57.191.1,31.172.0,53.162.1"}
P.entries["quest:1513"] = {n="Die Bindung",s="An Neeru Fireblades Kreis in Orgrimmar stellt Ihr Euch der Prüfung, einen Sukkubus zu binden. Dograns Anhänger lockt den Dämon aus dem Wirbelnden Nether herbei, worauf Ihr ihn durch Zauberkunst und Waffengewalt bezwingen müsst.",h="An Neeru Fireblades Kreis in Orgrimmar stellt Ihr Euch der Prüfung, einen Sukkubus zu binden.",kw={"bindung","die kluft der schatten","dogran","gan'rul","neeru","orgrimmar","anhänger","sukkubus","hexenmeister","zankaja"},ang={["class:Warlock"]="Als Hexenmeister beweist Ihr, dass Euer Wille die listigen, Unruhe stiftenden Dämonen des Nether beherrschen und ihren verführerischen Gefahren widerstehen kann.",["faction:Horde"]="Als Mitglied der Horde seht Ihr, wie die Fraktion im Verborgenen Dämonenbeschwörer in der Kluft der Schatten duldet, fernab der ehrbewussten Stadtbevölkerung.",["race:Orc"]="Als Orc tragt Ihr im Umgang mit Dämonen die bittere Last der einstigen Verderbnis Eures Volkes. Gan'ruls Forderung nach Disziplin und Kontrolle ist von dieser Geschichte geprägt."},sec={{t="Der Anker eines Dämons",b="Dograns Anhänger trägt Erinnerungen in die Beschwörung. Der verstümmelte Orc gab ihn her, obwohl er ein Andenken an seine Liebe zu Zankaja gewesen war. Er trug ihn durch Gefangenschaft und Qualen. Ihre Hingabe verleiht dem Anhänger die Kraft, über Welten hinwegzureichen, den Wirbelnden Nether zu überbrücken und die Aufmerksamkeit eines Sukkubus zu erregen."},{t="Der Kreis im Schatten",b="Unter den Klüften von Orgrimmar unterhält Neeru Feuerklinge ein Zelt mit einem Kreis, der für gefährliche Rituale vorbereitet ist. Unter Gan'rul Blutauges Anleitung aktiviert Ihr dessen Runen und stellt Euch dem beschworenen Sukkubus im Kampf. Einen Dämon zu rufen, ist nur der Anfang. Ihr müsst ihn allein überwältigen und seinen Geist Eurem Willen beugen."},{t="List und Willenskraft",b="Gan'rul Blutauge warnt, dass Sukkubi gefährliche Diener sein können. Ihre Gegenwart berauscht und verführt die Sinne, während sie unvorsichtigen Meistern Lebenskraft und Geist entziehen. Er mahnt Euch, an Dograns und Zankajas Leid zu denken, damit Hochmut und Selbstüberschätzung Euch nicht den Listen des Dämons ausliefern. Nur ein unbeugsamer Wille kann seiner Verlockung widerstehen."}},faq={{q="Was geschieht während dieses Rituals?",a="Ihr bringt Dograns Anhänger zum Kreis in Neeru Fireblades Zelt in der Kluft der Schatten. Die darin bewahrte Hingabe lockt einen Sukkubus aus dem Wirbelnden Nether herbei, und Ihr bekämpft den Dämon, bis er sich Eurem Willen unterwirft.",al={"wie funktioniert das ritual","was geschieht bei der bindung","sukkubusritual"}},{q="Wo findet die Beschwörung statt?",a="Die Beschwörung findet in Neeru Fireblades Zelt in der Kluft der Schatten unter Orgrimmar statt. Ein Ritualkreis ist in den Boden eingeritzt.",al={"wo ist der kreis","standort des beschwörungskreises","wo den sukkubus beschwören"}},{q="Wer war Dogran und warum wird sein Anhänger benötigt?",a="Dogran war ein Grunzer der Horde, der im Brachland von Stachelebern gefangen genommen und verstümmelt wurde. Sein Anhänger, ein Andenken an seine geliebte Zankaja, lockt einen Sukkubus herbei und dient ihm als Anker.",al={"wer ist dogran","warum dograns anhänger","dograns geschichte"}},{q="Wer ist Gan'rul Blutauge?",a="Gan'rul Blutauge ist ein hochrangiger Hexenmeisterlehrer in der Kluft der Schatten unter Orgrimmar. Er unterweist angehende Hexenmeister und führt sie durch Rituale zur Unterwerfung von Dämonen.",al={"wer vergibt die quest","wer ist gan'rul","gan'rul blutauges rolle"}},{q="Welche Macht erlangt ein Hexenmeister nach Abschluss dieser Prüfung?",a="Die Unterwerfung des Sukkubus schließt die Ausbildung eines Hexenmeisters ab und verleiht ihm das Wissen und die Runenbeherrschung, um jederzeit einen in seinen Dienst zu rufen.",al={"welche belohnung erhalten hexenmeister","warum einen sukkubus beschwören","sukkubus als begleiter fähigkeit"}},{q="Warum gilt die Beschwörung eines Sukkubus als besonders gefährlich?",a="Sukkubi bezaubern Sterbliche und spielen mit ihren Begierden. Ein allzu selbstsicherer Hexenmeister läuft Gefahr, dass seine Seele langsam ausgesaugt wird, bis die Arglist des Dämons seine Kontrolle überwindet.",al={"gefahr durch sukkubus","warum sind sukkubi riskant","sukkubus hintergrundgeschichte"}}},fx={["9ef07cc1"]={q="Warum möchte Gan'rul Blutauge, dass dies erledigt wird?",a="Als Mentor für die heranwachsenden Hexenmeister der Horde muss Gan'rul Blutauge Euren Willen und Eure magische Stärke testen, bevor er Euch das Kommando über gefährliche dämonische Diener gewährt. Indem er Euch anweist, eine Sukkubus mit dem tragischen Überbleibsel von Dograns Liebe zu beschwören und zu unterwerfen, lehrt er Euch Vorsicht gegenüber dämonischer Täuschung und Stolz. Sobald Ihr siegreich seid, beabsichtigt Gan'rul zudem, Dograns Anhänger zurückzugeben und die Nachricht an Zankaja zu überbringen.",al={"gan'rul blutauges beweggrund","warum sukkubus beschwören gan'rul","warum the binding quest"}},["9690a59c"]={q="Warum muss Gan'rul Blutauge die Beschwörung von Euch durchführen lassen, anstatt es selbst zu tun?",a="Dieses Ritual ist ein Initiationsritus, der allein für Euch bestimmt ist. Ein Hexenmeister muss einen beschworenen Dämon persönlich seinem Willen unterwerfen; kein Lehrer oder Stadtwache kann diese psychische Dominanz in Eurem Namen etablieren. Würde Gan'rul die Kreatur selbst bezwingen, würdet Ihr weder die Disziplin noch die Autorität erlangen, die erforderlich ist, um einen Sukkubus zu binden und zu befehligen.",al={"warum ich the binding","warum kann gan'rul den sukkubus nicht beschwören","warum muss ich sie beschwören"}},dee6d59e={q="Gegen wen werdet Ihr während des Rituals geschickt?",a="Ihr tretet gegen einen beschworenen Sukkubus an, der aus dem Wirbelnden Nether in den Beschwörungskreis innerhalb von Neeru Fireblades Zelt gezogen wird. Diese listigen dämonischen Verführerinnen lieben es, sterbliche Leidenschaften zu manipulieren und Seelen zu verschlingen. Indem Ihr das Scheusal mit Dograns Anhänger ködert – einem Objekt, das von sterblicher Liebe und Tragödie durchdrungen ist – zwingt Ihr es in die Realität, um es zu besiegen und zu meistern.",al={"ziel von the binding","was bekämpft man in the binding","beschworener sukkubus"}}},fp="11,202,16.310.1,25.306.0,19.341.1,32.206.0,36.137.0,45.150.1,24.165.0,58.135.0,60.167.0"}
P.entries["quest:1515"] = {n="Dograns Gefangenschaft",s="Im Camp Taurajo steht ein Hexenmeister vor einer wichtigen Prüfung der Horde: einen gefangenen Orc-Krieger retten. Mit Ken'ziglas Trunk müsst Ihr den schwer zugerichteten Grunzer Dogran finden und ihm Kraft zur Flucht geben.",h="Im Camp Taurajo steht ein Hexenmeister vor einer wichtigen Prüfung der Horde: einen gefangenen Orc-Krieger...",kw={"brachland","dogran","trunk","ken'zigla","logmar","borstennacken","sukkubus","taurajo","hexenmeister"},ang={["class:Warlock"]="Als Hexenmeister steht Ihr vor einem entscheidenden Schritt zum Verständnis sterblicher Leidenschaft und Opferbereitschaft, die zur Beschwörung eines Sukkubus nötig sind.",["faction:Horde"]="Als Mitglied der Horde wisst Ihr, dass Borstennacken überall im zentralen Brachland Patrouillen und Außenposten gefährden.",["race:Orc"]="Als Orc könnt Ihr in Dograns Durchhaltevermögen trotz Verstümmelung und Folter jene unbändige Widerstandskraft erkennen, die von einem orcischen Grunzer erwartet wird."},sec={{t="Eine einsame Rettung",b="Grunzer Logmar im Camp Taurajo will keine Soldaten der Horde bei einem verlustreichen Angriff auf die verschanzten Borstennacken riskieren. So liegt Grunzer Dograns Schicksal in Euren Händen, als angehender Hexenmeister, der nur mit Ken'ziglas Trunk bewaffnet ist. Reist nach Norden durch das Dornengestrüpp und die feindlichen Lager, um herauszufinden, wo die Borstennacken ihn gefangen halten."},{t="Der Preis des Blutes",b="Inmitten feindlicher Borstennacken liegt Grunzer Dogran schwer zugerichtet in den Hütten nördlich von Taurajo. Ken'ziglas Trunk gibt ihm genug Kraft, um in Sicherheit zu humpeln, doch seine Verletzungen lassen ihn dauerhaft verstümmelt zurück. Er verliert einen Arm und ein Bein."}},faq={{q="Wo wird Grunzer Dogran gefangen gehalten?",a="Grunzer Dogran wird in einer kleinen Ansammlung von zwei Borstennackenhütten direkt nördlich von Camp Taurajo im Brachland gefangen gehalten.",al={"dogran aufenthaltsort","wo ist dogran","dogran im brachland finden"}},{q="Warum schickt Grunzer Logmar keine Soldaten zu Hilfe?",a="Grunzer Logmar kann keine Truppen von der Verteidigung von Camp Taurajo abziehen. Er hält eine Rettung im schwer bewachten Gebiet der Borstennacken für zu gefährlich, um weitere Soldatenleben zu riskieren.",al={"warum helfen keine hordenwachen","logmar soldaten","taurajo verstärkung"}},{q="Was ist Ken'ziglas Trunk?",a="Ken'ziglas Trunk ist ein starkes, übel schmeckendes Stärkungsmittel, das dem schwer verletzten Dogran genug Kraft geben soll, aufzustehen und der Gefangenschaft der Borstennacken zu entkommen.",al={"kenzigla trank","was ist der trunk","dogran medizin"}},{q="In welchem Zustand wird Dogran gefunden?",a="Dogran steht am Rande des Todes, gezeichnet von schweren Wunden und der Folter durch die Borstennacken. Selbst nachdem er den Trunk getrunken hat, sind sein Arm und sein Bein unheilbar geschädigt.",al={"dogran verletzungen","lebt dogran","dogran arm bein"}},{q="Was hat diese Rettung mit der Beschwörung eines Sukkubus zu tun?",a="Dogran trägt ein Zeichen der Liebe und der Hingabe Sterblicher bei sich, Gefühle und Vorstellungen, die Hexenmeister nutzen, um einen Sukkubus zu beschwören und zu binden.",al={"warum tun hexenmeister das","zusammenhang mit sukkubusquest","hexenmeisterquest dogran"}},{q="Wer hat Dogran gefangen genommen?",a="Dogran wurde von Borstennackenstämmen gefangen genommen, die im Dornengestrüpp nördlich von Camp Taurajo leben.",al={"wer hat dogran verschleppt","dograns kerkermeister","brachland entführer"}}},fx={b38341a7={q="Warum möchte Grunzer Logmar, dass Dogran gefunden wird?",a="Grunzer Dogran ist einer von Logmars Kameraden, der während einer Patrouille im Brachland von den Stachelebern gefangen genommen wurde. Obwohl Logmar keine Soldaten der Horde entbehren oder einen militärischen Angriff für eine Rettungsaktion riskieren kann, ist er nicht bereit, seinen Kameraden vollständig aufzugeben. Da er Eure Entschlossenheit gesehen hat, diesen Punkt zu erreichen, erlaubt Logmar Euch, einen Rettungsversuch auf eigene Faust mit Ken'ziglas Trank zu unternehmen, um Dogran eine Chance auf das Überleben zu geben.",al={"warum dogran helfen","grunzer logmars beweggrund","warum dogran retten"}}},fp="18,191,15.297.0,18.220.1,27.107.0,45.164.0,28.161.0,39.167.1,52.123.1,20.84.0"}
P.entries["quest:1516"] = {n="Ruf der Erde",s="Im Tal der Prüfungen prüft Canaga Erdenrufer Ausdauer und Geduld angehender Schamanen der Horde. Ihre Jagd auf Teufelspirscher dient der Vorbereitung einer rituellen Sapta.",h="Im Tal der Prüfungen prüft Canaga Erdenrufer Ausdauer und Geduld angehender Schamanen der Horde.",kw={"burning blade","ruf der erde","canaga erdenrufer","erdtotem","teufelspirscher","sapta","schamanenprüfung","das tal der prüfungen"},ang={["class:Shaman"]="Als Schamane beginnt Ihr hier die förmliche Zwiesprache mit den Elementen. Damit legt Ihr den Grundstein für Euer Erdtotem.",["race:Orc"]="Als Orc unter Thralls Horde ehrt Ihr alte Clantraditionen aus der Zeit vor der dämonischen Verderbnis, indem Ihr auf den schamanischen Pfad zurückkehrt.",["race:Troll"]="Als Troll folgt Ihr den Hexendoktoren und Spiritualisten der Dunkelspeere und wendet Euch den Erdgeistern zu. Sie unterstützen die neue Heimat Eures Volkes an der Seite der Orcs."},sec={{t="Die erste Bindung",b="Ein Schamane lernt zunächst, sich mit jedem Element zu verbinden. Für Orcs und Trolle beginnt dieser Pfad mit der Erde, dem Fundament des Lebens, der Ausdauer und der Geduld. Im Tal der Prüfungen führt Canaga Erdenrufer angehende Schamanen. Er lehrt sie, dass die Erde Respekt und Standhaftigkeit verlangt, bevor sie Schutz gewährt."},{t="Eine reinigende Jagd",b="Nördlich des Tals der Prüfungen wirkt der Kult der Burning Blade dunkle Magie in den Schluchten. Seine Zauber beschwören Teufelspirscher, verderbte Hunde von jenseits dieser Ebene. Die Jagd auf sie prüft, ob ein Schamane das Land vor unnatürlichem Verfall bewahren kann. Canaga braut aus ihren Hufen eine Earth Sapta, einen heiligen Trank, der sterblichen Augen die Elementarebene offenbart."}},faq={{q="Welchen Zweck hat diese Prüfung?",a="Mit dieser Prüfung beginnt ein Schamane das Studium der elementaren Mysterien und beweist vor den Erdgeistern Geduld und spirituelle Disziplin. Sie bereitet ihn darauf vor, mit diesen Geistern Zwiesprache zu halten und sich ein Erdtotem zu verdienen.",al={"warum ruf der erde machen","was gibt ruf der erde","zweck der quest"}},{q="Wer ist Canaga Erdenrufer?",a="Canaga Erdenrufer ist ein Schamanenlehrer der Trolle im Tal der Prüfungen in Durotar. Er führt junge Schamanen der Orcs und Trolle sowie zu Besuch kommende Taurenschamanen zur Beherrschung der Elemente.",al={"wer ist canaga","canaga erdenrufer hintergrundgeschichte"}},{q="Warum braucht Canaga Teufelspirscherhufe?",a="Canaga verwendet Teufelspirscherhufe, um eine Earth Sapta zuzubereiten. Der Trank lässt einen sterblichen Schamanen Elementargeister wahrnehmen und mit ihnen sprechen.",al={"warum teufelspirscherhufe","zweck der hufe"}},{q="Wo befinden sich die Teufelspirscher?",a="Teufelspirscher suchen die Höhle und die umliegenden Klippen nördlich der Übungsplätze im Tal der Prüfungen heim. Sie befinden sich im Koven der Brennenden Klinge.",al={"fundort der teufelspirscher","wo teufelspirscher finden"}},{q="Können andere Völker der Horde diese Variante der Prüfung ablegen?",a="Ja. Die Prüfung richtet sich vor allem an Schamanen der Orcs und Trolle, die in Durotar erwachsen werden. Taurenschamanen, die von der Hochwolkenebene anreisen, können sie ebenfalls im Tal der Prüfungen ablegen.",al={"können tauren das machen","nur für orcs"}},{q="Welche Tugenden verkörpert die Erde für einen Schamanen?",a="In der schamanischen Tradition ist die Erde das Fundament des Lebens. Sie verkörpert große Stärke, Ausdauer und ewige Geduld, kann jedoch eigensinnig und launisch sein, wenn man ihr keinen Respekt erweist.",al={"tugenden der erde","bedeutung der erde für schamanen"}}},fx={a9a10a24={q="Warum möchte Canaga Erdenrufer, dass dies erledigt wird?",a="Canaga dient als Führer für junge Schamanen, die ihre ersten Schritte auf dem spirituellen Pfad unternehmen. Er spürt, dass eine Zeit des Konflikts bevorsteht und dass Ihr den ausdauernden Geist besitzt, der erforderlich ist, um mit der Erde in Verbindung zu treten. Bevor er die heilige Sapta vorbereiten und die Geheimnisse der Erde teilen kann, muss er Eure Entschlossenheit, Stärke und Geduld gegenüber gefährlichen Widersachern testen, um sicherzustellen, dass Ihr bereit seid, den Ruf der Elemente zu beachten.",al={"canaga erdenrufers beweggrund","warum testet canaga dich","canaga erdenrufer warum"}},["3057b25e"]={q="Warum sind die Teufelspirscher im Tal der Prüfungen?",a="Diese dämonischen Hunde suchen die nördlichen Bereiche des Tals heim, beschworen und gebunden von den schattenhaften Hexenmeistern des Kovens der Brennenden Klinge, die sich in den örtlichen Höhlen versteckt haben. Ihre üble Präsenz beschmutzt das umliegende Land, was sie sowohl zu einer unmittelbaren Bedrohung für junge Eingeweihte als auch zu einer passenden Prüfung für den Mut und die Kampfstärke eines angehenden Schamanen macht.",al={"warum sind hier teufelspirscher","teufelspirscher tal der prüfungen","was sind teufelspirscher"}},dddcc185={q="Warum müsst Ihr Euch den Teufelspirschern stellen anstatt den Wachen des Tals?",a="Dies ist eine persönliche spirituelle Prüfung, keine militärische Standardoperation. Ein Schamane muss seine eigene Harmonie mit den Elementen durch persönliche Prüfung und demonstrierte Stärke etablieren. Krieger oder Wachen die Hufe sammeln zu lassen, würde den sturen Geistern der Erde nichts beweisen, die verlangen, dass Ihr Euch der Gefahr direkt stellt und Eure eigene Geduld, Ausdauer und Fähigkeit beweist, bevor sie ihre Macht gewähren.",al={"warum ich call of earth","warum keine wachen schicken teufelspirscher","warum muss ich teufelspirscher jagen"}}},fp="13,154,14.298.0,16.345.0,34.200.0,26.162.0,39.131.0,34.145.0,58.168.0,50.163.0"}
P.entries["quest:1517"] = {n="Ruf der Erde",s="Am Geisterfelsen führt Canaga Erdenrufer junge Schamanen zu ihrer ersten Zwiesprache mit den Elementen. Ein Earth Sapta lässt sie auf heiligem Boden die Schwache Erdmanifestation sehen.",h="Am Geisterfelsen führt Canaga Erdenrufer junge Schamanen zu ihrer ersten Zwiesprache mit den Elementen.",kw={"ruf der erde","canaga erdenrufer","earth sapta","verborgener pfad","schwache erdmanifestation","saptasicht","geisterfelsen","das tal der prüfungen"},ang={["class:Shaman"]="Als Schamane macht Ihr Euren ersten Schritt auf dem Weg zur Einstimmung auf die Elemente. Wahre Meisterschaft beginnt mit der stillen Geduld der Erde.",["race:Orc"]="Für Orcs, die nach Generationen der Verderbnis durch Teufelsmagie zu den Wegen ihrer Ahnen zurückkehren, ist die Zwiesprache durch das Earth Sapta eine heilige Wiederentdeckung der traditionellen Verbindung ihres Volkes mit den Geistern.",["race:Troll"]="Als Dunkelspeertroll nehmt Ihr diese Erdriten an, um Eure tiefe Verbundenheit mit den Ahnen an Durotars raue, sonnenversengte Landschaft anzupassen."},sec={{t="Die Macht des Saptas",b="Ein Sapta ist ein seltener Trank, den nur wenige Schamanenmeister kennen. Elementarmagie verbindet durch ihn die sterbliche Wahrnehmung mit der Geisterebene und verleiht Willensstarken die Saptasicht. Da er den Geist des Trinkenden direkt an ein Element bindet, verbietet die Tradition, ihn außerhalb geweihten, heiligen Bodens zu trinken."},{t="Pilgerreise zum Geisterfelsen",b="Um mit der Erde Zwiesprache zu halten, verlasst Ihr das Tal der Prüfungen und steigt über den Verborgenen Pfad in Durotars südliche Felsberge hinauf. Der Geisterfelsen wartet am Ende des Pfades, ein hoch gelegenes Heiligtum über dem zerklüfteten Ödland. Trinkt dort das Sapta, und Ihr könnt sehen, was gewöhnlichen Augen verborgen bleibt: eine elementare Präsenz inmitten des Gesteins."},{t="Die Geduld der Erde",b="Die Schwache Erdmanifestation verlangt weder Blutvergießen noch Unterwerfung. Sie bittet Euch lediglich, demütig vor die Welt zu treten. Feuer, Wasser und Luft tragen unruhige, unbeständige, oft chaotische Geister in sich, während die Erde Beständigkeit lehrt. Berge überdauern, und Ebenen lehren grenzenlose Geduld."}},faq={{q="Was ist ein Earth Sapta?",a="Ein Earth Sapta ist ein Trank, den erfahrene Schamanen brauen, um den Geist des Trinkenden vorübergehend auf die Erde einzustimmen. Er verleiht die innere Sicht, die nötig ist, um verborgene Elementargeister zu sehen und mit ihnen zu sprechen.",al={"was ist sapta","earth sapta bedeutung","was bewirkt sapta"}},{q="Wo liegt der Geisterfelsen?",a="Der Geisterfelsen liegt in den zerklüfteten Bergen südwestlich von Den im Tal der Prüfungen. Folgt dem Verborgenen Pfad in die Hügel südlich der Talsohle, um ihn zu erreichen.",al={"wo ist der geisterfelsen","geisterfelsen standort","geisterfelsen finden"}},{q="Warum muss das Sapta am Geisterfelsen getrunken werden?",a="Die schamanische Tradition erlaubt es nur, ein Sapta an einer dafür bestimmten heiligen Stätte zu trinken. An heiligen Stätten wie dem Geisterfelsen ist der Schleier zwischen der Welt der Sterblichen und den Elementargeistern von Natur aus dünn.",al={"warum am geisterfelsen trinken","sapta überall trinken"}},{q="Wer ist die Schwache Erdmanifestation?",a="Die Schwache Erdmanifestation ist ein Elementargeist, der am Geisterfelsen wohnt. Nur die Saptasicht kann ihn sichtbar machen, und der Geist begrüßt junge Schamanen, um ihre Demut zu prüfen und erste Lehren des elementaren Gleichgewichts zu vermitteln.",al={"manifestation der erde","wer ist der erdgeist"}},{q="Kann jeder Schamane der Horde diese Prüfung ablegen?",a="Vor allem junge Schamanen der Orcs und Dunkelspeertrolle, die in Durotar ausgebildet werden, vollziehen diesen Ritus. Taurenschamanen, die hierherreisen, können ihn ebenfalls vollziehen, doch ihr entsprechender Ritus findet auf der Hochwolkenebene statt.",al={"können tauren diese quest machen","wer kann ruf der erde machen"}},{q="Wie reagiert der Erdgeist auf den Initianden?",a="Anders als die unbeständigen Manifestationen des Feuers oder der Luft heißt der Erdgeist Initianden willkommen, die sich ihm mit demütigem Respekt nähern. Er gewährt seinen Segen, ohne eine Kraftprobe zu verlangen.",al={"was sagt der erdgeist","ist der erdgeist feindselig"}}},fx={["1aaf4733"]={q="Warum möchte Canaga Erdenrufer, dass dies erledigt wird?",a="Canaga Erdenrufer führt Euch auf dem spirituellen Pfad des Schamanen. Nachdem Ihr Eure Bereitschaft durch das Sammeln der notwendigen Ritualkomponenten bewiesen habt, verlangt er nun von Euch, die Erd-Sapta am Geisterfelsen zu trinken. Sein Ziel ist es, Eure Bindung mit den Elementargeistern des Landes zu schmieden, damit Eure Vision den Schleier durchdringen und direkt mit der Erde kommunizieren kann.",al={"canagas beweggrund","warum zum geisterfelsen schicken","warum erd-sapta trinken"}},["99304602"]={q="Warum schickt Canaga Erdenrufer Euch, anstatt selbst zu gehen?",a="Diese Reise ist ein heiliger Initiationsritus, den jeder angehende Schamane persönlich unternehmen muss. Die Erd-Sapta bindet den Geist des Trinkenden an das Element und gewährt eine Vision, die nicht durch einen Stellvertreter erfahren werden kann. Canaga befehligt diese Verbindung bereits; Ihr müsst selbst demütig vor der Erde stehen, um ihren Segen zu verdienen.",al={"warum ich canaga","warum spieler zum geisterfelsen schicken","warum muss ich die sapta trinken"}}},fp="13,183,22.296.0,25.303.0,21.285.0,23.183.0,29.163.0,46.180.0,40.220.0,42.197.0,48.185.0"}
P.entries["quest:1518"] = {n="Ruf der Erde",s="In Durotar sucht Ihr die Gunst des Erdgeistes und kehrt mit Rohquarz zu Canaga Erdenrufer zurück. Er formt daraus Euer erstes Elementartotem.",h="In Durotar sucht Ihr die Gunst des Erdgeistes und kehrt mit Rohquarz zu Canaga Erdenrufer zurück.",kw={"ruf der erde","canaga erdenrufer","durotar","erdtotem","schwache manifestation","rohquarz","schamane","das tal der prüfungen"},ang={["class:Shaman"]="Als Schamane erhaltet Ihr durch diesen Ritus Euer erstes Totem. Es erlaubt Euch, Euch in den Elementen zu verwurzeln und den Boden um Beistand anzurufen.",["faction:Horde"]="Als Mitglied der Horde wisst Ihr, dass Kalimdors Elemente wild und ungezähmt sind. Der Bund, den die Schamanen der Horde mit ihnen schließen, ist für das Überleben ihrer neuen Siedlungen unerlässlich.",["race:Orc"]="Als Orc nehmt Ihr an der Wiederbelebung des orcischen Schamanismus in Durotar teil. Nach Jahrzehnten dämonischer Verderbnis wendet Ihr Euch wieder dem Gleichgewicht der Elemente zu.",["race:Troll"]="Als Troll lernt Ihr an der Seite der Orcs im Tal der Prüfungen. Ihr erweitert die traditionelle Zwiesprache der Hexendoktoren und Spiritualisten der Dunkelspeer um die vier Elementarpfade."},sec={{t="Herz des Steins",b="Ein angehender Schamane sucht die Erde durch Geduld und Demut. Rohe Stärke allein gewinnt die Gunst des Geistes nicht. Die Schwache Erdmanifestation gibt Euch Rohquarz. Dieser kleine Stein beweist, dass der Geist Euer Gelöbnis angenommen hat, und birgt den Samen der Macht."},{t="Der erste von vier Pfaden",b="Ihr vollendet die Prüfung, wenn Ihr den Quarz zu Canaga Erdenrufer im Tal der Prüfungen bringt. Canaga formt daraus ein Erdtotem, den Fokus, durch den Ihr den unerschütterlichen Schutz und die Stärke des Bodens kanalisiert.\n\nMit der Erde beginnt Euer Weg durch die vier Elementardisziplinen. Der Ritus legt den Grundstein für ein Leben in Zwiesprache mit der natürlichen Welt."}},faq={{q="Wozu dient der Rohquarz?",a="Der Rohquarz ist ein Zeichen der Schwachen Erdmanifestation und ein Beweis dafür, dass Ihr mit dem Geist Zwiesprache gehalten habt. Canaga Erdenrufer setzt ihn als Herzstück und Fokus für Eure Erdzauber in Euer Erdtotem ein.",al={"rohquarz","was bewirkt quarz","zweck von quarz"}},{q="Wer ist Canaga Erdenrufer?",a="Canaga Erdenrufer bildet Schamanen im Tal der Prüfungen in Durotar aus. Er führt junge Orc- und Trollinitianden durch ihre ersten Prüfungen, bereitet sie auf die Zwiesprache mit Elementargeistern vor und formt ihre ersten Totems.",al={"canaga","canaga erdenrufer","wer ist canaga"}},{q="Können Tauren diese Quest absolvieren?",a="Ja. Tauren vollenden ihre Prüfung der Erde gewöhnlich bei ihren eigenen Ältesten auf der Hochwolkenebene in Mulgore. Jeder Schamane der Horde, der ins Tal der Prüfungen reist, kann den Ritus bei Canaga Erdenrufer durchlaufen.",al={"können tauren ruf der erde in durotar absolvieren","taurenschamane durotar","tauren ruf der erde"}},{q="Was bedeutet es, das Erdtotem zu erhalten?",a="Ein Erdtotem zu erhalten bedeutet, dass der Geist der Erde Euch anerkannt hat. Es kennzeichnet Euren Stand unter den Schamanen und gibt Euch einen greifbaren Fokus für Segnungen und Schutzzauber der Erde.",al={"warum erdtotem erhalten","schamane erdtotem bedeutung"}},{q="Welche Tugenden verlangt die Erde von einem Schamanen?",a="Der Geist verlangt von einem Initianden Geduld, Stärke und Weisheit. Selbst der kleinste Kiesel kann durch Ausdauer Berge überdauern. Die Erde lehrt Schamanen, den Boden zu achten, damit er sie im Gegenzug trägt.",al={"lehren des erdgeistes","was verlangt die erde"}},{q="Wohin führt der Weg des Schamanen danach?",a="Erde ist das erste der vier Elemente, die ein Schamane meistern muss. Im weiteren Verlauf Eurer Ausbildung werdet Ihr gerufen, Zwiesprache mit den Geistern des Feuers, des Wassers und der Luft zu suchen.",al={"welches totem als nächstes","nach dem erdtotem","vier pfade schamane"}}},fx={["946f939a"]={q="Warum gibt Euch die Schwache Erdmanifestation den Rohquarz?",a="Nachdem sie Eure Entschlossenheit getestet und Eure Gemeinschaft anerkannt hat, gewährt Euch der Geist den Rohquarz als greifbaren Beweis Eurer Bindung. Er möchte, dass Ihr diesen kleinen Stein zu Canaga Erdenrufer zurückbringt, damit er als lebendiges Herz Eures ersten Totems dienen kann, das die ausdauernde Stärke und Geduld der Erde direkt mit Eurer spirituellen Praxis verbindet.",al={"beweggrund der schwachen erdmanifestation","warum rohquarz","warum schickt die erdmanifestation"}}},fp="13,145,18.262.0,23.364.0,34.215.0,26.220.0,25.202.0,44.187.0,49.210.0,41.164.0"}
P.entries["quest:1519"] = {n="Ruf der Erde",s="Die Erde ruft einen Schamanen zu einer geduldigen Prüfung der Zwiesprache. Indem der Suchende ein irdenes Sapta annimmt, beschreitet er einen Pfad spiritueller Wiedergeburt und lernt, das Fundament des Lebens zu hören.",h="Die Erde ruft einen Schamanen zu einer geduldigen Prüfung der Zwiesprache.",kw={"call of earth","earth mother","elemente","geduld","wiedergeburt","sapta","schamane","ausdauer"},ang={["class:Shaman"]="Für Euch als Schamanen markiert dieser Ritus einen Wendepunkt in Eurer Ausbildung. Die Zwiesprache mit der Erde bringt Stärke, Ausdauer und tiefe spirituelle Einsicht.",["faction:Horde"]="Als Mitglied der Horde schöpfen Eure schamanischen Traditionen aus den Elementen. Euer Pfad beginnt mit der fest verwurzelten Widerstandskraft der Erde.",["race:Tauren"]="Als Tauren steht die Verehrung der Earth Mother im Mittelpunkt Eurer Kultur. Diese Prüfung ehrt die Glaubensvorstellungen Eurer Ahnen."},sec={{t="Das Fundament aller Dinge",b="Ein Schamane lernt durch einen prägenden Ritus, mit der Urkraft der Erde Zwiesprache zu halten. Die Erde ist das sturste und weiseste der Elemente, das beständige Fundament allen Daseins. Sie bewegt sich in langsamen Zyklen von Erosion und Wiedergeburt. Berge verwittern zu Wüsten, und Flüsse graben über Zeitalter hinweg Schluchten. Um die Stimme der Erde zu hören, braucht ein Initiand dieselbe Geduld."},{t="Sapta und Wiedergeburt",b="Dem Ruf zu folgen, verändert einen Suchenden so sehr, dass er nie zu seiner früheren Unwissenheit zurückkehren kann. Wenn der Initiand seine Bereitschaft und seinen Respekt vor den Gesetzen der Earth Mother beweist, erhält er ein irdenes Sapta. Das Elixier eröffnet eine neue Sichtweise, und der Schamane beginnt, die Geheimnisse der Erde um Stärke, Ausdauer und elementaren Schutz zu begreifen."}},faq={{q="Was ist Call of Earth?",a="Call of Earth prüft die Geduld eines angehenden Schamanen und seine Bereitschaft, mit der Erde Zwiesprache zu halten. Der Suchende muss ihrer beständigen Weisheit Gehör schenken.",al={"was ist call of earth","erde quest schamane","zweck von call of earth"}},{q="Wofür steht das Element Erde in der schamanischen Tradition?",a="Die Erde ist das Fundament aller Dinge und verkörpert Stärke, Ausdauer und Geduld. Sie ist das sturste und weiseste Element und lehrt, dass alle Dinge mit der Zeit verwittern und wiedergeboren werden.",al={"wofür steht erde","hintergrund zum element erde","bedeutung der erde für schamanen"}},{q="Was ist ein Sapta?",a="Ein Sapta ist ein elementarer Trank, den ein schamanischer Mentor zubereitet. Ihn anzunehmen eröffnet einen spirituellen Pfad und stimmt die Sinne des Suchenden auf Elementargeister ein.",al={"was ist ein sapta","earth sapta","was bewirkt sapta"}},{q="Wer ist die Earth Mother, die in der Prüfung erwähnt wird?",a="Die Earth Mother ist die Quelle des Lebens und des Gleichgewichts und wird besonders von Taurenschamanen verehrt. Sie beschützt jene, die ihre Gesetze achten, und gewährt Suchenden Weisheit, die das Land respektieren.",al={"wer ist die earth mother","hintergrund zur earth mother","verbindung zur earth mother"}},{q="Was geschieht, wenn man dem Ruf folgt?",a="Dem Ruf zu folgen bereitet den Suchenden auf den nächsten Schritt seines Pfades vor. Es bringt eine spirituelle Wiedergeburt, nach der ein Schamane nicht zur Unwissenheit zurückkehren kann und neue Geheimnisse der Erde sichtbar werden.",al={"was geschieht beim abschluss","nach call of earth","call of earth wiedergeburt"}},{q="Warum braucht man Geduld, um mit der Erde Zwiesprache zu halten?",a="Die Erde bewegt sich in Zyklen von Erosion und Wiedergeburt. Berge verwittern zu Wüsten und Flüsse graben Schluchten, daher braucht ein Schamane Geduld und Ausdauer, um sich auf diese beständigen Rhythmen einzustimmen.",al={"warum erfordert erde geduld","geduld und erde"}}},fp="13,187,28.357.0,21.315.0,26.128.0,60.180.0,16.150.0,47.178.0,37.189.0,51.180.0"}
P.entries["quest:152"] = {n="Ärger an der Küste",s="Schiffbrüchige Seeleute kämpfen darum, Westfalls Westküste zu erreichen, während Murlocs näher rücken. Kapitän Grausohn ruft Euch auf, die Strände zu räumen, damit Überlebende sicher an Land kommen können.",h="Schiffbrüchige Seeleute kämpfen darum, Westfalls Westküste zu erreichen, während Murlocs näher rücken.",kw={"kapitän grausohn","küstenläufer","großes meer","murloc","orakel","schiffswracks","gezeitenjäger","der leuchtturm von westfall"},ang={["faction:Alliance"]="Da die Armee von Sturmwind in Westfall fehlt, hat die Volksmiliz Mühe, die Bauernhöfe im Landesinneren zu schützen. Verbündete wie Kapitän Grausohn helfen, die Küste zu verteidigen.",["race:Human"]="Als Mensch wisst Ihr, dass Handelsschiffe und Fischer schon lange Westfalls Gewässer befahren. Die von Murlocs beherrschte Küste ist ein bitteres Zeichen für die verlorenen Grenzgebiete des Königreichs."},sec={{t="Ein Friedhof der Schiffe",b="Riffe, Sturmböen und schroffe Felsen treiben Schiffe auf Westfalls Untiefen. Überlebende klammern sich an Wrackteile und kriechen auf den Sand, in der Hoffnung auf Hilfe. Stattdessen treffen sie entlang der Küste auf Murlocstämme, und die Murlocs kennen keine Gnade mit Schiffbrüchigen."},{t="Der geisterhafte Ausguck",b="Kapitän Grausohn hält auf einem einsamen Felsvorsprung südwestlich des Festlands Wache. Obwohl er tot ist, bleibt er an den Leuchtturm und seine Pflicht gegenüber vorbeifahrenden Schiffen und verirrten Seeleuten gebunden. Küstenläufer beherrschen die nördliche Küste. Weiter südlich versammeln sich Gezeitenjäger, Krieger und Orakel."}},faq={{q="Wer ist Kapitän Grausohn?",a="Kapitän Grausohn ist der geisterhafte Seekapitän, der im Leuchtturm von Westfall spukt. Er fühlt sich noch immer verpflichtet, Seeleute in gefährlichen Gewässern und Überlebende von Schiffbrüchen zu beschützen.",al={"kapitän grausohn","geist im leuchtturm","leuchtturmwärter westfall"}},{q="Warum will Grayson die Murlocs von der Küste vertreiben lassen?",a="Grayson will die Murlocs vertreiben lassen, weil schiffbrüchige Seeleute oft an Westfalls Küste angespült werden. Murlocs überrennen die Strände von Norden bis Süden und töten Überlebende, die das Land erreichen.",al={"warum murlocs in westfall töten","ärger an der küste grund","warum die küste räumen"}},{q="Wo halten sich diese verschiedenen Murlocs auf?",a="Murlocküstenläufer leben meist an Westfalls nördlicher Küste. Murlockrieger, Orakel und Gezeitenjäger versammeln sich in Siedlungen und Lagern an den südlichen Stränden.",al={"murlocstandorte westfall","wo sind küstenläufer","wo sind gezeitenjäger"}},{q="Ist Kapitän Grausohn der Allianz oder der Horde feindlich gesinnt?",a="Kapitän Grausohn ist neutral. Seine Pflicht gegenüber Seeleuten reicht über politische Grenzen hinaus, und er bittet jeden fähigen Reisenden, die Küste sicherer zu machen.",al={"ist grayson freundlich","grayson fraktion","kann die horde diese quest machen"}},{q="Muss für diese Quest zuerst das Leuchtfeuer wieder entzündet werden?",a="Nein. Kapitän Grausohn bittet Euch, die Küste zu räumen, unabhängig davon, ob Ihr geholfen habt, das Leuchtfeuer im Leuchtturm von Westfall wieder zu entzünden.",al={"ist keeper of the flame zuerst nötig","voraussetzung für ärger an der küste"}},{q="Arbeiten die Murlocs für die Bruderschaft der Defias?",a="Nein. Die Murlocs handeln eigenständig und greifen jeden an, der ihre Jagdgründe an der Küste betritt. Die Bruderschaft der Defias ist in der Nähe tätig, in der Gegend um Mondbruch und in den südlichen Buchten.",al={"sind defias mit murlocs verbündet","verbindung zwischen defias und murlocs"}}},fx={["9a80f3b4"]={q="Welche Murlocs bedrohen die Küste von Westfall?",a="Ihr jagt die Murlocs, die die westlichen Strände von Westfall bevölkern: Küstenläufer, die durch die nördliche Brandung streifen, sowie Krieger, Gezeitenjäger und Orakel, die sich weiter südlich verschanzt haben. Diese Wasserraubtiere nisten zwischen den Schiffswracks an der Küste, plündern gestrandete Schiffe und greifen jeden an, der das Unglück hat, an den Strand gespült zu werden.",al={"welche murlocs töte ich","wer sind die küsten-murlocs","murloc-ziele küste westfall"}},["49634979"]={q="Warum benötigt Kapitän Grausohn einen Abenteurer, um gegen die Murlocs zu kämpfen?",a="Kapitän Grausohn ist ein rastloser Geist, der an die einsamen Felsen vom Leuchtturm von Westfall gebunden ist. Da er selbst nicht am Ufer entlangmarschieren kann und die Garnison von Sturmwind die Region der Räuberei überlassen hat, ist er voll und ganz auf durchreisende Abenteurer wie Euch angewiesen, um die Strände für überlebende Seeleute zu sichern.",al={"warum tötet grausohn keine murlocs","warum braucht grausohn mich","warum säubern die wachen nicht die küste"}}},fp="21,163,20.237.0,19.275.0,23.170.0,57.176.0,42.166.0,52.130.0,56.111.0,51.176.0"}
P.entries["quest:1520"] = {n="Ruf der Erde",s="Am Kodofels sucht Ihr durch einen heiligen Ritus der Tauren Zwiesprache mit der Erde. Trinkt eine Earth Sapta, um eine Schwache Erdmanifestation zu sehen.",h="Am Kodofels sucht Ihr durch einen heiligen Ritus der Tauren Zwiesprache mit der Erde.",kw={"ruf der erde","camp narache","earth sapta","kodofels","manifestation","mulgore","sapta","seherin rabenfeder"},ang={["class:Shaman"]="Für Euch als Schamanen bildet dieser Ritus den spirituellen Kern Eurer Bindung an das Land. Er ist die Brücke zur Zwiesprache mit der Erde und zum Empfang eines Erdtotems.",["race:Tauren"]="Als Tauren könnt Ihr am Sapta-Ritual teilnehmen, einer der ehrwürdigsten Prüfungen auf dem Weg zum Erwachsensein für Spiritualisten auf der Hochwolkenebene."},sec={{t="Der Zweck der Sapta",b="Schamanische Älteste brauen eine Sapta, um den sterblichen Geist eines Initianden mit einem Urelement zu verbinden. Ahnenmagie hütet das Rezept, das nur wenige Tauren kennen. Trinkt den Trank an einer heiligen Stätte, und Euer Geist öffnet sich über die stoffliche Welt hinaus. Der Schleier teilt sich und offenbart die Elemente in ihrer ursprünglichen Form."},{t="Zwiesprache am Kodofels",b="Östlich von Camp Narache erhebt sich der Kodofels als Steinsäule und heiliges Refugium. Trinkt dort die Sapta, und eine Schwache Erdmanifestation erscheint vor Euch. Andere Aspekte der Natur auf dem Pfad des Schamanen sind unbeständig, feurig oder tobend. Die Erde verlangt stille Demut. Ehrt das Land, und sein Geist gewährt Euch die unerschütterliche Stärke des Berges und die ruhige Geduld der Ebenen."}},faq={{q="Was ist eine Earth Sapta?",a="Eine Earth Sapta ist ein zeremonieller Trank, den schamanische Älteste brauen. Ihre Magie öffnet Eure Wahrnehmung, sodass Ihr elementare Erdgeister sehen und mit ihnen sprechen könnt.",al={"was ist sapta","earth sapta bedeutung","was bewirkt der trank"}},{q="Wo liegt der Kodofels?",a="Der Kodofels ist ein natürlicher Steinmonolith östlich von Camp Narache, jenseits der Hochwolkenebene.",al={"kodofels finden","kodofels standort","wo ist der schrein"}},{q="Wer hat die Earth Sapta für diesen Ritus hergestellt?",a="Seherin Rabenfeder, eine Schamanenälteste in Camp Narache, hat den Trank zubereitet und überreicht. Seherin Rabenfeder beaufsichtigt die Ausbildung junger spiritueller Führer.",al={"wer gibt die sapta","seherin rabenfeder sapta"}},{q="Warum muss die Sapta an einer heiligen Stätte getrunken werden?",a="Die Tradition der Tauren verlangt, eine Sapta nur in einem geweihten Schrein zu trinken, wo Elementargeister wohnen und den Bittsteller gefahrlos empfangen können. Der Trank ist heilig und bei Missbrauch gefährlich.",al={"warum am kodofels trinken","sapta überall trinken"}},{q="Was geschieht, nachdem der Trank am Kodofels getrunken wurde?",a="Den Trank am Kodofels zu trinken, lüftet den Schleier der alltäglichen Welt und offenbart eine Schwache Erdmanifestation. Das Gespräch mit dem Geist vollendet die Bindung des Schamanen an die Erde.",al={"was erscheint","schwache erdmanifestation erscheinen"}},{q="Welche Lehre vermittelt der Erdgeist den Initianden?",a="Der Erdgeist lehrt demütige Geduld, keinen Kampf. Feuer und Luft können chaotisch und gewaltsam sein, während die Erde Stärke, Ausdauer und ein ruhiges Fundament für die Seele des Schamanen bietet.",al={"lehre des erdgeistes","bedeutung des erdritus"}}},fx={["52e0a178"]={q="Warum schickt Seherin Rabenfeder Euch zum Kodofels?",a="Seherin Rabenfeder leitet Euren Weg als Schamanenschüler. Die Earth Sapta, die sie vorbereitet hat, ist mit Magie durchtränkt, die dazu dient, Eure Wahrnehmung für die Geister der Welt zu öffnen. Indem sie Euch anweist, das Gebräu am heiligen Schrein vom Kodofels zu trinken, zielt sie darauf ab, Euren Geist dauerhaft an das Element der Erde zu binden, damit Ihr direkt mit seinen Manifestationen kommunizieren und seine grundlegende Weisheit erlernen könnt.",al={"seherin rabenfeder motiv","warum earth sapta trinken","warum rabenfeder call of earth"}}},fp="13,133,24.291.0,22.376.0,23.152.0,27.86.0,42.151.0,46.193.0,52.166.0,54.182.0"}
P.entries["quest:1521"] = {n="Ruf der Erde",s="In Mulgore kehrt ein junger Taurenschamane mit einem Geschenk der Erde nach Camp Narache zurück. Die Earth Sapta lässt den Initianden mit einem Geist sprechen und rohen Stein empfangen, womit der Weg durch die vier Elemente beginnt.",h="In Mulgore kehrt ein junger Taurenschamane mit einem Geschenk der Erde nach Camp Narache zurück.",kw={"ruf der erde","camp narache","erdtotem","schwache erdmanifestation","mulgore","die hochwolkenebene","rohquarz","seherin rabenfeder","taurenschamane"},ang={["class:Shaman"]="Als Schamane erhaltet Ihr durch diesen Ritus Euer erstes Totem. Es bei Euch zu tragen verankert Eure spirituelle Identität und lässt Euch grundlegende Schutzbanne der Erde wirken.",["faction:Horde"]="Als Schamane der Horde dient Ihr als spiritueller Anker und Ratgeber und verbindet die sterblichen Völker mit Kalimdors unberechenbaren Elementarkräften.",["race:Tauren"]="Die Kultur der Tauren verehrt die Earth Mother zutiefst. Diese Prüfung bindet einen Initianden an den lebendigen Fels und Boden seiner angestammten Heimat."},sec={{t="Ein Geschenk des Berges",b="Nachdem Ihr die Earth Sapta getrunken habt, begegnet Ihr der Schwachen Erdmanifestation auf den Felsen nahe der Hochwolkenebene. Der Geist gibt Euch Rohquarz, einen schlichten Stein, der Euren Pakt mit dem Element und dessen Beständigkeit verkörpert. Geduld und Stärke sind die Tugenden, die die Erde verlangt. Durch gegenseitigen Respekt verspricht der Geist Einklang mit dem Land."},{t="Das erste Totem",b="In Camp Narache formt Seherin Rabenfeder aus dem geschenkten Quarz Euer erstes Erdtotem. Es ist mehr als ein Zeichen des Ranges und dient als dauerhafter Anker für Körper und Geist. Durch diesen geschnitzten Fokus kanalisiert Ihr die erdende und schützende Magie der Erde. Es ist Euer erster wahrer Schritt auf dem vierfachen Elementarpfad."}},faq={{q="Welchem Zweck dient der Rohquarz?",a="Der Rohquarz ist ein Zeichen, das Euch die Schwache Erdmanifestation als Beweis Eurer Zwiesprache gibt. Seherin Rabenfeder macht ihn zum spirituellen Herzen Eures neuen Erdtotems.",al={"wozu wird rohquarz benötigt","wofür ist der quarz","rohquarz verwendung"}},{q="Warum ist ein Erdtotem für einen Schamanen so wichtig?",a="Totems lassen einen Schamanen elementare Macht kanalisieren. Ohne ein Erdtotem als Fokus kann ein Schamane die Geister des Landes nicht für Zauber und schützende Banne anrufen.",al={"wozu wird ein erdtotem benötigt","was bewirkt ein erdtotem","erdtotem hintergrund"}},{q="Wer ist Seherin Rabenfeder?",a="Seherin Rabenfeder ist die spirituelle Führerin und Schamanenlehrerin in Camp Narache auf der Hochwolkenebene. Sie beaufsichtigt die Elementarprüfungen junger Tauren, führt sie durch ihre ersten Visionen und fertigt ihre heiligen Werkzeuge.",al={"wer ist rabenfeder","seherin rabenfeder hintergrund","camp narache seherin"}},{q="Was sind die vier Pfade, die Seherin Rabenfeder erwähnt?",a="Seherin Rabenfeder meint die vier Urelemente, die ein Schamane meistern muss: Erde, Feuer, Wasser und Luft. Die Erde bildet das Fundament, und ihre Beständigkeit und Standhaftigkeit machen sie zur ersten Prüfung des Initianden.",al={"vier pfade","vier elemente schamane","was sind die pfade"}},{q="Wo findet diese Zwiesprache statt?",a="Die Zwiesprache findet zwischen den schroffen Klippen statt, die die Hochwolkenebene in Mulgore säumen. Ihr könnt die Schwache Erdmanifestation erst erreichen, nachdem Ihr die Earth Sapta getrunken habt.",al={"wo ist der erdgeist zu finden","manifestation fundort","wo ist der geist"}},{q="Durchlaufen andere Schamanen der Horde einen ähnlichen Ritus?",a="Ja. Orcs und Dunkelspeertrolle in Durotar folgen ihrem eigenen Ruf der Erde im Tal der Prüfungen. Sie suchen Zwiesprache mit örtlichen Elementarmanifestationen und schnitzen ihre ersten Totems.",al={"folgen orcs dem ruf der erde","troll ruf der erde","erhalten alle schamanen ein erdtotem"}}},fx={["43ccddec"]={q="Warum schickt die Schwache Erdmanifestation Euch zurück zu Seherin Rabenfeder?",a="Der Elementargeist hat Eure Entschlossenheit geprüft und Euch für würdig befunden, den Pfad der Erde zu beschreiten. Indem er Euch ein Stück von sich selbst verleiht – den Rohquarz – liefert er den greifbaren Beweis Eurer Verbindung und gegenseitigen Achtung. Er fordert Euch auf, zu Seherin Rabenfeder zurückzukehren, damit der Stein das Herz Eures ersten Totems bilden kann, das die Geister der Erde in Euren Dienst stellt, während Ihr Geduld, Stärke und Weisheit bewahrt.",al={"schwache erdmanifestation motiv","warum rohquarz schicken","zweck der erdmanifestation"}}},fp="13,211,24.333.0,15.307.0,40.165.0,47.153.0,25.219.0,51.198.0,37.170.0,48.186.0"}
P.entries["quest:1522"] = {n="Ruf des Feuers",s="Ein Schamane erkennt Eure Stärke in der Erde und schickt Euch nach Norden zu Kranal Fiss. Dort könnt Ihr die Wege des Feuers erlernen.",h="Ein Schamane erkennt Eure Stärke in der Erde und schickt Euch nach Norden zu Kranal Fiss.",kw={"brachland","call of fire","das wegekreuz","erde","feuer","kranal fiss","schamane"},ang={["class:Shaman"]="Als Schamane werdet Ihr zu Kranal Fiss geschickt, um die Wege des Feuers zu erlernen, nachdem Ihr Stärke in der Erde bewiesen habt."},sec={{t="Kranal Fiss",b="Kranal Fiss lebt nördlich vom Wegekreuz. Der Schamane sagt, er sei leicht zu finden, warnt Euch aber davor, zu weit zu gehen, sonst erreicht Ihr die Lande der Elfen."}},faq={{q="Wer ist Kranal Fiss?",a="Kranal Fiss ist ein Schamane im Brachland, der Euch die Wege des Feuers lehren kann.",al={"wer ist kranal","kranal"}},{q="Wo kann ich Kranal finden?",a="Kranal lebt nördlich vom Wegekreuz im Brachland.",al={"kranals standort","wo ist kranal"}},{q="Warum werde ich zu Kranal geschickt?",a="Der Schamane erkennt Eure Stärke in der Erde und glaubt, dass Ihr bereit seid, mit Kranal zu sprechen, der Euch die Wege des Feuers lehren kann.",al={"warum kranal","feuerausbildung"}}},fp="12,111,11.144.0,19.74.0,24.52.0,30.123.0"}
P.entries["quest:1524"] = {n="Ruf des Feuers",s="Im Brachland schickt Kranal Fiss einen angehenden Schamanen zur nächsten Prüfung, um mit dem Feuer in Einklang zu treten. Der Initiant überquert den Südstrom zu einem abgelegenen Bergschrein in Durotar und trägt dabei eine unangezündete Fackel der schlafenden Flamme.",h="Im Brachland schickt Kranal Fiss einen angehenden Schamanen zur nächsten Prüfung, um mit dem Feuer in...",kw={"brachland","ruf des feuers","durotar","feuertotem","kranal fiss","schrein der schlafenden flamme","der südstrom","telf joolam"},ang={["class:Shaman"]="Als Schamane sucht Ihr das Feuertotem, indem Ihr mit Kalimdors elementaren Kräften in Einklang tretet. Dieser Weg führt Euch zu abgelegenen Schreinen, über bloße Unterweisung hinaus.",["faction:Horde"]="Als Mitglied der Horde teilt Ihr schamanische Lehren mit Orcs, Tauren und Trollen. Diese Traditionen führen Schüler von den Ebenen des Brachlands zu Durotars heiligen Klippen."},sec={{t="Eine Prüfung der Bereitschaft",b="Kranal Fiss vertraut Euch die Fackel der schlafenden Flamme an. Rohe mystische Stärke genügt den Ansprüchen des Feuers nicht; die Prüfung verlangt Mäßigung, Konzentration und Respekt. Die Fackel ist zugleich ein rituelles Instrument und ein Beweis für den Hüter des Schreins, dass Ihr für die Prüfung als bereit erachtet werdet."},{t="Der verborgene Gipfel",b="Der Schrein liegt jenseits des Südstroms, zwischen Durotars südlichen Felsen. Ein verwitterter Stein mit einer eingemeißelten Feuerrune markiert einen unscheinbaren Pfad, der zu einem der höchsten Gipfel der Region hinaufführt. Auf dem Gipfel wacht Telf Joolam, ein Troll-Eremit, über den Schrein der schlafenden Flamme. Er weist neugierige Reisende und Schatzsucher ab und schützt die heilige Kohlenpfanne vor gewöhnlichen Blicken, bis ein Bittsteller mit der unangezündeten Fackel eintrifft."}},faq={{q="Welchem Zweck dient die Fackel der schlafenden Flamme?",a="Kranal Fiss gibt Euch die unangezündete Fackel als Zeichen Eurer Absicht. Sie weist Euch gegenüber Telf Joolam, dem Hüter des Schreins, als angehenden Schamanen aus, der für die Prüfung als bereit erachtet wird.",al={"warum fackel tragen","fackel der schlafenden flamme","bedeutung der fackel"}},{q="Wer ist Telf Joolam?",a="Telf Joolam ist ein schamanischer Eremit der Horde, der auf den Gipfeln im Süden Durotars über den Schrein der schlafenden Flamme wacht. Er schützt die Kohlenpfanne vor jenen, die die Geister weder verstehen noch achten.",al={"telf joolam","hüter des schreins","wer ist der troll am schrein"}},{q="Wo liegt der Verborgene Pfad?",a="Der verborgene Pfad beginnt in Durotar, südlich der Brücke über den Südstrom. Nahe dem Flussufer, wo die Berge auf die Küste treffen, kennzeichnet ein aufrecht stehender Stein mit einer Flammenrune den schmalen Aufstieg zum hohen Bergrücken.",al={"lage des verborgenen pfades","schrein der schlafenden flamme finden","pfad auf den berg"}},{q="Warum muss die Fackel unangezündet gebracht werden?",a="Ihr bringt die Fackel unangezündet, weil das Feuer durch ein Ritual erweckt und gemeistert werden muss und nicht einfach beansprucht werden kann. Ihre schlafende Flamme steht für den Zustand, den Ihr durch Einklang mit dem Feuer zum Leben erwecken müsst.",al={"warum ist die fackel unangezündet","ritual der schlafenden fackel","warum schlafende flamme"}},{q="Was geschieht, nachdem Ihr Telf Joolam erreicht habt?",a="Nachdem Telf Joolam die Fackel geprüft hat, schickt er Euch zu härteren, gefährlicheren Riten. Dort entfacht Ihr ihre schlafende Flamme und beweist Eure Beherrschung des elementaren Feuers.",al={"nächster schritt ruf des feuers","was kommt nach telf joolam"}},{q="Warum wird dieser Schrein vor dem Rest der Horde geheim gehalten?",a="Der Schrein liegt abseits, weil elementare Kräfte unberechenbar und in ungeübten Händen gefährlich sind. Schamanische Traditionen legen heilige Stätten fernab gewöhnlicher Siedlungen an, damit neugierige Reisende und Schatzsucher keine ruhenden Geister stören oder Unheil heraufbeschwören.",al={"warum geheimer schrein","ist der schrein verborgen"}}},fx={["10005cfa"]={q="Warum schickt Kranal Fiss Euch zum Schrein der schlafenden Flamme?",a="Kranal Fiss erkennt, dass Euer Geist zwar die rohe Stärke besitzt, um Feuer zu führen, rohe Macht allein jedoch nicht ausreicht. Feuer ist gefährlich, zerstörerisch und ungezähmt; Euch dessen Totem vorzeitig zu gewähren, würde eine Katastrophe riskieren. Als Mentor ist es seine Pflicht, sicherzustellen, dass Ihr die heiligen Prüfungen der Vorbereitung und des Respekts durchlauft. Er schickt Euch zu Telf Joolam, damit Ihr Eure Disziplin beweisen und das Recht verdienen könnt, die Flamme vor den Elementen selbst zu tragen.",al={"warum will kranal fiss das erledigt haben","kranal fiss motiv","warum schickt kranal einen"}},b8cc7d40={q="Warum müsst Ihr diese Reise antreten und nicht jemand anderes?",a="Diese Pilgerreise ist keine einfache Besorgung oder eine Angelegenheit der militärischen Verteidigung – es ist ein zutiefst persönlicher spiritueller Ritus des Übergangs. Der Schrein der schlafenden Flamme wird streng vor den profanen Mitgliedern der Horde und gewöhnlichen Wachen verborgen gehalten. Nur ein Schüler, der die Verbindung mit den Feuerelementen anstrebt, kann die schlafende Fackel tragen, Telf Joolams Führung suchen und seine Würdigkeit beweisen, die Macht des Elements zu führen.",al={"warum ich call of fire","warum schickt man mich zum schrein der schlafenden flamme","warum können wachen nicht gehen"}}},fp="12,231,19.286.0,15.433.0,54.165.0,19.206.0,33.228.0,36.173.0,40.159.0,58.260.0"}
P.entries["quest:1525"] = {n="Ruf des Feuers",s="Telf Joolam schickt Euch durch Durotar und das östliche Brachland, um Zutaten für eine Feuersapta zu sammeln. Der Trank bereitet einen Initianden darauf vor, Feuergeister zu sehen und mit ihnen zu sprechen.",h="Telf Joolam schickt Euch durch Durotar und das östliche Brachland, um Zutaten für eine Feuersapta zu sammeln.",kw={"burning blade","ruf des feuers","staubwindhöhle","feuersapta","feuerteer","razormane","reagent pouch","telf joolam"},ang={["class:Shaman"]="Als Schamane stellt Ihr Euch einer Prüfung, bei der Ihr gegensätzliche Kräfte ins Gleichgewicht bringen müsst. Flammen können Lebenskraft und Licht ebenso wie Zorn bringen, wenn Weisheit sie lenkt.",["faction:Horde"]="Als Verteidiger der Horde begegnet Ihr Bedrohungen an den Grenzen: Razormane-Stachelebern, die im Brachland vordringen, und Kultisten der Burning Blade, die sich in Durotar verbergen.",["race:Orc"]="Als Orc stellt Ihr Euch der Burning Blade und der Hexenmeistermagie, die einst Euer Volk verdarb. Das Feuer als natürliches Element zurückzugewinnen, ist ein Akt kultureller Wiederherstellung."},sec={{t="Die Feuersapta brauen",b="Eine Feuersapta öffnet die Sinne eines Schamanen für die Ewige Flamme. Wie der Trank für die Erde lässt sie Euch Geister sehen, die sterblichen Augen verborgen bleiben, und mit ihnen sprechen. Telf Joolam schickt Euch durch Durotar und ins östliche Brachland, um Zutaten zu beschaffen, die an Hitze und Flamme gebunden sind."},{t="Feinde und Elemente",b="Die Zauberwirker der Razormane-Stacheleber im östlichen Brachland tragen Feuerteer bei sich, der bei ihren erdverbundenen Ritualen entsteht. Kultisten der Burning Blade tragen die andere Zutat in der Staubwindhöhle bei sich, in den Schluchten nordöstlich von Klingenhügel. Sie nutzen Feuer für Zerstörung und dämonisches Chaos, doch die Reagenzien in ihren Beuteln sind von Natur aus mit dem Element verbunden."},{t="Das Wesen der Flamme",b="Telf Joolam lehrt, dass Feuer mehr als Zerstörung und Verderben bringt. Es spendet Wärme und Licht und ermöglicht Schöpfung. Ein weiser Schamane erkennt, wie gegensätzliche Kräfte einander Bedeutung verleihen, und setzt gegensätzliche Elemente gemeinsam ein, statt Feuer nur als Waffe zu führen."}},faq={{q="Was ist eine Feuersapta?",a="Eine Feuersapta ist ein ritueller Trank aus Zutaten, die mit Feuer verbunden sind. Wenn Ihr sie trinkt, stimmen sich Euer Geist und Eure Sicht kurzzeitig auf die Ebene des Feuers ein, sodass Ihr ihre Geister sehen und mit ihnen sprechen könnt.",al={"was ist feuersapta","feuersapta bedeutung","warum sapta trinken"}},{q="Wo finde ich den Feuerteer?",a="Die Zauberwirker der Razormane-Stacheleber tragen Feuerteer im östlichen Brachland bei sich, von Durotar aus jenseits des Südstroms. Geomanten, Seers, Mystics und Thornweavers tragen oft Töpfe mit der dickflüssigen, brennbaren Mischung für Stammesriten bei sich.",al={"feuerteer fundort","wer lässt feuerteer fallen","feuerteer stacheleber"}},{q="Wo ist der Reagent Pouch zu finden?",a="Kultisten der Burning Blade tragen den Reagent Pouch in der Staubwindhöhle bei sich, oberhalb der Schluchten nordöstlich von Klingenhügel in Durotar. Die Höhle ist nicht die Knochenhöhle, die weiter nördlich nahe der Küste liegt.",al={"reagent pouch fundort","welche höhle enthält reagent pouch","burning blade beutel"}},{q="Warum verwendet ein Schamane Gegenstände von Hexenmeistern?",a="Telf Joolam braucht für die Sapta Zutaten, die von Feuer durchdrungen sind. Kultisten der Burning Blade beschwören zerstörerische dämonische Flammen, und ihre Zauberbeutel enthalten mächtige Reagenzien, die mit Feuer verbunden sind.",al={"warum reagenzien der burning blade verwenden","hexenmeistergegenstände für schamanen","hexenmeisterfeuer"}},{q="Wer ist Telf Joolam?",a="Telf Joolam ist ein einsiedlerischer Trollschamane, dessen Lager auf Durotars Felsen südlich von Klingenhügel liegt. Er wacht über die Feuerprüfungen der Initianden der Horde und lehrt sie, Zerstörung und Schöpfung ins Gleichgewicht zu bringen.",al={"telf joolam hintergrundgeschichte","wer ist telf joolam"}},{q="Was geschieht nach dieser Quest?",a="Nachdem Telf Joolam die Feuersapta aus den gesammelten Zutaten hergestellt hat, schickt er Euch zu den feurigen Höhen des nahen ruhenden Vulkans. Dort trinkt Ihr sie, stellt Euch dem Elementargeist und verdient Euch Euer Feuertotem.",al={"nächste quest ruf des feuers","nach dem sammeln der reagenzien","was mit feuersapta tun"}}},fx={["8d79977d"]={q="Warum schickt Telf Joolam Euch auf diese Quest?",a="Telf Joolam leitet Eure Einweihung in die tieferen Künste der Elemente. Um die Macht des Feuers zu führen und Euer Feuertotem zu verdienen, müsst Ihr einen speziellen Trank namens Feuersapta trinken, der vorübergehend Eure spirituellen Sinne auf das Reich des Feuers ausrichtet. Telf kann diesen Trank nicht aus dem Nichts brauen; er benötigt Euch, um Reagenzien zu beschaffen, die tief mit der Flamme in Einklang stehen, damit er die Mischung vorbereiten und Euch auf den Pfad der Ewigen Flamme bringen kann.",al={"warum will telf joolam das","zweck von telf joolam","warum telf joolam helfen"}},["08a6380d"]={q="Wofür ist der Feuerteer?",a="Feuerteer ist einer von zwei lebenswichtigen Katalysatoren, die Telf Joolam benötigt, um eine Feuersapta zu brauen. Der Teer wird von den zauberwirkenden Stachelebern des Stammes der Razormane im östlichen Brachland getragen und besitzt von Natur aus flüchtige Eigenschaften, die auf Feuermagie abgestimmt sind, was dem Trank die nötige Kraft verleiht, um Eure Sinne auf die Elementargeister einzustimmen.",al={"warum brauche ich feuerteer","zweck von feuerteer","verwendung von feuerteer"}},["52c07fd8"]={q="Wofür ist der Reagent Pouch?",a="Der Reagent Pouch liefert die flüchtigen Komponenten, die benötigt werden, um die Feuersapta zu vervollständigen. Telf Joolam lässt Euch diesen von den Kultisten der Burning Blade beschaffen, die nordöstlich von Klingenhügel lauern, da diese Hexenmeister regelmäßig Materialien sammeln, die für ihre eigene dunkle Zauberei untrennbar mit dem Feuer verbunden sind. Anstatt das Land nach seltenen, verstreuten Katalysatoren abzusuchen, enthalten die persönlichen Vorräte der Kultisten genau die Reagenzien, die benötigt werden, um Euren Geist mit der Flamme zu verbinden.",al={"warum reagent pouch nötig","zweck von reagent pouch","schamanenverwendung reagent pouch"}},["65d894ad"]={q="Wer sind die Kultisten der Burning Blade in Durotar?",a="Die Kultisten sind sterbliche Agenten der Burning Blade, einem schattenhaften Überbleibsel der alten dämonischen Kulte, die einst dem Schattenrat dienten. Diese Hexenmeister lauern in versteckten Höhlen über den Schluchten nordöstlich von Klingenhügel und praktizieren verbotene Teufelsmagie direkt unter der Nase der Horde, wobei sie auf chaotische Feuerkräfte zurückgreifen, die ihre Reagenzienbeutel zu erstklassigen Quellen für die elementare Braukunst machen.",al={"burning blade ziel","wer sind die kultisten","burning blade durotar"}},f71fa686={q="Warum müsst Ihr die Reagenzien selbst sammeln und nicht Telf Joolam?",a="Die Reise selbst ist Teil Eurer spirituellen Prüfung. Ein Schamane muss beweisen, dass er in der Lage ist, sich Gefahren zu stellen, verdorbener Magie entgegenzutreten und Entschlossenheit zu zeigen, bevor er die Verbindung mit dem Feuer beansprucht. Telf Joolam dient als Mentor und Führer auf diesem abgelegenen Gipfel, aber die Verbindung mit dem Element kann Euch nicht einfach so übergeben werden – Ihr müsst persönlich die Komponenten ergreifen, die Euch an die Flamme binden.",al={"warum kann telf sie nicht holen","warum ich feuerquest","warum sammelt schamane reagenzien"}}},fp="12,172,22.260.0,20.326.0,19.274.1,21.192.0,29.223.0,33.186.0,42.181.0,19.206.0,30.204.1"}
P.entries["quest:1526"] = {n="Ruf des Feuers",s="Auf Durotars Gipfeln stellt Ruf des Feuers einen Schamanen vor eine Feuerprüfung. Telf Joolam schickt den Initianden aus, Feuersapta zu trinken, sich einer Minor Manifestation of Fire zu stellen und ihre Glut an sich zu nehmen.",h="Auf Durotars Gipfeln stellt Ruf des Feuers einen Schamanen vor eine Feuerprüfung.",kw={"brazier of the dormant flame","ruf des feuers","durotar","feuersapta","feuertotem","minor manifestation of fire","schamanenprüfung","shrine of eternal flame","telf joolam"},ang={["class:Shaman"]="Als Schamane lernt Ihr, dass Feuer unbeständig und zerstörerisch ist, anders als die feste, unnachgiebige Erde. Es verzehrt einen unentschlossenen Rufer, daher sind Konzentration und Autorität nötig, um es zu beherrschen.",["faction:Horde"]="Als Schamane der Horde schließt Ihr Euch Ork- und Trollschamanen an, die Durotars rote Felsen erklimmen, um ihre Verbundenheit mit den feurigen Geistern des Landes zu beweisen."},sec={{t="Augen der Flamme",b="Auf Durotars Gipfel bleiben Feuergeister ungeübten Augen verborgen. Trinkt Feuersapta, einen Trank aus Reagenzien, die im Brachland und an der Küste gesammelt wurden, und Eure Sinne schärfen sich für das Unsichtbare. Niedere Geister und Manifestationen erscheinen zwischen den Gipfelfelsen."},{t="Der Manifestation entgegentreten",b="Eine Minor Manifestation of Fire wartet auf dem Berggipfel. Sobald die Sapta wirkt, weiß sie, dass Ihr sie sehen könnt, und erwartet Eure Herausforderung. Feuer antwortet auf Stärke und entschlossenes Handeln, also schlagt ohne Zögern zu. Je länger der Kampf dauert, desto heftiger brennt das elementare Feuer."},{t="Das Brazier of the Dormant Flame",b="Nachdem die Manifestation gefallen ist, nehmt Ihr ihre verbliebene Hitze als Glut an Euch. Legt sie am Gipfelschrein in das Brazier of the Dormant Flame. Das beschriftete Metall bleibt unter Durotars Sonne und Winden kühl, bis die Glut die Schale berührt. Dann entzündet eine weißglühende Flamme die rituelle Fackel."}},faq={{q="Welchen Zweck hat diese Prüfung?",a="Ihr beweist Eure Stärke, indem Ihr Euch einer Manifestation des Feuers stellt und ihre Hitze in einer rituellen Fackel einfangt. Die Prüfung verleiht Euch das Recht, ein Feuertotem herzustellen.",al={"warum ruf des feuers","bedeutung der feuertotemquest","ruf des feuers prüfung"}},{q="Warum muss ich die Feuersapta trinken?",a="Ihr trinkt Feuersapta, um die Feuerelementare auf dem Berggipfel zu sehen und zu berühren, die dem Blick der Sterblichen gewöhnlich verborgen bleiben.",al={"was bewirkt feuersapta","warum sapta","feuerelementar nicht sichtbar"}},{q="Wo ist die Minor Manifestation of Fire zu finden?",a="Die Minor Manifestation of Fire wartet auf dem höchsten Gipfel des Bergkamms über Telf Joolams Hochsitz in Durotar, nahe dem Shrine of Eternal Flame.",al={"fundort der manifestation","wo ist der feuerelementar","wohin gehen"}},{q="Wer ist Telf Joolam?",a="Telf Joolam ist ein exzentrischer Schamane und Einsiedler, der hoch oben auf einem felsigen Bergkamm in Durotar lebt. Er führt junge Initianden der Horde durch gefährliche, unberechenbare Riten, damit sie das Feuer verstehen.",al={"telf joolams rolle","telf joolams geschichte","wer ist der hermit"}},{q="Warum wird die Manifestation während des Kampfes stärker?",a="Feuer sammelt Kraft und brennt mit der Zeit heißer. Schlagt entschlossen zu, denn Zögern lässt den Geist stärker werden.",al={"warum ist der feuerelementar so stark","stärkezuwachs der manifestation","schneller schlag feuer"}},{q="Was geschieht, nachdem das Kohlenbecken entzündet wurde?",a="Das Entzünden des Kohlenbeckens entfacht die zeremonielle Fackel. Tragt ihre heilige Flamme den Berg hinab, um Euer Feuertotem zu vollenden.",al={"was nach der ruhenden flamme","nächste quest ruf des feuers","wohin mit der entzündeten fackel"}}},fx={e554f055={q="Warum schickt Telf Joolam Euch auf diese Prüfung?",a="Telf Joolam ist Euer Mentor in den Wegen der Elemente, beauftragt damit, junge Schamanen durch ihre Verbindung mit dem Feuer zu führen. Feuer ist stürmisch, zerstörerisch und unberechenbar; die Geister werden Euch ihre Macht oder ihren Respekt nicht gewähren, wenn Ihr nicht beweist, dass Ihr fähig seid, ihrer Essenz direkt entgegenzutreten und sie zu befehligen. Telf schickt Euch auf den Gipfel, nicht um den Berg von einer Bedrohung zu befreien, sondern um Euren Geist im Kampf zu stählen und das Recht zu verdienen, die Flamme zu tragen.",al={"telf joolam motiv","warum will telf joolam das","warum diese prüfung machen"}},e534729d={q="Wofür ist die Glut?",a="Die Glut ist der reine elementare Überrest, der von der getöteten Schwachen Feuermanifestation geerntet wurde. Um Euren Ritus abzuschließen, müsst Ihr diesen feurigen Kern zum Schrein der ewigen Flamme tragen und ihn in das schlafende Kohlenbecken legen. Das Wiederentfachen des kalten Beckens mit der lebendigen Essenz des Elementars entzündet eine heilige, weißglühende Flamme, die wiederum Eure Schlafende Fackel entzündet und Eure Verbindung zum Element des Feuers besiegelt.",al={"verwendung der glut","warum brauche ich glut","zweck der glut"}},["8a082e57"]={q="Was ist die Schwache Feuermanifestation und warum ist sie hier?",a="Die Schwache Feuermanifestation ist ein Elementargeist, der auf dem Berggipfel in der Nähe vom Schrein der schlafenden Flamme verweilt. Nur für diejenigen sichtbar, deren Sinne durch die heilige Feuersapta geöffnet wurden, verkörpert sie die rohe, aggressive Natur der Flamme. Sie verharrt als ewiger Wächter und Prüfung für aufstrebende Schamanen auf dem Felsvorsprung und fordert jeden heraus, der das Feuer meistern will, um ihren brennenden Zorn zu bezwingen.",al={"lore schwache feuermanifestation","wer ist die manifestation","warum ist das feuerelementar hier"}}},fp="12,176,17.257.0,29.272.0,32.289.1,34.154.0,38.106.0,47.146.0,19.176.0,58.121.0,38.120.0"}
P.entries["quest:1528"] = {n="Call of Water",s="Ein Schamane schickt Euch zu Islen Wasserdeuter jenseits von Ratschet, wo sie Euch die Wege des Wassers lehren kann. Eure Stärke im Feuer hat Euch darauf vorbereitet, ihren Rat zu suchen.",h="Ein Schamane schickt Euch zu Islen Wasserdeuter jenseits von Ratschet, wo sie Euch die Wege des Wassers...",kw={"brachland","großer hai","call of water","feuer","islen wasserdeuter","ratschet","schamane","der südstrom","wasser"},sec={{t="Zur Küste",b="Das Brachland birgt den nächsten Schritt in Eurer elementaren Ausbildung. Ihr habt Stärke im Feuer bewiesen, und nun werdet Ihr zu Islen Wasserdeuter geschickt, die an der Küste lebt. Folgt dem Südstrom nach Süden, an Ratschet vorbei, und haltet nahe ihrem Zuhause nach einem großen Hai Ausschau."}},faq={{q="Wer ist Islen Wasserdeuter?",a="Islen Wasserdeuter lebt an der Küste des Brachlands und kann Euch die Wege des Wassers lehren.",al={"islen","fundort von islen wasserdeuter","wer lehrt wasser"}},{q="Wo kann ich Islen finden?",a="Islen lebt jenseits von Ratschet an der Küste des Brachlands. Geht nach Süden am Südstrom entlang und haltet nach einem großen Hai Ausschau.",al={"wo ist islen","fundort von islen","islen finden"}},{q="Warum suche ich Islen?",a="Ihr habt Stärke im Feuer bewiesen, und Islen kann Euch die Wege des Wassers lehren.",al={"warum call of water","wasserausbildung","warum islen suchen"}},{q="Wonach soll ich in der Nähe von Islen Ausschau halten?",a="Haltet in der Nähe von Islen nach einem großen Hai Ausschau.",al={"großer hai","hai islen","orientierungspunkt bei islen"}}},fp="13,157,16.247.0,23.89.0,23.114.0,27.75.0,34.32.0"}
P.entries["quest:1529"] = {n="Ruf des Wassers",s="In Donnerfels wendet sich Eure Ausbildung dem Wasser und einer Reise zur Küste des Brachlands zu. Ihr reist nach Osten, um Islen Wasserdeuter zu treffen und den Weg zum Wassertotem zu beginnen.",h="In Donnerfels wendet sich Eure Ausbildung dem Wasser und einer Reise zur Küste des Brachlands zu.",kw={"brachland","ruf des wassers","islen wasserdeuter","ratschet","schamane","der südstrom","donnerfels","wassertotem","xanis flameweaver"},ang={["class:Shaman"]="Als Schamane führt Euer Weg von den ersten Elementarprüfungen zu den reinigenden, heilenden Kräften von Wasser und Gezeiten.",["faction:Horde"]="Als Mitglied der Horde teilt Ihr schamanische Traditionen, die die Geisterkundigen der Orcs, Trolle und Tauren verbinden.",["race:Tauren"]="Als Tauren verlasst Ihr von Donnerfels aus die geschützten Ebenen von Mulgore und reist in die Weiten Kalimdors."},sec={{t="Ein Ruf aus Donnerfels",b="Ihr habt Erde und Feuer gemeistert, und Eure Lehrer halten Euch nun für bereit, das Wasser zu ergründen. In Donnerfels erkennt Xanis Flameweaver, dass Ihr die nötige Disziplin besitzt, um Euch diesem reinigenden Element zu nähern. So verlasst Ihr die Tafelberge von Mulgore und durchquert die trockenen Ebenen des Brachlands nach Osten."},{t="The Hermit an der Küste",b="Islen Wasserdeuter lebt in einer Fischerhütte an der Ostküste des Brachlands, südlich von Ratschet und der Mündung des Südstroms. Sie hält sich fern von den Siedlungen am offenen Meer. Islen erkennt Eure Bereitschaft an den Elementen um Euch herum. Erde, Wind und Feuer berühren bereits Euren Geist, und sie bereitet Prüfungen vor, die Euch die Reinheit des Wassers lehren sollen."}},faq={{q="Wer schickt mich auf diese Reise?",a="Ein Schamanenlehrer in Donnerfels, etwa Xanis Flameweaver, schickt Euch, sobald Eure Ausbildung Euch zu den Riten des Wassers führt.",al={"questgeber","wer beginnt ruf des wassers","wo ruf des wassers in donnerfels annehmen"}},{q="Wo befindet sich Islen Wasserdeuter?",a="Islen Wasserdeuter lebt in einer Fischerhütte an der Ostküste des Brachlands, südlich von Ratschet und der Mündung des Südstroms.",al={"wo ist islen wasserdeuter","islens standort","islen finden"}},{q="Welchen Zweck hat die Prüfung Ruf des Wassers?",a="Mit der Prüfung beginnt Eure Zwiesprache mit dem Wasser. Sie prüft Euer Verständnis seiner Reinheit und führt Euch zum Wassertotem.",al={"warum ruf des wassers machen","ruf des wassers zweck","schamanenquest wassertotem"}},{q="Erhalten andere Völker der Horde dieselbe Unterweisung?",a="Taurenschamanen erhalten den Ruf in Donnerfels. Orc- und Trollschamanen in Orgrimmar und Durotar erhalten ähnliche Rufe, Islen Wasserdeuter an der Küste des Brachlands aufzusuchen.",al={"nur für tauren","orc ruf des wassers","troll ruf des wassers"}},{q="Welche Elemente muss ein Schamane vor dem Wasser meistern?",a="Bevor Ihr das Wasser sucht, tretet Ihr mit Erde und Feuer in Zwiesprache. Auch Islen sieht, wie Erde, Wind und Feuer Euren Geist berühren, bevor das Wasser seine Reinheit offenbart.",al={"voraussetzungen","welche totems zuerst","reihenfolge der elemente"}},{q="Was geschieht, nachdem ich Islen Wasserdeuter gefunden habe?",a="Mit dem Auffinden von Islen endet Eure Reise von Donnerfels. Anschließend stellt sie Euch weitere Aufgaben in ganz Kalimdor, damit Ihr Wasser verstehen und reinigen lernt.",al={"was kommt als nächstes","nach dem finden von islen","ruf des wassers teil zwei"}}},fx={["6892158c"]={q="Warum schickt Xanis Flameweaver mich auf diese Quest?",a="Xanis Flameweaver dient als Führer auf Eurem Pfad als Schamane. Da er Eure Geduld und Eure Meisterschaft über die anfänglichen Elemente beobachtet hat, erkennt er, dass Euer Geist weit genug fortgeschritten ist, um sich den Prüfungen des Wassers zu stellen. Seine Rolle ist es nicht, Euch bei jedem Schritt des Weges zu führen, sondern Eure Bereitschaft zu erkennen und Euch an Islen Wasserdeuter zu verweisen, die über das tiefere Wissen verfügt, das notwendig ist, um Euer Verständnis für die Reinheit des Wassers zu prüfen.",al={"warum schickt mich xanis","xanis flameweaver motiv","warum islen wasserdeuter suchen"}},["22e527b8"]={q="Warum muss ich diese Reise selbst unternehmen?",a="Der Pfad eines Schamanen ist zutiefst persönlich. Die Verbindung mit den Elementen erfordert individuelle spirituelle Disziplin und den Beweis der Hingabe, was nicht an Wachen delegiert oder von Euren Mentoren in Eurem Namen unternommen werden kann. Wie Islen Wasserdeuter beobachtet, müsst Ihr jeden Schritt aus eigener Kraft tun, um den Geistern zu zeigen, dass Ihr über die innere Standhaftigkeit verfügt, um mit Wasser zu kommunizieren.",al={"warum muss ich selbst gehen","warum ich call of water","kann jemand anderes zu islen gehen"}}},fp="13,169,24.275.0,23.348.0,29.124.0,33.119.0,47.119.0,51.165.0,48.146.0,43.141.0"}
P.entries["quest:153"] = {n="Rote Lederkopftücher",s="Auf der Späherkuppe stehen Rote Lederkopftücher für den Kampf gegen die Defias. Späher Galiaan sucht die roten Masken der Gesetzlosen, während die Volksmiliz Mühe hat, ihre Spur durch Westfall zu verfolgen.",h="Auf der Späherkuppe stehen Rote Lederkopftücher für den Kampf gegen die Defias.",kw={"kopftücher","bruderschaft der defias","volksmiliz","rote lederkopftücher","späher galiaan","späherkuppe","westfall"},ang={["class:Rogue"]="Als Schurke seht Ihr, wie sich die Wegelagerer der Defias unter karmesinroten Masken vereint haben, um vor Sturmwinds Toren eine Armee zu bilden.",["faction:Alliance"]="Als Verbündeter der Volksmiliz helft Ihr, Westfall zu verteidigen, während Sturmwinds königliche Führung keine Hilfe schickt."},sec={{t="Ein Zeichen der Treue",b="In ganz Westfall kennzeichnet ein rotes Kopftuch die Bruderschaft der Defias. Beutelschneider, Plünderer und Verräter aus vielen Gesellschaftsschichten schließen sich der Bande an und versammeln sich dann unter demselben karmesinroten Zeichen. Auf der Späherkuppe sammeln Späher Galiaan und die Volksmiliz die Tücher als Beweis dafür, dass Banditen gefallen sind. Die Kopftücher helfen ihnen auch, den Defias zu folgen, während sich deren Fronten im Umland verschieben."},{t="Die Erkundungen der Miliz",b="Sturmwind hat Westfall angemessene militärische Unterstützung verwehrt, sodass die Volksmiliz mit erfahrenen Beobachtern wie Späher Galiaan die Aktivitäten der Defias erfassen muss. Von der Späherkuppe aus beobachtet Galiaan die Patrouillen der Gesetzlosen und verfolgt ihre Bewegungen. Durchreisende Abenteurer und Freiwillige der Miliz übernehmen die gefährliche Aufgabe, jene Wegelagerer zur Strecke zu bringen, die ehrliche Bauern von ihrem Land vertrieben haben."}},faq={{q="Warum tragen die Defias rote Lederkopftücher?",a="Das Rote Lederkopftuch zeigt die Treue zur Bruderschaft der Defias und verbirgt die Identität ehemaliger Arbeiter, Diebe und Gesetzloser. Es versetzt auch die verbliebenen Bauern Westfalls in Angst.",al={"bedeutung der roten defiasmasken","warum rote masken","geschichte der defiaskopftücher"}},{q="Wer ist Späher Galiaan?",a="Späher Galiaan dient in der Volksmiliz auf der Späherkuppe. Er verfolgt die Bewegungen und wechselnden Fronten der Bruderschaft der Defias in ganz Westfall und koordiniert Kopfgeldaufträge, um die Aktivitäten der Gesetzlosen einzudämmen.",al={"späher galiaan","wer vergibt rote lederkopftücher","späher auf der späherkuppe"}},{q="Warum braucht die Miliz Abenteurer, die diese Kopftücher sammeln?",a="Die Volksmiliz ist überlastet und erhält weder königliche Soldaten noch Geld aus Sturmwind. Kopfgeldaufträge liefern Spähern wie Galiaan Beweise für gefallene Banditen und helfen, die Defias zu schwächen, während die Späherkuppe weiter verteidigt wird.",al={"warum kopftücher sammeln","warum zahlt die miliz kopfgeld"}},{q="Wo findet man die Banditen, die diese Kopftücher tragen?",a="Gesetzlose der Defias durchstreifen nahezu jeden Winkel Westfalls. Sie besetzen verlassene Bauernhöfe, lauern an Wegkreuzungen und lagern an der Gold Coast sowie rund um die Hügel von Mondbruch.",al={"wo defiaskopftücher finden","defiasstandorte in westfall"}},{q="Was geschieht mit den Kopftüchern, nachdem Ihr sie abgegeben habt?",a="Späher Galiaan nutzt die Kopftücher als Beweise für gefallene Gesetzlose. Sie helfen ihm, die wechselnden Fronten der Defias zu verfolgen und einzuschätzen, wie sich die Feldzüge der Miliz auf die Stärke der Bruderschaft in der Region auswirken.",al={"was macht galiaan mit den kopftüchern"}},{q="Ist die Sturmwind Army an diesem Kopfgeldauftrag beteiligt?",a="Nein. Sturmwinds Militär hat Westfall weitgehend verlassen, um sich auf andere innere Unruhen zu konzentrieren. Die örtliche Verteidigung liegt bei Gryan Starkmantel und der aus Freiwilligen bestehenden Volksmiliz.",al={"sturmwinds wache in westfall","hilft sturmwind der späherkuppe"}}},fx={b62187e9={q="Warum möchte Späher Galiaan, dass Defias-Bandanas gesammelt werden?",a="Späher Galiaan verfolgt die sich verschiebenden Bewegungen der The Defias Brotherhood in ganz Westfall. Durch das Sammeln der roten Lederbandanas, die von ihren Fußsoldaten und Halsabschneidern getragen werden, kann er Bandenaktivitäten bestätigen, die Stärke ihrer Fronten einschätzen und ihre Zahl verringern, bevor sie die Späherkuppe vollständig überrennen.",al={"galiaan bandana motiv","warum will galiaan bandanas","warum rote lederbandanas sammeln"}},["868cbc1b"]={q="Wen jagt Ihr für diese Bandanas?",a="Ihr jagt die Wegelagerer und Handlanger der Bruderschaft der Defias, die durch die Ebenen und verlassenen Gehöfte von Westfall streifen. Späher Galiaan hat erfahren, dass sich viele Bandenmitglieder an ihren roten Lederbandanas erkennen lassen, und ihre wechselnde Front hat sich durch Überfälle, Diebstahl und Erpressung über die ganze Region ausgebreitet.",al={"wer hat rote bandanas","defias bandanas ziele","wer lässt red leather bandanas fallen"}}},fp="20,176,20.374.0,30.375.0,44.189.0,21.194.0,64.210.0,52.170.0,52.188.0,46.166.0"}
P.entries["quest:1530"] = {n="Ruf des Wassers",s="Schamanen der Horde ziehen auf Islen Wasserdeuters Geheiß nach Süden durch das Brachland und suchen Brine. Dort lernen sie, wie Wasser reinigt und heilt.",h="Schamanen der Horde ziehen auf Islen Wasserdeuters Geheiß nach Süden durch das Brachland und suchen Brine.",kw={"brachland","brine","ruf des wassers","islen wasserdeuter","borstennacken","wiedergeburt","schamane","water sapta"},ang={["class:Shaman"]="Für Euch als Schamanen ist die Zwiesprache mit dem Wasser ein wichtiger Schritt in Eurer Entwicklung. Sie vereint die Stärke der Erde und die Macht des Feuers mit der Heilkraft des Wassers.",["faction:Horde"]="Als Mitglied der Horde reist Ihr durch Kalimdor, um die Elemente zu meistern und die Geister zu ehren, die den Schamanen des Kriegshäuptlings ihre lebenswichtige Magie gewähren."},sec={{t="Lehren der Gezeiten",b="Islen Wasserdeuter lehrt, dass Wasser Wiedergeburt bringt. Es formt Fels, spült Unreinheiten fort und heilt Fleisch, doch nur, wenn es rein ist. Verschmutztes Wasser bringt Verderbnis statt Leben. Bevor ein Schamane die Zwiesprache mit dem Wasser sucht, muss er dieses Gleichgewicht verstehen."},{t="Eine Einsiedlerin im Staub",b="Ihr reist weit nach Süden durch das trockene Brachland, um Brine zu finden. Überfälle der Borstennacken plagen die Ödnis, doch Brine lebt allein, ohne Wachen oder Furcht. Sie verfügt über das Wissen und die Prüfungen, die Euch helfen werden, Euch mit dem Wasser zu verbinden."}},faq={{q="Wer ist Islen Wasserdeuter?",a="Islen Wasserdeuter ist eine Schamanenmeisterin an der Küste des Brachlands, südlich der Händlerküste. Sie führt Schamanen der Horde durch Prüfungen zur Zwiesprache mit Wassergeistern.",al={"islen","wasserdeuter","wer erteilt diese quest"}},{q="Warum im südlichen Brachland inmitten von Borstennacken leben?",a="Brine lebt allein in der südlichen Ödnis, obwohl die Borstennacken sie ständig bedrängen. Sie weiß, dass Außenstehende dies für töricht halten mögen, doch sie behält ihre Gründe für sich und prüft, ob Ihr die Willensstärke habt, sie zu finden.",al={"warum lebt brine dort","brine borstennacken","brine aufenthaltsort"}},{q="Welchem Zweck dient Water Sapta?",a="Ein Sapta ist eine zeremonielle Mischung, die die Wahrnehmung eines Schamanen verändert. Sie lässt ihn Elementargeister sehen und mit ihnen sprechen, die für sterbliche Augen unsichtbar sind.",al={"sapta","water sapta verwendung","warum water sapta holen"}},{q="Welche grundlegende Lehre verkörpert Wasser für einen Schamanen?",a="Wasser bringt Wiedergeburt, Reinigung und Erneuerung. Reines Wasser kann heilen, während verunreinigtes oder stehendes Wasser Verfall und Verwüstung bringt.",al={"lehre des wassers","elementare bedeutung wasser","wasser wiedergeburt"}},{q="Wer kann diese Reise antreten?",a="Schamanen der Horde, die ihre Hingabe bewiesen und sich auf Erde und Feuer eingestimmt haben, stellen sich den Prüfungen des Rufs des Wassers.",al={"wer erhält ruf des wassers","ruf des wassers nur für die horde"}},{q="Welche Gefahren lauern auf dem Weg zu Brine?",a="Angriffslustige Stämme der Borstennacken verteidigen ihre dornigen Bauten im südlichen Brachland, und wilde Tiere jagen Wanderer fern der Sicherheit des Wegekreuzes oder von Camp Taurajo.",al={"gefahren südliches brachland","weg zu brine"}}},fx={c40eecf4={q="Warum schickt Islen Wasserdeuter Euch nach Brine?",a="Islen Wasserdeuter möchte Euch durch die heiligen Prüfungen der Verbindung mit dem Wasser führen. Sie lehrt, dass Wasser Wiedergeburt, Heilung und verheerende Verderbnis verkörpert, wenn es unrein bleibt. Um die Water Sapta vorzubereiten, die benötigt wird, um den Schleier zu durchdringen und die Elementargeister wahrzunehmen, weist sie Euch an Brine, der das praktische Wissen und die Zutaten besitzt, die für Euren nächsten Ritus des Übergangs erforderlich sind.",al={"warum zu brine schicken","islen wasserdeuter motiv","warum brine suchen"}},d6b5acd2={q="Warum lässt Islen Wasserdeuter Euch diese Reise alleine unternehmen?",a="Die Verbindung mit den Elementen ist eine zutiefst persönliche spirituelle Reise, die jeder aufstrebende Schamane für sich selbst gehen muss. Weder Wachen noch Älteste können eine Prüfung des Verständnisses in Eurem Namen unternehmen. Die Suche nach Brine durch das feindselige südliche Brachland prüft Eure Entschlossenheit, Eigenständigkeit und Hingabe, um die Gunst der Wassergeister zu verdienen.",al={"warum muss ich zu brine gehen","warum ich call of water","warum schickt man den spieler alleine"}}},fp="13,140,19.259.0,21.220.0,23.158.0,56.204.0,39.145.0,50.128.0,31.112.0,38.154.0"}
P.entries["quest:1531"] = {n="Ruf der Luft",s="In Grommash Hold schickt Searn Feuerwächter erfahrene Schamanen für das Lufttotem nach Süden. Prate Cloudseer führt sie durch das letzte Element ihrer Kunst.",h="In Grommash Hold schickt Searn Feuerwächter erfahrene Schamanen für das Lufttotem nach Süden.",kw={"lufttotem","ruf der luft","orgrimmar","prate cloudseer","searn feuerwächter","schamanenquest","tausend nadeln","tal der geister"},ang={["class:Shaman"]="Das Lufttotem kennzeichnet den letzten Schritt Eurer frühen schamanischen Reise. Mit ihm ruft Ihr neben Erde, Feuer und Wasser auch die Windgeister an.",["faction:Horde"]="Eure schamanische Tradition verbindet die verschiedenen Völker der Horde miteinander. Älteste und Einsiedler im zentralen Kalimdor geben ihre heiligen Bräuche weiter."},sec={{t="Ein Atemzug aus dem Süden",b="Ihr habt die Gunst von Erde, Feuer und Wasser erlangt. Nun reist Ihr von Orgrimmar nach Süden durch das Brachland und dann hinab in die Schluchten von Tausend Nadeln, um das letzte Element kennenzulernen: Luft. Der Trolllehrer Searn Feuerwächter schickt Euch los, sobald er erkennt, dass Ihr für diesen letzten Schritt Eurer frühen Ausbildung bereit seid."},{t="Cloudseers Einsiedelei",b="Prate Cloudseer wartet in einer hoch gelegenen Höhle zwischen den Sandsteintafelbergen von Tausend Nadeln. Sie lebt zurückgezogen mit ihrem Partner, fernab der Lager der Horde, und erwartet Ehrerbietung, bevor sie die Geheimnisse des Windes teilt. Begegnet Ihr mit gebührendem Respekt, und sie vermittelt Euch das Wissen und die Konzentration, um das Lufttotem zu manifestieren. Dann ist Euer Kreis der elementaren Kunst vollendet."}},faq={{q="Wer beginnt diese Quest?",a="Searn Feuerwächter, ein Schamanenlehrer der Trolle in Grommash Hold, schickt geeignete Schamanen los, sobald sie für diesen Schritt bereit sind.",al={"questgeber","wo gibt es ruf der luft","searn feuerwächter"}},{q="Wo kann ich Prate Cloudseer finden?",a="Prate Cloudseer lebt in Tausend Nadeln. Nehmt den Großen Aufzug vom Südlichen Brachland hinab und reist dann über den Grund der Schlucht nach Osten, um ihre Höhle zu finden.",al={"prate cloudseer standort","prate finden","lufttotem npc"}},{q="Wozu dient das Lufttotem?",a="Das Lufttotem ist der vierte und letzte elementare Fokus, den ein Schamane erlangt. Es ermöglicht einem Schamanen, Luftzauber und Totems mit Schnelligkeit, Anmut und den Kräften des Windes zu wirken.",al={"lufttotem zweck","warum lufttotem-quest machen","was bewirkt das lufttotem"}},{q="Warum schickt Searn Feuerwächter Euch so weit fort?",a="Die Elemente zu meistern bedeutet, Mentoren zu finden, die sich bestimmten Geistern verschrieben haben. Prate Cloudseer kennt die wechselnden Windböen in den Schluchten von Tausend Nadeln und ist damit eine passende Lehrerin für das Element Luft.",al={"warum tausend nadeln","warum prate cloudseer"}},{q="Muss ich zuerst andere Quests für Elementartotems abschließen?",a="Ja. Die Schamanenausbildung folgt einer festen Reihenfolge durch die Elemente: Erde, dann Feuer und Wasser und schließlich Luft.",al={"voraussetzungen","totemreihenfolge","lufttotem zuerst möglich"}},{q="Gibt es andere Fassungen dieser Quest für verschiedene Städte?",a="Ja. Schamanenlehrer in anderen Hauptstädten der Horde, darunter Donnerfels, schicken Schamanen zu Prate Cloudseer in Tausend Nadeln.",al={"donnerfels lufttotem","unterstadt lufttotem"}}},fx={["9e3dc8ab"]={q="Warum schickt Euch Searn Feuerwächter zu Prate Cloudseer?",a="Searn Feuerwächter sieht, dass Euer spirituelles Wachstum als Schamane weit genug fortgeschritten ist, um mit den Geistern der Luft in Verbindung zu treten. Er kann die Verbindung mit dem Lufttotem nicht selbst gewähren, da diese Weisheit bei Prate Cloudseer in Tausend Nadeln liegt. Euch zu ihr zu führen, ist seine Pflicht als Mentor, um sicherzustellen, dass Ihr den gebührenden Respekt vor den launischen Geistern des Windes von jemandem lernt, der tief in ihre Wege eingeweiht ist.",al={"beweggrund von searn feuerwächter","warum will searn dies erledigt haben","warum zu prate cloudseer schicken"}},bc8bd922={q="Warum muss Searn Feuerwächter Euch schicken, anstatt es selbst zu tun?",a="Der Pfad eines Schamanen ist eine individuelle spirituelle Reise, die nicht durch einen Stellvertreter gegangen werden kann. Searn Feuerwächter beherrscht bereits die Elemente und dient der Horde, indem er Novizen in Orgrimmar ausbildet. Das Lufttotem zu verdienen erfordert, dass Ihr persönlich Eure Demut, Widerstandsfähigkeit und Euren Respekt direkt vor Prate Cloudseer und den Winden, mit denen sie verkehrt, beweist.",al={"warum ich call of air","warum muss ich zu prate","warum geht searn nicht selbst"}}},fp="11,152,23.299.0,25.374.0,22.117.0,33.153.0,31.163.0,47.187.0,57.107.0,60.123.0"}
P.entries["quest:1532"] = {n="Ruf der Luft",s="Xanis Flameweaver schickt erfahrene Schamanen der Horde von Donnerfels nach Süden, um Prate Cloudseer in Tausend Nadeln aufzusuchen. Dort suchen sie Zwiesprache mit dem Wind und streben nach dem Lufttotem, das seine flinken Kräfte kanalisiert.",h="Xanis Flameweaver schickt erfahrene Schamanen der Horde von Donnerfels nach Süden, um Prate Cloudseer in...",kw={"lufttotem","ruf der luft","prate cloudseer","schamane","tausend nadeln","donnerfels","xanis flameweaver"},ang={["class:Shaman"]="Für Euch als Schamane ist die Vervollständigung Eurer Elementartotems ein Wendepunkt. Das Lufttotem eröffnet Euch den Zugang zu flinken Strömungen und blitzumwobenen Kräften.",["faction:Horde"]="Als Schamane der Horde stärkt Ihr den spirituellen Rückhalt Eurer Fraktion, indem Ihr Kalimdors wilde Winde in einem heiligen Totem bindet.",["race:Tauren"]="Als Tauren verehrt Ihr die Winde als heilige Boten. Sie tragen das Flüstern der Earth Mother von Mulg ores hoch aufragenden Felsklippen über die Ebenen."},sec={{t="Die flüsternden Winde",b="Ihr habt Euch auf Erde, Feuer und Wasser eingestimmt. Nun führt Euch Xanis Flameweaver von Donnerfels aus durch eine Prüfung der Demut, Konzentration und Ehrfurcht vor dem Himmel. Luft ist das letzte Element, und ihre Winde sind launisch. Sie sind schwerer zu beherrschen als die Elemente, die Ihr bereits kennengelernt habt."},{t="Eine Pilgerreise nach Süden",b="Euer Weg führt nach Süden, am Brachland vorbei und in die Schluchten von Tausend Nadeln. Weit im Osten wohnt Prate Cloudseer in einer abgeschiedenen Höhle an den Felswänden, wo die Winde der Schluchten Tag und Nacht heulen. Sie prüft Eure Bereitschaft, bevor sie Euch das Lufttotem gibt. Es kanalisiert Windstöße, Blitze und flinke Windgeister."}},faq={{q="Wer schickt mich auf diese Quest?",a="Xanis Flameweaver, ein Schamanenlehrer in Donnerfels, schickt Euch los, um Euch auf die Luft einzustimmen, sobald Ihr genug Erfahrung gesammelt habt.",al={"questgeber","wer startet ruf der luft","xanis flameweaver"}},{q="Wo befindet sich Prate Cloudseer?",a="Prate Cloudseer lebt in einer geschützten Höhle weit im Osten von Tausend Nadeln, unmittelbar südlich des Brachlands.",al={"prate cloudseer aufenthaltsort","wo ist prate","prate cloudseer finden"}},{q="Warum wird das Element Luft zuletzt aufgesucht?",a="Schamanen suchen die Luft zuletzt auf, weil ihre Strömungen unberechenbar und schwer zu fassen sind. Die Tradition verlangt, Erde, Feuer und Wasser zu meistern, bevor man versucht, sich auf die wilden Winde einzustimmen.",al={"warum luft zuletzt","schamane lufttotem hintergrund","reihenfolge der elemente"}},{q="Was erhalte ich, wenn ich Prate Cloudseer finde?",a="Prate Cloudseer gibt Euch das Lufttotem, mit dem Ihr Eure Elementarmagie bündeln und Luftgeister zur Unterstützung anrufen könnt.",al={"lufttotem belohnung","was gibt prate","questbelohnung ruf der luft"}},{q="Ist diese Quest ausschließlich für Tauren?",a="Jeder Schamane der Horde, der sich auf Erde, Feuer und Wasser eingestimmt hat, kann von Donnerfels nach Tausend Nadeln reisen, um ein Lufttotem zu erhalten.",al={"können orks das machen","ist das nur für tauren","horde schamane luftquest"}},{q="Was geschieht nach Abschluss dieser Quest?",a="Bei Eurer Ankunft gibt Euch Prate Cloudseer das Lufttotem, mit dem Ihr sofort Windtotems beschwören könnt. Sie bietet Euch auch weitere Unterweisungen und Prüfungen an, um Eure Verbindung zum Himmel zu vertiefen.",al={"what comes next","nach ruf der luft","prate cloudseer quests"}}},fx={["52df4f2b"]={q="Warum schickt mich Xanis Flameweaver auf diese Quest?",a="Xanis Flameweaver sieht, dass Ihr auf Eurem schamanischen Pfad stark genug geworden seid, um die Meisterschaft über das flüchtigste Element anzustreben: die Luft. Als Euer Mentor in Donnerfels erkennt er, dass die rauschenden Winde von Kalimdor nach Euch rufen. Das Element Luft ist bekanntermaßen schwierig zu binden und mit ihm zu verkehren, und Xanis kann dieses letzte Verständnis selbst nicht von den hohen Klippen aus vermitteln. Stattdessen schickt er Euch nach Süden in Tausend Nadeln, damit Prate Cloudseer Euch in die Verbindung mit den Luftgeistern einweihen kann.",al={"warum xanis mich schickt","beweggrund von xanis flameweaver","zweck von call of air"}}},fp="11,209,20.279.0,18.310.0,27.120.0,33.105.0,38.167.0,47.124.0,34.131.0,40.185.0"}
P.entries["quest:1534"] = {n="Ruf des Wassers",s="Brine schickt einen Schamanen vom Brachland nach Norden, um Wasser für den Ruf des Wassers zu sammeln. Diese letzte Essenz stammt aus einem uralten Brunnen in Eschental.",h="Brine schickt einen Schamanen vom Brachland nach Norden, um Wasser für den Ruf des Wassers zu sammeln.",kw={"eschental","blauer wasserschlauch","brine","ruf des wassers","islen wasserdeuter","mystralsee","die sternenstaubruinen","schamane"},ang={["class:Shaman"]="Als Schamane überschreitet Ihr auf der Suche nach Gleichgewicht gefährliche Grenzen und sammelt die letzte flüssige Essenz, die zum Binden des Wassertotems nötig ist.",["faction:Horde"]="Als Reisender der Horde betretet Ihr uraltes Land der Kaldorei, wo die Vorhut des Kriegshymnenklans einen anhaltenden Holzkrieg gegen feindselige Nachtelfenschildwachen führt.",["race:Tauren"]="Als Tauren reist Ihr aus der trockenen Heimat im Herzen Kalimdors zu heiligen Hainen, von denen Mythen und Lieder der Ältesten erzählen."},sec={{t="Reise in den Zwielichtshain",b="Nachdem Ihr Wasser aus dem Teich unter Brines Hütte im Brachland und dem reinen Brunnen von Tarrens Mühle gesammelt habt, braucht Ihr eine letzte Essenz. Brine schickt Euch nach Norden über die trockenen Ebenen nach Eschental, einem uralten Wald, der den Nachtelfen heilig ist. Das Brachland weicht Eschentals dichtem Blätterdach, wo Wasser eine andere Gestalt annimmt. Um im Einklang mit dem Element zu leben, muss ein Schamane seine vielen Formen verstehen."},{t="Die Sternenstaubruinen",b="Jenseits der schimmernden Wasser des Mystralsees, nahe dem Gebirgspass zwischen Eschental und dem Steinkrallengebirge, liegen die Sternenstaubruinen. In diesem abgeschiedenen elfischen Heiligtum steht ein uralter Brunnen zwischen stillen Gewässern und alten Steinen. Ungezähmte Elementar- und Naturgeister bewachen die Ruinen und dulden keine Eindringlinge. Geht vorsichtig vor, wenn Ihr Wasser aus dem Brunnen schöpft."},{t="Der Trunk reinsten Wassers",b="Brine erhält nach Eurer Pilgerreise durch Kalimdor und die Östlichen Königreiche den vollen blauen Wasserschlauch. Sie vermischt das reine Brunnenwasser mit Proben aus der Wasserstelle im Brachland und aus Tarrens Mühle und bereitet dann eine Phiole reinsten Wassers zu. Dieser Trunk bereitet Euch auf die nächste Prüfung vor: Zwiesprache mit Wasserelementargeistern durch die Seherin Islen Wasserdeuter."}},faq={{q="Wo liegen die Sternenstaubruinen?",a="Die Sternenstaubruinen liegen im Südwesten von Eschental. Reist vom Brachland nach Norden und folgt dann den Straßen nach Westen, am Mystralsee vorbei in Richtung der Ausläufer des Steinkrallengebirges.",al={"lage der sternenstaubruinen","wo ist stardust","weg zu den sternenstaubruinen"}},{q="Warum braucht Brine Wasser aus einer elfischen Ruine?",a="Ein Schamane sammelt Wasser aus verschiedenen Formen des Elements, um mit den Wassergeistern Zwiesprache zu halten. Der Brunnen in den Sternenstaubruinen birgt uraltes, magisch reines Wasser, unberührt von der dürren Ödnis des Brachlands. Es vervollständigt die drei Essenzen, die Brine für ihre Ritualmischung braucht.",al={"warum wasser aus eschental","warum sternenstaubruinen","grund für stardust-wasser"}},{q="Welche Gefahren gibt es rund um die Sternenstaubruinen?",a="Wachsame Wildtiere und Naturgeister bewachen die Ruinen und die nahen Gewässer. Wasserelementare, die ihr Revier verteidigen, und in Eschental heimische Wildtiere greifen jene an, die den Hain stören.",al={"stardust feinde","ist stardust gefährlich","wer bewacht den brunnen"}},{q="Wer ist Brine und warum hilft sie?",a="Brine ist eine asketische Orkschamanin, die in einer einsamen Hütte im südlichen Brachland lebt. Als erfahrene Mentorin an der Seite von Islen Wasserdeuter prüft sie Geduld, Ausdauer und Wasserverständnis angehender Schamanen, bevor sie ihnen den Segen des Elements gewährt.",al={"wer ist brine","brines geschichte","welche rolle hat brine"}},{q="Was geschieht, nachdem Ihr dieses Wasser zu Brine gebracht habt?",a="Wenn Brine die dritte Probe erhält, vermischt sie die Wasser zu einem Trunk reinsten Wassers. Dann schickt sie Euch zu Islen Wasserdeuter an der Ostküste des Brachlands, um in Visionen mit den Elementaren Zwiesprache zu halten.",al={"nächster schritt ruf des wassers","was geschieht als nächstes","wohin nach brine"}},{q="Ist Eschental für Hordenschamanen niedriger Stufe sicher?",a="Eschental ist ein umkämpftes Gebiet, in dem Nachtelfen und Horde aufeinanderprallen. Der Weg durch die südlichen Wälder umgeht größere Nachtelfensiedlungen wie Astranaar, doch umherstreifende Wildtiere, aggressive Elementare und Allianzpatrouillen gefährden einen Initianden.",al={"ist eschental gefährlich","stufe für eschental-quest"}}},fx={d600fc8e={q="Warum möchte Brine, dass dies erledigt wird?",a="Brine führt angehende Schamanen durch ihre Wasserprüfung. Durch das Sammeln reiner Proben von fernen und heiligen Orten beweist Ihr Eure Hingabe zum Verständnis des Elements. Sobald Ihr Wasser aus dem uralten Brunnen bei The Ruins of Stardust beschafft, kann sie all Eure gesammelten Wässer zu einem Trank von höchster Reinheit vermengen, womit sie ihren Teil an Eurem Initiationsritus erfüllt und Euch darauf vorbereitet, zu Islen Wasserdeuter zurückzukehren.",al={"warum hilft brine","beweggrund von brine call of water","warum wasser aus stardust sammeln"}},bc32fa0f={q="Wozu dient der Volle blaue Wasserschlauch?",a="Der Schlauch enthält das unberührte Wasser, das aus dem heiligen Brunnen innerhalb von The Ruins of Stardust im Eschental geschöpft wurde. Er dient als dritte und letzte reine Wasserkomponente, die Brine benötigt, um ein Fläschchen mit makellosem Wasser für Eure Schamanenprüfungen zusammenzubrauen.",al={"was macht der volle blaue wasserschlauch","verwendung voller blauer wasserschlauch","warum blauen wasserschlauch füllen"}},d1cea88a={q="Warum schickt Brine Euch, anstatt das Wasser selbst zu holen?",a="Diese Reise ist ein wesentlicher Bestandteil Eures Initiationsritus als Schamane. Das Aufsuchen ferner, heiliger Wasser testet Eure Ausdauer, Euren Respekt vor den Elementen und Eure Hingabe. Brine bleibt an ihrem Teich, um die Rituale vorzubereiten, aber die Pilgerreise selbst muss von Euch persönlich unternommen werden.",al={"warum muss ich das wasser holen","warum geht brine nicht ins eschental","warum schickt man mich call of water"}}},fp="13,142,31.404.0,21.361.0,27.363.1,40.179.0,45.275.0,48.167.0,36.249.0,48.212.1,46.259.0"}
P.entries["quest:1535"] = {n="Ruf des Wassers",s="Brine schickt Schamanen durch das Brachland, um Wasser für einen Sapta zu sammeln. Unterhalb ihres Hügels liefert ein bewachtes Wasserloch die erste Probe, und Wasser bedeutet Überleben.",h="Brine schickt Schamanen durch das Brachland, um Wasser für einen Sapta zu sammeln.",kw={"brachland","brine","brauner wasserschlauch","ruf des wassers","quilboar","sapta","wasserloch"},ang={["class:Shaman"]="Als Schamane lernt Ihr, dass Wasser Heilung und Erneuerung bringt, aber auch Konflikte und den verzweifelten Kampf ums Überleben entfacht.",["faction:Horde"]="Als Mitglied der Horde steht Ihr vor der Herausforderung, Wasser im Brachland zu kontrollieren und zu teilen, wo Stämme und Bestien um jedes Rinnsal kämpfen."},sec={{t="Eine Lektion in der Wüste",b="Brine bittet Schamaneninitianden, Wasser in all seinen Formen zu studieren, bevor sie ihnen den Water Sapta gewährt. Der Sapta erweitert die Wahrnehmung eines Initianden und ermöglicht ihm, mit den Geistern Zwiesprache zu halten. Im trockenen Brachland bedeutet Wasser Überleben. Wälder gedeihen, wo es fließt, während Wüsten ohne Wasser darben. Lebewesen töten, um selbst die unscheinbarste Quelle zu schützen."},{t="Der Hort der Quilboar",b="Quilboar bewachen das Wasserloch unterhalb von Brines Hügel erbittert. Sie betrachten jedes Wasserloch als unbezahlbaren Hort und feiern, wenn Regen fällt. Brine bedauert die Gewalt, die ihr Horten mit sich bringt. Doch ihre Gier und ihre gespaltenen Clans halten ihre Bedrohung in Grenzen und wahren ein unsicheres Gleichgewicht für die anderen Völker der Ebenen."}},faq={{q="Welchen Zweck hat das Sammeln von Wasser für Brine?",a="Brine braucht Proben reinen Wassers aus verschiedenen Winkeln der Welt, um einen zeremoniellen Water Sapta zu brauen. Der Trank erweitert die Wahrnehmung eines Initianden und ermöglicht die Zwiesprache mit elementaren Wassergeistern.",al={"warum wasser holen","brine wasseraufgabe","ruf des wassers quest drei zweck"}},{q="Warum ist das Wasserloch unterhalb von Brine so heftig umkämpft?",a="Wasser ist die kostbarste Ressource im ausgedörrten Brachland. Die einheimischen Quilboar betrachten jedes Wasserloch als heiligen Schatz und bekämpfen jeden erbittert, der daraus schöpfen will.",al={"warum bewachen quilboar wasser","quilboar teich","wasserloch brachland"}},{q="Wer ist Brine?",a="Brine ist eine Orkschamanin und Einsiedlerin, die in einer einsamen Hütte über dem Südlichen Brachland lebt. Ihre tiefe Weisheit über Wasser und Elementargeister führt Schamanen der Horde zur Zwiesprache.",al={"wer ist brine","brine brachland","brine nsc"}},{q="Was geschieht nach der Rückgabe des vollen braunen Wasserschlauchs?",a="Nachdem Ihr mit einer Probe aus dem Wasserloch zurückgekehrt seid, schickt Brine Euch weiter hinaus, um reines Wasser an ganz unterschiedlichen Orten zu sammeln, darunter am Brunnen von Tarrens Mühle im Vorgebirge des Hügellands.",al={"wie weiter bei ruf des wassers","nach dem wasserloch","nächster schritt brine"}},{q="Warum spricht Brine die Spaltung der Quilboar an?",a="Brine sieht im Revierverhalten der Quilboar und den Rivalitäten ihrer Clans die Ursachen ihres Elends. Würden sie sich vereinen, statt um einzelne Quellen zu kämpfen, würden sie den Rest des Brachlands weit stärker bedrohen.",al={"brine quilboar bemerkungen","warum kämpfen quilboar gegeneinander"}},{q="Was ist ein Sapta?",a="Ein Sapta ist ein mystisches Elixier, das Schamanen aus gesammelten Reagenzien und Wassern zubereiten, die mit den Elementen im Einklang stehen. Wer ihn trinkt, erweitert seine geistige Sicht und erkennt Elementarwesen, die sterblichen Augen gewöhnlich verborgen bleiben.",al={"was ist sapta","water sapta bedeutung"}}},fx={["6eca6e0d"]={q="Wozu dient der Volle braune Wasserschlauch?",a="Der Volle braune Wasserschlauch enthält eine Wasserprobe, die aus dem umstrittenen Teich unterhalb von Brines Hügel stammt. Brine verlangt von Euch, dieses Wasser nicht nur als Zutat zum Brauen der Water Sapta zu sammeln, sondern auch als Anschauungsunterricht für Eure Schamanenprüfungen. Indem Ihr es holt, werdet Ihr Zeuge der erbitterten Verbundenheit und des Blutvergießens, das die knappe, lebensspendende Flüssigkeit unter den örtlichen Stachelebern hervorruft.",al={"zweck voller brauner wasserschlauch","warum voller brauner wasserschlauch","voller brauner wasserschlauch"}}},fp="13,151,22.346.0,20.311.0,50.198.0,58.171.0,13.182.0,56.196.1,49.202.0,16.203.0"}
P.entries["quest:1536"] = {n="Ruf des Wassers",s="Ihr verlasst das Brachland für eine reine Quelle im von den Verlassenen gehaltenen Tarrens Mühle. Ihr Wasser hilft Brine, das Water Sapta zuzubereiten, und ihr Fortbestehen schenkt Hoffnung.",h="Ihr verlasst das Brachland für eine reine Quelle im von den Verlassenen gehaltenen Tarrens Mühle.",kw={"brachland","brine","ruf des wassers","hillsbrad","sapta","schamane","tarrens mühle","thrall","wasserschlauch"},ang={["class:Shaman"]="Als Schamane reist Ihr weit, um Wasser zu holen. Ihr lernt, inmitten der trostlosen Lande der Östlichen Königreiche nach Harmonie und Leben zu suchen.",["faction:Horde"]="Als Krieger oder Schamane der Horde, der in Kalimdor geboren wurde, besucht Ihr Tarrens Mühle und begegnet den Verlassenen, Euren neuen, schwierigen Verbündeten an der Front gegen Hillsbrads menschliche Verteidiger.",["race:Orc"]="Als Orc könnt Ihr über Thralls Vermächtnis des Überlebens und der Stärke nachdenken und über den hohen Preis, der für Eure Freiheit gezahlt wurde."},sec={{t="Eine wundersame Quelle",b="Brine schickt Euch über das Meer nach Tarrens Mühle im Vorgebirge des Hügellands. Sie braucht Wasser von dort, um das Water Sapta zuzubereiten. Menschlicher Widerstand und die neu verbündeten Verlassenen umgeben den Ort, doch sein kleiner Brunnen im Zentrum spendet reines Quellwasser. Für Brine ist er ein heiliges Überbleibsel der Reinheit in einem unheiligen Land."},{t="Beständigkeit in der Finsternis",b="Für Brine ist der reine Brunnen in Tarrens Mühle mehr als eine Zutat. Sie erkennt seine Beständigkeit in Kriegshäuptling Thrall wieder, der Entbehrungen, Gefangenschaft und Leid ertrug, bevor er zum Anführer des orcischen Volkes aufstieg. Thrall schenkt der Horde Hoffnung. Der Brunnen zeigt, dass Leben und Reinheit Tragödien und Verderbnis überdauern können."}},faq={{q="Wo wird die Wasserprobe gesammelt?",a="Ihr schöpft die Probe aus dem Brunnen im Zentrum von Tarrens Mühle, einer alten Menschensiedlung im Vorgebirge des Hügellands, die nun die Verlassenen halten.",al={"tarrens mühle wasser","wo ist der brunnen","ruf des wassers brunnenstandort"}},{q="Warum schickt Brine Euch für Wasser so weit fort?",a="Brine braucht unterschiedliche Wasseressenzen, um das Water Sapta zu brauen, mit dem Schamanen Elementargeister wahrnehmen können. Sie entdeckte diese Quelle auf einer früheren Reise nach Hillsbrad und schätzt ihre Reinheit inmitten des Verfalls der Verlassenen als kraftvoll und lehrreich.",al={"warum tarrens mühle","warum wasser aus hillsbrad","warum brine dieses wasser will"}},{q="Was ist Tarrens Mühle?",a="Tarrens Mühle ist eine bescheidene Menschenstadt im nördlichen Vorgebirge des Hügellands. Sylvanas Windläufers Verlassene halten sie nun als befestigten Außenposten der Horde gegen die örtlichen menschlichen Streitkräfte.",al={"tarrens mühle geschichte","wem gehört tarrens mühle"}},{q="Wie hängt diese Quest mit Thrall zusammen?",a="Brine vergleicht den reinen Brunnen mit Kriegshäuptling Thrall. Obwohl Thrall versklavt und gequält wurde, bewahrte er die Stärke und Weitsicht, die New Horde anzuführen, so wie der Brunnen inmitten von Seuche und Tod seine Frische bewahrt.",al={"brine thrall dialog","verbindung zu thrall"}},{q="Was geschieht nach der Rückgabe des gefüllten Wasserschlauchs?",a="Brine nimmt den vollen roten Wasserschlauch entgegen. Sie erklärt Euch, dass sie noch eine weitere, andersartige Wasserprobe braucht, um die Reagenzienmischung für Euer Water Sapta fertigzustellen.",al={"was kommt als nächstes bei ruf des wassers","nach dem wasser aus tarrens mühle"}},{q="Warum gilt die Reinheit des Brunnens als ungewöhnlich?",a="Ein Großteil Lordaerons wurde durch die Seuche des Untodes der Geißel entweiht, und Siedlungen der Verlassenen werden selten mit frischen Quellen verbunden. Doch der Brunnen im Zentrum von Tarrens Mühle spendet noch immer makelloses Wasser, ein seltenes unverdorbenes Überbleibsel.",al={"warum ist das wasser in tarrens mühle rein","verlassene verschmutzter brunnen"}}},fx={["05ee6a54"]={q="Wozu dient der Volle rote Wasserschlauch?",a="Der Volle rote Wasserschlauch enthält reines Quellwasser, das aus dem Brunnen in Tarrens Mühle in Hillsbrad geschöpft wurde. Brine benötigt diese reine Probe zusammen mit anderen, um ein spezielles Reagenz für Eure Water Sapta zu brauen. Das Trinken dieses Tranks wird Euch die spirituelle Sicht verleihen, die nötig ist, um direkt mit Wassergeistern zu verkehren.",al={"verwendung voller roter wasserschlauch","warum voller roter wasserschlauch","wasserprobe tarrens mühle"}}},fp="13,150,19.308.0,21.300.0,36.136.0,46.235.0,20.167.0,38.198.0,50.146.0,44.215.0"}
P.entries["quest:154"] = {n="Rückkehr mit dem Kamm",s="In Dunkelhain wartet Madame Eva auf den Kamm, den die blinde Mary zurückgegeben hat. Seine geisterhaften Strähnen lassen sich zu Geisterhaarfaden verspinnen.",h="In Dunkelhain wartet Madame Eva auf den Kamm, den die blinde Mary zurückgegeben hat.",kw={"die blinde mary","dunkelhain","dämmerwald","geisterhaar","geisterhaarfaden","madame eva","rückkehr mit dem kamm"},ang={["class:Priest"]="Als Priester könnt Ihr erkennen, wie Trauer Geister quält, die an die Welt der Sterblichen gebunden sind, selbst wenn sie nichts Böses im Sinn haben.",["faction:Alliance"]="Als Reisender der Allianz zieht Ihr über düstere Straßen zwischen Dunkelhain und Marys Heim, wo der Verfall des Dämmerwalds die Straßen erreicht.",["profession:Tailoring"]="Das Spinnen von Geisterhaarfaden zeigt, wie sich das geisterhafte Material des Dämmerwalds gewinnen und zu haltbaren übernatürlichen Textilien kardieren lässt."},sec={{t="Ein bitteres Spiegelbild",b="Die blinde Mary wartet in einer Hütte südlich von Dunkelhain und trauert um den Tod, der sie verändert hat. Madame Evas Kamm erinnert sie an die Körperpflege zu ihren Lebzeiten und vertieft ihren Kummer. Sie sieht nur einen Geist, ein Monster, dem jede sterbliche Anmut genommen wurde. Überzeugt, dass niemand sie je wieder lieben kann, drückt sie Euch den Kamm und das geisterhafte Haar zwischen seinen Zinken wieder in die Hände."},{t="Das Übernatürliche verweben",b="Madame Eva erwartet den Kamm in Dunkelhain und weiß, dass die Arbeit bedrückend war. Aus dem geisterhaften Haar kann die Wahrsagerin eine Spule Geisterhaarfaden spinnen. Für alle Strähnen, die nach der behutsamen Arbeit übrig bleiben, bezahlt sie Euch."}},faq={{q="Warum reagiert die blinde Mary entsetzt auf den Kamm?",a="Der Kamm erinnert die blinde Mary an ihr sterbliches Leben und ihre Schönheit. Sich als verkümmerten Geist zu sehen, überwältigt sie mit Trauer, und sie weist den Kamm zurück, überzeugt, ein Monster geworden zu sein, das niemand lieben wird.",al={"warum ist mary aufgewühlt","warum hat die blinde mary geschrien","marys reaktion auf den kamm"}},{q="Was macht Madame Eva mit dem Haar am Kamm?",a="Madame Eva verwebt das Haar aus dem Kamm zu Geisterhaarfaden, einem mystischen Faden, mit dem sich böse Geister binden und unbelebten Gegenständen Leben einnähen lässt.",al={"warum geisterhaar","was macht eva mit geisterhaar","madame evas faden"}},{q="Wo befindet sich die blinde Mary?",a="Die blinde Mary spukt in einer verfallenen Hütte südlich von Dunkelhain, nahe dem Friedhof \"Stille Gärten\" im Dämmerwald.",al={"wo ist die blinde mary","aufenthaltsort der blinden mary"}},{q="Wer ist Madame Eva?",a="Madame Eva ist eine menschliche Mystikerin und Wahrsagerin, die in Dunkelhain lebt. Wer sich den Gefahren des Dämmerwalds stellt, erhält von ihr Weissagungen, rätselhafte Ratschläge sowie magischen Tand und Reagenzien.",al={"wer ist madame eva","eva dunkelhain"}},{q="Was folgt, nachdem Ihr Madame Eva den Kamm zurückgebracht habt?",a="Nachdem Madame Eva den Kamm entgegengenommen und den Geisterhaarfaden vorbereitet hat, bittet sie Euch, ihn Calvinius zu bringen, dem Einsiedler nahe dem Friedhof von Rabenflucht.",al={"what comes next","nächste quest nach rückkehr mit dem kamm"}},{q="Warum gibt Madame Eva Euch zum Abschluss Münzen?",a="Madame Eva sagt, am Kamm sei weit mehr geisterhaftes Haar gewesen, als für die Spule nötig war. Sie gibt Euch ein paar Münzen für die übrigen Strähnen, die sie behält.",al={"warum gibt es münzen","geld für übrige strähnen"}}},fp="15,124,19.349.0,24.207.0,50.200.0,50.145.0,28.101.0,18.183.0,52.145.1,51.133.0"}
P.entries["quest:155"] = {n="Die Bruderschaft der Defias",s="In Westfall sucht die Volksmiliz den verborgenen Stützpunkt der Bruderschaft der Defias. Ein gefangener Brigant führt Euch im Austausch für Schutz dorthin, durch Mondbruch bis in Edwin van Cleefs Allerheiligstes.",h="In Westfall sucht die Volksmiliz den verborgenen Stützpunkt der Bruderschaft der Defias.",kw={"die todesminen","verräter der defias","edwin van cleef","eskorte","gryan starkmantel","mondbruch","volksmiliz","späherkuppe","westfall"},ang={["class:Rogue"]="Als Schurke kennt Ihr den Preis des Verrats in der Unterwelt, wo gebrochene Schwüre mit Dolchen beantwortet werden.",["faction:Alliance"]="Für die bedrängte Volksmiliz ist die Entdeckung des Verstecks ein großer militärischer Durchbruch und ihre erste wirkliche Chance, Westfalls verbrecherischem Aufstand einen entscheidenden Schlag zu versetzen.",["race:Human"]="Als Mensch aus Sturmwind seht Ihr Mondbruch der Gesetzlosigkeit verfallen und von ehemaligen Stonemasons besetzt. Das zeigt, wie tief das Königreich seit dem Dritten Krieg gespalten ist."},sec={{t="Der Handel eines Überläufers",b="Der Verräter der Defias fürchtet die Hinrichtung oder die Ermordung durch seine ehemaligen Brüder. Also handelt er mit der Volksmiliz: Eskortiert ihn sicher durch feindliches Gebiet, und er verrät, wo sich Edwin van Cleef und seine Rädelsführer verstecken. Das Netzwerk der Diebe bringt jene zum Schweigen, die auspacken, und der Überläufer braucht unterwegs bewaffneten Schutz."},{t="Der Weg durch Mondbruch",b="Der Verräter führt Euch von der Späherkuppe nach Südwesten nach Mondbruch, einer von der Bruderschaft überrannten Ortschaft. Er führt Euch am verlassenen Marktplatz und am Brunnen vorbei und zieht den Zorn der Briganten, Plünderer und Wegelagerer auf sich, die durch die Ruinen patrouillieren. Dann führt er Euch zum Eingang der weitläufigen Todesminen unter Mondbruch, wo van Cleef eine unterirdische Festung ausgebaut hat."}},faq={{q="Wer ist der Verräter der Defias?",a="Der Verräter der Defias ist ein ehemaliges Mitglied der Bruderschaft, das zum Informanten für Gryan Starkmantel und die Volksmiliz wurde. Aus Furcht vor dem Tod durch seine ehemaligen Kameraden verriet er den Standort von Edwin van Cleefs unterirdischer Zuflucht im Austausch für Geleit in Sicherheit.",al={"wer ist der verräter","identität des verräters der defias","ratte der defias"}},{q="Wohin führt Euch der Verräter?",a="Er führt Euch von der Späherkuppe nach Südwesten nach Mondbruch, am verfallenen Marktplatz und am Brunnen vorbei, zum Eingang der Todesminen unter der Stadt.",al={"wo ist das versteck der defias","weg des verräters","wohin geht er"}},{q="Warum braucht Gryan Starkmantel diese Informationen?",a="Die Volksmiliz hat in ganz Westfall gegen Wegelagerer gekämpft, ohne zu wissen, von wo aus Edwin van Cleef die Einsätze lenkt. Den Eingang zu seinem unterirdischen Versteck zu finden, gibt der Miliz ein klares Angriffsziel im Herzen der Rebellion.",al={"warum eskortieren wir den verräter","starkmantels absicht","warum das versteck finden"}},{q="Warum wimmelt es in Mondbruch von Defias?",a="Mondbruch war einst ein blühendes landwirtschaftliches Zentrum, doch das Königreich Sturmwind wurde vernachlässigt, und Banditen zogen ein. Die Bewohner verließen die Stadt, und die Bruderschaft der Defias besetzte die leeren Gebäude als oberirdischen Verteidigungsring zum Schutz des Eingangs der Todesminen.",al={"warum sind defias in mondbruch","übernahme von mondbruch","wem gehört mondbruch"}},{q="Was geschieht, nachdem Ihr das Versteck entdeckt habt?",a="Nachdem der Verräter den Eingang der Todesminen enthüllt hat, erstattet Ihr Gryan Starkmantel auf der Späherkuppe Bericht. Mit dem Beweis für van Cleefs Aufenthaltsort bereitet die Miliz einen direkten Angriff auf das unterirdische Versteck vor.",al={"what comes next","nach der defias-eskorte","questfortschritt"}},{q="Warum will die Bruderschaft den Verräter tot sehen?",a="Die Defias sind auf Geheimhaltung angewiesen und verbergen sich in Tunneln, während sie ihre Einsätze in allen Gebieten Sturmwinds lenken. Ein Überläufer, der den Eingang zu ihrem Hauptstützpunkt verrät, droht ihre Verschwörung auffliegen zu lassen.",al={"warum den verräter töten","defias greifen verräter an"}}},fx={["0ac3b75c"]={q="Warum ist Der Verräter der Defias bereit, Euch zu führen?",a="Der Verräter hat einen verzweifelten Handel mit The People's Militia abgeschlossen. Nachdem er Edwin van Cleef und der Bruderschaft den Rücken gekehrt hat, weiß er, dass er ein gezeichneter Mann ist, dessen ehemalige Kameraden seinen Kopf wollen. Euch direkt zum geheimen Versteck zu führen, ist das einzige Pfand, das ihm bleibt, um sein eigenes Überleben und seine Freiheit unter dem Schutz von Gryan Starkmantel zu erkaufen.",al={"warum dem defias-verräter helfen","beweggrund defias-verräter","warum führt der verräter euch"}},ef72c66d={q="Warum schickt Gryan Starkmantel Euch, um den Verräter zu eskortieren, anstatt seine eigenen Wachen zu schicken?",a="The People's Militia ist verzweifelt dünn besetzt, nur um Späherkuppe zu halten und Banditenüberfälle in ganz Westfall abzuwehren. Sturmwind hat sich geweigert, königliche Truppen zur Unterstützung der Region abzustellen, wodurch Starkmantel ohne die disziplinierten Soldaten oder überschüssigen Wachen dasteht, die für eine sichere Eskortmission durch feindliches Gebiet erforderlich wären. Die Aufgabe fähigen, unabhängigen Abenteurern anzuvertrauen, ist seine einzige praktische Option.",al={"warum keine milizwachen schicken","warum den verräter eskortieren","warum braucht euch starkmantel"}}},fp="22,206,20.335.0,26.377.1,26.261.0,32.143.0,49.224.0,38.270.0,44.197.1,47.210.0"}
P.entries["quest:156"] = {n="Das Sammeln von Faulblüten",s="Im Dämmerwald braucht Schankwart Smitts Faulblüten für seinen Zombie Juice. Sie wachsen in den Schädeln von Skeletthorrors und Skelettschrecknissen auf den Friedhöfen.",h="Im Dämmerwald braucht Schankwart Smitts Faulblüten für seinen Zombie Juice.",kw={"dunkelhain","night watch","friedhof von rabenflucht","faulblüte","skelettschrecknis","skeletthorror","schankwart smitts","der friedhof \"stille gärten\"","zombie juice"},ang={["faction:Alliance"]="Als Abenteurer der Allianz erleichtert Ihr den täglichen Kampf der Nachtwache, indem Ihr auf den Friedhöfen des Dämmerwalds Untote jagt und helft, Dunkelhains Fall zu verhindern.",["profession:Herbalism"]="Faulblüten sind finstere Gewächse, die in nekromantischer Verwesung und belebten Knochen wurzeln. Gewöhnliche Kräuter gedeihen in nährstoffreicher Erde und im Sonnenlicht."},sec={{t="Eine bizarre Zutat",b="In der Scarlet Raven Tavern braut Schankwart Smitts manchmal ein seltsames Getränk. Sein Zombie Juice verlangt nach Faulblüten, die in den leeren Schädeln belebter Skelette wurzeln. Smitts meidet die Untoten, daher sammeln durchreisende Söldner die Blüten für ihn."},{t="Schädlingsbekämpfung auf dem Friedhof",b="Faulblüten wachsen auf Skeletthorrors und Skelettschrecknissen in den überwucherten Grabfeldern des Friedhofs \"Stille Gärten\" und des Friedhofs von Rabenflucht. Die Miliz der Nachtwache ist im Kampf gegen die Schrecken, die durch die Wälder schleichen, überlastet. Smitts lobt jene, die die Toten jagen, bei Kommandantin Althea Schwarzhaupt und hilft so, die rastlosen Reihen auszudünnen, die Dunkelhain bedrohen."}},faq={{q="Was ist eine Faulblüte?",a="Faulblüten sind widerliche Pflanzen, die inmitten dunkler Magie und Verwesung wachsen. Im Dämmerwald sprießen sie in den Schädeln belebter Skeletthorrors und Skelettschrecknisse.",al={"faulblüte","was ist eine faulblüte","woher kommen faulblüten"}},{q="Warum braucht Schankwart Smitts Faulblüten?",a="Schankwart Smitts verwendet Faulblüten, um Zombie Juice zu brauen, ein Getränk, das bestimmte Gäste in der Region verlangen.",al={"warum will smitts blüten","zombie juice zutaten","smitts getränk"}},{q="Wo findet man die Skelette, die diese Blüten tragen?",a="Skeletthorrors und Skelettschrecknisse, die Faulblüten tragen, suchen die Begräbnisstätten des Dämmerwalds heim. Man findet sie besonders auf dem Friedhof \"Stille Gärten\" nahe Dunkelhain und dem Friedhof von Rabenflucht im Westen.",al={"wo sind skeletthorrors","faulblüte fundort","friedhof stille gärten skelette"}},{q="Hilft diese Aufgabe bei der Verteidigung von Dunkelhain?",a="Ja. Dunkelhain verlässt sich bei den ständigen Angriffen der Untoten auf die Nachtwache. Die Jagd auf Skelette wegen ihrer Blüten verringert die Zahl der Monster, die den Ort bedrohen, und hilft Kommandantin Althea Schwarzhaupt.",al={"night watch helfen","althea schwarzhaupt skelette töten"}},{q="Was folgt nach der Abgabe der Blüten?",a="Nachdem Smitts die Blüten erhalten und den Zombie Juice gebraut hat, bittet er Euch, den Trank zu Calvinius zu bringen, einem exzentrischen Einsiedler nahe dem Friedhof von Rabenflucht.",al={"nächste quest nach faulblüten","juice delivery folgequest"}},{q="Ist Zombie Juice ein gewöhnliches Getränk, das in Dunkelhain ausgeschenkt wird?",a="Nein. Die Scarlet Raven Tavern serviert gewöhnlich regionale Kost. Smitts bereitet Zombie Juice, ein seltsames Gebräu mit nekrotischen Zutaten, nur auf eine ausgefallene Bestellung hin zu.",al={"ist zombie juice normal","scarlet raven getränke"}}},fx={["1d59b9b9"]={q="Was hat es mit den Skeletten auf sich, die Fäulnisblüten tragen?",a="Ihr werdet gegen die Skelettschrecken und Skelettunholde ausgesandt, die die Friedhöfe des Dämmerwalds befallen, insbesondere den Friedhof \"Stille Gärten\" und Raven Hill. Diese untoten Monstrositäten erheben sich aus gestörten Gräbern in den schattigen Wäldern und beherbergen seltsame, nekrotische Fäulnisblüten direkt in ihren Schädelhöhlen.",al={"skelettschrecken dämmerwald","skelettunholde stille gärten","welche skelette lassen fäulnisblüten fallen"}},["1e6a32cf"]={q="Warum schickt Euch Schankwart Smitts und nicht The Nachtwache?",a="Smitts betreibt die Scarlet Raven Tavern und gibt zu, dass er es nie gewagt hat, nah genug heranzugehen, um ein lebendes Skelett zu untersuchen. Unterdessen ist The Nachtwache gefährlich dünn besetzt, um Dunkelhain von allen Seiten vor Unholden zu verteidigen. Ein fähiger Abenteurer, der in der Nähe der Friedhöfe jagt, entlastet die örtliche Wache, damit diese die Stadtgrenzen bewachen kann.",al={"warum tötet night watch keine skelette","warum schickt smitts mich","warum braucht euch schankwart smitts"}}},fp="19,149,20.256.0,22.343.0,22.149.0,45.109.0,56.190.0,45.188.0,46.159.1,54.172.0"}
P.entries["quest:1560"] = {n="Toogas Bitte",s="In Tanaris versucht Ihr mit Tooga, Torta zu erreichen. Sie wartet etwas südlich des Dampfdruckpiers.",h="In Tanaris versucht Ihr mit Tooga, Torta zu erreichen.",kw={"dampfdruckpier","tanaris","disteltal","tooga","torta","schildkröte"},sec={{t="Ein verirrter Wanderer",b="Tooga wandert bei einem abgestürzten Goblin-Zeppelin nahe dem Disteltal umher und weiß den Heimweg nicht. Seine Frau Torta hat ihn losgeschickt, um das Abendessen zu besorgen. Er ist falsch abgebogen und hat sich verirrt, also bittet er Euch, ihn zu ihr zurückzuführen."},{t="Quer durch die Zone",b="Torta wartet etwas südlich des Dampfdruckpiers, von Tooga aus quer durch Tanaris. Um sie zu erreichen, muss er fast die gesamte Breite der Zone zu Fuß durchqueren."},{t="Der Empfang seiner Frau",b="Torta ist nicht überrascht, dass Tooga den Heimweg nicht allein finden konnte. Sie sagt ihm, er solle ins Meer gehen und etwas zu essen mitbringen."}},faq={{q="Wer ist Tooga?",a="Tooga ist eine verirrte Schildkröte in Tanaris, die Hilfe braucht, um den Weg zurück zu ihrer Frau zu finden.",al={"wer ist tooga","tooga schildkröte","wer ist die schildkröte in tanaris"}},{q="Wer ist Torta?",a="Torta ist Toogas Frau und wartet etwas südlich des Dampfdruckpiers.",al={"wer ist torta","wo ist torta","torta fundort"}},{q="Warum hat sich Tooga in der Wüste verirrt?",a="Torta schickte Tooga los, um das Abendessen zu besorgen, doch er bog falsch ab und verirrte sich.",al={"warum hat sich tooga verirrt","was ist tooga passiert","tooga hintergrundgeschichte"}},{q="Wo ist Tooga anfangs zu finden?",a="Tooga ist bei einem abgestürzten Goblin-Zeppelin nahe dem Disteltal in Tanaris zu finden.",al={"tooga startort","wo beginnt toogas bitte","tooga finden"}}},fp="13,95,15.203.0,15.134.0,16.124.1,13.82.0,13.63.0,32.65.0,32.80.0"}
P.entries["quest:157"] = {n="Abliefern des Fadens",s="In Dunkelhain schickt Madame Eva Geisterhaarfaden westwärts durch den Dämmerwald zu Calvinius nahe dem Friedhof von Rabenflucht. Der Einsiedler sagt, er brauche ihn, um seine Hütte vor rastlosen Geistern zu schützen.",h="In Dunkelhain schickt Madame Eva Geisterhaarfaden westwärts durch den Dämmerwald zu Calvinius nahe dem...",kw={"calvinius","dunkelhain","abliefern des fadens","dämmerwald","geisterhaarfaden","madame eva","rabenflucht","friedhof von rabenflucht","zombie juice"},ang={["class:Priest"]="Als Priester würdet Ihr gewöhnlich auf heilige Riten des Lichts zurückgreifen, um ein Heim vor rastlosen Toten zu schützen. Dass Calvinius auf verwobene Überreste der Toten vertraut, deutet auf einen dunkleren Weg hin.",["faction:Alliance"]="Als Reisender der Allianz helft Ihr, Unterstützung aus Dunkelhain durch die gefährlichen westlichen Wälder zu einem abgeschieden lebenden Einsiedler zu bringen, während die Nachtwache mit Mühe die Grenze bewacht.",["profession:Tailoring"]="Geisterhaftes Haar zu brauchbaren Spulen zu verspinnen, verbindet Nähkunst mit volkstümlicher Nekromantie. Der Faden kann Materie jenseits der körperlichen Welt zusammennähen."},sec={{t="Ein Weg durch die Dunkelheit",b="Madame Eva gibt Euch eine Spule Geisterhaarfaden, gesponnen aus Haaren, die vom Geist der blinden Mary gesammelt wurden. Ihr tragt sie westwärts durch den Dämmerwald, wo Spinnen und Untote umherstreifen. Calvinius wartet in seiner baufälligen Hütte direkt nördlich des Friedhofs von Rabenflucht."},{t="Fäden von Leben und Tod",b="Calvinius sagt, er werde seine Fenster und den Türrahmen mit dem geisterhaften Faden auskleiden, um die klagenden Toten von Rabenflucht fernzuhalten. Madame Eva sagt, Geisterhaarfaden könne bösartige Geister binden und toter wie unbelebter Materie den Anschein von Leben einnähen. Calvinius nimmt die Spule mit Freude entgegen und setzt dann sein verborgenes Handwerk in Gang."}},faq={{q="Was ist Geisterhaarfaden?",a="Geisterhaarfaden ist eine verzauberte Spule, die Madame Eva in Dunkelhain aus Haaren spinnt, die vom Geist der blinden Mary gesammelt wurden. Sie sagt, er könne Geister binden oder unbelebten Gegenständen Leben einnähen.",al={"geisterhaar","was ist der faden","geisterfaden"}},{q="Wer ist Calvinius?",a="Calvinius ist ein zurückgezogen lebender alter Mann in einer einsamen Hütte direkt nördlich des Friedhofs von Rabenflucht. Er wirkt gebrechlich und harmlos und sagt, er fürchte die Untoten nahe seinem Heim.",al={"einsiedler","wer ist calvinius","kerl in der hütte"}},{q="Warum behauptet Calvinius, den Faden zu brauchen?",a="Calvinius sagt, er werde Geisterhaarfaden entlang seiner Fenster und Türöffnungen spannen, um die im Dämmerwald umherstreifenden Ghule und Geister abzuwehren.",al={"warum der faden","calvinius' ausrede","geister abwehren"}},{q="Wo befindet sich Calvinius?",a="Calvinius lebt in einer abgelegenen Holzhütte nördlich des Hauptgeländes des Friedhofs von Rabenflucht, unweit der westlichen Straße durch den Dämmerwald.",al={"calvinius' standort","wo ist die hütte","einsiedlerhütte"}},{q="Was geschieht, nachdem Ihr Calvinius den Faden gegeben habt?",a="Nachdem Calvinius den Faden erhalten hat, belohnt er Euch und klagt über weitere dringende Bedürfnisse. Er schickt Reisende los, um seltsame alchemistische Zutaten wie Zombie Juice zu beschaffen.",al={"nächste quest","was kommt danach","nach dem abliefern des fadens"}},{q="Weiß Madame Eva, was Calvinius vorhat?",a="Madame Eva wirft Calvinius keine finsteren Machenschaften vor. Sie bemerkt, dass Geisterhaarfaden unbelebten Gegenständen Leben einnähen könne, und zeigt damit, dass sie sein nekromantisches Potenzial kennt, erfüllt die Bitte jedoch ohne Widerspruch.",al={"weiß eva davon","madame eva mitschuldig","evas warnung"}}},fx={["011e87a7"]={q="Warum möchte Madame Eva, dass der Geisterhaarfaden an Calvinius geliefert wird?",a="Madame Eva erfüllt ihren Teil einer Abmachung. Calvinius bat um Geisterhaarfaden, um seine Einsiedelei gegen die ruhelosen Toten zu schützen, und Eva stimmte zu, ihn zu spinnen, sobald Ihr ihr das Geisterhaar der blinden Mary gebracht habt. Da sie ihn lediglich für einen gebrechlichen, exzentrischen Einsiedler hält, der versucht, die Schrecken bei Raven Hill zu überleben, vertraut sie Euch damit, die fertige Spule sicher zu seiner Tür zu bringen.",al={"warum hilft madame eva calvinius","beweggrund madame eva","warum den faden liefern"}}},fp="18,179,22.245.0,25.326.1,26.180.0,19.162.0,47.133.0,29.134.0,52.166.0,47.215.0"}
P.entries["quest:1578"] = {n="Nachschub für die Front",s="In Loch Modan brauchen die Mountaineers neue Waffen, da Trogg-Angriffe ihre Verteidigung bedrohen. Tormus Tiefenschmied schickt Schmiedelehrlinge nach Osten, um sie zu versorgen.",h="In Loch Modan brauchen die Mountaineers neue Waffen, da Trogg-Angriffe ihre Verteidigung bedrohen.",kw={"schmiedekunst","kupferaxt","kupferkettengürtel","eisenschmiede","loch modan","nachschub für die front","thelsamar","thorvald tiefenschmied","tormus tiefenschmied","troggs"},ang={["faction:Alliance"]="Als Mitglied der Allianz helft Ihr, die Grenzstraßen von Khaz Modan zwischen Eisenschmiede, Sturmwind und den Einsätzen der Allianz im Süden zu sichern.",["profession:Blacksmithing"]="Als Schmied beweist Ihr Euer Können, indem Ihr zuverlässige Kupferwaffen und Rüstungen für den militärischen Einsatz herstellt.",["race:Dwarf"]="Als Zwerg helft Ihr mit Eurem Handwerk, Loch Modan zu verteidigen, an der Seite der Mountaineers mit ihren Gewehren."},sec={{t="Waffen für die Mountaineers",b="Ausgrabungen haben jenseits der Grenze Ruinen und Höhlen freigelegt. Troggs greifen die Mountaineers nun ohne Vorwarnung an. Ihre Verteidigungslinien brauchen neue Klingen, Gürtel und Beschläge, um den Angriffen standzuhalten."},{t="Die Verwandtschaft der Tiefenschmieds",b="Tormus schickt Lehrlinge nach Osten, während erfahrene Schmiede an den städtischen Schmieden von Eisenschmiede bleiben. Sein Kollege Thorvald Tiefenschmied unterhält eine Feldwaffenkammer im südlichen Wachturm. Dort beweisen robuste Kupferäxte und Kupferkettengürtel die Zuverlässigkeit eines Schmieds und verschaffen ihm Zugang zu fortgeschrittenen Schmiedetechniken."}},faq={{q="Wer bietet diese Quest an und was wird benötigt?",a="Tormus Tiefenschmied, ein Schmied in der Großen Schmiede von Eisenschmiede, bietet diese Arbeit Schmiedelehrlingen mit einer Fertigkeit von mindestens dreißig an. Ihr müsst sechs Kupferäxte und sechs Kupferkettengürtel herstellen.",al={"wer vergibt nachschub für die front","questgeber","anforderungen der schmiedequest"}},{q="Wo befindet sich Thorvald Tiefenschmied?",a="Thorvald Tiefenschmied befindet sich im südlichen Wachturm von Loch Modan. Folgt der Hauptstraße nach Süden an Thelsamar vorbei in Richtung der Grenze zum Ödland. Der Turm steht neben dem Gebirgspass.",al={"wo ist thorvald","thorvalds standort","südlicher wachturm loch modan"}},{q="Warum brauchen die Mountaineers so viel Nachschub aus Kupfer?",a="Die Mountaineers in Loch Modan liefern sich ständig Scharmützel mit gewalttätigen Troggs. Im Kampf bekommt ihre Ausrüstung schnell Scharten, wird stumpf und zerbricht, weshalb sie stetigen Nachschub an einfachen Waffen und Kettenrüstungen brauchen.",al={"warum brauchen sie äxte","wofür ist das kupfer"}},{q="In welchem Verhältnis steht Thorvald zu Tormus?",a="Tormus bezeichnet Thorvald als seinen Kollegen. Sie tragen denselben Clannamen Tiefenschmied und verbinden die Schmiedekraft von Eisenschmiede mit der Verteidigung vor Ort.",al={"sind thorvald und tormus verwandt","tormus kollege"}},{q="Welche Belohnung bietet Thorvald an?",a="Thorvald bietet Pläne für neue Rüstungen als Dank dafür an, dass Ihr die Versorgungsengpässe am südlichen Wachturm lindert.",al={"questbelohnung","was lehrt thorvald"}},{q="Warum sind die Troggs gerade jetzt ein solches Problem in Loch Modan?",a="Zwergische Ausgrabungen haben in ganz Khaz Modan unterirdische Gewölbe und Hohlräume geöffnet. Die Arbeiten haben versehentlich Scharen aggressiver Troggs geweckt und freigelegt. Sie bedrohen nun nahe gelegene Siedlungen und Wachtürme.",al={"warum greifen troggs an","troggproblem loch modan"}}},fx={["0062256f"]={q="Warum braucht Tormus Tiefenschmied mehr Kupferäxte?",a="Die Bergsteiger aus Eisenschmiede, die in Loch Modan kämpfen, sind in ununterbrochene Scharmützel gegen die Troggs verwickelt. Waffen zerbrechen im ständigen Kampf schnell, und Thorvald Tiefenschmied benötigt dringend frische Bewaffnung, um sicherzustellen, dass die Verteidiger ihre Frontlinie halten können.",al={"wofür sind kupferäxte","kupferaxt verwendung frontversorgung","warum kupferäxte"}},c19cb0c2={q="Warum benötigt Thorvald Kupferkettenbänder?",a="Trogg-Angriffe sind brutal und unerbittlich und nutzen die Schutzausrüstung der Bergsteiger so schnell ab, wie sie sie reparieren können. Thorvald verlässt sich auf stetige Lieferungen haltbarer Rüstungsteile wie Kupferkettenbänder, um die zwergischen Wachen in den südlichen Pässen angemessen geschützt zu halten.",al={"wofür sind kupferkettenbänder","verwendung kupferkettenband","warum kupferkettenbänder"}},f96d051f={q="Warum bittet Tormus Tiefenschmied einen Abenteurer, bei der Versorgung der Front zu helfen?",a="Thorvald ist überlastet mit den Reparaturen an der Front, und Tormus kann seinen eigenen Amboss in Eisenschmiede nicht verlassen. Als angehender Schmied testet das Schmieden der Ausrüstung und das Tragen nach Osten durch die Tunnel Euer Handwerk, während es gleichzeitig die Bergwache direkt entlastet.",al={"warum ich frontversorgung","warum braucht tormus mich","warum einen abenteurer zu thorvald schicken"}}},fp="19,147,23.192.0,21.286.0,43.193.0,36.178.0,53.197.0,36.131.0,40.103.0,57.210.0"}
P.entries["quest:1579"] = {n="Klemmmuffen",s="Bei Auberdine braucht Hexknall Kurbeldreh seine verlorenen Klemmmuffen. Auf seiner Überfahrt von Eisenschmiede verlor er eine Kiste mit Bauteilen über Bord, und die Teile liegen irgendwo an der Küste der Dunkelküste.",h="Bei Auberdine braucht Hexknall Kurbeldreh seine verlorenen Klemmmuffen.",kw={"auberdine","dunkelküste","electropellers","angeln","klemmmuffen","eisenschmiede","stintle pegs","hexknall kurbeldreh"},ang={["profession:Engineering"]="Als Ingenieur wisst Ihr, wie sehr es einen zur Verzweiflung treibt, wenn ein einziges ungewöhnliches Teil fehlt, das zum Kalibrieren eines empfindlichen Geräts nötig ist.",["race:Gnome"]="Als Gnom kennt Ihr die rastlose Eigenwilligkeit der Tüftler. Hexknalls empfindliche Bauteile und sein übermäßiger Alkoholkonsum könnten selbst Euch zusammenzucken lassen.",["race:NightElf"]="Als Nachtelf wisst Ihr, dass die Wälder der Dunkelküste still und heilig sind. Ein lauter Gnomerfinder mit einem Kater ist für Auberdines Schildwachen ein seltsamer Anblick."},sec={{t="Ein wirrer Geist im stillen Hafen",b="Hexknall Kurbeldreh überquerte von Eisenschmiede aus das große Meer, um an der Dunkelküste Ruhe zu finden. Der Gnomerfinder trank auf der Überfahrt zu viel. Im Rausch lehnte er sich über die Reling und verlor nahe Auberdine eine Kiste mit speziellen Metallteilen, den sogenannten Klemmmuffen, im Wasser."},{t="Die Stintle Pegs justieren",b="Hexknall sagt, Klemmmuffen seien unverzichtbare Präzisionswerkzeuge. Ohne sie kann er weder seine Stintle Pegs justieren noch seine filigranen Tüfteleien fortsetzen. Er will nicht selbst in die kalte Brandung waten, also bittet er einheimische Angler, am Ufer der Dunkelküste ihre Leinen auszuwerfen und die verstreuten Teile herauszufischen."}},faq={{q="Was sind Klemmmuffen?",a="Klemmmuffen sind kleine gnomische Befestigungselemente und mechanische Bauteile. Hexknall Kurbeldreh braucht sie, um seine Stintle Pegs zu justieren.",al={"was ist eine klemmmuffe","klemmmuffen verwendung","klemmmuffen gegenstand"}},{q="Wie sind die Klemmmuffen ins Meer geraten?",a="Hexknall Kurbeldreh trank während seiner Überfahrt von den Östlichen Königreichen nach Kalimdor zu viel. Betrunken ließ er an Bord seine Vorratskiste nahe der Dunkelküste über Bord fallen.",al={"wie hat er sie verloren","warum sind sie im wasser","warum nach klemmmuffen angeln"}},{q="Warum ist Hexknall Kurbeldreh in Auberdine statt in Eisenschmiede?",a="Hexknall ging wegen der Ruhe nach Auberdine. Das ständige Scheppern und die lauten Werkstätten von Eisenschmiede zehrten an seinen Nerven, besonders wenn er seinen Kater auskurierte.",al={"warum ist hexknall in auberdine","warum hat hexknall eisenschmiede verlassen"}},{q="Wo lassen sich die verlorenen Klemmmuffen herausfischen?",a="Angler können Klemmmuffen im offenen Salzwasser an der Dunkelküste nahe Auberdine angeln. Sie können beim gewöhnlichen Auswerfen anbeißen, nicht nur an Fischschwärmen.",al={"wo klemmmuffen angeln","klemmmuffen fundort"}},{q="Was geschieht nach der Bergung der Klemmmuffen?",a="Nachdem Hexknall seine Klemmmuffen zurückbekommen hat, um seine Stintle Pegs zu justieren, erzählt er, dass er auch seine electropellers in den Flüssen und Seen der Dunkelküste verloren hat. Auch die müssen herausgefischt werden.",al={"was kommt nach den klemmmuffen","quest nach den klemmmuffen"}},{q="Warum braucht Hexknall Abenteurer, statt die Teile selbst zu bergen?",a="Hexknall hat einen dröhnenden Kater und keine Ausrüstung zum Meeresangeln. Er bleibt auf den Stegen von Auberdine im Trockenen und überlässt das Herausfischen jedem, der eine Angelrute hat.",al={"warum kann hexknall sie nicht holen","warum angelt hexknall nicht"}}},fx={bd1e627b={q="Warum möchte Hexknall Kurbeldreh, dass die Klemmmuffen geborgen werden?",a="Hexknall Kurbeldreh reiste den ganzen Weg von Eisenschmiede zur Dunkelküste, auf der Suche nach Ruhe und Frieden, um an seinen Erfindungen zu arbeiten. Leider ließen seine ungeschickten, betrunkenen Missgeschicke auf der Reise seine wesentlichen Vorräte auf dem Meeresgrund landen. Ohne diese Klemmmuffen kommt seine tüftlerische Arbeit sofort zum Stillstand, da er ohne sie nicht einmal seine Stintle-Stifte justieren kann.",al={"warum braucht wizbang gaffer jacks","beweggrund von hexknall kurbeldreh","warum hexknall kurbeldreh helfen"}}},fp="12,183,33.269.0,23.273.0,22.124.0,43.162.0,61.144.0,45.150.0,47.159.1,69.147.0"}
P.entries["quest:158"] = {n="Zombiesaft",s="Calvinius schickt Reisende von seiner einsamen Hütte im Dämmerwald nach Dunkelhain, um Zombiesaft zu holen. Er sagt, die nächtliche Kälte lasse ihn frieren.",h="Calvinius schickt Reisende von seiner einsamen Hütte im Dämmerwald nach Dunkelhain, um Zombiesaft zu holen.",kw={"calvinius","dunkelhain","dämmerwald","schnaps","scarlet raven tavern","schankwart smitts","zombiesaft"},ang={["faction:Alliance"]="Als Abenteurer der Allianz überbringt Ihr womöglich Nachrichten für die eigenwilligen Einsiedler entlang der gefährlichen Straßen des Dämmerwalds und unterstützt dabei Dunkelhains bedrängten Außenposten."},sec={{t="Eine frostige Bitte",b="Calvinius lebt allein inmitten der Schrecken der schattigen Wälder des Dämmerwalds und schickt Reisende oft auf seltsame Botengänge. Er sagt, die schleichende Dämmerung raube ihm Wärme und Lebenskraft, und bittet Euch dann, nach Osten nach Dunkelhain zu reisen. In der Scarlet Raven Tavern verkauft Schankwart Smitts das starke Getränk, das Calvinius sucht. Sein unheilvoller Name lautet Zombiesaft, und Calvinius sagt, es werde wieder Feuer in seine Adern bringen."},{t="Im Scarlet Raven",b="Schankwart Smitts bewirtet müde Wachen und verängstigte Stadtbewohner in Dunkelhains Taverne, doch nur wenige verlangen nach Zombiesaft. Das Getränk ist für seine gefährliche Stärke bekannt, und Smitts erkennt den Jahrgang. Calvinius' Vorliebe für ein derart morbides Gebräu sorgt in einer von rastlosen Toten belagerten Region für leises Stirnrunzeln."}},faq={{q="Was ist Zombiesaft?",a="Zombiesaft ist ein außergewöhnlich starker Schnaps mit einem morbiden Namen, den Schankwart Smitts in der Scarlet Raven Tavern in Dunkelhain verkauft. Gewöhnliche Gäste verlangen nur selten danach.",al={"zombiesaft getränk","was ist der schnaps","zombiesaft hintergrundgeschichte"}},{q="Wer schickt Euch los, um Zombiesaft zu holen?",a="Der Einsiedler Calvinius schickt Euch los, um Zombiesaft zu holen. Er lebt allein in einer Hütte im westlichen Dämmerwald und sagt, das Getränk werde seine kalten Knochen wärmen.",al={"wer gibt die quest zombiesaft","calvinius quest getränk","einsiedler bitte um getränk"}},{q="Wo gebt Ihr die Quest ab?",a="Ihr sprecht mit Schankwart Smitts in der Scarlet Raven Tavern, Dunkelhains zentralem Gasthaus im östlichen Dämmerwald.",al={"wo ist smitts","zombiesaft abgeben","smitts standort"}},{q="Warum will Calvinius ihn haben?",a="Calvinius sagt, die düsteren, schattigen Nächte des Dämmerwalds ließen ihn zittern, und er brauche das feurige Getränk, um sein Blut zu wärmen.",al={"warum braucht calvinius saft","calvinius kälte","warum trinkt er zombiesaft"}},{q="Ist Schankwart Smitts über die Bestellung überrascht?",a="Ja. Smitts sagt, Zombiesaft sei außerordentlich stark, und seine Stammgäste verlangten nur selten danach.",al={"smitts reaktion","hat smitts zombiesaft","smitts dialog"}},{q="Müsst Ihr bei dieser Quest gegen Monster kämpfen?",a="Nein. Ihr folgt der Straße von Calvinius' abgelegener Hütte nach Dunkelhain und sprecht mit Schankwart Smitts. Auf den Straßen des Dämmerwalds lauern allerdings auch umherstreifende Bestien und Untote.",al={"zombiesaft kampf","ist zombiesaft gefährlich","zombiesaft monster"}}},fx={aa8c42e6={q="Warum braucht Calvinius Euch, um den Zombie Juice zu besorgen?",a="Calvinius lebt als gebrechlicher, einsamer Eremit, abgeschieden in den düsteren, verfluchten Wäldern bei Raven Hill. Das Reisen über die von Kreaturen verseuchten Straßen des Dämmerwalds bis hin nach Dunkelhain, nur um die Scarlet Raven Tavern zu besuchen, ist für einen alten Einsiedler viel zu gefährlich, besonders wenn fähige Abenteurer wie Ihr bereit sind, seine Besorgungen zu machen.",al={"warum kann calvinius es nicht holen","warum ich zombie juice","warum schickt man mich für zombie juice"}}},fp="12,137,16.399.0,20.309.0,21.170.0,36.146.0,31.112.0,29.122.0,44.101.0,46.180.0"}
P.entries["quest:1580"] = {n="Elektropeller",s="In der Dunkelküste will Hexknall Kurbeldreh seine verlorenen Electropellers zurück. Ein Missgeschick mit einer explosiven Lockente verstreute die Prototypbauteile in Süßwasserläufen.",h="In der Dunkelküste will Hexknall Kurbeldreh seine verlorenen Electropellers zurück.",kw={"auberdine","der klippenquell","dunkelküste","lockente","electropellers","angeln","der wildbend","hexknall kurbeldreh"},ang={["profession:Engineering"]="Als Ingenieur könnt Ihr Electropellers als kuriose Beispiele für miniaturisierte gnomische Antriebstechnik betrachten. Sie treiben mechanische Lockvögel an, bevor sie heftig in Flammen aufgehen.",["race:Gnome"]="Als Gnom erkennt Ihr vielleicht Hexknalls chaotischen Ehrgeiz wieder, explodierende Lockenten zu bauen. Teure Bauteile in einem von Elfen bewachten Fluss zu verlieren, ist peinlich.",["race:NightElf"]="Als Nachtelf mögt Ihr Hexknalls laute, qualmende Erfindungen und seine Missgeschicke, die Flüsse vermüllen, mit stiller Missbilligung betrachten. Die Bäche der Dunkelküste sollten naturbelassen bleiben."},sec={{t="Eine beschwipste Erfindung",b="Hexknall Kurbeldreh ging eines Abends ins Landesinnere, um einen Ort zum Testen seiner neuesten Erfindung zu finden. Der in Auberdine ansässige Gnomen-Tüftler hatte eine selbstfahrende Lockente gebaut, die explodiert. Er trank zu viel und hatte einen Filmriss. Stunden später erwachte er mit angesengtem Haar und leerem Rucksack in der Stadt; seine Tasche voller Electropellers war in einen der Küstenflüsse gefallen."},{t="Die Gewässer durchkämmen",b="Hexknall bittet einheimische Fischer, die Süßwasserläufe der Dunkelküste abzusuchen, denn selbst will er sich nicht in die Wildnis wagen. Angler am Wildbend und am Klippenquell können neben einheimischen Fischen auch die schwimmfähigen Metallteile an den Haken bekommen. Sobald die Bauteile zurück sind, kann Hexknall seine unberechenbaren Experimente mit Wasservögeln fortsetzen."}},faq={{q="Wo finde ich die Electropellers?",a="Angelt in den Süßwasserflüssen und Seen der Dunkelküste, darunter im Klippenquell und im Wildbend. Die Electropellers befinden sich nicht im Meer entlang der Küste.",al={"wo sind electropellers","wie bekommt man electropellers","electropellers fundort"}},{q="Wer ist Hexknall Kurbeldreh?",a="Hexknall Kurbeldreh ist ein exzentrischer Gnomeningenieur, der in Auberdine lebt. Er baut bizarre, explosive Erfindungen und verlässt sich auf Reisende, die verlorene Bauteile und Kuriositäten für seine Experimente sammeln.",al={"wer vergibt electropellers","hexknall kurbeldreh"}},{q="Was wollte Hexknall bauen?",a="Hexknall baute eine selbstfahrende Lockente, die explodiert. Nachdem er zu viel getrunken hatte, brachte er versehentlich einen frühen Prototyp zur Explosion, versengte sich das Haar und verlor seine Tasche voller Bauteile im Wasser.",al={"explodierende lockente","hexknalls projekt"}},{q="Kann man Electropellers in Fischschwärmen finden?",a="Nein. Electropellers erhaltet Ihr beim Angeln im offenen Süßwasser, nicht aus besonderen Fischschwärmen wie Lesser Oily Blackmouth.",al={"fischschwärme electropellers","in fischschwärmen angeln möglich"}},{q="Was kommt vor dieser Quest?",a="Schließt zuerst Klemmmuffen ab. Hexknall vergibt diese Quest zuvor, um Euer Anglerglück in den örtlichen Gewässern zu prüfen.",al={"vorquest für electropellers","electropellers voraussetzung"}},{q="Lassen Monster Electropellers fallen?",a="Nein. Weder Gegner noch Behälter am Boden liefern Electropellers. Holt sie mit einer Angel aus den Flüssen.",al={"lassen monster electropellers fallen","wer lässt electropellers fallen"}}},fx={d23bdc75={q="Warum bittet Euch Wizbang, die Electropellers zu angeln, anstatt es selbst zu tun?",a="Wizbang hat bereits Beweise für Euer unheimliches Glück und Euer anglerisches Können gesehen, als Ihr zuvor Klemmmuffen für ihn herausgefischt habt. Nachdem er sich in Auberdine von seinem alkoholbedingten Missgeschick erholt hat, orientierungslos und versengt, verlässt er sich lieber auf einen bewährten Angler, anstatt die Wildnis der Dunkelküste selbst zu durchsuchen.",al={"warum ich wizbang","warum angelt wizbang sie nicht selbst"}},["42aa198c"]={q="Warum möchte Hexknall Kurbeldreh, dass Ihr die Electropellers bergt?",a="Hexknall Kurbeldreh verlor seine gesamte Tasche mit Komponenten während eines betrunkenen Missgeschicks beim Testen von Erfindungen entlang der Wasserwege der Dunkelküste. Er wachte zurück in Auberdine mit versengtem Haar und einem leeren Rucksack auf. Ohne diese fehlenden Teile ist seine laufende Ingenieursforschung an selbstfahrenden, explodierenden Entenattrappen komplett zum Stillstand gekommen.",al={"warum braucht wizbang electropellers","beweggrund wizbang","warum electropellers holen"}},c9029636={q="Wozu wird ein Elektropeller verwendet?",a="Electropellers sind spezialisierte mechanische Komponenten, die Hexknall Kurbeldreh für den Antrieb entwickelt hat. Insbesondere dienen sie als Antriebsmechanismus in seiner Prototyp-selbstfahrenden, explodierenden Entenattrappe und ermöglichen es der mechanischen Attrappe, durch Gewässer zu steuern und zu fahren, bevor ihre flüchtige Ladung detoniert.",al={"was sind electropellers","electropeller verwendung","zweck electropeller"}}},fp="14,160,17.351.0,19.303.0,35.157.0,27.199.0,33.195.0,44.109.0,29.102.0,39.109.0"}
P.entries["quest:1581"] = {n="Elixiere für die Messerblatts",s="In Dolanaar sucht Syral Messerblatt Hilfe für das florierende Geschäft ihrer Familie. Ihr Mann verbringt fast seine ganze Zeit mit dem Brauen, und frische Elixiere könnten ihn entlasten und ihm zugleich ungewöhnliche Kräuter einbringen.",h="In Dolanaar sucht Syral Messerblatt Hilfe für das florierende Geschäft ihrer Familie.",kw={"alchemie","dolanaar","earthroot","elixier der löwenstärke","elixier der geringen verteidigung","elixiere für die messerblatts","silverleaf","syral messerblatt","teldrassil"},ang={["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr helfen, Dolanaar mit stärkenden und schützenden Tränken für Verteidiger und durchreisende Verbündete zu versorgen, die Gefahren im Wald begegnen.",["profession:Herbalism"]="Auf Teldrassils fruchtbarem Boden gedeihen Silverleaf und Earthroot, sodass Ihr die Kräuter für Syrals Ladenauftrag sammeln könnt.",["race:NightElf"]="Als Nachtelf wisst Ihr, dass der Handel der Messerblatts zum Leben in Dolanaar unter Teldrassils Blätterdach gehört."},sec={{t="Die Last des Wohlstands",b="Reisende, Schildwachen und Druiden kommen auf ihrem Weg durch Teldrassil nach Dolanaar. Syral Messerblatt und ihr Mann haben einen florierenden Kräuter- und Alchemiehandel aufgebaut, um sie zu versorgen. Die Nachfrage hält ihn fast jede wache Stunde an Phiolen und Kesseln beschäftigt. Die Arbeit lässt den beiden wenig Zeit füreinander."},{t="Ein Handel unter Händlern",b="Syral bittet durchreisende Kräuterkundige und Brauer, ihrem Mann etwas Arbeit abzunehmen. Sie sucht Elixiere der Löwenstärke und der geringen Verteidigung und bietet im Tausch frisch gesammelte, ungewöhnliche Kräuter an. Für einen angehenden Alchemisten unter dem Weltenbaum bringt der Handel ein Bündel Kräuter und die Gelegenheit, gewöhnliche Waldpflanzen in begehrte Waren für die Einheimischen zu verwandeln."}},faq={{q="Warum braucht Syral Messerblatt diese Tränke?",a="Syral Messerblatts Familiengeschäft in Dolanaar läuft gut, und ihr Mann verbringt fast seine ganze Zeit mit dem Brauen, um die Nachfrage zu decken. Wenn ein anderer Brauer die Elixiere herstellt, verschafft ihm das eine dringend benötigte Pause.",al={"warum elixiere benötigt","syral messerblatts beweggrund","problem im laden der messerblatts"}},{q="Welche Tränke werden für die Aufgabe benötigt?",a="Syral bittet um sechs Elixiere der Löwenstärke und zwei Elixiere der geringen Verteidigung. Abenteurer und örtliche Schildwachen in Teldrassil kaufen häufig beide Sorten.",al={"welche elixiere","was zum brauen benötigt wird","benötigte tränke"}},{q="Welche Kräuter werden zum Brauen der benötigten Elixiere gebraucht?",a="Für die Herstellung werden Silberblatt, Earthroot und gewöhnliche Crystal Vials benötigt. Silberblatt und Earthroot wachsen überall auf Teldrassils Waldboden.",al={"benötigte zutaten","materialien für elixiere","welche kräuter sammeln"}},{q="Wer kann diesen Auftrag übernehmen?",a="Syrals Auftrag richtet sich an Alchemisten mit grundlegenden Kenntnissen ihres Handwerks. Sie braucht zuverlässige, sorgfältig gemischte Heilmittel für ihren Laden.",al={"stufenanforderung","berufsvoraussetzung","kann jeder diese quest annehmen"}},{q="Was bietet Syral im Tausch für die Elixiere an?",a="Syral bietet im Tausch für die Elixiere ein Bündel frisch gesammelter, ungewöhnlicher Kräuter an. Sie sind entlang der Waldpfade Teldrassils nur schwer zu finden.",al={"hintergrund der belohnung","was gibt syral","belohnung für den handel mit den messerblatts"}},{q="Wo befindet sich Syral Messerblatt?",a="Syral Messerblatt steht vor dem nördlichen Gebäude Dolanaars, nahe der zentralen Straße durch das Walddorf.",al={"wo ist syral","messerblatts standort","wo abgeben"}}},fx={c3ad307f={q="Wozu dient das Elixier der Löwenstärke?",a="Das Elixier der Löwenstärke ist ein Grundnahrungsmittel unter Frontkämpfern und Alchemisten, das gebraut wurde, um die physische Macht eines jeden, der es trinkt, vorübergehend zu stärken. Syral Messerblatt lagert es in Dolanaar, um den ständigen Bedarf von Jägern, Wächtern und Reisenden zu decken, die sich auf die gefährliche Wildnis von Teldrassil vorbereiten.",al={"nutzung elixier der löwenstärke","warum elixier der löwenstärke","zweck elixier der löwenstärke"}},["34301f2f"]={q="Wozu dient das Elixier der kleinen Verteidigung?",a="Das Elixier der kleinen Verteidigung ist ein alchemistisches Gebräu, das dazu entwickelt wurde, die Haut zu härten und die natürliche Rüstung gegen physische Schläge zu stärken. Syral Messerblatt hält es in ihrem Laden bereit, um es an Beschützer und Abenteurer zu verkaufen, die beim Patrouillieren der Äste des großen Baumes einen zuverlässigen, grundlegenden Schutz benötigen.",al={"nutzung elixier der kleinen verteidigung","warum elixier der kleinen verteidigung","zweck elixier der kleinen verteidigung"}}},fp="26,197,22.281.0,19.336.0,44.192.0,39.147.0,51.136.0,31.122.0,50.146.0,33.108.0"}
P.entries["quest:1582"] = {n="Mondscheinweste",s="In Darnassus fertigt Lotherias Lederausrüstung für junge Abenteurer, die nach Kalimdor aufbrechen. Im Gegenzug für Lieferungen geprägter Lederwaren bietet sie ein nachtelfisches Schnittmuster an.",h="In Darnassus fertigt Lotherias Lederausrüstung für junge Abenteurer, die nach Kalimdor aufbrechen.",kw={"herstellung","darnassus","geprägtes leder","kaldorei","lederverarbeitung","lotherias","mondscheinweste","teldrassil"},ang={["faction:Alliance"]="Als Handwerker der Allianz helft Ihr dabei, neue Rekruten in Darnassus auszurüsten. Die Allianz hält einen unsicheren Stützpunkt im Norden Kalimdors, während die Gefahren der Wildnis und feindliche Bedrohungen zunehmen.",["race:NightElf"]="Als Nachtelf könnt Ihr in der Mondscheinweste die feine Lederarbeit Teldrassils erkennen. Sie bietet Kundschaftern und Schildwachen unter dem Blätterdach des Waldes Schutz und Beweglichkeit."},sec={{t="Ausrüstung für die Kaldorei",b="Die Lederverarbeiter von Darnassus statten Schildwachen und junge Kundschafter aus. Nachtelfen und verbündete Wanderer verlassen Teldrassil und ziehen in Kalimdors Wildnis, wo robuste Rüstung gefragt ist. Lotherias ist eine Meisterlederverarbeiterin, die sie mit Ausrüstung versorgt."},{t="Das Handwerk meistern",b="Lotherias bittet Lehrlinge, passende geprägte Handschuhe, Stiefel und Umhänge zu bringen, um ihr Können zu zeigen. Wer ihren Auftrag erfüllt, gewinnt ihr Vertrauen. Sie lehrt sie ein nachtelfisches Schnittmuster für eine Weste, die Schutz bietet und zugleich Bewegungsfreiheit gewährt."}},faq={{q="Wer ist Lotherias?",a="Lotherias ist eine nachtelfische Lederverarbeitungslehrerin in Darnassus. Sie lehrt das Handwerk und gibt anspruchsvolle Schnittmuster an Lederverarbeiter weiter, die ihr Können beweisen.",al={"lotherias darnassus","wer vergibt mondscheinweste"}},{q="Warum braucht Lotherias so viele Lederwaren?",a="Lotherias benötigt geprägte Lederausrüstung für junge Abenteurer, die sich auf Reisen über Darnassus hinaus vorbereiten. Sie bittet Lehrlinge, die üblichen Kleidungsstücke zu liefern.",al={"warum so viele stiefel nötig","warum geprägtes leder verarbeiten"}},{q="Was ist die Mondscheinweste?",a="Die Mondscheinweste ist ein Schnittmuster für eine Lederrüstung, das Lotherias Euch lehrt, nachdem Ihr bewiesen habt, dass Ihr geprägte Waren in größeren Mengen herstellen könnt.",al={"mondscheinweste rezept","was bekommt man"}},{q="Welche Materialien werden benötigt, um diese Aufgabe zu erfüllen?",a="Bringt Lotherias ein Paar Geprägte Lederhandschuhe, fünf Paar Geprägte Lederstiefel und fünf Embossed Leather Cloaks. Fertigt jedes Stück an und liefert es bei ihr ab.",al={"was wird benötigt","mondscheinweste gegenstände"}},{q="Können Lederverarbeiter der Horde dieses Schnittmuster hier erlernen?",a="Nein. Lotherias bildet Handwerker der Allianz in Darnassus aus. Lederverarbeiter der Horde brauchen eigene Lehrer in Kalimdor und den Östlichen Königreichen.",al={"kann die horde das machen","ist mondscheinweste nur für die allianz"}},{q="Erfordert diese Quest eine bestimmte Berufsfertigkeitsstufe?",a="Ja. Ihr benötigt eine Lederverarbeitungsfertigkeit von mindestens siebzig, bevor Lotherias Euch für geschickt genug hält, um ihren Auftrag und das Schnittmuster für die Weste zu erhalten.",al={"benötigte lederverarbeitungsstufe","wann ist mondscheinweste erhältlich"}}},fx={["304f0e76"]={q="Wozu dienen die Geprägten Lederhandschuhe?",a="Lotherias und die anderen Handwerker in Darnassus sind überlastet, da sie versuchen, die Welle junger Abenteurer auszustatten, die in die Wildnis aufbrechen. Sie bittet Euch, ein Paar Geprägte Lederhandschuhe herzustellen, um ihr zu helfen, ihre überquellenden Aufträge zu erfüllen, und testet dabei Euer Geschick für feine Details, bevor sie fortgeschrittene Techniken mit Euch teilt.",al={"warum geprägte lederhandschuhe","nutzung geprägte lederhandschuhe","lotherias handschuhe"}},["3d684782"]={q="Wozu dienen die Geprägten Lederstiefel?",a="Lotherias benötigt fünf Paar Geprägte Lederstiefel, um lokale Abenteurer zu versorgen, die sich auf gefährliche Expeditionen durch Kalimdor vorbereiten. Die Bereitstellung von robustem, zuverlässigem Schuhwerk in großen Mengen beweist Eure Beständigkeit als Lederverarbeiter und entlastet die geschäftigen Handwerkswerkstätten von Darnassus.",al={"warum geprägte lederstiefel","nutzung geprägte lederstiefel","lotherias stiefel"}},["83a79481"]={q="Wozu dient der Geprägte Lederumhang?",a="Die fünf Geprägten Lederumhänge sollen neue Abenteurer ausrüsten, die den Elementen in Teldrassil und darüber hinaus trotzen. Lotherias ist mit Versorgungsanforderungen überflutet, und die Herstellung dieser haltbaren Umhänge beweist, dass Ihr sowohl über die Ausdauer als auch über die technischen Fähigkeiten verfügt, die für eine fortgeschrittene Ausbildung in der Lederverarbeitung erforderlich sind.",al={"warum geprägter lederumhang","nutzung geprägte lederumhänge","lotherias umhänge"}}},fp="13,178,22.229.0,19.236.0,17.155.0,46.151.0,26.120.0,50.164.0,49.146.0,53.142.0"}
P.entries["quest:159"] = {n="Saftlieferung",s="In Dunkelhain bringt Ihr Zombie Juice nach Westen zu einem Einsiedler am Rand des Dämmerwalds. Schankwart Smitts sagt, das Gebräu sei stark genug, um Tote zu erwecken. Es soll Calvinius wärmen, doch seine Wirkungskraft wirft Fragen auf.",h="In Dunkelhain bringt Ihr Zombie Juice nach Westen zu einem Einsiedler am Rand des Dämmerwalds.",kw={"calvinius","dunkelhain","dämmerwald","saftlieferung","scarlet raven","schankwart smitts","zombie juice"},ang={["faction:Alliance"]="Als Bote der Allianz trotzt Ihr für die Bürger von Dunkelhain den gefährlichen Straßen des Dämmerwalds. Jedem Einsiedler im Wald zu vertrauen, kann unvorhergesehenen Ärger bringen.",["profession:Cooking"]="Als Koch erkennt Ihr, dass Schankwart Smitts' Rezept für Zombie Juice auf streng riechende, ungewöhnliche Zutaten setzt und auslotet, was in ein Schankgetränk gehört."},sec={{t="Ein zweifelhaftes Gebräu",b="Schankwart Smitts braut in Dunkelhain einen legendären Trunk. Als der Zombie Juice fertig ist, überreicht er Euch die Flasche und mahnt Euch, behutsam damit umzugehen. Er sagt, das Gebräu sei stark genug, um Tote zu erwecken. Ihr tragt es durch den verwunschenen Wald zu einem exzentrischen Einzelgänger, was wie ein einfacher Akt der Nächstenliebe erscheint."},{t="Der Versprecher des Einsiedlers",b="Calvinius lebt in einer Hütte am Waldrand, wohin Ihr ihm das flüchtige Gebräu bringt. Der gebrechliche Einsiedler sagt, er brauche den Schnaps, um seine schmerzenden Knochen in den eisigen, nebelverhangenen Nächten des Dämmerwalds zu wärmen. Als er die Flasche entgegennimmt, dankt er Euch beinahe für Eure „Torheit“, verbessert sich dann rasch und lobt Eure „Güte“. Sein Versprecher deutet an, dass er mit dem Gebräu mehr vorhat als einen abendlichen Umtrunk."}},faq={{q="Was ist Zombie Juice?",a="Zombie Juice ist ein äußerst starkes Gebräu, das Schankwart Smitts in der Scarlet Raven Tavern in Dunkelhain herstellt. Er sagt, es sei stark genug, um Tote zu erwecken, und weitaus stärker als gewöhnliche Spirituosen.",al={"zombie juice hintergrund","was ist smitts' saft","calvinius getränk"}},{q="Wer bestellt den Zombie Juice?",a="Calvinius, ein exzentrischer alter Einsiedler, bittet um den Zombie Juice. Er lebt in einer einsamen Hütte nahe der westlichen Grenze des Dämmerwalds.",al={"wer will den saft","für wen ist die saftlieferung"}},{q="Warum will Calvinius das Getränk?",a="Calvinius behauptet, er brauche das Getränk, um sich in den bitterkalten, feuchten Nächten des Dämmerwalds warmzuhalten. Als er es erhält, deutet sein Versprecher auf finstere Pläne für das Gebräu hin.",al={"warum braucht calvinius saft","calvinius kälte"}},{q="Wer braut den Zombie Juice?",a="Schankwart Smitts braut Zombie Juice selbst in der Scarlet Raven Tavern im Herzen von Dunkelhain, sobald er die nötigen, streng riechenden Zutaten hat.",al={"wer stellt zombie juice her","smitts schankwart"}},{q="Wo steht Calvinius' Hütte?",a="Calvinius' abgelegene Hütte steht im westlichen Dämmerwald, unmittelbar nördlich des Friedhofs von Rabenflucht.",al={"calvinius aufenthaltsort","wo steht calvinius' hütte"}},{q="Was tut Calvinius als Nächstes, nachdem er den Saft erhalten hat?",a="Nachdem er sich den Zombie Juice gesichert hat, nutzt Calvinius weiterhin gutgläubige Reisende aus. Er schickt sie zum Friedhof von Rabenflucht, um Ghulrippen für eine Ghoulish Effigy zu sammeln, die angeblich die Untoten fernhalten soll.",al={"nächste quest nach saftlieferung","was passiert als nächstes"}}},fx={["9f2016f2"]={q="Warum möchte Schankwart Smitts, dass der Saft geliefert wird?",a="Smitts betreibt die Scarlet Raven Tavern in Dunkelhain und hat seinen Teil der Transaktion abgeschlossen, indem er das starke Gebräu braute, das Calvinius angefordert hatte. Da das Getränk abgefüllt und fertig ist, besteht sein einziges Interesse darin, dass die versprochene Bestellung erfüllt und aus seinen Händen gegeben wird, während er Euch gleichzeitig warnt, mit dem flüchtigen Getränk vorsichtig umzugehen.",al={"warum möchte smitts das erledigt haben","motiv schankwart smitts","warum zombie juice liefern"}},["6bab1f80"]={q="Warum lässt Smitts den Saft von einem Abenteurer liefern, anstatt selbst zu gehen?",a="Schankwart Smitts muss die Bar in der Scarlet Raven Tavern bedienen, und das Umherwandern auf den schattigen Straßen des Dämmerwaldes ist ein viel zu gefährliches Unterfangen für einen gewöhnlichen Schankwirt. Calvinius' Einsiedelei befindet sich in den schattigen Wäldern in der Nähe von Raven Hill, einem Gebiet, das von Untoten und wilden Tieren wimmelt, die nur ein bewaffneter Reisender sicher durchqueren kann.",al={"warum ich smitts","warum kann smitts den saft nicht liefern","warum geht der schankwart nicht selbst"}}},fp="14,212,20.307.0,17.418.1,21.189.0,28.127.0,36.182.0,27.145.0,29.89.0,56.201.0"}
P.entries["quest:1598"] = {n="Der gestohlene Foliant",s="In der Abtei von Nordhain sucht Drusilla La Salle einen gestohlenen Folianten aus dem Lager der Defias in den Weinbergen. „Macht der Leere“ könnte ihren Unterricht bereichern, und wenn Ihr das Buch zurückbringt, beweist Ihr Euer Können.",h="In der Abtei von Nordhain sucht Drusilla La Salle einen gestohlenen Folianten aus dem Lager der Defias in den...",kw={"bruderschaft der defias","drusilla la salle","abtei von nordhain","novize dieb","macht der leere","gestohlenes buch","weinberge","hexenmeister wichtel"},ang={["class:Warlock"]="Als Hexenmeister beweist Ihr, dass Ihr gefährliches Gelände durchqueren könnt, ohne zurückzuschrecken. Die Bergung des Folianten bringt Euch die Riten ein, mit denen Ihr Euren ersten Wichtel ruft.",["faction:Alliance"]="Als Mitglied der Allianz geht Ihr im Umfeld der Paladine und Kleriker von Nordhain behutsam vor und nutzt die Fehler von Gesetzlosen, um verbotenes okkultes Wissen zu erlangen.",["race:Human"]="Als Mensch seht Ihr den Einfluss der Bruderschaft der Defias in Nordhain, wo selbst Schüler der Abtei heilige Schriften stehlen und sich dem Aufstand anschließen."},sec={{t="Eine verbotene Gelegenheit",b="Hexenmeister in den Landen von Sturmwind verbergen ihr Handwerk und ihre Forschungen vor neugierigen Blicken. Die Abtei von Nordhain bewacht verbotene Grimoires in ihren Archiven. Drusilla kann es nicht riskieren, durch das Betreten des geschützten Flügels den Verdacht der Kleriker und Paladine zu erregen. Sie begehrt „Macht der Leere“ und braucht jemanden, der das Buch für sie beschafft."},{t="Die Gelegenheit der Defias",b="Ein Novize der Abtei schloss sich der Bruderschaft der Defias an und stahl bei seinem Fortgang mehrere wertvolle Schriften. Er floh in die Weinberge von Nordhain und suchte nahe dem Lager der Defias Zuflucht. Die Diebe verwahren ihre Beute in einem Feldzelt, ohne die Gefahr der dunklen Künste in diesem Buch zu kennen."},{t="Die erste Bindung",b="Die Bergung von „Macht der Leere“ stellt Euren Mut auf die Probe und öffnet den Weg zu dunklerem Wissen. Den Folianten zurückzubringen befriedigt Drusillas Ehrgeiz und beweist, dass Ihr bereit seid, die dunklen Künste auszuüben. Sie belohnt Euch mit den Riten zur Beschwörung und Bindung eines Wichtels, des ersten Dämons, den ein Lehrling zu befehligen lernt."}},faq={{q="Was ist „Macht der Leere“?",a="„Macht der Leere“ ist ein verbotenes Grimoire über dunkle Magie und die Beherrschung der Ebenen. Der bewachte Flügel der Bibliothek der Abtei von Nordhain birgt Wissen, das Drusilla La Salle für ihre Studien und ihren Unterricht begehrt.",al={"macht der leere buch","was ist das buch","was hat der novize gestohlen"}},{q="Warum hat Drusilla La Salle das Buch nicht selbst gestohlen?",a="Drusilla La Salle muss ihr Ansehen in der Abtei von Nordhain schützen. Das Betreten der gesicherten Archive der Bibliothek würde die Kleriker und Paladine alarmieren. Als ein Novize den Folianten stahl und sich den Defias anschloss, bot sich ihr die Gelegenheit, ihn durch einen Lehrling zu erlangen.",al={"warum drusilla es nicht selbst stahl","warum mich schicken"}},{q="Wo ist der gestohlene Foliant versteckt?",a="Die Defias versteckten den Folianten in einem Zelt in ihrem Lager in den Weinbergen von Nordhain, östlich der Abtei.",al={"wo ist das buch","fundort des folianten","gestohlener foliant zelt"}},{q="Warum schloss sich ein Novize aus Nordhain der Bruderschaft der Defias an?",a="Unzufriedenheit und Zwietracht im ganzen Königreich treiben Arbeiter, Bauern und Schüler der Kirche dazu, sich der Bruderschaft der Defias anzuschließen. Der Novize brach seine Gelübde, stahl mehrere wichtige Bücher aus der Bibliothek und floh dann zu den Banditen in den Weinbergen.",al={"warum der novize sich den defias anschloss","abtei defias verräter","wer hat das buch gestohlen"}},{q="Welche Belohnung erhält ein Hexenmeister für die Bergung des Folianten?",a="Wenn Ihr den Folianten zurückbringt, beweist Ihr, dass Ihr den Mut und die Widerstandskraft besitzt, die dunklen Künste auszuüben. Drusilla belohnt Euch mit den Lehren zur Beschwörung eines Wichtels, Eures ersten Dämons.",al={"was lernt man","hexenmeister questbelohnung","warum diese quest erfüllen"}},{q="Wissen die Defias, wie man das Buch benutzt?",a="Die Banditen betrachten die gestohlenen Bücher als wertvolle Beute aus der Abtei. Obwohl die Defias abtrünnige Zauberwirker beschäftigen, verstauten der Novize und seine Gefährten den Folianten in einer Zeltkiste, statt seine dunklen Geheimnisse zu meistern.",al={"können die defias den folianten benutzen","was machen die defias mit dem buch"}}},fx={["1f0061ae"]={q="Warum möchte Drusilla La Salle die Macht der Leere?",a="Drusilla hat schon lange das verbotene Wissen begehrt, das in der Macht der Leere eingeschlossen ist, aber es wurde in einem gesicherten, geschützten Flügel der Library der Abtei von Nordhain aufbewahrt, wo sie es nicht erreichen konnte, ohne Verdacht zu erregen. Dass ein zielloser Novize es stahl, gab ihr die perfekte Gelegenheit, ihre dunklen Geheimnisse endlich für sich zu beanspruchen und gleichzeitig zu testen, ob Ihr die Stärke habt, die Künste der Hexenmeister zu studieren.",al={"warum möchte drusilla das buch","motiv drusilla la salle","warum den folianten stehlen"}},a46315b9={q="Gegen wen werdet Ihr ausgesandt, um den Folianten zurückzuholen?",a="Ihr werdet gegen die Banditen der The Defias Brotherhood ausgesandt, die in den Weinberge von Nordhain kampieren. Ein abtrünniger Novize der Abtei stahl mehrere wertvolle Bände aus der geschützten Library, bevor er floh, um sich ihrer Rebellion anzuschließen, und versteckte den Folianten zwischen ihren Zelten.",al={"wer nahm das buch","defias in den weinbergen","wer stahl die macht der leere"}}},fp="15,184,23.309.0,18.261.0,17.293.0,31.203.0,52.248.0,32.99.0,56.231.0,55.162.0,39.219.0"}
P.entries["quest:1599"] = {n="Anfänge",s="In Dun Morogh prüft Alamar Grimm Hexenmeisternovizen der Allianz, bevor er sie lehrt, einen Wichtel zu beschwören. Zuerst müssen sie Frostmane-Trollnovizen Federglücksbringer abnehmen.",h="In Dun Morogh prüft Alamar Grimm Hexenmeisternovizen der Allianz, bevor er sie lehrt, einen Wichtel zu...",kw={"alamar grimm","ambossar","beginnings","das coldridgetal","dun morogh","federglücksbringer","frostmane-novize","wichtel"},ang={["class:Warlock"]="Als Hexenmeister der Allianz in Dun Morogh beginnt Ihr Eure Ausbildung damit, Grimms Anerkennung zu gewinnen und die Beschwörung Eures ersten dämonischen Dieners zu erlernen.",["race:Gnome"]="Als Gnomenhexenmeister in der Ausbildung im Coldridgetal beweist Ihr Euren Verstand und Eure Beherrschung der Magie, indem Ihr die örtlichen Frostmane-Trolle überlistet."},sec={{t="Ein widerwilliger Mentor",b="Einflussreiche Stimmen sind auf einen vielversprechenden Rekruten aufmerksam geworden, und ihr Interesse holt Alamar Grimm aus seinen okkulten Forschungen. Widerwillig kommt der Hexenmeister, um den Novizen zu beurteilen."},{t="Der Funke dunkler Magie",b="Bevor Grimm einen Novizen lehrt, niedere Dämonen zu versklaven, verlangt er einen Beweis für Ausdauer und magische Begabung. Frostmane-Trollnovizen tragen Federglücksbringer in einer Höhle südwestlich von Ambossar bei sich. Feine urtümliche Magie durchströmt die Glücksbringer, und sie zu erbeuten beweist, dass der Novize einen magischen Gegner überwinden kann. Die ungewöhnlichen Fundstücke dienen auch Grimms Forschung."},{t="Die Beschwörung des Wichtels",b="Die Glücksbringer überzeugen Grimm davon, dass der Novize den Willen zum Überleben besitzt. Er lehrt die Beschwörung eines Wichtels, des einfachsten Dieners eines Hexenmeisters. Dessen chaotische Feuermagie kann einen Meister überwältigen, dem es an Disziplin mangelt."}},faq={{q="Wer vergibt die Quest Beginnings?",a="Alamar Grimm stellt die Prüfung. Er bildet Hexenmeister in Ambossar im Coldridgetal in Dun Morogh aus.",al={"wer startet beginnings","questgeber beginnings","alamar grimm standort"}},{q="Wofür werden die Federglücksbringer verwendet?",a="Die Federglücksbringer beweisen, dass ein angehender Hexenmeister magisch begabten Gegnern entgegentreten und sie besiegen kann. Diese verzauberten Trollschmuckstücke liefern Alamar Grimm außerdem ungewöhnliche Fundstücke für seine Forschung.",al={"warum federglücksbringer","federglücksbringer zweck","frostmane-glücksbringer"}},{q="Wo befinden sich die Frostmane-Novizen?",a="Frostmane-Trollnovizen versammeln sich in einer Höhle südwestlich von Ambossar im Coldridgetal. Die Frostmane-Trolle haben sich dort niedergelassen.",al={"wo sind die trollnovizen","frostmane-höhle standort","frostmane-novizen fundort"}},{q="Welche Belohnung erhält ein Hexenmeister für den Abschluss dieser Aufgabe?",a="Die Prüfung bringt einem Hexenmeister Alamar Grimms Anerkennung ein und lehrt ihn, einen Wichtel zu beschwören, seinen ersten dämonischen Begleiter.",al={"was lehrt beginnings","questbelohnung beginnings","wichtelzauber quest"}},{q="Warum unterrichtet Alamar Grimm neue Hexenmeister?",a="Einflussreiche Stimmen zeigen Interesse an dem angehenden Hexenmeister. Ihre Aufmerksamkeit bewegt Grimm dazu, seine privaten okkulten Studien zu unterbrechen, um den Rekruten zu prüfen und anzuleiten.",al={"warum bildet alamar mich aus","wer hat alamar gesagt mich auszubilden"}},{q="Ist der Wichtel für einen Hexenmeisternovizen gefährlich?",a="Ja. Alamar Grimm warnt, dass sich hinter der geringen Größe eines Wichtels unberechenbares Teufelsfeuer und Verschlagenheit verbergen. Ein unerfahrener Beschwörer kann leicht überwältigt werden.",al={"wichtel gefahr","können wichtel einen töten","wichtel warnungen"}}},fx={["5dfeed0e"]={q="Warum möchte Alamar Grimm, dass dies erledigt wird?",a="Alamar Grimm wurde überredet, seine eigene Forschung zu unterbrechen und Euch auszubilden, weil bedeutende Gönner Interesse an Eurem Potenzial zeigten. Bevor er Euch beibringt, Euren ersten Dämon, einen Wichtel, zu beschwören, benötigt er den Beweis, dass Ihr über die magische Stärke und den körperlichen Mut verfügt, ihn zu überleben. Die Bergung der Federamulette dient auch seiner Neugier und bietet ihm seltsame Trollmagie zum Studium.",al={"motiv alamar grimm","warum federamulette","warum möchte alamar federamulette"}},f653bf22={q="Gegen wen werdet Ihr bei den Frostmähne-Novizen ausgesandt?",a="Die Frostmähne-Novizen sind junge Eistrolle, die in einer Höhle südwestlich von Ambossar rudimentäre Magie praktizieren. Der einheimische Frostmähne-Stamm steckt in einem Konflikt mit den Zwergen von Eisenschmiede in ganz Dun Morogh und nutzt nahegelegene Höhlen, um sich neu zu gruppieren und seine angehenden Zauberwirker auszubilden.",al={"frostmähne-novizen dun morogh","wer sind die frostmähne-novizen","troll-novizen höhle"}}},fp="10,164,18.178.0,23.341.0,17.201.0,31.97.0,37.179.0,40.139.0,58.110.0,42.162.0,42.138.0"}
P.entries["quest:16"] = {n="Etwas zu trinken für Gerard",s="In den Weinbergen der Maclures arbeitet Gerard Tiller lange Tage auf den Feldern und braucht frisches Quellwasser. Vorbeiziehende Reisende bringen Wasser und tauschen es gegen Äpfel.",h="In den Weinbergen der Maclures arbeitet Gerard Tiller lange Tage auf den Feldern und braucht frisches...",kw={"äpfel","tauschhandel","wald von elwynn","gerard tiller","weinberge der maclures","erfrischendes quellwasser"},ang={["faction:Alliance"]="Wer Elwynns Bauern an Orten wie den Weinbergen der Maclures unterstützt, hilft, die Gehöfte und Garnisonen des Waldes zu ernähren, während sich das Königreich verteidigt.",["race:Human"]="Wenn Ihr als Mensch in Nordhain beginnt und Nachbarn wie Gerard Tiller helft, zeigt Ihr den Gemeinschaftssinn, der Elwynn zusammenhält."},sec={{t="Durstige Arbeit in den Weinbergen",b="Elwynns Bauernhöfe versorgen Sturmwinds Stadtbewohner und Garnisonen mit Getreide, Obst und Gemüse. Unter freiem Himmel ist die Arbeit heiß. In den Weinbergen der Maclures pflegt Gerard Tiller die Feldfrüchte, hält Schädlinge fern und kümmert sich um die Ernte. Da er kaum Zeit hat, die Stadtbrunnen aufzusuchen, ist er auf vorbeiziehende Rekruten angewiesen, die sauberes Quellwasser bringen, damit er weiterarbeiten kann."},{t="Die Wirtschaft des Tauschhandels",b="Gerard tauscht Vorräte gegen Wasser statt gegen Münzen. Reisende mit zusätzlichen Fläschchen Erfrischendem Quellwasser können sie gegen frische Äpfel aus seinem Obstgarten eintauschen. Das Königreich muss mit seinen Mitteln haushalten, um die Ordnung aufrechtzuerhalten und seine Armee zu ernähren. So bleibt der Tauschhandel zwischen Kleinbauern und Rekruten ein praktischer Weg, um im ländlichen Elwynn über die Runden zu kommen."}},faq={{q="Wer ist Gerard Tiller?",a="Gerard Tiller bewirtschaftet einen Hof in den Weinbergen der Maclures im südlichen Wald von Elwynn. Er pflegt die Felder und Obstgärten, die die örtlichen Bewohner versorgen.",al={"gerard tiller","wer ist tiller","gerard"}},{q="Warum braucht Gerard Wasser?",a="Den ganzen Tag unter der Sonne auf den Feldern zu arbeiten, ist anstrengend. Gerard ist auf vorbeiziehende Reisende angewiesen, die frisches Quellwasser bringen, damit er genug trinken kann, ohne seine Arbeit liegen zu lassen.",al={"warum quellwasser","gerard durstig","warum etwas zu trinken nötig"}},{q="Wo gibt es Erfrischendes Quellwasser?",a="Händler für Speis und Trank sowie Gastwirte im gesamten Wald von Elwynn verkaufen üblicherweise Erfrischendes Quellwasser. Brother Danil verkauft es in der Abtei von Nordhain.",al={"wo wasser bekommen","quellwasserquelle","wie wasser bekommen"}},{q="Lässt sich dieser Tausch wiederholen?",a="Ja. Gerard arbeitet weiter auf den Feldern und tauscht frische Äpfel aus seinem Obstgarten gegen weitere Wasserflaschen, die Ihr entbehren könnt.",al={"wiederholbare quest","kann ich das wiederholen","mehr wasser abgeben"}},{q="Was bietet Gerard im Gegenzug für das Getränk?",a="Gerard tauscht einen Glänzenden roten Apfel gegen frisches Wasser.",al={"gerard belohnung","was bekomme ich","tauschbelohnung"}},{q="Wo befindet sich Gerard?",a="Gerard steht vor der Scheune in den Weinbergen der Maclures im südlichen Wald von Elwynn.",al={"gerard tiller standort","wo ist gerard","wo ist der bauernhof"}}},fx={d51fec31={q="Wofür wird das Erfrischende Quellwasser verwendet?",a="Die Arbeit auf den Feldern der Weinberge der Maclures ist anstrengend, und Gerard Tiller benötigt einfach einen zuverlässigen Vorrat an frischem, sauberem Wasser, um seinen Durst während der Arbeit unter der Sonne zu stillen. Anstatt seine Ernte unbeaufsichtigt zu lassen, um selbst etwas zu trinken zu holen, freut er sich, mit vorbeiziehenden Reisenden zu tauschen, die etwas übrig haben.",al={"nutzung erfrischendes quellwasser","warum quellwasser","gerard quellwasser"}}},fp="19,154,35.353.0,21.323.0,21.133.0,27.168.0,43.149.0,25.109.0,47.48.0,24.78.0"}
P.entries["quest:160"] = {n="Ein Brief für den Bürgermeister",s="Im westlichen Dämmerwald schickt Calvinius eine Nachricht nach Dunkelhain, wo den Bürgermeister eine unerwartete Lieferung erwartet. Er nennt sich einen alten Freund von Bürgermeister Lord Ello Schwarzhaupt, doch der Brief wirft Fragen auf.",h="Im westlichen Dämmerwald schickt Calvinius eine Nachricht nach Dunkelhain, wo den Bürgermeister eine...",kw={"calvinius","dunkelhain","dämmerwald","ello schwarzhaupt","brief","bürgermeister","ein brief für den bürgermeister"},ang={["faction:Alliance"]="Dunkelhains Sicherheit hängt davon ab, die Ursache seltsamer Störungen zu finden, bevor sie die Verteidigungslinie der Nachtwache erreichen. Der verdächtige Brief erfordert die Aufmerksamkeit von Agenten der Allianz.",["race:Human"]="Als menschlicher Bote im Dienst der Nachtwache und des House of Ebonlocke könntet Ihr feststellen, dass der alte Einsiedler am Rand des Dämmerwalds nicht so aufrichtig ist, wie er scheint."},sec={{t="Eine freundliche Nachricht?",b="Ihr holt Calvinius' gestohlene Kiste von den Ogern im Ogerhort Vul'Gol zurück und tragt dann seine Nachricht über die nebligen Straßen in die Stadt. Der Einsiedler lacht vor Vergnügen. Er sagt, er und Bürgermeister Lord Ello Schwarzhaupt seien alte Freunde, und beharrt darauf, dass der Bürgermeister ebenso begeistert von Eurer Tat sein werde."},{t="Ratlose Stadtführung",b="Im Rathaus von Dunkelhain sagt Bürgermeister Lord Ello Schwarzhaupt, er habe noch nie von Calvinius gehört. Das Pergament enthält keinen Gruß, den er lesen kann. Seine uralte Schrift lässt den Bürgermeister ratlos zurück."}},faq={{q="Wer schickt „Ein Brief für den Bürgermeister“?",a="Calvinius gibt Euch den Brief, nachdem Ihr seine gestohlenen Besitztümer von den örtlichen Ogern zurückgeholt habt. Er lebt allein in einer Hütte am westlichen Rand des Dämmerwalds.",al={"wer gibt ein brief für den bürgermeister","wer startet ein brief für den bürgermeister","calvinius brief absender"}},{q="Sind Calvinius und Bürgermeister Schwarzhaupt wirklich Freunde?",a="Nein. Calvinius bezeichnet sie als alte Bekannte, doch Bürgermeister Lord Ello Schwarzhaupt hat noch nie von ihm gehört und wird aus der Nachricht nicht schlau.",al={"kennen sie einander","ist calvinius mit dem bürgermeister befreundet","calvinius ello schwarzhaupt beziehung"}},{q="Was steht in dem Brief?",a="Der Brief ist in einer uralten, kaum bekannten Sprache geschrieben. Weder Ihr noch Bürgermeister Schwarzhaupt könnt ihn entziffern, weshalb er um Hilfe bei der Übersetzung bittet.",al={"was steht in calvinius' brief","kann ello den brief lesen","in welcher sprache ist der brief"}},{q="Wo befindet sich Lord Ello Schwarzhaupt?",a="Bürgermeister Lord Ello Schwarzhaupt befindet sich im Rathaus von Dunkelhain, auf der Ostseite der Stadt an der Hauptstraße durch den Dämmerwald.",al={"wo ist der bürgermeister","ello schwarzhaupt aufenthaltsort","wo ein brief für den bürgermeister abgeben"}},{q="Was geschieht, nachdem Bürgermeister Schwarzhaupt den Brief erhalten hat?",a="Da er die geheimnisvolle Schrift nicht lesen kann, bittet Lord Schwarzhaupt Euch, jemanden zu finden, der sie deuten kann. Er schickt Euch los, um Calvinius' Brief übersetzen zu lassen.",al={"was kommt nach ein brief für den bürgermeister","was folgt auf ein brief für den bürgermeister"}},{q="Warum hat Calvinius gelacht, als er Euch den Brief gab?",a="Calvinius lacht vor Vergnügen, als er Euch den Brief gibt, doch der Text nennt keinen Grund dafür. Seine Behauptung, sie seien Freunde, lässt Dunkelhains Bürgermeister ratlos zurück.",al={"warum lacht calvinius","ist calvinius böse","calvinius lachen brief"}}},fx={["7816d016"]={q="Warum schickt Euch Calvinius mit dem Brief, anstatt ihn selbst zuzustellen?",a="Calvinius lebt als gebrechlicher, einsamer Eremit in den verwunschenen Wäldern weit westlich von Dunkelhain. Indem er einen ahnungslosen Reisenden, der ihm gerade geholfen hat, seine Nachricht überbringen lässt, kann er seine unheilvolle Überraschung direkt zum Rathaus bringen, ohne jemals in die Nähe der misstrauischen The Nachtwache oder des Stadtrats von Dunkelhain zu kommen.",al={"warum ich für note to the mayor","warum liefert calvinius den brief nicht","warum den spieler nutzen um den brief zu liefern"}}},fp="17,201,19.290.0,18.184.1,32.151.0,53.136.0,28.141.0,37.115.0,55.153.0,57.155.1"}
P.entries["quest:161"] = {n="Eine dunkle Bedrohung",s="Am Steinwerkdamm vermutet Chefingenieur Hinderweir VII. Sabotage und schickt eine Pulverprobe zur Untersuchung nach Norden. Ein Kurier muss sie durch das Sumpfland zum Sprengstoffexperten Ashlan Schmunzelstein in Dun Modr bringen.",h="Am Steinwerkdamm vermutet Chefingenieur Hinderweir VII.",kw={"ashlan schmunzelstein","eine dunkle bedrohung","dun modr","explosives pulver","hinderweir","der steinwerkdamm","thandol-übergang","sumpfland"},ang={["faction:Alliance"]="Die Hauptstraße durch Loch Modan und das Sumpfland ist eine lebenswichtige militärische Verbindung zwischen Eisenschmiede und den nördlichen Besitzungen der Allianz jenseits des Thandol-Übergangs.",["profession:Engineering"]="Um Rückstände hochwertiger Sprengstoffe zu identifizieren, braucht es das geübte Auge eines Sappeurs. Selbst gewöhnliche Pulver können die technischen Fähigkeiten eines feindlichen Saboteurs verraten.",["race:Dwarf"]="Der Steinwerkdamm ist eines der größten Meisterwerke der Ingenieurskunst der Bronzebeard. Ein Komplott zur Zerstörung seines Mauerwerks bedroht den Stolz und die Sicherheit von ganz Khaz Modan."},sec={{t="Ein Pulver in böser Absicht",b="Ein verdächtiges Fass nahe der östlichen Rampe des Damms enthielt ein sonderbar riechendes Pulver. Hinderweir hatte Dunkeleisensappeure in der Nähe gesehen und vermutet, dass das Pulver ein veredelter Sprengstoff ist, der zwergisches Mauerwerk zerschmettern soll. Am Damm fehlt die Spezialausrüstung, um es zu prüfen. Bevor er Gewissheit haben kann, muss ein militärischer Sprengstoffexperte die Probe untersuchen."},{t="Die Straße nach Norden",b="Die Straße führt durch das Algaz-Tor hinab in die durchnässten Niederungen des Sumpflands. Feindselige Wildtiere, aggressive Drachkin und Dunkeleiseninfiltratoren machen den Weg gefährlich. Hinderweir mahnt Kuriere, auf der gepflasterten Straße nach Dun Modr zu bleiben. Die geplünderte Zwergenstadt liegt am südlichen Zugang zum Thandol-Übergang, wo noch immer ein Regiment aus Eisenschmiede Wache hält."},{t="Der Sprengmeister von Dun Modr",b="In Dun Modr ist Ashlan Schmunzelstein der Meister des Regiments für hochexplosive Sprengstoffe. Jahrzehnte heftiger Druckwellen haben ihn halbtaub gemacht. Sein scharfes Auge und seine feine Nase bestätigen, dass das Pulver eine spezielle Sprengladung ist. Seine Anwesenheit deutet auf ein gezieltes Komplott gegen das Herz zwergischer Ingenieurskunst hin."}},faq={{q="Was ist das sonderbar riechende Pulver?",a="Das sonderbar riechende Pulver ist eine alchemistische Sprengladung, die nahe dem Steinwerkdamm sichergestellt wurde. Chefingenieur Hinderweir VII. vermutet, dass Saboteure damit die Dammmauern durchbrechen wollen.",al={"was ist das pulver","hinderweir pulver","sonderbares pulver"}},{q="Warum wird das Pulver bis nach Dun Modr geschickt?",a="In Dun Modr ist das Militärkontingent aus Eisenschmiede untergebracht, das den Thandol-Übergang verteidigt, darunter auch Ashlan Schmunzelstein. Er ist ein erfahrener Sprengstoffexperte mit dem Fachwissen, um spezielle Sprengstoffgemische zu identifizieren.",al={"warum dun modr","warum ashlan schmunzelstein","warum ins sumpfland"}},{q="Wo befindet sich Ashlan Schmunzelstein?",a="Ashlan Schmunzelstein ist im Militärlager von Dun Modr stationiert, im äußersten Norden des Sumpflands, unmittelbar südlich des Thandol-Übergangs.",al={"wo ist schmunzelstein","ashlan finden","schmunzelstein standort"}},{q="Warum mahnt Hinderweir, auf der Straße zu bleiben?",a="Hinderweir mahnt Kuriere, auf der Straße vom Algaz-Tor hinab zu bleiben, weil feindselige Bestien, Raptoren, Gnolle und Dunkeleisensaboteure durch das Sumpfland streifen. Reisen abseits der Straße sind äußerst gefährlich.",al={"warum auf der straße bleiben","gefahren im sumpfland","straße ins sumpfland"}},{q="Wer sabotiert den Steinwerkdamm?",a="Die Sprengstoffe gehören den Dunkeleisenzwergen, die die Infrastruktur der Bronzebeard untergraben und den Steinwerkdamm zum Einsturz bringen wollen, um die Täler darunter zu überfluten.",al={"wer hat das pulver hergestellt","saboteure am damm","eine dunkle bedrohung täter"}},{q="Warum ist Ashlan Schmunzelstein schwerhörig?",a="Die Arbeit an der Front als Militärsappeur und Sprengstoffspezialist hat Ashlan durch die Druckwellen der Explosionen chronisches Ohrenklingeln und schweren Hörverlust eingebracht.",al={"schmunzelstein taub","warum kann ashlan nicht hören"}}},fx={["4fa83212"]={q="Warum möchte Chefingenieur Hinderweir VII., dass dies erledigt wird?",a="Chefingenieur Hinderweir VII. ist für die Integrität des Steinwerkdamms verantwortlich, eines der größten technischen Wunderwerke von Khaz Modan. Da er vermutet, dass das seltsame Pulver, das in der Nähe entdeckt wurde, ein Sprengstoff ist, der die Struktur sabotieren soll, benötigt er eine Expertenanalyse, um die genaue Bedrohung zu verstehen, der der Damm gegenübersteht, bevor eine Katastrophe eintritt.",al={"warum braucht hinderweir das","motivation hinderweir","warum das pulver schicken"}}},fp="19,222,22.340.0,14.371.0,28.294.1,36.181.0,44.210.0,35.122.0,46.204.0,39.155.1,41.158.0"}
P.entries["quest:1618"] = {n="Die Aufrüstung im Rotkammgebirge",s="In Seenhain braucht eine schwer bedrängte Garnison robuste Kupferausrüstung aus Eisenschmiede. Tormus Tiefenschmied bittet aufstrebende Schmiede der Allianz, sie zu fertigen und Verner Gutmark bei der Verteidigung der Region gegen feindselige Orcs und Gnolle zu unterstützen.",h="In Seenhain braucht eine schwer bedrängte Garnison robuste Kupferausrüstung aus Eisenschmiede.",kw={"schwarzfelsorcs","schmiedekunst","gnolle","schwerer kupferschlägel","seenhain","rotkammgebirge","runenverzierter kupfergürtel","steinwacht","tormus tiefenschmied","verner gutmark"},ang={["faction:Alliance"]="Als Mitglied der Allianz bringt Ihr Hilfe aus Eisenschmiede zu den schwer bedrängten menschlichen Städten des Südens, wo Sturmwinds uneinige Führung nur zögerlich handelt.",["profession:Blacksmithing"]="Als Schmied zeigt Ihr, dass Ihr haltbare Waffen und schützende Rüstungen in großen Mengen für eine umkämpfte Front fertigen könnt.",["race:Dwarf"]="Als Zwerg schöpft Ihr aus einem Handwerk, das die Kriegsanstrengungen der Allianz trägt. Tormus schickt Eisenschmiedes beste Schmiede aus, um ihren Verbündeten zu helfen.",["race:Human"]="Als Mensch aus den südlichen Königreichen erhaltet Ihr in Khaz Modan geschmiedete Metallwaren, die im Kampf gegen die aggressiven Überreste der Schwarzfelsorcs Entlastung bringen."},sec={{t="Ein Hilferuf über Grenzen",b="Die Große Schmiede schickt Hilfe über Dun Morogh hinaus, wo die Front der Allianz unter Druck steht. Im Rotkammgebirge erleidet Seenhain wiederholte Angriffe durch Schwarzfelsorcs, die von Burg Steinwacht heranmarschieren, und Gnolle, die über die nördlichen Bergkämme streifen. Königliche Verstärkung aus Sturmwind lässt auf sich warten, und die örtlichen Vorräte sind gefährlich knapp."},{t="Die Ambosse von Seenhain",b="Verner Gutmark, Seenhains ansässiger Schmied, arbeitet beinahe allein an seiner Schmiede unter freiem Himmel. Er bessert zerschlagene Rüstungen aus und ersetzt zerbrochene Waffen. Tormus Tiefenschmied sieht die Belastung seines menschlichen Kollegen und bittet angehende Schmiede, vier Runenverzierte Kupfergürtel und vier Schwere Kupferschlägel nach Seenhain zu bringen. Die Ausrüstung stärkt die Reserven der Miliz, und Verner lehrt reisende Handwerker feinere Techniken ihres Handwerks."}},faq={{q="Wer vergibt die Quest „Die Aufrüstung im Rotkammgebirge“?",a="An der Großen Schmiede in Eisenschmiede bietet Tormus Tiefenschmied die Arbeit Schmieden der Allianz an, die ihr Handwerk ausreichend beherrschen.",al={"die aufrüstung im rotkammgebirge questgeber","wer vergibt die aufrüstung im rotkammgebirge","tormus quest"}},{q="Warum braucht Seenhain Waffen und Rüstungen aus Eisenschmiede?",a="Seenhain wird ständig von Schwarzfelsorcs, die Burg Steinwacht besetzen, und aggressiven Gnollen auf den nördlichen Bergkämmen angegriffen. Verner Gutmark ist überlastet, da er allein Waffen und Rüstungen für die Miliz ausbessert.",al={"warum das rotkammgebirge ausrüstung braucht","warum seenhain waffen braucht","versorgungsengpass im rotkammgebirge"}},{q="Wer nimmt die Lieferung im Rotkammgebirge entgegen?",a="Verner Gutmark, Seenhains örtlicher Schmied, nimmt die Lieferung nahe der Schmiede in der Stadt am See entgegen.",al={"wo die aufrüstung im rotkammgebirge abgeben","verner gutmark standort","rotkammgebirge abgabe beim schmied"}},{q="Welche Ausrüstung muss für den Auftrag geschmiedet werden?",a="Schmiedet vier Runenverzierte Kupfergürtel und vier Schwere Kupferschlägel. Zusammen erfordern sie Geschick bei der Fertigung schützender Panzerplatten und schwerer Schlagwaffen.",al={"die aufrüstung im rotkammgebirge benötigte gegenstände","materialien für die aufrüstung im rotkammgebirge","was für tormus schmieden"}},{q="Welche Bedrohungen plagen das Rotkammgebirge zu dieser Zeit?",a="Schwarzfelsorcs halten Burg Steinwacht besetzt, während gewalttätige Gnollrudel durch die nördlichen Ausläufer der Berge um Seenhain streifen.",al={"feinde im rotkammgebirge","wer greift seenhain an","bedrohungen im rotkammgebirge"}},{q="Welche Belohnung bietet Verner Gutmark im Gegenzug?",a="Sobald Verner nicht mehr jeden Gardisten von Grund auf ausrüsten muss, lehrt er Euch feinere Schmiedetechniken.",al={"verner gutmark ausbildung","belohnung für die aufrüstung im rotkammgebirge","was gibt es als belohnung"}}},fx={ba6aca96={q="Warum möchte Tormus Tiefenschmied, dass dies erledigt wird?",a="Tormus Tiefenschmied erkennt, dass die menschlichen Verbündeten von Eisenschmiede in Bedrängnis sind und ihre eigenen verzweifelten Schlachten schlagen. Da der Clan der Schwarzfels ständig Überfälle gegen Seenhain durchführt, versucht Tormus, die Bindungen zwischen Zwergen und Menschen zu stärken, indem er einem Verbündeten, der überlastet ist, wichtige Schmiedehilfe leistet.",al={"warum dem rotkammgebirge helfen","motiv tormus tiefenschmied","warum vorräte in das rotkammgebirge schicken"}},e26bdf46={q="Wozu dient der Runenverzierte Kupfergürtel?",a="Diese verzauberten Gürtel bieten eine wichtige Rüstungsverstärkung für die Verteidiger von Seenhain. Da lokale Schmiede mit der Reparatur kaputter Ausrüstung überfordert sind, helfen robust hergestellte Gürtel dabei, die Stadtwachen und Milizen zu schützen, die ständig Scharmützeln mit Schwarzfels-Orks und Gnollen ausgesetzt sind.",al={"nutzung runenverzierte kupfergürtel","warum runenverzierte kupfergürtel","zweck runenverzierte kupfergürtel"}},["61555f3e"]={q="Wozu dient der Schwere Kupferhammer?",a="Die schweren Kupferhämmer statten die Verteidiger an der Front von Seenhain mit langlebigen, bestrafenden Waffen aus. Die Verteidiger des Rotkammgebirges stoßen ständig auf gepanzerte Schwarzfels-Orks und zähe Gnolle aus dem Rotkammgebirge, was zermalmende stumpfe Waffen für ihre Kriegsanstrengungen unverzichtbar macht.",al={"zweck schwerer kupferhammer","warum schwere kupferhämmer","schwerer kupferhammer rotkammgebirge"}},["330fd0fb"]={q="Warum benötigt Tormus Tiefenschmied Euch, anstatt sie selbst auszuliefern?",a="Tormus ist ein Meisterschmied, der Lehrlinge ausbildet und Die Große Schmiede von Eisenschmiede leitet, ein wichtiger Posten, den er für eine Reise in die Menschenlande nicht aufgeben kann. Die Lieferung einem angehenden Schmied anzuvertrauen, hilft sowohl ihren Verbündeten als auch Euch, Handels-Techniken von Verner Gutmark zu lernen.",al={"warum mich ins rotkammgebirge schicken","warum kann tormus nicht liefern","warum ich gearing redridge"}}},fp="16,219,22.337.0,23.408.0,38.110.0,57.200.0,38.103.0,43.136.0,49.109.0,47.113.0"}
P.entries["quest:162"] = {n="Aufstieg der Silithid",s="Leitender Feldmesser Rutenwünschels schickt Euch mit einem Bericht für Gracina Spiritmight, eine Nachtelfengelehrte und Historikerin, nach Darnassus.",h="Leitender Feldmesser Rutenwünschels schickt Euch mit einem Bericht für Gracina Spiritmight, eine...",kw={"darnassus","rutenwünschels","gracina","insektenanalyse","silithiden","spiritmight","tanaris","tempel des mondes"},sec={{t="Eine Gelehrte in Darnassus",b="Leitender Feldmesser Rutenwünschels möchte den Bericht in den Händen von jemandem wissen, der sich mit solchen Dingen auskennt. Gracina Spiritmight ist eine Nachtelfengelehrte und Historikerin. Sie hat viel Zeit damit verbracht, Lebensformen zu erforschen, die nur in Azeroths Ökologie vorkommen. Rutenwünschels hofft, dass sie die Gefahr einschätzen und einen Weg finden kann, sie aufzuhalten. Nach Rutenwünschels' letztem Stand lebt Gracina im Tempel des Mondes in Darnassus."},{t="Gracinas Antwort",b="Gracina Spiritmight sagt, dass die Nachtelfen von dem im Bericht beschriebenen Schrecken wissen. Sie glaubt, dass Rutenwünschels eine gute Wahl getroffen hat, als er den Bericht und Euch entsandte. Die Silithiden werden die Wüste von Tanaris rasch verschlingen und zu den größten Gefahren zählen, denen sich je jemand stellen muss. Sie sind Werkzeuge einer der schwerwiegendsten Bedrohungen für Horde und Allianz. Gracina beklagt, dass niemand die Gefahr früher erkannt hat."}},faq={{q="Wer ist Gracina Spiritmight?",a="Gracina Spiritmight ist eine Nachtelfengelehrte und Historikerin, die viel Zeit damit verbracht hat, Lebensformen zu erforschen, die nur in Azeroths Ökologie vorkommen.",al={"gracina spiritmight hintergrundgeschichte","wer ist gracina","gelehrte im tempel des mondes"}},{q="Wer schickt Euch zu Gracina?",a="Leitender Feldmesser Rutenwünschels gibt Euch den Insekten-Analysebericht und bittet Euch, ihn zu Gracina Spiritmight zu bringen.",al={"woher kam der bericht","herkunft des insekten-analyseberichts"}},{q="Wo ist Gracina Spiritmight zu finden?",a="Nach Rutenwünschels' letztem Stand lebt Gracina Spiritmight im Tempel des Mondes in Darnassus.",al={"wo ist gracina","gracina spiritmight aufenthaltsort","gracina spiritmight finden"}},{q="Was ging dieser Reise nach Darnassus voraus?",a="Insect Part Analysis geht Eurer Reise nach Darnassus voraus.",al={"vorherige quest","was führte zum aufstieg der silithid","quest vor dem besuch bei gracina"}}},fp="20,125,22.378.0,16.383.1,27.129.0,25.113.0,39.94.0,43.60.0"}
P.entries["quest:163"] = {n="Rabenflucht",s="Im äußersten Westen des Dämmerwalds flackert Licht in einem verfallenen Fenster von Rabenflucht. Elaine Carevin schickt Reisende aus Dunkelhain los, um herauszufinden, was dort Unterschlupf gefunden hat.",h="Im äußersten Westen des Dämmerwalds flackert Licht in einem verfallenen Fenster von Rabenflucht.",kw={"calor","dunkelhain","dämmerwald","elaine carevin","bibbers","night watch","rabenflucht"},ang={["class:Paladin"]="Als Paladin seid Ihr darin ausgebildet, die ruhelosen Untoten auf dem benachbarten Friedhof zu jagen. Der zitternde Bibbers aus Fleisch und Blut könnte eine unerwartete Entdeckung sein.",["faction:Alliance"]="Die Nachtwache erhält kaum oder gar keine Hilfe von der Garnison Sturmwinds. Als Held der Allianz könntet Ihr gerufen werden, um Bedrohungen in den verfallenen Winkeln des Dämmerwalds nachzugehen."},sec={{t="Augen im Westen",b="Die Nachtwache hat den äußersten Westen des Dämmerwalds längst den Toten und der Wildnis überlassen. Doch Lebenszeichen dort verlangen Aufmerksamkeit. Calor, ein Wächter auf den düsteren Straßen, sah zwei Nächte hintereinander Bewegung zwischen den stillen Häusern von Rabenflucht. Eine Laterne flackerte in einem Fenster. Angesichts der Ghule, Skelette und Bestien im ganzen Land kann die Nachtwache nicht ignorieren, was sich zwischen den Ruinen regt."},{t="Ein verstörter Einsiedler",b="In Rabenflucht zittert Bibbers bei jedem Laut im Dunkeln. Der Vagabund kauert zwischen den verfallenen Gebäuden und beharrt darauf, dass es außer dem harmlosen Bibbers keine Gefahr gebe. Sein wirres Gerede deutet an, dass er mehr über den Albtraum weiß, der den Dämmerwald verschlingt, als er zu sagen wagt."}},faq={{q="Wer schickt Euch los, um Rabenflucht zu untersuchen?",a="Elaine Carevin lebt in Dunkelhain und unterstützt die Nachtwache. Aus Sorge um die Sicherheit des Dämmerwalds bittet sie Reisende, beunruhigenden Berichten aus dem Westen nachzugehen.",al={"wer vergibt die quest für rabenflucht","questgeber rabenflucht","elaine carevin quest"}},{q="Was hat Calor in Rabenflucht tatsächlich gesehen?",a="Calor sah zwei Nächte hintereinander Schatten durch die verlassene Siedlung Rabenflucht huschen. In der Nacht zuvor sah er eine Laterne oder Kerze im Fenster eines Gebäudes brennen.",al={"was hat calor gesehen","calors sichtung in rabenflucht","schatten in rabenflucht"}},{q="Welches Monster sucht die Ruinen heim?",a="Ihr werdet ausgesandt, um herauszufinden, was Rabenflucht heimsucht. Calor sah sich bewegende Schatten und Licht in einem Fenster, doch nur ein Besuch der verfallenen Gebäude kann enthüllen, was dort lauert.",al={"wer sucht rabenflucht heim","was ist in rabenflucht","ist das monster von rabenflucht echt"}},{q="Wer ist Bibbers?",a="Bibbers ist ein paranoider Landstreicher im westlichen Dämmerwald, der ständig am Rande der Panik lebt. Er behauptet, harmlos zu sein, doch seine Schuldgefühle und sein wirres Gerede deuten auf eine Verbindung zu den dunkleren Geheimnissen der Region hin.",al={"bibbers hintergrundgeschichte","wer ist bibbers im dämmerwald","warum versteckt sich bibbers"}},{q="Wo liegt Rabenflucht?",a="Rabenflucht liegt im äußersten Westen des Dämmerwalds, direkt südlich des großen, von Untoten verseuchten Friedhofs, der denselben Namen trägt.",al={"rabenflucht lage","wo liegt rabenflucht","rabenflucht karte"}},{q="Warum bereiten umherhuschende Schatten der Nachtwache solche Sorgen?",a="Die Verteidiger von Dunkelhain sind durch auferstehende Skelette, wilde Worgen und lauernde Spinnen bis an ihre Grenzen gefordert. Seltsame Bewohner oder organisierte Bewegungen im verlassenen Westen könnten die verbliebenen Siedlungen der Lebenden bedrohen.",al={"warum ist rabenflucht wichtig","night watch rabenflucht"}}},fx={["2c575d43"]={q="Warum möchte Elaine Carevin, dass Raven Hill untersucht wird?",a="Elaine Carevin widmet sich der Sicherheit des Dämmerwaldes. Da The Nachtwache bereits durch die Schrecken, die durch die Wälder kriechen, überlastet ist, können seltsame Lichter und sich bewegende Schatten in der verlassenen Siedlung von Raven Hill nicht ignoriert werden. Sie braucht jemanden, der herausfindet, ob eine neue Bedrohung am westlichen Rand der Region Fuß fasst.",al={"warum schickt euch elaine","motiv elaine carevin","warum raven hill untersuchen"}},["2a1c77d7"]={q="Warum bittet Elaine Carevin einen Abenteurer anstelle der The Nachtwache?",a="Die The Nachtwache ist gefährlich unterbesetzt und überlastet, während sie nur versucht, den Außenposten von Dunkelhain zu halten und die Straßen zu schützen. Da jeder kampffähige Verteidiger damit beschäftigt ist, sich gegen Untote, Spinnen und Worgen zu verteidigen, ist Elaine auf fähige Reisende angewiesen, die bereit sind, sich in die verlassenen Ruinen von Raven Hill zu wagen.",al={"warum ich raven hill","warum schickt elaine nicht die night watch","warum einen abenteurer fragen"}}},fp="10,160,16.375.0,16.274.1,40.165.0,42.164.0,35.168.1,15.199.1,28.111.0,57.213.0"}
P.entries["quest:1638"] = {n="Die Ausbildung eines Kriegers",s="Lyria Du Lac schickt junge Krieger von Goldhain nach Sturmwind, um Ausdauer auf dem Schlachtfeld zu erlernen. In der Pig and Whistle Tavern in der Altstadt unterweist sie der kampferprobte Veteran Harry Burlguard.",h="Lyria Du Lac schickt junge Krieger von Goldhain nach Sturmwind, um Ausdauer auf dem Schlachtfeld zu erlernen.",kw={"bartleby","goldhain","harry burlguard","lyria du lac","die altstadt","pig and whistle","sturmwind","ausbildung","krieger"},ang={["class:Warrior"]="Als Krieger vollzieht Ihr mit diesem Ritus den Übergang vom Rekruten der örtlichen Miliz zum offiziell anerkannten Soldaten der Allianz. Er eröffnet Euch den Weg zu fortgeschrittenen Haltungen und Verteidigungstechniken.",["faction:Alliance"]="Als Rekrut der Allianz könnt Ihr neben Taktiken aus Büchern auch praktische Weisheiten aus Raufereien von Veteranen wie Harry Burlguard an umkämpfte Grenzen mitnehmen.",["race:Human"]="Als menschlicher Kämpfer führt Euch Euer Weg von der Verteidigung des ländlichen Elwynn in die Altstadt, die alte, von Arbeitern geprägte Wiege von Sturmwinds kriegerischem Erbe."},sec={{t="Von Elwynn in die Altstadt",b="Wenn Ihr Euer Können gegen Bedrohungen im ganzen Wald von Elwynn bewiesen habt, können Euch die Ausbilder in Goldhain kaum noch etwas beibringen. Deshalb schickt Euch Lyria Du Lac nach Sturmwind in das raue Viertel der Altstadt. Dort versammeln sich erfahrene Kämpfer, um fernab der starren Gepflogenheiten der königlichen Garnison weiterzugeben, was der Kampf sie gelehrt hat."},{t="Die Lehren des Veteranen",b="Harry Burlguard ist ein betagter Kriegsveteran, der sein Quartier in der Pig and Whistle Tavern hat. Er prüft Euren Schneid mit Trinkgelagen und praktischen Ausdauerproben statt mit Übungen auf dem Exerzierplatz. Bevor Harry Euch Verteidigungsmanöver für gefährliche Feldzüge beibringt, erwartet er, dass Ihr mit seiner Trinklust mithaltet und Euch den örtlichen Schlägern der Taverne stellt."}},faq={{q="Wer vergibt diese Quest?",a="Lyria Du Lac, die Kriegerlehrerin hinter der Schmiede in Goldhain, bietet diese Ausbildung an, nachdem Ihr Euer anfängliches Kampfgeschick bewiesen habt.",al={"questgeber","wer beginnt die ausbildung eines kriegers","lyria du lac quest"}},{q="Wo ist Harry Burlguard zu finden?",a="Harry Burlguard ist in der Pig and Whistle Tavern in der Altstadt von Sturmwind zu finden.",al={"wo ist harry burlguard","harry burlguard standort","pig and whistle tavern"}},{q="Was lehrt Harry Burlguard?",a="Harry lehrt praktische Manöver und Haltungen, die Kriegern helfen, im Feld länger durchzuhalten. Sein Unterricht beginnt mit Ausdauerproben.",al={"was wird gelehrt","kriegerquest belohnung stufe zehn","harry burlguard unterricht"}},{q="Warum findet die Ausbildung in einer Taverne statt und nicht in der Kaserne?",a="Die Altstadt ist das traditionsreiche, raue Herz von Sturmwind, wo sich ehemalige Soldaten und kampferprobte Veteranen versammeln. Harry lehrt bei Bier und mit der Disziplin bloßer Fäuste, fernab der förmlichen militärischen Gepflogenheiten der Kaserne.",al={"warum pig and whistle","warum ausbildung in der taverne","sturmwind kaserne"}},{q="Was folgt nach dem Gespräch mit Harry?",a="Nach dem Gespräch mit Harry stellt Ihr Euch Bartleby the Drunk, einem örtlichen Schläger. Diese Herausforderung prüft Eure körperliche Widerstandskraft, bevor Eure Ausbildung abgeschlossen ist.",al={"was ist die nächste quest","nach der ausbildung eines kriegers","nächster schritt"}},{q="Können auch andere Klassen diese Quest erhalten?",a="Nur Krieger können diese Ausbildung erhalten. Sie gehört zur speziellen Ausbildungsreihe für Krieger.",al={"nur für krieger","auch für paladine möglich","krieger klassenquest"}}},fx={["7596c61a"]={q="Warum schickt Lyria Du Lac Euch zu Harry Burlguard?",a="Lyria Du Lac erkennt an, dass Ihr Euch als fähiger Krieger erwiesen habt, doch sie weiß, dass reiner Enthusiasmus auf dem Schlachtfeld nur bis zu einem gewissen Punkt hilft. Um Euer Überleben gegen tödlichere Bedrohungen zu sichern, weist sie Euch an Harry Burlguard weiter. Als erfahrener Veteran verfügt Harry über bewährte Kampftechniken und praktische Weisheit vom Schlachtfeld, die neue Rekruten dringend benötigen, wenn sie hoffen, am Leben zu bleiben.",al={"warum will lyria das","lyria du lac motiv","warum zu harry burlguard schicken"}}},fp="20,206,23.301.0,22.331.0,21.131.0,35.101.0,32.127.0,57.205.0,35.151.1,36.91.0"}
P.entries["quest:1639"] = {n="Bartleby der Trunkenbold",s="In der Pig and Whistle Tavern stellt sich Bartleby der Trunkenbold Harry Burlguards Prüfung. Ein angehender Krieger der Allianz muss Bartlebys geliebten Becher an sich nehmen, bevor Harry weiterführende Kampffertigkeiten lehrt.",h="In der Pig and Whistle Tavern stellt sich Bartleby der Trunkenbold Harry Burlguards Prüfung.",kw={"bartleby","betrunken","harry burlguard","becher","die altstadt","pig and whistle","sturmwind","ausbildung","krieger"},ang={["class:Warrior"]="Als Krieger stellt Ihr Euch einer praktischen Prüfung der Ausbilder von Sturmwind, bevor sie Euch Verteidigungstaktiken und die Beherrschung von Kampfhaltungen lehren.",["faction:Alliance"]="Als Reisender der Allianz erlebt Ihr die raue, glanzlose Seite der Altstadt von Sturmwind, fern vom königlichen Hof im Keep."},sec={{t="Eine Prüfung im Wirtshaus",b="Harry Burlguard verlangt von Euch, Rückgrat zu beweisen, bevor er Euch in der Pig and Whistle Tavern weiterführende Kampffertigkeiten lehrt. Auf der anderen Seite des Raums sitzt Bartleby am hinteren Ende des Tresens und schlürft seine Getränke. Harry will, dass Ihr dem Mann seinen Becher abnehmt, denn er weiß, dass Bartleby lieber kämpft, als sein Bier herzugeben. Die Herausforderung prüft Eure Entschlossenheit."},{t="Manieren in der Altstadt",b="Soldaten, Arbeiter und raue Einheimische füllen die Pig and Whistle, wo feine Manieren wenig zählen. Bartleby verspottet Neuankömmlinge als zu zimperlich für eine Wirtshausschlägerei, statt höflich zu antworten. Der Wortwechsel führt zu einer Schlägerei auf den Dielen. In Sturmwind beginnt die Ausbildung eines Kriegers mit einer Prüfung im einfachen Kneipenkampf."}},faq={{q="Wer ist Bartleby?",a="Bartleby ist ein starrsinniger, trinkfreudiger Gast am Tresen der Pig and Whistle Tavern in der Altstadt von Sturmwind.",al={"wer ist bartleby","bartleby npc","bartleby der trunkenbold"}},{q="Warum schickt mich Harry Burlguard zu Bartleby?",a="Harry Burlguard will sehen, welche Kniffe Ihr beherrscht, bevor er Euch fortgeschrittene Kriegertechniken beibringt. Bartleby den Becher abzunehmen, führt unweigerlich zum Kampf und prüft, ob Ihr einen Schlag einstecken und standhalten könnt.",al={"warum gegen bartleby kämpfen","harry burlguards prüfung","warum den becher holen"}},{q="Wo findet diese Begegnung statt?",a="Die Begegnung findet in der Pig and Whistle Tavern in der Altstadt auf der Ostseite von Sturmwind statt.",al={"wo ist bartleby","pig and whistle standort"}},{q="Was geschieht, wenn Ihr Bartleby ansprecht?",a="Bartleby beschimpft Euch als vornehm und zimperlich und warnt Euch dann, Euch in der Pig and Whistle keinen Nagel abzubrechen. Seine Worte lösen rasch einen Kampf aus.",al={"was sagt bartleby","bartleby dialog"}},{q="Was folgt auf das Gespräch mit Bartleby?",a="Nachdem Ihr Bartleby angesprochen habt, beginnt eine Wirtshausschlägerei. Ihr müsst ihn besiegen, um seinen Becher an Euch zu nehmen und ihn Harry Burlguard zurückzubringen.",al={"nächste quest nach bartleby","was folgt auf bartleby den trunkenbold"}},{q="Ist diese Quest für jede Klasse verfügbar?",a="Nein. Diese Klassenausbildung ist für Krieger der Allianz bestimmt, die die zehnte Stufe erreicht haben.",al={"kann jeder bartleby machen","nur für krieger"}}},fx={["1d302574"]={q="Warum schickt Harry Burlguard Euch, anstatt selbst gegen Bartleby vorzugehen?",a="Harry Burlguard hat nichts Persönliches mit dem örtlichen Säufer zu regeln – er ist ein Kriegerausbilder, der Euer Können testet. Bevor er seine Zeit damit verschwendet, Euch fortgeschrittene Kampftechniken beizubringen, will er sehen, ob Ihr den Mumm habt, Euch in einer rauen Schlägerei zu behaupten. Euch loszuschicken, um einem sturen Kneipensäufer einen Krug zu entreißen, ist schlicht seine praktische Aufnahmeprüfung.",al={"warum ich","warum schickt man mich zu bartleby","warum kämpft harry nicht gegen bartleby"}}},fp="18,187,18.327.0,18.327.0,16.116.0,45.197.0,37.111.0,40.133.0,37.122.0,37.82.0"}
P.entries["quest:164"] = {n="Lieferung an Sven",s="In Dunkelhain schickt Elaine Carevin Vorräte zu Sven Yorgens Lager im nordwestlichen Dämmerwald. Sven und seine wenigen Gefolgsleute trotzen den Gefahren des verheerten Waldes.",h="In Dunkelhain schickt Elaine Carevin Vorräte zu Sven Yorgens Lager im nordwestlichen Dämmerwald.",kw={"carevin","dunkelhain","dämmerwald","elaine carevin","licht","vorräte für sven","sven yorgen"},ang={["class:Paladin"]="Elaine sieht in Sven einen Mann, der das Werk des Lichts verrichtet. Als Paladin könnt Ihr einem bedrängten Mitstreiter helfen.",["faction:Alliance"]="Wachen an entlegenen Orten wie Sven zeigen, wie sehr der Einfluss der Allianz im Dämmerwald geschwunden ist. Freiwillige Kuriere bringen Vorräte dorthin, wohin die regulären Versorgungslinien der Garnisonen nicht mehr reichen.",["race:Human"]="Die Carevins und Svens Gefolgsleute zeigen die Zähigkeit der Landbevölkerung von Sturmwind. Als Mensch wisst Ihr, dass sie sich trotz seiner Düsternis weigern, den Dämmerwald aufzugeben."},sec={{t="Eine Lebensader zur Wildnis",b="Sven Yorgen und einige Gefährten unterhalten ein Lager an der nordwestlichen Grenze des Dämmerwalds. Wölfe, Spinnen und ruhelose Tote bedrohen Dunkelhain, doch Svens Schar hält jenseits der Stadtmauern stand. Die Gefahr lässt sie niemanden für den gefährlichen Weg zurück in die Stadt entbehren, um Vorräte zu holen. Elaine Carevin sorgt dafür, dass Reisende Vorräte bringen, damit die Kämpfer durchhalten können."},{t="Die Verbindung zu Carevin",b="Die Familie Carevin achtet Sven und sieht seinen Widerstand als Hingabe an das Licht. Elaine organisiert Vorräte und schickt sie zu seinem Lager. Als Sven die Kiste erhält, weiß er, dass die Carevins ihn unterstützen. Seine Aufmerksamkeit bleibt auf den Kampf vor Ort gerichtet."}},faq={{q="Wer ist Sven Yorgen?",a="Sven Yorgen ist ein Grenzlandbewohner mit einem bewaffneten Lager am nordwestlichen Rand des Dämmerwalds. Elaine Carevin sieht in ihm einen rechtschaffenen Kämpfer im Dienste des Lichts. Er und seine kleine Schar stellen sich den Schrecken der umliegenden Wälder.",al={"wer ist sven","svens geschichte","sven yorgen infos"}},{q="Warum müssen Sven Vorräte gebracht werden?",a="Svens kleine Schar muss ständig vor den Gefahren ringsum auf der Hut sein. Sie können niemanden für den gefährlichen Weg nach Dunkelhain und zurück entbehren und sind deshalb auf Vorräte von Stadtbewohnern und durchreisenden Kurieren angewiesen.",al={"warum kann sven keine vorräte holen","svens vorräte","warum die lieferung"}},{q="Wer stellt die Vorräte bereit?",a="Elaine Carevin stellt Vorräte aus Dunkelhain bereit. Ihre Familie achtet Svens Hingabe und organisiert Hilfe für sein Lager.",al={"wer schickt vorräte","elaine carevin","familie carevin"}},{q="Wo liegt Svens Lager?",a="Svens Lager liegt an den nordwestlichen Bergen des Dämmerwalds, weit jenseits der Straße und nördlich des verheerten Ackerlands, am Rand der Wildnis.",al={"wo ist sven","svens standort","svens lager"}},{q="Ist diese Lieferung erforderlich, bevor man Sven weiterhelfen kann?",a="Nein. Reisende, die Svens Lager auf eigene Faust finden, können ihm helfen, ohne Elaines Kiste zu bringen.",al={"ist lieferung an sven erforderlich","ist lieferung an sven nötig","lieferung als voraussetzung"}},{q="Was tut Sven nach Erhalt der Lieferung?",a="Sven dankt der Familie Carevin für ihre Unterstützung und wendet sich dann den Bedrohungen seines Lagers und der Vergangenheit seiner Familie zu. Er sucht Kämpfer, die ihm helfen, Rache zu üben.",al={"was passiert danach","nach lieferung an sven","svens nächste quest"}}},fx={cd88e308={q="Warum möchte Elaine Carevin, dass Vorräte an Sven Yorgen geliefert werden?",a="Elaine Carevin hält große Stücke auf Sven Yorgen und betrachtet seinen Kreuzzug in der Wildnis als wahres Werk des Lichts. Ihre Familie unterstützt seine Sache regelmäßig mit wichtigen Vorräten, doch Svens Truppe ist viel zu klein, um jemanden entbehren zu können, der nach Dunkelhain läuft, um sie sicher abzuholen.",al={"warum schickt elaine vorräte","elaine carevin motiv","warum hilft elaine sven"}},d0ad7f5e={q="Warum bittet Elaine Carevin Euch anstelle der The Nachtwache?",a="Die The Nachtwache ist bereits bis zum Äußersten angespannt, da sie nur Dunkelhain bewacht und die Hauptstraßen vor den Untoten und Bestien des Dämmerwalds patrouilliert. Sie haben keine Wachen, die sie für Versorgungsfahrten zu einem abgelegenen Lager in der nordwestlichen Wildnis entbehren könnten.",al={"warum braucht elaine mich","warum nicht die night watch schicken","warum die vorräte selbst liefern"}}},fp="18,158,28.371.0,22.246.0,19.211.0,43.204.0,26.115.0,29.144.0,55.93.0,47.160.0"}
P.entries["quest:1640"] = {n="Besiegt Bartleby",s="In Sturmwind hält Besiegt Bartleby einen geschätzten Becher der Kriegerausbilder zurück. Er will ihn nicht hergeben, also muss ein Rekrut ihn in einer Schlägerei erringen.",h="In Sturmwind hält Besiegt Bartleby einen geschätzten Becher der Kriegerausbilder zurück.",kw={"bartleby","schlägerei","betrunken","becher","sturmwind","ausbildung","prüfung","krieger"},ang={["class:Warrior"]="Als Krieger der Allianz bestreitet Ihr früh eine Wirtshausschlägerei und lernt, dass Willenskraft und eine schwere Faust Streitigkeiten beilegen können, wenn Diplomatie versagt.",["faction:Alliance"]="Auf den Straßen der Hauptstadt Sturmwind erhascht Ihr neben den stattlichen Steinmauern einen Blick auf die raue Schattenseite der Stadt."},sec={{t="Die Herausforderung eines Schlägers",b="Die Kriegerausbilder behaupten nicht, dass der Kampf edel oder erhaben sei. Bartleby schwört, niemand werde ihm seinen geschätzten Becher nehmen, ohne ihn aus seinen kalten, toten Fingern zu reißen. Also regelt Ihr die Sache mit Euren Fäusten. Für einen angehenden Krieger weichen Worte einer Schlägerei."},{t="Eine betrunkene Lektion",b="Bartleby prahlt, er werde bis zum Tod kämpfen, doch eine gehörige Abreibung ernüchtert ihn. Als er Eure Stärke erkennt, weicht seine Prahlerei einer von Blessuren gezeichneten Bewunderung, und er gibt friedlich auf. Ihr könnt den Becher in die Ausbildungshalle bringen und Eure Prüfung abschließen."}},faq={{q="Wer ist Bartleby?",a="Bartleby ist ein streitsüchtiger Trunkenbold, der sich oft in Sturmwind aufhält. Er klammert sich an ein geliebtes Trinkgefäß und prüft Kriegerneulinge, die ihre körperliche Standfestigkeit beweisen sollen.",al={"bartleby","wer ist bartleby","bartleby npc"}},{q="Warum muss ich gegen Bartleby kämpfen?",a="Die Kriegerausbilder der Allianz schicken Rekruten los, um einen Becher zurückzuholen, den Bartleby besitzt. Er weigert sich, ihn ohne eine Schlägerei herzugeben, also müsst Ihr ihn im Faustkampf besiegen, um den Becher zu erhalten.",al={"warum gegen bartleby kämpfen","besiegt bartleby grund","warum ihn besiegen"}},{q="Töte ich Bartleby bei dieser Quest tatsächlich?",a="Nein. Bartleby prahlt, Ihr müsstet ihm den Becher aus seinen kalten, toten Fingern reißen, doch nach seiner Niederlage ergibt er sich und gesteht ein, dass Ihr zäher seid als erwartet.",al={"stirbt bartleby","bartleby töten","ist bartleby tot"}},{q="Wo findet diese Quest statt?",a="Die Auseinandersetzung findet in Sturmwind statt, wo Bartleby trinkt und herumlungert.",al={"besiegt bartleby ort","wo ist bartleby","bartleby standort"}},{q="Was geschieht, nachdem ich ihn besiegt habe?",a="Nachdem Ihr ihn besiegt habt, gibt Bartleby auf und spricht freundlich mit Euch. Ihr könnt seinen Becher zu den Kriegerausbildern zurückbringen und Eure Aufnahmeprüfung abschließen.",al={"nach besiegt bartleby","was danach bartleby"}},{q="Für welchen Ausbildungsstand ist diese Prüfung gedacht?",a="Diese Schlägerei ist ein früher Meilenstein für angehende Krieger etwa in ihrer zehnten Saison der Erfahrung. Sie prüft die grundlegende Ausdauer im Faustkampf.",al={"bartleby quest stufe","wann gegen bartleby kämpfen"}}},fx={["14f26138"]={q="Warum kämpft Bartleby gegen Euch?",a="Bartleby will diese Schlägerei eigentlich gar nicht; stattdessen habt Ihr den Kampf provoziert, indem Ihr nach seinem Krug verlangt habt. Stur, betrunken und an seinem Getränk hängend, weigert er sich, es freiwillig herauszugeben, und erklärt, dass Ihr es ihm aus seinen kalten, toten Fingern reißen müsstet. Für Bartleby ist der Kampf gegen Euch eine rein betrunkene Angelegenheit von Stolz und dem Festhalten an seinem Bier.",al={"warum greift bartleby an","bartleby motiv","warum kämpft bartleby"}}},fp="13,137,21.257.0,16.246.0,16.167.0,32.163.0,42.149.0,33.78.0,32.143.0,49.145.0"}
P.entries["quest:1641"] = {n="Der Foliant der Offenbarung",s="In Sturmwinds Kathedrale des Lichts führt Duthorian Rall Euch durch einen feierlichen Ritus für junge Paladine. Seine Lehren prüfen Eure Tugend und Hingabe an das Heilige Licht.",h="In Sturmwinds Kathedrale des Lichts führt Duthorian Rall Euch durch einen feierlichen Ritus für junge...",kw={"buch der offenbarung","bruder wilhelm","kathedrale des lichts","duthorian rall","heiliges licht","paladin","sturmwind","tome of divinity","tugend"},ang={["class:Paladin"]="Für Euch als Paladin markiert dieser Ritus den Übergang vom Waffenlehrling zum Diener des Heiligen Lichts. Er lehrt die Opferbereitschaft und Barmherzigkeit, die das Herz des Ordens bilden.",["faction:Alliance"]="Als Mitglied der Allianz stärkt Eure Ausbildung Sturmwinds Herz und bereitet seine Paladine darauf vor, die Allianz vor der aufziehenden Dunkelheit zu schützen.",["race:Human"]="Als Mensch aus Sturmwind ehrt Ihr die gefallenen Ritter Lordaerons und führt die stolze Tradition der Silver Hand im südlichen Königreich fort."},sec={{t="Die Berufung eines Paladins",b="Eure Ausbildung reicht nun über den Waffengebrauch und die Riten des Ordens hinaus. Duthorians Prüfungen verlangen, dass Ihr die moralischen Pflichten eines Paladins abwägt und das tiefere Versprechen begreift, das Eure Berufung fordert. Wer auf das Heilige Licht angewiesen ist, braucht Verteidiger, die verstehen, was diese Pflicht bedeutet."},{t="Der Pfad der Tugend",b="Das Buch der Offenbarung verpflichtet Euch zu Dienst und Selbstaufopferung. Duthorian bittet Euch, seinen heiligen Text zu studieren und zu lernen, was das Licht von seinen Verteidigern verlangt. Seine Lehren bereiten Euch darauf vor, den schleichenden Schrecken der Geißel entgegenzutreten und das einfache Volk zu schützen. Tugend und Mitgefühl müssen Eure Macht leiten."}},faq={{q="Welchen Zweck erfüllt der Foliant der Offenbarung?",a="Der Foliant der Offenbarung prüft, ob ein neuer Paladin die heiligen Grundsätze versteht. Bevor einem Initianden größere göttliche Fähigkeiten anvertraut werden, müssen neben kriegerischem Geschick auch Hingabe und Tugend seine Stärke begründen.",al={"warum tome of divinity","was ist tome of divinity","paladin buch quest"}},{q="Wer ist Duthorian Rall?",a="Duthorian Rall ist ein hochrangiger Paladinlehrer in Sturmwinds Kathedrale des Lichts. Er leitet neue Paladine an, gibt ihnen das Buch der Offenbarung und lenkt ihre Prüfungen im ganzen Königreich.",al={"duthorian rall","paladinlehrer sturmwind","wer ist duthorian"}},{q="Wo findet diese Prüfung statt?",a="Die Prüfung beginnt in der Kathedrale des Lichts auf dem Kathedralenplatz in Sturmwind. Nach vorbereitenden Aufgaben in außerhalb gelegenen Ortschaften wie Goldhain melden sich die Initianden bei Duthorian Rall.",al={"wo ist duthorian","kathedrale des lichts quest","wo beginnt tome of divinity"}},{q="Warum wird die Geißel in Sturmwinds Lehren erwähnt?",a="Die Geißel verwüstete Lordaeron im Norden, doch ihre Untoten bedrohen noch immer alle lebenden Sterblichen. Sturmwinds Paladine lernen, die unheilige Verderbnis der Geißel überall in Azeroth zu erkennen und zu bekämpfen.",al={"geißel bedrohung sturmwind","warum geißel hier","paladine gegen geißel"}},{q="Was folgt auf die Lektüre des Buches der Offenbarung?",a="Das Buch der Offenbarung zu lesen ist nur der erste Schritt. Duthorian Rall prüft, ob Ihr seine Lehren verinnerlicht habt, indem er Euch aussendet, Menschen in größter Not zu helfen, wobei Eure Taten Mitgefühl und Widerstandskraft beweisen müssen.",al={"nächster schritt tome of divinity","nach dem lesen des buches","was will duthorian als nächstes"}},{q="Wer verweist Anwärter gewöhnlich an Duthorian Rall?",a="Örtliche Ausbilder und Geistliche in Elwynns abgelegenen Siedlungen können Anwärter an Duthorian Rall verweisen. Bruder Wilhelm in Goldhain ist einer dieser Wegweiser und schickt Initianden in die Hauptstadt, sobald sie für die formellen Prüfungen bereit sind.",al={"wer hat mich zu duthorian geschickt","vorherige quest tome of divinity","bruder wilhelm"}}},fx={f1eda7dc={q="Warum möchte Duthorian Rall, dass Ihr diese Prüfung ablegt?",a="Duthorian Rall trägt in Sturmwind die Pflicht, angehende Paladine zu wahrer Tugend und Hingabe an das Heilige Licht zu führen. Da Azeroth von der Geißel und unzähligen anderen Gefahren bedroht wird, benötigt der Orden standhafte Verteidiger mit festem Glauben und Können. Indem er Euch den The Tome of Divinity überreicht, versucht er, Euer Verständnis für die heiligen Gelübde eines Paladins zu prüfen, um sicherzustellen, dass Ihr über das erforderliche geistige Fundament verfügt, bevor er Euch größere heilige Segnungen gewährt.",al={"warum will duthorian rall das erledigt haben","duthorian rall motiv","warum den book of divinity studieren"}},e0af06a7={q="Warum wählt Duthorian Rall Euch für diese Aufgabe aus?",a="Diese Prüfung ist ein innerer, spiritueller Ritus, den nur Ihr selbst vollziehen könnt. Gewöhnliche Wachen oder etablierte Ritter können die Lehren des Lichts nicht in Eurem Namen studieren. Duthorian Rall überwacht Euer persönliches Wachstum als aufstrebender Paladin; um die Ehre und die Fähigkeiten des Ordens zu verdienen, müsst Ihr Eure eigene Hingabe und Bereitschaft beweisen, die heiligen Verantwortungen, die vor Euch liegen, zu schultern.",al={"warum ich duthorian rall","warum wählt duthorian euch","warum keine wachen schicken"}}},fp="20,165,19.259.0,18.289.0,44.213.0,22.179.0,33.183.0,54.214.0,46.214.0,50.222.0"}
P.entries["quest:1642"] = {n="Der Foliant der Offenbarung",s="In Sturmwind leitet der Tome of Divinity die ersten Schritte der Paladinausbildung. Seine Lehren rufen die Streiter des Heiligen Lichts zu Demut, Mitgefühl und Geduld auf, nicht zu Gottgleichheit oder Stärke allein.",h="In Sturmwind leitet der Tome of Divinity die ersten Schritte der Paladinausbildung.",kw={"kathedrale des lichts","mitgefühl","göttlichkeit","duthorian rall","heiliges licht","paladin","geduld","sturmwind","the tome of divinity"},ang={["class:Paladin"]="Für einen Paladin legt der Tome of Divinity den sittlichen Kern der Berufung dar: Mitgefühl und Geduld zählen ebenso viel wie Kampfbereitschaft.",["faction:Alliance"]="Sturmwinds Paladine bilden das geistliche und militärische Rückgrat der Allianz. Sie gründen die Verteidigung des Reiches auf sittliche Integrität und demütigen Dienst an den einfachen Bürgern.",["race:Human"]="Für die Menschen von Sturmwind ist das Studium des heiligen Folianten ein heiliger Übergangsritus, der Bürgerpflicht und Hingabe an das Heilige Licht stärkt."},sec={{t="Das Wesen der Göttlichkeit",b="Die heiligen Texte des Tome of Divinity lehren Paladinanwärter, was es bedeutet, dem Licht zu dienen. Göttlichkeit bedeutet weder, nach Gottgleichheit zu streben, noch die Herrschaft über andere zu beanspruchen. Stattdessen spiegeln Streiter die Gnade des Lichts durch reine Absichten und Güte in jeder Tat wider. Paladine greifen gegen das Böse zu den Waffen, doch Stärke ohne sittliches Ziel bedeutet wenig. Was sie wahrhaft auszeichnet, ist ihr Umgang mit den einfachen Leuten in ganz Azeroth, wobei ihre Macht stets an Rechtschaffenheit und Demut gebunden bleibt."},{t="Prüfungen des Mitgefühls und der Geduld",b="Die heilige Schrift ist nur der Anfang des Dienstes eines Paladins. Nachdem ein Anwärter den Tome of Divinity studiert hat, prüft Duthorian Rall in Sturmwind, ob dessen Lehren in Herz und Geist des Kandidaten Wurzeln geschlagen haben. Das Licht verlangt mehr als das Erlegen von Bestien. Es fordert Geduld, Tapferkeit und Verständnis.\n\nIn der Stadt und den umliegenden Landen leiden Menschen, und bescheidene Aufgaben bringen keinen Ruhm. Indem ein Anwärter Bedürftigen hilft und Verzweifelte tröstet, beweist er, dass er den gesunden Verstand und selbstlosen Geist besitzt, die Segnungen des Lichts verantwortungsvoll zu tragen."}},faq={{q="Was ist der Tome of Divinity?",a="Paladine in Sturmwind studieren den Tome of Divinity als heiligen Leitfaden für ihre Berufung. Seine Lehren lehnen Gottgleichheit und persönlichen Ruhm ab und mahnen sie, das Heilige Licht durch Güte, Mitgefühl und Geduld widerzuspiegeln.",al={"was ist tome of divinity","tome of divinity quest","paladin tome of divinity"}},{q="Wer ist Duthorian Rall?",a="Duthorian Rall ist ein Anführer der Paladine in Sturmwind, der junge Paladine beim Studium des Tome of Divinity anleitet. Er beaufsichtigt ihre geistlichen und kämpferischen Prüfungen und erprobt ihre Entschlossenheit durch praktischen Dienst am Königreich und seinen Menschen.",al={"wer ist duthorian rall","duthorian rall standort","sturmwind duthorian rall"}},{q="Welche Tugenden betont der Tome of Divinity?",a="Der Tome of Divinity lehrt, dass Mitgefühl, Geduld und Tapferkeit für einen heiligen Krieger ebenso wichtig sind wie Kampfgeschick. Paladine müssen das Böse zerschmettern, doch ihr Edelmut liegt darin, Schutzbedürftigen zu helfen und das Wohlwollen des Lichts widerzuspiegeln.",al={"paladintugenden tome of divinity","was lehrt der foliant","tugenden des lichts"}},{q="Warum prüft Duthorian Rall angehende Paladine?",a="Duthorian Rall prüft Anwärter, um festzustellen, ob sie sich die Lehren des Tome of Divinity wirklich zu Herzen genommen haben. Sie müssen im Dienst an Bedürftigen Urteilsvermögen und Geduld zeigen und so beweisen, dass ihre Hingabe auf Dienstbereitschaft statt auf Hochmut beruht.",al={"warum prüft duthorian paladine","duthorian rall prüfungen","zweck der paladinprüfungen"}},{q="Lehrt der Tome of Divinity Paladine, nach Gottgleichheit zu streben?",a="Nein. Der Tome of Divinity lehnt das Streben nach Gottgleichheit ab und lehrt Paladine, in jeder Tat nach Güte zu streben. Das Licht verleiht ihnen Stärke, um andere zu beschützen und zu unterstützen, nicht um sich über andere Sterbliche zu erheben.",al={"streben paladine nach gottgleichheit","nach gottgleichheit streben paladin","bedeutung der göttlichkeit paladin"}},{q="Wo findet diese Quest statt?",a="Die Prüfungen finden im Menschenkönigreich Sturmwind statt. Anwärter studieren die heiligen Lehren und melden sich bei Duthorian Rall in der Stadt, bevor sie auf den Straßen und im Umland Prüfungen der Nächstenliebe, Geduld und Tapferkeit bestehen.",al={"wo ist die quest tome of divinity","tome of divinity sturmwind standort","wo tome of divinity abgeben"}},{q="Warum ist Geduld für einen Paladin des Lichts so wichtig?",a="Geduld zeigt, dass ein heiliger Krieger diszipliniert, demütig und bei klarem Verstand ist. Den Unterdrückten zu dienen bedeutet oft, bescheidene, schwierige oder ruhmlose Aufgaben zu übernehmen, die neben Mut im Kampf auch innere Standhaftigkeit und echtes Mitgefühl verlangen.",al={"warum geduld paladin","bedeutung der geduld licht","paladin geduldsprüfung"}}},fp="20,195,22.474.0,33.575.0,29.215.0,22.234.0,49.243.0,47.245.0,57.216.0,33.232.0,56.253.0"}
P.entries["quest:1643"] = {n="Der Foliant der Offenbarung",s="In Sturmwind werden Initianden des Lichts ausgesandt, um jemandem in Not zu helfen. Sie suchen einen Bürger reinen Herzens und edler Absichten und finden Stephanie Turner im Handelsdistrikt.",h="In Sturmwind werden Initianden des Lichts ausgesandt, um jemandem in Not zu helfen.",kw={"heiliges licht","eisenschmiede","waisenhaus","paladin","stephanie turner","sturmwind","the tome of divinity","tome of divinity","der handelsdistrikt"},ang={["class:Paladin"]="Als Paladin, der dem Heiligen Licht zu dienen lernt, beginnt Ihr mit demütiger Wohltätigkeit statt mit kriegerischem Ruhm.",["faction:Alliance"]="Als Bürger der Allianz erlebt Ihr Sturmwinds Ringen um die Versorgung seiner Waisen und die Verbindungen zu Eisenschmiede, während Menschen in wirtschaftlicher Not Hilfe suchen."},sec={{t="Eine Lektion in Demut und Hilfsbereitschaft",b="Initianden des Lichts beginnen diese heilige Prüfung mit einem Gang durch Sturmwinds Straßen. Sie suchen jemanden mit edlen Absichten und reinen Beweggründen, der auf die Güte Fremder angewiesen ist. Vor der tieferen Unterweisung in heiligen Pflichten lernen sie, dass der Dienst an den Schwachen mehr zählt als ruhmreicher Kampf."},{t="Hilfe im Handelsdistrikt",b="In Sturmwinds Handelsdistrikt fertigt Stephanie Turner gemeinsam mit ihrem Mann Kleidung für die Kinder im Waisenhaus der Stadt. Mehr Händler sind in die Stadt gekommen, und die Konkurrenz um Stoff und Leder hat es erschwert, Spenden zu finden. Ihr Mann ist nach Eisenschmiede gereist, um Unterstützung zu suchen. Stephanie bleibt in Sturmwind und führt ihre gemeinsame Arbeit fort."}},faq={{q="Welchen Zweck hat die Prüfung Tome of Divinity?",a="Die Prüfung lehrt angehende Paladine, dem Heiligen Licht durch demütige Hilfe zu dienen. Initianden suchen in Sturmwind jemanden reinen Herzens, der Hilfe braucht, statt sich im Kampf oder durch große Taten zu beweisen.",al={"was ist tome of divinity","zweck von tome of divinity","warum tome of divinity absolvieren"}},{q="Wer ist Stephanie Turner?",a="Stephanie Turner lebt in Sturmwinds Handelsdistrikt und näht Kleidung für die Kinder im Waisenhaus der Stadt. Um sie zu versorgen, ist sie auf Stoff- und Lederspenden angewiesen.",al={"wer ist stephanie turner","stephanie turner sturmwind","wo ist stephanie turner"}},{q="Warum ist Stephanie Turners Mann nach Eisenschmiede gereist?",a="Stephanie Turners Mann ist nach Eisenschmiede gereist, um Unterstützung für ihre Arbeit im Waisenhaus zu suchen. Während seiner Abwesenheit sammelt sie Material und näht Kleidung in Sturmwind.",al={"stephanie turners mann","wer ist stephanies mann","ehemann in eisenschmiede"}},{q="Vor welchen Schwierigkeiten steht Stephanie Turner?",a="Mehr Händler in Sturmwind haben die Konkurrenz um Stoff und Leder verschärft. Da weniger Menschen bereit sind, diese Materialien zu spenden, fällt es Stephanie schwer, genug für die Kleidung der Waisen zusammenzutragen.",al={"warum hat stephanie schwierigkeiten","stoffmangel sturmwind","kleidungsproblem im waisenhaus"}},{q="Warum führt diese Prüfung Initianden gerade zu Stephanie Turner?",a="Stephanie Turner hat edle Absichten, ein reines Herz und braucht wirklich Hilfe. Ihr beizustehen gibt einem Initianden die Gelegenheit, jemandem zu dienen, der sich der Fürsorge für andere widmet.",al={"warum stephanie turner helfen","warum führt die quest zu stephanie"}},{q="Welche Lektion vermittelt diese Prüfung den Dienern des Lichts?",a="Die Prüfung lehrt Diener des Lichts, Mitgefühl zu zeigen und den Schwachen zu dienen. Bevor sie heilige Macht im Kampf einsetzen, müssen sie lernen, bedürftigen Bürgern mit Güte zu begegnen.",al={"was lehrt das licht hier","lektion von tome of divinity"}}},fp="20,171,32.291.0,25.339.0,50.217.0,24.176.0,53.173.0,45.200.0,70.159.0,60.167.0"}
P.entries["quest:1644"] = {n="Der Foliant der Offenbarung",s="Stephanie Turner in Sturmwind braucht Hilfe, um Kinder einzukleiden, die durch die Geißel zu Waisen wurden. Ihr Mann John sammelt Vorräte, während ein angehender Paladin Leinenstoff zu ihrem Haus bringt.",h="Stephanie Turner in Sturmwind braucht Hilfe, um Kinder einzukleiden, die durch die Geißel zu Waisen wurden.",kw={"barmherzigkeit","john turner","leinenstoff","waisen","paladin","geißel","stephanie turner","sturmwind","tome of divinity"},ang={["class:Paladin"]="Als Paladin zeigt Ihr Mitgefühl und Hingabe zum Licht, indem Ihr in Sturmwind für Schutzbedürftige sorgt und Almosen gebt.",["faction:Alliance"]="Kriegswaisen in Sturmwind zeigen das menschliche Leid durch die jüngsten Angriffe der Geißel in den nördlichen Reichen der Allianz.",["profession:Tailoring"]="Stephanie Turner näht aus Leinenstoffballen Hemden und Hosen für die Waisenkinder."},sec={{t="Die Waisen des Krieges",b="Stephanie Turner kümmert sich um Kinder, die im vergangenen Jahrzehnt ihre Familien durch die Geißel in den nördlichen Ländern verloren haben. Ihr Mann John ist unterwegs, um Vorräte zu sammeln. So muss Stephanie die Kinder ernähren, warmhalten und beherbergen und zugleich Zeit finden, ihnen Kleidung zu nähen."},{t="Eine Prüfung des Mitgefühls",b="Ein angehender Paladin beweist Mitgefühl, indem er Stephanie Leinenstoff bringt. Daraus kann sie Hemden und Hosen für die Kinder nähen, während sie sich um deren Nahrung und Unterkunft kümmert. Solch bescheidene Hilfe zeigt, wie die Beschützer des Lichts die Schwachen behüten."},{t="Lasten der Hauptstadt",b="Stephanie sagt, dieses Jahr sei härter geworden. John muss lange, beschwerliche Reisen bis nach Eisenschmiede unternehmen, um Vorräte zu sammeln. Selbst innerhalb der hohen Steinmauern von Sturmwind ist der Schmerz über die jüngsten Tragödien im Norden noch immer zu spüren."}},faq={{q="Wer ist Stephanie Turner?",a="Stephanie Turner lebt in Sturmwind und kümmert sich um Kinder, die durch die Geißel zu Waisen wurden. Mithilfe von Almosen und ihrem Mann John sorgt sie für Nahrung, Kleidung und Unterkunft.",al={"wer ist stephanie turner","stephanie turner sturmwind","waisenhausbetreuerin"}},{q="Warum braucht Stephanie Turner Leinenstoff?",a="Stephanie braucht Leinenstoff, um Hemden und Hosen für die Waisenkinder zu nähen. Da sie sich um Nahrung und Unterkunft kümmern muss, bleibt ihr wenig Zeit, selbst Materialien zu sammeln.",al={"warum leinenstoff","wofür wird leinen verwendet","stoff für stephanie"}},{q="Wer ist John und wohin ist er gegangen?",a="John ist Stephanie Turners Ehemann. Er reist von Sturmwind aus bis nach Eisenschmiede, um Vorräte zu sammeln, obwohl er ungern von seiner Familie getrennt ist.",al={"wer ist john","wo ist john","stephanie turners ehemann"}},{q="Warum gibt es so viele Waisenkinder in Sturmwind?",a="Die meisten Kinder in Stephanies Obhut verloren ihre Familien im vergangenen Jahrzehnt bei Angriffen der Geißel in den nördlichen Königreichen. Flüchtlinge und Überlebende brachten viele von ihnen nach Süden nach Sturmwind.",al={"warum gibt es waisen in sturmwind","geißel waisen sturmwind","was geschah mit den eltern der kinder"}},{q="Was hat die Hilfe für Stephanie mit dem Tome of Divinity zu tun?",a="Der Tome of Divinity prüft die Tugenden eines angehenden Paladins, besonders Barmherzigkeit und Mitgefühl. Einer Betreuerin grundlegende Vorräte zu geben, zeigt, dass ein Diener des Lichts die einfachen Leute beschützt und sich auch Monstern stellt.",al={"tome of divinity bedeutung","warum ist dies eine paladinquest","paladin barmherzigkeit quest"}},{q="Was meint Stephanie damit, dass „etwas in der Luft liegt“?",a="Stephanie sagt, dieses Jahr fühle sich härter an als frühere Jahre, als würde etwas in der Luft eine große Veränderung ankündigen. Sie kann nicht sagen, was es ist.",al={"schlechtes jahr sturmwind","etwas liegt in der luft","sturmwinds sorgen"}}},fp="20,177,18.266.0,21.243.0,22.222.0,24.173.0,43.160.0,34.155.0,53.194.0,58.208.0,54.136.0"}
P.entries["quest:1645"] = {n="Der Foliant der Offenbarung",s="In Eisenschmiede legt Tiza Kriegshammer einem Zwergenpaladin den Folianten der Offenbarung in die Hände. Seine Lehren leiten Prüfungen der Hingabe an das Licht und der Bereitschaft ein, Azeroth gegen finstere Mächte wie die Geißel zu verteidigen.",h="In Eisenschmiede legt Tiza Kriegshammer einem Zwergenpaladin den Folianten der Offenbarung in die Hände.",kw={"book of divinity","hall of mysteries","heiliges licht","eisenschmiede","paladin","erlösung","geißel","tiza kriegshammer","tome of divinity"},ang={["class:Paladin"]="Als Paladin führt Euch dieser Ritus von der kriegerischen Ausbildung zu den tieferen Tugenden des Heiligen Lichts und zu Kräften der Erlösung und Auferstehung.",["race:Dwarf"]="Als Zwerg stärkt Ihr mit der Annahme des Tome of Divinity das Glaubensband zwischen dem Königreich Bronzebeard und den menschlichen Rittern der Silbernen Hand."},sec={{t="Ein Ruf zur Tugend",b="Aus allen Teilen der Östlichen Königreiche kommen vielversprechende Paladininitianden in die Hall of Mysteries von Eisenschmiede, nachdem sie die kriegerischen und geistigen Grundlagen gemeistert haben. Dort lernen junge Zwergenpaladine, was einen Streiter des Heiligen Lichts von einem gewöhnlichen Krieger unterscheidet. Dieser Berufung zu folgen bedeutet, sein Leben der Pflicht, der Selbstaufopferung und der geistigen Disziplin zu weihen."},{t="Der Book of Divinity",b="Der Novize erhält den Book of Divinity als Leitfaden für seine Pflichten, Tugenden und geistigen Lehren. Seine Worte zeigen, wie heilige Macht gegen finstere Bedrohungen eingesetzt werden kann. Doch das Studium ist nur der erste Schritt. Der Initiand muss diese Lehren in Khaz Modan und darüber hinaus in Glaubenstaten umsetzen."}},faq={{q="Welchen Zweck hat die Quest „Foliant der Offenbarung“?",a="Der Foliant der Offenbarung leitet die weiterführende Ausbildung von Zwergenpaladinen ein. Tiza Kriegshammer gibt Initianden ein heiliges Buch und schickt sie auf Prüfungen, um ihre Tugend zu beweisen und zu lernen, gefallene Verbündete vom Tod zurückzurufen.",al={"was bewirkt tome of divinity","tome of divinity zweck","warum diese quest machen"}},{q="Wer ist Tiza Kriegshammer?",a="Tiza Kriegshammer bildet Paladine in der Hall of Mysteries von Eisenschmiede aus. Sie führt Zwergenpaladine zu größerer Tugend, prüft ihre Hingabe an das Licht und bereitet sie auf Bedrohungen wie die Geißel vor.",al={"tiza kriegshammer","wer ist der paladinlehrer in eisenschmiede","wer gibt tome of divinity"}},{q="Warum müssen Initianden den Book of Divinity studieren?",a="Der Book of Divinity lehrt die Pflichten und Tugenden, die das Heilige Licht verlangt. Seine Lehren bereiten Initianden auf die geistige Disziplin vor, die nötig ist, um heilige Kräfte einzusetzen.",al={"was ist der book of divinity","warum das buch lesen","book of divinity hintergrundgeschichte"}},{q="Auf den Kampf gegen welche großen Bedrohungen bereiten sich Zwergenpaladine vor?",a="Zwergenpaladine bereiten sich darauf vor, Azeroth gegen Gefahren im ganzen Land zu verteidigen, besonders gegen die vordringende untote Bedrohung durch die Geißel.",al={"gegen wen kämpfen paladine","warum paladine in eisenschmiede ausbilden","paladin zweck"}},{q="Wo findet diese Ausbildung statt?",a="Die Ausbildung beginnt in der Hall of Mysteries von Eisenschmiede, in den nördlichen Vierteln der Stadt. Gelehrte, Priester, Magier und Paladine versammeln sich dort zum Gebet und zum Studium.",al={"wo ist tiza kriegshammer","eisenschmiede paladin standort","hall of mysteries paladin"}},{q="Was folgt nach dem Erhalt des Buches?",a="Nachdem der Initiand den Book of Divinity gelesen und darüber nachgedacht hat, stellt er sich praktischen Prüfungen von Tiza Kriegshammer. Diese verlangen jenseits der Stadttore Mitgefühl, Pflichterfüllung und Opferbereitschaft.",al={"was passiert als nächstes","nächste quest tome of divinity","wohin nach erhalt des buches"}}},fx={b6d4c081={q="Warum möchte Tiza Kriegshammer, dass Ihr den Tome of Divinity studiert?",a="Tiza Kriegshammer beaufsichtigt die Ausbildung von Paladinen in Eisenschmiede. Sie sieht es als ihre heilige Pflicht an, Initianden zu wahrer Tugend und Hingabe an das Heilige Licht zu führen. Angesichts der drohenden Gefahr der Geißel und anderer Gefahren, die Azeroth bedrohen, möchte sie sicherstellen, dass jeder Verteidiger, den sie ausbildet, seine spirituellen Verantwortlichkeiten versteht und bereit ist, größere heilige Kräfte zur Verteidigung des Reiches einzusetzen.",al={"warum will tiza das erledigt haben","tiza kriegshammer motiv","warum den tome of divinity studieren"}},a71115f0={q="Warum bittet Tiza Kriegshammer Euch, diese Prüfung abzulegen, anstatt sie selbst zu übernehmen?",a="Tiza kann den Pfad der Tugend nicht für Euch beschreiten. Als Ausbilderin des Heiligen Lichts besteht ihre Verantwortung darin, zu führen und zu lehren, aber die Hingabe, das Verständnis und die innere Stärke, die ein wahrer Paladin benötigt, müssen aus dem Initianden selbst kommen. Um die Segnungen und Fähigkeiten des Lichts zu verdienen, müsst Ihr Eure Fähigkeit und Hingabe persönlich durch Studium und Dienst unter Beweis stellen.",al={"warum ich tome of divinity","warum macht tiza es nicht selbst","warum muss ich den folianten studieren"}}},fp="20,210,19.352.0,20.292.0,50.208.0,24.207.0,46.171.0,59.129.0,36.160.0,41.182.0"}
P.entries["quest:1646"] = {n="Der Foliant der Offenbarung",s="In Eisenschmiede lehrt Tiza Kriegshammer junge Paladine, was das Licht von ihnen verlangt. Der Tome of Divinity erklärt, dass Hingabe neben kriegerischer Stärke auch Geduld, Mitgefühl und demütigen Dienst an den Bedürftigen erfordert.",h="In Eisenschmiede lehrt Tiza Kriegshammer junge Paladine, was das Licht von ihnen verlangt.",kw={"mitgefühl","heiliges licht","eisenschmiede","paladin","geduld","the tome of divinity","tiza kriegshammer","tome of divinity"},ang={["class:Paladin"]="Als Paladin lernt Ihr, dass Mitgefühl und Dienst ebenso viel zählen wie Kampfgeschick.",["race:Dwarf"]="Als Zwerg erhaltet Ihr diese Unterweisung in Eisenschmiede von Mentoren wie Tiza Kriegshammer, die Euch lehren, Stärke mit Geduld und Tugend zu lenken."},sec={{t="Das Maß der Göttlichkeit",b="Für einen Paladin muss Stärke im Kampf einem höheren Zweck dienen. Tiza Kriegshammer in Eisenschmiede gibt Anwärtern den Tome of Divinity, damit sie lernen, warum sie ihre Waffen führen. Er lenkt ihre Gedanken von Herrschaft und Gottsein hin zu moralischer Güte. Die Berufung eines Paladins ist es, als beständiges Werkzeug des Lichts zu dienen."},{t="Prüfungen in Dienst und Mitgefühl",b="Der Foliant lehrt, dass es nicht genügt, das Böse niederzustrecken, um ein Paladin zu sein. Mitgefühl, Geduld und Demut unterscheiden diese Krieger von gewöhnlichen Kämpfern. Nachdem sie seine Worte studiert haben, stellen sich Anwärter Prüfungen in Eisenschmiede und den umliegenden Landen. Durch Wohltätigkeit und Dienst zeigen sie gutes Urteilsvermögen und unerschütterliche Hingabe."}},faq={{q="Was ist der Tome of Divinity?",a="Der Tome of Divinity lehrt angehende Paladine, dass Göttlichkeit bedeutet, Gutes zu tun, Benachteiligten zu helfen und Mitgefühl, Geduld und Tapferkeit zu zeigen, statt nach Gottsein zu streben.",al={"was ist der tome of divinity","tome of divinity paladin","was lehrt der foliant"}},{q="Wer ist Tiza Kriegshammer?",a="Tiza Kriegshammer ist eine Paladinmentorin in Eisenschmiede. Sie führt Neulinge durch ihre ersten Prüfungen und lehrt sie, rechtschaffenen Kampf und selbstlosen Dienst in Einklang zu bringen.",al={"wer ist tiza kriegshammer","tiza kriegshammer standort","wo ist tiza"}},{q="Warum müssen Paladine Geduld und Mitgefühl lernen?",a="Die Macht eines Paladins spiegelt das Licht wider, daher genügt Stärke im Kampf allein nicht. Geduld und Mitgefühl helfen Paladinen, andere zu verteidigen und ihnen beizustehen.",al={"warum den folianten lesen","paladintugenden","warum geduld und mitgefühl"}},{q="Welche Prüfungen folgen auf die Lektüre des Buches?",a="Nach der Lektüre des Folianten beweisen Paladine ihre Tugenden in praktischen Prüfungen. Mentoren schicken sie durch Eisenschmiede und die umliegenden Lande, um Bedürftigen zu helfen und ihre Hingabe an das Licht zu beweisen.",al={"was geschieht nach der lektüre des folianten","tome of divinity prüfungen","nächste prüfung nach der lektüre"}},{q="Wo findet diese Prüfung statt?",a="Nach dem Studium des Folianten kehren Paladine zu Tiza Kriegshammer in Eisenschmiede zurück, der Hauptstadt der Zwerge.",al={"wo wird diese quest abgegeben","eisenschmiede paladinquest"}},{q="Was bedeutet es, nach Göttlichkeit zu streben?",a="Nach Göttlichkeit zu streben bedeutet, sich in allen Dingen für das Gute zu entscheiden, statt nach Gottsein zu streben. Paladine nutzen das Licht, um den Bewohnern Azeroths beizustehen und sie zu beschützen.",al={"was bedeutet streben nach göttlichkeit","paladin gottsein"}}},fp="20,210,23.312.0,32.314.0,29.181.0,24.164.0,48.141.0,35.193.0,33.95.0,41.152.0"}
P.entries["quest:1647"] = {n="Der Foliant der Offenbarung",s="Im Tempel von Eisenschmiede sucht ein Initiand durch Dienst eine Lehre im Licht. Von einem Mentor in den äußeren Ring entsandt, sucht Ihr jemanden mit reinen Absichten, der wirklich Hilfe braucht. Dort zeigt John Turner, wie Mitgefühl und selbstlose Arbeit zum Pfad des Lichts gehören.",h="Im Tempel von Eisenschmiede sucht ein Initiand durch Dienst eine Lehre im Licht.",kw={"eisenschmiede","john turner","licht","waisenhaus","paladin","tempel","the tome of divinity","tome of divinity"},ang={["class:Paladin"]="Als Paladin lernt Ihr, dass Hingabe an das Licht mit selbstloser Hilfe für einfache Menschen in Not beginnt.",["faction:Alliance"]="Als Mitglied der Allianz seht Ihr, dass Mitgefühl, Wohltätigkeit und Fürsorge für die Schwachen zu den Tugenden gehören, die Städte wie Eisenschmiede hochhalten.",["race:Dwarf"]="Als Zwerg legt Ihr diese Prüfung in Eisenschmiede ab, Eurer eigenen Hauptstadt, in den Hallen Eurer Heimatstadt."},sec={{t="Eine Lektion in Mitgefühl",b="Initianden des Lichts, die in Eisenschmiede stationiert sind, stellen sich einer Prüfung des Mitgefühls. Ihr Mentor schickt sie in die Zwergenstadt, um jemanden zu finden, der wahrhaftig Hilfe benötigt. Die Suche verlangt Urteilsvermögen: Ihr müsst ein reines Herz, edle Absichten und ein echtes Bedürfnis nach Güte erkennen. Demütiger Dienst steht im Mittelpunkt dieser Berufung."},{t="Die Bürde von John Turner",b="Im äußeren Ring von Eisenschmiede geht ein bescheidener Arbeiter namens John Turner seinem Handwerk nach. Durch Euer Näherkommen aufgeschreckt, ruft er etwas über das Orphanage of Sturmwind und erzählt Euch dann, warum er so hart arbeitet. Lange Stunden der Plackerei trennen Turner von seiner geliebten Frau, während er dafür arbeitet, dass Waisenkinder Kleidung und Nahrung haben. Helft ihm und kehrt dann zum Tempel zurück, um Euren Weg im Licht fortzusetzen."}},faq={{q="Was ist die Quest The Tome of Divinity?",a="The Tome of Divinity ist eine heilige Prüfung für angehende Diener des Lichts in Eisenschmiede. Ihr sucht jemanden mit reinem Herzen und edlen Beweggründen auf und helft ihm, bevor Ihr Eure geistliche Unterweisung fortsetzt.",al={"was ist tome of divinity","zweck von tome of divinity","was ist diese quest"}},{q="Wer ist John Turner?",a="John Turner ist ein hart arbeitender Mann, der im äußeren Ring von Eisenschmiede seinem Handwerk nachgeht. Er arbeitet viele Stunden fern seiner geliebten Frau, um Mittel zu beschaffen und Waisen mit Nahrung und Kleidung zu versorgen.",al={"wer ist john turner","john turner eisenschmiede","wo ist john turner"}},{q="Warum schickt Euch der Mentor los, um jemanden in Not zu finden?",a="Der Mentor schickt Euch los, um Euer Verständnis von Mitgefühl und Dienst zu prüfen. Ihr lernt, edle Absichten zu erkennen, Güte zu zeigen und jenen den Weg zu weisen, die im Stillen für andere arbeiten.",al={"warum jemanden in not finden","zweck der hilfe für john turner","warum diese prüfung ablegen"}},{q="Wo befindet sich John Turner in Eisenschmiede?",a="John Turner geht am äußeren Ring von Eisenschmiede entlang, während er seiner anstrengenden täglichen Arbeit für das Waisenhaus nachgeht.",al={"wo john turner finden","john turner aufenthaltsort","wie john turner finden"}},{q="Was geschieht, nachdem Ihr mit John Turner gesprochen habt?",a="Nachdem Ihr von John Turners Notlage erfahren habt, kehrt Ihr zum Mentor im Tempel zurück. Dort denkt Ihr darüber nach, was es bedeutet, dem Licht zu folgen, und bereitet Euch auf den nächsten Schritt Eurer Berufung vor.",al={"was geschieht nach dem finden von john turner","rückkehr zum tempel des lichts","tome of divinity nächster schritt"}},{q="Warum hat John Turner etwas über ein Waisenhaus gerufen?",a="Als Ihr John Turner zum ersten Mal ansprecht, ruft er etwas über das Orphanage of Sturmwind, besinnt sich dann und entschuldigt sich. Er arbeitet, um die auf Wohltätigkeit angewiesenen Waisenkinder mit Nahrung und Kleidung zu versorgen.",al={"über welches waisenhaus ruft john turner","sturmwind waisenhaus eisenschmiede","warum hat john turner gerufen"}}},fp="20,268,22.318.0,25.380.0,35.192.0,19.181.0,53.173.0,42.107.0,45.178.0,48.197.0"}
P.entries["quest:1648"] = {n="Der Foliant der Offenbarung",s="In Eisenschmiede ruft The Tome of Divinity Diener des Lichts zu Mitgefühl auf. John Turner sucht Hilfe für das Waisenhaus in Sturmwind, das er mit seiner Frau leitet und in dem sie Kinder betreuen, die durch die Geißel ihre Eltern verloren haben. Die Prüfung verlangt von einem Initianden, Nächstenliebe über kriegerischen Ruhm zu stellen.",h="In Eisenschmiede ruft The Tome of Divinity Diener des Lichts zu Mitgefühl auf.",kw={"heiliges licht","eisenschmiede","john turner","leinenstoff","paladin","geißel waisen","sturmwind waisenhaus","the tome of divinity"},ang={["class:Paladin"]="Ein Paladin stellt sich dieser Prüfung durch selbstlose Hilfe für Unschuldige, nicht durch Stahl oder Kampf. Solches Mitgefühl ist eine Tugend im Herzen des Heiligen Lichts.",["faction:Alliance"]="Für die Allianz offenbart dies die tiefen Wunden, die die Geißel in den Heimen der Menschen hinterlassen hat, und wie sehr Sturmwind und Eisenschmiede aufeinander angewiesen sind."},sec={{t="Nächstenliebe in der Großen Schmiede",b="Für einen Initianden auf dem Pfad des Lichts verlangt die Prüfung in Eisenschmiede Nächstenliebe statt Waffengewalt. John Turner ist in die Hallen der Zwerge gekommen, um Hilfe zu suchen. Er und seine Frau leiten ein Waisenhaus in Sturmwind, wo sie Kinder betreuen, die durch die Verheerungen der Geißel im vergangenen Jahrzehnt ihre Eltern verloren haben. Seine Reise nach Eisenschmiede zeugt von den Nöten, die die einfachen Leute der Allianz teilen."},{t="Die Narben der Geißel",b="Vorräte lassen sich über Grenzen hinweg nur schwer beschaffen. Mehr Handwerker sind gekommen, um überall in Azeroth zu arbeiten, und die örtlichen Vorräte sind knapp geworden. John Turner hat wochenlang in Eisenschmiede Bürgervereinigungen und Einwohner um Hilfe gebeten, mit wenig Erfolg. Seine Frau braucht Leinenstoff, um Kleidung für die Kinder zu nähen. Ihn freigebig zu spenden, zeigt die selbstlose Hingabe, die einen Diener des Lichts im Innersten ausmacht."}},faq={{q="Wer ist John Turner?",a="John Turner ist ein menschlicher Betreuer, der mit seiner Frau ein Waisenhaus in Sturmwind leitet. Etwa einmal im Monat reist er nach Eisenschmiede, um zwergische Bürger und Händlergilden um Vorräte und Spenden für Kriegswaisen zu bitten.",al={"wer ist john turner","john turner hintergrundgeschichte","eisenschmiede turners"}},{q="Warum braucht John Turner Leinenstoff?",a="John Turner braucht Leinenstoff, damit seine Frau in Sturmwind warme Kleidung für die Waisenkinder nähen kann. Mehr Handwerker in ganz Azeroth und Veränderungen im Handel haben einfachen Stoff knapp und schwer erhältlich gemacht.",al={"warum leinen","warum braucht john turner stoff","leinen für waisenhaus"}},{q="Warum gibt es in Sturmwind so viele Waisen?",a="Die Kinder in der Obhut der Turners haben ihre Eltern bei den verheerenden Angriffen der Geißel im vergangenen Jahrzehnt verloren. Der Dritte Krieg riss Familien in den Menschenkönigreichen auseinander und ließ viele junge Menschen ohne Zuhause zurück.",al={"sturmwind waisenhaus waisen","warum gibt es waisen","geißel waisen"}},{q="Warum ist John Turner nach Eisenschmiede gereist?",a="John Turner reist über die Berge nach Eisenschmiede, um zwergische Bürger und Handelsvereinigungen um Spenden und Vorräte zu bitten, die in Sturmwind schwer erhältlich sind.",al={"warum ist john turner in eisenschmiede","warum eisenschmiede für sturmwinds waisenhaus"}},{q="Was hat die Hilfe für ein Waisenhaus mit dem Heiligen Licht zu tun?",a="Das Heilige Licht fordert Selbstlosigkeit, Barmherzigkeit und den Dienst an Verzweifelten. Einem erschöpften Betreuer bei der Versorgung von Kriegswaisen zu helfen, stellt die Demut und Nächstenliebe eines angehenden Paladins auf die Probe.",al={"was hat das mit dem licht zu tun","verbindung zu paladinen","warum machen paladine diese quest"}},{q="Warum war John Turners Reise nach Eisenschmiede so schwierig?",a="John Turners Reise kommt nur langsam voran und bringt wenig ein, weil Vorräte knapp sind und nur wenige Vereinigungen Hilfe angeboten haben. Er kann erst nach Hause zurückkehren, wenn er eine Lieferung gesichert hat.",al={"sitzt john turner fest","warum kommt die reise langsam voran"}}},fp="20,272,26.397.0,24.387.0,19.223.0,38.198.0,43.213.0,40.157.0,55.178.0,58.162.0"}
P.entries["quest:1649"] = {n="Der Foliant der Tapferkeit",s="In Sturmwind ruft der Foliant der Tapferkeit Paladine auf, Glauben und Mut zu beweisen. Duthorian Rall erwartet jene, die bereit sind, der Kirche ihr Gesuch vorzutragen.",h="In Sturmwind ruft der Foliant der Tapferkeit Paladine auf, Glauben und Mut zu beweisen.",kw={"kathedrale des lichts","kirche des heiligen lichts","duthorian rall","glaube","paladin","sturmwind","foliant der ehre","tapferkeit"},ang={["class:Paladin"]="Für Euch als Paladin ist diese Prüfung ein entscheidender Schritt in Eurer Entwicklung. Sie verbindet Euer Kampfgeschick mit diszipliniertem Glauben und selbstlosem Dienst.",["faction:Alliance"]="Als Mitglied der Allianz habt Ihr Anteil an der Stärke, die diese Prüfungen in Sturmwind in unruhigen Zeiten für Verteidigung und Geist bewahren."},sec={{t="Den Geist stählen",b="Der Foliant lehrt, dass Tapferkeit durch Entbehrungen geschmiedet wird. Sein heiliger Text vergleicht Tugenden mit kostbaren Erzen, die schon beim Fund wertvoll sind, doch geläutert werden müssen, um zu bestehen. Durch harte Prüfungen und wahre Hingabe vereint ein Paladin Glauben, Mitgefühl und Mut zu Stärke gegen die Übel, die Azeroth bedrohen."},{t="Ein Gesuch an die Kirche",b="Nachdem Ihr den Folianten gelesen habt, werdet Ihr zu Duthorian Rall geschickt, einem angesehenen Anführer der Paladine in Sturmwinds Kathedrale des Lichts. Er hört die Gesuche jener an, die sich den Prüfungen der Tapferkeit stellen wollen. Die Prüfungen sind kein bloßes Ritual. Unschuldige zu verteidigen und für die Kirche einzustehen, kann Euch das Leben kosten, und nur die Standhaften erringen Anerkennung im Orden."}},faq={{q="Welchen Zweck hat diese Quest?",a="Der Foliant der Tapferkeit führt einen Anwärter von der heiligen Lehre zu gefährlichen Prüfungen. Nach der Lektüre bitten angehende Paladine Duthorian Rall in der Kathedrale des Lichts um Prüfungen ihres Glaubens und Mutes.",al={"was ist die quest der foliant der tapferkeit","warum ist diese quest nötig","foliant der ehre zweck"}},{q="Wer ist Duthorian Rall?",a="Duthorian Rall ist ein hochrangiger Paladin und Lehrer in Sturmwinds Kathedrale des Lichts. Er beaufsichtigt die Ausbildung vielversprechender Verteidiger und die Prüfungen, durch die ein Anwärter der Kirche seinen Wert beweist.",al={"wer ist duthorian rall","duthorian rall hintergrundgeschichte","paladinlehrer kathedrale"}},{q="Warum prüft die Kirche ihre Paladine so streng?",a="Die Kirche des Heiligen Lichts prüft Paladine, damit sie Verzweiflung und Gewalt standhalten können. Schwache Entschlossenheit oder brüchiger Glaube könnten im Kampf Leben kosten, weshalb Ausbilder jeden Anwärter vor entscheidenden heiligen Missionen prüfen und stählen.",al={"warum sind paladinprüfungen gefährlich","warum tapferkeit prüfen"}},{q="Wo findet diese Prüfung statt?",a="Ihr tragt Euer Gesuch Duthorian Rall in der Kathedrale des Lichts vor, im Herzen des Kathedralenplatzes in Sturmwind.",al={"wo foliant der ehre abgeben","duthorian rall aufenthaltsort"}}},fx={["5e1febd2"]={q="Warum verweist Euch der Foliant der Ehre an Duthorian Rall?",a="Der Text des The Tome of Valor fungiert als geistiger und moralischer Wegweiser und betont, dass Tugenden wie Glaube und Mut aktiv geprüft und in eine unzerbrechliche Entschlossenheit geschmiedet werden müssen. Er schickt Euch zu Duthorian Rall in Sturmwind, weil Prüfungen nicht einfach nur gelesen werden können; ein angehender Paladin muss die Führung der Kathedrale des Lichts direkt aufsuchen, um zu beweisen, dass seine Hingabe tödlichem Opfermut standhalten kann.",al={"warum muss ich mit duthorian rall sprechen","warum duthorian rall tome of valor","warum schickt man mich zu rall"}}},fp="17,138,20.288.0,22.332.0,34.197.0,22.196.0,50.230.0,33.120.0"}
P.entries["quest:165"] = {n="Der Einsiedler",s="In Dunkelhain bittet Elaine Carevin Euch, nach Calvinius zu sehen, einem alten Einsiedler, der nicht mehr kommt, um Vorräte zu holen. Seine baufällige Hütte steht am Rand des Friedhofs von Rabenflucht.",h="In Dunkelhain bittet Elaine Carevin Euch, nach Calvinius zu sehen, einem alten Einsiedler, der nicht mehr...",kw={"calvinius","dunkelhain","dämmerwald","elaine carevin","friedhof von rabenflucht","hütte","der einsiedler"},ang={["faction:Alliance"]="Die Nachtwache hat Mühe, die Straßen zwischen Dunkelhain und Rabenflucht zu schützen. Einsiedler wie Calvinius bleiben von der Sicherheit des Ortes abgeschnitten.",["race:Human"]="Als Mensch kennt Ihr die nachbarschaftlichen Bande der Carevin Family. Sie kümmern sich um die Alten des Dämmerwalds, selbst während sich Schatten über die Region legen."},sec={{t="Ein nachbarschaftlicher Besuch",b="Elaine Carevin erinnert sich an einen alten Mann, der einst nach Dunkelhain kam, um Vorräte zu holen, dann aber nicht mehr erschien. Da die Straßen des Dämmerwalds gefährlich sind, bittet sie Euch, seine Hütte beim Friedhof von Rabenflucht aufzusuchen und herauszufinden, ob er wohlauf ist."},{t="Der Einsiedler von Rabenflucht",b="Bei der Hütte findet Ihr Calvinius lebend vor. Er schmunzelt über die Sorge der Carevins und sagt, sein Alter und die Ungeheuer im Wald hätten ihn vom Ort ferngehalten. Froh über einen tüchtigen Reisenden vor seiner Tür, bittet er Euch gleich um Hilfe bei ein paar Besorgungen."}},faq={{q="Wer erteilt diesen Auftrag?",a="Elaine Carevin, die in Dunkelhain lebt, bittet Euch, nach einem alten Einsiedler zu sehen, der einst in den Ort kam, um Vorräte zu holen.",al={"wer vergibt der einsiedler","wo beginnt der einsiedler","elaine carevin quest"}},{q="Wo befindet sich der Einsiedler?",a="Calvinius lebt in einer Holzhütte am nördlichen Rand des Friedhofs von Rabenflucht im westlichen Dämmerwald.",al={"wo ist calvinius","einsiedler standort dämmerwald","hütte bei rabenflucht"}},{q="Warum machte sich Elaine Carevin Sorgen um ihn?",a="Calvinius kam früher nach Dunkelhain, um Vorräte zu holen, blieb dann aber aus. Wegen der wilden Tiere und Untoten auf den Straßen fürchtete Elaine, er sei gestorben.",al={"warum nach calvinius sehen","warum ist elaine besorgt","was ist dem alten mann passiert"}},{q="Ist Calvinius tatsächlich in Gefahr, wenn Ihr ihn findet?",a="Nein. Calvinius lebt, als Ihr seine Hütte erreicht. Er sagt, sein Alter und die gefährlichen Straßen hätten das Reisen zu beschwerlich gemacht.",al={"ist calvinius wohlauf","liegt der einsiedler im sterben","wurde der einsiedler angegriffen"}},{q="Warum lebt jemand freiwillig direkt neben dem Friedhof von Rabenflucht?",a="Calvinius sagt, er ziehe die Abgeschiedenheit vor. Sein Zuhause neben einem der am stärksten von Nekromantie verderbten Friedhöfe der Östlichen Königreiche beunruhigt viele Reisende.",al={"warum bei rabenflucht leben","calvinius friedhofshütte","warum ist der einsiedler bei gräbern"}},{q="Worum bittet Calvinius, sobald Ihr ihn erreicht?",a="Calvinius bittet Euch gleich, bei ein paar Besorgungen im Wald zu helfen.",al={"was will calvinius","einsiedler folgequest","was kommt nach der einsiedler"}}},fx={e8a34d53={q="Warum bittet Elaine Carevin einen Abenteurer, nach Calvinius zu sehen?",a="Die örtliche The Nachtwache von Dunkelhain ist bereits gefährlich dünn besetzt, um den Außenposten gegen gefräßige Bestien, wilde Worgen und die ruhelosen Toten zu halten. Sich tief in die westlichen Wälder in Richtung Raven Hill zu wagen, nur um nach einem exzentrischen Einsiedler zu sehen, ist ein Luxus, den sich die Stadtwachen nicht leisten können, was fähige Reisende zur einzigen wirklichen Option macht.",al={"warum schickt man mich","warum braucht elaine einen abenteurer","warum sehen die wachen nicht nach dem einsiedler"}}},fp="10,181,21.223.0,25.236.0,23.110.0,28.100.0,41.133.0,52.110.0,66.157.0,49.73.0"}
P.entries["quest:1650"] = {n="Der Foliant der Tapferkeit",s="Duthorian Rall schickt Euch, um Daphne Stillbrunn an Westfalls ferner Küste zu beschützen. Ihr Mann ist fort, und Banditen der Defias bedrohen ihren Hof.",h="Duthorian Rall schickt Euch, um Daphne Stillbrunn an Westfalls ferner Küste zu beschützen.",kw={"daphne stillbrunn","bruderschaft der defias","duthorian rall","jordan stillbrunn","die endlose küste","sturmwind","foliant der ehre","westfall"},ang={["class:Paladin"]="Als Paladin verlasst Ihr die Sicherheit von Sturmwinds Kathedrale, um die Schutzlosen zu beschützen und Eure Tapferkeit zu beweisen.",["faction:Alliance"]="Der Hof der Stillbrunns zeigt, wie weit Westfall dem Schutz Sturmwinds entglitten ist. Die Menschen auf dem Land müssen sich den Defias allein stellen."},sec={{t="Ein Ruf zu den Waffen",b="In Sturmwinds Kathedrale des Lichts prüft Duthorian Rall jene, die Paladine werden wollen. Er fordert sie auf, die Menschen des Reiches zu verteidigen. Nun habt Ihr den Mantel der Tapferkeit angelegt und müsst diese Ideale dort in die Tat umsetzen, wo Gesetz und Obrigkeit versagt haben."},{t="Gefahr an der Endlosen Küste",b="Daphne Stillbrunn und ihr Mann Jordan unterhalten einen Außenposten an Westfalls abgelegener Endloser Küste. Jordan ist in Eisenschmiede, um sich mit Zwergenschmieden zu beraten, während die Bruderschaft der Defias ihr Unwesen treibt. Deshalb schickt Duthorian Euch nach Westen, um Daphne zu beschützen, bevor Diebe ihren Hof überrennen."}},faq={{q="Warum ist Daphne Stillbrunn allein in Westfall?",a="Ihr Mann, Jordan Stillbrunn, ist nach Eisenschmiede gereist, um sich mit anderen Schmieden zu beraten. Während seiner Abwesenheit muss Daphne die zunehmenden Angriffe der Defias auf ihr Anwesen an der Küste allein abwehren.",al={"wo ist daphnes mann","warum ist jordan stillbrunn fort","daphne stillbrunn allein"}},{q="Wer erteilt dem Paladin diesen Auftrag?",a="Duthorian Rall erteilt ihn. Er bildet in Sturmwinds Kathedrale des Lichts Paladine aus und gibt den Befehl, sobald Ihr Euch für die Prüfungen der Tapferkeit bereit erwiesen habt.",al={"wer vergibt foliant der ehre 1650","questgeber foliant der ehre","duthorian rall quest"}},{q="Wo ist Daphne Stillbrunn zu finden?",a="Daphne lebt in einem kleinen Häuschen im äußersten Süden der Endlosen Küste, an der Küste im Südwesten Westfalls.",al={"wo ist daphne stillbrunn","daphne stillbrunn standort","daphne stillbrunn finden"}},{q="Ist Daphne völlig hilflos, wenn Ihr eintrefft?",a="Nein. Bis Ihr ihre Veranda erreicht, hat Daphne bei der Verteidigung des Hofes bereits ein halbes Dutzend Banditen der Defias mit ihrer eigenen Waffe getötet.",al={"kann daphne kämpfen","ist daphne schutzlos","daphne stillbrunn im kampf"}},{q="Welche Gefahr bedroht das Heim der Stillbrunns?",a="Die Bruderschaft der Defias bedroht das Heim der Stillbrunns. Die Bruderschaft hat weite Teile Westfalls überrannt und bedrängt weiterhin den abgelegenen Hof an der Küste, um das Land an sich zu reißen und die verbliebenen Vorräte und Besitztümer zu plündern.",al={"wer greift daphne an","defias in westfall","feinde auf dem hof der stillbrunns"}},{q="Wie fügt sich dieser Auftrag in die Questreihe um den Folianten der Ehre ein?",a="Die Tapferkeit eines Paladins bemisst sich an seiner Opferbereitschaft und der Verteidigung der Schutzlosen. Daphne vor marodierenden Banditen zu beschützen, setzt Rechtschaffenheit in die Tat um.",al={"warum muss man daphne helfen","foliant der ehre zweck der prüfung","bedeutung dieser quest"}}},fx={ef242344={q="Warum schickt Duthorian Rall Euch zu Daphne Stillbrunn?",a="Duthorian Rall zielt darauf ab, Eure Entschlossenheit und Hingabe an die Tugenden des Lichts zu prüfen. Während ihr Ehemann Jordan nach Eisenschmiede reist, um Schmiedewissen zu handeln, wurde Daphne Stillbrunn in Westfall allein gelassen, gerade als The Defias Brotherhood die Küste überrennt. Euch loszuschicken, um eine ungeschützte Zivilistin zu verteidigen, dient sowohl als rechtschaffene Pflicht als auch als wahre Prüfung der Tapferkeit.",al={"warum will duthorian rall das","duthorian rall motiv","warum paladin zu daphne schicken"}},["49096f91"]={q="Warum benötigt Duthorian Rall Euch anstelle der Stadtwache von Sturmwind?",a="Westfall liegt weit außerhalb der Sicherheit der Mauern von Sturmwind, von der Krone vernachlässigt und von Banditen überrannt. Die Stadtwache ist durch die Verteidigung von Elwynn und die Bewältigung städtischer Unruhen überlastet. Für die Kirche des Heiligen Lichts ist der Schutz wehrloser Siedler die feierliche Berufung der Paladine, was diese gefährliche Mission zum idealen Schmelztiegel macht, um zu beweisen, dass Ihr des The Tome of Valor würdig seid.",al={"warum ich duthorian rall","warum keine wachen zu daphne schicken","warum einen initianden schicken"}}},fp="17,146,14.254.0,22.285.0,41.169.0,37.148.0,35.104.0,46.141.0,42.200.0,52.153.0"}
P.entries["quest:1651"] = {n="Der Foliant der Tapferkeit",s="Auf ihrem Hof in Westfall ruft Daphne Stillbrunn um Hilfe, während die Bruderschaft der Defias näher rückt. Ein Paladin muss ihrem Hilferuf folgen.",h="Auf ihrem Hof in Westfall ruft Daphne Stillbrunn um Hilfe, während die Bruderschaft der Defias näher rückt.",kw={"daphne stillbrunn","bruderschaft der defias","defias-räuber","paladinprüfung","foliant der ehre","westfall"},ang={["class:Paladin"]="Als Paladin werdet Ihr als standhafter Beschützer geprüft. Indem Ihr neben Daphne die Stellung haltet, setzt Ihr Tapferkeit in die Tat um und bewahrt Unschuldige vor Schaden.",["faction:Alliance"]="Sturmwinds Garnison ist überlastet und kann die ländlichen Gehöfte nicht bewachen. Der Schutz der treuen Bürger von Westfall fällt einzelnen Helden zu."},sec={{t="Standhalten im Staub",b="Die Bruderschaft der Defias kämpft noch immer um das Land rund um Daphnes Gehöft. Frühere Gefechte haben die Gefahr nicht gebannt, und ein weiterer Angriff wird erwartet. Ihr werdet entsandt, um neben ihrem Haus die Stellung zu halten. Es gibt keinen Rückzug. Euer Streben nach den Tugenden im Folianten der Ehre steht nun vor einer Mutprobe."},{t="Die Prüfung der Tapferkeit",b="Daphne hat nur ihre eigene Schusswaffe, während Ihr den Segen des Heiligen Lichts anrufen könnt. Welle um Welle greifen Defias-Räuber an, und der Kampf prüft, ob Ihr unter erdrückendem Druck einen schutzbedürftigen Menschen verteidigen könnt. Wahre Tapferkeit bedeutet, sich zwischen unschuldige Zivilisten und skrupellose Gewalt zu stellen, selbst wenn die Gefahr Euch bedrängt."}},faq={{q="Wer ist Daphne Stillbrunn?",a="Daphne Stillbrunn ist eine menschliche Siedlerin im Grasland von Westfall. Die Bruderschaft der Defias dringt oft auf ihr Land vor, doch sie weigert sich zu gehen und wehrt sich gegen ihre Überfälle.",al={"daphne stillbrunn","wer ist daphne","stillbrunn westfall"}},{q="Warum greifen die Defias gerade diesen Hof an?",a="Die Bruderschaft der Defias hat weite Teile des ländlichen Westfall eingenommen und die Bauern vertrieben oder zur Unterwerfung gezwungen. Daphnes Mann Jordan ist in Eisenschmiede, sodass sie allein und ungeschützt ist. Die Defias wollen ihr Land.",al={"warum greifen defias an","defias überfall daphne","warum stillbrunn angreifen"}},{q="Was ist der Foliant der Ehre?",a="Der Foliant der Tapferkeit ist eine heilige Schrift, mit der die Kirche des Heiligen Lichts junge Paladine anleitet. Angehende Ritter stellen sich im ganzen Königreich körperlichen und geistigen Prüfungen, um nach seinen Tugenden zu leben.",al={"was ist der foliant der ehre","foliant der ehre quest","paladin foliant der ehre"}},{q="Was geschieht, wenn Daphne während der Schlacht fällt?",a="Wenn Daphne Stillbrunn im Kampf fällt, scheitert die Prüfung. Tapferkeit verlangt von Euch, ihr Leben ebenso wie Euer eigenes vor dem Angriff der Banditen zu schützen.",al={"kann daphne sterben","daphne stillbrunn stirbt"}},{q="Wo findet dieser Angriff statt?",a="Der Angriff findet vor Daphne Stillbrunns Bauernhaus statt. Ihr kleiner Hof liegt in den Dolchhügeln mit Blick auf die Endlose Küste im Süden von Westfall.",al={"daphne stillbrunn standort","wo ist der hof"}},{q="Was folgt auf die Verteidigung des Hofes?",a="Nachdem Ihr Euren Mut bewiesen und die Defias-Räuber vertrieben habt, erkennt Daphne Eure Hingabe an. Sie weist Euch den Weg zum nächsten Abschnitt Eurer Paladinprüfungen.",al={"nächste quest foliant der ehre","nach daphnes verteidigung"}}},fx={dca50aad={q="Warum braucht Daphne Stillbrunn Eure Hilfe bei der Verteidigung der Farm?",a="Westfall ist größtenteils von der Armee von Sturmwind verlassen, sodass die Siedler sich gegen die aufkommende Welle von Gesetzlosen selbst verteidigen müssen. Obwohl Daphne entschlossen ist, ihr Zuhause zu verteidigen, und eine Schusswaffe im Haus hat, kann sie nicht allein gegen einen organisierten Angriff bestehen. Eine frühere Welle hat sie bereits auf die Probe gestellt, und sie weiß, dass der kommende Überfall weit mehr Gesetzlose schicken wird, als eine einzelne Siedlerin jemals überleben könnte.",al={"warum daphne stillbrunn helfen","warum kann daphne sich nicht selbst verteidigen","daphne stillbrunn hilfe warum"}},["3da31dda"]={q="Warum will Daphne Stillbrunn standhalten?",a="Diese Farm repräsentiert Daphne Stillbrunns Lebensgrundlage und ihre sture Weigerung, sich von Gesetzlosen vertreiben zu lassen. Anstatt zu fliehen oder ihr Land an Briganten abzutreten, die Westfall überrannt haben, entscheidet sie sich dazu, standzuhalten. Ihr Gehöft zu schützen ist eine Frage des reinen Überlebens und Stolzes; wenn sie hier nachgibt, verliert sie alles, was sie sich aufgebaut hat.",al={"daphne stillbrunn motiv","warum defias bei daphne bekämpfen","warum will daphne bleiben"}},["7af5f29f"]={q="Wer sind die Angreifer der The Defias Brotherhood, die Daphne Stillbrunns Farm attackieren?",a="Die Angreifer sind Defias-Plünderer, Mitglieder der weit verbreiteten kriminellen Bruderschaft, die Westfall terrorisiert. Sie agieren in der gesamten Region, beschlagnahmen verlassene Gehöfte, erpressen Bewohner und vertreiben gewaltsam jeden, der sich ihrer Präsenz widersetzt. Daphnes Weigerung, ihr Zuhause aufzugeben, macht ihr Gehöft zu einem erstklassigen Ziel für einen koordinierten Überfall, um jeglichen verbleibenden zivilen Widerstand zu zerschlagen.",al={"wer sind die angreifer","was sind defias-plünderer","defias greifen stilwell-farm an"}}},fp="17,120,19.298.0,18.330.0,23.177.0,48.221.0,26.191.0,47.132.0,34.148.0,36.159.0"}
P.entries["quest:1652"] = {n="Der Foliant der Tapferkeit",s="In Sturmwinds Kathedrale des Lichts berichtet Ihr Duthorian Rall, dass Daphne Stillbrunn nach der Verteidigung ihres Hofs in Westfall in Sicherheit ist. Euer Mut erfüllt die Tapferkeitsprüfungen der Kirche und ihren Auftrag, die Unschuldigen ohne Rücksicht auf Euch selbst zu schützen.",h="In Sturmwinds Kathedrale des Lichts berichtet Ihr Duthorian Rall, dass Daphne Stillbrunn nach der...",kw={"kathedrale des lichts","daphne stillbrunn","duthorian rall","eisenschmiede","jordan stillbrunn","sturmwind","foliant der ehre","westfall"},ang={["class:Paladin"]="Als Paladin schließt Ihr mit Eurem Bericht an Duthorian Rall Eure Lektion in Tapferkeit ab und zeigt die Selbstlosigkeit, die von einem heiligen Beschützer der Allianz erwartet wird.",["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr erkennen, wie die Sorgen der Stilwells die menschlichen Äcker Westfalls mit den zwergischen Werkstätten Eisenschmiedes verbinden. Ihre Geschichte zeigt, wie sehr die Allianz auf gegenseitige Hilfe zwischen fernen Ländern angewiesen ist."},sec={{t="Ein heiliger Schild",b="Eure Verteidigung zeigt, dass Ihr Euch zwischen die Gefahr und die Wehrlosen stellen könnt, wie die Kirche es von einem angehenden Paladin erwartet. Der Hof hält stand, und Daphne ist vor den Banditen sicher, die sie bedrohten."},{t="Bande zwischen Königreichen",b="Jordan Stillbrunn, Daphnes Ehemann, bleibt in Eisenschmiede und stellt seine weithin geschätzte Handwerkskunst in den Dienst der Allianz. Duthorian Rall bereitet eine Nachricht nach Norden vor, damit Jordan sich auf seine Arbeit konzentrieren kann, im Wissen, dass seine Familie beschützt wird."}},faq={{q="Wer ist Duthorian Rall?",a="Duthorian Rall ist ein ranghoher Paladinlehrer an Sturmwinds Kathedrale des Lichts. Er führt junge Paladine durch geistige und kriegerische Prüfungen und lehrt sie Tapferkeit, Rechtschaffenheit und Demut.",al={"duthorian rall","wer ist duthorian","paladinlehrer sturmwind"}},{q="Warum war Daphne Stillbrunn in Gefahr?",a="Banditen belagerten Daphne Stillbrunns abgelegenen Bauernhof in Westfall. Ihr Ehemann Jordan war fort und arbeitete in Eisenschmiede.",al={"daphne stillbrunn","hof der stilwells","wer griff daphne an"}},{q="Wer ist Jordan Stillbrunn?",a="Jordan Stillbrunn ist Daphnes Ehemann, ein geschickter Schmied und Handwerker. Er ist in Eisenschmiede und hilft der Allianz mit seiner Arbeit, während die Kirche seine Frau daheim beschützt.",al={"jordan stillbrunn","daphnes ehemann","jordan eisenschmiede"}},{q="Was ist der Foliant der Ehre?",a="Der Foliant der Tapferkeit ist ein heiliges Lehrbuch, dessen Lehren mit praktischen Prüfungen der Kathedrale des Lichts verbunden sind. Darin beweisen Paladine ihren Mut, indem sie sich der Dunkelheit stellen und die Schutzbedürftigen unter Einsatz ihres eigenen Wohls beschützen.",al={"foliant der ehre bedeutung","was ist der foliant der ehre"}},{q="Was folgt nach Abschluss dieser Prüfung?",a="Nachdem Duthorian Rall Eure Verteidigung von Daphne Stillbrunn anerkannt hat, weist er Euch den Weg zu The Test of Righteousness, dem nächsten Schritt Eurer geistigen und kriegerischen Entwicklung.",al={"nächste quest nach foliant der ehre","was kommt als nächstes"}},{q="Warum kümmert sich die Kirche um den Hof der Stilwells?",a="Die Kirche kümmert sich um den Hof der Stilwells, weil Daphne und Jordan ihr durch treue Dienste und Handwerkskunst geholfen haben. Daphne während Jordans Abwesenheit zu beschützen, erfüllt das Versprechen der Kirche, für die Ihren zu sorgen.",al={"warum hilft die kirche daphne","kirche und stilwells"}}},fx={["9332b34b"]={q="Warum möchte Daphne Stillbrunn, dass Ihr Duthorian Rall Bericht erstattet?",a="Daphne möchte, dass Duthorian Rall weiß, dass sie in Sicherheit ist und das Gehöft den Angriff überlebt hat, aber ihre größte Sorge gilt ihrem Ehemann Jordan. Jordan arbeitet fern in Eisenschmiede, und Daphne weiß, dass er sich endlos Sorgen machen wird, bis er Nachrichten von zu Hause hört. Indem Ihr der Kirche des Lichts in Sturmwind Bericht erstattet, kann Duthorian Nachricht nach Eisenschmiede senden, um Jordan zu versichern, dass seine Frau und sein Zuhause in Sicherheit sind.",al={"warum zu duthorian schicken","daphne stillbrunn motiv","warum mit duthorian rall sprechen"}}},fp="17,251,15.196.0,21.217.0,22.185.0,34.110.0,23.171.0,26.211.0,39.171.0,54.217.0"}
P.entries["quest:1653"] = {n="Die Prüfung der Rechtschaffenheit",s="Am Kathedralenplatz schickt Euch Duthorian Rall mit Neuigkeiten für Jordan Stillbrunn nach Eisenschmiede. Seine Frau Daphne hat den Angriff der Defias in Westfall überlebt.",h="Am Kathedralenplatz schickt Euch Duthorian Rall mit Neuigkeiten für Jordan Stillbrunn nach Eisenschmiede.",kw={"daphne stillbrunn","bruderschaft der defias","dun morogh","duthorian rall","eisenschmiede","jordan stillbrunn","sturmwind","prüfung der rechtschaffenheit"},ang={["class:Paladin"]="Als Paladin geht Ihr vom Schutz der Schwachen dazu über, heilige Werkzeuge zu schmieden, um das Böse in den Landen der Allianz zu tilgen.",["faction:Alliance"]="Als Mitglied der Allianz seht Ihr, wie die einfachen Leute in Westfall gegen die Defias kämpfen, während königliche Berater in Sturmwind Maßnahmen hinauszögern.",["profession:Blacksmithing"]="Als Schmied erkennt Ihr Jordans Hingabe in seiner Arbeit am Amboss ebenso deutlich wie in einer geweihten Klinge, die im Kampf geführt wird."},sec={{t="Ein Bote froher Kunde",b="Ihr habt Daphne Stillbrunn auf ihrem Gehöft in Westfall beschützt, als Gesetzlose der Defias angriffen, und sie hat überlebt. Ihr Mann war nach Eisenschmiede aufgebrochen und fürchtete, seine Familie sei in Gefahr. Nun schickt Rall Euch, um Jordan persönlich zu berichten, damit er erfährt, was Daphne widerfahren ist."},{t="Der Schmied von Dun Morogh",b="Jordan Stillbrunn hoffte einst, sich den Paladinen anzuschließen, entschied sich aber für das Handwerk seines Vaters und wurde ein Meisterwaffenschmied. Er arbeitet an einem Amboss vor den Toren von Eisenschmiede und hält an seinem Glauben fest, während er Waffen formt. Als Ihr ihm berichtet, dass Daphne überlebt hat, bewegt ihn seine Dankbarkeit dazu, Euch beim Schmieden einer gesegneten Waffe der Rechtschaffenheit zu helfen."}},faq={{q="Wer ist Jordan Stillbrunn?",a="Jordan Stillbrunn ist ein frommer Waffenschmied, der vor den Toren von Eisenschmiede arbeitet. Einst studierte er an der Seite von Paladinen die Wege des Lichts, entschied sich dann aber für das Handwerk seines Vaters.",al={"jordan stillbrunn","wer ist jordan","der schmied in eisenschmiede"}},{q="Warum war Jordans Frau in Gefahr?",a="Daphne Stillbrunn lebt auf einem Gehöft in Westfall, wo Gesetzlose der Bruderschaft der Defias die Menschen bedrohen. Jordan fürchtete einen Angriff, als er nach Eisenschmiede aufbrach. Banditen stürmten den Hof, doch Paladin-Initianden vertrieben sie.",al={"daphne stillbrunn gefahr","was geschah mit jordans frau","warum griffen die defias an"}},{q="Wo ist Jordan Stillbrunn zu finden?",a="Jordan Stillbrunn arbeitet vor den Haupttoren von Eisenschmiede in Dun Morogh. Er zieht die Bergluft der Großen Schmiede im Inneren der Stadt vor.",al={"wo ist jordan stillbrunn","stillbrunn aufenthaltsort","jordan eisenschmiede aufenthaltsort"}},{q="Warum schickt Duthorian Rall den Spieler nach Eisenschmiede?",a="Duthorian Rall schickt Euch, um Jordan zu berichten, dass Daphne den Angriff der Defias überlebt hat. Die Reise führt Euch zu einem Meisterschmied, der Euch bei der Herstellung einer heiligen Paladinwaffe anleiten kann.",al={"warum nach eisenschmiede gehen","duthorian rall auftrag","grund für die nachricht"}},{q="Was folgt nach dem Gespräch mit Jordan?",a="Nachdem Jordan die Neuigkeiten gehört hat, bietet er Euch an, beim Schmieden eines heiligen Kriegshammers zu helfen. Er bittet Euch, seltene Materialien und geweihte Relikte aus fernen Landen zu sammeln.",al={"prüfung der rechtschaffenheit nächster schritt","was will jordan","nach dem gespräch mit jordan"}},{q="Was hält Jordan von der Bedrohung durch die Defias?",a="Jordan ist über den Rat von Sturmwind und dessen Untätigkeit erzürnt. Die Bruderschaft der Defias plagt Westfall schon seit langer Zeit. Er hofft, dass Angriffe auf die Gehöfte ehrlicher Leute die Regenten des jungen Königs zwingen werden, sich der Krise zu stellen.",al={"jordans meinung zu den defias","stillbrunn königliche berater","defias in westfall"}}},fx={c7e3478b={q="Warum schickt Duthorian Rall Euch zu Jordan Stillbrunn?",a="Jordan Stillbrunn reiste nach Eisenschmiede, ohne zu wissen, ob sein Zuhause und seine Frau den Überfall der Defias in Westfall überlebt hatten. Nachdem er Eure Tapferkeit durch die Verteidigung seiner Familie geprüft hat, möchte Duthorian Rall dem Schmied Seelenfrieden verschaffen. Indem er Euch schickt, überbringt Ihr die frohe Botschaft direkt von dem Paladin, der dem Ruf gefolgt ist.",al={"warum schickt man mich zu jordan","duthorian rall motiv","warum jordan stillbrunn besuchen"}},["26f62cea"]={q="Warum wählt Duthorian Rall Euch für diesen Botengang aus anstatt einen gewöhnlichen Boten?",a="Ihr seid derjenige, der tatsächlich die Defias abgewehrt hat, um Jordans Frau zu retten. Anstatt einem unpersönlichen Kurier zu vertrauen, glaubt Duthorian, dass Jordan es verdient, die frohe Kunde direkt vom Retter seiner Familie zu hören, was Eure Ausbildung unter dem Licht mit einem Verbündeten fortsetzt, der dem Paladinorden zutiefst wohlgesinnt ist.",al={"warum mich anstatt einen boten schicken","warum überbringe ich die nachricht","warum ich prüfung der rechtschaffenheit"}}},fp="25,145,24.257.0,23.314.0,23.165.0,32.219.0,35.131.0,53.173.0,38.152.1,45.210.0"}
P.entries["quest:1654"] = {n="Die Prüfung der Rechtschaffenheit",s="Jordan Stillbrunn plant eine heilige Waffe für einen Paladin, der des Lichts würdig ist. Der Schmied aus Eisenschmiede braucht seltene Materialien aus fernen Landen, darunter seinen verlorenen Familienhammer.",h="Jordan Stillbrunn plant eine heilige Waffe für einen Paladin, der des Lichts würdig ist.",kw={"bailor's erz","dun morogh","eisenschmiede","jordan stillbrunn","kor gem","paladinwaffe","die prüfung der rechtschaffenheit","whitestone oak"},ang={["class:Paladin"]="Als Paladin stellt Ihr Euch einer Prüfung der Hingabe und Opferbereitschaft für eine Waffe, die geschmiedet wird, um das Licht zu kanalisieren.",["faction:Alliance"]="Als Mitglied der Allianz verlasst Ihr Euch auf menschliche Handwerkskunst und die Besitzungen der Allianz in Khaz Modan und darüber hinaus, um Verteidiger gegen aufkommende finstere Bedrohungen zu wappnen.",["profession:Blacksmithing"]="Als Schmied seht Ihr, wie Jordan Stillbrunn ein wiedergefundenes Erbstück als Werkzeug mit gereinigten arkanen und mineralischen Bestandteilen vereint, um eine heilige Reliquie zu fertigen."},sec={{t="Ein heiliger Auftrag",b="Vor den Toren von Eisenschmiede kann Jordan Stillbrunn die Waffe des Paladins nicht allein schmieden. Ihr beschafft die Materialien, die sein Handwerk erfordert."},{t="Bestandteile der Weihe",b="Jordan Stillbrunn braucht vier Dinge für die Waffe: Weißsteineichenholz, veredeltes Erz von Meistergoldsuchern, einen Geläuterten Koredelstein und seinen Schmiedehammer. Er ließ den Hammer bei seiner Flucht aus Burg Shadowfang zurück. Um alle vier zu finden, müsst Ihr Euch Gefahren in den Östlichen Königreichen und darüber hinaus stellen."},{t="Das Erbe des Schmieds",b="Jordan Stillbrunn braucht den Hammer seines Vaters für die Arbeit. Das Erbstück ist mit seinem Handwerk und seiner Familienlinie verbunden. Mit dem wiedergefundenen Hammer und einem seltenen, geläuterten Kor Gem kann Jordan seine seit Jahren gehegten Pläne verfolgen und ein Werkzeug der Gerechtigkeit schmieden."}},faq={{q="Welchen Zweck hat diese Quest?",a="Jordan Stillbrunn braucht seltene Materialien aus dem ganzen Reich, um eine heilige Waffe für aufstrebende Paladine zu schmieden. Sie zu beschaffen, stellt ihre Hingabe und Opferbereitschaft auf die Probe.",al={"was bewirkt diese quest","warum die prüfung der rechtschaffenheit machen","ziel der prüfung der rechtschaffenheit"}},{q="Wer ist Jordan Stillbrunn?",a="Jordan Stillbrunn ist ein menschlicher Waffenschmied vor den Toren von Eisenschmiede in Dun Morogh. Er plant eine heilige Waffe für Paladine und sucht den verlorenen Schmiedehammer seines Vaters.",al={"jordan stillbrunn hintergrundgeschichte","wer ist der schmied vor eisenschmiede","stillbrunn hintergrund"}},{q="Welche Materialien werden zum Schmieden der Waffe benötigt?",a="Jordan braucht Jordans Schmiedehammer, Weißsteineichenholz, Bailor's Refined Ore Shipment und einen Geläuterten Koredelstein.",al={"welche gegenstände werden benötigt","materialien für jordan stillbrunn","zutaten für die prüfung der rechtschaffenheit"}},{q="Warum ist Jordans Hammer ihm so wichtig?",a="Jordans Hammer gehörte seinem Vater. Die Bergung dieses Familienerbstücks bringt es in Jordans Schmiede zurück und gibt ihm ein Werkzeug, das mit seinem Handwerk und seiner Abstammung verbunden ist.",al={"warum der hammer seines vaters","jordans schmiedehammer hintergrundgeschichte","stillbrunn hammer geschichte"}},{q="Was ist ein Kor Gem?",a="Ein Kor Gem ist ein seltener, mächtiger Stein. Von verderblichen Einflüssen gereinigt, kann er die Macht bündeln, mit der eine heilige Waffe geweiht wird.",al={"kor gem hintergrundgeschichte","was ist ein kor gem","geläuterter koredelstein"}},{q="Wo fertigt Jordan Stillbrunn diese Waffe?",a="Jordan Stillbrunn arbeitet direkt vor den verschneiten Toren von Eisenschmiede in den Bergen von Dun Morogh.",al={"jordan stillbrunn standort","wo ist jordan","wo wird das abgegeben"}}},fx={c050f299={q="Warum möchte Jordan Stillbrunn, dass dies erledigt wird?",a="Jordan hegte schon lange den Wunsch, eine großartige Waffe der Rechtschaffenheit zu erschaffen, doch es fehlten ihm sowohl die seltenen Materialien als auch die Mittel, um durch die Welt zu reisen und sie zu beschaffen. Durch den Zusammenschluss mit Euch hat er nun endlich die Gelegenheit, den verlorenen Hammer seiner Familie wiederzuerlangen und sein bisher bestes Meisterwerk zu schmieden, wobei er gleichzeitig einen Verfechter des Lichts belohnt.",al={"jordan stillbrunns motiv","warum will jordan diese gegenstände?","jordan stillbrunn warum"}},["4a2d94b4"]={q="Wozu dient Jordans Schmiedehammer?",a="Jordans Schmiedehammer ist ein Erbstück, das von Jordans Vater an ihn weitergegeben wurde. Jordan benötigt dieses vertraute Werkzeug, bevor er sich an die komplizierte und anspruchsvolle Arbeit machen kann, Eure heilige Waffe zu schmieden.",al={"was ist jordans schmiedehammer?","zweck von jordans schmiedehammer","warum wird jordans hammer benötigt?"}},deb75c2f={q="Wozu dient Jordans aufbereitete Erzlieferung?",a="Diese aufbereitete Erzlieferung liefert das gehärtete Metall, das für den Kopf Eurer Waffe benötigt wird. Gewöhnliches Eisen kann die heiligen Energien eines Paladins nicht leiten, weshalb hochwertiges, aufbereitetes Erz unerlässlich ist, um sowohl schwerem Kampf als auch dem Licht selbst standzuhalten.",al={"verwendung von jordans aufbereiteter erzlieferung","wozu dient das aufbereitete erz?","erzlieferung jordan"}},a71ac5b5={q="Wozu dient das Weißsteineichenholz?",a="Weißsteineichenholz ist ein dichtes, außergewöhnlich haltbares Holz, das für die Herstellung widerstandsfähiger Stiele geschätzt wird. Jordan benötigt dieses Holz, um einen stabilen Griff zu schnitzen, der den schweren geschmiedeten Hammerkopf tragen kann, ohne unter der gewaltigen heiligen Kraft zu zersplittern.",al={"verwendung weißsteineichenholz","warum weißsteineichenholz?","zweck von weißsteineichenholz"}},ab9031e0={q="Wozu dient der Geläuterte Koredelstein?",a="Ein Koredelstein besitzt eine angeborene Affinität zur Kanalisierung magischer und spiritueller Kräfte. Sobald er von dunklen Makeln gereinigt und geläutert wurde, dient der Edelstein als heiliger Fokuspunkt, der in die Waffe eingesetzt wird und es Euch ermöglicht, das Licht durch Eure Schläge zu bündeln und zu projizieren.",al={"verwendung geläuterter koredelstein","wozu dient der koredelstein?","warum geläuterter koredelstein?"}},c2f50c47={q="Warum muss Jordan Stillbrunn, dass Ihr die Materialien sammelt?",a="Jordan ist ein einfacher Schmied, der an seine Schmiede außerhalb von Eisenschmiede gebunden ist. Ihm fehlt die Kampfausbildung und die Freiheit, sich in gefährliche Gebiete in ganz Azeroth zu begeben. Die benötigten Gegenstände sind an weit entfernten, gefährlichen Orten verstreut, was einen geschickten Paladin des Lichts erfordert, der in der Lage ist, Gefahren zu trotzen, um sie zu bergen.",al={"warum ich jordan stillbrunn","warum braucht jordan hilfe?","warum kann jordan das erz nicht besorgen?"}}},fp="25,173,19.132.0,26.290.0,20.247.1,34.153.0,23.162.0,46.116.0,43.152.0,18.126.0,45.90.0"}
P.entries["quest:1655"] = {n="Bailors Erzlieferung",s="In Loch Modan ist Bailors Erzlieferung für Jordan Stillbrunns geheiligte Waffe bestimmt. Mo'grosh-Oger plünderten die Legierung auf der Straße aus dem Sumpfland.",h="In Loch Modan ist Bailors Erzlieferung für Jordan Stillbrunns geheiligte Waffe bestimmt.",kw={"bailor","jordan stillbrunn","loch modan","mo'grosh","oger","erz","lieferung","steinhand","test of righteousness"},ang={["class:Paladin"]="Als Paladin stellt Ihr Euch während des Test of Righteousness gefährlichen Unholden und beschafft Materialien für Euren heiligen Kriegshammer.",["faction:Alliance"]="Mo'grosh-Oger im Nordosten von Loch Modan bedrohen Nachschubwege und Karawanen, die durch den Pass zum Sumpfland ziehen.",["profession:Blacksmithing"]="Bailors eigens angefertigte Legierung erfüllt die strengen Anforderungen an die Metallverarbeitung, die Jordan Stillbrunn für seine legendären Waffen stellt."},sec={{t="Eine überfallene Karawane",b="Jordan Stillbrunn wartet auf Erz, das sein alter Freund Bailor Steinhand veredelt hat, doch die Lieferung erreicht Eisenschmiede nie. Als die Karawane vom Sumpfland nach Süden in Richtung Loch Modan zieht, überfallen Mo'grosh-Oger sie und schlachten ihre Wachen ab. Eine verwundete Wache erreicht ein Lager, stirbt aber kurz darauf. Die Lieferung bleibt im Gebiet der Oger zurück."},{t="Die Legierung zurückholen",b="Bailor Steinhand lagert in Loch Modan und schickt Paladine über den Loch zu den nordöstlichen Hügeln. Die gestohlene Kiste mit der Legierung liegt verlassen zwischen den Lagern der Mo'grosh-Oger. Um sie zu bergen, muss feindliches Gebiet betreten werden, doch so kann Bailor seine Vereinbarung mit Jordan Stillbrunn einhalten."}},faq={{q="Wer ist Bailor Steinhand?",a="Bailor Steinhand ist ein zwergischer Handwerker, der in Loch Modan arbeitet, und ein alter Freund von Jordan Stillbrunn. Er stellt die besondere Legierung her, die Jordan für sein Handwerk benötigt, und versorgt ihn damit.",al={"bailor steinhand","wer ist bailor","bailor"}},{q="Wer hat Jordans Erzlieferung gestohlen?",a="Mo'grosh-Oger überfielen die Karawane auf ihrer Reise vom Sumpfland nach Loch Modan. Sie töteten ihre Begleitwachen und brachten die Fracht in ihre Lager.",al={"wer hat das erz gestohlen","wer hat die lieferung genommen","erzdiebe"}},{q="Wo fand der Überfall statt?",a="Die Karawane wurde auf der Bergstraße vom Sumpfland nach Loch Modan überfallen, bevor sie die dortigen Siedlungen erreichte.",al={"ort des überfalls","wo wurde die karawane angegriffen"}},{q="Wo befinden sich die Mo'grosh-Oger?",a="Mo'grosh-Oger haben befestigte Lager in den zerklüfteten Hügeln nordöstlich des Lochs, jenseits des Wassers gegenüber den westlichen Siedlungen.",al={"wo sind die mogrosh","standort des ogerlagers","wo ist die lieferung"}},{q="Warum wird diese Lieferung benötigt?",a="Jordan Stillbrunn benötigt die Legierung, um eine heilige Waffe für Paladine zu schmieden, die sich dem Test of Righteousness stellen.",al={"warum wird erz benötigt","wofür ist die lieferung","zweck des erzes"}},{q="Was geschah mit den Wachen der Karawane?",a="Fast alle Wachen starben bei dem Überfall. Die einzige Wache, die Hilfe erreichte, starb wenige Tage später, bevor ein Heiler sie retten konnte.",al={"wachen der karawane","überlebende der karawane"}}},fx={f726d253={q="Warum möchte Bailor Steinhand, dass dies erledigt wird?",a="Bailor hat mit seinem alten Freund Jordan Stillbrunn ein Abkommen getroffen, eine spezielle Lieferung veredelter Legierung bereitzustellen. Als der Karawanenzug, der sie aus dem Sumpfland transportierte, überfallen wurde, verlor Bailor die Waren und der letzte überlebende Wächter erlag seinen Verletzungen. Bailor ist stolz darauf, seine Verträge einzuhalten, doch da sein Transport zerstört wurde und die Oger die Legierung besitzen, benötigt er jemanden, der in der Lage ist, die gestohlene Fracht zu bergen, damit Jordan erhält, was versprochen wurde.",al={"warum bailor helfen?","bailors motiv","warum will bailor das erz?"}},["8c6c3897"]={q="Wer sind die Mo'grosh-Oger?",a="Die Mo'grosh sind ein brutaler Ogerclan, der in das nordöstliche Hochland von Loch Modan vorgedrungen ist und eine Festung namens Festung Mo'grosh errichtet hat. Sie sind aggressiv und opportunistisch, überfallen regelmäßig Gebirgspässe und Handelsrouten, die Loch Modan mit dem Sumpfland verbinden, schlachten Reisende ab und plündern Versorgungswagen auf der Suche nach Rohstoffen, Waffen und Nahrung.",al={"mo'grosh-oger","wer hat das erz genommen?","oger in loch modan"}},["6bcba9e0"]={q="Warum benötigt Bailor einen Abenteurer anstelle der örtlichen Wachen?",a="Die örtlichen Zwergenwachen und Gebirgsjäger sind bereits stark beansprucht, da sie Trogg-Aufstände niederschlagen und Verteidigungslinien im gesamten Loch halten müssen. Die Karawanenwachen, die Bailors Legierung eskortieren sollten, wurden bei dem Hinterhalt vollständig ausgelöscht, und der einzige Überlebende starb, bevor Verstärkung eintreffen konnte. Bailor hat weder die Soldaten, um sie zu entbehren, noch die Kraft, eine Ogerfestung alleine zu stürmen, sodass ihm nur ein fähiger Abenteurer als Ausweg bleibt.",al={"warum schickt bailor keine wachen?","warum ich bailor","warum nicht die wachen aus eisenschmiede?"}}},fp="21,152,19.323.0,20.278.0,24.174.0,32.147.0,32.120.0,37.125.0,28.106.0,36.128.0"}
P.entries["quest:1656"] = {n="Eine unvollendete Aufgabe",s="Auf der Hochwolkenebene kann ein junger Taure eine Familienpflicht nicht allein erfüllen. Seine Reifeprüfungen und der Auftrag seines Vaters lassen ihn zu erschöpft zurück, um Felle zu Gastwirt Kauth im Dorf der Bluthufe zu tragen.",h="Auf der Hochwolkenebene kann ein junger Taure eine Familienpflicht nicht allein erfüllen.",kw={"eine unvollendete aufgabe","dorf der bluthufe","fellbündel","gastwirt kauth","mulgore","die hochwolkenebene","rite of strength","tauren"},ang={["faction:Horde"]="Als Mitglied der Horde findet Ihr im Dorf der Bluthufe einen Treffpunkt für Reisende in Mulgore. Es bietet jenen, die die Ebenen durchqueren, Unterkunft und warme Herdfeuer.",["race:Tauren"]="Als junger Taure stellt Ihr Euch auf der Hochwolkenebene anspruchsvollen Prüfungen, um Eure Reife und Stärke zu beweisen. Neben den Riten stellen auch Familienpflichten und Stammesaufgaben Eure Ausdauer auf die Probe."},sec={{t="Prüfungen auf der Hochebene",b="Junge Tauren auf der Hochwolkenebene stellen sich Riten, die beweisen, dass sie für die weite Welt bereit sind. Die Prüfungen verlangen Kraft, während die Stammespflichten weiterhin erfüllt werden müssen. Ein Jüngling muss den Rite of Strength abschließen und einen dringenden Auftrag seines Vaters erfüllen. Zu müde, um ein Fellbündel die Hochebene hinabzutragen, bittet er Euch um Hilfe."},{t="Herdfeuer und Zuflucht",b="Das Dorf der Bluthufe liegt in den offenen Ebenen unterhalb der Hochebene, wo Gastwirt Kauth die Felle entgegennimmt. Er möchte daraus warme Decken für müde Wanderer fertigen. Die Tauren der Ebenen heißen Reisende willkommen, und ihre Unterstützung hilft jenen, die sich einsamen Kraftproben stellen."}},faq={{q="Was ist die Quest Eine unvollendete Aufgabe?",a="Ein erschöpfter junger Taure auf der Hochwolkenebene bittet Euch, Felle zu Gastwirt Kauth im Dorf der Bluthufe zu tragen. Er stellt sich noch dem Rite of Strength.",al={"was ist eine unvollendete aufgabe","eine unvollendete aufgabe questinfo","wer vergibt eine unvollendete aufgabe"}},{q="Wer ist Gastwirt Kauth?",a="Gastwirt Kauth führt das Gasthaus im Dorf der Bluthufe in Mulgore. Er bietet müden Reisenden Unterkunft, warme Decken und Gastfreundschaft, wenn sie von den hohen Tafelbergen aus die Ebenen durchqueren.",al={"wer ist gastwirt kauth","wo ist kauth","dorf der bluthufe gastwirt"}},{q="Warum werden die Felle zum Gasthaus gebracht?",a="Der Vater des jungen Tauren hat darum gebeten, die Felle zu Gastwirt Kauth zu bringen. Kauth möchte daraus warme Decken für Gäste fertigen, die in seinem Gasthaus im Dorf der Bluthufe Unterkunft und Ruhe suchen.",al={"warum felle abliefern","wofür sind die felle","fellbündel mulgore"}},{q="Warum konnte der junge Taure die Felle nicht selbst abliefern?",a="Der junge Taure stellt sich auf der Hochwolkenebene dem Rite of Strength und ist zu erschöpft, um zum Dorf der Bluthufe zu reisen. Er kann den Weg nicht zurücklegen, ohne bei dem heiligen Ritus zu scheitern oder vor Erschöpfung zusammenzubrechen.",al={"warum kann der questgeber die felle nicht abliefern","warum braucht der jüngling hilfe"}},{q="Was ist der Rite of Strength?",a="Der Rite of Strength ist eine Reifeprüfung für junge Tauren auf der Hochebene. Er prüft ihre Ausdauer und Widerstandskraft und zeigt, ob sie zu Beschützern ihres Stammes werden können.",al={"was ist der rite of strength","rite of strength taurenprüfung"}},{q="Wo liegt das Dorf der Bluthufe?",a="Das Dorf der Bluthufe ist eine der Hauptsiedlungen in den wogenden Ebenen von Mulgore, unterhalb der geschützten Höhen der Hochwolkenebene. Das Dorf bietet ein offenes Gasthaus, Handwerksbedarf und Handelsposten.",al={"wo ist das dorf der bluthufe","dorf der bluthufe lage"}}},fp="17,203,18.319.0,18.256.0,36.156.0,23.171.0,44.195.0,58.212.0,29.175.0,36.182.0"}
P.entries["quest:166"] = {n="Die Bruderschaft der Defias",s="In Westfall hält die Bruderschaft der Defias die Bauern noch immer in Angst. Gryan Starkmantel hat ihre Festung unter Mondbruch gefunden und ruft zum letzten Schlag gegen ihren Anführer auf.",h="In Westfall hält die Bruderschaft der Defias die Bauern noch immer in Angst.",kw={"die todesminen","kopf","juggernaut","miliz","mondbruch","steinmetze","starkmantel","van cleef","westfall"},ang={["class:Rogue"]="Als Schurke tretet Ihr van Cleef, einem berühmten Schurken und Meisterhandwerker, in seinem innersten Heiligtum gegenüber. Der Kampf stellt die Ausbildung jedes verdeckt operierenden Kämpfers auf die Probe.",["faction:Alliance"]="Als Mitglied der Allianz führt Ihr einen frühen Schlag, um Westfalls Kornkammer zu sichern, während Sturmwinds Thron keine eigenen Truppen entbehren kann.",["race:Human"]="Als Mensch des Königreichs erlebt Ihr in van Cleefs Tod eine bittere Tragödie: Er war der Handwerker, der Eure Hauptstadt aus der Asche wiederaufbaute."},sec={{t="Ein Urteil ist gefällt",b="Gryan Starkmantel und die Volksmiliz kämpfen seit Monaten in ganz Westfall gegen die Bruderschaft der Defias. Nun ist ihre Festung unter Mondbruch aufgedeckt. Starkmantel befiehlt, Edwin van Cleef zu töten, da er glaubt, dessen Tod werde die Rebellion endlich beenden."},{t="In das Labyrinth",b="Tief unter den Todesminen führen gewundene Schächte an abtrünnigen Steinmetzen, Gobliningenieuren und schweren eisernen Schotttüren vorbei. Im zentralen Trockendock überwacht van Cleef die letzten Arbeiten an seinem gewaltigen Kriegsschiff. Sein Tod würde die Befehlsgewalt zerschlagen, die das Netzwerk der Gesetzlosen zusammenhält."},{t="Schatten einer größeren Verschwörung",b="Gryan Starkmantel glaubt, van Cleefs Tod werde das Ende der Bruderschaft einläuten. Doch bei der Leiche des gefallenen Gildenmeisters liegt ein nie abgeschickter Brief. Er deutet an, dass Westfalls Aufstand mit einem größeren Geflecht verbunden war, das bis in den Adel von Sturmwind reichte."}},faq={{q="Was ist das Ziel dieser Quest?",a="Gryan Starkmantel bittet Euch, die Todesminen unter Mondbruch zu betreten, Edwin van Cleef zu töten und seinen abgeschlagenen Kopf zur Späherkuppe zu bringen.",al={"questziel","was ist zu tun","worum geht es in dieser quest"}},{q="Wer ist Edwin van Cleef?",a="Edwin van Cleef diente einst als Großsteinmetz der Stonemasons Guild und leitete den Wiederaufbau von Sturmwind, nachdem die Orcs die Stadt im Ersten Krieg zerstört hatten. Nach einem erbitterten Streit mit dem House of Nobles um die Bezahlung gründete er die Bruderschaft der Defias, um am Königreich Rache zu nehmen.",al={"wer ist van cleef","van cleefs identität","edwin van cleefs geschichte"}},{q="Warum befiehlt Gryan Starkmantel einen Mordanschlag?",a="Der Volksmiliz fehlt die Verstärkung durch reguläre Truppen aus Sturmwind, die sie für einen langen Krieg bräuchte. Starkmantel sieht in der Beseitigung der Führung der Bruderschaft Westfalls einzige wirkliche Chance, die Bauern aus dem Griff des Syndikats zu befreien.",al={"warum van cleef töten","starkmantels beweggrund","warum die todesstrafe"}},{q="Wo ist Edwin van Cleef zu finden?",a="Edwin van Cleef hält sich tief in den Todesminen unter Mondbruch verborgen. Gryan Starkmantel bittet Euch, das Versteck zu betreten und ihn zu finden.",al={"van cleefs aufenthaltsort","wo ist edwin van cleef","bossstandort in den todesminen"}},{q="Vernichtet van Cleefs Tod die Defias vollständig?",a="Starkmantel hofft, van Cleefs Tod werde die Herrschaft der Bruderschaft über Westfall brechen. Der Ausgang und mögliche weitere Entdeckungen stehen bis zum Angriff noch aus.",al={"sind die defias besiegt","sind die defias verschwunden","ende der bruderschaft"}},{q="Welcher bemerkenswerte Gegenstand wird nach van Cleefs Niederlage bei ihm gefunden?",a="Starkmantel verlangt van Cleefs Kopf als Beweis. Weitere Entdeckungen im Versteck ergeben sich während des Angriffs.",al={"van cleefs beute","nie abgeschickter brief","welche beute hinterlässt van cleef"}}},fx={e9d4d384={q="Wozu dient Van Cleefs Kopf?",a="Gryan Starkmantel verlangt einen unbestreitbaren Beweis dafür, dass Edwin van Cleef tatsächlich tot ist. The Defias Brotherhood hat Westfall jahrelang aus dem Schatten heraus terrorisiert, Gerüchte verbreitet und sich der Gefangennahme entzogen. Die Vorlage von Van Cleefs abgetrenntem Kopf bringt The People's Militia endgültig Gewissheit und signalisiert den bedrängten Bauern, dass ihr größter Peiniger endlich gefallen ist.",al={"warum van cleefs kopf nehmen?","zweck von van cleefs kopf","warum brauche ich van cleefs kopf?"}},["48642626"]={q="Warum schickt Euch Gryan Starkmantel anstelle von The People's Militia?",a="The People's Militia ist bereits an ihre Grenzen gestoßen, allein bei der Verteidigung der Späherkuppe und den verstreuten Gehöften in Westfall gegen tägliche Banditenüberfälle und Gnollangriffe. Sturmwind hat sich geweigert, Verstärkung zu schicken, wodurch Starkmantel ohne die disziplinierte, schwere Eingreiftruppe dasteht, die nötig wäre, um die befestigten Tiefen der Todesminen zu stürmen. Er muss sich auf erfahrene, fähige Abenteurer wie Euch verlassen, um direkt ins Herz der Verschwörung zu schlagen.",al={"warum greift die miliz die todesminen nicht an?","warum schickt man mich gegen van cleef?","warum tötet starkmantel van cleef nicht?"}}},fp="22,178,17.250.0,18.274.1,31.236.1,31.134.0,22.274.0,50.230.0,34.127.0,52.140.1,55.107.1"}
P.entries["quest:1665"] = {n="Bartlebys Becher",s="In Sturmwinds Pig and Whistle Tavern stellt sich Bartleby der Prüfung eines jungen Kriegers. Nachdem Ihr ihn besiegt habt, bringt Ihr seinen Trinkbecher zu Eurem Ausbilder Harry Burlguard.",h="In Sturmwinds Pig and Whistle Tavern stellt sich Bartleby der Prüfung eines jungen Kriegers.",kw={"bartleby","burlguard","becher","die altstadt","pig and whistle","sturmwind","krieger"},ang={["class:Warrior"]="Als Krieger in Sturmwind beweist Ihr, dass Ihr Euch ungebärdigen Gegnern stellen könnt, indem Ihr Bartleby seinen Becher abnehmt.",["faction:Alliance"]="Als Mitglied der Allianz wisst Ihr, dass randalierende Gäste in der Altstadt Sturmwinds Kampfausbildern oft Ärger bereiten."},sec={{t="Trophäe einer Wirtshausschlägerei",b="In der Altstadt prüft Harry Burlguard junge Krieger mit einer Schlägerei. Er schickt Euch zu Bartleby, einem sturen Trunkenbold an der Theke der Pig and Whistle Tavern. Sobald Bartleby bezwungen ist, gibt er widerwillig seinen geliebten Trinkbecher heraus. Zuerst nimmt er noch einen letzten Schluck, um den Bodensatz auszutrinken."},{t="Ein Schritt zur Meisterschaft",b="Wenn Ihr den Becher zurückbringt, nimmt Harry Burlguard ihn als Beweis Eurer bestandenen Novizenprüfung an. Er erkennt, dass Ihr andere mit Gewalt zum Einlenken bringen könnt, und hält Euch für bereit, Verteidigung zu erlernen. Dann verweist er Euch an Marschall Haggard, einen erfahrenen Veteranen im Wald von Elwynn, der Euch auf dem Schlachtfeld weiter unterweisen soll."}},faq={{q="Warum will Harry Burlguard Bartlebys Becher?",a="Harry Burlguard will Bartlebys Becher als Beweis, dass Ihr gegen ihn gekämpft und ihn besiegt habt. Bartleby klammert sich verbissen an seinen Trank, daher zeigt die Übergabe seines eigenen Bechers, dass er gründlich geschlagen wurde.",al={"warum bartlebys becher","burlguard becher zweck","beweis für den sieg über bartleby"}},{q="Wer ist Bartleby?",a="Bartleby ist ein ungebärdiger Gast an der Theke des Pig and Whistle in Sturmwinds Altstadt. Betrunken und übellaunig dient er den örtlichen Kriegerausbildern als informelle Prüfung für aufstrebende Kämpfer.",al={"bartleby hintergrundgeschichte","wer ist bartleby the drunk","bartleby altstadt"}},{q="Wo findet dieser Kampf statt?",a="Die Schlägerei findet in der Pig and Whistle Tavern in Sturmwinds Altstadt statt.",al={"wo ist bartleby","bartleby aufenthaltsort","pig and whistle kampf"}},{q="Was folgt, nachdem Ihr Burlguard den Becher zurückgebracht habt?",a="Nachdem Burlguard den Becher begutachtet und Euren Sieg bestätigt hat, lehrt er Euch fortgeschrittene defensive Kampfhaltungen. Dann schickt er Euch vor die Stadttore, um Marschall Haggard im Wald von Elwynn zu finden.",al={"was folgt nach bartlebys becher","quest nach bartlebys becher","haggard quest"}},{q="Trägt Bartleby bleibende Verletzungen von der Schlägerei davon?",a="Nein. Die Schlägerei soll Bartleby nicht töten. Er gibt auf, trinkt aus, übergibt seinen Becher und bleibt mit blauen Flecken und verletztem Stolz in der Taverne.",al={"ist bartleby tot","ist bartleby gestorben","bartleby überlebt"}},{q="Kann jede Klasse der Allianz diese Quest abschließen?",a="Nur Krieger der Allianz stellen sich dieser Prüfung als Teil ihrer Ausbildung auf Stufe zehn in Kampfhaltungen und Verteidigungsmanövern.",al={"bartlebys becher nur für krieger","wer kann bartlebys quest machen","becher quest klassen"}}},fx={["2bbd1f99"]={q="Warum gibt Bartleby seinen Krug heraus?",a="Bartleby händigt seinen geschätzten Krug nur deshalb aus, weil Ihr ihn in einer Kneipenschlägerei redlich besiegt habt. Er war nicht bereit, sich freiwillig davon zu trennen, aber nachdem er in die Knie gezwungen wurde, gibt er sich ehrenhaft geschlagen – wenn auch nicht, ohne hastig den Rest des Getränks auszutrinken.",al={"warum gibt bartleby seinen krug ab?","bartlebys motiv","warum den krug herausgeben?"}}},fp="14,158,24.272.0,21.305.0,45.178.0,16.184.0,33.80.0,48.191.0,48.151.0,37.122.0"}
P.entries["quest:1666"] = {n="Marschall Haggard",s="In Eastvale hütet Marschall Haggard die Waffen, die er über ein Leben im Dienst gesammelt hat. Harry Burlguard schickt angehende Krieger aus Sturmwind zu dem pensionierten Marschall, damit sie nach besseren Waffen suchen.",h="In Eastvale hütet Marschall Haggard die Waffen, die er über ein Leben im Dienst gesammelt hat.",kw={"eastvale","holzfällerlager des osttals","wald von elwynn","harry burlguard","marschall haggard","sturmwind","krieger"},ang={["class:Warrior"]="Als Krieger der Allianz verlasst Ihr Sturmwinds geregelte Ausbildung und wagt Euch auf der Suche nach Waffen in die Wildnis.",["faction:Alliance"]="Als Kämpfer der Allianz folgt Ihr Sturmwinds Brauch, auf pensionierte Veteranen und ihre privaten Vorräte zu setzen, um die nächste Generation von Verteidigern vorzubereiten."},sec={{t="Die Waffenkammer eines Veteranen",b="Sturmwinds angehende Krieger brauchen mehr als Geschick, um Gefahren jenseits der Stadt zu begegnen. Harry Burlguard schickt vielversprechende Kämpfer ostwärts durch den Wald von Elwynn zu Marschall Haggard, einem pensionierten Offizier, der dem Reich jahrelang diente. Während eines Lebens im Felde trug Haggard eine eigene Waffenkammer zusammen. Sein Heim nahe dem Holzfällerlager des Osttals birgt Waffen für junge Krieger, die nach besserer Bewaffnung suchen."},{t="Ruhestand in Eastvale",b="Marschall Haggard lebt in einem abgelegenen Herrenhaus nahe dem Holzfällerlager des Osttals. Die Jahre im Dienst haben seine Sehkraft geschwächt, und manchmal verwechselt er herannahende Reisende mit umherstreifenden Flussgnomen. Das Alter hält ihn in diesem ruhigen Winkel im Osten Elwynns. Dennoch achten Sturmwinds Wachen und Ausbilder den alten Marschall noch immer."}},faq={{q="Wer vergibt diese Quest?",a="Harry Burlguard, ein Kriegerlehrer in Sturmwind, schickt vielversprechende junge Krieger zu Marschall Haggard.",al={"wo gibt es die quest marschall haggard","wer vergibt marschall haggard","questgeber marschall haggard"}},{q="Wo befindet sich Marschall Haggard?",a="Marschall Haggard lebt in einem Herrenhaus unmittelbar östlich des Holzfällerlagers des Osttals, im äußersten Osten des Walds von Elwynn nahe der Grenze zum Rotkammgebirge.",al={"marschall haggard standort","wo ist haggard","holzfällerlager des osttals herrenhaus"}},{q="Warum schickt Harry Burlguard Euch zu Haggard?",a="Harry Burlguard schickt Euch zu Marschall Haggard, weil junge Krieger bessere Waffen als ihre Übungsklingen brauchen. Haggard sammelte während seiner langen Laufbahn Waffen und Rüstungen und teilt sie vielleicht mit jenen, die sich als würdig erweisen.",al={"warum marschall haggard","warum als krieger nach eastvale","zweck der quest marschall haggard"}},{q="Warum verwechselt Haggard Besucher mit Gnollen?",a="Marschall Haggards Sehkraft hat mit dem Alter nachgelassen. Gnolle bedrängen die Holzfällerbetriebe und Randgebiete im Osten des Walds von Elwynn, weshalb der alte Veteran unverhofften Besuchern misstraut.",al={"haggards sehkraft","ist haggard blind","haggard gnollendialog"}},{q="Was folgt nach Abschluss dieser Quest?",a="Nachdem Ihr Marschall Haggard begrüßt habt, prüft er Euren Mut und schickt Euch los, um Euch um Dead-tooth Jack zu kümmern, bevor er erwägt, Waffen aus seinen Vorräten mit Euch zu teilen.",al={"marschall haggard nächste quest","folgequest von marschall haggard"}},{q="Ist diese Quest auch für andere Klassen als Krieger verfügbar?",a="Nein. Dieser Weg ist Kriegern vorbehalten, als Teil ihrer Ausbildung um Stufe zehn und ihrer Vorbereitung auf Gefahren jenseits des Walds von Elwynn.",al={"können paladine marschall haggard machen","haggard quest nur für krieger"}}},fp="15,194,18.383.0,22.319.0,22.104.0,33.137.0,45.223.0,45.169.0,39.150.1,55.129.0"}
P.entries["quest:1667"] = {n="Stumpfzahn Jack",s="Im östlichen Wald von Elwynn braucht Marschall Haggard im Ruhestand Eure Hilfe: Stumpfzahn Jack hat ihm sein Abzeichen abgeschwindelt. Jack trug einen Wappenrock von Sturmwind und gab sich als Marschall Dughan aus. Haggard fürchtet, dass die Bruderschaft der Defias das Abzeichen nutzen wird, um sich als Amtsträger von Sturmwind auszugeben.",h="Im östlichen Wald von Elwynn braucht Marschall Haggard im Ruhestand Eure Hilfe: Stumpfzahn Jack hat ihm sein...",kw={"abzeichen","stumpfzahn jack","defias","wald von elwynn","wache burlguard","falsche identität","marschall dughan","marshal haggard","geldkassette"},ang={["class:Rogue"]="Als Schurke erkennt Ihr, dass Stumpfzahn Jacks Gaunerei ebenso auf Verkleidung, Täuschung und Dreistigkeit beruht wie auf plumpem Straßenraub.",["class:Warrior"]="Marschall Haggard war einst ein erfahrener Frontkämpfer. Als Krieger könnt Ihr Euch seinen Dank verdienen und aus den überzähligen Waffen wählen, die er aus seiner Dienstzeit behalten hat.",["race:Human"]="Als Mensch aus Sturmwind erkennt Ihr, wie anfällig die ländlichen Grenzgebiete des Königreichs für eingeschleuste Defias sind. Sie tragen die Farben der Krone selbst, um pensionierte Veteranen zu täuschen."},sec={{t="Betrug im Dunkeln",b="Nachts kam eine Gestalt in einem Wappenrock von Sturmwind zu Haggards abgelegener Hütte auf den östlichen Anhöhen von Elwynn. Der Fremde behauptete, in offizieller Angelegenheit zu kommen, und bat um Haggards altes Marschallsabzeichen. Haggard glaubte, es einem Offizierskameraden auszuhändigen, und übergab es ihm. Die Gestalt lachte und verschwand im Wald. Es war ein Schurke der Defias namens Stumpfzahn Jack."},{t="Die Gefahr vorgetäuschter Amtsgewalt",b="Marschall Haggard ist im Ruhestand, doch sein Abzeichen verleiht noch immer die rechtliche Amtsgewalt von Sturmwind. Banditen der Defias schleichen durch Elwynn, Westfall und das Rotkammgebirge. Mit dem Abzeichen könnten sie Kontrollposten der Wachen passieren, Patrouillen umleiten oder die Verfügungsgewalt über Vorräte übernehmen. Jack zog sich in ein Lager im Süden zurück und schloss das Abzeichen in einer Geldkassette ein. Haggard braucht es zurück, bevor die Defias ernsthaften Schaden anrichten."}},faq={{q="Wer ist Stumpfzahn Jack?",a="Stumpfzahn Jack ist ein Agent der Defias im östlichen Wald von Elwynn. Nachts gab er sich als Marschall Dughan aus und brachte den pensionierten Marschall Haggard dazu, ihm sein offizielles Abzeichen von Sturmwind auszuhändigen.",al={"stumpfzahn jack","wer ist stumpfzahn","stumpfzahn jack hintergrundgeschichte"}},{q="Warum braucht Marschall Haggard sein Abzeichen zurück?",a="Marschall Haggard braucht sein Abzeichen zurück, weil es ein echtes Zeichen der Amtsgewalt von Sturmwind ist. Er fürchtet, dass die Defias es nutzen werden, um sich als Amtsträger auszugeben, Militärpatrouillen zu umgehen und im ganzen Königreich Unheil anzurichten.",al={"warum abzeichen zurückholen","haggards abzeichen","warum ist das abzeichen wichtig"}},{q="Wie konnte Jack Marschall Haggard täuschen?",a="Jack kam nachts in einem Wappenrock von Sturmwind zu Haggards Hütte. Im schwachen Licht hielt Haggard ihn für Marschall Dughan aus Goldhain und gab ihm das Abzeichen, im Glauben, einem Offizierskameraden zu helfen.",al={"wie hat er haggard getäuscht","haggard getäuscht","warum gab haggard das abzeichen her"}},{q="Wo bewahrt Jack das gestohlene Abzeichen auf?",a="Jack bewahrt das gestohlene Abzeichen in einer verschlossenen Geldkassette in seinem Banditenlager südlich von Marshal Haggards Haus auf. Den Schlüssel trägt er bei sich.",al={"abzeichen fundort","wo ist das abzeichen","stumpfzahns lager"}},{q="Wer hat Euch ursprünglich zu Marschall Haggard geschickt?",a="Harry Burlguard, ein erfahrener Krieger, der regelmäßig die Pig and Whistle Tavern in Sturmwind besucht, schickt Abenteurer zu Marschall Haggard. Er weiß, dass der pensionierte Marschall möglicherweise überzählige Waffen gegen Hilfe eintauscht.",al={"wer schickt einen hierher","burlguard","questgeber beginn"}},{q="Was geschieht, sobald das Abzeichen zurückgebracht wurde?",a="Marschall Haggard ist sehr erleichtert, dass die Defias weder seine Identität noch seinen Rang gegen das Königreich einsetzen können. Er salutiert Euch zum Dank und lässt Euch aus gut gepflegten Militärwaffen aus seiner Dienstzeit wählen.",al={"quest abgeben","haggards reaktion","abzeichen zurückgebracht"}}},fx={["5b8b35d8"]={q="Wozu dient Marschall Haggards Abzeichen?",a="Marschall Haggards Abzeichen ist ein außer Dienst gestelltes Zeichen hoher Autorität in der Armee von Sturmwind. In ehrlichen Händen ist es ein geschätztes Erbstück aus Haggards Dienstjahren. In den Händen von The Defias Brotherhood hingegen ermöglicht ein offizielles Marschall-Abzeichen Dieben und Banditen, sich als Offiziere Sturmwinds auszugeben, Kontrollpunkte zu passieren und gefährliche Täuschungsmanöver im ganzen Königreich zu inszenieren.",al={"zweck von haggards abzeichen","was bewirkt das abzeichen?","warum ist das abzeichen gefährlich?"}},["55355d07"]={q="Warum benötigt Marschall Haggard Euch, um sein Abzeichen zurückzuholen?",a="Haggard ist längst im Ruhestand und lebt in einer abgelegenen Hütte; es ist ihm peinlich, dass ein Schurke ihn im Dunkeln ausgetrickst hat. Die Stadtgarnison oder Marschall Dughan um Hilfe zu bitten, würde bedeuten, zuzugeben, dass er sein offizielles Abzeichen direkt einem Defias-Dieb ausgehändigt hat, und die Wachen Sturmwinds sind bereits mit der Verteidigung der Gemeinde überlastet. Da Ihr auf der Suche nach seinen Ersatzwaffen zu ihm gekommen seid, seid Ihr die perfekte, fähige und diskrete Person, um die Sache zu bereinigen.",al={"warum braucht haggard mich?","warum holt haggard es nicht selbst?","warum keine wachen einsetzen?"}}},fp="15,277,17.370.0,29.385.0,23.184.0,45.209.0,44.205.0,38.136.0,51.191.0,40.215.1"}
P.entries["quest:167"] = {n="Oh Bruder...",s="In Sturmwind wartet Wilder Distelklette, nachdem er einem Einsturz unter Mondbruch entkommen ist. Sein Bruder, Großknecht Distelklette, und der Rest der Mannschaft sind hinter dem Geröll zurückgeblieben, und Wilder bittet Euch, seinen Bruder zu finden oder das Abzeichen der Forscherliga des Zwergs zu bergen.",h="In Sturmwind wartet Wilder Distelklette, nachdem er einem Einsturz unter Mondbruch entkommen ist.",kw={"abzeichen","die todesminen","forscherliga","mondbruch","sturmwind","distelklette","untoter","westfall","wilder"},ang={["faction:Alliance"]="Als Reisender der Allianz könnt Ihr sehen, wie die Defias und die Schrecken unter der Erde unschuldigen Menschen nahe Sturmwind Leid zugefügt haben.",["race:Dwarf"]="Als Zwerg berührt Euch der Verlust eines Großknechts der Forscherliga in den Ländern der Menschen in Fragen der Brüderlichkeit, der Steinmetzkunst und der unermüdlichen Arbeit der Liga."},sec={{t="Eine gefangene Expedition",b="Wilder Distelklette und sein Bruder arbeiteten für eine Bergbaugesellschaft in den Tunneln unter Mondbruch. Dann strömten Diebe in die Minen, und ein Einsturz versperrte die unteren Gänge. Wilder entkam nach Sturmwind. Sein Bruder und der Rest der Mannschaft blieben hinter dem Geröll gefangen."},{t="Das düstere Schicksal von Großknecht Distelklette",b="Großknecht Distelklette überlebte unter dem Geröll nicht. Dunkle Energien in den verlassenen Minen erweckten den Zwerg als untote Hülle. Er wandert zwischen anderen ruhelosen Leichen durch die Tunnel und trägt noch immer sein Abzeichen der Forscherliga, das letzte Zeichen dessen, wer er einst war."}},faq={{q="Wo beginne ich die Quest „Oh Bruder...“?",a="Wilder Distelklette bietet die Suche im Zwergendistrikt von Sturmwind an.",al={"questgeber oh bruder","wer vergibt oh bruder","wo gibt es oh bruder"}},{q="Wo befindet sich Großknecht Distelklette?",a="Großknecht Distelklette wandert durch die äußeren Minengänge unter Mondbruch in Westfall, irgendwo entlang der Tunnel, die zum Portal führen.",al={"großknecht distelklette fundort","wo ist distelklette","wo ist der bruder"}},{q="Was ist Großknecht Distelklette zugestoßen?",a="Ein Einsturz schloss Großknecht Distelklette und seine Bergleute in den Höhlen ein. Seitdem hat niemand mehr von ihnen gehört. Wilder muss seinen Bruder oder zumindest dessen Abzeichen finden, um zu erfahren, was geschehen ist.",al={"lebt distelklette","was ist dem bruder zugestoßen","distelklette hintergrundgeschichte"}},{q="Welchen Gegenstand muss ich bergen?",a="Ihr braucht das Abzeichen der Forscherliga von Großknecht Distelklette, das er immer bei sich trug. Findet ihn tief in den Tunneln der Todesminen, und das Abzeichen wird bei ihm sein.",al={"oh bruder questgegenstand","was wird für oh bruder fallengelassen"}},{q="Was tat die Expedition in Mondbruch?",a="Die Brüder Distelklette arbeiteten für eine Bergbaugesellschaft unter Mondbruch. Banditen der Defias überfielen sie aus dem Hinterhalt, dann trennte sie ein plötzlicher Einsturz.",al={"warum waren die zwerge in westfall","forscherliga todesminen","warum waren sie in mondbruch"}},{q="Wird diese Quest innerhalb der Dungeoninstanz der Todesminen abgeschlossen?",a="Nein. Ihr könnt Großknecht Distelklette in den umkämpften Minentunneln finden, die zum Portal führen, ohne den Dungeon zu betreten. Er ist ein Elitegegner.",al={"ist oh bruder innerhalb der todesmineninstanz","ist eine dungeongruppe nötig"}}},fx={["7bf03114"]={q="Warum möchte Wilder Distelklette, dass dies erledigt wird?",a="Wilder entkam nur knapp mit dem Leben, als die Tunnel tief unter Mondbruch einstürzten. Sein Bruder und der Rest der Bergbauexpedition kamen nie wieder heraus, verschlungen von der Dunkelheit und den Dieben, die die Gänge befallen haben. Zurück in Sturmwind gelassen, in qualvoller Ungewissheit, sucht Wilder nach Seelenfrieden. Er muss wissen, ob sein Bruder noch lebt oder ob ihn ein grausames Schicksal in der Tiefe ereilt hat.",al={"warum will wilder seinen bruder finden?","wilder distelklettes motiv","warum großknecht distelklette finden?"}},ebc7a172={q="Was ist Distelklettes Abzeichen?",a="Großknecht Distelklette trug ein Abzeichen der Forscherliga, das seinen Status in der Gilde der Gräber und Abenteurer von Eisenschmiede kennzeichnete. Sollten Ihr in den Tiefen keinen lebenden Zwerg finden, dient die Bergung dieses persönlichen Tokens als Beweis seines Schicksals und gewährt seinem trauernden Bruder endgültige Gewissheit.",al={"was ist distelklettes abzeichen?","distelklette abzeichen der forscherliga","warum das abzeichen besorgen?"}},["5e05fe78"]={q="Warum bittet Wilder Distelklette Euch, anstatt selbst zu gehen?",a="Wilder hat es gerade noch lebend herausgeschafft, als die Katastrophe zuschlug. Das weitläufige Labyrinth unter Mondbruch wimmelt von Halsabschneidern und gefährlichen Hindernissen, weit mehr, als ein entkommener Minenarbeiter allein bewältigen könnte. Da er in Euch einen fähigen Abenteurer sieht, setzt er seine Hoffnung darauf, dass Ihr dort Erfolg habt, wo er nur fliehen konnte.",al={"warum geht wilder nicht selbst?","warum schickt man mich in die todesminen?","warum braucht wilder hilfe?"}}},fp="15,259,20.273.0,38.257.1,45.76.0,39.136.0,39.189.1,32.154.1,43.142.0,62.141.0"}
P.entries["quest:1678"] = {n="Vejrek",s="In den Ausläufern südlich der Höhle der Frostmähnen stellt Ihr Euch Vejrek, um Euch zu beweisen. Muren Sturmlanze will einen Beweis, dass Ihr es mit echten Gegnern aufnehmen könnt. Euer Erfolg leitet eine Lektion in starker Verteidigung ein.",h="In den Ausläufern südlich der Höhle der Frostmähnen stellt Ihr Euch Vejrek, um Euch zu beweisen.",kw={"höhle der frostmähnen","eisenschmiede","tüchtigkeit","muren stormpike","starke verteidigung","troll","vejrek"},sec={{t="Eine Bewährungsprobe",b="Muren Sturmlanze sagt, Ihr müsst zäh sein, bevor er Euch neue Techniken beibringen kann. Vejrek ist der zäheste Troll in dieser Gegend, und seine Hütte liegt in den Ausläufern südlich der Höhle der Frostmähnen. Muren bittet Euch, Vejreks Kopf als Beweis zurückzubringen, dass Ihr es mit echten Gegnern aufnehmen könnt."},{t="Die Lektion",b="Muren nimmt Vejreks Kopf entgegen und sagt, Ihr habt das Zeug dazu. Er ist bereit, Euch starke Verteidigung beizubringen, die Euch gegen Gegner auf den Beinen hält, die andere zu Fall bringen würden, und Eure Verbündeten unterstützt."}},faq={{q="Wer ist Vejrek?",a="Vejrek wird als der zäheste Troll in dieser Gegend beschrieben. Seine Hütte liegt in den Ausläufern südlich der Höhle der Frostmähnen.",al={"wer ist vejrek","vejrek troll","dieser troll"}},{q="Warum schickt Muren mich gegen Vejrek?",a="Muren will einen Beweis, dass Ihr es mit echten Gegnern aufnehmen könnt, bevor er Euch neue Techniken beibringt.",al={"warum vejrek töten","murens prüfung","tüchtigkeit beweisen"}},{q="Wo steht Vejreks Hütte?",a="Vejreks Hütte steht in den Ausläufern südlich der Höhle der Frostmähnen.",al={"vejreks standort","wo steht seine hütte","troll in den ausläufern"}},{q="Was soll für Muren zurückgebracht werden?",a="Muren bittet Euch, Vejreks Kopf als Beweis Eurer Tüchtigkeit zurückzubringen.",al={"vejreks kopf","was mitbringen","was will muren"}},{q="Was lehrt Muren nach der Prüfung?",a="Muren beginnt, Euch starke Verteidigung beizubringen, nachdem er Vejreks Kopf entgegengenommen hat. Die Lektion behandelt, wie sie Euch hilft, gegen Gegner auf den Beinen zu bleiben.",al={"murens lektion","was ist die lektion","starke verteidigung"}}},fp="6,181,16.258.0,10.195.1,14.112.0,36.80.0,22.59.0,34.69.0,37.132.0"}
P.entries["quest:1679"] = {n="Muren Sturmlanze",s="In Eisenschmiede erwartet Muren Sturmlanze Krieger, die aus Kharanos zur formellen Ausbildung geschickt werden. Granis Flinkaxt schickt Rekruten, die sich in Dun Morogh bewährt haben, in den Military Ward der Stadt.",h="In Eisenschmiede erwartet Muren Sturmlanze Krieger, die aus Kharanos zur formellen Ausbildung geschickt...",kw={"defensive stance","granis flinkaxt","hall of arms","eisenschmiede","kharanos","military ward","muren sturmlanze","kriegerlehrer"},ang={["class:Warrior"]="Für Euch als Krieger markiert dieser Ruf den Übergang vom Rekruten zum disziplinierten Soldaten, bereit, die Stellung zu halten und Verbündete zu schützen.",["race:Dwarf"]="Als zwergischer Kämpfer findet Ihr durch Eure Meldung in der Hall of Arms Zugang zu den kriegerischen Traditionen und der taktischen Disziplin der Bergclans.",["race:Gnome"]="Als gnomischer Krieger seid Ihr auf die Hall of Arms in Eisenschmiede angewiesen, um den traditionellen schweren Frontkampf zu erlernen, nachdem der Fall Gnomeregans Euer Volk nach Dun Morogh vertrieben hat."},sec={{t="Ein Ruf nach Eisenschmiede",b="Granis Flinkaxt schickt vielversprechende Krieger aus Kharanos nach Eisenschmiede, nachdem sie sich örtlichen Bedrohungen in Dun Morogh gestellt haben. Er weiß, dass raue Scharmützel nur begrenzt etwas lehren können. Im Military Ward leiten erfahrene Kämpfer die formelle Ausbildung jener, die in die Schlacht ziehen werden."},{t="Der Waffenmeister",b="In der Hall of Arms begegnet Ihr Muren Sturmlanze, einem Veteranen eines geschichtsträchtigen Zwergenclans. Er will Beweise dafür, dass seine neuen Schützlinge echte Kämpfe durchstehen können, keine Tavernenmärchen. Euch bei ihm zu melden, eröffnet Euch den Weg, Verteidigungskünste zu erlernen, die Aggression eines Feindes zu kontrollieren und eiserne Waffen für die Front zu verdienen."}},faq={{q="Wer schickt Euch auf die Suche nach Muren Sturmlanze?",a="Granis Flinkaxt, der Kriegerlehrer in Kharanos, schickt Euch los, nachdem Ihr Eure grundlegenden Kampffertigkeiten in Dun Morogh bewiesen habt.",al={"wer vergibt die quest muren sturmlanze","wo gibt es die quest muren sturmlanze","questgeber muren sturmlanze"}},{q="Wo befindet sich Muren Sturmlanze?",a="Muren Sturmlanze befindet sich in der Hall of Arms im Military Ward auf der Ostseite von Eisenschmiede.",al={"wo ist muren sturmlanze","muren sturmlanze standort","wie muren finden"}},{q="Warum ist diese Quest für Krieger wichtig?",a="Mit Eurer Meldung bei Muren beginnt die fortgeschrittene Kriegerausbildung. Sie führt zur Unterweisung in Defensive Stance und Taunt sowie zu einer verlässlichen Waffe für die ersten Kämpfe.",al={"was schaltet muren sturmlanze frei","warum muren sturmlanze abschließen","muren sturmlanze belohnungen"}},{q="Wer ist Muren Sturmlanze?",a="Muren Sturmlanze ist ein erfahrener Kampfausbilder in Eisenschmiede und Mitglied des Clans Stormpike, einer berühmten Zwergenfamilie von Kriegern und Expeditionsingenieuren.",al={"wer ist muren","muren sturmlanze hintergrundgeschichte","gehört muren zum clan stormpike"}},{q="Kann jede Klasse diese Quest annehmen?",a="Nein. Nur Kriegernovizen, die für eine spezialisierte Kampfausbildung bereit sind, können sie annehmen.",al={"muren sturmlanze für andere klassen","muren sturmlanze nur für krieger","muren sturmlanze klassen"}},{q="Was geschieht, nachdem Ihr Euch bei Muren gemeldet habt?",a="Nachdem Ihr mit Muren gesprochen habt, stellt er Eure Entschlossenheit auf die Probe und schickt Euch zu einer Kampfprüfung gegen Vejrek.",al={"was kommt nach muren sturmlanze","nächste quest nach muren sturmlanze","vejrek quest"}}},fx={["61377fd6"]={q="Warum schickt Euch Granis Flinkaxt zu Muren Sturmlanze?",a="Granis Flinkaxt sieht echtes Potenzial in Euren Kampffähigkeiten, aber in Kharanos kann man Euch nur die Grundlagen vermitteln. Um Eure Ausbildung zum Krieger voranzutreiben und zu lernen, was es wirklich bedeutet, ein Krieger zu sein, verweist er Euch an Muren Sturmlanze, einen erfahrenen Veteranen, der in der Hall of Arms in Eisenschmiede stationiert ist.",al={"granis flinkaxts motiv","warum zu muren schicken?","warum mit muren stormpike sprechen?"}}},fp="15,188,22.252.0,18.287.0,38.116.0,33.89.0,41.143.0,23.162.0,30.76.0,38.100.0"}
P.entries["quest:168"] = {n="Die Suche nach Andenken",s="In Sturmwind bittet Wilder Distelklette Euch, der unter Mondbruch verlorenen Bergleute zu gedenken. Er möchte, dass ihre Gewerkschaftskarten der Bergleute zu ihren trauernden Familien zurückkehren.",h="In Sturmwind bittet Wilder Distelklette Euch, der unter Mondbruch verlorenen Bergleute zu gedenken.",kw={"die suche nach andenken","die todesminen","gewerkschaftskarte der bergleute","mondbruch","sturmwind","untote bergleute","wilder distelklette"},ang={["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr den trauernden Familien der Arbeiter aus Westfall helfen. Sie durchleben schwere Zeiten innerhalb der Mauern von Sturmwind.",["profession:Mining"]="Als Bergarbeiter kennt Ihr die Furcht vor einem Schachteinsturz. Die verlorenen Gewerkschaftskarten zu bergen, verleiht dieser Furcht ein düsteres Gewicht.",["race:Dwarf"]="Als Zwerg kennt Ihr die Bande, die unter Tage geschmiedet werden, und die Ehre, die gefallenen Angehörigen gebührt. Wilder Distelklettes Bitte berührt Euch zutiefst."},sec={{t="Ein tragischer Einsturz",b="Bevor die Bruderschaft der Defias Gesetzlosigkeit nach Mondbruch brachte, sicherten die Minen von Westfall vielen Arbeiterfamilien den Lebensunterhalt. Wilder Distelklette überlebte einen Einsturz, der einen Teil der Tunnel verschüttete. Viele Freunde und Bergarbeiterkollegen starben unter Tage, außerhalb der Reichweite jeder Rettung. Ihre Familien in Sturmwind erfuhren nie mit Gewissheit, was aus ihnen geworden war."},{t="Rastlose Überreste",b="Die beim Einsturz getöteten Bergleute wandern nun als Untote durch die Tunnel außerhalb der Haupteisenwerke. Ihr durchsucht diese heimgesuchten Gänge nach ihren Gewerkschaftskarten der Bergleute und stellt Euch den Überresten der Männer, an deren Seite Wilder arbeitete. Bringt die Karten nach Sturmwind zurück, damit ihre Familien erfahren, was geschehen ist, und Wilder seine gefallenen Gefährten ehren kann."}},faq={{q="Wer ist Wilder Distelklette?",a="Wilder Distelklette ist ein Zwergenbergarbeiter in Sturmwind. Er überlebte einen Einsturz unter Westfall, bei dem seine engen Arbeitskollegen starben. Nun möchte er ihren Familien Gewissheit und Frieden bringen.",al={"wilder distelklette","questgeber","wer vergibt die suche nach andenken"}},{q="Was geschah mit den Bergleuten in den Todesminen?",a="Ein Einsturz schloss eine Gruppe Bergleute in einem Teil der Ausgrabungsstätten von Mondbruch ein und tötete sie. Ihre Körper und Geister suchen nun als Untote die verlassenen Gänge heim.",al={"warum gibt es untote bergleute","mineneinsturz","einsturz in den todesminen"}},{q="Warum möchte Wilder ihre Gewerkschaftskarten der Bergleute haben?",a="Die Gewerkschaftskarten der Bergleute geben Aufschluss darüber, welche Arbeiter bei dem Einsturz starben. Ihre Leichen wurden nie geborgen, deshalb möchte Wilder die Karten zurückbringen und ihre Familien in Sturmwind erfahren lassen, was geschehen ist.",al={"wozu dienen die gewerkschaftskarten","gewerkschaftskarten der bergleute"}},{q="Wo sind die Gewerkschaftskarten zu finden?",a="Die Karten liegen in den heimgesuchten äußeren Tunneln unter Mondbruch, in den Gängen vor dem gesicherten Eingang zu den eigentlichen Todesminen.",al={"wo sind die karten zu finden","untote in den todesminen fundort","wo sind die toten bergleute"}},{q="Hat die Bruderschaft der Defias den Einsturz verursacht?",a="Wilder erinnert sich an einen schrecklichen Grubenunfall und Einsturz. Die Bruderschaft der Defias beherrscht nun die tiefen Gänge, doch der Einsturz scheint ein Arbeitsunfall gewesen zu sein, der die Bergleute einschloss.",al={"haben die defias den einsturz verursacht","wer hat die mine zum einsturz gebracht"}},{q="Gelten die Bergleute als Teil der Bruderschaft der Defias?",a="Nein. Sie waren gewöhnliche Gewerkschaftsarbeiter, als sich der Einsturz ereignete. Ihre untoten Überreste wandern an den Rändern der Höhlen umher, abseits von Edwin van Cleefs organisierten Defiastruppen tiefer im Inneren.",al={"sind die toten bergleute defias","gehören die untoten bergleute zu den defias"}}},fx={e1328ead={q="Was ist der Gewerkschaftsausweis eines Minenarbeiters?",a="Diese Gewerkschaftsausweise dienten als offizieller Identitätsnachweis für die Arbeiter, die vor der Katastrophe die reichen Adern der Minen von Mondbruch bearbeiteten. Heute sind sie der einzige bleibende Beweis dafür, wer unter der Erde ums Leben kam, als die Tunnel einstürzten. Sie zu bergen ist die einzige Möglichkeit, zu bestätigen, welche Arbeiter genau in den Tiefen ihr Ende fanden, was es Wilder Distelklette ermöglicht, deren trauernde Familien in Sturmwind zu benachrichtigen und ihnen Gewissheit zu geben.",al={"gewerkschaftsausweis eines minenarbeiters","was sind die gewerkschaftsausweise?","gewerkschaftsausweis"}},["22601dce"]={q="Warum benötigt Wilder Distelklette für diese Aufgabe einen Abenteurer?",a="Wilder Distelklette hat den schrecklichen Einsturz überlebt, doch die Tiefen der Minen von Mondbruch sind seither in gefährliches Chaos versunken. Das Gebiet um den alten Einsturz herum ist von feindlichen Kräften und ruhelosen Toten überlaufen, was weit über das hinausgeht, was ein gewöhnlicher Zivilist oder ehemaliger Minenarbeiter bewältigen kann. Da keine offiziellen Stadtwachen in die tückischen Ruinen von Westfall entsandt wurden, verlässt sich Wilder auf fähige Abenteurer, die ohnehin vorhaben, in die Minen vorzudringen, um in den Trümmern nach seinen verlorenen Freunden zu suchen.",al={"warum ich collecting memories","warum braucht wilder hilfe?","warum einen abenteurer schicken?"}}},fp="19,167,17.348.0,16.333.0,28.194.0,45.152.0,47.198.0,32.131.0,45.194.0,57.175.0"}
P.entries["quest:1680"] = {n="Tormus Tiefenschmied",s="In Eisenschmiede erwartet Tormus Tiefenschmied Kämpfer, die Muren Sturmlanze zu ihm schickt. Bevor er ihnen eine Waffe schmiedet, verlangt er, dass sie sich einer gefährlichen Prüfung stellen.",h="In Eisenschmiede erwartet Tormus Tiefenschmied Kämpfer, die Muren Sturmlanze zu ihm schickt.",kw={"zwergenschmied","die große schmiede","eisenschmiede","muren stormpike","tormus tiefenschmied","kriegerquest","waffenschmied"},ang={["class:Warrior"]="Muren Sturmlanze schickt vielversprechende Krieger zu Tormus Tiefenschmied in Eisenschmiede. Dort beweisen sie ihren Mut und suchen eine Waffe, die für ihre Berufung geschmiedet wird.",["faction:Alliance"]="Die Meisterschmiede von Eisenschmiede prüfen vielversprechende Kämpfer der Allianz mit gefährlichen Unterfangen, bevor sie ihnen edle Waffen schmieden."},sec={{t="Der Amboss des Schmieds",b="Tormus Tiefenschmied ist ein meisterhafter zwergischer Waffenschmied in Eisenschmiede. Krieger, die Muren Sturmlanze ihr wachsendes Können zeigen, werden quer durch die Stadt geschickt, um ihn aufzusuchen. Tormus ist für robuste, mächtige Waffen bekannt, doch er gibt nicht jedem Vorbeikommenden feine Klingen oder Schlagwaffen. Ein Krieger muss sich seine Arbeit durch Taten verdienen."},{t="Eine gefährliche Prüfung",b="Bevor Tormus einwilligt, eine Waffe zu schmieden, verlangt er vom Abenteurer das Versprechen, ihm einen Gefallen zu tun. Er spricht offen über die bevorstehende Gefahr und warnt, dass sie ein Leben kosten könnte. Für ihn ist Gefahr kein Grund umzukehren. Sie ist die rechte Prüfung für den Mut eines Kriegers."}},faq={{q="Wer ist Tormus Tiefenschmied?",a="Tormus Tiefenschmied ist ein versierter Waffenschmied in Eisenschmiede. Er kann außergewöhnliche Waffen für Krieger schmieden, die ihren Mut und ihr Können durch gefährliche Taten beweisen.",al={"wer ist tormus","tormus tiefenschmied eisenschmiede","wer ist tormus tiefenschmied"}},{q="Wer schickt Euch zu Tormus Tiefenschmied?",a="Muren Sturmlanze schickt vielversprechende Kämpfer zu Tormus Tiefenschmied, wenn sie bereit für eine Waffe sind, die ihrem wachsenden Kampfgeschick entspricht.",al={"wer hat mich zu tormus geschickt","warum mit tormus sprechen","muren stormpike empfehlung"}},{q="Was verlangt Tormus Tiefenschmied dafür, dass er eine Waffe schmiedet?",a="Tormus erklärt sich bereit, eine edle Waffe zu schmieden, nachdem der Abenteurer ihm einen Gefallen getan hat. Er verlangt ein gefährliches Unterfangen, das den Tod bedeuten könnte, die Art von Herausforderung, die ein aufstrebender Krieger seiner Ansicht nach sucht.",al={"tormus gefallen","welche waffe schmiedet tormus","was will tormus"}},{q="Warum betont Tormus, dass die Aufgabe gefährlich ist?",a="Tormus warnt, dass das Unterfangen gefährlich ist, weil es ein Leben kosten könnte. Er glaubt, dass Gefahr die rechte Prüfung für jeden ist, der seiner Handwerkskunst würdig ist.",al={"ist tormus tiefenschmied gefährlich","was ist tormus aufgabe","eisenschmiede kriegerquest tormus"}},{q="Wo ist Tormus Tiefenschmied zu finden?",a="Tormus Tiefenschmied arbeitet nahe der Großen Schmiede in Eisenschmiede. Andere Schmiede, Ambosse und dröhnende Schmelzöfen umgeben ihn.",al={"wo ist tormus","tormus tiefenschmied standort"}},{q="Mit welchen Abenteurern arbeitet Tormus Tiefenschmied zusammen?",a="Tormus arbeitet mit Kriegern zusammen, die von ihren Ausbildern geschickt werden. Er sucht Kämpfer mit dem Mut und der Entschlossenheit, sich lebensbedrohlichen Gefahren zu stellen.",al={"welche klasse bekommt tormus quest","ist tormus nur für krieger"}}},fp="16,149,22.311.0,16.250.0,24.168.0,45.132.0,61.194.0,52.145.0,36.115.0,50.128.0"}
P.entries["quest:1681"] = {n="Eisenbands Truppenlager",s="In Eisenbands Truppenlager sucht Tormus Tiefenschmied Rache für seinen ermordeten Mentor Sturgy Ironband. Seltener Schatteneisenstein lockte die Dunkeleisenzwerge zum Vorposten und brachte ihm den Untergang.",h="In Eisenbands Truppenlager sucht Tormus Tiefenschmied Rache für seinen ermordeten Mentor Sturgy Ironband.",kw={"schmiedekunst","dunkeleisen","dun morogh","helmsbettsee","eisenbands truppenlager","sturgy ironband","tormus tiefenschmied","schatteneisenstein"},ang={["profession:Blacksmithing"]="Sturgy Ironbands Schicksal zeigt, welche Gefahr unerprobte Erze für eine Schmiede bergen können.",["race:Dwarf"]="Der Angriff auf Ironbands Vorposten spiegelt den bitteren Hass zwischen den Bronzebeard-Zwergen aus Eisenschmiede und ihren Verwandten vom Dunkeleisenclan wider."},sec={{t="Der Tod eines Meisters",b="Südlich des Helmsbettsees lehrte Sturgy Ironband die Schmiedekunst in einem Lager fernab der überfüllten Ambosse der Großen Schmiede. Vielversprechende Schüler kamen dorthin, um bei einem Meister zu lernen, der in ganz Eisenschmiede als unvergleichlicher Ausbilder verehrt wurde. Dann erwarb ein Schüler ein unbekanntes Mineral namens Schatteneisenstein, und Sturgy beschloss, damit zu experimentieren. Er wusste nicht, dass dessen Anwesenheit seine Schule dem Untergang geweiht hatte."},{t="Der Überfall der Dunkeleisenzwerge",b="Kurz nach der Ankunft des Schatteneisensteins griffen Dunkeleisenzwerge das Lager an. Sie töteten Sturgy Ironband und jeden seiner Lehrlinge und besetzten dann das Gelände. Tormus Tiefenschmied, einer von Ironbands überlebenden Schützlingen in der Hauptstadt, will das Massaker nicht ungesühnt lassen. Er schickt Reisende der Allianz los, um seinen Lehrer zu rächen und das Erz zu bergen, das dem Vorposten die Zerstörung brachte."}},faq={{q="Wo liegt Eisenbands Truppenlager?",a="Eisenbands Truppenlager liegt im östlichen Dun Morogh, südlich des Helmsbettsees.",al={"ironband standort","wo liegt das lager","eisenbands truppenlager finden"}},{q="Wer war Sturgy Ironband?",a="Sturgy Ironband war ein angesehener zwergischer Meisterschmied, der in einem Lager außerhalb von Eisenschmiede fortgeschrittene Metallbearbeitung lehrte. Dunkeleisenzwerge töteten ihn bei einem Überfall.",al={"wer ist ironband","sturgy ironband geschichte","wer war sturgy"}},{q="Warum griffen die Dunkeleisenzwerge das Lager an?",a="Einer von Ironbands Schülern brachte Schatteneisenstein ins Lager und lockte damit die Dunkeleisenzwerge dorthin. Sie griffen kurz nach dessen Ankunft an, töteten alle Anwesenden und übernahmen das Gelände.",al={"warum der angriff","warum der dunkeleisenüberfall","dunkeleisen motiv"}},{q="Was ist Schatteneisenstein?",a="Schatteneisenstein ist ein seltenes, geheimnisvolles Mineral, das Meister Ironbands Interesse weckte. Seine Ankunft zog die tödliche Aufmerksamkeit des Dunkeleisenclans auf sich.",al={"schatteneisenstein geschichte","was ist schatteneisenstein","seltsames erz"}},{q="Wer ist Tormus Tiefenschmied?",a="Tormus Tiefenschmied ist ein Schmied aus Eisenschmiede und ehemaliger Lehrling von Sturgy Ironband. In Trauer um seinen Lehrer schickt er Reisende los, um die eingedrungenen Dunkeleisenzwerge zu bestrafen und das Erz zurückzuholen.",al={"wer vergibt eisenbands truppenlager","tormus tiefenschmied geschichte","wer ist tiefenschmied"}},{q="Was will Tormus aus dem Lager zurückhaben?",a="Tormus will, dass Reisende Ironband rächen, indem sie die Dunkeleisenangreifer vertreiben und die Lieferung Schatteneisenstein bergen, die das Unheil brachte.",al={"was bergen","lager ziel","quest abgeben"}}},fp="19,174,15.393.0,18.392.0,37.73.0,24.162.0,50.191.0,19.146.0,24.190.0,50.147.0"}
P.entries["quest:1683"] = {n="Vorlus Elendshuf",s="In Darnassus stellt Elanaria junge Nachtelfenkrieger auf die Probe. Sie müssen einen Satyr jagen, der einen verborgenen Mondbrunnen nahe dem Grabhügel von Ban'ethil entweiht.",h="In Darnassus stellt Elanaria junge Nachtelfenkrieger auf die Probe.",kw={"ban'ethil","darnassus","elanaria","horn von vorlus","mondbrunnen","satyr","teldrassil","vorlus elendshuf","kriegerquest"},ang={["class:Warrior"]="Als Krieger beginnt mit der Jagd auf Vorlus Eure Einweihung in die fortgeschrittene Kampfausbildung. Sie beweist, dass Eure Klinge die Lande der Kaldorei und die Heiligkeit der Göttin schützt.",["faction:Alliance"]="Als Mitglied der Allianz helft Ihr, das Innere Teldrassils vor lauernden dämonischen Überresten zu sichern. Darnassus bleibt ein unerschütterliches Bollwerk der Allianz im nördlichen Kalimdor.",["race:NightElf"]="Als Nachtelf wisst Ihr, dass Mondbrunnen Elunes Reinheit und die Lebensader der Spiritualität der Kaldorei widerspiegeln. Ein Satyr, der in ihren Wassern badet, beleidigt alle Nachtelfen."},sec={{t="Eine Prüfung der Entschlossenheit",b="Elanaria verlangt von Euch einen Beweis Eurer Hingabe und Disziplin, bevor sie Euch fortgeschrittene Kampftechniken lehrt. Wer Kalimdor verteidigt, muss mehr als Worte bieten. Ein Beschützer muss sich der Verderbnis stellen und die heiligen Äste von Teldrassil reinigen."},{t="Entweihung der heiligen Wasser",b="Eure Prüfung führt Euch zu einem Mondbrunnen in den Bergen südöstlich des Grabhügels von Ban'ethil. Dort verbirgt sich Vorlus Elendshuf. Satyrn waren uralte Verräter, durch dämonischen Einfluss entstellt, und sie hassen heilige Relikte der Kaldorei. Vorlus badet im Mondbrunnen, besudelt dessen gesegnete Wasser und verhöhnt Elune's Grace."},{t="Das Horn als Beweis",b="Gnarlpine-Furbolgs bewachen einen verborgenen Bergpfad zu Vorlus. An der verdorbenen Quelle stellt Ihr Euch dem Satyr im Kampf. Bringt sein Horn als Beweis seines Todes zur Terrasse der Krieger in Darnassus. Die Heiligkeit der Lichtung kann wiederhergestellt werden, und der Weg zu spezialisierten Kriegswaffen öffnet sich."}},faq={{q="Wer ist Vorlus Elendshuf?",a="Vorlus Elendshuf ist ein verderbter Satyr, der auf Teldrassil lebt. Er fand einen abgelegenen Mondbrunnen südöstlich des Grabhügels von Ban'ethil und begann, in dessen geweihten Wassern zu baden und sie zu entweihen.",al={"vorlus elendshuf hintergrund","wer ist vorlus","vorlus der satyr"}},{q="Warum schickt Elanaria Krieger gegen Vorlus aus?",a="Elanaria schickt Euch gegen Vorlus aus, um einen vielversprechenden Krieger zu prüfen. Der Sieg über diesen gefährlichen, verderbten Unhold beweist die nötige Konzentration, den Mut und die Entschlossenheit, bevor sie Euch fortgeschrittene Kampffertigkeiten lehrt oder beim Schmieden spezialisierter Waffen anleitet.",al={"warum vorlus töten","elanarias questgrund","zweck der quest um vorlus elendshuf"}},{q="Wo liegt der verborgene Mondbrunnen?",a="Der verborgene Mondbrunnen liegt in den Höhenzügen südöstlich des Grabhügels von Ban'ethil. Ein unscheinbarer, von Fackeln gesäumter Bergpfad beginnt direkt hinter einem Lager der Gnarlpine-Furbolgs östlich der Grabhügel.",al={"vorlus aufenthaltsort","wie vorlus finden","pfad zum verborgenen mondbrunnen"}},{q="Was ist ein Mondbrunnen, und warum ist seine Anwesenheit dort von Bedeutung?",a="Mondbrunnen sind heilige Becken mit gesegnetem Wasser, die Elunes Licht kanalisieren und die Lebenskraft der Natur erhalten. Ein dämonischer Satyr, der darin badet, entweiht den Glauben der Kaldorei und bringt eine gefährliche Quelle der Verderbnis nach Teldrassil.",al={"warum sind mondbrunnen wichtig","entweihung des mondbrunnens","mondbrunnen der nachtelfen"}},{q="Was folgt nach dem Sieg über Vorlus Elendshuf?",a="Bringt Vorlus' abgetrenntes Horn zurück, und Elanaria bestätigt, dass Ihr bereit seid. Sie schickt Euch weiter, um die legendären Weapons of Elunite zu erlangen, beginnend mit Shade of Elura.",al={"nächste quest nach vorlus","was geschieht als nächstes","shade of elura quest"}},{q="Gibt es weitere Satyrn auf Teldrassil?",a="Ja. Satyrn lauern auf Teldrassil, unter anderem am Teufelsfels und in verstreuten verderbten Senken. Sie versuchen, den Weltbaum mit dämonischer Verderbnis zu infizieren.",al={"satyrn auf teldrassil","satyrbedrohung auf teldrassil"}}},fx={["2a0bd33d"]={q="Warum möchte Elanaria, dass Vorlus Vilehoof getötet wird?",a="Für Elanaria und die Nachtelfen sind Mondbrunnen heilige Zufluchtsorte, die mit gesegnetem Wasser gefüllt sind. Vorlus Vilehoof hat einen abgelegenen Mondbrunnen südöstlich des Grabhügels von Ban'ethil entdeckt und entweiht ihn aktiv, indem er seinen korrupten Satyrdreck in dessen heiliges Wasser spritzt. Elanaria kann eine solche Schändung auf Teldrassil nicht dulden, und die Vernichtung der Bestie beseitigt eine unmittelbare Bedrohung durch Verderbnis vom Großen Baum.",al={"elanaria beweggrund","warum vorlus töten","elanaria grund vorlus"}}},fp="15,142,17.236.0,26.296.0,17.278.1,23.187.0,45.234.0,37.186.0,53.218.0,43.168.1,37.142.0"}
P.entries["quest:1685"] = {n="Gakins Beschwörung",s="In Sturmwind führt Gakins Beschwörung vielversprechende Hexenmeister unter das Slaughtered Lamb. Remen Marcot überbringt die Nachricht von Gakin dem Dunkelbinder und schickt angehende Praktizierende zur weiteren okkulten Ausbildung in die Krypten unter der Taverne im Magierviertel.",h="In Sturmwind führt Gakins Beschwörung vielversprechende Hexenmeister unter das Slaughtered Lamb.",kw={"dämonologie","gakin der dunkelbinder","das magierviertel","remen marcot","slaughtered lamb","sturmwind","leerwandler","hexenmeister"},ang={["class:Warlock"]="Als Hexenmeister lasst Ihr Taschenspielertricks und niedere Wichtel hinter Euch. Die bevorstehenden Prüfungen bereiten Euch darauf vor, einen Leerwandler zu versklaven, der Euch im Kampf schützt.",["faction:Alliance"]="Als Mitglied der Allianz wisst Ihr, dass Sturmwind einen verborgenen Zirkel von Schattenwirkern duldet. Ihr Wissen um die Teufelsmagie verschafft der Allianz einen Vorteil gegenüber ihren Feinden."},sec={{t="Eine diskrete Nachricht",b="Dämonologie ist in Sturmwinds bewohnten Vierteln verboten, doch ihre Praktizierenden wirken unweit der Stadtwache. Wenn ein Hexenmeister Geschick im Umgang mit seinen ersten Wichteln zeigt, erreicht die Kunde heimlich erfahrene Hexenmeister. Remen Marcot überbringt ihre Nachricht unauffällig und mahnt angehende Praktizierende, den Treffpunkt geheim zu halten, während sie sich unter das Magierviertel begeben."},{t="Die Krypten des Slaughtered Lamb",b="Hinter der bescheidenen Fassade des Slaughtered Lamb liegen Keller und verborgene Katakomben. Gakin der Dunkelbinder unterrichtet dort Sturmwinds Hexenmeister, außerhalb der Reichweite der Magier der Kirin Tor und der Inquisitoren der Kathedrale. Unter seiner Anleitung lernen Hexenmeister, einen Leerwandler zu befehligen. Der Ritus erfordert gefährliche gestohlene Reagenzien und gefahrvolle Beschwörungskreise."}},faq={{q="Warum ruft Gakin der Dunkelbinder Hexenmeister zu sich?",a="Gakin ruft angehende Hexenmeister zu sich, sobald sie genügend Erfahrung gesammelt haben. Er betrachtet Unausgebildete als Gefahr, da sie leicht den Kopf verlieren könnten, und lehrt sie das komplexe Ritual, einen Leerwandler an ihre Dienste zu binden.",al={"warum gakin ruft","wozu dient gakins beschwörung","leerwandlerquest beginn"}},{q="Wo befindet sich Gakin der Dunkelbinder?",a="Gakin hält sich in tiefen Krypten unter dem Slaughtered Lamb verborgen, einer Taverne in Sturmwinds Magierviertel.",al={"wo ist gakin","gakin standort","slaughtered lamb keller"}},{q="Wer ist Remen Marcot?",a="Remen Marcot ist ein Verbündeter von Sturmwinds Hexenmeisterzirkel. Er hält sich im Keller des Gasthauses \"Zur Höhle des Löwen\" in Goldhain auf, sucht vielversprechende Kandidaten und führt sie unauffällig zu Gakins verborgener Enklave.",al={"remen marcot","wer startet gakins beschwörung"}},{q="Warum muss der Ort geheim bleiben?",a="Teufelsmagie und Dämonenbeschwörung sind im Königreich Sturmwind verboten. Die Silver Hand, die Kathedrale des Lichts oder die Stadtwachen könnten den Zirkel entdecken, was Haft oder Hinrichtung nach sich ziehen würde.",al={"warum geheim","hexenmeister geheimhaltung sturmwind"}},{q="Was folgt, nachdem man Gakins Ruf gefolgt ist?",a="Nachdem Ihr Euch bei Gakin gemeldet habt, schickt er Euch zu Brackbrunns Kürbisbeet im Wald von Elwynn. Dort sollt Ihr Surena Caledon einen Blutsteinhalsreif abnehmen, der für das Ritual zur Bindung des Leerwandlers unerlässlich ist.",al={"nächste quest nach gakins beschwörung","was passiert als nächstes"}},{q="Können auch andere Klassen diesen Ruf erhalten?",a="Nein. Nur Hexenmeister, die den Umgang mit ihrem ersten Wichtelbegleiter gemeistert haben, erhalten den Ruf und weiterführenden okkulten Unterricht.",al={"können magier das erhalten","wer kann gakins beschwörung machen"}}},fx={["0d517c2f"]={q="Warum möchte Remen Marcot, dass Ihr Gakin aufsucht?",a="Remen Marcot handelt ausschließlich auf Befehl von Meister Gakin der Dunkelbinder. Er hat den ganzen Tag damit verbracht, die Stadt nach Euch abzusuchen, und ist dabei zusehends frustriert geworden. Sein einziges Ziel ist es, seine Aufgabe zu erfüllen, damit er aufhören kann, Euch hinterherzujagen, und zu seinen eigenen Geschäften zurückkehren kann. Er warnt Euch, Euch schnellstmöglich zu melden, bevor Euer Meister die Geduld verliert.",al={"warum schickt remen einen zu gakin","remen marcot motiv","warum sucht remen nach einem"}}},fp="15,248,18.350.0,34.337.0,46.213.0,38.98.0,20.200.0,37.194.0,43.199.1,38.114.0"}
P.entries["quest:1686"] = {n="Eluras Schemen",s="Elanaria schickt junge Nachtelfenkrieger unter die Wellen von Auberdine, um Elura zur Ruhe zu betten. Sie suchen ihr Medaillon und Elunite-Erz für eine Waffe, die Smith Mathiel schmieden wird.",h="Elanaria schickt junge Nachtelfenkrieger unter die Wellen von Auberdine, um Elura zur Ruhe zu betten.",kw={"auberdine","dunkelküste","darnassus","elanaria","elunite-erz","elura","eluras schemen","smith mathiel","weapons of elunite"},ang={["class:Warrior"]="Als Nachtelfenkrieger beweist Ihr Eure Zähigkeit im Wasser und Eure Disziplin im Kampf. Die Prüfung bringt Euch eine geschmiedete Elunite-Waffe ein.",["profession:Blacksmithing"]="Als Schmied erkennt Ihr die Handwerkskunst der Nachtelfen an den mächtigen Waffen, die sie aus gesegneten Elunite-Materialien fertigen.",["race:NightElf"]="Als Nachtelf ehrt Ihr eine andere Kaldorei, indem Ihr Eluras Schemen zur Ruhe bettet. Ihr Pflichtgefühl hielt sie seit Generationen unter den Wellen gebunden."},sec={{t="Die ewige Wacht einer Kapitänin",b="Vor langer Zeit lief ein Schiff mit seltenem Elunite-Erz nahe dem Leuchtturm von Auberdine auf Felsen und sank. Seine Kapitänin Elura verfluchte ihre eigene Seele aus Verzweiflung und unerschütterlichem Pflichtgefühl. An das Wrack unter den Wellen gebunden, bewacht ihr Schemen die verlorene Fracht vor allen, die sie antasten wollen."},{t="Waffen aus Elunit",b="Elanaria schickt junge Nachtelfenkrieger in die Brandung der Dunkelküste, um Elura zu besiegen und ihr Medaillon sowie Erz zu bergen. Beides wird benötigt, um die Kapitänin zur Ruhe zu betten, und das Metall gelangt in Smith Mathiels Schmiede. Die Prüfung stellt ihr Kampfgeschick und ihre Achtung vor den Gefallenen auf die Probe. Sie liefert auch Erz für eine geschmiedete Waffe."}},faq={{q="Wer ist Eluras Schemen?",a="Elura befehligte ein Elfenschiff, das im seichten Wasser nahe dem Leuchtturm von Auberdine Schiffbruch erlitt. Aus Verzweiflung und Pflichtgefühl verfluchte sie ihre Seele dazu, die gesunkene Ladung Elunite-Erz zu bewachen.",al={"eluras schemen hintergrundgeschichte","wer ist elura","kapitänin elura"}},{q="Warum schickt Elanaria Krieger gegen Elura aus?",a="Elanaria schickt Krieger aus, um Elura zu besiegen, ihr Medaillon und Erz zu bergen und ihren Geist zur Ruhe zu betten. Die Prüfung stellt ihr Kampfgeschick auf die Probe und liefert Metall für eine Waffe.",al={"warum töten wir elura","elanaria quest zweck"}},{q="Wo geschah der Schiffbruch?",a="Das Wrack liegt unter Wasser vor Auberdines Küste in der Dunkelküste. Es liegt nahe dem Leuchtturm und unmittelbar südlich der Hauptanlegestellen des Hafens.",al={"wo ist das schiffswrack","eluras schiff fundort"}},{q="Wofür wird Elunite-Erz verwendet?",a="Nachtelfische Schmiede schmieden Waffen aus seltenem Elunite-Erz. Smith Mathiel in Darnassus nutzt die geborgenen Kisten, um für vielversprechende Krieger eine auf sie zugeschnittene Kampfwaffe anzufertigen.",al={"was ist elunite","elunite-erz verwendung"}},{q="Schadet ein Sieg über den Schemen Elura dauerhaft?",a="Ein Sieg über Elura bricht den Fluch, der ihren Geist an den Meeresboden bindet. Elanaria sagt, dass ein Sieg über die Kapitänin im Kampf ihr nach ihrer langen Wacht Frieden bringt.",al={"ist elura gestorben","ist elura gerettet"}},{q="Wer fertigt die Waffe an, sobald das Erz gesammelt ist?",a="Nachdem Elanaria das Erz und das Medaillon erhalten hat, schickt sie den Krieger zu Smith Mathiel auf der Terrasse der Krieger in Darnassus. Er verarbeitet das Metall zu einer außergewöhnlichen Waffe.",al={"wer fertigt die elunite-waffe","nächste quest nach elura"}}},fx={["522232db"]={q="Warum schickt Elanaria Euch, anstatt das Erz selbst zu bergen?",a="Als Eure Kriegerausbilderin führt Elanaria Euch durch den Ritus des Übergangs zur wahren Kampfbeherrschung. Das Elunit-Erz zu bergen ist nicht bloß ein Besorgungsgang für Darnassus; den tückischen Tiefen vor Auberdine zu trotzen und den ruhelosen Geist von Kapitän Elura zu erlösen, beweist, dass Ihr den Mut und das Geschick besitzt, die eine eigens für einen Krieger geschmiedete Waffe verdienen.",al={"warum ich schatten von elura","warum elanaria schickt krieger","warum keine wachen für elura"}}},fp="18,166,25.278.0,18.308.0,26.177.0,44.162.0,27.128.0,29.169.0,48.148.0,48.166.0"}
P.entries["quest:1688"] = {n="Surena Caledon",s="Unter dem Slaughtered Lamb in Sturmwind sucht Gakin nach seiner früheren Schülerin und dem Blutsteinhalsreif, den sie trägt. Er schickt einen neuen Lehrling hinter Surena Caledon her, die ihn verraten und sich der Bruderschaft der Defias angeschlossen hat.",h="Unter dem Slaughtered Lamb in Sturmwind sucht Gakin nach seiner früheren Schülerin und dem Blutsteinhalsreif...",kw={"blutsteinhalsreif","brackbrunns kürbisbeet","defias","erlan drudgemoor","gakin der dunkelbinder","slaughtered lamb","surena caledon","leerwandler"},ang={["class:Warlock"]="Als Hexenmeister müsst Ihr Euch bei der Jagd auf Surena Caledon bewähren. Gakin lehrt, dass Verrat einen tödlichen Preis hat und Gefühle keinen Platz in den dunklen Künsten haben.",["race:Human"]="Als Mensch seht Ihr, wie die Bruderschaft der Defias weiterhin unzufriedene Bürger des Königreichs Sturmwind verlockt."},sec={{t="Ein verbitterter Meister",b="Unter dem Slaughtered Lamb im Mage Quarter von Sturmwind lehrt Gakin der Dunkelbinder Novizen die verbotenen Künste der Teufelsbeschwörung. Einst nahm er Surena Caledon als Schülerin auf. Er bewunderte ihre natürliche magische Begabung und ihre Schönheit. Doch Surena gab ihre Studien und Gakins Gunst auf und floh dann mit ihrem Geliebten Erlan Drudgemoor aus Sturmwind, um sich der Bruderschaft der Defias anzuschließen."},{t="Der gestohlene Blutstein",b="Surenas Überleben ist Gakin völlig gleichgültig. Er will den Blutsteinhalsreif, den er ihr während ihrer Ausbildung schenkte. Also schickt er seinen neuesten Lehrling nach Südosten zu Brackbrunns Kürbisbeet im Wald von Elwynn, einem von Defiasbanditen überrannten Gehöft. Der Lehrling soll Surena das Schmuckstück mit allen nötigen Mitteln abnehmen. Der Blutstein wird als magischer Katalysator für die nächste Prüfung dienen: einen Leerwandler zu beschwören und zu binden."}},faq={{q="Wer ist Surena Caledon?",a="Surena Caledon war die Schülerin von Gakin dem Dunkelbinder in Sturmwind. Sie war von Natur aus begabt und gewann seine Gunst und Geschenke, bevor sie ihre Studien aufgab, um mit dem Defiasbanditen Erlan Drudgemoor zu fliehen.",al={"surenas geschichte","wer ist surena","surena caledons vorgeschichte"}},{q="Warum will Gakin ihren Halsreif zurück?",a="Gakin schenkte Surena den Halsreif während ihrer Ausbildung, und er will dessen wertvollen Blutstein. Er nimmt ihr den Verrat übel und braucht den Stein als Ritualreagenz, um seinem neuen Lehrling zu helfen, einen Leerwandler zu binden.",al={"warum den halsreif zurückholen","bedeutung des blutsteinhalsreifs"}},{q="Wo ist Surena Caledon zu finden?",a="Ihr findet Surena mit ihren Defiasgefährten bei Brackbrunns Kürbisbeet, einem verlassenen Gehöft im Südosten des Waldes von Elwynn.",al={"surenas aufenthaltsort","wo ist surena","wo ist das kürbisbeet"}},{q="Was geschieht nach der Rückholung des Halsreifs?",a="Wenn Ihr Gakin den Blutsteinhalsreif zurückbringt, ist die Prüfung abgeschlossen. Als Nächstes betretet Ihr den Beschwörungskreis in den Krypten unter dem Slaughtered Lamb und bindet einen Leerwandler aus dem Twisting Nether.",al={"what comes next","nächste quest nach surena"}},{q="Wer ist Erlan Drudgemoor?",a="Erlan Drudgemoor ist ein Schurke der Bruderschaft der Defias. Er verführte Surena Caledon und überredete sie, ihre Hexenmeisterausbildung aufzugeben und aus Sturmwind zu fliehen, um unter den Banditen zu leben.",al={"erlans geschichte","wer ist erlan drudgemoor"}},{q="Zeigt Gakin Reue über Surenas Schicksal?",a="Gakin zeigt keine Reue über Surenas Schicksal. Er sagt, ihr Leben bedeute ihm nichts und es sei eine Schande, ihr magisches Talent zu vergeuden, doch ihr Verrat mache ihre Beseitigung notwendig.",al={"kümmert es gakin","gakins reaktion auf surena"}}},fx={["8bc53c35"]={q="Wozu dient Surenas Halsreif?",a="Der Halsreif ist ein verzaubertes Schmuckstück aus Blutstein, das Gakin der Dunkelbinder törichterweise seiner ehemaligen Schülerin schenkte. Für einen Hexenmeister birgt Blutstein rohe arkanmagische und beschwörerische Macht. Gakin benötigt die anhaltende Kraft des Artefakts, um den Ritualkreis unter dem The Slaughtered Lamb vorzubereiten, damit Ihr einen Leerwandler beschwören und an Euren Willen binden könnt.",al={"zweck von surenas halsreif","warum blutsteinhalsreif","was macht der halsreif"}},["703ff238"]={q="Warum schickt Gakin einen Lehrling, anstatt sich selbst um Surena zu kümmern?",a="Hexenmeister in Sturmwind operieren in strikter Geheimhaltung unter dem The Slaughtered Lamb; sie sind nach den Gesetzen des Königreichs verboten und werden bei Entdeckung gejagt. Gakin kann die Stadtwache nicht bitten, ein illegales magisches Erbstück von Defias-Gesetzlosen zu bergen, noch kann er sein Sanktum verlassen, um eine persönliche Peinlichkeit zu bereinigen. Euch zu schicken, testet Eure Skrupellosigkeit und beweist, ob Ihr den nötigen Schneid besitzt, um die dunklen Künste zu meistern.",al={"warum schickt sie mich surena","warum kann gakin den halsreif nicht holen","warum geht gakin nicht selbst"}}},fp="14,210,15.361.0,21.418.1,22.198.0,36.203.0,34.128.0,41.198.1,24.176.0,47.178.0"}
P.entries["quest:1689"] = {n="Die Bindung",s="Unter Sturmwind stellt Euch Gakin der Dunkelbinder eine letzte Prüfung. Mit seinem wiederbeschafften Blutsteinhalsreif zieht Ihr einen Leerwandler in einen verborgenen Kreis und zwingt ihn zur Unterwerfung.",h="Unter Sturmwind stellt Euch Gakin der Dunkelbinder eine letzte Prüfung.",kw={"bindung","blutsteinhalsreif","gakin der dunkelbinder","das magierviertel","slaughtered lamb","sturmwind","beschwörungskreis","leerwandler"},ang={["class:Warlock"]="Als Hexenmeister erhaltet Ihr einen Leerwandler, der Euch verteidigt. Dieser Ritus markiert Euren Übergang vom unerfahrenen Beschwörer zum Gebieter über Wesen jenseits dieser Welt.",["faction:Alliance"]="Als Mitglied der Allianz dient Ihr einer Sache, die für das Heilige Licht und die arkane Ordnung eintritt. In gefährlichen Zeiten drücken pragmatische Anführer angesichts der dunklen Praktiken unter dem Magierviertel ein Auge zu.",["race:Gnome"]="Als Gnomenhexenmeister bringt Ihr einen präzisen, wissbegierigen Geist in die dunkle Beschwörung ein. Unter Gakins Anleitung erforscht Ihr die Unterwerfung von Leerenwesen als metaphysisches Experiment.",["race:Human"]="Als menschlicher Hexenmeister steht Ihr unter strenger Beobachtung der Priesterschaft von Sturmwind. Ihr beherrscht gefährliche Wesen im Schatten und haltet Eure Macht vor der Stadt über Euch verborgen."},sec={{t="Unterwerfung in den Krypten",b="Unter dem Slaughtered Lamb in Sturmwinds Magierviertel liegen Katakomben, fernab der wachsamen Blicke der Silbernen Hand und der Magistrate der Kirin Tor. Gakin lehrt, dass dunkle Magie mehr als Macht erfordert. Sie verlangt die Beherrschung von Wesen jenseits dieser Welt. Ihr habt seinen gestohlenen Blutsteinhalsreif von Surena Caledon zurückgeholt. Nun fordert er Euch auf, unter der Taverne einen Leerwandler zu beschwören."},{t="Willenskraft gegen die Leere",b="Ein Leerwandler wird nicht mit Euch verhandeln. Der Blutsteinhalsreif öffnet einen Riss und zieht die Schattenkreatur in die Welt der Sterblichen. Ihr setzt ihr mit Magie und Gewalt zu, bis ihr Wille bricht. Dann bindet sich ihre Essenz an Euch und gibt Euch einen zähen, schattenhaften Beschützer, der in den kommenden Schlachten schwere Schläge einstecken kann."}},faq={{q="Wo befindet sich der Beschwörungskreis?",a="Der Beschwörungskreis liegt tief in den Katakomben unter dem Slaughtered Lamb in Sturmwinds Magierviertel. Folgt von Gakin dem Dunkelbinder aus den Treppen in die unterirdischen Gänge und steigt dann zur untersten Kammer hinab. Eine violett leuchtende Ritualrune zeichnet sich auf dem Steinboden ab.",al={"standort des beschwörungskreises","wo den leerwandler beschwören","wo ist der kreis"}},{q="Wer ist Gakin der Dunkelbinder?",a="Gakin der Dunkelbinder ist ein Hexenmeisterlehrer unter dem Slaughtered Lamb in Sturmwind. Im Verborgenen lehrt er vielversprechende Menschen und Gnome, dämonische und von der Leere berührte Wesen zu beschwören und zu beherrschen, fernab der Stadtwache und Kirchenobrigkeit.",al={"wer ist gakin","geschichte von gakin dem dunkelbinder","gakin"}},{q="Wozu dient der Blutsteinhalsreif?",a="Surena Caledon stahl den Blutsteinhalsreif, und Ihr habt ihn für Gakin zurückgeholt. Seine gebündelte Magie hilft einem angehenden Hexenmeister, den Schleier zu durchbrechen und einen Leerwandler in den Beschwörungskreis zu ziehen.",al={"verwendung des blutsteinhalsreifs","wozu wird der halsreif benötigt","halsreif"}},{q="Warum müssen Hexenmeister gegen ihre Dämonen kämpfen, um sie zu binden?",a="Dämonen und Leerenkreaturen dienen sterblichen Meistern nicht freiwillig. Ein Hexenmeister muss ein solches Wesen im Kampf durch Stärke und Willenskraft brechen, bevor er es an sich bindet und zum Dienst zwingt.",al={"warum gegen den leerwandler kämpfen","warum dämonen unterwerfen","dämonenunterwerfung"}},{q="Was geschieht nach Abschluss des Rituals?",a="Nachdem Ihr die Kreatur besiegt und Gakin den Halsreif zurückgegeben habt, erlangt Ihr das Wissen und die Technik, einen treuen Leerwandler zu beschwören und zu befehligen. Er kann Euch auf Euren Reisen schützen.",al={"welche belohnung gibt es","leerwandlerzauber","nach der bindung"}},{q="Warum wird dieses Ritual heimlich unter einer Taverne durchgeführt?",a="Dämonologie und Leerenmagie sind tabu. Die Kirche des Heiligen Lichts und die Magier der Allianz stehen ihnen feindselig gegenüber. Hexenmeister in Sturmwind üben ihre Künste in verborgenen Kellern und Katakomben aus, fernab der Obrigkeit.",al={"warum unter der taverne verborgen","ist teufelsmagie illegal","slaughtered lamb keller"}}},fx={bc8c924d={q="Warum möchte Gakin der Dunkelbinder, dass Ihr einen Leerwandler beschwört?",a="Gakin erkennt rohes Potenzial in Euch, nachdem Ihr seinen Blutsteinhalsreif zurückgeholt habt, doch er betrachtet Eure magische Ausbildung als unvollständig. Ein wahrer Hexenmeister zu sein erfordert weit mehr, als nur Schattenenergien zu kanalisieren; es verlangt den Willen, Kreaturen des Nether zu beherrschen. Bevor er Euch lehren kann, wie Ihr einen Leerwandler im Kampf richtig befehligt, müsst Ihr Eure Überlegenheit über einen solchen mit Eurer eigenen Macht unter Beweis stellen.",al={"warum will gakin das","gakin beweggrund","warum leerwandler binden"}},["8fb1392b"]={q="Was ist das für ein Leerwandler, den Ihr beschwört?",a="Ihr beschwört eine feindselige Entität aus dem Wirbelnden Nether in den Beschwörungskreis unterhalb des Gasthauses. Leerwandler sind schattenhafte, widerstandsfähige Wesen, die von chaotischer Bosheit angetrieben werden. Durch die Macht des Blutsteinhalsreifs über die Schwelle gezogen, wird diese Kreatur augenblicklich angreifen und versuchen, ihren Beschwörer zu vernichten, es sei denn, sie wird durch physischen und magischen Kampf zur Unterwerfung gezwungen.",al={"was für ein leerwandler","gegen wen kämpft ihr","beschworener leerwandler"}},b41bc1ad={q="Warum lässt Gakin Euch den Leerwandler selbst beschwören?",a="Ein Dämon kann nicht stellvertretend an einen Hexenmeister gebunden werden. Würden Gakin oder ein Gehilfe das Biest zähmen, würde es nur ihnen gehorchen. Um die Macht und den Schutz eines Leerwandlers zu erlangen, müsst Ihr ihn persönlich in den Kreis ziehen und seinen Willen brechen. Nur indem Ihr ihn selbst überwältigt, könnt Ihr das mystische Band knüpfen, das erforderlich ist, um ihn in Zukunft beschwören und befehligen zu können.",al={"warum muss ich ihn beschwören","warum kann gakin das nicht","warum ich leerwandler"}}},fp="11,168,25.362.0,28.304.0,38.268.0,28.248.0,39.181.0,56.153.0,41.175.0,56.211.0"}
P.entries["quest:169"] = {n="GESUCHT: Gath'Ilzogg",s="Im Rotkammgebirge setzt Magistrat Solomon ein Kopfgeld auf Gath'Ilzogg aus, den Kriegsfürsten hinter der Schwarzfels-Invasion von Steinwacht. Wer die eroberte Burg stürmt und den abgetrennten Kopf des Kommandanten zurückbringt, kann es beanspruchen.",h="Im Rotkammgebirge setzt Magistrat Solomon ein Kopfgeld auf Gath'Ilzogg aus, den Kriegsfürsten hinter der...",kw={"schwarzfels","kopfgeld","gath'ilzogg","seenhain","magistrat solomon","rotkammgebirge","steinwacht","steckbrief"},ang={["class:Warrior"]="Ganz oben in Burg Steinwacht stellt Ihr Euch den kampferprobten Veteranen und der rohen Gewalt des Frontkommandos der Dunklen Horde.",["faction:Alliance"]="Mit Gath'Ilzoggs Tod fällt eine der unmittelbarsten militärischen Bedrohungen an der Ostgrenze des Königreichs weg. Seenhains Bürger gewinnen dringend benötigte Luft zum Atmen.",["race:Human"]="Für Sturmwinds Volk war Burg Steinwacht hart erkämpft. Gath'Ilzogg schlachtete bei ihrem Fall Unschuldige ab und machte dieses Kopfgeld zu einer Sache bitterer Rache."},sec={{t="Der Kriegsfürst von Steinwacht",b="Gath'Ilzogg führt die Raubzüge der Schwarzfelsorcs im gesamten Rotkammgebirge an. Seine Orcs eroberten Burg Steinwacht, einst eine Bastion der Menschen, und machten sie zu einem Stützpunkt für Angriffe auf nahe Siedlungen. Von ihren höchsten Zinnen aus plant er weitere Angriffe auf Seenhain. Dem Rotkammgebirge droht die Abschneidung vom Rest des Königreichs."},{t="Eine Stadt am Abgrund",b="Sturmwinds königliche Armee hat keine Verstärkung an die Grenze geschickt, also handelt Magistrat Solomon auf eigene Faust. Seenhain fehlen die Soldaten, um Burg Steinwacht mit Gewalt zurückzuerobern. Solomon setzt öffentlich ein Kopfgeld auf Gath'Ilzogg aus, in der Hoffnung, die Schwarzfels-Führung zu zerschlagen und die Rückeroberung der Burg für die Krone einzuleiten."}},faq={{q="Wer ist Gath'Ilzogg?",a="Gath'Ilzogg ist ein Orc-Kriegsfürst, der die Schwarzfels-Truppen anführt, die Steinwacht besetzen. Er leitete die Eroberung der Burg und ist für häufige tödliche Überfälle auf Seenhains menschliche Siedler verantwortlich.",al={"gath'ilzogg hintergrundgeschichte","wer ist gathilzogg","schwarzfelsanführer rotkammgebirge"}},{q="Wo ist Gath'Ilzogg zu finden?",a="Gath'Ilzogg hat sich ganz oben in Burg Steinwacht verschanzt, in den östlichen Felshöhen des Rotkammgebirges. Schwarzfels-Champions und Leibwächter bewachen ihn.",al={"gath'ilzogg aufenthaltsort","wo ist gathilzogg","steinwacht boss aufenthaltsort"}},{q="Warum setzt Magistrat Solomon ein Kopfgeld aus, statt Soldaten zu schicken?",a="Seenhains Stadtwache ist überlastet, und Sturmwinds Krone hat keine Truppen zur Entlastung der Region geschickt. Magistrat Solomon verlässt sich auf Söldner und unabhängige Abenteurer, um großen Bedrohungen zu begegnen.",al={"warum ein kopfgeld","wo sind sturmwinds soldaten","hilfe für seenhains wache"}},{q="Was geschieht nach Gath'Ilzoggs Tod?",a="Magistrat Solomon sieht Gath'Ilzoggs Tod als ersten Schritt, um die Orcs zu vertreiben und schließlich Burg Steinwacht für das Königreich Sturmwind zurückzuerobern. Die Schwarzfels-Truppen bleiben in der Region stark.",al={"ist steinwacht zurückerobert","nach gath'ilzogg"}},{q="Warum haben die Schwarzfelsorcs Burg Steinwacht angegriffen?",a="Der Schwarzfelsklan nutzt Burg Steinwacht als befestigten Vorposten hoch im Rotkammgebirge. Von dort aus kontrollieren seine Truppen die Pässe und überfallen menschliche Siedlungen.",al={"warum sind schwarzfelsorcs im rotkammgebirge","warum wurde steinwacht erobert"}},{q="Wer zahlt das Kopfgeld aus, sobald Gath'Ilzogg tot ist?",a="Bringt Gath'Ilzoggs Kopf als Beweis für seine Niederlage zu Magistrat Solomon im Rathaus von Seenhain.",al={"bei wem gathilzogg abgeben","gathilzogg quest abgeben"}}},fx={["1d021e94"]={q="Warum möchte Seenhain, dass Gath'Ilzogg getötet wird?",a="Gath'Ilzogg dient als General, der die Invasion der Dunkeleisenzwerge auf das Rotkammgebirge leitet. Unter seinem Kommando haben die Orcs menschliche Verteidiger abgeschlachtet, Burg Steinwacht erobert und direkte, gewalttätige Überfälle auf die Siedlung Seenhain gestartet. Die Stadtführung weiß, dass der Schwarzfelsklan weiterhin Gräueltaten gegen unschuldige Bürger planen wird, solange er ihre Streitkräfte koordiniert. Ihm ein Ende zu setzen ist entscheidend, um die Belagerung zu brechen und schließlich die Burg zurückzuerobern.",al={"warum gath'ilzogg töten","warum kopfgeld gath'ilzogg","warum will solomon gath'ilzogg tot"}},["69773e29"]={q="Wozu dient Gath'Ilzoggs Kopf?",a="Der Kopf liefert den unwiderlegbaren Beweis, dass der Kriegsfürst des Schwarzfels tatsächlich gefallen ist. Magistrat Solomon benötigt konkrete Beweise für Gath'Ilzoggs Ableben, bevor er das Kopfgeld der Stadt auszahlen und die in Panik geratenen Bürger von Seenhain beruhigen kann, dass der Architekt hinter den Angriffen ausgeschaltet wurde.",al={"zweck von gath'ilzoggs kopf","warum gath'ilzoggs kopf sammeln","was mache ich mit gath'ilzoggs kopf"}}},fp="19,215,25.311.0,26.299.0,19.195.0,31.150.0,72.197.0,41.207.0,50.169.0,47.95.0"}
P.entries["quest:1690"] = {n="Wüstenläufergerechtigkeit",s="In Tanaris halten die Wastewander fast jeden Brunnen besetzt, und Gadgetzans Wasserversorgung ist in Gefahr. Chefingenieur Bilgewhizzle schickt Euch östlich der Stadt, um die Banditen und Diebe der Wastewander ihrer gerechten Strafe zuzuführen.",h="In Tanaris halten die Wastewander fast jeden Brunnen besetzt, und Gadgetzans Wasserversorgung ist in Gefahr.",kw={"bandit","bilgewhizzle","gadgetzan","tanaris","dieb","wastewander","wassergesellschaft","brunnen"},sec={{t="Gerechtigkeit für die Brunnen",b="Ohne Zugang zu den Brunnen, die von den Nomaden der Wastewander besetzt werden, wird Gadgetzans Wasservorrat bald versiegen. Chefingenieur Bilgewhizzle will, dass Ihr östlich der Stadt zehn Banditen und Diebe der Wastewander zur Strecke bringt. Danach sollt Ihr unverzüglich zurückkehren und Bericht erstatten. Er hat eine Vorliebe für Gerechtigkeit nach Goblinart."},{t="Noch lange nicht fertig",b="Bilgewhizzle ist erfreut darüber, wie schnell Ihr gehandelt habt. Die Reihen der Wastewander sind so weit gelichtet, dass die Gesellschaft erwägen kann, ihre Brunnen zurückzugewinnen. Doch Bilgewhizzle ist mit den üblen Nomaden noch lange nicht fertig, und er hat noch mehr im Sinn."}},faq={{q="Wer ist Chefingenieur Bilgewhizzle?",a="Chefingenieur Bilgewhizzle arbeitet für die Gadgetzan Water Company in Gadgetzan.",al={"bilgewhizzle","wer vergibt wüstenläufergerechtigkeit","gadgetzan water company ingenieur"}},{q="Warum geht die Gadgetzan Water Company gegen die Wastewander vor?",a="Die Nomaden der Wastewander halten fast jeden Wasserbrunnen in der Wüste besetzt. Ohne Zugang zu ihnen wird Gadgetzans Wasservorrat versiegen.",al={"warum banditen der wastewander töten","wüstenläufergerechtigkeit grund","warum nomaden in tanaris angreifen"}},{q="Wo befinden sich die Banditen und Diebe der Wastewander?",a="Die Banditen und Diebe der Wastewander befinden sich in der Wüste östlich von Gadgetzan.",al={"wo banditen der wastewander finden","banditen der wastewander fundort","diebe tanaris fundort"}}},fp="19,200,21.279.0,13.219.1,35.79.0,64.129.0,54.72.0"}
P.entries["quest:1691"] = {n="Noch mehr Wüstenläufergerechtigkeit",s="Östlich und südöstlich von Gadgetzan nimmt Bilgewhizzle nun Wastewander-Schurken, -Assassinen und -Schattenmagier ins Visier. Wenn weniger Nomaden übrig sind, kann die Gesellschaft die Wasserbrunnen leichter zurückerobern.",h="Östlich und südöstlich von Gadgetzan nimmt Bilgewhizzle nun Wastewander-Schurken, -Assassinen und...",kw={"assassinen","bilgewhizzle","gadgetzan","schattenmagier","tanaris","wastewander","wassergesellschaft"},sec={{t="Die stärkeren Reihen",b="Chefingenieur Bilgewhizzle sagt, Ihr habt gute Arbeit geleistet, doch die Gesellschaft braucht weniger Nomaden, bevor sie die Brunnen zurückerobern kann. Nun steht Ihr ihren Schurken, Assassinen und Schattenmagiern östlich und südöstlich von Gadgetzan gegenüber. Bilgewhizzle nennt sie eine üble Brut. Er besteht darauf, dass die Brunnen rechtmäßig der Gesellschaft gehören."},{t="Den Kampf zu ihnen tragen",b="Da die Zahl der Nomaden geschrumpft ist, kann die Gesellschaft den Kampf zu ihnen tragen. Bilgewhizzle verweist Euch an Leitungshahnmaschinist Luglunket in Gadgetzan. Luglunket bietet ein Kopfgeld für alle Wastewander-Wasserbeutel, die Ihr beim Vorgehen gegen die Nomaden gesammelt habt."}},faq={{q="Wer bittet darum?",a="Chefingenieur Bilgewhizzle von der Gadgetzan Water Company bittet Euch in Gadgetzan darum.",al={"wer vergibt noch mehr wüstenläufergerechtigkeit","questgeber"}},{q="Warum will die Gadgetzan Water Company diese Nomaden loswerden?",a="Die Gesellschaft will die Wasserbrunnen zurückerobern, und weniger Nomaden werden das erleichtern.",al={"warum wastewander töten","bilgewhizzles beweggrund"}},{q="Wo sind die gesuchten Nomaden zu finden?",a="Die gesuchten Nomaden befinden sich östlich und südöstlich von Gadgetzan.",al={"wo sind wastewander-schurken","wo schattenmagier finden"}},{q="Was kommt vor diesem Schritt?",a="Dieser Schritt folgt auf Wastewander Justice.",al={"voraussetzung","vorherige quest"}}},fp="24,183,18.300.0,24.246.1,18.81.0,63.85.0,39.56.0,28.33.0"}
P.entries["quest:1692"] = {n="Schmied Mathiel",s="In Darnassus ist heiliges Elunit-Erz auf dem Weg zur Schmiede. Nachdem Ihr es aus dem verwunschenen Schiffswrack vor Auberdine geborgen habt, schickt Elanaria Euch zu Mathiel, damit er daraus eine Waffe für die Kaldorei schmiedet.",h="In Darnassus ist heiliges Elunit-Erz auf dem Weg zur Schmiede.",kw={"die terrasse der krieger","darnassus","elanaria","elunit","mathiel","schmied","krieger"},ang={["class:Warrior"]="Als junger Krieger der Kaldorei vollzieht Ihr mit der Lieferung von Elunit an Mathiel den Übergang von Übungsklingen zu einer maßgefertigten, von der Mondgöttin gesegneten Waffe.",["profession:Blacksmithing"]="Mathiels Ehrfurcht vor Elunit zeigt, wie die Schmiede der Kaldorei neben Hitze und Hammer auch heiligen Segen in ihr Handwerk einbringen.",["race:NightElf"]="Als Nachtelf verbindet die Arbeit mit Elunit das Handwerk Eures Volkes mit der Hingabe an Elune, wo kriegerische Stärke und Glaube zusammentreffen."},sec={{t="Eine heilige Lieferung",b="Elanaria schickt Euch mit dem Elunit-Erz, das Ihr aus dem verwunschenen Schiffswrack vor Auberdine geborgen habt, über die Terrasse der Krieger in Darnassus. Die Kriegerausbilderin verpackt das Erz in einem stabilen Behälter und verweist Euch an Mathiel, einen der besten Schmiede der Hauptstadt. Er kann das Metall zu einer Waffe formen, die Eurer Berufung würdig ist."},{t="Der Segen des Elunits",b="Mathiel betrachtet das Schmieden als einen Akt der Hingabe. Elunit trägt den heiligen Segen von Elune, der Mondgöttin, und er empfindet es als Ehre, den Behälter entgegenzunehmen. Er wird das heilige Metall zu Waffen formen, um die jungen Zweige von Teldrassil zu verteidigen."}},faq={{q="Wer ist Schmied Mathiel?",a="Mathiel ist ein geschickter Nachtelfenschmied, der auf der Terrasse der Krieger in Darnassus arbeitet. Er fertigt besondere Waffen und nimmt Auftragsarbeiten für die Verteidiger der Stadt an.",al={"wer ist mathiel","schmied mathiel","wo ist mathiel"}},{q="Was ist das Besondere an Elunit-Erz?",a="Nachtelfen verehren Elunit als seltenes Metall, das von Elune gesegnet ist. Mathiel betrachtet es als große Ehre, daraus mächtige Waffen zu formen.",al={"was ist elunit","ist elunit magisch","elunit hintergrundgeschichte"}},{q="Wer schickt Euch zu Mathiel?",a="Elanaria, die Kriegerausbilderin auf der Terrasse der Krieger in Darnassus, verpackt Euer geborgenes Erz und schickt Euch über die Terrasse zu Mathiel.",al={"wer vergibt die quest schmied mathiel","questgeber schmied mathiel"}},{q="Ist diese Quest nur für Krieger verfügbar?",a="Ja. Sie gehört zur Klassengeschichte der Krieger auf Stufe zehn und soll junge Krieger mit ihrer ersten spezialisierten Waffe ausstatten.",al={"nur für krieger","können andere klassen schmied mathiel machen"}},{q="Wo in Darnassus ist Mathiel zu finden?",a="Mathiel arbeitet auf der Terrasse der Krieger in Darnassus, von Elanaria aus ein kurzes Stück nach Süden auf der anderen Seite des Bauwerks.",al={"mathiel standort","mathiel finden"}},{q="Was geschieht, nachdem Ihr Mathiel das Erz gebracht habt?",a="Nachdem Ihr das Erz abgeliefert habt, beginnt Mathiel, es zu formen, und lässt Euch wählen, welche Elunit-Waffe zu Eurem Kampfstil passt.",al={"was kommt nach schmied mathiel","nächste quest nach schmied mathiel"}}},fx={["4e03f025"]={q="Warum schickt Elanaria Euch zu Smith Mathiel?",a="Elanaria ist Eure Kriegerausbilderin in Darnassus, und ihre Pflicht ist es, Eure Ausbildung zu überwachen und Euch für die kommenden Herausforderungen zu rüsten. Nachdem Ihr das heilige Elunit-Erz aus der Dunkelküste gesammelt hattet, verpackte sie es sicher, damit Smith Mathiel, ein in heiliger Metallverarbeitung geschickter Handwerker, es zu einer richtigen Waffe schmieden konnte, die eines Elfenkriegers würdig ist.",al={"elanaria beweggrund","warum zu mathiel schicken","warum elanaria mathiel"}}},fp="13,197,17.308.0,23.226.0,21.159.0,34.123.0,25.133.0,41.120.0,40.94.0,50.127.0"}
P.entries["quest:1693"] = {n="Waffen aus Elunit",s="In Darnassus vollendet Waffen aus Elunit den Übergangsritus eines jungen Kriegers. Ihr bringt von Elune gesegnetes Erz zu Mathiel, der daraus Waffen für einen Verteidiger Kalimdors schmiedet.",h="In Darnassus vollendet Waffen aus Elunit den Übergangsritus eines jungen Kriegers.",kw={"darnassus","elune","elunit","kaldorei","mathiel","teldrassil","krieger","waffenschmied"},ang={["class:Warrior"]="Als junger Krieger der Kaldorei vollzieht Ihr einen frühen Übergangsritus im Kriegsdienst und erhaltet verlässliche, von Elune gesegnete Waffen.",["profession:Blacksmithing"]="Als Schmied seht Ihr, wie Mathiel gewöhnliche Metallarbeit mit der Sorgfalt verbindet, die das Formen von heiligem Elunit verlangt.",["race:NightElf"]="Als Nachtelf seht Ihr, wie sich die Verehrung der Mondgöttin mit dem praktischen Handwerk des Krieges und der Verteidigung verbindet."},sec={{t="Eine heilige Schmiede",b="Nachtelfenkrieger verteidigen Teldrassil und das Volk der Kaldorei. Vielversprechende junge Krieger sammeln Elunit, ein von der Mondgöttin gesegnetes Mineral, um sich mit mehr als gewöhnlichem Stahl zu wappnen. Sein Erz braucht einen Schmied, der die Metallverarbeitung beherrscht und Elunes Gabe achtet."},{t="Mathiels Handwerk",b="Mathiel arbeitet in Darnassus und formt gesegnetes Elunit zu Kriegswaffen. Er betrachtet die Arbeit als Ehre, nicht als alltägliche Metallverarbeitung. Bringt ihm das Erz, und er schmiedet Waffen, die zu Eurem Stil passen. Für Eure Dienste gibt er Euch Waffen, die von Eurer Göttin gesegnet wurden."}},faq={{q="Welchen Zweck hat diese Quest?",a="Der Übergangsritus eines jungen Kriegers in Darnassus endet, wenn Ihr Smith Mathiel Eluniterz bringt. Er schmiedet von Elune gesegnete Waffen, die Euch auf Eurer Reise durch Kalimdor helfen.",al={"waffen aus elunit quest","warum diese quest machen","krieger stufe zehn darnassus"}},{q="Wer ist Mathiel?",a="Mathiel ist ein geschickter Nachtelfenschmied, der in Darnassus lebt. Er kann aus Elunit ausgewogene Waffen für die Verteidiger der Stadt schmieden.",al={"smith mathiel","wer ist mathiel","darnassus schmied"}},{q="Was ist Elunit?",a="Elunit ist ein seltenes Mineral, das den Nachtelfen heilig ist und dem nachgesagt wird, Elunes Leuchten und Gunst zu bergen. Es zu Waffen zu formen, ist für einen Schmied eine feierliche Ehre.",al={"was ist eluniterz","elunit hintergrundgeschichte"}},{q="Wer kann diese Quest annehmen?",a="Krieger der Allianz, die nahe Darnassus ausgebildet werden, können diese Quest annehmen, nachdem sie Elunit für Smith Mathiel gefunden und gesammelt haben.",al={"wer erhält waffen aus elunit","ist das nur für krieger"}},{q="Wo spielt diese Quest?",a="Ihr bringt das Erz zu Smith Mathiel in Darnassus, der Hauptstadt der Nachtelfen hoch in den Ästen Teldrassils.",al={"waffen aus elunit ort","wo ist mathiel"}},{q="Warum dankt Mathiel dem Abenteurer?",a="Mathiel dankt Euch, weil es sowohl eine heilige Ehre als auch eine persönliche Freude ist, Elunit zu formen. Nur wenige Schmiede dürfen Erz verarbeiten, das mit Elune verbunden ist, daher ist Eure Lieferung ein Segen für ihn.",al={"warum fühlt sich mathiel geehrt","mathiel dialog"}}},fx={cb47846f={q="Warum bittet Mathiel Euch darum, anstatt einen Wächter zu beauftragen?",a="Dieser Auftrag ist ein Ritus des Übergangs für einen vielversprechenden jungen Krieger und keine offizielle bürgerliche Pflicht. Wachposten und Tempelwachen sind darauf vereidigt, Darnassus und Teldrassil vor aktiven Bedrohungen zu verteidigen, wodurch sie keine Zeit haben, seltene Schmiedematerialien für persönliche Ausrüstung zu sammeln. Indem Ihr die Arbeit auf Euch nehmt, das Erz selbst zu sammeln, beweist Ihr Eure Hingabe und Disziplin und verdient eine Waffe, die speziell auf Euren Kampfweg zugeschnitten ist.",al={"warum schickt sie mich","warum ich mathiel","warum krieger"}}},fp="18,180,14.255.0,15.250.0,34.168.0,15.126.0,16.156.0,29.115.0,33.104.0,38.185.0"}
P.entries["quest:1698"] = {n="Yorus Gerstenbräu",s="Im Gasthaus von Seenhain erwartet Yorus Gerstenbräu kühne Krieger der Allianz mit einer exzentrischen Herausforderung. Ausbilder in den Hauptstädten der Allianz schicken erfahrene Kämpfer aus Sturmwind ins Grenzland des Rotkammgebirges, um den Zwerg zu treffen und sich seiner Waffenprobe zu stellen.",h="Im Gasthaus von Seenhain erwartet Yorus Gerstenbräu kühne Krieger der Allianz mit einer exzentrischen...",kw={"kelv sternhammer","seenhain","gasthaus von seenhain","rotkammgebirge","rethban","sturmwind","krieger","wu shen","yorus gerstenbräu"},ang={["class:Warrior"]="Als Krieger der Allianz durchlauft Ihr einen Übergangsritus von einführenden Übungen zu gefährlichen Prüfungen im Grenzland des Rotkammgebirges.",["faction:Alliance"]="Als Rekrut der Allianz werdet Ihr womöglich nach Seenhain geschickt, einer verwundbaren Siedlung, die von Gnollen und Schwarzfelsorcs bedrängt wird."},sec={{t="Ein Ruf an die Starken",b="In den Hauptstädten der Allianz beobachten Kriegerausbilder, wie Kämpfer ihren ersten Übungen entwachsen. Wenn ein Lehrling um seine zwanzigste Saison herum sein Können beweist, geben Kelv Sternhammer, Wu Shen und Darnath Bladesinger die Kunde von Yorus Gerstenbräu weiter. Der Zwerg bietet keinen gewöhnlichen Militärbefehl an. Stattdessen hat er eine offene Wette und eine Waffenprobe für jeden Krieger der Allianz ausgerufen, der kühn genug ist, sich ihr zu stellen."},{t="Warten in Seenhain",b="Yorus Gerstenbräu wartet in der Taverne von Seenhain, an vorderster Front im Kampf des Rotkammgebirges gegen vordringende Gnolle und Schwarzfelsorcs. Wer ihn findet, trifft einen prahlerischen Zwerg mit einem kräftigen Trunk in der Hand, bereit, jeden Herausforderer zu beurteilen, der wahren Kampfgeist für sich beansprucht. Für Krieger, die sich jenseits der sicheren Pflasterstraßen der Hauptstadt beweisen wollen, öffnet seine Prüfung den Weg zu den härteren Kämpfen des Grenzlands."}},faq={{q="Wer ist Yorus Gerstenbräu?",a="Yorus Gerstenbräu gehört dem berühmten Brauerclan Gerstenbräu an und hat eine offene kämpferische Herausforderung an die Krieger der Allianz gerichtet. Er wartet im Gasthaus von Seenhain und prüft Kämpfer, die sich für das brutale Grenzland des Rotkammgebirges bereit halten.",al={"yorus gerstenbräu","wer ist gerstenbräu","zwerg im gasthaus von seenhain"}},{q="Warum schicken die Ausbilder Krieger ins Rotkammgebirge?",a="Sobald ein Krieger in Sturmwind genügend Fertigkeiten erworben hat, schicken ihn die örtlichen Waffenmeister in echte Kämpfe, bei denen viel auf dem Spiel steht. Yorus Gerstenbräus Prüfung führt die Lehrlinge über die Stadtmauern hinaus, wo sie ihre Ausdauer gegen wirkliche Bedrohungen der Wildnis beweisen.",al={"warum seenhain","kriegerausbilder quest rotkammgebirge","warum zu yorus"}},{q="Wo kann ich Yorus Gerstenbräu finden?",a="Yorus Gerstenbräu wartet im Gasthaus von Seenhain, in der Stadt Seenhain im Rotkammgebirge, gleich östlich des Waldes von Elwynn.",al={"yorus gerstenbräu standort","wo ist yorus","gerstenbräu finden"}},{q="Was geschieht nach dem Gespräch mit Yorus?",a="Das Gespräch mit Yorus eröffnet seine Waffenprobe, die Rethban Gauntlet. Sie ist eine gefährliche Prüfung gegen die wilden Bestien und Gnolle in den umliegenden Hügeln.",al={"nach yorus","gerstenbräus prüfung","nächste quest"}},{q="Wer bietet die Quest an, ihn zu finden?",a="Kriegerausbilder der Allianz, darunter Kelv Sternhammer, Wu Shen und Darnath Bladesinger, schicken Krieger auf die Suche nach Yorus, sobald sie grundlegendes Können bewiesen haben.",al={"wer vergibt die quest","questgeber","ausbilder für yorus"}},{q="Steht diese Prüfung auch anderen Klassen als Kriegern offen?",a="Nein. Yorus Gerstenbräu bietet diese Herausforderung nur Kriegern an, die sich auf körperliche Ausdauer und Waffen verlassen.",al={"können paladine das machen","ist das nur für krieger","klassenbeschränkungen"}}},fx={f43b4090={q="Warum schicken die Ausbilder Euch zu Yorus Barleybrew?",a="Eure Ausbilder erkennen, dass Ihr den grundlegenden Übungen entwachsen seid und Prüfungen benötigt, die Euren Schneid im Feld testen. Yorus Barleybrew hat eine offene Herausforderung speziell an fähige Krieger der Allianz gerichtet und verspricht jedem, der stark genug ist, sie zu bestehen, eine große Belohnung. Anstatt Euch in den Ausbildungshallen der Hauptstadt zu schonen, schicken Euch Eure Mentoren ins Rotkammgebirge, um Eure Fähigkeiten in einer echten Prüfung unter Beweis zu stellen.",al={"warum zu yorus schicken","warum ich yorus barleybrew","warum kriegerprüfung rotkamm"}}},fp="16,246,20.391.0,20.414.0,24.247.0,46.254.0,34.128.0,39.153.0,33.156.0,50.101.0"}
P.entries["quest:1699"] = {n="Der Rethbanspießrutenlauf",s="In Seenhain schickt Yorus Barleybrew Läufer nach Norden zu den Rethbanhöhlen und wieder zurück. Sie trinken den feurigen Gerstenbräusenger seiner Familie und eilen dann los, um innerhalb einer Stunde zurückzukehren.",h="In Seenhain schickt Yorus Barleybrew Läufer nach Norden zu den Rethbanhöhlen und wieder zurück.",kw={"gerstenbräusenger","gnolle","seenhain","rotkammgebirge","rethbanhöhlen","rethbanspießrutenlauf","lauf auf zeit","yorus barleybrew"},ang={["faction:Alliance"]="Als Reisender der Allianz könnt Ihr Seenhain gegen die Bedrohung durch die Gnolle helfen, indem Ihr den Lauf wagt und die feindlichen Patrouillen nahe den nördlichen Höhlen dezimiert.",["race:Dwarf"]="Als Zwerg ist Euch Yorus' ausgelassene Vorstellung von Vergnügen vielleicht vertraut: kräftigen Schnaps aus Familienherstellung mit einem gefährlichen Sprint durchs Gebirge zu verbinden."},sec={{t="Eine zwergische Mutprobe",b="Im Gasthaus von Seenhain ist viel düsteres Gerede über Gnollüberfälle und vermisste Stadtwachen zu hören. Yorus Barleybrew bietet Reisenden eine andere Zerstreuung: eine Prüfung ihrer Schnelligkeit, ihres Mutes und ihrer Ausdauer. Bevor sie zu Fuß zu den nördlichen Ausläufern aufbrechen, trinken sie einen Schluck vom Gerstenbräusenger seiner Familie."},{t="Lauf durch wilde Hügel",b="Gnolle aus dem Rotkammgebirge durchstreifen die Hügel zwischen Seenhain und den Rethbanhöhlen. Läufer müssen sich durch ihre Rudel kämpfen oder vorbeischleichen, die erste Gabelung in den dunklen Tunneln erreichen und innerhalb einer Stunde zu Yorus zurückeilen. Das feurige Getränk erschwert den Lauf, und die Herausforderer torkeln durch die Hügel."}},faq={{q="Wer fordert zum Rethbanspießrutenlauf heraus?",a="Yorus Barleybrew, ein Zwergenbrauer, der sich in Seenhain aufhält, fordert Reisende zum Spießrutenlauf heraus, um ihre Standhaftigkeit und sein Gebräu zu erproben.",al={"wer vergibt den rethbanspießrutenlauf","yorus barleybrew quest","wer startet den spießrutenlauf"}},{q="Was macht diese Herausforderung besonders schwierig?",a="Läufer treffen in den Ausläufern des Rotkammgebirges auf Gnollrudel und haben nur eine Stunde Zeit. Zuerst trinken sie Gerstenbräusenger, der sie schwer berauscht und ihnen Mühe bereitet, das Gleichgewicht zu halten.",al={"warum ist der rethbanspießrutenlauf schwer","gerstenbräusenger wirkung"}},{q="Wo liegen die Rethbanhöhlen?",a="Die Rethbanhöhlen liegen in den nördlichen Ausläufern des Rotkammgebirges, nordwestlich von Seenhain. Der Weg führt nach Norden an den örtlichen Gehöften vorbei zu zerklüfteten Felsen, in denen Gnollrudel hausen.",al={"rethbanhöhlen lage","wo ist rethban","wie gelangt man zu den rethbanhöhlen"}},{q="Wie weit muss ein Läufer in die Höhlen vordringen?",a="Herausforderer müssen nur die erste Gabelung in den Höhlen erreichen, dann umkehren und nach Seenhain zurückrennen.",al={"rethbanhöhlen ziel","wie weit in rethban hinein"}},{q="Wer bewohnt die Hügel und Höhlen entlang der Strecke?",a="Feindselige Gnolle aus dem Rotkammgebirge haben das Gebiet entlang der Strecke und die Höhlen überrannt. Läufer müssen schleichen oder rasch kämpfen, um den Weg zu überleben.",al={"welche feinde in rethban","was ist in den rethbanhöhlen"}},{q="Wohin führt diese Herausforderung als Nächstes?",a="Wenn Ihr den Lauf überlebt, beweist Ihr Yorus Barleybrew Eure Ausdauer und eröffnet Euch weitere Aufgaben in der Region, etwa den Schildschmied Furen Langbart in Sturmwind aufzusuchen.",al={"rethbanspießrutenlauf folgequest","welche quest folgt auf den rethbanspießrutenlauf"}}},fx={["26a182c4"]={q="Warum möchte Yorus Barleybrew, dass dies getan wird?",a="Yorus Barleybrew versucht nicht, eine Krise zu lösen oder Seenhain mit dieser Prüfung zu retten. Stattdessen konzipiert er den The Rethban Gauntlet als eine ausgelassene Prüfung von Nervenstärke, Ausdauer und Alkoholtoleranz. Indem er waghalsige Abenteurer tief in das Gnollgebiet schickt, während sie von seinem feurigen Barleybrew Scalder schwer berauscht sind, sucht Yorus pure Unterhaltung und den Nervenkitzel, jemanden dabei zu beobachten, der mutig genug ist, sowohl die wilden Gnolle des Rotkammgebirges als auch den heftigen Kick seines Gebräus zu bezwingen.",al={"warum die prüfung laufen","yorus barleybrew beweggrund","warum fordert yorus heraus"}}},fp="20,169,14.286.0,22.286.0,32.134.0,49.187.0,38.173.0,40.100.0,51.132.0,36.174.0"}
P.entries["quest:17"] = {n="Uldaman Reagent Run",s="Ghak Healtouch bittet Euch, magentafarbene Pilzkappen aus Uldaman für seine alchemistischen Studien zu sammeln. Als Gegenleistung will er Euch einen greater mender's potion brauen.",h="Ghak Healtouch bittet Euch, magentafarbene Pilzkappen aus Uldaman für seine alchemistischen Studien zu...",kw={"alchemie","ghak healtouch","greater mender's potion","magentafarbene kappen","magentafarbene pilzkappen","giftige sporen","thelsamar","uldaman","uldaman reagent run"},sec={{t="Ein neuer Pilz",b="Ghak Healtouch in Thelsamar hat von magentafarbenen Pilzkappen gehört, die tief im Ausgrabungsgebiet von Uldaman in Gruppen wachsen. Er möchte ihren möglichen Einsatz in der Alchemie untersuchen und bittet Euch, ihm ein Dutzend Kappen zu bringen. Werden die Gruppen gestört, könnten sie giftige Sporen freisetzen."}},faq={{q="Wer möchte die magentafarbenen Pilzkappen?",a="Ghak Healtouch in Thelsamar bittet Euch, ihm ein Dutzend magentafarbene Pilzkappen für alchemistische Studien zu bringen.",al={"wer bat um die kappen","ghaks pilzbitte"}},{q="Wo wachsen magentafarbene Pilzkappen?",a="Die bekannten Gruppen wachsen tief im Ausgrabungsgebiet von Uldaman. Ghak hat gehört, dass sie auch anderswo wachsen könnten, doch Uldaman ist der einzige Ort, den er kennt.",al={"wo sind die pilzkappen","fundort der magentafarbenen kappen"}},{q="Warum möchte Ghak die Kappen?",a="Ghak möchte die magentafarbenen Pilzkappen auf einen möglichen Einsatz in der Alchemie untersuchen.",al={"wofür sind die kappen","ghaks alchemie"}},{q="Welche Gefahr geht von den Gruppen aus?",a="Werden die Gruppen gestört, könnten sie giftige Sporen ausstoßen.",al={"pilzsporen","sind die kappen giftig"}},{q="Was bietet Ghak als Gegenleistung?",a="Ghak sagt, er werde Euch eine Portion seines greater mender's potion brauen.",al={"was bekomme ich von ghak","ghaks trank"}}},fp="19,150,12.255.0,34.99.0,34.133.0,28.74.0,33.52.0,31.66.0"}
P.entries["quest:170"] = {n="Eine neue Bedrohung",s="Balir Frosthammer ruft um Hilfe, während Felskiefertroggs das Coldridgetal überrennen und seine Siedlungen und Lager bedrohen.",h="Balir Frosthammer ruft um Hilfe, während Felskiefertroggs das Coldridgetal überrennen und seine Siedlungen...",kw={"eine neue bedrohung","ambossar","balir frosthammer","burly rockjaw","das coldridgetal","dun morogh","felskiefertrogg"},ang={["faction:Alliance"]="Als Rekrut der Allianz helft Ihr, die Bedrohung aus der Tiefe im Coldridgetal einzudämmen. So bleiben Eisenschmiedes Ausbildungsgelände nutzbar und das südliche Gebirgstor gesichert.",["race:Dwarf"]="Als junger Bronzebeard-Zwerg, der Ambossar verlässt, habt Ihr die persönliche Pflicht, die Troggs zurückzudrängen und die heiligen Stätten und Tunnel von Dun Morogh zu schützen."},sec={{t="Einbruch ins Coldridgetal",b="Felskiefertroggs graben sich in wachsender Zahl von unten herauf. Ambossar erreichen Berichte über Troggs, die den zugefrorenen See und die nahen Ausläufer überschwemmen. Sie stören Patrouillen und unterbrechen Versorgungswege durch den Talpass. Jungen zwergischen Kriegern und Gebirgsjägern dient dieses Tal seit Langem als Ausbildungsstätte. Nun erreicht die Bedrohung auch diesen Ort."},{t="Ein überranntes Lager",b="Ein koordinierter Troggangriff hat ein Zwergenlager westlich des Tals überrannt. Die Gebirgsjäger zogen sich zurück und gaben ihre Posten auf. Eisenschmiede kann keine vollständigen Schlachtregimenter entbehren, deshalb ruft Balir Frosthammer frisch rekrutierte Abenteurer dazu auf, sich durch die Reihen der Felskiefer zu kämpfen. Die Hügel müssen gesichert werden, bevor die Kreaturen Ambossar erreichen."}},faq={{q="Wer ist Balir Frosthammer?",a="Balir Frosthammer ist ein erfahrener zwergischer Gebirgsjäger, der außerhalb von Ambossar im Coldridgetal stationiert ist. Er organisiert die Verteidigung gegen wilde Tiere und Troggs, die die örtlichen Rekruten bedrohen.",al={"balir frosthammer","wer vergibt eine neue bedrohung","frosthammer ambossar"}},{q="Warum sind plötzlich Troggs im Coldridgetal?",a="Felskiefertroggs graben sich überall in Dun Morogh aus tiefen Erdspalten nach oben. Das Coldridgetal gehört zu den ersten besiedelten Tälern, die getroffen werden, als die Kreaturen durchbrechen und Lager an der Oberfläche überrennen.",al={"woher kamen die troggs","warum greifen troggs an","trogginvasion"}},{q="Welches Lager haben die Troggs überrannt?",a="Troggs überwältigten ein Lager zwergischer Gebirgsjäger im Westen des Coldridgetals. Die Überlebenden zogen sich in Richtung Ambossar zurück.",al={"überranntes lager","westliches lager","wo griffen die troggs an"}},{q="Welche Art von Troggs bedroht das Tal?",a="Die Angreifer gehören zum Stamm der Felskiefer. Gewöhnliche Felskiefertroggs und größere, kräftigere Burly Rockjaw Troggs führen den Vormarsch rund um den zugefrorenen See und die Ausläufer an.",al={"felskiefertroggs","welche troggs","burly rockjaw troggs"}},{q="Weiß König Magni von dem Troggproblem?",a="Die örtlichen Wachen hoffen, dass König Magni Bronzebart und der Eisenschmiede Senate eine umfassendere Reaktion vorbereiten. Vorerst müssen Grenzposten wie das Coldridgetal die Anstürme allein abwehren.",al={"weiß magni davon","eisenschmiedes reaktion auf troggs","ironforge senate troggs"}},{q="Was geschieht, nachdem diese Troggs dezimiert wurden?",a="Die Troggs zu dezimieren hilft, die unmittelbare Umgebung von Ambossar zu sichern. Balir und andere zwergische Offiziere organisieren weiterhin Gegenangriffe, um das westliche Lager zurückzuerobern und die Troggs unter die Erde zu treiben.",al={"folgequest","nach eine neue bedrohung","coldridge troggquestreihe"}}},fx={["54af52f4"]={q="Warum möchte Balir Frosthammer, dass die Troggs dezimiert werden?",a="Das Coldridgetal steht unter unmittelbarer Belagerung. Die Troggs haben nicht nur die südlichen Hügel und den gefrorenen See verseucht, sondern erst vor wenigen Nächten das Zwergenlager im Westen gewaltsam überrannt. Balir muss ihre Zahl verringern, bevor die wilden Kreaturen tiefer in das Tal vordringen und Ambossar vollständig überwältigen.",al={"warum troggs töten","balir frosthammer beweggrund","warum braucht balir tote troggs"}},["3d273126"]={q="Warum benötigt Balir Frosthammer Eure Hilfe statt die der örtlichen Wachen?",a="Die Verteidiger in Ambossar sind gefährlich unterbesetzt. Der kürzliche Überraschungsangriff auf ihr westliches Lager hat ihre Streitkräfte zerstreut und die Garnison dünn aufgestellt, während sie versuchten, den Umkreis der Siedlung zu halten. Da keine überschüssigen Soldaten für einen offensiven Gegenangriff abkömmlich sind, muss Balir jeden fähigen Abenteurer rekrutieren, der eintrifft.",al={"warum ich balir","warum keine wachen nutzen","warum braucht balir mich"}}},fp="12,120,26.317.0,14.325.0,25.182.0,44.188.0,36.130.0,47.163.0,41.176.0,40.198.0"}
P.entries["quest:1700"] = {n="Grimand Elmore",s="In Sturmwind erhält Grimand Elmore die Fachnotizen von Furen Langbart. Ihr kurzer Austausch übermittelt komplexe Erkenntnisse zwischen zwei eigensinnigen Waffenschmieden, die in derselben Stadt leben.",h="In Sturmwind erhält Grimand Elmore die Fachnotizen von Furen Langbart.",kw={"schmiedekunst","der zwergendistrikt","fire hardened mail","furen langbart","furens notizen","grimand elmore","sturmwind"},ang={["class:Warrior"]="Als Krieger geht Ihr von Eurer eigenen Rüstung zu Kriegswaffen über, die mithilfe derselben elementaren Experimente geschmiedet werden.",["profession:Blacksmithing"]="Als Schmied erkennt Ihr im Austausch zwischen Furen und Grimand die erbitterte Rivalität und das Teilen von Berufsgeheimnissen, die unter Meistern der Metallverarbeitung üblich sind.",["race:Dwarf"]="Als Zwerg hört Ihr in Grimands und Furens stolzen Sticheleien die Traditionen von Wettbewerb und Zusammenarbeit heraus, die Khaz Modans Schmiedekultur prägen."},sec={{t="Eine Nachricht durch den Bezirk",b="Furen Langbart schmiedete die spezialisierte Fire Hardened Mail und entdeckte dabei komplexe Wärmebehandlungstechniken und elementare Prinzipien. Er hält seine Erkenntnisse auf Pergament fest und bittet Euch dann, sie direkt Grimand Elmore zu überbringen, einem erfahrenen Handwerker im nahegelegenen Waffenladen."},{t="Berufsstolz und Neugier",b="Grimand Elmore reagiert ungehalten auf das Manuskript. Er beharrt darauf, Furen alles beigebracht zu haben, was der jüngere Zwerg weiß, und der Gedanke, sein ehemaliger Schüler könne ihn etwas lehren, kränkt seinen Stolz. Doch Grimand kann nicht widerstehen, die Notizen zu lesen. Bald entdeckt er eine faszinierende Idee und brennt darauf, sie selbst zu erproben."}},faq={{q="Wer ist Grimand Elmore?",a="Grimand Elmore ist ein angesehener Waffenschmied mit einem Laden im Zwergendistrikt von Sturmwind. Er hat örtlichen Schmieden, darunter Furen Langbart, handwerkliche Fertigkeiten beigebracht und ist sehr stolz auf seine Arbeit.",al={"grimand elmore","wer ist grimand","elmore sturmwind"}},{q="Warum schickt Furen Grimand Notizen?",a="Furen entdeckte bei der Herstellung der Fire Hardened Mail neue Techniken und hielt seine Methoden in Fachnotizen fest. Er teilt seine Erkenntnisse mit Grimand, auch wenn das hitzige Gemüt und der sture Stolz des älteren Zwergs ihn gegen neue Lehren aufbringen könnten.",al={"warum notizen schicken","furens notizen","furen an grimand"}},{q="Wo ist Grimand Elmore zu finden?",a="Grimand Elmore arbeitet in einem Waffenladen im Zwergendistrikt von Sturmwind, nur einen kurzen Fußweg von Furen Langbarts Schmiede entfernt.",al={"wo ist grimand","grimands standort","grimand elmores laden"}},{q="Wie reagiert Grimand auf die Notizen?",a="Grimand reagiert zunächst ungehalten und beharrt darauf, Furen alles beigebracht zu haben, was der jüngere Zwerg weiß. Dann erwacht die Neugier des Meisterschmieds, als er eine faszinierende Technik entdeckt, die er erproben möchte.",al={"grimands reaktion","ist grimand wütend"}},{q="Was geschieht, nachdem Grimand die Notizen gelesen hat?",a="Furens Arbeit zum Härten von Metall im Feuer fasziniert Grimand und spornt ihn zu einem ehrgeizigen Handwerksprojekt an. Weitere Aufgaben verlangen seltene Bestandteile mit elementarer Hitze.",al={"wie weiter bei grimand","nach grimand elmores quest"}},{q="Warum warnt Furen davor, sich bei der Übergabe der Notizen zu ducken?",a="Furen kennt Grimands hitziges Gemüt und seinen Stolz aus eigener Erfahrung. Er rechnet damit, dass Grimand beim Gedanken, ein Lehrling könne dem Meister eine neue Technik beibringen, einen Wutanfall bekommt oder einen Gegenstand wirft.",al={"warum ducken","furens warnung zum ducken"}}},fx={["7d98159c"]={q="Warum schickt Furen Euch, anstatt selbst zu Grimand zu gehen?",a="Furen kennt das reizbare Temperament von Grimand Elmore nur allzu gut. Grimand behauptet, Furen alles beigebracht zu haben, was er weiß, und wenn sein ehemaliger Schüler in seinem Laden auftauchen würde, um ihn über neue Schmiedetechniken zu belehren, würde dies einen feurigen Streit entfachen. Indem er Euch die Notizen überbringen lässt, vermeidet Furen eine direkte Konfrontation und lässt seinen sturen Mentor seinen Stolz im Privaten herunterschlucken.",al={"warum schickt sie mich grimand elmore","warum liefert furen die notizen nicht selbst","warum braucht furen mich"}}},fp="14,181,29.272.0,32.288.0,22.197.0,37.260.0,34.118.0,36.186.0,43.158.1,56.181.0"}
P.entries["quest:1701"] = {n="Feuergehärteter Panzer",s="In Sturmwind bietet Furen Langbart einem Krieger der Allianz einen neuen Entwurf für einen Feuergehärteten Panzer an. Er wird ihn schmieden, wenn Ihr seltene Materialien von beiden Kontinenten bringt.",h="In Sturmwind bietet Furen Langbart einem Krieger der Allianz einen neuen Entwurf für einen Feuergehärteten...",kw={"verkohltes horn","feuergehärteter panzer","furen langbart","galvanisiertes horn","phlogiston","kral der klingenhauer","roogug","versengter spinnenfangzahn","steinkrallengebirge","sumpfland"},ang={["class:Warrior"]="Als Krieger beweist Ihr Euren Mut, indem Ihr Kalimdors Wildnis und tiefen Verliesen trotzt, um Euch ein meisterhaft gefertigtes Rüstungsteil zu verdienen.",["faction:Alliance"]="Als Soldat der Allianz dringt Ihr tief ins Brachland und ins Steinkrallengebirge vor, wo die Horde um das Land kämpft.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass wahre Rüstung unnachgiebige Materialien verlangt, die direkt von den wildesten Raubtieren der Natur stammen."},sec={{t="Der Ehrgeiz eines Rüstschmiedemeisters",b="Furen Langbart hat einen außergewöhnlichen Faustschild für Euch geschmiedet. Nun schlägt der zwergische Rüstschmied ein größeres Werk vor: eine Kettenrüstung, die heftigen Schlägen standhält. Sein Handwerk verlangt mehr als Eisen oder Stahl. Er braucht seltene Materialien, die von elementarer Hitze und natürlicher Widerstandskraft geprägt sind. Furen kann seine Schmiede in Sturmwind nicht verlassen, also müsst Ihr diese gefährlichen Zutaten sammeln."},{t="Eine Expedition über Kontinente",b="Furen schickt Euch für die Materialien in ferne Wildnisse und gefährliche Tiefen. Das Rezept verlangt nach Reißzähnen giftiger Spinnen aus den feuchten Klüften des Sumpflands. Es braucht auch versengte und galvanisierte Hörner wilder Schimären aus dem Steinkrallengebirge. Um diese Bestienteile zu einer Kettenrüstung zu verbinden und zu härten, braucht Furen flüchtiges Phlogiston von Roogug, einem Geomanten tief im Dornenlabyrinth des Krals der Klingenhauer im Brachland."}},faq={{q="Wer ist Furen Langbart?",a="Furen Langbart ist ein erfahrener zwergischer Rüstschmied und Schildschmied im Zwergendistrikt von Sturmwind. Er fertigt maßgeschneiderte Rüstungen und Schilde für vielversprechende Krieger, die bereit sind, ihm zu helfen.",al={"furen","wer vergibt feuergehärteter panzer","wer ist der schmied"}},{q="Warum braucht Furen so seltsame Zutaten?",a="Furen braucht ungewöhnliche Zutaten, um Metall über die Grenzen gewöhnlicher zwergischer Verfahren hinaus zu härten. Seine geheime Handwerkskunst nutzt organische Materialien, die von natürlichen Giften, Bergwinden und Atemwaffen geprägt wurden, zusammen mit flüchtigem Phlogiston.",al={"warum spinnenreißzähne","warum hörner","was ist phlogiston"}},{q="Woher stammen die Schimärenhörner?",a="Die versengten und galvanisierten Hörner stammen von Schimären aus Kalimdors Steinkrallengebirge. Die jüngeren Bestien und die mächtige Chimaera Matriarch, die sie anführt, tragen diese Hörner.",al={"wo schimärenhörner finden","verkohltes horn fundort","galvanisiertes horn"}},{q="Wo findet man Phlogiston?",a="Roogug, ein Geomant der Stacheleber, trägt in seinem Unterschlupf im Kral der Klingenhauer eine Phiole mit Phlogiston bei sich, nahe der Südspitze des Brachlands in Kalimdor.",al={"phiole mit phlogiston","wer lässt phlogiston fallen","roogug"}},{q="Welche Spinnen tragen versengte Spinnenreißzähne?",a="Leech Stalkers und Cave Stalkers tragen die versengten Spinnenreißzähne. Diese riesigen Spinnentiere lauern in den Sümpfen und Höhlen des Sumpflands in den Östlichen Königreichen.",al={"versengte spinnenreißzähne","wo sind die spinnen","spinnen im sumpfland"}},{q="Was geschieht, wenn alle Materialien gesammelt sind?",a="Sobald Furen die Reißzähne, Hörner und das Phlogiston erhält, beginnt er, eine maßgeschneiderte Brustplatte für Euch zu schmieden. Er fertigt sie in seiner Schmiede im Rahmen von Furen's Armor an.",al={"what comes next","feuergehärteter panzer folgequest","belohnung"}}},fx={cecd81db={q="Warum möchte Furen Langbart, dass dies getan wird?",a="Furen ist sehr stolz auf sein Schmiedehandwerk. Da er Euren Schild bereits gefertigt hat, möchte er sein Können unter Beweis stellen, indem er eine außergewöhnlich robuste Rüstung aus Kettenhemd schmiedet. Er kennt die geheimen Techniken, die erforderlich sind, um diese exotischen, feuergehärteten Reagenzien zu verarbeiten, und er bietet an, das Kettenhemd für Euch zu schmieden, einfach um zu sehen, wie eine solch außergewöhnliche Rüstung entsteht – vorausgesetzt, Ihr seid bereit, den Gefahren des Sammelns der Komponenten zu trotzen.",al={"furen langbarts motivation","warum fire hardened mail herstellen","warum will furen materialien"}}},fp="18,160,27.349.0,30.410.0,23.168.0,48.221.0,38.178.0,30.139.0,42.154.0,50.152.0"}
P.entries["quest:1702"] = {n="Der Schildschmied",s="In Sturmwind schickt Yorus Barleybrew Krieger los, um den versprochenen Schild abzuholen. Eine harte Prüfung im Rotkammgebirge liegt hinter ihnen, und ein Fass Gerstenbräu-Verbrüher ist für Furen Langbart bestimmt, den Schmied, der ihren Schild fertigen wird.",h="In Sturmwind schickt Yorus Barleybrew Krieger los, um den versprochenen Schild abzuholen.",kw={"gerstenbräu-verbrüher","fass","der zwergendistrikt","furen langbart","rethban","schildschmied","sturmwind","krieger","yorus barleybrew"},ang={["class:Warrior"]="Als Krieger bringt Ihr die Zähigkeit des Rotkammgebirges nach Sturmwind und erweist Euch eines Schildes würdig, den ein angesehener zwergischer Rüstschmied fertigt.",["profession:Blacksmithing"]="Als Schmied begegnet Ihr Furen Langbart, dessen Können bei der Herstellung von Schutzrüstung in der gesamten Allianz bekannt ist.",["race:Dwarf"]="Als Zwerg kennt Ihr den Handel: ein Fass feines Gerstenbräu-Bier gegen geschmiedetes Eisen im Zwergendistrikt von Sturmwind."},sec={{t="Ein Versprechen gehalten",b="Ihr habt Euch den Gnollen und Gefahren des Rethban Gauntlet gestellt, und Yorus Barleybrew hält seine Abmachung ein. Seenhain kann den versprochenen Schild nicht liefern, also schickt er bewährte Kämpfer zurück nach Sturmwind. Dort ist ein zwergischer Rüstschmied bereit, eine persönliche Schuld zu begleichen."},{t="Gerstenbräus Bestes",b="Yorus gibt Euch ein schweres Fass Gerstenbräu-Verbrüher anstelle eines Akkreditivs. Bringt es zu Furen Langbart im Zwergendistrikt von Sturmwind. Der erfahrene Schmied weiß, wessen Name hinter dem Fass steht, und stellt sein Können einem Krieger zur Verfügung, der einen robusten Schild sucht."}},faq={{q="Wer ist Furen Langbart?",a="Furen Langbart ist ein zwergischer Meisterrüstschmied im Zwergendistrikt von Sturmwind. Krieger der Allianz kennen sein Können, und er fertigt besondere Schutzausrüstung für erfahrene Kämpfer, die sich seinen Respekt verdienen.",al={"furen langbart","wer ist furen","wer ist der schildschmied"}},{q="Warum schickt Yorus Euch nach Sturmwind?",a="Yorus Barleybrew schickt Euch nach Sturmwind, weil er einen Schild für den Kampf versprochen hat, ihn aber nicht selbst schmieden kann. Sein Freund Furen Langbart schuldet ihm einen großen Gefallen.",al={"warum nach sturmwind gehen","warum sturmwind","yorus belohnung ort"}},{q="Was ist Gerstenbräu-Verbrüher?",a="Gerstenbräu-Verbrüher ist ein starkes Zwergengetränk, das von der Familie Gerstenbräu hergestellt wird. Yorus schickt Furen Langbart ein frisches Fass, um den Durst des Schmieds zu stillen und ihre Abmachung einzuhalten.",al={"fässlein mit gerstenbräu","gerstenbräu-verbrüher","was ist der verbrüher"}},{q="Wo ist Furen Langbart zu finden?",a="Furen Langbart arbeitet an seiner Schmiede im Zwergendistrikt von Sturmwind, inmitten der Werkstätten zwergischer Handwerker.",al={"furen aufenthaltsort","wo ist furen langbart","furen finden"}},{q="Was geschieht, nachdem Furen das Fass erhalten hat?",a="Das Fass verrät Furen, dass Yorus Euch geschickt hat. Furen erkennt seine Schuld an und bietet an, kampferprobte Rüstung zu fertigen, womit der Weg zu feuergehärteter Ausrüstung beginnt.",al={"what comes next","furen folgequest"}},{q="Warum ist dieser Botengang für Krieger der Allianz wichtig?",a="Diese Lieferung führt einen Krieger der Allianz zu einem der besten Rüstschmiede des Königreichs. Sie ebnet den Weg zu maßgefertigter Kampfausrüstung und weiterer Unterweisung in der defensiven Kriegsführung.",al={"bedeutung der kriegerquest","warum für krieger wichtig"}}},fx={["23250e3d"]={q="Warum schickt Yorus Barleybrew Euch auf diese Lieferung anstatt eines Boten?",a="Yorus löst sein Versprechen ein, nachdem Ihr den The Rethban Gauntlet bestanden habt. Anstatt eine routinemäßige Lieferung abzuwickeln, schickt er Euch, um Eure versprochene Belohnung persönlich abzuholen. Da sich der versprochene Schild bei seinem Freund Furen Langbart in Sturmwind befindet, lässt er Euch ein Fass seines berühmten Scalder tragen, damit er sein Wort halten und einen alten Gefallen direkt in Eurem Namen einfordern kann.",al={"warum schickt sie mich shieldsmith","warum schickt yorus mich","warum ich yorus barleybrew"}}},fp="15,235,14.260.0,19.261.0,23.200.0,37.157.0,27.173.0,35.110.0,41.173.0,51.169.0"}
P.entries["quest:1703"] = {n="Mathiel",s="Furen Langbart schickt seine Handwerksnotizen über das Meer zu Mathiel in Darnassus. Auf der Terrasse der Krieger könnte der Nachtelfenschmied die zwergische Kunst des Kettenschmiedens in weitere Hände legen.",h="Furen Langbart schickt seine Handwerksnotizen über das Meer zu Mathiel in Darnassus.",kw={"schmied","darnassus","fire hardened mail","furen langbart","furens notizen","mathiel","teldrassil","die terrasse der krieger"},ang={["class:Warrior"]="Als Krieger führt Euch die Überbringung von Furens Notizen von den Schmieden der Östlichen Königreiche zu den Proving Grounds in Darnassus. Dort wachsen Eure Kenntnisse der Rüstungsschmiedekunst.",["profession:Blacksmithing"]="Als Schmied seht Ihr, wie Meisterschmiede ihr Handwerk durch Zeichnungen und Verfahren zur Wärmehärtung weitergeben, die sie zwischen fernen Schmieden austauschen.",["race:Dwarf"]="Als Zwerg tragt Ihr den Stolz Eures Volkes auf das Schmiedehandwerk über das Meer, indem Ihr Furens Entdeckung mit den Nachtelfen teilt.",["race:NightElf"]="Als Nachtelf könnt Ihr Mathiels Interesse an der zwergischen Schmiedekunst und deren Platz neben der Rüstungsschmiedekunst der Kaldorei erkennen."},sec={{t="Ein Kurier übers Meer",b="Furen Langbart beherrscht das Schmieden feuergehärteter Rüstungen. Nun teilt er sein Wissen mit anderen Handwerkern der Allianz. Er kopiert seine Zeichnungen und schickt Euch über die Kontinente zu Mathiel, einem Schmied auf Teldrassil."},{t="Kaldoreistahl und Zwergenhandwerk",b="Auf der Terrasse der Krieger in Darnassus betreibt Mathiel eine Schmiede für die Schildwachen und andere Verteidiger der Nachtelfenhauptstadt. Furens Notizen bringen zwergische Methoden aus den unterirdischen Schmieden von Khaz Modan zu den Rüstungsschmieden der Kaldorei. Ihr Handwerk ist von ihrer Verbundenheit mit der Natur geprägt."}},faq={{q="Wer ist Mathiel?",a="Mathiel ist ein Nachtelfenschmied auf der Terrasse der Krieger in Darnassus. Er fertigt Ausrüstung für die Verteidiger der Hauptstadt und steht mit Schmieden in der ganzen Allianz im Briefwechsel.",al={"mathiel hintergrundgeschichte","wer ist mathiel darnassus"}},{q="Warum schickt Furen Euch nach Darnassus?",a="Furen Langbart möchte, dass andere Handwerker der Allianz von seiner Arbeit an feuergehärteten Rüstungen profitieren. Er schickt Euch mit seinen Handwerksnotizen zu Mathiel, einem Kollegen, der die Techniken studieren kann.",al={"warum notizen an mathiel schicken","furens notizen grund"}},{q="Wo finde ich Mathiel in Darnassus?",a="Mathiel arbeitet an der Schmiede auf der Terrasse der Krieger in Darnassus, im östlichen Bezirk beim Haupttor. Dort trainieren Krieger und Schildwachen.",al={"mathiel standort","wo ist mathiel"}},{q="Was geschieht, nachdem Mathiel die Notizen erhalten hat?",a="Nachdem Mathiel Furens Notizen erhalten hat, ist er von den Entdeckungen beeindruckt und macht sich daran, die zwergischen Techniken weiterzuentwickeln. Er schickt Euch in Kalimdors Wildnis, um seltene Materialien zu sammeln, darunter Sunscorched Shells.",al={"nächste quest nach mathiel","mathiel folgequest"}},{q="Was für Notizen werden überbracht?",a="Die Notizen enthalten Furens Beobachtungen und Schmiedemethoden aus Experimenten mit versengten Spinnenzähnen, Chimärenhörnern und Phlogiston. Daraus fertigte er verstärkte Kettenrüstung.",al={"furens notizen inhalt","was sind furens notizen"}},{q="Ist diese Quest nur für Krieger?",a="Ja. Die Überbringung gehört zu den Prüfungen und der Ausbildung von Kriegern der Allianz, die ihre Kampffertigkeiten und Kenntnisse der Rüstungsschmiedekunst ausbauen.",al={"kriegerquest mathiel","können andere klassen mathiels quest machen"}}},fx={c109af9e={q="Warum vertraut Furen Langbart darauf, dass Ihr seine Notizen an Mathiel überbringt?",a="Ihr habt Eure Hingabe und Stärke bewiesen, indem Ihr die seltenen Reagenzien gesammelt habt, die Furen brauchte, um Eure feuergehärtete Rüstung überhaupt erst zu schmieden. Da er Eure Zuverlässigkeit aus erster Hand miterlebt hat, weiß er, dass Ihr mehr als fähig seid, den langen Weg über das Meer nach Darnassus zu reisen, um seine hart erarbeiteten Techniken in Mathiels Hände zu bringen.",al={"warum schickt sie mich mathiel","warum ich furen notizen","warum braucht furen mich"}}},fp="7,184,24.217.0,32.267.0,15.163.0,37.190.0,38.138.0,44.215.1,39.170.0,37.132.0"}
P.entries["quest:1704"] = {n="Klockmort Spannsplint",s="In Tinkertown erreichen Furen Langbarts Erkenntnisse über feuergehärtete Kettenrüstung Klockmort Spannsplint. Der Zwergenschmied vertraut darauf, dass sein gnomischer Kollege herausfindet, was die neuen Techniken leisten können.",h="In Tinkertown erreichen Furen Langbarts Erkenntnisse über feuergehärtete Kettenrüstung Klockmort Spannsplint.",kw={"schmied","feuergehärtet","furen","eisenschmiede","klockmort","langbart","notizen","spannsplint","tinkertown"},ang={["class:Warrior"]="Als Krieger folgt Ihr einem Weg zu widerstandsfähiger Kampfausrüstung, von zwergischen Schmiedefeuern bis zu gnomischer Erfindungskunst. Ihr erregt die Aufmerksamkeit der besten Handwerker von Tinkertown.",["profession:Blacksmithing"]="Als Schmied überbringt Ihr Furens Notizen im Rahmen eines Austauschs fortgeschrittener Schmiedetechniken unter den Handwerksmeistern von Eisenschmiede.",["race:Gnome"]="Als Gnom seht Ihr, wie Klockmort in Tinkertown zwergische Metallbearbeitung mit gnomischer Experimentierfreude verbindet."},sec={{t="Ein Kollege in Tinkertown",b="Ihr bringt Furens Notizen von Sturmwind nach Eisenschmiede und dann weiter nach Tinkertown. Dort arbeitet Klockmort Spannsplint als Schmied und kann die Entdeckungen in seinem eigenen Handwerk erproben."},{t="Gnomische Begeisterung",b="Gnomische Schmiede sind unter ihren zwergischen Gastgebern selten. Klockmort will über die traditionelle Metallbearbeitung hinausgehen, und die Aussicht auf einen Durchbruch in den Notizen begeistert ihn. Er ist bereit, die feurigen Techniken an seinen eigenen ungewöhnlichen Projekten zu erproben."}},faq={{q="Wer ist Klockmort Spannsplint?",a="Klockmort Spannsplint ist ein gnomischer Schmied in Tinkertown, einem Viertel von Eisenschmiede. Er arbeitet mit zwergischen Schmieden wie Furen Langbart an Techniken der Metallbearbeitung.",al={"klockmort spannsplint","wer ist klockmort","gnom schmied eisenschmiede"}},{q="Warum schickt Furen Langbart Euch zu Klockmort?",a="Furen Langbart hält schriftlich fest, was er beim Schmieden feuergehärteter Kettenrüstung entdeckt. Er schickt Euch zu Klockmort, weil der Gnom gern erfindet und mit Furens Erkenntnissen experimentieren kann.",al={"warum notizen überbringen","furens notizen","furen langbart klockmort"}},{q="Wo kann ich Klockmort Spannsplint finden?",a="Ihr findet Klockmort Spannsplint in Tinkertown, dem Gnomenviertel im Osten von Eisenschmiede. Er arbeitet dort zwischen Werkbänken und Maschinen.",al={"klockmort standort","wo ist klockmort","klockmort eisenschmiede"}},{q="Was geschieht, nachdem Klockmort die Notizen erhalten hat?",a="Furens Durchbruch begeistert Klockmort, und er beginnt, seine eigenen Metallarbeiten zu planen. Er schickt Euch los, um ungewöhnliche Materialien wie Iron Coral zu sammeln.",al={"questfortsetzung","was kommt nach klockmort","iron coral quest"}},{q="Ist diese Quest auf Krieger beschränkt?",a="Ja. Diese Lieferung gehört zu einer Questreihe zur Rüstungsherstellung für Krieger der Allianz, die bei erfahrenen Waffen- und Rüstungsmeistern lernen.",al={"nur für krieger","kann jeder diese quest machen","klassenvoraussetzung"}},{q="Warum sagt Klockmort, dass er Tag und Nacht nicht unterscheiden kann?",a="Eisenschmiede liegt unter den Bergen von Dun Morogh. In Tinkertown verhindern steinerne Gewölbe und leuchtende Lampen, dass die Handwerker Sonne oder Himmel sehen.",al={"klockmort tag nacht dialog","hier tief unten dialog"}}},fp="21,178,25.173.0,18.242.0,29.159.0,47.184.0,39.136.0,46.154.1,34.124.0,53.140.0"}
P.entries["quest:1705"] = {n="Brennendes Blut",s="In Sturmwind stellt Grimand Elmore Furen Langbarts Schmiedemethoden auf die Probe. Um sie an seiner eigenen Esse zu erproben, braucht er Brennendes Blut und einen Brennenden Fels aus dem Dämmerwald.",h="In Sturmwind stellt Grimand Elmore Furen Langbarts Schmiedemethoden auf die Probe.",kw={"brennendes blut","brennender fels","dämmerwald","furen langbart","grimand elmore","gutspill","nightbane-worgen","rolands verdammnis"},ang={["class:Warrior"]="Als Krieger könnt Ihr Euch für Grimands Experiment den verfluchten Bestien des Dämmerwalds stellen und eine auf einzigartige Weise gehärtete Rüstung für die Front verdienen.",["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr Reagenzien aus Rolands Verdammnis bergen und so helfen, die Worgenbedrohung im Dämmerwald einzudämmen und Sturmwinds Waffenschmieden neue Verteidigungsmethoden zu erschließen.",["profession:Blacksmithing"]="Als Schmied könnt Ihr zusehen, wie Grimand die Methoden seines ehemaligen Schülers Furen mit seltenen Metallen und Abschreckmitteln erprobt."},sec={{t="Ein widerwilliges Experiment",b="Grimand Elmore ist einer der besten Rüstungsschmiede der Allianz. Er glaubt selten, dass ein anderer Schmied seine Methoden übertreffen kann. Doch Furen Langbarts ungewöhnliche Entdeckungen haben seine berufliche Neugier geweckt, und Grimand willigt ein, damit ein Rüstungsteil anzufertigen.\n\nFür diese Arbeit braucht er seltsame, unbeständige Materialien aus den finsteren Gefilden des Südens. Damit wird er das Metall genau nach seinen Vorgaben abschrecken und härten. Gewöhnliches Wasser und einfache Kohlen reichen dafür nicht aus."},{t="Die Schrecken von Rolands Verdammnis",b="Grimand schickt Euch nach Rolands Verdammnis, einer verlassenen Mine im Dämmerwald. Wilde Nightbane-Worgen haben ihre Stollen überrannt, und in ihren verfluchten Adern pulsiert brennender Ichor.\n\nEr braucht Phiolen ihres Brennenden Blutes und einen seltenen, flammenden Kern, der Brennender Fels genannt wird. Gutspill, der Anführer des Rudels, trägt ihn bei sich. Bringt beide sengenden Materialien zurück, damit Grimand Furens Methoden an der Esse erproben kann."}},faq={{q="Wer ist Grimand Elmore?",a="Grimand Elmore ist ein angesehener Rüstungsschmiedemeister im Zwergendistrikt von Sturmwind. Gemeinsam mit anderen Handwerkern rüstet er die Verteidiger der Stadt aus und unterweist angehende Krieger im Gewicht und in der Stärke solider Plattenrüstung.",al={"grimand","grimand elmore","rüstungsschmied sturmwind"}},{q="Warum will Grimand Brennendes Blut und einen Brennenden Fels?",a="Grimand möchte eine von Furen Langbart entwickelte Rüstungsschmiedetechnik erproben. Das Brennende Blut und der Brennende Fels liefern die übernatürliche Hitze, die zum Schmieden und Härten besonderer Rüstungsplatten benötigt wird.",al={"warum brennendes blut","wofür ist brennender fels","zweck der quest"}},{q="Wo finde ich die Nightbane-Worgen, die diese Materialien bei sich tragen?",a="Ihr findet die Materialien in Rolands Verdammnis, einer verlassenen Mine im Südosten des Dämmerwalds, südwestlich von Dunkelhain. Nightbane-Worgen bevölkern ihre Stollen und tragen das Brennende Blut bei sich.",al={"wo sind die worgen","rolands verdammnis standort","wo ist brennendes blut"}},{q="Wer hat den Brennenden Fels?",a="Gutspill, ein mächtiger Anführer unter den Nightbane-Worgen, trägt den Brennenden Fels tief in Rolands Verdammnis bei sich.",al={"wer hat brennenden fels","gutspill","gutspill standort"}},{q="In welcher Beziehung stehen Grimand Elmore und Furen Langbart zueinander?",a="Furen Langbart ist Grimand Elmores ehemaliger Schüler. Grimand begegnet fremden Ideen gewöhnlich mit Skepsis, doch Furens neueste Rüstungsschmiedemethoden haben ihn überzeugt, sie selbst zu erproben.",al={"grimand und furen","wer ist furen langbart"}},{q="Was geschieht, nachdem Blut und Fels zurückgebracht wurden?",a="Nachdem er die feurigen Reagenzien erhalten hat, beginnt Grimand, eine Rüstung zu schmieden, um Furens Methoden zu erproben. Er verspricht das fertige Stück dem Abenteurer, der die Materialien beschafft hat.",al={"nächste quest","belohnung","was stellt grimand her"}}},fx={["50895b50"]={q="Wozu dient Burning Blood?",a="Grimand Elmore benötigt das brennende Blut, um eine exotische Schmiedetechnik zu testen, die von seinem ehemaligen Schüler, Furen Langbart, entwickelt wurde. Grimand nutzt die unnatürliche, feurige Hitze, die durch die Adern der Worgen im Dämmerwald fließt, um eine spezielle Rüstung zu härten und zu sehen, ob Furens Metallurgie wirkliche Vorzüge hat.",al={"burning blood questgegenstand","wofür wird burning blood verwendet","warum burning blood"}},["8a0ab7ce"]={q="Wozu dient Brennender Fels?",a="Grimand benötigt den brennenden Fels als wesentliche Komponente für die Erprobung der Rüstungsschmiedemethoden von Furen Langbart. Der sengende Stein stammt von dem Worgenrudelführer Gutspill tief in Rolands Verdammnis und liefert die rohe elementare Hitze und die arkanen Eigenschaften, die zum Schmieden der Fire Hardened Coif erforderlich sind.",al={"nutzen von brennender fels","warum brennender fels","was macht grimand mit brennender fels"}},["0438723a"]={q="Wer sind die Nightbane-Worgen im Dämmerwald?",a="Die Nightbane sind wilde, wolfsähnliche Humanoide, die die dunklen Wälder des Dämmerwaldes heimsuchen. Ein Trupp von ihnen hat Zuflucht in der verlassenen Mine von Rolands Verdammnis gefunden, befehligt von dem furchterregenden Gutspill. Ihr unnatürlich heißes Blut und ihre feurigen Schätze machen sie zum Ziel ehrgeiziger Rüstungsschmiede wie Grimand.",al={"wer sind nightbane worgen","rolands verdammnis worgen","nightbane rolands verdammnis"}}},fp="13,170,22.455.0,28.382.0,22.221.0,55.196.0,62.177.0,27.109.0,68.186.0,48.168.0"}
P.entries["quest:1706"] = {n="Grimands Rüstung",s="Grimand Elmore bietet Euch nun eine Bundhaube aus seltenen Materialien an. Sie erprobt Furen Langbarts Schmiedemethoden und soll wuchtigen Schlägen standhalten, ein hart erkämpfter Schritt in Eurer Ausbildung zum Krieger der Allianz.",h="Grimand Elmore bietet Euch nun eine Bundhaube aus seltenen Materialien an.",kw={"rüstung","bundhaube","burning blood","der zwergendistrikt","furen langbart","grimand elmore","sturmwind","kriegerquest"},ang={["class:Warrior"]="Als Krieger der Allianz erreicht Ihr einen entscheidenden Schritt Eurer Ausbildung: eine widerstandsfähige Bundhaube, geschmiedet, um den harten Schlägen im Kampf an der Front standzuhalten.",["faction:Alliance"]="Grimand Elmore greift auf Furen Langbarts Entwürfe zurück, während die zwergischen Schmiede im Zwergendistrikt von Sturmwind ihre Erkenntnisse zusammentragen, um Krieger der Allianz auszurüsten.",["profession:Blacksmithing"]="Der Austausch verbindet zwei zwergische Schmiede im Zwergendistrikt von Sturmwind, die ungewöhnliche Reagenzien zum Härten von Metall verwenden."},sec={{t="Die bewährte Neuerung eines Meisters",b="Die Bundhaube zeigt, dass Furen Langbarts gewagte Methoden Rüstungen gegen wuchtige Schläge stärken können. Grimand Elmore schmiedete sie aus seltenen Elementar- und Bestienbestandteilen, die Ihr in feindlichem Gebiet gesammelt habt, und stellte damit die Theorien des zwergischen Meisterrüstungsbauers auf die Probe."},{t="Das Schmieden der Ägide",b="Grimand Elmore behandelt das Metall, damit es Druck und Schlägen standhält, die gewöhnlichen Stahl verformen würden. Dann überreicht er Euch die fertige Bundhaube. Ihre Widerstandskraft ehrt Furen Langbarts Handwerk und Eure Entschlossenheit und könnte Euch helfen, die Front gegen Azeroths größte Bedrohungen zu halten."}},faq={{q="Was ist der Zweck dieser Quest?",a="Grimand Elmore vollendet aus den seltenen Materialien, die Ihr gesammelt habt, eine speziell behandelte Bundhaube und erprobt damit Furen Langbarts experimentelle Schmiedemethoden. Dies ist die abschließende Übergabe einer bedeutenden Questreihe zur Kriegerausbildung.",al={"grimands rüstung zweck","warum grimands rüstung machen","was gibt grimand"}},{q="Wer ist Grimand Elmore?",a="Grimand Elmore ist ein geschickter zwergischer Waffenschmied im Zwergendistrikt von Sturmwind. Er arbeitet mit Kollegen in Eisenschmiede zusammen, um angehenden Kriegern zu spezialisierter Rüstung zu verhelfen.",al={"wer ist grimand","grimand elmore rolle","wo ist grimand"}},{q="Wer ist Furen Langbart und warum wird er erwähnt?",a="Furen Langbart ist ein zwergischer Meisterrüstungsbauer im Zwergendistrikt von Sturmwind. Er entwickelte eine Methode, um Rüstungen gegen gewaltige Belastungen zu verstärken, doch Grimand bezweifelte seine Behauptungen, bis Ihr Materialien zur Erprobung brachtet.",al={"wer ist furen","furens technik","furen langbart"}},{q="Welche Quest führt unmittelbar zu dieser?",a="Diese Quest folgt auf „Burning Blood“. Dort bringt Ihr Grimand die letzte seltene Reagenz, Burning Blood von den Nightbane-Worgen in Rolands Verdammnis im Dämmerwald, damit er das Metall abschrecken und härten kann.",al={"voraussetzung für grimands rüstung","burning blood quest","welche quest kommt davor"}},{q="Kann jede Klasse diese Quest abschließen?",a="Nein. Diese Questreihe richtet sich an Krieger der Allianz um ihre dreißigste Saison und markiert eine Bewährungsprobe auf dem Weg zu widerstandsfähiger Kettenrüstung.",al={"grimands rüstung nur für krieger","wer kann grimands rüstung machen"}},{q="Wo wird diese Quest abgegeben?",a="Ihr bringt die Bundhaube zu Grimand Elmore an seinem Amboss im Zwergendistrikt von Sturmwind.",al={"wo grimands rüstung abgeben","grimand standort sturmwind"}}},fx={c92a0d61={q="Warum möchte Grimand Elmore, dass dies getan wird?",a="Grimand Elmore stellt die radikalen Schmiedetechniken von Furen Langbart auf die ultimative Probe. Zunächst skeptisch, dass Furens Methoden überlegene Ergebnisse liefern könnten, benötigte Grimand seltene und potente Komponenten, um das Set selbst zu schmieden. Indem er die Rüstung fertigstellt und beweist, dass sie unglaublicher Beanspruchung standhalten kann, bestätigt er den Durchbruch seines Schmiedekollegen und rüstet gleichzeitig einen versierten Krieger für den Kampf aus.",al={"warum grimands rüstung herstellen","grimand elmore beweggrund","warum die rüstung schmieden"}}},fp="15,202,28.259.0,17.261.0,34.201.0,22.168.0,47.208.0,40.187.0,34.124.0,35.87.0"}
P.entries["quest:1707"] = {n="Wasserbeutelkopfgeld",s="In Gadgetzan bittet Euch Leitungshahnmaschinist Luglunket, die von den Nomaden gestohlenen Wastewander-Wasserbeutel zurückzuholen. Bringt sie von überall aus der Wüste zurück, und die Gadgetzan Water Company bietet für jeweils fünf ein offizielles Hilfspaket an.",h="In Gadgetzan bittet Euch Leitungshahnmaschinist Luglunket, die von den Nomaden gestohlenen...",kw={"gadgetzan","luglunket","tanaris","wastewander","wassergesellschaft","wasserbeutel"},sec={{t="Wasser, das Gadgetzan gehört",b="Leitungshahnmaschinist Luglunket möchte, dass Ihr die Wastewander-Wasserbeutel zurückbringt, die Ihr in der Wüste findet. Die Nomaden haben Gadgetzans Wasser gestohlen, also hilft jeder Beutel der Stadt, ihr Eigentum zurückzuerlangen. Für jeweils fünf zurückgebrachte Beutel bietet die Gadgetzan Water Company ein offizielles Hilfspaket an."},{t="Immer her damit",b="Luglunket freut sich über jeden zurückgeholten Beutel, denn jeder einzelne zögert die Katastrophe weiter hinaus. Bringt fünf zurück, und Luglunket verspricht, dass es sich für Euch lohnt."}},faq={{q="Wer ist Leitungshahnmaschinist Luglunket?",a="Leitungshahnmaschinist Luglunket ist ein erfahrener Leitungshahnmaschinist in Gadgetzan, der die Wastewander-Wasserbeutel zurückhaben möchte.",al={"wer ist luglunket","luglunkets aufgabe","leitungshahnmaschinist"}},{q="Warum will Luglunket Wastewander-Wasserbeutel haben?",a="Die Wastewander-Nomaden haben Wasser gestohlen, das Gadgetzan gehört.",al={"warum wasserbeutel","warum wastewander töten","wastewander wasser hintergrund"}},{q="Wo sind Wastewander-Wasserbeutel zu finden?",a="Die gestohlenen Beutel sind irgendwo in der Wüste, in den Händen der Wastewander-Nomaden.",al={"wo wasserbeutel finden","wastewander-beutel fundort","wer lässt wasserbeutel fallen"}},{q="Was bietet die Gadgetzan Water Company für die Beutel an?",a="Die Gadgetzan Water Company bietet für jeweils fünf Beutel ein offizielles Hilfspaket an.",al={"hilfspaket","was gibt es für beutel"}}},fp="18,236,31.288.0,16.153.1,33.118.0,50.61.0,45.87.0,60.83.0"}
P.entries["quest:1708"] = {n="Eisenkoralle",s="In der Tüftlerstadt sucht Klockmort Spannerspan Sengkoralle für eine neue Rüstung. Der Gnomschmied hofft, mit diesem seltenen Meeresmaterial von der Küste des Sumpflands neue Schmiedemethoden zu erproben.",h="In der Tüftlerstadt sucht Klockmort Spannerspan Sengkoralle für eine neue Rüstung.",kw={"rüstung einschmelzen","furen langbart","eisenkoralle","eisenschmiede","klockmort spannerspan","hafen von menethil","sengkoralle","tüftlerstadt","sumpfland"},ang={["profession:Blacksmithing"]="Als Schmied könnt Ihr Klockmorts Versuch würdigen, ein Meeresvorkommen einzuschmelzen und daraus gehärtete Rüstungsplatten zu fertigen.",["profession:Engineering"]="Als Ingenieur könnt Ihr den Wert darin erkennen, ungewöhnliche Materialien zu erproben, um besseren Schutz zu schaffen.",["race:Dwarf"]="Als Zwerg könnt Ihr sehen, wie die metallurgischen Entdeckungen des Meisterschmieds Furen Langbart bei dieser Zusammenarbeit zwischen Gnomen und Zwergen in der Tüftlerstadt Anwendung finden.",["race:Gnome"]="Als Gnom könnt Ihr Klockmorts Suche nach ungewöhnlichen Küstenmineralien als einen Weg sehen, traditionelles Handwerk durch Experimente zu verbessern."},sec={{t="Vereinte Handwerkskünste",b="Klockmort Spannerspan hat sich mit Furen Langbart, einem zwergischen Meisterschmied, über Entdeckungen ausgetauscht. Nun hofft er, Furens Können in der Metallurgie mit seiner eigenen Tüftelkunst zu vereinen. Bergerz allein wird ihm nicht die widerstandsfähige Rüstung liefern, die er anstrebt. Deshalb braucht er Sengkoralle, ein vom Meer gehärtetes Material."},{t="Tauchen an der Sumpflandküste",b="Sengkoralle wächst unter Wasser vor der Küste des Sumpflands, südlich des Hafens von Menethil. Ihr müsst zwanzig Ansammlungen bergen, während unter Wasser Raubtiere umherstreifen. Bringt die Ausbeute dann nach Eisenschmiede. Klockmort plant, die Koralle einzuschmelzen und zu experimentellen Rüstungsplatten zu schmieden."}},faq={{q="Wer ist Klockmort Spannerspan?",a="Klockmort Spannerspan ist ein geschickter Gnomschmied in der Tüftlerstadt in Eisenschmiede. Er liebt mechanische Tüfteleien und neue Ansätze in der Metallurgie und arbeitet mit zwergischen Handwerkern an Methoden zur Rüstungsherstellung.",al={"klockmort","wer vergibt eisenkoralle","questgeber eisenkoralle"}},{q="Was ist Sengkoralle?",a="Sengkoralle ist ein seltenes Meeresgewächs am Meeresgrund südlich des Hafens von Menethil im Sumpfland. Dank ihrer ungewöhnlichen chemischen und physikalischen Eigenschaften kann ein einfallsreicher Schmied sie einschmelzen und zu Rüstungsverstärkungen schmieden.",al={"sengkoralle hintergrund","wofür wird sengkoralle verwendet"}},{q="Wo finde ich die Sengkoralle?",a="Sucht unter Wasser entlang der Küste des Sumpflands südlich des Hafens von Menethil. Taucher müssen die mineralreichen Zweige vom Meeresgrund losbrechen.",al={"sengkoralle fundort","wo findet man eisenkoralle","sumpfland koralle fundort"}},{q="Warum braucht Klockmort Sengkoralle statt Metallerz?",a="Klockmort hofft, dass Sengkoralle Rüstungen leichter und haltbarer macht als solche, die allein aus Erz aus Eisenschmiede bestehen. Er passt Schmiedetechniken an, die er vom Zwerg Furen Langbart gelernt hat.",al={"warum koralle für rüstungen","koralle metallurgie"}},{q="Welche Rolle spielt Furen Langbart bei dieser Aufgabe?",a="Furen Langbart hat mit Eurer Hilfe neue Techniken zur Rüstungsherstellung entwickelt. Aus Dank für Eure Unterstützung teilte er seine Handwerksgeheimnisse mit Klockmort und regte so die Rüstungsentwürfe des Gnoms an.",al={"verbindung zu furen","furen langbart eisenkoralle"}},{q="Was geschieht, nachdem die Koralle zu Klockmort gebracht wurde?",a="Mit zwanzig Ladungen Sengkoralle beginnt Klockmort an seiner Werkbank, sie einzuschmelzen und zu schmieden. Seine Arbeit führt in „Klockmort's Creation“ zu experimenteller Ausrüstung.",al={"eisenkoralle folgequest","nächste quest eisenkoralle"}}},fx={f5cb4716={q="Warum möchte Klockmort Spannerspan, dass die Sengkoralle gesammelt wird?",a="Klockmort ist ein begeisterter Gnomenerfinder, der begierig darauf ist, zu experimentieren. Nachdem er von Furen Langbart innovative Schmiedetechniken gelernt hat, möchte er Furens Methoden mit seinem eigenen Ingenieurswissen kombinieren, um eine außergewöhnlich widerstandsfähige Rüstung zu schmieden. Um sie herzustellen, benötigt er spezifisch die einzigartigen Eigenschaften der Sengkoralle, die an der Küste des Sumpflandes geerntet wird.",al={"warum will klockmort koralle","klockmort motiv sengkoralle","warum sengkorallenrüstung herstellen"}}},fp="10,189,18.290.0,25.272.0,29.199.0,22.216.0,34.133.0,59.187.0,45.180.0,51.157.1"}
P.entries["quest:1709"] = {n="Klockmorts Kreation",s="In Tüftlerstadt wendet Klockmort Spannerspan Furen Langbarts Schmiedeverfahren auf seltene Materialien an. Das Ergebnis ist eine Rüstung, die viel aushält.",h="In Tüftlerstadt wendet Klockmort Spannerspan Furen Langbarts Schmiedeverfahren auf seltene Materialien an.",kw={"furen langbart","iron coral","eisenschmiede","klockmort","belagerungsmaschine","spannerspan","tüftlerstadt","kriegerrüstung"},ang={["class:Warrior"]="Als Krieger der Allianz erreicht Ihr mit diesen Handschuhen einen wichtigen Meilenstein. Sie wurden eigens gehärtet, um den zermalmenden Schlägen im Frontkampf standzuhalten.",["profession:Blacksmithing"]="Als Schmied erkennt Ihr den Wert darin, unkonventionelle Härteverfahren mit seltenen Materialien aus dem Meer zu erproben.",["race:Gnome"]="Als Gnom erkennt Ihr, wie der Einfallsreichtum Eures Volkes die Herstellung schwerer Rüstungen unterstützt und dabei mechanische Präzision mit zwergischer Handwerkskunst verbindet."},sec={{t="Eine Verbindung der Disziplinen",b="Mit Furen Langbarts Verfahren vollendet Klockmort in Tüftlerstadt ein Paar Panzerhandschuhe. Zwergische Metallverarbeitung und gnomisches Geschick in der Mechanik vereinen sich in Handschuhen, die Belastungen standhalten, die gewöhnlichen Stahl zermalmen würden."},{t="Unübertroffene Widerstandskraft",b="Klockmort sagt, eine Belagerungsmaschine könnte über die Rüstung rollen, ohne bleibende Verformungen zu hinterlassen. Auf besondere Weise behandelte seltene Bestandteile verleihen ihr Widerstandskraft. Zwergische Schmiedekunst und gnomischer Einfallsreichtum vereinen sich in einer Rüstung, die den heftigsten Schlachten an der Front standhält."}},faq={{q="Wer ist Klockmort Spannerspan?",a="Klockmort Spannerspan ist ein geschickter gnomischer Schmied in Tüftlerstadt in Eisenschmiede. Er hilft bei anspruchsvollen mechanischen Arbeiten und fertigt gemeinsam mit zwergischen Handwerkern wie Furen Langbart ungewöhnliche, langlebige Ausrüstung.",al={"klockmort","wer ist klockmort","gnom in tüftlerstadt"}},{q="Wer hat das Verfahren zur Herstellung dieser Rüstung entwickelt?",a="Furen Langbart, ein versierter zwergischer Rüstungsschmied, entwickelte das Schmiedeverfahren. Klockmort befolgte Furens genaue Methoden, um die Materialien zu behandeln und die Rüstung zu vollenden.",al={"wer entwickelte das verfahren","furen langbart rüstung","furens verfahren"}},{q="Warum hat ein gnomischer Schmied diese Rüstung hergestellt?",a="Klockmort wollte Furen Langbarts neue Technik an einer eigenen Rüstung erproben. Da Ihr Furen geholfen hattet, bot Klockmort Euch die fertige Rüstung dafür an, dass Ihr die benötigte Sengkoralle beschafft.",al={"warum ein gnom","gnomische schmiedekunst","ingenieurskunst rüstung"}},{q="Was macht diese Rüstung im Vergleich zu gewöhnlicher Plattenrüstung besonders?",a="Klockmort sagt, die fertige Rüstung verbinde bemerkenswerte Federkraft und Elastizität mit robuster Beständigkeit. Er behauptet, selbst wenn eine schwere Belagerungsmaschine sie platt walzen würde, spränge das Metall in seine ursprüngliche Form zurück.",al={"wie widerstandsfähig ist sie","belagerungsmaschine rüstung","haltbarkeit der rüstung"}},{q="Welchen Platz hat diese Rüstung in der Ausbildung eines Kriegers?",a="Die Rüstung gehört zu einer Reihe von Aufgaben für vielversprechende Krieger der Allianz, die widerstandsfähige, von Eisenschmiedes klügsten Köpfen maßgeschmiedete Ausrüstung suchen.",al={"kriegerquest rüstung","warum diese quest erledigen","kriegerbelohnung"}},{q="Wo ist Klockmort zu finden?",a="Klockmort Spannerspan arbeitet zwischen den Werkstätten, klappernden Zahnrädern und Dampfauslässen von Tüftlerstadt, dem gnomischen Viertel von Eisenschmiede.",al={"klockmort standort","wo ist spannerspan"}}},fx={fd9fc5fd={q="Warum hilft Klockmort Spannerspan bei der Herstellung dieser Rüstung?",a="Klockmort Spannerspan hat die Aufgabe übernommen, Furen Langbarts radikale Schmiedetheorie zu testen. Zwergisches Schmieden verlässt sich selten auf präzise gnomische Ingenieurskunst, daher bot der Zusammenbau der Handschuhe Klockmort die Chance zu beweisen, dass die Kombination von Furens Methoden mit gnomischer Mechanik eine Rüstung hervorbringen könnte, die widerstandsfähig genug ist, um selbst eine Belagerungsmaschine zu überstehen.",al={"warum hilft klockmort","klockmort spannerspan motiv","warum schmiedet klockmort dies"}}},fp="20,138,23.232.0,20.248.0,29.208.0,44.167.0,43.198.0,57.207.0,62.136.0,25.125.0"}
P.entries["quest:1710"] = {n="Sonnenverbrannte Schalen",s="In Darnassus sucht Mathiel Wyverneierschalen, um ein neues Verfahren zur Herstellung von Kettenrüstungen zu verbessern. Er arbeitet mit Furen Langbart, einem Zwergenschmied, zusammen und schickt Krieger los, um Schalen vom Steilhang in Tausend Nadeln zu sammeln.",h="In Darnassus sucht Mathiel Wyverneierschalen, um ein neues Verfahren zur Herstellung von Kettenrüstungen zu...",kw={"eierschalen","furen langbart","der steilhang","lack","kettenrüstung","mathiel","tausend nadeln","wyvern"},ang={["class:Warrior"]="Als Krieger der Allianz könnt Ihr Mathiel helfen, ein Verfahren zur Herstellung widerstandsfähiger Kettenrüstungen zu erproben.",["faction:Alliance"]="Ihr könnt erleben, wie nachtelfische Handwerker in Darnassus Techniken mit zwergischen Rüstungsschmieden in Sturmwind austauschen.",["profession:Blacksmithing"]="Ihr könnt eine ungewöhnliche Schmiedemethode im Einsatz sehen: Aus tierischen Materialien wird ein schützender Lack für metallene Kettenglieder."},sec={{t="Eine fraktionsübergreifende Handwerksallianz",b="Von der Terrasse der Krieger in Darnassus aus blickt Mathiel über nachtelfische Methoden hinaus. Er steht mit Furen Langbart, einem geschickten Zwergenrüstschmied in Sturmwind, im Briefwechsel und studiert dessen Entdeckungen in der Metallverarbeitung und Rüstungsschmiedekunst. Mathiel hofft, Kettenrüstungen mit natürlichen Materialien zu verstärken, die großen Belastungen standhalten können. Um seine Idee zu prüfen, braucht er Materialien, die es nirgendwo in der Nähe von Teldrassil gibt."},{t="Die Gefahren des Steilhangs",b="Mathiels Experiment erfordert Schalen vom Steilhang, weit im Süden jenseits des Meeres in den Canyonschluchten von Tausend Nadeln. Hoch über den Salzebenen und roten Tafelbergen nisten Wyvern unter Kalimdors sengender Sonne. Hitze und Höhenlage härten ihre Eierschalen. Mathiel will die sonnengebackenen Bruchstücke zermahlen, zu einem widerstandsfähigen Lack verarbeiten und damit Kettenglieder überziehen, damit die Rüstung biegsam bleibt und außergewöhnlichen Belastungen standhält."}},faq={{q="Wer ist Mathiel?",a="Mathiel ist ein Nachtelf und Rüstungsschmied auf der Terrasse der Krieger in Darnassus. Mit zwergischen Methoden und Furen Langbart entwickelt er fortschrittliche Kettenrüstungen für bewährte Krieger.",al={"mathiel","wer vergibt sonnenverbrannte schalen","mathiel darnassus"}},{q="Warum braucht Mathiel Wyvernschalen?",a="Die Wyvernschalen vom Steilhang härten unter der erbarmungslosen Sonne von Tausend Nadeln aus. Mathiel will sie zermahlen und zu Lack für Kettenglieder verarbeiten, um die Rüstung zu verstärken.",al={"warum wyvernschalen","sonnenverbrannte schale zweck","wozu dienen die schalen"}},{q="Wo liegt der Steilhang?",a="Der Steilhang ist ein steiler Tafelberg im Westen von Tausend Nadeln, nahe der Grenze zu Feralas. Wyvern nisten an seinen Klippen und auf seinem Plateau.",al={"steilhang lage","wo ist der steilhang","wie den steilhang finden"}},{q="Was hat Furen Langbart mit dieser Aufgabe zu tun?",a="Furen Langbart ist ein meisterhafter Zwergenrüstschmied in Sturmwind. Mathiel schätzt ihn als Kollegen und lässt sich von seinen Entdeckungen in der Rüstungsschmiedekunst inspirieren.",al={"furen langbart verbindung","wer ist furen"}},{q="Warum bittet ein Elf in Darnassus um Materialien aus Tausend Nadeln?",a="Mathiel braucht die Widerstandsfähigkeit von Wyverneiern, die der trockenen Hitze auf den Tafelbergen der südlichen Schluchten ausgesetzt sind. Diese Hitze lässt sich im nebligen Geäst von Teldrassil nicht nachbilden.",al={"warum tausend nadeln","von darnassus nach tausend nadeln"}},{q="Was geschieht, nachdem die Schalen zu Mathiel gebracht wurden?",a="Sobald Mathiel zwanzig sonnenverbrannte Schalen erhalten hat, beginnt er, den Lack herzustellen und als Gegenleistung für Eure Mühen eine maßgeschneiderte Kettenrüstung für Euch zu schmieden.",al={"wie geht es bei mathiel weiter","nach sonnenverbrannten schalen","mathiel fortsetzung"}}},fx={dd37f0b8={q="Wozu dient die Sonnenverbrannte Schale?",a="Diese widerstandsfähigen Eierschalen von den Wyvern am Steilhang sind überraschend robust. Mathiel beabsichtigt, sie aufzubrechen und zu einem Schutzlack zu verarbeiten, den er verwenden wird, um die einzelnen Glieder seiner experimentellen Kettenrüstung zu beschichten und ihre Haltbarkeit zu erhöhen.",al={"verwendung sonnenverbrannte schale","warum sonnenverbrannte schale","wozu dienen die eierschalen"}}},fp="18,206,33.376.0,23.399.0,15.160.0,36.155.0,27.123.0,46.152.0,70.157.0,50.155.0"}
P.entries["quest:1711"] = {n="Mathiels Rüstung",s="An der Schmiede in Darnassus vereint Mathiels Rüstung die Handwerkskunst von Nachtelfen und Zwergen. Auf der Terrasse der Krieger nutzt Mathiel von Furen Langbart entwickelte Methoden, um exotische Materialien zu Rüstungen für Krieger der Allianz zu formen.",h="An der Schmiede in Darnassus vereint Mathiels Rüstung die Handwerkskunst von Nachtelfen und Zwergen.",kw={"die terrasse der handwerker","darnassus","furen langbart","mathiel","mathiels rüstung","sonnenverbrannte schalen","kriegerrüstung"},ang={["class:Warrior"]="Für Krieger der Allianz bringt diese Questreihe robuste Gamaschen hervor, gefertigt mit dem Schmiedewissen der Nachtelfen und Zwerge.",["faction:Alliance"]="Die Zusammenarbeit von Mathiel und Furen zeigt, wie die Allianz ferne Völker durch Handel und gemeinsame Verteidigung vereint, um ihren militärischen Bedarf zu decken.",["profession:Blacksmithing"]="Zwergische Härtungsmethoden und die Schmiedekunst der Nachtelfen finden in diesem Werk zusammen."},sec={{t="Vereinte Handwerkskunst",b="Seit Jahrtausenden richten die Rüstungsschmiede der Nachtelfen ihre Arbeit an der Natur, geschmeidigem Leder und sorgfältig bearbeiteten Metallen aus. Der Handel mit den Östlichen Königreichen hat Schmiede wie Mathiel dazu angeregt, neue Wege zu erproben. Er verbindet elfische Handwerkskunst mit den zwergischen Techniken, die Furen Langbart entwickelt hat."},{t="Exotische Bestandteile",b="Mathiel benötigt sonnenverbrannte Eierschalen aus den Wyvernestern am Steilhang in Tausend Nadeln. Er verarbeitet die sonnengehärteten Schalen zu Lack und nutzt dann Furens Wärmebehandlungsformeln, um widerstandsfähige Gamaschen für die vordersten Fronten zu schmieden."}},faq={{q="Wer ist Mathiel?",a="Mathiel ist ein geschickter Rüstungsschmied der Nachtelfen auf der Terrasse der Krieger in Darnassus. Er arbeitet mit anderen Handwerkern der Allianz zusammen und erprobt Ideen von Verbündeten wie Furen Langbart.",al={"mathiel","wer ist mathiel","rüstungsschmied darnassus"}},{q="Wer ist Furen Langbart?",a="Furen Langbart ist ein zwergischer Meisterrüstungsschmied, der in Sturmwind lebt. Er entwickelte Methoden zum Härten und Schmieden spezieller Rüstungsplatten und teilt Anleitungen und Entwürfe mit verbündeten Schmieden.",al={"furen","furen langbart"}},{q="Aus welchen Materialien wurde die Rüstung geschmiedet?",a="Für die Rüstung werden sonnenverbrannte Eierschalen verwendet, die unterhalb der Wyvernester am Steilhang in Tausend Nadeln gesammelt werden. Mathiel formt und verstärkt sie mit den Schmiedemethoden von Furen Langbart.",al={"rüstungsmaterialien","woraus besteht mathiels rüstung"}},{q="Warum nutzt ein Elf zwergische Techniken?",a="Schmiede der Allianz teilen ihr Wissen, um ihre Kämpfer gegen wachsende Bedrohungen auszurüsten. Mathiel verbindet zwergische Härtungsmethoden mit der Finesse und Haltbarkeit der Schmiedekunst der Nachtelfen.",al={"warum zwergische schmiedekunst","zusammenarbeit nachtelfen zwerge"}},{q="Wo spielt diese Quest?",a="Die Arbeit beginnt und endet an der Schmiede auf der Terrasse der Krieger in Darnassus, auf der Insel Teldrassil.",al={"mathiel standort","wo ist mathiel"}},{q="Welche Quest geht dieser Questreihe voraus?",a="Die Questreihe folgt auf „Sonnenverbrannte Schalen“, worin ein Abenteurer in einen entlegenen Teil Kalimdors reist, um widerstandsfähige Eierschalen für Mathiels Handwerk zu sammeln.",al={"vorherige quest","mathiels rüstung voraussetzung"}}},fx={["5fea36e4"]={q="Warum schmiedet Mathiel diese Rüstung für Euch?",a="Mathiel möchte das Handwerk, das Furen Langbart geteilt hat, testen und beweisen. Indem er zwergische Plattnertechniken mit elfischen Traditionen verbindet, ist er in der Lage, außergewöhnlich widerstandsfähige Kettengamaschen herzustellen, um Krieger zu stärken, die im Namen der Allianz kämpfen.",al={"warum stellt mathiel rüstung her","mathiel motivation","warum mathiel's armor herstellen"}}},fp="15,208,17.274.0,17.228.0,15.168.0,23.202.0,44.175.0,39.179.0,33.100.0,41.147.0"}
P.entries["quest:1712"] = {n="Cyclonian",s="An der Beschwörungsstätte wartet Cyclonian auf einen Champion, der kühn genug ist, sich ihm zu stellen. Ein besonderes Pergament nennt die seltenen Materialien, die nötig sind, um den Windlord herbeizurufen, dessen Wirbelherz eine mächtige Waffe stärken kann.",h="An der Beschwörungsstätte wartet Cyclonian auf einen Champion, der kühn genug ist, sich ihm zu stellen.",kw={"champion","cyclonian","elementar","beschwörung","wirbelherz","windlord"},ang={["class:Warrior"]="Als Krieger stellt Ihr mit einem Sieg über Cyclonian Eure Stärke und Eure Kampfkunst auf die Probe. Nehmt sein Wirbelherz an Euch und schmiedet damit eine mächtige Waffe."},sec={{t="Der schlummernde Windlord",b="Seit Zeitaltern hält ein Beobachter an der Beschwörungsstätte Wache. Der tobende elementare Windlord erwartet einen Kämpfer mit genug roher kriegerischer Kraft, um ihn herauszufordern und zu vernichten."},{t="Den Sturm beschwören",b="Ein besonderes Pergament nennt die seltenen Materialien, die nötig sind, um Cyclonian zu beschwören. Sobald der Windlord herbeigerufen ist, stellt Ihr Euch ihm im direkten Kampf. Ihr könnt ihn besiegen oder seinem heulenden Sturm erliegen."},{t="Das Wirbelherz",b="Cyclonians Wirbelherz ist die begehrte Beute des besiegten Elementars. Von ihm abgetrennt, können seine wilden Elementarenergien gebunden und in eine Waffe eingeflößt werden, die eines vollendeten Champions würdig ist."}},faq={{q="Wer ist Cyclonian?",a="Cyclonian ist ein mächtiger elementarer Windlord und eine ernste Bedrohung. Seit Zeitaltern beobachten ihn Wächter und warten auf einen Champion, der stark genug ist, ihn herauszufordern und zu besiegen.",al={"wer ist cyclonian","cyclonians geschichte","was ist cyclonian"}},{q="Warum muss Cyclonian beschworen werden?",a="Cyclonian wird beschworen, damit ein würdiger Champion ihn herausfordern und erschlagen kann. Der Sieger kann sein Wirbelherz an sich nehmen und dessen Macht in eine mächtige Waffe einfließen lassen.",al={"warum cyclonian beschwören","cyclonians zweck","warum cyclonian bekämpfen"}},{q="Was ist das Wirbelherz?",a="Das Wirbelherz ist Cyclonians innerste Essenz. Dem besiegten Windlord entrissen, können seine stürmischen Energien in eine Waffe von großer kriegerischer Macht eingeflößt werden.",al={"was ist das wirbelherz","cyclonians herz","zweck des wirbelherzens"}},{q="Wer hat Cyclonian beobachtet?",a="Bath'rah der Windbehüter im Alteracgebirge hält seit Zeitaltern Wache über die Stätte. Unablässig sucht er nach einem wahren Champion, der Cyclonian bezwingen und sein stürmisches Herz meistern kann.",al={"wer will cyclonians tod","wer beobachtet cyclonian"}},{q="Wie wird Cyclonian herbeigerufen?",a="Ein besonderes Pergament verzeichnet die seltenen Reagenzien, die nötig sind, um Cyclonian zu beschwören und den Windlord in die Welt zu ziehen, damit er herausgefordert werden kann.",al={"wie cyclonian beschwören","cyclonians zutaten"}},{q="Welche Waffe wird aus Cyclonian geschmiedet?",a="Der Champion, der die nötigen Komponenten sammelt, Cyclonian beschwört und ihn erschlägt, verdient sich eine Waffe, erfüllt vom schlummernden Zorn des Wirbelherzens dieses Elementars.",al={"cyclonians belohnung","welche waffe von cyclonian"}}},fp="9,217,24.165.0,21.188.0,19.187.1,17.166.0,31.164.0,28.160.0,32.189.0,31.128.0,37.163.0"}
P.entries["quest:1713"] = {n="Die Beschwörung",s="In Bath'rah Windwatchers Lager stellt sich ein Krieger einer Prüfung gegen Cyclonian, den Windlord. Erschlagt den Elementar und erringt das Wirbelherz, dessen Sturmkraft in eine Waffe gebunden werden kann.",h="In Bath'rah Windwatchers Lager stellt sich ein Krieger einer Prüfung gegen Cyclonian, den Windlord.",kw={"bath'rah windwatcher","bathrah","cyclonian","elementar","die beschwörung","kriegerquest","wirbelherz","windlord"},ang={["class:Warrior"]="Als Krieger stellt Ihr Euch einer Bewährungsprobe, wenn Ihr Cyclonian entgegentretet und das Wirbelherz erringt. Sie bringt Euch eine Waffe ein, die von der rohen Macht des Sturms durchdrungen ist.",["race:Troll"]="Als Troll wisst Ihr, dass Bath'rah Windwatchers urtümliche Künste weit über die Zivilisation hinausreichen. Seine Herrschaft über Windelementare spiegelt die tiefen mystischen Traditionen der Trollschamanen und Hexendoktoren wider."},sec={{t="Den Sturm herbeirufen",b="Bath'rah Windwatcher hat ein uraltes Ritual vorbereitet, um Cyclonian in das Reich der Sterblichen zu beschwören. Der furchterregende Elementar ist als Windlord bekannt. Mit dem Sturm wird nicht verhandelt. Ein fähiger Champion muss ihn niederstrecken, sobald er Gestalt annimmt."},{t="Das Herz des Sturms",b="Cyclonians Wirbelherz erhält seine körperliche Gestalt aufrecht. Wenn der Windlord fällt, reißt Bath'rah das Herz heraus und macht sich den Sturm darin zunutze. Seine unbeständige Macht kann eine Waffe mit der Kraft des Sturms erfüllen."}},faq={{q="Wer ist Cyclonian?",a="Cyclonian ist ein mächtiger Elementar, der als Windlord bekannt ist. Bath'rah Windwatchers Ritual ruft ihn als gewaltigen Sturm herbei, und er muss besiegt werden, um die in seinem Kern versiegelte Essenz zu erlangen.",al={"wer ist cyclonian","was ist cyclonian","cyclonians geschichte"}},{q="Was ist das Wirbelherz?",a="Das Wirbelherz ist Cyclonians elementarer Kern. Bath'rah Windwatcher braucht es, um die wirbelnde, zerstörerische Macht des Windlords in eine Waffe zu binden.",al={"was ist das wirbelherz","warum wird das wirbelherz benötigt","verwendung des wirbelherzens"}},{q="Wer ist Bath'rah Windwatcher?",a="Bath'rah Windwatcher ist ein Trollmystiker, der in der Wildnis lebt und weiß, wie man Cyclonian beschwört. Er führt Krieger durch das Ritual und nutzt dann das Herz des gefallenen Elementars, um mächtige Waffen zu schmieden.",al={"wer ist bathrah","bathrah windwatcher","questgeber die beschwörung"}},{q="Warum wird Cyclonian beschworen?",a="Cyclonian wird beschworen, damit ein Krieger sich dem Windlord stellen, ihn erschlagen und dann sein elementares Herz erringen kann. Dessen Macht kann in eine Waffe gebunden werden.",al={"warum cyclonian beschwören","zweck der beschwörung","grund für die beschwörung"}},{q="Was geschieht, nachdem Cyclonian besiegt wurde?",a="Nachdem Cyclonian gefallen ist, kann Bath'rah die elementare Macht in dessen Wirbelherz nutzen, um eine Waffe mit Cyclonians Sturmmagie zu stärken.",al={"was geschieht nach dem sieg über cyclonian","geschichte von cyclonians belohnung","nach der beschwörung"}},{q="Wo findet die Beschwörung statt?",a="Das Ritual findet in Bath'rah Windwatchers Lager statt. Dort sammelt der Mystiker die urtümliche Kraft, die nötig ist, um Cyclonian aus dem Elementarreich in die körperliche Welt zu ziehen.",al={"wo findet das ritual statt","ort der beschwörung"}}},fp="13,185,19.250.0,22.212.0,17.189.0,28.147.0,28.204.0,32.137.0,41.135.0,36.172.0"}
P.entries["quest:1714"] = {n="Essenz der Verbannung",s="Am Kessel lockt Essenz der Verbannung Reisende mit seinen Dämpfen an. Talismane lösen eine heftige Reaktion aus, die geschmolzenes Gestein zum Vorschein bringt.",h="Am Kessel lockt Essenz der Verbannung Reisende mit seinen Dämpfen an.",kw={"blase","kessel","talismane","essenz der verbannung","geschmolzenes gestein","transmutation","dämpfe"},ang={["class:Mage"]="Alchemistische Kessel und elementare Transmutationen können getrennte Essenzen durch unbeständige Magie zu einer festen Form verbinden.",["class:Shaman"]="Selbst wenn blubbernde Kessel geschmolzenes Gestein umwälzen, erfordert die Arbeit mit elementaren Essenzen ein Verständnis der wirkenden Urkräfte."},sec={{t="Ein lockender Kessel",b="Ein blubbernder Kessel verströmt Dämpfe, die Reisende zu seinen brodelnden Tiefen locken. Bestimmte verzauberte Talismane lösen eine heftige Reaktion im Gefäß aus."},{t="Der glühende Schmelztiegel",b="Die Talismane sinken langsam durch die Flüssigkeit. Dann steigt eine große Blase auf und zerplatzt, wodurch ein brodelnder Klumpen geschmolzenen Gesteins zum Vorschein kommt, der aus den vereinten Materialien geschmiedet wurde."}},faq={{q="Was ist Essenz der Verbannung?",a="Essenz der Verbannung ist ein Transmutationsritual, das an einem blubbernden Kessel vollzogen wird. Talismane lösen eine heftige Reaktion aus, die einen brodelnden Klumpen geschmolzenen Gesteins hervorbringt.",al={"was ist essenz der verbannung","essenz der verbannung quest"}},{q="Was geschieht, wenn Talismane in den Kessel gelegt werden?",a="Die Dämpfe des Kessels locken Reisende näher. Talismane sinken zu Boden, dann zerplatzt eine große Blase an der Oberfläche und hinterlässt geschmolzenes Gestein.",al={"was geschieht am kessel","wie funktioniert der kessel"}},{q="Was bringt der Kessel hervor?",a="Wenn eine große Blase an der Oberfläche zerplatzt, kommt im Kessel ein brodelnder Klumpen geschmolzenen Gesteins zum Vorschein.",al={"was bringt der kessel hervor","was erhält man bei essenz der verbannung"}},{q="Wo befindet sich der Kessel für dieses Ritual?",a="Das Ritual findet an einem kochenden Kessel statt, dessen heiße Dämpfe Reisende anlocken. Dort verwandelt das Gefäß seinen Inhalt.",al={"standort des kessels","wo ist der kessel zu finden"}},{q="Warum werden Talismane in den Kessel gelegt?",a="Die Talismane werden in den Tiefen des Kessels als Reagenzien verbraucht. Ihre Anwesenheit in der erhitzten Flüssigkeit trägt zur Bildung des geschmolzenen Gesteins bei.",al={"wozu dienen die talismane","warum kommen talismane in den kessel"}},{q="Warum blubbert der Kessel unablässig?",a="Die blubbernde Flüssigkeit und die lockenden Dämpfe zeugen von einer aktiven Reaktion im Gefäß. Es ist bereit, alles zu verwandeln, was in seine Tiefen gelangt.",al={"warum blubbert es","was sind die dämpfe"}}},fp="20,140,20.150.0,19.157.0,33.158.0,52.144.0,31.106.0,43.122.0,40.125.0,40.136.0"}
P.entries["quest:1715"] = {n="Zum Geschlachteten Lamm",s="Gnomhexenmeister aus Eisenschmiede suchen ihre Ausbildung nun in Sturmwind. „Zum Geschlachteten Lamm“ bietet ihnen einen Ort, um von Menschenhexenmeistern zu lernen, während König Magni Bronzebart daheim über die Anwender dunkler Künste wacht.",h="Gnomhexenmeister aus Eisenschmiede suchen ihre Ausbildung nun in Sturmwind.",kw={"gakin der dunkelbinder","gnomeregan","eisenschmiede","lago blackwrench","das magierviertel","slaughtered lamb","sturmwind","hexenmeister"},ang={["class:Warlock"]="Junge Hexenmeister der Allianz führt die Reise in ein verborgenes Netzwerk von Anwendern über die Grenzen der Völker hinweg.",["race:Dwarf"]="Eisenschmiedes Behörden überwachen die Ausübung dämonischer Künste genau. Zwergenhexenmeister halten sich im Schatten und schicken ihre Schüler andernorts hin.",["race:Gnome"]="Im Exil drängen sich die Gnome in Eisenschmiede und sind auf die Gastfreundschaft der Menschen angewiesen, nachdem sie ihre Akademien in Gnomeregan verloren haben."},sec={{t="Exil und Überwachung",b="Bevor Gnomeregan fiel, lernten angehende Hexenmeister aus Khaz Modan bei Tüftler-Magiern und Gelehrten des Dämonischen in der Technostadt. Dann zerschlug die Katastrophe diese Schulen und trieb die Gnome ins Exil. Die Überlebenden drängten sich in Eisenschmiedes unterirdischen Höhlen, wo König Magni Bronzebart und die Zwergenwache sie beobachten. Sie können weder offen dämonische Künste ausüben noch gefährliche Rituale vollziehen, weshalb erfahrene Ausbilder wie Lago Blackwrench ihre Schüler fortschicken."},{t="Der geheime Keller im Magierviertel",b="Von Eisenschmiede reisen Gnomenschüler nach Süden zum Geschlachteten Lamm im Magierviertel von Sturmwind. Gewundene Steingänge und Treppen führen von der Schankstube der Taverne hinab zu einem verborgenen Sanktum, in dem sich Menschenhexenmeister versammeln. Gakin der Dunkelbinder beaufsichtigt sie dort. In seinen schattigen Räumen können Ausbilder Novizen lehren, niedere Dämonen zu beschwören und zu binden, ohne sofort den Zorn der städtischen Marschälle auf sich zu ziehen."},{t="Wachsende Spannungen im Schatten",b="Sturmwinds Zirkel heißt fähige Hände willkommen, doch geflüchtete Novizen bringen neue Spannungen mit sich. Die menschlichen Lehrmeister riskieren bereits, von den Paladinen und Behörden der Stadt entdeckt zu werden. Während weitere Anwender aus Khaz Modan eintreffen, stellen Gakin und seine Kollegen fest, dass ihr Zufluchtsort immer voller wird. Der stetige Zustrom aus dem Zwergenberg könnte ihre geheime Zusammenkunft aufdecken. Doch weder die Gnome noch die Menschenhexenmeister haben eine leichtere Wahl."}},faq={{q="Warum können Gnomhexenmeister nicht in Eisenschmiede lernen?",a="König Magni Bronzebart beobachtet Hexenmeister in Eisenschmiede genau. Seit Gnomeregan gefallen ist, haben die vertriebenen Anwender keine eigene Akademie mehr, und beim Beschwören von Dämonen im Zwergenberg droht ihnen die Entdeckung.",al={"warum nach sturmwind schicken","hexenmeisterausbildung eisenschmiede","warum hexenmeister gnomeregan verlassen"}},{q="Wo wurden Hexenmeister aus Khaz Modan früher ausgebildet?",a="Bevor Gnomeregan fiel, lernten Hexenmeister aus Khaz Modan bei Tüftler-Magiern und Gelehrten des Dämonischen in der Technostadt. Die Katastrophe zerschlug diese Schulen und trieb die Überlebenden ins Exil.",al={"hexenmeistergeschichte gnomeregan","frühere hexenmeisterausbildung khaz modan"}},{q="Wer ist Gakin der Dunkelbinder?",a="Gakin der Dunkelbinder ist ein Menschenhexenmeister, der das verborgene Sanktum unter dem Slaughtered Lamb in Sturmwind beaufsichtigt. Er lehrt Schüler, darunter Gnomennovizen aus Eisenschmiede, Dämonen zu beschwören und zu binden.",al={"wer ist gakin","gakins rolle"}},{q="Was ist das „Zum Geschlachteten Lamm“?",a="„Zum Geschlachteten Lamm“ ist eine Taverne im Magierviertel von Sturmwind. Ihr Keller verbirgt einen Versammlungsort für Hexenmeister, fernab der Blicke der städtischen Behörden.",al={"slaughtered lamb taverne","wo ist slaughtered lamb"}},{q="Warum ist Gakin über die Neuankömmlinge verärgert?",a="Gakin fürchtet, dass ein Zustrom geflüchteter Gnome die Aufmerksamkeit auf Sturmwinds verborgenen Zirkel lenken wird. Platz und Lehrkräfte sind begrenzt, und zu viel Hexenmeisterei könnte sie vor den Behörden entlarven.",al={"gakin beschwert sich","warum ist gakin wütend"}},{q="Wer ist Lago Blackwrench?",a="Lago Blackwrench ist ein Hexenmeisterlehrer der Gnome, der in Eisenschmiedes dunklen Gassen lebt. Er schickt vielversprechende Novizen nach Sturmwind, damit sie ihre Ausbildung fortsetzen.",al={"lago blackwrench","questgeber slaughtered lamb"}}},fx={["2a96a15b"]={q="Warum schickt Euch Lago Blackwrench nach Sturmwind?",a="Lago Blackwrench hat keine andere Wahl, wenn Ihr in Euren dämonischen Künsten vorankommen wollt. Seit der Fall von Gnomeregan die gnomischen Praktizierenden nach Eisenschmiede trieb, behält König Magni Bronzebart die dunkle Magie in seiner Bergfestung wachsam und misstrauisch im Auge. Da sie unter der Überwachung der Zwerge keine eigenen Ausbildungssanktuarien betreiben können, sind die in Eisenschmiede exilierten Hexenmeister gezwungen, ihren Stolz herunterzuschlucken und vielversprechende Novizen zu menschlichen Lehrmeistern in den Süden zu entsenden.",al={"warum nach sturmwind schicken","blackwrench beweggrund","warum zum geschlachteten lamm gehen"}}},fp="20,211,18.450.0,32.393.0,29.416.0,44.195.0,46.178.0,28.205.0,29.146.0,43.193.0,24.149.0"}
P.entries["quest:1716"] = {n="Verschlinger der Seelen",s="In Sturmwind schickt Gakin Hexenmeister übers Meer, um Rat zur Beschwörung eines Sukkubus einzuholen. Takar der Seher besitzt das Wissen, das sie brauchen.",h="In Sturmwind schickt Gakin Hexenmeister übers Meer, um Rat zur Beschwörung eines Sukkubus einzuholen.",kw={"camp taurajo","gakin der dunkelbinder","herzholz","slaughtered lamb","sturmwind","sukkubus","takar der seher","brachland","hexenmeisterquest"},ang={["class:Warlock"]="Als Hexenmeister bringt Euch die Bindung eines Sukkubus der Beherrschung von Geistesmanipulation und Verführungsmagie näher. Exotische Ritualreagenzien zu erreichen, erfordert körperlichen Wagemut.",["faction:Alliance"]="Als Zauberwirker der Allianz reist Ihr über das Meer und quer durch den Kontinent tief in umkämpfte Gebiete der Horde."},sec={{t="Eine gefährliche Reise gen Westen",b="Unter dem Slaughtered Lamb im Magierviertel von Sturmwind leitet Gakin der Dunkelbinder vielversprechende Hexenmeister bei der Beschwörung eines Sukkubus an. Der Dämon verschlingt Seelen, zerstört Herzen und beherrscht den Geist, also sollte kein Hexenmeister einen solchen blindlings nach Azeroth rufen. Ein mächtiger Köder ist nötig: ein Gegenstand, der mit reiner Liebe verbunden ist. Dieses Zeichen lockt den Sukkubus aus dem Wirbelnden Nether hervor, damit der Hexenmeister ihn besiegen und binden kann. Sturmwinds Zirkel können nicht lehren, wo ein solcher Gegenstand zu finden ist."},{t="Der Seher im Feindesland",b="Gakin schickt seine Schüler über das große Meer nach Kalimdor, um den nötigen Katalysator zu beschaffen. Takar der Seher wartet im trockenen Brachland, nahe der Hordensiedlung Camp Taurajo. Ein Hexenmeister der Allianz muss eine Wildnis durchqueren, in der feindliche Zentauren, Borstennacken und Krieger der Horde patrouillieren, um ihn zu erreichen. Die Reise prüft, ob ein Beschwörer überleben kann, noch bevor das Ritual beginnt."}},faq={{q="Was ist der Zweck dieser Quest?",a="Ihr reist von Sturmwind nach Kalimdor, um zu lernen, wie Ihr einen Sukkubus beschwört und bindet, der Eurem uneingeschränkten Befehl untersteht.",al={"warum verschlinger der seelen abschließen","ziel der sukkubusquest","sukkubusquestreihe für hexenmeister"}},{q="Warum muss ich den ganzen Weg ins Brachland reisen?",a="Gakin der Dunkelbinder schickt Euch ins Brachland, weil Takar der Seher das nötige okkulte Wissen besitzt, um ein Symbol reiner Liebe zu finden, den Köder für die Beschwörung eines Sukkubus.",al={"warum kalimdor","warum ins brachland reisen","warum so weit geschickt werden"}},{q="Wer ist Gakin der Dunkelbinder?",a="Gakin der Dunkelbinder ist ein Meisterbeschwörer, der in den Katakomben unter dem Slaughtered Lamb in Sturmwind wirkt. Er lehrt angehende Hexenmeister dämonische Pakte, Bindungen und die dunklen Künste, fernab der Blicke der Stadtwache.",al={"geschichte von gakin dem dunkelbinder","wer vergibt die quest verschlinger der seelen"}},{q="Wer ist Takar der Seher?",a="Takar der Seher ist ein Mystiker, der im zentralen Brachland lebt, gleich außerhalb des Taurenaußenpostens Camp Taurajo. Er weist reisenden Hexenmeistern den Weg zu Relikten, die Dämonen nach Azeroth locken können.",al={"wo ist takar der seher","geschichte von takar dem seher"}},{q="Warum braucht die Beschwörung eines Sukkubus ein Symbol der Liebe?",a="Ein Sukkubus wird von echter, reiner Zuneigung angezogen und verschlingt sie. Der Dämon verdirbt Herzen und beherrscht den Geist, daher kann ein Relikt romantischer Liebe ihn aus dem Wirbelnden Nether locken.",al={"warum liebe für einen sukkubus","hintergrund zum sukkubusköder","köder für einen sukkubus"}},{q="Ist das Brachland für einen Charakter der Allianz sicher?",a="Nein. Das Brachland ist Gebiet der Horde, mit feindlichen Bestien, Borstennackenstämmen und Siedlungen wie Camp Taurajo. Verhaltet Euch unauffällig und meidet Wachen, während Ihr nach Takar sucht.",al={"ist das brachland gefährlich","greift die horde im brachland an"}}},fx={["25fde1fe"]={q="Warum möchte Gakin der Dunkelbinder, dass dies erledigt wird?",a="Gakin der Dunkelbinder bildet Euch darin aus, gefährlichere dämonische Wesen Eurem Willen zu unterwerfen. Um Eure Meisterschaft als Hexenmeister voranzubringen, verlangt er von Euch, eine Sukkubus zu beschwören, zu bezwingen und zu binden – ein grausamer Devourer of Souls und Bezwinger der Geister. Da ein solches Wesen ohne einen starken emotionalen Köder nicht durch den Wirbelnden Nether gelockt werden kann, schickt Gakin Euch auf diesen langen Weg, um den rituellen Köder vorzubereiten, der notwendig ist, um die Kreatur Eurem Dienst zu unterwerfen.",al={"warum schickt mich gakin","gakin motiv devourer of souls","warum sukkubus beschwören gakin"}}},fp="17,129,24.466.0,29.355.0,34.109.0,47.173.0,28.216.0,22.188.0,55.167.0,46.168.0"}
P.entries["quest:1717"] = {n="Gakins Beschwörung",s="Gakins Beschwörung schickt vielversprechende Hexenmeister der Allianz von Eisenschmiede nach Süden nach Sturmwind. Unter dem Magierviertel wartet Gakin der Dunkelbinder, um ihre Fortschritte beim Befehligen mächtigerer Unholde zu überwachen.",h="Gakins Beschwörung schickt vielversprechende Hexenmeister der Allianz von Eisenschmiede nach Süden nach...",kw={"gakin","gakins beschwörung","eisenschmiede","lago blackwrench","das magierviertel","slaughtered lamb","sukkubus","hexenmeister"},ang={["class:Warlock"]="Als Hexenmeister werdet Ihr von Eisenschmiede zurück nach Sturmwind geschickt, um das mehrteilige Ritual zu beginnen, das Eure Sukkubusdienerin bindet.",["faction:Alliance"]="Als Mitglied der Allianz seht Ihr, wie das geheime Netzwerk der Hexenmeister über die Hauptstädte hinweg in Kontakt bleibt, während Dämonologie vor den Augen der Zivilbevölkerung verborgen bleibt.",["race:Gnome"]="Als Gnomenhexenmeister in der Ausbildung bei Lago Blackwrench in Eisenschmiede werdet Ihr zum Untergrundnetzwerk von Sturmwind geschickt, um tiefergehende dämonische Lehren zu erhalten."},sec={{t="Eine Botschaft aus dem Untergrund",b="Dämonologie bleibt in den Ländern der Allianz im Verborgenen. In Eisenschmiede behält Lago Blackwrench für die Bruderschaft in Sturmwind unauffällig umherreisende Praktizierende im Auge. Wenn ein Hexenmeister seine ersten Diener beherrscht, spricht sich das schnell herum. Lago überbringt die Anweisung, die verschneiten Berge von Khaz Modan zu verlassen und sich unverzüglich im Süden zu melden."},{t="Rückkehr zum Slaughtered Lamb",b="Unter dem Slaughtered Lamb im Magierviertel von Sturmwind koordiniert Gakin der Dunkelbinder die Hexenmeister der Stadt. Er betrachtet jeden fähigen Schüler als wertvolle, aber riskante Investition. Seine Vorladung markiert die Schwelle zum wahren Binden von Dämonen. Nun beginnen die Prüfungen, um eine Sukkubus aus dem Wirbelnden Nether zu unterwerfen."}},faq={{q="Wer schickt mir diese Vorladung?",a="Lago Blackwrench, ein Hexenmeisterlehrer in Eisenschmiede, überbringt die Vorladung im Auftrag von Gakin dem Dunkelbinder, der die Unterweisung in Dämonologie in Sturmwind leitet.",al={"wer vergibt die quest","wer beginnt dies","lago blackwrench"}},{q="Wo finde ich Gakin den Dunkelbinder?",a="Gakin der Dunkelbinder lebt in den dunklen, verwinkelten Katakomben unter dem Slaughtered Lamb, einer Taverne im Magierviertel von Sturmwind.",al={"gakins standort","wo ist gakin","slaughtered lamb standort"}},{q="Warum lässt Gakin mich rufen?",a="Ihr seid in Eurer Kunst weit genug fortgeschritten, um die Rituale zur Beschwörung und Unterwerfung einer Sukkubus durchzuführen und Euer dämonisches Arsenal zu erweitern.",al={"zweck der quest","wozu dient das","warum gerufen"}},{q="Was geschieht, nachdem ich mit Gakin gesprochen habe?",a="Nachdem Ihr mit Gakin gesprochen habt, schickt er Euch auf die Quest Devourer of Souls. Ihr werdet in gefährliche Länder reisen, um die Ritualkomponenten zu sammeln, die zur Beschwörung und Bindung einer Sukkubus benötigt werden.",al={"nächster schritt","was folgt danach","questreihe"}},{q="Warum nimmt ein Hexenmeister in Eisenschmiede Befehle aus Sturmwind entgegen?",a="Die Hexenmeister der Allianz unterhalten aus Notwendigkeit ein diskretes Netzwerk. Praktizierende in Eisenschmiede und Sturmwind bleiben in Kontakt und schicken vielversprechende Lehrlinge zu Gakin, der unter dem Slaughtered Lamb über spezielle Ritualausrüstung und Wissen verfügt.",al={"hexenmeister in eisenschmiede","gnomenhexenmeister in sturmwind","organisation der hexenmeister"}},{q="Kann ich diese Vorladung ignorieren, wenn ich in Khaz Modan bleiben möchte?",a="Ihr könnt Euren Besuch in Sturmwind aufschieben, doch um die Beschwörung einer Sukkubus zu erlernen, müsst Ihr Gakins Prüfung bestehen. Die Reise ist für jeden aufstrebenden Hexenmeister unerlässlich.",al={"ist das erforderlich","lässt sich das überspringen","ist die reise nach sturmwind nötig"}}},fx={["27281f2a"]={q="Warum schickt Euch Lago Blackwrench nach Sturmwind?",a="Lago Blackwrench hat von seinen Kollegen in Sturmwind die ausdrückliche Anweisung, nach vielversprechenden Hexenmeistern Ausschau zu halten, die durch Eisenschmiede reisen. Der Zirkel hat bereits beträchtliche Zeit und Ressourcen in Eure dunklen Künste investiert, und Lago möchte sicherstellen, dass Ihr nicht vom Pfad abkommt oder umkommt, bevor Ihr Euer Handwerk unter der Anleitung von Gakin der Dunkelbinder weiterentwickeln könnt.",al={"warum will lago, dass dies erledigt wird","lago blackwrench motiv","warum schickt lago mich nach sturmwind"}}},fp="15,195,30.308.0,30.309.0,26.152.0,37.125.0,26.137.0,36.168.0,59.232.0,58.158.0"}
P.entries["quest:1718"] = {n="Der Inselbewohner",s="Auf Prügel-Eiland stellen sich Krieger aus ganz Azeroth einer Prüfung unter ihresgleichen. Ihre Lehrer schicken bewährte Kämpfer dorthin, damit sie den nächsten Schritt ihrer Ausbildung machen. Die Insel liegt vor der Händlerküste, wo der oberste Krieger Klannoc Macleod sie erwartet.",h="Auf Prügel-Eiland stellen sich Krieger aus ganz Azeroth einer Prüfung unter ihresgleichen.",kw={"prügel-eiland","klannoc macleod","die händlerküste","ratschet","the affray","brachland","der inselbewohner","krieger"},ang={["class:Warrior"]="Als Krieger führt Euer Weg von grundlegenden Manövern zur vollen Wildheit und taktischen Vielseitigkeit der Haltungen erfahrener Kämpfer.",["faction:Alliance"]="Als Krieger der Allianz überquert Ihr das Meer oder durchstreift Kalimdors Wildnis, um Prügel-Eiland zu erreichen. Dort zeigt Ihr Eure Hingabe an die Kampfkunst in einem rauen Grenzgebiet fern der Hochburgen von Menschen und Zwergen.",["faction:Horde"]="Als Krieger der Horde reist Ihr von Donnerfels oder Orgrimmar ins Brachland. Dort beweist Ihr Eure Stärke fern der wachsamen Augen Eurer Häuptlinge."},sec={{t="Eine Zusammenkunft der Klingen",b="Kriegerlehrer in den Hauptstädten der Allianz und der Horde schicken Schüler, die den Grundübungen entwachsen sind, um sich mit ihresgleichen zu messen. Der Kampf zeigt den Fortschritt eines Kämpfers, nicht Rang oder Loyalität. So führt die Reise über die Übungsplätze der Zivilisation hinaus zu einem zerklüfteten Eiland im großen Meer."},{t="Prügel-Eiland und die Händlerküste",b="Prügel-Eiland liegt östlich der Händlerküste, knapp südlich von Ratschet im Brachland. Ihr könnt durch das seichte Wasser über versunkenen Sandbänken dorthin schwimmen. Politische Bindungen zählen auf der Insel wenig. Kämpfer versammeln sich vor Klannoc Macleod, dem obersten Krieger der Insel, und erwarten die Prüfung, die er auswählt."}},faq={{q="Was ist Prügel-Eiland?",a="Prügel-Eiland ist eine Felseninsel vor der Händlerküste des Brachlands, südlich von Ratschet. Krieger aus ganz Azeroth versammeln sich dort, um ihre Kampfkunst zu verfeinern, sich in Zweikämpfen zu üben und fern staatlicher Obrigkeit Kampfprüfungen zu bestehen.",al={"wo liegt prügel-eiland","prügel-eiland hintergrundgeschichte","fray isle"}},{q="Wer ist Klannoc Macleod?",a="Klannoc Macleod ist der oberste Krieger von Prügel-Eiland. Er beurteilt jene, die die Reise auf sich nehmen, und entscheidet, ob ihr Kampfgeist und ihr Können weitere Anleitung auf dem Weg des Kriegers verdienen.",al={"wer ist klannoc","klannoc macleod rolle","macleod krieger"}},{q="Warum schicken Lehrer sowohl der Horde als auch der Allianz Krieger hierher?",a="Lehrer sowohl der Horde als auch der Allianz schicken Krieger, um deren Kampfkunst im Gefecht zu prüfen. Lehrer in Orgrimmar, Sturmwind, Donnerfels und Eisenschmiede erkennen Prügel-Eiland als Bewährungsstätte für Krieger an, die seine Herausforderungen überleben können.",al={"warum kommen beide fraktionen hierher","ist prügel-eiland neutral","horde und allianz prügel-eiland"}},{q="Wie erreicht Ihr Prügel-Eiland vom Festland aus?",a="Reist von Ratschet im Brachland aus entlang der Händlerküste nach Süden. Schwimmt vom Ufer aus nach Osten durch das seichte Wasser über den Sandbänken auf Prügel-Eiland zu.",al={"wie gelangt man nach prügel-eiland","prügel-eiland wegbeschreibung","prügel-eiland finden"}},{q="Was geschieht nach der Begegnung mit Klannoc Macleod?",a="Nachdem Klannoc Macleod Eure Anreise bestätigt und Eure Entschlossenheit abgewogen hat, lädt er Euch zu The Affray ein. Diese Prüfung stellt Eure Ausdauer gegen Wellen von Herausforderern auf die Probe.",al={"was folgt auf der inselbewohner","klannoc macleod nächste quest"}}},fx={b7452d18={q="Warum schicken die Kriegerausbilder Euch zum Prügel-Eiland?",a="Eure Ausbildung in den Städten hat Euch so weit gebracht, wie es mit Standardübungen möglich ist. Während Euer Ruhm wächst, wissen Eure Mentoren, dass wahre Kampfbeherrschung nicht an Trainingsattrappen oder durch freundschaftliches Sparring erlernt werden kann. Sie schicken Euch zu Klannoc Macleod, damit Ihr Eure Stärke an echten Gleichgesinnten aus der ganzen Welt messen könnt, um zu testen, ob Ihr wirklich würdig seid, auf dem Pfad des Kriegers voranzuschreiten.",al={"warum zum prügel-eiland schicken","ausbilder motiv prügel-eiland","warum will der ausbilder, dass ich gehe"}}},fp="12,244,21.276.0,34.293.0,20.200.0,23.178.0,64.244.0,47.136.0,43.163.1"}
P.entries["quest:1719"] = {n="Der Ringkampf",s="Auf Prügel-Eiland stellen sich Krieger Herausforderern, bevor Klannoc Macleod sie ausbildet. Der Ringkampf prüft ihre Stärke gegen die Kämpfer der Insel und deren Champion.",h="Auf Prügel-Eiland stellen sich Krieger Herausforderern, bevor Klannoc Macleod sie ausbildet.",kw={"ringkampf","brachland","big will","prügel-eiland","klannoc macleod","twiggy flathead","kriegerprüfung"},ang={["class:Warrior"]="Als Krieger stellt Ihr Euch dem Ringkampf, um Eure Kampfhaltungen und Eure Ausdauer unter Beweis zu stellen. Beweist dort Euren Wert, und Klannoc Macleod wird in Betracht ziehen, Euch zu tieferer Meisterschaft Eures Handwerks zu führen."},sec={{t="Ein Prüfplatz im großen Meer",b="Prügel-Eiland liegt abseits des Festlands und zieht Raufbolde, Ausgestoßene und Kampfausbilder an. Klannoc Macleod bildet nicht jeden Wanderer aus, der mit dem Boot ankommt. Krieger, die seine Unterweisung suchen, müssen zuerst am Ringkampf teilnehmen. Dort zeigen ihre Ausdauer und ihr Gespür im Kampf, ob hinter ihren Prahlereien auch Kampfgeschick steckt."},{t="Der Kreis aus Eisen und Blut",b="Ein Krieger beginnt den Ringkampf, indem er auf das zentrale Eisengitter inmitten der Zuschauer tritt. Dann schickt Ringmeister Twiggy Flathead einen Herausforderer nach dem anderen in den Ring. Wer überlebt, tritt gegen den Schwergewichtschampion der Insel an, Big Will. Nur wer ihn besiegt, kann sich Klannocs Respekt verdienen."}},faq={{q="Was ist der Ringkampf?",a="Der Ringkampf prüft angehende Krieger in einer Reihe von Arenakämpfen auf Prügel-Eiland. Klannoc Macleod beurteilt, ob sie für eine fortgeschrittene Kampfausbildung bereit sind.",al={"ringkampfprüfung","was ist der ringkampf","prügel-eiland arena"}},{q="Wo findet der Ringkampf statt?",a="Der Ringkampf findet auf Prügel-Eiland statt, vor der Ostküste des Brachlands im großen Meer.",al={"wo ist der ringkampf","ringkampf ort"}},{q="Wer organisiert die Prüfung?",a="Kriegerlehrer Klannoc Macleod beaufsichtigt die Kämpfer der Insel und legt die Prüfung fest. Twiggy Flathead leitet die Kämpfe vom Rand der Grube aus.",al={"wer leitet den ringkampf","ringkampf veranstalter"}},{q="Wie läuft der Kampf im Ring ab?",a="Ein Krieger tritt auf das zentrale Eisengitter, um seine Bereitschaft zu signalisieren. Twiggy Flathead schickt Inselforderer in Wellen in die Grube und lässt dann den Inselchampion Big Will antreten.",al={"wie läuft der kampf ab","ringkampf wellen","ringkampf beginnen"}},{q="Wer ist Big Will?",a="Big Will ist der amtierende Champion der Raufbolde von Prügel-Eiland. Ihn zu besiegen ist die letzte Voraussetzung, um den Ringkampf zu bestehen.",al={"big will","wer ist big will","prügel-eiland champion"}},{q="Warum müssen Krieger diese Prüfung bestehen?",a="Klannoc Macleod lehrt seine Kampftechniken erst, wenn ein Krieger seine Zähigkeit gegen mehrere Gegner bewiesen hat.",al={"warum am ringkampf teilnehmen","ringkampf zweck"}}},fx={["0df51000"]={q="Warum verlangt Klannoc Macleod von Euch zu kämpfen, anstatt Euch selbst zu testen?",a="Klannoc Macleod verschwendet seine fortgeschrittene Kampfanweisung nicht an jeden prahlerischen Raufbold, der zum Prügel-Eiland segelt. The Affray existiert speziell als Ausdauerprüfung für aufstrebende Krieger. Indem er Euch in die Grube gegen Wellen erfahrener Herausforderer und den Champion Big Will wirft, kann Klannoc aus der Ferne zusehen und Euren Mut, Eure Gegnerkontrolle und Eure Ausdauer unter echtem Druck beurteilen, bevor er Euch als Schüler annimmt.",al={"warum ich klannoc","warum testet klannoc mich","warum the affray kämpfen"}}},fp="10,163,33.314.0,28.304.0,19.154.0,33.89.0,24.144.0,37.173.0,16.121.0,38.120.0"}
P.entries["quest:173"] = {n="Worgen in den Wäldern",s="In Dunkelhain schickt Calor Jäger gegen Nachtbann-Schattenweber im Dämmerwald aus. Der desillusionierte ehemalige Wachmann ist in der Stadt stationiert, und die Jagd führt durch den Schattenhain und den Verrottenden Obstgarten. Wer sich den Worgen stellt, beweist sich vor den Monsterjägern von Meister Jonathan Treuwein.",h="In Dunkelhain schickt Calor Jäger gegen Nachtbann-Schattenweber im Dämmerwald aus.",kw={"schattenhain","calor","treuwein","dunkelhain","dämmerwald","nachtbann","der verrottende obstgarten","schattenweber","worgen"},ang={["class:Hunter"]="Die Jagd auf die Nachtbann stellt Fährtenlesen und Tierkunde auf die härteste Probe. Worgen sind weder natürliche Wildtiere noch gewöhnliche menschliche Gesetzlose; sie sind zweibeinige Schrecken, die Schattenzauber wirken.",["faction:Alliance"]="Dunkelhain fühlt sich von Sturmwinds High Seat im Stich gelassen, weshalb Stadtbewohner und Selbstjustiz übende Kämpfer wie Calor umherziehende Abenteurer der Allianz suchen, die die Monster zurückhalten können.",["race:Human"]="Für Menschen aus Elwynn oder Westfall sind die verfallenen Höfe des Dämmerwalds, etwa der Verrottende Obstgarten, eine Warnung vor den Folgen ungezügelter dunkler Magie für die Kornkammern eines Königreichs."},sec={{t="Eine private Wacht",b="Die Nachtwache kämpft an Dunkelhains Grenzen gegen Untote, Spinnen und Gesetzlose. Calor war der Wachen überdrüssig, die zu langsam und selbstzufrieden waren, um das Land zu säubern. Er verließ die Wache und schloss sich Meister Jonathan Treuwein an, um seine Klinge gegen Ketzerei und Verderbnis zu richten.\n\nTreuwein nimmt niemanden leichtfertig in seinen Kreis auf. Wer ihm helfen will, muss zunächst beweisen, dass er die grausamsten Schrecken des Waldes überleben kann."},{t="Die lauernden Nachtbann",b="Wilde Worgen beherrschen den Schattenhain und den verseuchten Verrottenden Obstgarten. Unter ihnen wirken Nachtbann-Schattenweber dunkle Magie, um ihre Opfer zu blenden und zu fesseln, bevor sie sie zerreißen. Calor schickt angehende Jäger aus, um diese zauberwirkenden Bestien zu erschlagen. Ihr Mut wird auf die Probe gestellt, während die Bedrohung eingedämmt wird, doch deren Ursprung beunruhigt Dunkelhains Verteidiger zutiefst."},{t="Monster aus dem Nichts",b="Worgen sind im Dämmerwald zu einem unausweichlichen Albtraum geworden, doch niemand kann ihre Anwesenheit erklären. Calor sagt, sie schienen aus dem Nichts aufgetaucht zu sein, ohne natürliche Abstammungslinie in der Region. Anders als gefräßige wilde Wölfe oder Leichen aus örtlichen Grabhügeln wirken diese zweibeinigen Raubtiere bizarre, fremdartige Zauber und bringen unersättliche Raserei.\n\nDie Schattenweber zu erschlagen beweist das Können eines Jägers, kratzt aber nur an der Oberfläche eines unnatürlichen Befalls, der im ganzen Wald Wurzeln schlägt."}},faq={{q="Wer ist Calor?",a="Calor ist ein Jäger und ehemaliges Mitglied der Nachtwache von Dunkelhain. Frustriert vom vorsichtigen Vorgehen der Stadtmiliz schloss er sich Meister Jonathan Treuwein an, um die Kreaturen zu jagen, die den Dämmerwald bedrohen.",al={"calor","calor dunkelhain","wer vergibt worgen in den wäldern"}},{q="Warum will Calor die Nachtbann-Schattenweber töten lassen?",a="Calor nutzt die Nachtbann-Schattenweber, um Können und Mut zu prüfen. Wer Meister Treuwein helfen will, muss beweisen, dass er gefährliche, zauberwirkende Worgen jagen und zur Verteidigung der Stadt beitragen kann.",al={"warum schattenweber töten","worgen in den wäldern ziel"}},{q="Wo sind die Nachtbann-Schattenweber zu finden?",a="Nachtbann-Schattenweber streifen durch den Schattenhain und den Verrottenden Obstgarten, westlich und südwestlich von Dunkelhain. Das Gelände des Obstgartens ist verlassen und überwuchert.",al={"wo sind nacht bann-schattenweber","schattenweber fundort"}},{q="Woher kamen die Worgen im Dämmerwald?",a="Das plötzliche Auftauchen der Worgen ist den Bewohnern des Dämmerwalds ein Rätsel. Calor sagt, die Bestien schienen aus dem Nichts erschienen zu sein und brachten dunkle Schattenmagie und unersättliche Raserei in einen ohnehin dem Untergang nahen Wald.",al={"worgen ursprung dämmerwald","warum sind worgen im dämmerwald","woher kommen worgen"}},{q="Wer ist Meister Treuwein?",a="Meister Jonathan Treuwein ist ein unabhängiger Monsterjäger mit Sitz in Dunkelhain. Er und seine Anhänger arbeiten außerhalb der Nachtwache und jagen das Böse, Untote und bizarre Monstrositäten in der ganzen Region.",al={"treuwein","meister treuwein","wer ist meister treuwein"}},{q="Warum verließ Calor die Nachtwache?",a="Calor verlor angesichts der aus seiner Sicht passiven und selbstzufriedenen Haltung der Nachtwache seine Illusionen. Statt an den Grenzzäunen Wache zu halten, während die Dunkelheit näher rückte, entschied er sich für Treuweins aktive Jagd auf das Böse.",al={"warum verließ calor die wache","calor night watch"}}},fx={e85e2f18={q="Was sind die Nachtbann-Schattenweber?",a="Nachtbann-Schattenweber sind zauberwirkende Worgen, die an Orten wie Schattenhain und dem verlassenen Obstgarten lauern. Diese lupinen Bestien tauchten plötzlich überall im Dämmerwald auf und führen dunkle Magie, die die Grenzen von Dunkelhain bedroht. Calor und Meister Carevin betrachten ihr plötzliches Erscheinen als eine aktive Plage für den Wald, die ausgerottet werden muss.",al={"wer sind nachtbann-schattenweber","nachtbann-schattenweber","was sind die worgen"}},["5ce72e6e"]={q="Warum braucht Calor Euch, um die Worgen zu jagen, anstatt es selbst zu tun?",a="Calor hat sich von The Nachtwache getrennt, da er von deren Selbstgefälligkeit und Untätigkeit desillusioniert war. Nun dient er Meister Carevin bei ihrem engagierten Bestreben, Häresie und das Böse aus dem Dämmerwald zu tilgen. Calor erwartet von Neulingen, die sich ihrer Sache anschließen wollen, dass sie sich durch Taten und nicht durch leere Worte beweisen.",al={"warum mich schicken","warum braucht calor mich","warum nicht the night watch"}}},fp="19,295,15.398.0,21.355.0,21.469.1,13.189.0,52.184.0,45.154.0,43.214.0,22.194.0,36.197.0"}
P.entries["quest:1738"] = {n="Herzholz",s="Seit dem Dritten Krieg suchen Hexenmeister Herzholz wegen einer alten Tragödie der Nachtelfen. Takar der Seher schickt sie für Gakin den Dunkelbinder nach Eschental, der das Holz braucht, um in Sturmwind eine Sukkubus anzulocken und zu unterwerfen.",h="Seit dem Dritten Krieg suchen Hexenmeister Herzholz wegen einer alten Tragödie der Nachtelfen.",kw={"anathera","eschental","brachland","dunkler strang","gakin der dunkelbinder","herzholz","latherion","ordil'aran","sukkubus","takar der seher"},ang={["class:Warlock"]="Als Hexenmeister braucht Ihr Herzholz, um eine Sukkubus zu beschwören und zu versklaven. Mit ihren Kräften kann sie den Verstand Eurer Feinde auf dem Schlachtfeld gegen sie selbst wenden.",["faction:Alliance"]="Als Zauberwirker der Allianz durchquert Ihr umkämpfte Wildnis und stellt Euch feindlichen Außenposten der Horde inmitten uralter Nachtelfenruinen in Kalimdor.",["race:Human"]="Als Mensch könnt Ihr Euch auf weit entfernte Kundschafter wie Takar den Seher verlassen, um Relikte aus dem alten Kalimdor zu finden. Solche Relikte liegen jenseits dessen, was menschliche Arkanisten aufgezeichnet haben."},sec={{t="Ein Denkmal tragischer Liebe",b="Takar der Seher sagt, Herzholz sei dort gewachsen, wo die Nachtelfen Anathera und Latherion als Liebespaar vor zehntausend Jahren im Krieg der Ahnen fielen. Ihre letzten Atemzüge und ihre Hingabe nährten den Baum. Für Sterbliche ist er ein Zeichen tragischer Liebe. Für die Ausübenden der dunklen Künste sind seine geballten Gefühle ein mächtiger magischer Brennstoff."},{t="Die Sukkubus anlocken",b="Sukkubi nähren sich von der Leidenschaft, dem Verlangen und den Qualen der Sterblichen. Takar weiß, dass gewöhnliche Versuchungen einem Artefakt voller jahrtausendelanger Hingabe nicht gleichkommen können. Ein Stück Herzholz gibt Gakin dem Dunkelbinder den nötigen Katalysator, um eine gerissene Dämonin durch den Nether in einen Beschwörungskreis im Magierviertel von Sturmwind zu ziehen."},{t="Die Ruinen von Ordil'Aran",b="Im nordwestlichen Eschental wächst der Herzholzbaum inmitten der Ruinen von Ordil'Aran. Wilde Bestien, feindselige Gebiete und Kultisten des Dunklen Strangs, die die elfischen Ruinen besetzen, versperren den Weg. Sobald das Holz geborgen ist, muss es über das Meer zum Slaughtered Lamb in Sturmwind gebracht werden, wo das Ritual der Unterwerfung beginnt."}},faq={{q="Warum brauchen Hexenmeister Herzholz, um eine Sukkubus zu beschwören?",a="Sukkubi werden von Leidenschaft, Verlangen und starken Gefühlsbindungen angezogen. Herzholz wuchs dort, wo vor zehntausend Jahren zwei einander innig liebende Nachtelfen gemeinsam starben, und ihre fortbestehende Leidenschaft erfüllt das Holz. Das macht es zum idealen Köder, um eine Sukkubus durch den Nether zu ziehen.",al={"warum herzholz","sukkubusköder","warum holz für sukkubus"}},{q="Wo wächst der Herzholzbaum?",a="Der Herzholzbaum wächst inmitten der Ruinen von Ordil'Aran im nordwestlichen Eschental, nicht weit südlich der Dunkelküste. Finstere Kultisten haben die Kontrolle über das Gebiet übernommen.",al={"herzholz fundort","wo ist das herzholz","wo herzholz finden"}},{q="Wer waren Anathera und Latherion?",a="Anathera und Latherion waren Nachtelfen, die während des Kriegs der Ahnen Seite an Seite kämpften. Sie fielen gemeinsam auf dem Schlachtfeld. Herzholz wuchs dort, wo sie ihre letzten Atemzüge taten, als Zeichen ihrer fortwährenden Liebe.",al={"anathera und latherion","wer waren die liebenden","liebende von eschental"}},{q="Wer ist Takar der Seher?",a="Takar der Seher ist ein menschlicher Seher, der mit den Hexenmeistern von Sturmwind verbündet ist. Er lebt als Einsiedler im südlichen Brachland nahe Camp Taurajo. Mit seiner Sehergabe blickt er in die Vergangenheit und findet vergessene Relikte für Gakin den Dunkelbinder.",al={"wer ist takar","takar der seher","einsiedler im brachland"}},{q="Wie reist ein Hexenmeister der Allianz sicher vom Brachland nach Eschental?",a="Reisende der Allianz müssen im Brachland den Außenposten der Horde am Mor'shan-Schutzwall meiden, wo die Wachen alles genau beobachten. Hexenmeister können durch eine unbewachte Bresche direkt östlich des Haupttors schlüpfen, den höher gelegenen Weg durch das Steinkrallengebirge nehmen oder den Grenzfluss durchschwimmen.",al={"wie nach eschental gelangen","mor'shan umgehen","schutzwall der horde meiden"}},{q="Was geschieht, nachdem Gakin das Herzholz erhalten hat?",a="Gakin bereitet mit dem Holz ein Ritual in den Katakomben unter dem Slaughtered Lamb in Sturmwind vor. Er zeichnet einen Beschwörungskreis, um eine Sukkubus aus dem Twisting Nether zu ziehen, und beauftragt dann den Hexenmeister, sie zu besiegen und zu unterwerfen.",al={"was kommt nach herzholz","was macht gakin mit herzholz"}}},fx={bf8a48f3={q="Warum schickt Euch Takar der Seher aus, um das Herzholz zu finden?",a="Takar fungiert als weitsichtiger Verbündeter für Gakin der Dunkelbinder und seinen Zirkel in Sturmwind. Er bereitete Eure Ankunft vor, indem er mit seiner mystischen Sicht die Nebel der Zeit durchkämmte und ein Artefakt ausfindig machte, das mächtig genug ist, eine Sukkubus über die Ebenen hinweg anzulocken und zu fangen. Die Unterstützung angehender Hexenmeister bei ihren Prüfungen ist seine Rolle innerhalb ihrer geheimen Bruderschaft.",al={"takar motiv herzholz","warum hilft takar","warum lässt takar mich herzholz besorgen"}}},fp="10,221,25.318.0,20.325.0,23.303.1,53.262.0,36.160.0,32.215.0,22.220.0,73.260.0,49.231.0"}
P.entries["quest:1739"] = {n="Die Bindung",s="In Sturmwind wollen Hexenmeister eine Sukkubus ihrem Willen unterwerfen. Unter dem Slaughtered Lamb beschwört ein Initiand mit einem verzauberten Herzholzkern den Dämon und besiegt ihn im Kampf.",h="In Sturmwind wollen Hexenmeister eine Sukkubus ihrem Willen unterwerfen.",kw={"bindung","gruft","dunkelbinder","gakin","herzholz","slaughtered lamb","sturmwind","sukkubus","beschwörungskreis"},ang={["class:Warlock"]="Als menschlicher oder gnomischer Hexenmeister geht Ihr vom Umgang mit geistlosen Wichteln und Leerwandlern dazu über, denkende, berechnende Dämonen zu befehligen.",["faction:Alliance"]="Als Mitglied der Allianz erlebt Ihr, wie Sturmwind trotz der Lehren der Kirche Shadow Magic in verborgenen Nischen stillschweigend duldet."},sec={{t="Abstieg in die Gruft",b="Unter dem Slaughtered Lamb im Magierviertel von Sturmwind bietet eine Gruft den Hexenmeistern der Stadt Zuflucht. Dort praktizieren sie verbotene Künste, fernab der Stadtwache und der Kathedrale des Lichts. Steinerne Beschwörungskreise kanalisieren die Macht des Nethers und lassen Initianden durch den Schleier zwischen den Welten greifen."},{t="Die Verführerin unterwerfen",b="Ein Hexenmeister braucht einen vorbereiteten Herzholzkern, um eine Sukkubus zu beschwören. Das Ritual öffnet einen Riss am Beschwörungskreis, doch der Dämon kann selbst einen gefestigten Geist verderben und überwältigen. Um ihn zu beherrschen, muss der Hexenmeister ihn im Zweikampf besiegen. Seine körperliche Gestalt kehrt in den Wirbelnden Nether zurück, während sein wahres Band gesichert wird."},{t="Gakins Geheimnisse",b="Nachdem die beschworene Kreatur erschlagen wurde, bringt der Initiand den verbrauchten Kern zu Gakin dem Dunkelbinder zurück. Gakin vermittelt ihm dann das nötige Wissen, um die Sukkubus durch die Leere herbeizurufen. Der Ritus macht einen Hexenmeister der Allianz zum Adepten, dem man den Umgang mit unberechenbaren, denkenden Dämonen zutraut."}},faq={{q="Wo findet die Beschwörung statt?",a="Die Beschwörung findet in Katakomben unter dem Slaughtered Lamb statt, einer Schenke im Magierviertel von Sturmwind. Wendeltreppen führen am Schankkeller vorbei zu einem unterirdischen Heiligtum mit arkanen Beschwörungskreisen.",al={"wo beschwören","beschwörungsort der sukkubus","lage der gruft"}},{q="Welchem Zweck dient der Herzholzkern?",a="Der Herzholzkern verankert die Beschwörung und versorgt sie mit Kraft. Er stammt vom Herzholz, einem Baum, der dort wuchs, wo zwei Nachtelfenliebende während des War of the Ancients im Eschental fielen. Seine spirituelle Resonanz öffnet einen Riss und zieht eine Sukkubus durch den Wirbelnden Nether.",al={"warum herzholzkern","was bewirkt herzholz"}},{q="Warum muss der Hexenmeister die Sukkubus töten?",a="Ein Hexenmeister muss die Sukkubus erschlagen, um seine Vorherrschaft über sie zu begründen. Sukkuben setzen auf Manipulation und geistige Unterwerfung, und wer eine Gestalt annehmen lässt, ohne sie zu besiegen, beschwört Unheil herauf. Der Kampf prägt dem Geist die Autorität des Hexenmeisters ein, bevor er im Nether erneut Gestalt annimmt.",al={"warum gegen die sukkubus kämpfen","warum den dämon töten, um ihn zu binden"}},{q="Wer ist Gakin der Dunkelbinder?",a="Gakin der Dunkelbinder ist ein ranghoher Hexenmeister, der im Slaughtered Lamb lebt und die Ausbildung der Hexenmeister der Allianz in Sturmwind beaufsichtigt. Er organisiert die geheime Beschaffung dämonologischer Artefakte und beurteilt, ob Akolythen den Willen besitzen, Dämonen zu befehligen.",al={"wer ist gakin","geschichte von gakin dem dunkelbinder"}},{q="Wer ist Surena, die Gakin erwähnt?",a="Surena Caledon war Gakins ehemalige Schülerin. Sie schloss sich den Defias an, und Ihr habt zuvor ihr Halsband zurückgeholt. Gakin fragt sich spöttisch, ob sie eine verkleidete Sukkubus war, die seinen Geist verderben sollte, meint dann aber, er traue ihr zu viel zu.",al={"anspielung auf surena","wer war surena"}},{q="Sind Sukkuben auf den Straßen von Sturmwind erlaubt?",a="Die Kirche des Heiligen Lichts und die Obrigkeit des Königreichs verbieten offen praktizierte Dämonologie streng. Gebundene Dämonen dürfen Hexenmeistern durch die Stadt folgen, doch die Praktiken bleiben im Verborgenen, in Kellern und abgeschiedenen Heiligtümern wie den Gruften des Slaughtered Lamb.",al={"können wachen die sukkubus sehen","ist dämonenbeschwörung in sturmwind erlaubt"}}},fx={["69ec55c9"]={q="Warum möchte Gakin der Dunkelbinder, dass dies erledigt wird?",a="Gakin stellt Eure Disziplin und Meisterschaft als angehender Hexenmeister auf die Probe. Er möchte sicherstellen, dass Ihr über die Willenskraft verfügt, dämonische Mächte Eurem Befehl zu unterwerfen, anstatt ihren Täuschungen zu erliegen. Indem Ihr beweist, dass Ihr einen beschworenen Dämon unter der Taverne bezwingen könnt, zeigt Ihr, dass Ihr es wert seid, zu lernen, wie man einen Sukkubus dauerhaft bindet und kontrolliert.",al={"warum will gakin das","gakin motiv","warum gakin sukkubus beschwören"}},["2be029b1"]={q="Was ist der Sukkubus, den Ihr beschwören sollt?",a="Ihr beschwört einen Sukkubus – einen verführerischen, gerissenen Dämon aus dem Wirbelnden Nether. Sukkubi sind dafür bekannt, Wünsche zu manipulieren und selbst entschlossene Geister zu überwältigen. Er hält sich nicht von Natur aus in Sturmwind auf; Euer Zauber und der Herzholzkern reißen gezielt einen lokalen Riss auf, um die Kreatur hervorzulocken, damit Ihr ihr Wesen besiegen und versklaven könnt.",al={"was ist der sukkubus","wer ist das ziel the binding","beschworener sukkubus"}},f36093f2={q="Warum lässt Gakin Euch den Sukkubus beschwören, anstatt es selbst zu tun?",a="Ein Dämon kann nicht im Auftrag eines anderen Hexenmeisters gebunden werden; der Pakt der Knechtschaft verlangt, dass der Beschwörer die Kreatur persönlich dominiert. Gakin beherrscht bereits seine eigenen dunklen Künste. Damit Ihr den Sukkubus als Euren Diener rufen könnt, müsst Ihr Euch persönlich der Gefahr stellen, Eure Dominanz über seine Reize beweisen und seinen Willen an den Euren binden.",al={"warum muss ich den sukkubus beschwören","warum ich the binding","warum kann gakin nicht gegen den sukkubus kämpfen"}}},fp="11,182,22.291.0,26.321.0,15.284.1,36.202.0,43.262.0,39.267.0,28.254.0,34.234.0,50.249.0"}
P.entries["quest:174"] = {n="Der Blick zu den Sternen",s="Im Dämmerwald sucht Viktori Prism'Antras am Himmel nach Antworten auf den Fluch des Waldes. Er vertraut Beobachtungen mehr als arkanem Aberglauben und bittet Euch, Teile für ein Teleskop zu sammeln, das sein gnomischer Gefährte entworfen hat.",h="Im Dämmerwald sucht Viktori Prism'Antras am Himmel nach Antworten auf den Fluch des Waldes.",kw={"bronzeröhre","cog","dunkelhain","dämmerwald","der blick zu den sternen","teleskop","viktori prism'antras"},ang={["faction:Alliance"]="Patrouillen der Nachtwache wehren Schrecken entlang der Straßen von Dunkelhain ab, während Viktoris Projekt dem Ort Hoffnung gibt, zu verstehen, was seine Heimat vergiftet hat.",["profession:Engineering"]="Gnomische Entwürfe und geschickte Metallarbeit treiben Viktoris Vorhaben voran und lassen Ingenieure unmittelbar an seiner Erforschung der Sterne mitwirken.",["race:Gnome"]="Viktori ist auf seinen gnomischen Gefährten Cog angewiesen, dessen Handwerk Ordnung und Vernunft in einen dunklen Winkel des Königreichs bringt."},sec={{t="Die Suche am Himmel",b="Viele im verängstigten Dunkelhain machen schwarze Magie, Flüche und rastlose Tote für die Nöte des Dämmerwalds verantwortlich. Viktori Prism'Antras bezweifelt, dass diese allein die Verderbnis des Landes erklären. Er glaubt, dass Antworten über dem Blätterdach liegen könnten. Mit Bauplänen seines gnomischen Partners Cog will er ein Instrument zur Erforschung des Himmels bauen."},{t="Eine Frage der Ingenieurskunst",b="Viktori braucht ein stabiles Gestell, um mit dem Bau seines Instruments zur Sternenbeobachtung zu beginnen. Cogs Pläne sehen eine maschinell gefertigte Bronzeröhre vor, und Viktori bittet Euch, eine zu beschaffen. Er vertraut darauf, dass praktische Ingenieurskunst und sorgfältige Beobachtung Licht ins Dunkel bringen, wo Mystik versagt hat."}},faq={{q="Wer ist Viktori Prism'Antras?",a="Viktori Prism'Antras ist ein gelehrter Bewohner von Dunkelhain, der durch die Erforschung der Sterne vernünftige Erklärungen für die Verderbnis des Dämmerwalds sucht.",al={"viktori","wer vergibt der blick zu den sternen","viktori prismantras"}},{q="Warum will Viktori ein Teleskop bauen?",a="Viktori glaubt, dass der Himmel eine greifbare Antwort auf den seltsamen Wandel des Dämmerwalds bergen könnte, die über Magie und örtliche Legenden hinausgeht.",al={"warum sterne beobachten","warum bronzeröhre dämmerwald","teleskop quest dunkelhain"}},{q="Wer ist Cog?",a="Cog ist Viktoris gnomischer Ingenieursfreund, der die Baupläne für das Gerät zur Sternenbeobachtung gezeichnet hat.",al={"cog gnom","wer hat das teleskop entworfen"}},{q="Wo bekommt man eine Bronzeröhre?",a="Ingenieure stellen Bronzeröhren her. Reisende, die selbst keine herstellen können, finden vielleicht eine im Handel, in Auktionshäusern oder bei reisenden Händlern für Ingenieursbedarf mit überschüssigen Vorräten.",al={"wie bronzeröhre bekommen","bronzeröhre fundort","wo bronzeröhre finden"}},{q="Ist dies Teil einer längeren Questreihe?",a="Ja. Damit beginnt ein längeres Unterfangen, um Viktoris Apparat zur Sternenbeobachtung in Dunkelhain zusammenzubauen und zu kalibrieren.",al={"der blick zu den sternen questreihe","wie viele quests der blick zu den sternen"}},{q="Warum sucht Viktori im Dämmerwald nach natürlichen Erklärungen?",a="Obwohl Untote und dunkle Zauber den Wald erfüllen, glaubt Viktori, dass Naturgesetze seinen Wandel bestimmen könnten. Er erforscht den Himmel auf der Suche nach Antworten.",al={"warum wissenschaftliche erklärung dämmerwald","magie gegen wissenschaft dämmerwald"}}},fx={["45e6e811"]={q="Wozu dient das Bronzerohr?",a="Das Bronzerohr dient als struktureller Körper für das Teleskop, das Viktori Prism'Antras konstruiert. Den Bauplänen seines gnomischen Partners Cog folgend, bildet das Metallgehäuse das wesentliche Gehäuse, das benötigt wird, um optische Linsen zusammenzusetzen und das Instrument auf den Himmel auszurichten.",al={"wozu dient das bronzerohr","warum braucht viktori ein bronzerohr","viktori bronzerohr zweck"}}},fp="17,214,19.316.0,23.254.0,28.132.0,43.140.0,11.92.0,36.163.0,35.101.0,60.158.0"}
P.entries["quest:1740"] = {n="Die Kugel von Soran'ruk",s="Im südlichen Brachland versammelt Doan Karhan Hexenmeister um die zerbrochene Kugel von Soran'ruk. Sie wollen die verstreuten Teile und die darin gebundene Essenz wiederherstellen.",h="Im südlichen Brachland versammelt Doan Karhan Hexenmeister um die zerbrochene Kugel von Soran'ruk.",kw={"blackfathom","dämon","doan karhan","kugel von soran'ruk","kugel von zargain","shadowfang","soranruk","hexenmeister"},ang={["class:Warlock"]="Als Hexenmeister erreicht Ihr mit der Wiederherstellung von Soran'ruk einen bedeutenden Meilenstein in Eurer Kunst. Ihr lernt, wie die Legion ihresgleichen bestraft und wie sich gebundene Dämonen in brauchbaren Werkzeugen nutzbar machen lassen.",["faction:Horde"]="Als Mitglied der Horde könnt Ihr Doan Karhan im rauen südlichen Brachland finden. Reisende Beschwörer kommen in diese Ebenen, um tieferes dunkles Wissen zu erlangen."},sec={{t="Gefäße der Geächteten",b="Wenn niedere Dämonen bei der Brennenden Legion in Ungnade fallen, gilt ihre Strafe für alle Ewigkeit. Ihre Geister werden in kristallene Kugeln gebunden und sterblichen Beschwörern und Hexenmeistern als Machtgefäße unter dämonischer Kontrolle überlassen. Eine Kugel zu zerschmettern befreit ihren Gefangenen nicht. Selbst die Splitter bewahren mächtige Magie."},{t="Über Kontinente verstreut",b="Teile von Soran'ruk liegen über zwei Kontinente verstreut. Kultisten des Schattenhammers besitzen kleinere Fragmente in den feuchten Höhlen der Tiefschwarzen Grotte in Eschental. Ein Zauberer in den heimgesuchten Ruinen von Burg Shadowfang im Silberwald nahm die größere, weitgehend unversehrte Hälfte an sich.\n\nDoan Karhan hat sein Leben dem Studium der Kugeln der Legion gewidmet und bereits die Kugel von Zargain zusammengesetzt. Mit den geborgenen Teilen kann er Soran'ruk als brauchbares Werkzeug wiederherstellen."}},faq={{q="Was ist die Kugel von Soran'ruk?",a="Soran'ruk war ein Dämon der Brennenden Legion, der in Ungnade fiel. Nach dämonischem Brauch wurde sein Geist in eine magische Kugel gesperrt und sterblichen Magieanwendern überlassen. Die Kugel wurde später zerschmettert, doch ihre Fragmente bergen noch immer die Macht des Dämons.",al={"soranruk hintergrund","was ist soranruk","wer war soranruk"}},{q="Wer ist Doan Karhan?",a="Doan Karhan ist ein zurückgezogen lebender Hexenmeister im südlichen Brachland. Er hat sein Leben dem Studium und der Wiederherstellung der Kugeln der Brennenden Legion gewidmet. Nachdem er viele Jahre mit dem Zusammensetzen der Kugel von Zargain verbracht hat, hilft er angehenden Hexenmeistern, Soran'ruk zusammenzufügen.",al={"wer ist doan karhan","doan karhan vorgeschichte"}},{q="Warum ist die zerbrochene Kugel auf zwei verschiedene Dungeons verteilt?",a="Die Kugel wurde in zwei Hauptteile gespalten. Kultisten des Schattenhammers besitzen kleinere Fragmente in der Tiefschwarzen Grotte, während ein Zauberer den größeren Überrest in Burg Shadowfang an sich nahm.",al={"warum sind teile in bfd und sfk","wo sind soranruks fragmente"}},{q="Wer kann diese Aufgabe übernehmen?",a="Hexenmeister, die ihre Kunst vertiefen und Werkzeuge aus gefangenen Dämonengeistern meistern wollen, können sich diesem Ritus widmen.",al={"wer kann diese quest machen","kugel von soran'ruk nur für hexenmeister"}},{q="Was macht Doan Karhan mit den geborgenen Fragmenten?",a="Doan Karhan untersucht die geborgenen Fragmente, um seine Forschungen über Relikte der Legion voranzutreiben. Dann setzt er sie zu einem magischen Werkzeug zusammen, dessen Gestalt der Hexenmeister wählt.",al={"was geschieht nach dem sammeln der splitter","soranruk wiederherstellen"}},{q="Was ist die Kugel von Zargain?",a="Die Kugel von Zargain ist ein Gefängnis für einen Dämon der Legion, der in Ungnade fiel. Doan Karhan spürte sie auf und verbrachte viele Jahre damit, sie für den eigenen Gebrauch wiederherzustellen.",al={"kugel von zargain","zargain hintergrund"}}},fx={f1114029={q="Warum möchte Doan Karhan die Fragmente der Kugel von Soran'ruk?",a="Doan Karhan hat sein Leben dem Studium der dämonischen Kugeln gewidmet, die von der Brennende Legion geschmiedet wurden, und der Meisterschaft in der Kunst ihrer Nachbildung. Das Bergen der verstreuten Scherben der Kugel von Soran'ruk ermöglicht es ihm, das Gefäß des eingesperrten Geistes eines in Ungnade gefallenen Dämons aus erster Hand zu untersuchen und seine tiefgreifende Forschung in die Praxis umzusetzen.",al={"warum will doan karhan die kugel","doan karhan motiv","warum fragmente sammeln"}},["32900559"]={q="Was ist das Fragment von Soran'ruk?",a="Die Fragmente von Soran'ruk sind kleine Scherben der zerbrochenen Kugel von Soran'ruk, ein Gefäß, das den Geist eines Dämons bindet, der bei der Brennende Legion in Ungnade gefallen war. Kultisten des Schattenhammers trugen diese Stücke in die Tiefschwarze Grotte, um ihre verbleibende dämonische Macht zu nutzen.",al={"fragment von soran'ruk verwendung","was sind soran'ruk fragmente","tiefschwarze grotte fragmente"}},["321416b0"]={q="Was ist das Große Fragment von Soran'ruk?",a="Das Große Fragment von Soran'ruk ist das wichtigste verbleibende Stück der Kugel von Soran'ruk. Es bewahrt genug konzentrierte dämonische Essenz, dass ein dunkler Hexenmeister in den heimgesuchten Hallen von Burg Shadowfang es für sich beanspruchte, um seine eigene Zauberkunst anzutreiben.",al={"großes fragment von soran'ruk","burg shadowfang fragment","großes fragment verwendung"}},["120120b9"]={q="Wer hält die Fragmente der Kugel?",a="Die Fragmente wurden zwischen zwei gefährlichen Fraktionen aufgeteilt, die nach dämonischer Macht strebten. Die kleineren Scherben fielen in die Hände der Akolythen des Schattenhammers, die unter den Wellen der Tiefschwarze Grotte Pläne schmiedeten, während das größere Überbleibsel von einem gerissenen Hexenmeister ergriffen wurde, der in der Burg Shadowfang lauerte.",al={"wer hat die fragmente","wo sind soran'ruk teile","wer hält die kugelteile"}}},fp="20,161,24.287.0,27.433.0,29.240.0,19.243.0,52.173.0,28.120.0,54.166.0,27.159.0"}
P.entries["quest:175"] = {n="Der Blick zu den Sternen",s="Viktori Prism'Antras braucht einen Spiegel für das Teleskop, das er in Dunkelhain nach Cogs Bauplänen baut. Er schickt Euch nach Süden, um Mary zu finden, die dafür bekannt ist, einen Taschenspiegel bei sich zu tragen.",h="Viktori Prism'Antras braucht einen Spiegel für das Teleskop, das er in Dunkelhain nach Cogs Bauplänen baut.",kw={"die blinde mary","dunkelhain","dämmerwald","der blick zu den sternen","taschenspiegel","mary","teleskop","tranquil gardens","viktori prism'antras"},ang={["faction:Alliance"]="Als Mitglied der Allianz bringt Ihr einen seltenen Schimmer von Neugier und Fortschritt in eine von Schrecken und Fäulnis verzehrte Stadt, indem Ihr Viktori beim Bau seines Teleskops helft.",["profession:Engineering"]="Als Ingenieur folgt Ihr beim Zusammenbau des Teleskops präzisen optischen Plänen. Gnomische Baupläne leiten die Arbeit, schwaches Sternenlicht zu reflektieren und zu vergrößern."},sec={{t="Eine reflektierende Oberfläche",b="Viktori Prism'Antras hat die Bronzeröhre für sein Teleskop. Cogs Baupläne verlangen einen Spiegel, der Licht hindurchleitet und reflektiert. Feines verspiegeltes Glas lässt sich nur schwer herstellen, solange in Dunkelhain Mangel herrscht. Deshalb erinnert sich Viktori an Mary, eine Einheimische, die in der ganzen Region dafür bekannt ist, einen Taschenspiegel bei sich zu tragen."},{t="Suche im Süden",b="Marys altes Zuhause liegt tief im südlichen Dämmerwald, knapp nördlich des Friedhofs \"Stille Gärten\". Um es zu erreichen, müsst Ihr die sicheren Patrouillengebiete der Nachtwache hinter Euch lassen. Vor Euch liegen verheerte Haine, in denen ausgehungerte Wölfe, wilde Spinnen und umherstreifende Untote ihr Unwesen treiben."},{t="Eine tragische Bewohnerin",b="Die blinde Mary ist ein umherwandernder Geist nahe ihrem alten Zuhause und dem Friedhof. Ihre Hütte im Süden offenbart, was aus der Frau geworden ist, an die sich Viktori erinnerte. Gebunden an Erinnerungen und Besitztümer aus ihrem früheren Leben, bleibt sie nahe dem Ort, den sie einst ihr Zuhause nannte."}},faq={{q="Was baut Viktori Prism'Antras?",a="Viktori baut ein astronomisches Teleskop in seiner Hütte oben auf dem Hügel in Dunkelhain. Er folgt den Entwürfen von Cog, einem Tüftler.",al={"viktori teleskop","projekt der blick zu den sternen","was baut viktori"}},{q="Warum braucht Viktori einen Taschenspiegel?",a="Cogs Baupläne verlangen einen Spiegel, der Licht durch das Teleskop reflektiert und bündelt. Viktori erinnert sich, dass Mary einen Taschenspiegel bei sich trug, und hofft, ihn beim Zusammenbau verwenden zu können.",al={"warum spiegel nötig","reflektierende oberfläche teleskop"}},{q="Wo ist Mary zu finden?",a="Marys verfallenes Zuhause liegt im südöstlichen Dämmerwald, knapp nördlich des Friedhofs \"Stille Gärten\".",al={"wo ist mary","mary fundort dämmerwald","die blinde mary finden"}},{q="Wer ist Mary?",a="Mary lebte im südlichen Dämmerwald, bevor das Land in verfluchte Finsternis fiel. Die Menschen rund um Dunkelhain kannten sie dafür, einen Taschenspiegel bei sich zu tragen. Bei ihrem alten Zuhause nahe dem Friedhof \"Stille Gärten\" könnt Ihr erfahren, was aus ihr geworden ist.",al={"wer ist die blinde mary","vorgeschichte der blinden mary"}},{q="Hat Mary ihren Taschenspiegel noch?",a="Mary sagt, sie habe einst einen Taschenspiegel besessen, doch inzwischen hat sie ihn nicht mehr. Sie kann Euch nur einen Hinweis geben, wohin er gelangt ist.",al={"hat mary einen spiegel","die blinde mary taschenspiegel"}},{q="Welche Gefahren umgeben Marys Hütte?",a="Untote, wilde Dämmerungsfledermäuse, giftige Netzspinnen und tollwütige Wölfe durchstreifen die südöstlichen Wälder und den Friedhof \"Stille Gärten\". Sie machen Jagd auf Reisende, die sich südlich von Dunkelhain wagen.",al={"gefahren bei mary","bedrohungen am friedhof \"stille gärten\""}}},fx={["9372b916"]={q="Warum ist Viktori Prism'Antras so sehr darauf bedacht, sein Teleskop fertigzustellen?",a="Viktori Prism'Antras ist ganz von seinem Ehrgeiz erfüllt, in seiner Hütte in Dunkelhain ein astronomisches Teleskop fertigzustellen. Nach den Bauplänen des Gnoms Cog benötigt er spezielle Komponenten, um Licht zu reflektieren und zu bündeln. Er hofft, jenseits der ewigen Finsternis zu blicken, die den Dämmerwald einhüllt. Jedes obskure Bauteil zu sammeln, ist entscheidend, um seine gewaltige Konstruktion zum Leben zu erwecken.",al={"warum will viktori, dass das erledigt wird?","viktori prism'antras' beweggrund","warum das teleskop bauen?"}}},fp="17,173,20.295.0,19.241.0,17.249.1,38.124.0,38.168.0,24.88.0,12.219.1,39.108.1,37.174.0"}
P.entries["quest:1758"] = {n="Foliant der Kabale",s="Oberhalb von Ratschet schickt Strahad Farsan einen Hexenmeister der Allianz nach Eisenschmiede. Dort könnte der Foliant der Kabale enthalten, was ein unvorbereiteter Beschwörer braucht, um einen felhunter zu binden.",h="Oberhalb von Ratschet schickt Strahad Farsan einen Hexenmeister der Allianz nach Eisenschmiede.",kw={"felhunter","hall of explorers","eisenschmiede","krom starkarm","ratschet","strahad farsan","foliant der kabale","hexenmeister"},ang={["class:Warlock"]="Als Hexenmeister bringt Euch der Erwerb des Folianten der Kabale der Beherrschung von felhuntern näher. Er führt Euch über niedere Diener hinaus zur antimagischen Dämonologie.",["faction:Alliance"]="Als Hexenmeister der Allianz kehrt Ihr von Kalimdors Grenzland zur Hall of Explorers in Eisenschmiede zurück, auf der Suche nach verbotenen dunklen Schriften.",["race:Dwarf"]="Als Zwerg seht Ihr, dass nicht jeder in der Hall of Explorers Titanenartefakte ausgräbt. Krom Starkarm trägt im Verborgenen dämonisches Wissen zusammen."},sec={{t="Eine Bestie, die Magie verschlingt",b="Ein Wichtel, ein Leerwandler oder eine Sukkubus lässt sich durch ein Ritual unterwerfen. Bei einem felhunter liegt der Fall anders. Er dient der Brennenden Legion und jagt arkane Energie, um sie zu verschlingen. Ein gewöhnlicher Beschwörungskreis zerfällt, bevor er den Dämon festhalten kann. Der felhunter entzieht seinem Beschwörer die Magie, bevor eine Bindung greift. Von seiner Zuflucht im Brachland aus wacht Strahad Farsan über Ratschet. Er weiß, dass kein Anfänger die Bindung unvorbereitet versuchen sollte."},{t="Die erste Bindung",b="Ein Akolyth braucht die arkanen Formeln des Folianten der Kabale, um einen felhunter sicher zu beschwören und zu binden. Das Manuskript stammt von der ersten sterblichen Kabale von Hexenmeistern, die einen solchen Dämon ohne fremde Hilfe bezwang. Seine Seiten erläutern die Geomantie, die Materialien und die Bindungsrunen, die nötig sind, um dem Hunger der Kreatur standzuhalten. Das Exemplar ging vor langer Zeit verloren. Strahad und sein Zirkel besitzen das Meisterwerk nicht mehr."},{t="Der Horter von Dun Morogh",b="Strahad kann den Text nicht bereitstellen, also schickt er Hexenmeister der Allianz über das große Meer zur Hall of Explorers in Eisenschmiede. Krom Starkarm, ein umherziehender Zwergenhexenmeister, lebt dort. In seinem Lebensabend durchforstet er uralte Manuskripte und Bibliotheksaufzeichnungen. Falls in den Östlichen Königreichen noch eine Spur des verlorenen Zauberbuchs verzeichnet ist, findet sie sich in Kroms akribischen Katalogen."}},faq={{q="Warum muss ich den Folianten der Kabale finden?",a="Der Foliant der Kabale enthält genaue Anweisungen der ersten sterblichen Hexenmeister, die einen felhunter ohne fremde Hilfe beschworen und unterwarfen. Gewöhnliche Beschwörungsrituale können keinen Dämon festhalten, der sich von magischer Energie ernährt.",al={"was ist der foliant der kabale","warum das buch finden","zweck des folianten der kabale"}},{q="Wer ist Krom Starkarm?",a="Krom Starkarm ist ein umherziehender Zwergenhexenmeister, der in der Library der Hall of Explorers in Eisenschmiede lebt. Er verbringt seine Tage zwischen staubigen Folianten und katalogisiert uralte historische Aufzeichnungen.",al={"wo ist krom","wer ist krom starkarm","krom eisenschmiede"}},{q="Warum ist Strahad Farsan im Brachland?",a="Strahad Farsan ist ein versierter menschlicher Hexenmeister mit einer ruhigen, neutralen Zuflucht auf den Anhöhen über Ratschet. Fernab der wachsamen Augen der Kirin Tor und der Behörden von Sturmwind unterweist er Hexenmeister der Allianz und der Horde in mächtiger Dämonologie.",al={"strahads standort","warum ratschet","wer ist strahad"}},{q="Was geschieht, nachdem ich mit Krom Starkarm gesprochen habe?",a="Krom Starkarm erinnert sich an Verweise auf den Folianten in alten Katalogregistern. Er schickt Euch los, um dessen verlorene Teile aufzuspüren und die seltenen Reagenzien zu beschaffen, die zur Wiederherstellung des Zauberbuchs nötig sind.",al={"nächste quest","nach krom","foliant der kabale nächster schritt"}},{q="Können Hexenmeister der Horde diese Quest machen?",a="Diese Reise nach Eisenschmiede ist für Hexenmeister der Allianz bestimmt. Strahad schickt Hexenmeister der Horde zu kundigen Kontaktpersonen im Gebiet der Horde.",al={"hordenversion","nur für die allianz"}},{q="Welchen Dämon schaltet diese Questreihe frei?",a="Die Questreihe um den Folianten der Kabale endet in einem rituellen Kampf gegen einen beschworenen felhunter. Der Hexenmeister lernt, einen solchen Dämon als dauerhaften Diener zu beschwören und zu binden.",al={"welcher dämon","felhunter quest","welchen begleiter bekomme ich"}}},fx={["8ce24f0c"]={q="Warum möchte Strahad Farsan, dass Ihr das Tome of the Cabal findet?",a="Strahad Farsan leitet Eure Entwicklung als Hexenmeister und bereitet Euch darauf vor, einen der grausamsten Raubtiere des Wirbelnden Nether zu befehligen: einen Teufelsjäger. Das Beschwören eines solchen Tieres erfordert komplizierte, gefährliche Rituale, die weit über Standard-Magiekreise hinausgehen. Das verlorene Tome of the Cabal enthält die ursprünglichen Riten, die von den ersten Hexenmeistern verfasst wurden, die erfolgreich einen Teufelsjäger ohne Hilfe banden. Strahad und seine Akolythen stehen bereit, um die Beschwörungskreise über Ratschet zu weben, aber ohne das spezifische Wissen, das im Tome of the Cabal bewahrt ist, kann das Ritual nicht sicher beginnen.",al={"warum will strahad das tome","strahad farsan motiv","strahad cabal tome grund"}},["327d5815"]={q="Warum schickt Strahad mich, anstatt das Tome of the Cabal selbst zu bergen?",a="Die Unterwerfung eines dämonischen Dieners ist eine zutiefst persönliche Prüfung, die Euren Einfallsreichtum und Eure Entschlossenheit testet. Strahad stellt die Expertise, das Ritualheiligtum und die Akolythen bereit, um die Magie zu verankern, aber die Last, das notwendige Wissen zu sichern, liegt ganz bei Euch. Außerdem bleibt Strahad in Ratschet verschanzt, um gefährliche arkanische Kräfte zu verwalten, während Ihr frei zur Hall of Explorers in Eisenschmiede reisen könnt, um Gelehrte wie Krom Starkarm zu konsultieren und die verstreuten Relikte selbst zu bergen.",al={"warum schickt strahad mich","warum kann strahad das tome nicht holen","warum spieler nach eisenschmiede schicken"}}},fp="17,162,27.425.0,17.384.0,25.380.0,44.208.0,21.188.0,37.254.0,44.178.1,33.135.0,38.144.0"}
P.entries["quest:176"] = {n="GESUCHT: \"Hogger\"",s="Im Südwesten von Elwynn hat Hogger jeden örtlichen Versuch vereitelt, ihn zur Strecke zu bringen. Der Kopfgeldaushang der Allianz außerhalb von Goldhain fordert den Kopf dieses riesigen, wilden Gnollhäuptlings.",h="Im Südwesten von Elwynn hat Hogger jeden örtlichen Versuch vereitelt, ihn zur Strecke zu bringen.",kw={"kopfgeld","dughan","elwynn","der waldrand","gnoll","goldhain","hogger","gesucht"},ang={["faction:Alliance"]="Für Helden der Allianz ist der Sieg über Hogger eine Bewährungsprobe, bei der sie zur Verteidigung von Sturmwinds Kernland ihren Mut beweisen.",["race:Human"]="Für die Menschen von Elwynn sichert Hoggers Tod die Gehöfte und den Straßenhandel, die seit Monaten unter Gnollüberfällen leiden."},sec={{t="Eine Bedrohung im Wald",b="Banditentum und Koboldplagen setzen dem Wald von Elwynn zu, während die Gnolle im Süden unter Hoggers brutaler Führung kühner und organisierter werden. Er überragt die typischen Gnolle der Flusspfoten und hat nahe dem Waldrand sein Lager aufgeschlagen. Von dort aus überfällt er Reisende und überwältigt die örtlichen Milizpatrouillen, die ausgesandt werden, um ihn zu bezwingen."},{t="Goldhains Verzweiflung",b="Die Streitkräfte von Sturmwind sind überlastet und können keine regulären Truppen erübrigen, um die Außenbezirke der Hauptstadt zu sichern. Deshalb hat Marschall Dughan den ungewöhnlichen Schritt unternommen, ein öffentliches Kopfgeld auf Hogger auszusetzen. Wer ihn jagt, muss tief in feindseliges Gnollgebiet vordringen. Seine Wildheit hat ihm unter unerfahrenen Abenteurern in Elwynn einen furchterregenden Ruf eingebracht."}},faq={{q="Wer ist Hogger?",a="Hogger ist ein ungewöhnlich großer und wilder Gnollanführer, der den Südwesten des Waldes von Elwynn terrorisiert. Er befehligt die örtlichen Rudel rund um den Waldrand und hat jeden bisherigen Versuch der Wachen von Sturmwind, ihn gefangen zu nehmen oder zu töten, gewaltsam vereitelt.",al={"wer ist hogger","hoggers geschichte","was ist hogger"}},{q="Wo ist Hogger zu finden?",a="Hogger streift zwischen den Gnolllagern im Südwesten des Waldes von Elwynn umher, nahe dem südlichen Grenzgebiet, das als Waldrand bekannt ist. Das Gebiet liegt unmittelbar nördlich des Flusses, der die Grenze zu Westfall und zum Dämmerwald bildet.",al={"hoggers aufenthaltsort","wo ist hogger","hogger finden"}},{q="Warum ist ein Kopfgeld auf Hogger ausgesetzt?",a="Hogger hat örtliche Patrouillen überwältigt und stellt eine tödliche Gefahr für Reisende dar, weshalb die Streitkräfte von Sturmwind ein Kopfgeld auf ihn ausgesetzt haben. Da die regulären Truppen im gesamten Königreich überlastet sind, hat sich Marschall Dughan an unabhängige Abenteurer und Kopfgeldjäger gewandt, um die Bedrohung zu beseitigen.",al={"warum hogger töten","hoggers steckbrief","wer hat das kopfgeld auf hogger ausgesetzt"}},{q="Wer nimmt den Beweis für Hoggers Tod entgegen?",a="Bringt den Beweis für Hoggers Tod, seine Gewaltige Gnollklaue, direkt zu Marschall Dughan. Er befehligt die örtliche Garnison in Goldhain.",al={"hogger abgeben","wo hogger abgeben","wer will hoggers klaue"}},{q="Warum ist Hogger im Vergleich zu anderen Gnollen so gefährlich?",a="Hogger ist weitaus größer und brutaler als die gewöhnlichen Gnolle, die durch Elwynn streifen. Er schlägt deutlich härter zu und steckt weit mehr ein, wodurch er oft jeden überwältigt, der ihm allein gegenübertritt und ihn unterschätzt.",al={"ist hogger stark","warum ist hogger elite"}},{q="Warum können sich die Wachen von Sturmwind nicht selbst um Hogger kümmern?",a="Die militärischen Mittel des Königreichs sind stark erschöpft und durch die Verteidigung wichtiger Grenzen oder die Suche nach dem vermissten König Varian Wrynn gebunden. Marschall Dughans kleiner Abteilung in Goldhain fehlen die nötigen Leute, um ein derart zähes Ungeheuer ohne große Gefahr zur Strecke zu bringen.",al={"warum tötet dughan hogger nicht","wo sind die streitkräfte von sturmwind"}}},fx={fccb34f1={q="Wozu dient die Gewaltige Gnollklaue?",a="Die Gewaltige Gnollklaue dient als unbestreitbarer Beweis für den Tod von Hogger. Da das Biest jeden Versuch seiner Gefangennahme vereitelt hat, benötigen Marschall Dughan und die Armee von Sturmwind einen unmissverständlichen physischen Beweis, bevor sie die ausgeschriebene Kopfgeldprämie aushändigen.",al={"gewaltige gnollklaue","warum brauche ich hoggers klaue","hogger klaue verwendung"}}},fp="16,186,21.319.0,23.336.0,14.238.0,26.198.0,32.284.0,41.135.0,52.214.0,56.251.0"}
P.entries["quest:177"] = {n="Der Blick zu den Sternen",s="In Dunkelhain braucht Viktori Prism'Antras den Handspiegel der blinden Mary für sein Teleskop. Ein Wahnsinniger Ghul trug ihn zum Friedhof \"Stille Gärten\" im südlichen Dämmerwald.",h="In Dunkelhain braucht Viktori Prism'Antras den Handspiegel der blinden Mary für sein Teleskop.",kw={"die blinde mary","cog","dunkelhain","wahnsinniger ghul","der blick zu den sternen","marys handspiegel","teleskop","der friedhof \"stille gärten\"","viktori prism'antras"},ang={["class:Priest"]="Als Priester könnt Ihr auf dem Friedhof \"Stille Gärten\" das schreckliche Schicksal der Toten des Dämmerwalds bezeugen, wo verstorbene Dorfbewohner zu wahnsinnigen Plünderern geworden sind.",["faction:Alliance"]="Als Mitglied der Allianz seht Ihr das bittere Schicksal der Bewohner des Dämmerwalds, wenn verlorene Ortsreliquien in die Hände gefräßiger Untoter in den gefährlichen Randgebieten des Königreichs Sturmwind fallen.",["profession:Engineering"]="Ingenieure wissen zu schätzen, wie Viktori gewöhnliche polierte Handspiegel zu reflektierenden Bauteilen für ein astronomisches Instrument umfunktioniert."},sec={{t="Ein Relikt besserer Tage",b="Die blinde Mary hütete einst einen verzierten Handspiegel wie einen Schatz. Ein Vorfall raubte ihr Augenlicht und Verstand und ließ sie als weinenden Geist zurück. In ihrer Verzweiflung warf sie den Spiegel hinter der Scheune ihrer Familie in den Schmutz. Nun braucht Viktori Prism'Antras, ein Astronom in Dunkelhain, den Spiegel für sein Teleskop. Der Handspiegel wurde fortgetragen, lange bevor er begann, den Himmel zu erforschen."},{t="Der Plünderer des Friedhofs",b="Ein Wahnsinniger Ghul fand den Handspiegel beim Plündern hinter den verfallenen Gehöften. Rastloser Hunger trieb ihn nach Süden, und so trug er den Spiegel zum Friedhof \"Stille Gärten\". Er sucht eine verlassene Kapelle zwischen überwucherten Grabsteinen heim. Ihr stellt Euch den fleischfressenden Schrecken der südlichen Wälder, um Marys verlorenen Schatz seinen verrottenden Klauen zu entreißen."}},faq={{q="Warum braucht Viktori Marys Handspiegel?",a="Viktori Prism'Antras braucht Marys Handspiegel für das Teleskop, das er in seiner Hütte oben am Hügel in Dunkelhain zusammenbaut. Seine spiegelnde Oberfläche eignet sich für seine Erfindung, die schwaches Sternenlicht sammelt.",al={"viktori spiegel","warum handspiegel","wofür ist der spiegel"}},{q="Wer ist der Wahnsinnige Ghul, der den Spiegel gestohlen hat?",a="Der Wahnsinnige Ghul ist ein untoter Plünderer, der kleine Gegenstände aus verlassenen Gehöften nahe Marys Haus sammelte. Er floh nach Süden zur verfallenen Kapelle auf dem Friedhof \"Stille Gärten\".",al={"wo ist der wahnsinnige ghul","wer hat den handspiegel","ghul in der kapelle"}},{q="Warum hat die blinde Mary ihren Handspiegel weggeworfen?",a="Ein Vorfall raubte der blinden Mary Augenlicht und Verstand und ließ sie als ruhelosen Schatten zurück. Da sie es nicht ertragen konnte, ihren Handspiegel anzusehen oder zu halten, warf sie ihn verzweifelt hinter ihre Scheune.",al={"warum hat mary ihn weggeworfen","blinde mary spiegel","mary handspiegel vorfall"}},{q="Wo liegt der Friedhof \"Stille Gärten\"?",a="Der Friedhof \"Stille Gärten\" liegt im südöstlichen Dämmerwald, südlich der Hauptstraße. Einst eine friedliche Begräbnisstätte für die Bewohner des Dämmerwalds, ist er heute von angriffslustigen Ghulen, Skeletten und Aasbestien verseucht.",al={"friedhof \"stille gärten\" lage","wo ist der friedhof"}},{q="Wer ist Cog?",a="Cog ist ein gnomischer Tüftler, der in Dunkelhain lebt. Viktori verlässt sich auf Cogs Ingenieurskunst, um die empfindlichen Mechanismen seiner Sternenbeobachtungsmaschine zu beurteilen und beim Bau zu helfen.",al={"wer ist cog","viktori cog"}},{q="Was geschieht, nachdem der Spiegel zu Viktori zurückgebracht wurde?",a="Der Spiegel bringt Viktori der Fertigstellung seiner Apparatur näher. Er beginnt mit der letzten Phase des Teleskopbaus und bittet um ein letztes Bauteil für dessen Linsensystem.",al={"der blick zu den sternen nächste quest","what comes next"}}},fx={["9a9407cc"]={q="Warum hilft Die blinde Mary Euch, das Fernrohr zu finden?",a="Mary hegt keinen Wunsch, ihr Fernrohr zu behalten. Einst unter ihren wertvollsten Schätzen, wurde es für sie unerträglich, nachdem ein tragischer Vorfall sie erblindete und ins Verderben stürzte. Nachdem sie es in ihrer Verzweiflung bereits hinter ihre Scheune geworfen hat, hat sie keinen Grund, dessen Schicksal geheim zu halten, und weist Euch bereitwillig den Weg zu dem Plünderer, der es genommen hat.",al={"warum hilft die blinde mary","die blinde mary motiv fernrohr","warum sagt mary, wo der spiegel ist"}},f9c44b13={q="Warum braucht die blinde Mary Euch, um den Spiegel zu beschaffen, anstatt ihn selbst zu holen?",a="Die blinde Mary ist ein hilfloser, blinder Geist, der in Isolation außerhalb von Dunkelhain verweilt. Selbst zu Lebzeiten wäre es ihr unmöglich gewesen, sich einem wilden Ghul zu stellen, und im Tod ist sie an ihre verwunschene Hütte gebunden. Ein bewaffneter Abenteurer ist der Einzige, der in der Lage ist, den Friedhof \"Stille Gärten\" zu betreten, um ihn zurückzuholen.",al={"warum mary spiegel nicht holen kann","warum mary mich braucht","warum mary glas nicht birgt"}}},fp="17,164,22.350.0,23.330.0,43.192.0,46.172.0,48.173.0,39.207.0,11.167.0,51.173.1"}
P.entries["quest:1778"] = {n="Der Foliant der Offenbarung",s="In Eisenschmiede lehrt Tiza Kriegshammer Initianden, was der Dienst am Heiligen Licht verlangt. Sie helfen jemandem in Not und kehren dann zurück, um ihr von ihrem Dienst zu berichten.",h="In Eisenschmiede lehrt Tiza Kriegshammer Initianden, was der Dienst am Heiligen Licht verlangt.",kw={"nächstenliebe","heiliges licht","eisenschmiede","paladinprüfung","stephanie","sturmwind","tiza kriegshammer","tome of divinity"},ang={["class:Paladin"]="Als Paladin lernt Ihr, dass das Heilige Licht Selbstlosigkeit, Nächstenliebe und beständige Pflichterfüllung gegenüber gewöhnlichen Bürgern über Kriegsruhm stellt.",["faction:Alliance"]="Als Mitglied der Allianz erkennt Ihr die engen Verbindungen zwischen Eisenschmiede und Sturmwind an den Mentoren und Reisenden, die zwischen diesen großen Städten verkehren.",["race:Dwarf"]="Als Zwergenpaladin erstattet Ihr Tiza Kriegshammer in Eisenschmiede nach Euren Prüfungen in Dun Morogh Bericht. Ihr legt Rechenschaft über Eure Taten in der weiten Welt ab."},sec={{t="Lehren des Heiligen Lichts",b="Paladine beginnen ihre Prüfungen damit, Demut, Pflicht und Nächstenliebe zu lernen. Tiza Kriegshammer verlangt keine Heldentaten im Kampf. Ein Diener des Heiligen Lichts muss die Sorgen gewöhnlicher Menschen verstehen und Hilfe anbieten, ohne nach Lob oder Gewinn zu streben."},{t="Rechenschaft vor Eisenschmiede",b="Nachdem ein angehender Paladin jemandem in Eisenschmiede geholfen hat, kehrt er zu Tiza Kriegshammer zurück. Der Initiand erzählt ihr, wie er seine Zeit fern von ihr verbracht hat und wessen Lasten er mitzutragen half. Ist sie überzeugt, dass er mit Nächstenliebe und Pflichtbewusstsein gehandelt hat, lobt Tiza ihn. Solch selbstloser Dienst bedeutet es, dem Licht zu folgen."}},faq={{q="Was ist der Tome of Divinity?",a="Der Tome of Divinity prüft angehende Paladine auf Mitgefühl, Nächstenliebe und Selbstaufopferung. Seine Prüfungen verlangen von ihnen mehr als Stärke im Kampf.",al={"was ist der tome of divinity","tome of divinity prüfung","was bewirkt diese quest"}},{q="Wer ist Tiza Kriegshammer?",a="Tiza Kriegshammer ist eine Mentorin für Paladine in Eisenschmiede. Sie leitet Initianden an und beurteilt, ob ihre Taten dem Heiligen Licht folgen.",al={"wer ist tiza kriegshammer","wo ist tiza kriegshammer","eisenschmiede paladinlehrer"}},{q="Wer ist Stephanie?",a="Stephanie Turner ist John Turners Frau in Sturmwind. Gemeinsam führen sie ein Waisenhaus, und John hofft, zu ihr zurückzukehren, nachdem er in Eisenschmiede Vorräte gesammelt hat.",al={"wer ist stephanie","stephanie sturmwind"}},{q="Was verlangt Tiza Kriegshammer von zurückkehrenden Initianden?",a="Tiza Kriegshammer hört zu, wenn ein zurückkehrender Initiand berichtet, wie er anderen gedient hat. Sie fragt, wie er einer edlen Sache gedient und gewöhnlichen Bürgern geholfen hat, bevor sie ihren Segen erteilt.",al={"welche lehre prüft tiza","was will tiza","paladin prüfung der nächstenliebe"}},{q="Warum müssen Initianden in Eisenschmiede Bericht erstatten?",a="Initianden kehren nach Eisenschmiede zurück, um Tiza Kriegshammer von ihren Taten zu berichten. Indem sie John Turner in der Stadt helfen, zeigen sie Mitgefühl und Selbstlosigkeit.",al={"warum mit tiza in eisenschmiede sprechen","eisenschmiede tome of divinity"}},{q="Warum steht Selbstaufopferung im Mittelpunkt dieser Prüfung?",a="Die Lehren der Paladine stellen das Wohl anderer über das eigene. Tiza lehrt, dass selbstlose Aufopferung mit der Zeit belohnt wird.",al={"wie belohnt das licht aufopferung","paladin selbstaufopferung"}}},fp="20,155,25.242.0,27.315.0,29.139.0,24.125.0,17.155.0,54.164.0,39.144.0,44.125.0"}
P.entries["quest:1779"] = {n="Der Foliant der Offenbarung",s="In Eisenschmiede prüft der Tome of Divinity Paladin-Initianden in heiliger Macht und kriegerischer Hingabe. Mit dem Symbol des Lebens wird ein Initiand ausgesandt, um Muiredon Battleforge zu helfen, der nach einer tödlichen Begegnung mit Dunkeleisenzwergen verwundet ist.",h="In Eisenschmiede prüft der Tome of Divinity Paladin-Initianden in heiliger Macht und kriegerischer Hingabe.",kw={"dunkeleisen","heiliges licht","eisenschmiede","muiredon battleforge","narm","paladin","symbol des lebens","tome of divinity"},ang={["class:Paladin"]="Als Paladin tragt Ihr das Symbol des Lebens, um den Verwundeten Trost zu spenden. Die Prüfung bereitet Euch auf die heilige Pflicht der Auferweckung vor.",["race:Dwarf"]="Als Zwerg stellt Ihr Euch dieser Prüfung im Herzen von Eisenschmiede. Sie erinnert an die engen Bande zwischen Verteidigern, die Hinterhalten feindlicher Dunkeleisenklans trotzen."},sec={{t="Eine Prüfung des Glaubens und der Macht",b="In Eisenschmiede stellen sich Paladin-Initianden einer Prüfung ihrer Kampfkunst und heiligen Macht. Demut, Geduld und Mildtätigkeit haben sie bereits bewiesen. Nun wird ihnen das Symbol des Lebens anvertraut, und sie werden in die Stadt geschickt, um jenen zu helfen, die unter Konflikten jenseits ihrer Tore leiden."},{t="Ein gefallener Bruder",b="Muiredon Battleforge liegt nach einem Zusammenstoß mit Dunkeleisenzwergen schwer verwundet darnieder. Ein Priester versorgt seine akuten Verletzungen, während er sich darauf vorbereitet, vom Schicksal seiner Expedition und seines Gefährten Narm zu berichten. Der Initiand muss dieser Not mit der Gabe der Erneuerung des Lichts begegnen."}},faq={{q="Was ist der Tome of Divinity?",a="Der Tome of Divinity ist eine Aufnahmeprüfung für junge Paladine, die die Wege des Heiligen Lichts erlernen. Nachdem ein Initiand Mildtätigkeit und Geduld bewiesen hat, erhält er das Symbol des Lebens und wird ausgesandt, einem verwundeten Zwerg in Eisenschmiede zu helfen.",al={"was ist diese quest","zweck des tome of divinity","was bewirkt diese quest"}},{q="Was ist das Symbol des Lebens?",a="Das Symbol des Lebens ist ein heiliges Zeichen, das Paladin-Initianden während ihrer Prüfungen anvertraut wird. Es trägt die Macht des Heiligen Lichts, jene zu heilen und wiederherzustellen, die bei der Verteidigung ihres Volkes gefallen sind.",al={"was ist das symbol des lebens","symbol des lebens gegenstand"}},{q="Wer ist Muiredon Battleforge?",a="Muiredon Battleforge ist ein Zwergenkämpfer, der bei einem Zusammenstoß mit Dunkeleisenzwergen verwundet wurde. Ein Priester versorgt ihn in Eisenschmiede, während seine Frau vielversprechende Paladine zu ihm schickt, um seine Geschichte zu hören.",al={"wer ist muiredon battleforge","wer ist der verwundete zwerg"}},{q="Wer gibt Euch das Symbol des Lebens?",a="Muiredon Battleforges Frau, eine Paladinmentorin in Eisenschmiede, gibt Euch das Symbol des Lebens. Nachdem sie Eure Mildtätigkeit und Geduld erlebt hat, schickt sie Euch los, ihrem verwundeten Mann zu helfen und Eure Macht, Kampfbereitschaft und Hilfsbereitschaft zu prüfen.",al={"wer schickt paladine zu muiredon","wer vergibt diese quest"}},{q="Was ist Muiredon Battleforge widerfahren?",a="Muiredon und sein Gefährte Narm gerieten in einen Hinterhalt von Dunkeleisenzwergen. Muiredon entkam und kehrte mit schweren Verletzungen nach Eisenschmiede zurück, die geistiger und körperlicher Heilung bedürfen.",al={"wer hat muiredon angegriffen","was ist muiredon widerfahren"}},{q="Wer ist Narm?",a="Narm ist Muiredon Battleforges bester Freund und ebenfalls ein Paladin. Er begleitete Muiredon in den Kampf gegen die Dunkeleisenzwerge, entkam dem Zusammenstoß jedoch nicht und benötigt nun den Beistand eines Paladins.",al={"wer ist narm","was ist narm widerfahren"}}},fp="20,235,26.261.0,16.263.0,29.224.0,27.187.0,28.174.0,33.240.0,38.172.0,12.209.0"}
P.entries["quest:178"] = {n="Wiederbeschaffung für Theocritus",s="Im Rotkammgebirge erklingt durch einen Schattenfellanhänger eine seltsame Stimme über die Berge hinweg. Der Sprecher ist Theocritus, Hochmagier vom Turm von Azora, der das mystische Netzwerk der Gnolle angezapft hat und dringend um den Anhänger bittet, um ihn zu untersuchen.",h="Im Rotkammgebirge erklingt durch einen Schattenfellanhänger eine seltsame Stimme über die Berge hinweg.",kw={"elwynn","gnolle","morganth","anhänger","rotkammgebirge","schattenfell","theocritus","turm von azora"},ang={["class:Mage"]="Als Magier erkennt Ihr, wie einfallsreich Theocritus Bannmagie und Weissagung einsetzt. Er dringt in das Netzwerk eines anderen Zauberers ein, um Gegenzauber über gewaltige Entfernungen zu senden.",["faction:Alliance"]="Als Mitglied der Allianz seht Ihr, wie der Turm von Azora in Elwynn mit den bedrängten Verteidigern von Seenhain zusammenarbeitet. Örtliche Magier springen dort ein, wo Sturmwinds königliche Armee die Garnisonen unterbesetzt zurückgelassen hat."},sec={{t="Eine Stimme im Stein",b="Reisende, die im Rotkammgebirge gegen die wilden Schattenfellgnolle kämpfen, finden manchmal einen Schattenfellanhänger. Berührt Ihr das verzauberte Schmuckstück, antwortet statt Bellen oder Flüchen eine ruhige, ferne Stimme. Der Sprecher ist Theocritus, ein menschlicher Magier am Turm von Azora, jenseits der Grenze im Wald von Elwynn. Seine Botschaft entspringt langen Forschungen darüber, wie sich die dunklen Zaubereien brechen lassen, die die Gnollrudel lenken."},{t="Morganths Netzwerk unterwandern",b="Die Schattenfellgnolle gehorchen sowohl Morganth, einem abtrünnigen dunklen Zauberer, der sich in den Bergen verbirgt, als auch ihren eigenen Instinkten. Morganth fertigt verzauberte Anhänger an, um seinen Gnollgefolgsleuten Befehle zu senden. Theocritus verbrachte Monate damit, die Frequenz von Morganths Sendezaubern zu entschlüsseln.\n\nWenn Ihr den verblichenen Anhänger zum Turm von Azora bringt, bestätigt Theocritus, dass sein Spähzauber ihn erreicht hat. Nun kann er untersuchen, wie sich die Magie umkehren und die Gnolle ausschalten lassen."}},faq={{q="Wer ist Theocritus?",a="Theocritus ist ein Hochmagier der Allianz am Turm von Azora im östlichen Wald von Elwynn. Er hält nach Gefahren in der Region Ausschau und erforscht Wege, der dunklen Magie entgegenzuwirken, die sich vom Rotkammgebirge ausbreitet.",al={"theocritus hintergrundgeschichte","wer spricht durch den anhänger","magier vom turm von azora"}},{q="Warum trugen die Schattenfellgnolle magische Anhänger?",a="Morganth, ein abtrünniger Zauberer, erschuf die Anhänger als magische Kanäle. Er nutzt sie, um gedankliche Befehle zu senden und den Schattenfellklan aus der Ferne zu lenken.",al={"warum haben gnolle anhänger","zweck des schattenfellanhängers","magischer gnollgegenstand"}},{q="Warum kam die Stimme verzögert an, als Theocritus sie aussandte?",a="Theocritus sandte seine Botschaft Wochen bevor Ihr den Stein fandet. Zunächst glaubte er, der Zauber sei verblasst, ohne ihn zu erreichen. Das Durchbrechen von Morganths dunklen Schutzzaubern und das Herstellen einer Verbindung über eine so gewaltige Entfernung verzögerten die Botschaft.",al={"verzögerte botschaft","warum brauchte theocritus wochen","verblichener anhänger verzögerung"}},{q="Was hofft Theocritus mit dem wiederbeschafften Anhänger zu erreichen?",a="Theocritus hofft, die magische Frequenz zu entschlüsseln, die den Anhänger mit Morganth verbindet, und ihren Fluss umzukehren. Er will einen Angriffszauber durch das Netzwerk senden, der jeden Gnoll mit einem Anhänger augenblicklich bewegungsunfähig machen könnte.",al={"theocritus' plan","was wird theocritus tun","warum den anhänger untersuchen"}},{q="Wohin führt diese Questreihe als Nächstes?",a="Wenn Ihr den Anhänger zu Theocritus bringt, ist dieser Auftrag abgeschlossen. Sein gesonderter Kampf gegen Morganth geht in „A Watchful Eye“ weiter, wo Ihr Morganths Festung am Turm von Ilgalar ausspähen sollt.",al={"nächste quest nach wiederbeschaffung für theocritus","morganth questreihe","was passiert als nächstes"}}},fx={["24fcac1f"]={q="Warum benötigt Theocritus einen Abenteurer, um das Amulett zu überbringen?",a="Theocritus sandte seine Nachricht blind über die magischen Frequenzen aus, die Morganth benutzt, um mit den Gnollen zu kommunizieren, ohne eine Ahnung zu haben, wo oder wann ein Amulett sie empfangen könnte. An sein Heiligtum im Turm von Azora im Wald von Elwynn gebunden, konnte er die feindselige Wildnis des Rotkammgebirges nicht selbst durchkämmen. Er verlässt sich auf jeden fähigen Reisenden, der das Artefakt entdeckt, um es sicher zurück in zivilisierte Lande zu tragen.",al={"warum einen abenteurer schicken","warum braucht theocritus mich","warum kann theocritus das amulett nicht holen"}}},fp="21,236,20.398.0,29.430.1,18.186.0,57.146.0,50.224.0,64.218.0,38.200.1"}
P.entries["quest:1780"] = {n="Der Foliant der Offenbarung",s="In Sturmwinds Kathedrale des Lichts führt Duthorian Rall Paladine durch eine Prüfung ihrer Hingabe an das Heilige Licht. Sie beweisen ihren Wert durch Nächstenliebe, Selbstlosigkeit und die Pflicht, Bedürftige zu beschützen.",h="In Sturmwinds Kathedrale des Lichts führt Duthorian Rall Paladine durch eine Prüfung ihrer Hingabe an das...",kw={"kathedrale des lichts","nächstenliebe","duthorian rall","heiliges licht","paladinprüfung","sturmwind","tome of divinity"},ang={["class:Paladin"]="Als Paladin beweist Ihr Eure Hingabe an das Heilige Licht durch Nächstenliebe und den Schutz einfacher Bürger. Der Tome of Divinity prüft Eure Bereitschaft, anderen zu dienen.",["faction:Alliance"]="Als Verteidiger der Allianz werdet Ihr daran erinnert, dass Sturmwinds geistliche Stärke auf dem Schutz der Schwachen in Eurem Volk beruht."},sec={{t="Eine Prüfung der Tugend",b="Paladine im Dienste des Heiligen Lichts stellen sich in Sturmwind einer entscheidenden Prüfung. In der Kathedrale des Lichts sendet Duthorian Rall Anwärter aus, ihre Hingabe durch rechtschaffenes Verhalten und selbstlose Taten für die Bürger des Königreichs zu beweisen. Kriegerischer Ruhm allein wird nicht genügen."},{t="Die Tugend der Selbstlosigkeit",b="Nachdem sie den Schutzbedürftigen geholfen haben, kehren die Anwärter zu Duthorian Rall zurück. Sie haben Kindern dringend benötigte Hilfe gebracht und sich deren aufrichtige Dankbarkeit verdient. Ihr Mentor erkennt den Wert darin, andere an die erste Stelle zu setzen. Er lehrt, dass Nächstenliebe, Mitgefühl und die Pflicht gegenüber den Menschen von Azeroth den Pfad des Lichts kennzeichnen."}},faq={{q="Was ist der Tome of Divinity?",a="Der Tome of Divinity ist eine Reihe von Prüfungen für angehende Paladine. Unter Anleitung von Mentoren in Sturmwinds Kathedrale des Lichts zeigen Anwärter Tugend, Nächstenliebe und Pflichtbewusstsein, indem sie bedürftigen Bürgern im ganzen Königreich helfen.",al={"was ist tome of divinity","tome of divinity quest","paladinprüfung quest"}},{q="Wer ist Duthorian Rall?",a="Duthorian Rall ist ein hochrangiger Paladinlehrer in der Kathedrale des Lichts in Sturmwind. Er begleitet junge Paladine bei ihrer geistlichen Ausbildung und ihren moralischen Prüfungen und beurteilt, ob ihre Taten den Tugenden des Heiligen Lichts entsprechen.",al={"wer ist duthorian rall","paladinlehrer sturmwind","duthorian ralls rolle"}},{q="Welche Lehre steckt hinter dieser Prüfung?",a="Die Prüfung lehrt, dass der Umgang mit dem Licht Demut, selbstlose Opfer und den Dienst an anderen verlangt. Sie schätzt Mitgefühl, Nächstenliebe und die moralische Pflicht gegenüber den Menschen von Azeroth ebenso wie kriegerisches Können.",al={"tome of divinity zweck","warum tun paladine das","was lehrt diese quest"}},{q="Wo findet diese Quest statt?",a="Im Mittelpunkt der Prüfung steht die Kathedrale des Lichts in Sturmwind. Anwärter ziehen aus, um der Bevölkerung zu helfen, und kehren dann zurück, um Duthorian Rall in der Kathedrale von ihren Taten zu berichten.",al={"wo findet diese quest statt","wo tome of divinity abgeben","kathedrale des lichts quest"}},{q="Wem hat die Quest geholfen?",a="Die Prüfung bringt Menschen in größter Not Hilfe, darunter auch kleinen Kindern. Die Person, die Hilfe erhält, dankt von Herzen und erinnert Paladine in Sturmwind daran, sich niemals von Unschuldigen und Mittellosen abzuwenden.",al={"wem wurde in dieser quest geholfen","kinder nächstenliebe quest","wer erhielt hilfe"}},{q="Warum betont Duthorian Rall die Nächstenliebe?",a="Duthorian Rall betont die Nächstenliebe, weil das Heilige Licht Großzügigkeit und den Schutz der Unschuldigen verlangt. Er lehrt, dass ein Paladin Opfer für andere bringen und ihr Wohlergehen über sein eigenes stellen muss.",al={"warum ist nächstenliebe für paladine wichtig","paladine und die armen","nächstenliebe heiliges licht"}}},fp="20,203,17.271.0,26.298.0,29.213.0,22.229.0,37.200.0,33.171.0,23.192.0,42.206.0"}
P.entries["quest:1781"] = {n="Der Foliant der Offenbarung",s="In Sturmwinds Kathedrale des Lichts erwartet Paladin-Initianden eine Prüfung: Sie müssen das heilige Symbol des Lebens fokussieren. Wer seine Tugend beweist, wird ausgesandt, um Gazin Tenorm beizustehen, der einem Defias-Hinterhalt nahe der Heldenwache im Wald von Elwynn knapp entkam.",h="In Sturmwinds Kathedrale des Lichts erwartet Paladin-Initianden eine Prüfung: Sie müssen das heilige Symbol...",kw={"kathedrale des lichts","defias","duthorian","duthorian rall","gazin tenorm","henze","heldenwache","symbol des lebens","the tome of divinity","tome of divinity"},ang={["class:Paladin"]="Als Paladin steht Ihr in Sturmwind vor einem Meilenstein Eurer Ausbildung. Die Prüfung zeigt, ob Ihr die geistige Stärke besitzt, das Symbol des Lebens zu führen.",["faction:Alliance"]="Als Mitglied der Allianz wisst Ihr, dass Defias-Angriffe nahe der Heldenwache Reisende und Bürger im gesamten Wald von Elwynn bedrohen. Die Kirche muss eingreifen."},sec={{t="Eine Prüfung der Hingabe",b="In Sturmwinds Kathedrale des Lichts erhalten geduldige und wohltätige Paladin-Initianden das Symbol des Lebens. Duthorian Rall vertraut ihnen dieses heilige Gefäß an, um ihre Hingabe an das Licht zu prüfen. Nur ein würdiger Streiter kann eine der größten Gaben des Lichts fokussieren: die Macht, Gefallenen das Leben zurückzugeben."},{t="Hinterhalt an der Heldenwache",b="Gazin Tenorm zeigt, warum das Symbol gebraucht wird. Er kroch nach Sturmwind zurück, nachdem Defias-Banditen ihn nahe der Heldenwache im Wald von Elwynn angegriffen hatten. Priester versorgen seine schweren Wunden am Altar der Kathedrale. Sein Gefährte Henze ist dort, wo die Gesetzlosen zuschlugen, weiterhin in Gefahr."}},faq={{q="Wer ist Gazin Tenorm?",a="Gazin Tenorm ist ein Vertrauter von Duthorian Rall. Er entkam einem Defias-Hinterhalt nahe der Heldenwache im Wald von Elwynn nur knapp und wurde mit schweren Wunden in Sturmwinds Kathedrale des Lichts gebracht. Die dortigen Priester behandeln ihn.",al={"wer ist gazin tenorm","gazin elwynn defias","verwundeter mann sturmwind altar"}},{q="Was ist das Symbol des Lebens?",a="Das Symbol des Lebens ist eine heilige Reliquie, die geduldigen und wohltätigen Paladin-Initianden anvertraut wird. Es prüft, ob ein angehender Streiter die geistige Konzentration und Standhaftigkeit besitzt, um eine der größten Gaben des Heiligen Lichts zu kanalisieren: die Wiederherstellung des Lebens.",al={"was bewirkt das symbol des lebens","symbol des lebens paladin","paladin auferstehungsartefakt"}},{q="Was geschah an der Heldenwache?",a="An der Heldenwache im Wald von Elwynn überfielen Gesetzlose der Defias Gazin Tenorm und seinen Gefährten Henze. Gazin floh mit schweren Wunden nach Sturmwind, während Henze weiterhin in Gefahr ist.",al={"wo ist die heldenwache","heldenwache elwynn defias","gazin hinterhalt ort"}},{q="Wer ist Henze?",a="Henze ist Gazin Tenorms Gefährte. Defias-Banditen griffen sie nahe der Heldenwache im Wald von Elwynn an, und Henze blieb zurück, während Gazin Sturmwind lebend erreichte.",al={"wer ist henze","henze faulk","gazin freund defias"}},{q="Wer schickt Euch zu Gazin Tenorm?",a="Duthorian Rall schickt Euch zu Gazin Tenorm. Als einer der Anführer der Paladine in Sturmwinds Kathedrale des Lichts bestätigt er zunächst, dass ein Initiand Geduld und Wohltätigkeit bewiesen hat, und schickt ihn dann zu Gazin am Altar.",al={"wer schickt zu gazin","duthorian rall tome of divinity","sturmwind paladinlehrer quest"}},{q="Warum greifen Defias-Banditen Reisende nahe der Heldenwache an?",a="Gesetzlose und Wegelagerer der Defias überfallen Reisende im gesamten Wald von Elwynn, selbst in unmittelbarer Reichweite der Hauptstadt. Der Angriff auf Gazin Tenorm zeigt, wie dreist und tödlich ihr Vorgehen geworden ist.",al={"defias bedrohung elwynn","warum sind defias nahe der heldenwache","bruderschaft der defias sturmwind"}}},fp="20,240,18.300.0,23.263.0,20.219.0,27.238.0,31.173.0,13.163.0,41.216.0,62.194.0"}
P.entries["quest:1782"] = {n="Furens Rüstung",s="In Sturmwind stellt Furen Langbart neue Rüstung auf die Probe. Ein aufstrebender Krieger sammelt Spinnenzähne, Schimärenhörner und Phlogiston für seine Versuche. Anschließend übergibt Furen dem Krieger die feuergehärtete Kettenrüstung und verspricht, seine Erkenntnisse mit den Schmieden der Allianz zu teilen.",h="In Sturmwind stellt Furen Langbart neue Rüstung auf die Probe.",kw={"krieger der allianz","schmiedekunst","fire hardened mail","furen langbart","furens rüstung","kettenrüstung","sturmwind"},ang={["class:Warrior"]="Als Krieger der Allianz verdient Ihr Euch Furens eigens gehärtete Rüstung, wenn Ihr Euren Dienst an der Front antretet. Sie bietet Schutz bei frühen Feldzügen.",["faction:Alliance"]="Schlagkräftige Waffen helfen den Streitkräften der Allianz, gegen die Defias, Gnolle und feindliche Elementarkräfte zu überleben.",["profession:Blacksmithing"]="Furens Experiment zeigt, wie Schmiede der Allianz metallurgische Erkenntnisse teilen, um ihr Handwerk in Sturmwind und Eisenschmiede zu verbessern."},sec={{t="Durchbruch eines Meisters",b="Furen Langbart, ein zwergischer Rüstungsschmied in Sturmwind, sucht nach stärkerer Rüstung für die Allianz. Er prüft, wie gut sie Hitze und wuchtigen Schlägen standhält. Für diese Versuche bittet er einen aufstrebenden Krieger, seltene Materialien zu sammeln. Die daraus gefertigte Kettenrüstung bewährt sich und festigt Furens Ansehen unter den Rüstungsschmieden der Allianz."},{t="Geteiltes Handwerkswissen",b="Furen übergibt die fertige feuergehärtete Kettenrüstung dem Krieger, der die Materialien gesammelt hat. Er ist dankbar für die Hilfe, und die Experimente haben sein Wissen um das Schmieden schützender Rüstung vertieft. Nun plant er, seine Notizen und Erkenntnisse an andere Schmiede der Allianz zu schicken, damit sie die neuen Methoden nutzen können."}},faq={{q="Wer ist Furen Langbart?",a="Furen Langbart ist ein zwergischer Rüstungsschmiedemeister in Sturmwind. Er arbeitet eng mit den kriegerischen Orden der Allianz zusammen, besonders mit Kriegern, die nach spezialisierter Rüstung suchen.",al={"wer ist furen","furen langbart","sturmwind schmied furen"}},{q="Welche Art von Rüstung hat Furen geschaffen?",a="Furen schmiedete eine Feuergehärtete Halsberge, einen Kettenbrustschutz aus seltenen Zähnen, Hörnern und Phlogiston. Sie ist darauf ausgelegt, heftigen Angriffen und extremer Hitze standzuhalten.",al={"welche rüstung stellt furen her","fire hardened mail","furens belohnung"}},{q="Wohin schickt Furen Langbart seine Erkenntnisse über das Schmieden?",a="Furen verspricht, seine Erkenntnisse und Notizen an Schmiedekollegen in der gesamten Allianz zu schicken. Er teilt die erprobten Härtungsverfahren mit Schmieden im ganzen Reich.",al={"furens notizen","wer erhält furens entwürfe","schmiede der allianz"}},{q="Warum sollte der Krieger Reagenzien für Furen sammeln?",a="Furen brauchte seltene, instabile Materialien, um neue Schmiedetechniken zu erproben. Er konnte seine Schmiede nicht verlassen, um Spinnen im Sumpfland und Schimären im Steinkrallengebirge zu jagen, also verließ er sich auf einen ehrgeizigen Krieger, sie zu sammeln.",al={"warum reagenzien für furen sammeln","fire hardened mail questmaterialien"}},{q="Wo wird diese Rüstung geschmiedet und übergeben?",a="Furen schmiedet und übergibt die Rüstung an seiner Schmiede in Sturmwind. Dort stellt er die Kettenrüstung fertig.",al={"wo ist furen langbart","abgabeort","furens standort"}},{q="Kommt diese Arbeit anderen Kämpfern der Allianz zugute?",a="Ja. Furen plant, seine Erkenntnisse mit anderen Rüstungsschmieden der Allianz zu teilen, in der Hoffnung, dass sie damit widerstandsfähige Ausrüstung für die Soldaten der Allianz herstellen.",al={"nutzen für die allianz","furens durchbruch"}}},fp="13,261,23.301.0,17.290.0,23.161.0,36.159.0,57.161.0,55.213.0,41.96.0,47.152.0"}
P.entries["quest:1783"] = {n="Der Foliant der Offenbarung",s="Ein Paladin-Initiand trägt das Symbol des Lebens an die eisigen Ufer südlich des Helmsbettsees in Dun Morogh. Dort muss der Initiand Narm Faulk finden, einen tapferen Kundschafter, der beim Aufhalten von Dunkeleisenzwergen fiel, und ihn mit dem Licht zurückrufen.",h="Ein Paladin-Initiand trägt das Symbol des Lebens an die eisigen Ufer südlich des Helmsbettsees in Dun Morogh.",kw={"dunkeleisenzwerge","dun morogh","helmsbettsee","muiredon","narm faulk","paladin","wiederbelebung","symbol des lebens","tome of divinity"},ang={["class:Paladin"]="Als Paladin stellt Ihr Euch einer Prüfung des Lichts. Das Symbol des Lebens lässt Euch einen gefallenen Verbündeten wiederbeleben.",["faction:Alliance"]="Als Mitglied der Allianz helft Ihr, Zwergenkundschafter zu schützen und heilige Schriften vor den Dunkeleisenzwergen zu bewahren.",["race:Dwarf"]="Als Zwerg stellt Ihr Euch den Dunkeleisenzwergen, die sich südlich des Helmsbettsees in Dun Morogh verschanzt haben."},sec={{t="Hinterhalt am See",b="Südlich des Helmsbettsees beobachteten die Zwergenkundschafter Muiredon und Narm Faulk, wie Dunkeleisenzwerge sich verschanzten. Als sie einen feindlichen Kommandanten sahen, der Befehle erteilte, griffen sie mehrere Feinde an und versuchten, eine Schrift zu sichern. Die Dunkeleisenzwerge überwältigten sie mit unerwarteter Wildheit. Muiredon floh, um Verstärkung zu holen, während Narm die Stellung hielt."},{t="Ein Test of Faith",b="Mit dem Symbol des Lebens sucht ein Paladin-Initiand in den verschneiten Weiten von Dun Morogh nach Narm Faulk. Narm fiel unter dem Ansturm der Dunkeleisenzwerge, doch das heilige Relikt ruft seinen Geist zurück, gerade als das Licht ihn vollends aufnehmen wollte. In diesem Moment folgt der Initiand dem ersten Ruf eines Paladins: den Gefallenen das Leben zurückzugeben."}},faq={{q="Welchen Zweck hat diese Quest?",a="The Tome of Divinity stellt die Hingabe und Würdigkeit eines jungen Paladins auf die Probe. Ein Initiand erhält das Symbol des Lebens und wird ausgesandt, einen gefallenen Kundschafter zu retten und ihn mithilfe des Lichts vom Tod zurückzuholen.",al={"was ist the tome of divinity","tome of divinity zweck","paladin wiederbelebungsquest"}},{q="Wer ist Narm Faulk?",a="Narm Faulk ist ein Kundschafter der Allianz, der südlich des Helmsbettsees in einen Hinterhalt der Dunkeleisenzwerge geriet. Er verzichtete auf seine Chance zur Flucht, damit sein Gefährte Muiredon entkommen konnte, und fiel im Kampf, bevor das Licht ihn wiederbelebte.",al={"wer ist narm faulk","wo ist narm","gefallener zwerg narm"}},{q="Wer ist Muiredon?",a="Muiredon ist der Kundschafter, der auf Narm Faulks Drängen aus dem Hinterhalt der Dunkeleisenzwerge floh. Er kehrt zurück, um Verstärkung zu holen, und weist den Paladin an, seinen gefallenen Kameraden mit dem Symbol des Lebens zu retten.",al={"wer ist muiredon","questgeber muiredon","wer vergibt die quest"}},{q="Was ist das Symbol des Lebens?",a="Tiza und Muiredon übergeben dem Paladin das Symbol des Lebens zusammen mit Anweisungen. Dieses heilige Relikt kann Tote wiederbeleben, wenn ein würdiger Diener des Lichts seine Macht kanalisiert.",al={"was ist das symbol des lebens","wiederbelebungsgegenstand","symbol des lebens hintergrundgeschichte"}},{q="Was taten Narm und Muiredon nahe dem Helmsbettsee?",a="Muiredon und Narm Faulk spionierten Dunkeleisenzwerge aus, die sich südlich des Helmsbettsees verschanzt hatten. Sie sahen einen feindlichen Anführer, der Befehle erteilte, und versuchten, heilige Schriften zu bergen, bevor die Zwerge sie überwältigten.",al={"was taten sie südlich des helmsbettsees","warum dunkeleisenzwerge ausspionieren","dunkeleisenzwerge helmsbettsee"}},{q="Wer ist Tiza?",a="Tiza hilft dabei, Hilfe zu entsenden, und bereitet mit Muiredon das Symbol des Lebens für die Rettung vor.",al={"wer ist tiza","tiza paladin"}}},fp="20,236,18.335.0,15.323.1,34.200.0,18.205.0,16.181.0,27.175.0,55.206.0,12.85.0"}
P.entries["quest:1784"] = {n="Der Foliant der Offenbarung",s="In Dun Morogh brauchen verletzte Späher Hilfe, um Dunkeleisenspione nahe dem Helmsbettsee zu entlarven. Ihre Befehle könnten den skeptischen Rat von Eisenschmiede dazu bewegen, die Gefahr ernst zu nehmen.",h="In Dun Morogh brauchen verletzte Späher Hilfe, um Dunkeleisenspione nahe dem Helmsbettsee zu entlarven.",kw={"dunkeleisenzwerge","dunkeleisenmanuskript","dun morogh","helmsbettsee","eisenschmiede","muiredon battleforge","narm faulk","tome of divinity"},ang={["class:Paladin"]="Als Paladin stellt Ihr Euch in Tome of Divinity einer frühen Prüfung. Der Schutz des Königreichs und die Rettung von Kameraden in Not zeigen Eure Hingabe an das Licht.",["faction:Alliance"]="Für die Allianz schützt die Aufdeckung von Dunkeleisensabotage nahe Eisenschmiede die Zwergenhauptstadt und stärkt die Verteidigung im Norden gegen verdeckte Bedrohungen.",["race:Dwarf"]="Für Zwerge ist die Entlarvung von Dunkeleisenspionen nahe Eisenschmiede entscheidend für die Verteidigung des Königreichs. Sie beweist skeptischen Ratsherren, dass ein alter Feind nach Dun Morogh eingedrungen ist."},sec={{t="Eine Prüfung des Dienstes",b="Junge Zwergenpaladine folgen dem Ruf, Dun Morogh zu verteidigen, als eine Expedition nahe dem Helmsbettsee schiefgeht. Narm Faulk und Muiredon Battleforge brachen auf, um Dunkeleisenspähern einen Hinterhalt zu legen. Narm wurde verwundet, während Muiredon zur Genesung nach Eisenschmiede zurückkehrte."},{t="Beweise für den Rat",b="Gerüchte über Dunkeleiseninfiltratoren haben Eisenschmiede erreicht, doch einige Ratsmitglieder wollen nicht glauben, dass sie nach Dun Morogh eingedrungen sind. Nahe Helmsbett kann der Paladin die Spione aufspüren und ein Dunkeleisenmanuskript von ihrem Hauptmann erbeuten. Die Befehle liefern Beweise für feindliche Bewegungen und Verschwörungen nahe den Toren der Hauptstadt."},{t="Schutz für die Heimat",b="Die Übergabe der abgefangenen Befehle an Muiredon Battleforge in Eisenschmiede bringt Erleichterung. Narm wurde gerettet, und die Dokumente gehen an Muiredons Frau, damit sie diese dem Rat vorlegt. Die Tapferkeit des Paladins und seine Hingabe an das Licht helfen, das Zwergenreich vor verborgenem Verrat zu schützen."}},faq={{q="Wer vergibt die Quest The Tome of Divinity?",a="Narm Faulk beauftragt Euch, feindliche Schriftstücke zu beschaffen und seinem Gefährten Muiredon Battleforge in Eisenschmiede Bericht zu erstatten. Er ist ein verletzter Zwerg, der im Kampf gegen Dunkeleisenspione nahe dem Helmsbettsee verwundet wurde.",al={"wer vergibt diese quest","tome of divinity questgeber","wer ist narm"}},{q="Wer ist Muiredon Battleforge?",a="Muiredon Battleforge ist ein Zwerg in Eisenschmiede. Er kundschaftete mit Narm Faulk die Dunkeleisenspione nahe dem Helmsbettsee aus und kehrte dann in die Stadt zurück, um seine Wunden auszukurieren.",al={"wer ist muiredon battleforge","wo ist muiredon","muiredon battleforge aufenthaltsort"}},{q="Was ist das Dunkeleisenmanuskript?",a="Das Dunkeleisenmanuskript enthält schriftliche Befehle, die zwischen Dunkeleisenspionen und ihrem Hauptmann nahe dem Helmsbettsee weitergegeben werden. Es liefert dem skeptischen Rat von Eisenschmiede Beweise für das Eindringen feindlicher Kräfte.",al={"was ist das dunkeleisenmanuskript","warum das dunkeleisenmanuskript beschaffen","dunkeleisenmanuskript zweck"}},{q="Warum braucht der Rat in Eisenschmiede Beweise für die Dunkeleisenzwerge?",a="Einige Mitglieder des Rates von Eisenschmiede bezweifeln, dass Dunkeleisenzwerge nach Dun Morogh eingedrungen sind. Die beschafften Schriftstücke belegen ihre Bewegungen und enthüllen ihre geheimen Pläne.",al={"warum leugnet der rat die dunkeleisenzwerge","eisenschmiede rat dunkeleisenbeweise"}},{q="Wo befinden sich die Dunkeleisenspione?",a="Die Dunkeleisenspione operieren nahe dem Helmsbettsee im östlichen Dun Morogh, östlich von Kharanos. Sie sind bei einem kleinen Haus tätig und geben geheime Kampfbefehle weiter.",al={"wo ist der helmsbettsee","helmsbett dunkeleisenzwerge","dunkeleisenzwerge aufenthaltsort dun morogh"}},{q="Welche Rolle spielt diese Quest für Paladine?",a="Die Prüfungen von The Tome of Divinity stellen die Dienstbereitschaft, das Mitgefühl und den Mut eines angehenden Paladins auf die Probe. Indem Ihr gefallenen Kameraden wie Narm helft und Dun Morogh verteidigt, beweist Ihr Eure Hingabe an das Licht.",al={"was lehrt the tome of divinity","paladin tome of divinity hintergrundgeschichte"}}},fp="20,162,18.251.0,21.312.0,19.277.1,37.199.0,28.168.0,29.193.0,63.159.0,38.149.0,44.192.0"}
P.entries["quest:1785"] = {n="Der Foliant der Offenbarung",s="In Eisenschmiede stehen heilige Streiter vor einer letzten Prüfung bei Tiza Kriegshammer. The Tome of Divinity zeigt, ob sie bereit sind, das Symbol des Lebens zu führen und gefallene Verbündete ins Leben zurückzurufen.",h="In Eisenschmiede stehen heilige Streiter vor einer letzten Prüfung bei Tiza Kriegshammer.",kw={"eisenschmiede","paladin","redemption","auferstehung","symbol des lebens","the tome of divinity","tiza kriegshammer","tome of divinity"},ang={["class:Paladin"]="Als Paladin vollzieht Ihr einen heiligen Ritus in Eisenschmiede und empfangt die Macht des Lichts, die Gefallenen zu erwecken.",["faction:Alliance"]="Als Streiter der Allianz schult Ihr Euch im Licht, um der Geißel und dem Dunkeleisenclan entgegenzutreten.",["race:Dwarf"]="Als Zwerg stellt Ihr Euch dieser Prüfung in Eisenschmiede und erwerbt Euch den Dank der Familie Kriegshammer im Namen des Königreichs."},sec={{t="Ein heiliger Ritus in Eisenschmiede",b="Ihr habt die Prüfungen des Königreichs bestanden und kommt nun zu Tiza Kriegshammer in Eisenschmiede. Sie ist eine verehrte Lehrerin der heiligen Künste. Ihr Gatte sieht stolz zu, wie Ihr näher kommt, und erwartet sehnlich, dass das Zwergenvolk Eure Bereitschaft vor dem Heiligen Licht anerkennt."},{t="Der Segen der Auferstehung",b="Tiza Kriegshammers letzter Segen prüft, ob Euer Herz bereit ist, das Symbol des Lebens zu führen. Das Relikt antwortet nur jemandem, der bereit ist, die größten Gaben des Lichts zu kanalisieren. Beweist Eure Würdigkeit, und Tiza gewährt Euch eine heilige Schriftrolle, mit der Ihr gefallene Kameraden aus dem Tod zurückrufen könnt. Eisenschmiede braucht diese Macht gegen die Geißel und den Dunkeleisenclan."}},faq={{q="Was ist The Tome of Divinity?",a="The Tome of Divinity ist eine heilige Prüfung für heilige Streiter in Eisenschmiede. Indem Ihr Eure geistige Bereitschaft beweist, lernt Ihr, das Licht zu kanalisieren und gefallene Gefährten ins Leben zurückzubringen.",al={"was ist tome of divinity","tome of divinity quest","was bewirkt diese quest"}},{q="Wer ist Tiza Kriegshammer?",a="Tiza Kriegshammer ist eine verehrte zwergische Lehrerin des Lichts in Eisenschmiede. Sie erteilt Streitern den letzten Segen, wenn sie bereit sind, die Macht der Auferstehung zu führen.",al={"wer ist tiza kriegshammer","wo ist tiza kriegshammer","tiza kriegshammer finden"}},{q="Wer schickt Euch zu Tiza Kriegshammer?",a="Nachdem Ihr eine frühere Prüfung im Feld bestanden habt, weist Tiza Kriegshammers Gatte Euch den Weg zu ihr. Er ist bereits in Eisenschmiede und schickt Euch voller Stolz und mit ermutigenden Worten zu seiner Frau.",al={"wer vergibt diese quest","tizas gatte","wer hat mich zu tiza geschickt"}},{q="Was ist das Symbol des Lebens?",a="Das Symbol des Lebens ist ein heiliger Gegenstand, der bei den Prüfungen eines Paladins verwendet wird. Es antwortet nur einem Streiter, dessen Hingabe ihn würdig macht, einen gefallenen Verbündeten aus dem Tod zurückzurufen.",al={"was ist das symbol des lebens","symbol des lebens paladin","wie funktioniert auferstehung"}},{q="Welche Fähigkeit erlernt Ihr durch den Abschluss dieser Quest?",a="Wenn Ihr vor Tiza Kriegshammer tretet, segnet sie Euch mit einer heiligen Schriftrolle, die Euch Redemption lehrt, die Macht, gefallene Verbündete ins Leben zurückzubringen.",al={"welche macht erlerne ich","auferstehungszauber quest","paladin wiederbelebungsquest"}},{q="Warum braucht Eisenschmiede Streiter des Lichts?",a="Eisenschmiede braucht Streiter des Lichts gegen die Geißel und die Zwerge des Dunkeleisenclans. Ihre Heilung und ihre heilige Verteidigung helfen, das Reich zu schützen.",al={"wer sind eisenschmiedes feinde","warum gegen dunkeleisenclan und geißel kämpfen","feinde auf dem schlachtfeld"}}},fp="20,187,26.262.0,28.351.0,29.181.0,24.156.0,34.179.0,27.163.0,53.152.0,51.140.0"}
P.entries["quest:1786"] = {n="Der Foliant der Offenbarung",s="In Elwynn werden Glaube und Opferbereitschaft geprüft, als Henze Faulk bei einem Hinterhalt der Defias an der Heldenwache stirbt. Mit dem Symbol des Lebens werdet Ihr entsandt, um ihn wiederzubeleben und die Pläne der Bruderschaft zu durchkreuzen.",h="In Elwynn werden Glaube und Opferbereitschaft geprüft, als Henze Faulk bei einem Hinterhalt der Defias an der...",kw={"defias","duthorian","gazin","henze faulk","heldenwache","paladin","auferstehung","der steinhügelsee","symbol des lebens","tome of divinity"},ang={["class:Paladin"]="Als Paladin beweist Ihr Euren Glauben und Eure Verbundenheit mit dem Licht, indem Ihr mit dem Symbol des Lebens einen gefallenen Verbündeten wiederbelebt.",["faction:Alliance"]="Zauberwirker der Defias im Nordosten Elwynns bedrohen Sturmwinds Kernland. Informationen an der Heldenwache zu sammeln, ist für die Allianz von Bedeutung."},sec={{t="Hinterhalt an der Heldenwache",b="Henze Faulk und Gazin reisten zur Heldenwache, nachdem sie erfahren hatten, dass Agenten der Bruderschaft der Defias in den nordöstlichen Wald von Elwynn eingedrungen waren. Die Insel liegt mitten im Steinhügelsee. Die Späher suchten Beweise für die königlichen Berater des Königs und versuchten deshalb, zwei Verschwörern beim Prüfen ihrer Pläne einen Hinterhalt zu legen.\n\nBald griffen Zauberwirker der Defias in den Kampf ein, und die Späher wurden überwältigt. Henze hielt den Magiern stand und opferte sich, um Gazin Zeit zu verschaffen, mit dem Leben davonzukommen."},{t="Die Gabe der Auferstehung",b="Gewöhnliche Medizin kann Henze nicht wiederbeleben; das vermag nur das Heilige Licht. Mit dem Symbol des Lebens werdet Ihr entsandt, um seinen gefallenen Körper auf der Insel im Steinhügelsee zu finden.\n\nEuer Glaube, durch das heilige Artefakt gebündelt, erweckt Henze wieder zum Leben. Diese Prüfung zeigt die spirituelle Verbundenheit eines Paladins und seine Bereitschaft, dem Licht bei der Verteidigung Sturmwinds zu dienen."}},faq={{q="Wer ist Henze Faulk?",a="Henze Faulk ist ein Verteidiger, der mit Gazin zur Heldenwache im Steinhügelsee zog, um Beweise für das Eindringen der Defias zu finden. Er hielt die Magier auf, damit Gazin entkommen konnte, und fiel ihren Zaubern zum Opfer. Das Symbol des Lebens erweckte ihn später wieder zum Leben.",al={"wer ist henze faulk","henze faulk","wo ist henze"}},{q="Wo liegt die Heldenwache?",a="Die Heldenwache ist eine Insel mitten im Steinhügelsee im nordöstlichen Wald von Elwynn. Magier und Schurken der Defias haben dort einen Außenposten errichtet, wo sie über Plänen brüten.",al={"wo liegt die heldenwache","heldenwache lage","heldenwache insel"}},{q="Was ist das Symbol des Lebens?",a="Das Symbol des Lebens ist ein heiliger Gegenstand, der den Glauben eines Paladins bündelt, um Gefallene wiederzubeleben. Es erfordert wahre spirituelle Überzeugung, weshalb sein Einsatz bei Henze Faulk die Berufung eines Paladins auf die Probe stellt.",al={"was ist das symbol des lebens","wie henze wiederbeleben","symbol des lebens verwenden"}},{q="Wer leitet die Rettung von Henze Faulk?",a="Gazin Tenorm bittet um Hilfe, nachdem er den Defias auf der Insel entkommen ist. Verwundet liegt er nahe dem Altar in Sturmwinds Kathedrale des Lichts. Er ist ein Freund von Duthorian Rall, dem Anführer der Paladine, der den Initianden zu ihm geschickt hat.",al={"wer schickt zu henze","duthroian oder gazin","questgeber tome of divinity"}},{q="Was tun die Defias an der Heldenwache?",a="Agenten der Defias sind in den Nordosten Elwynns eingedrungen und haben sich an der Heldenwache versammelt, um Dokumente zu studieren und ihre Unternehmungen abzustimmen. Henze und Gazin suchten diese Dokumente als Beweise für die Berater des Königs.",al={"warum defias an der heldenwache","was tun die defias am steinhügelsee","defias pläne elwynn"}},{q="Warum gingen Henze und Gazin zum Steinhügelsee?",a="Henze Faulk und Gazin gingen zum Steinhügelsee, nachdem sie Berichte über eingedrungene Defias gehört hatten. Sie wollten den Verschwörern einen Hinterhalt legen und schriftliche Beweise für deren Pläne beschaffen, bestimmt für die Berater von König Anduin in Sturmwind.",al={"warum waren henze und gazin dort","henze und gazin auftrag"}}},fp="20,195,23.494.0,24.340.1,19.238.0,23.171.0,27.185.0,38.217.0,43.210.0,47.212.0"}
P.entries["quest:1787"] = {n="Der Foliant der Offenbarung",s="Ihr beweist Eure Hingabe an das Licht in einer Prüfung für Paladine der Allianz. Nachdem Ihr einem verletzten Späher im Wald von Elwynn geholfen habt, stellt Ihr Euch Defias Rogue Wizards und sucht Papiere, die das Reich bedrohen.",h="Ihr beweist Eure Hingabe an das Licht in einer Prüfung für Paladine der Allianz.",kw={"defias rogue wizards","schrift der defias","wald von elwynn","gazin tenorm","henze faulk","heldenwache","paladin quest","tome of divinity"},ang={["class:Paladin"]="Als Paladin stellt Ihr Euch einer Prüfung Eurer Hingabe und Eures Mutes. Sie prüft Eure Entschlossenheit, die Unschuldigen zu schützen und das Licht gegen Bedrohungen wie die Bruderschaft der Defias zu verteidigen.",["faction:Alliance"]="Als Mitglied der Allianz helft Ihr, Bewegungen und Dokumente der Defias im Wald von Elwynn aufzudecken. Diese Informationen gehen an die Verteidiger von Sturmwind."},sec={{t="Die Prüfung eines Paladins",b="Als angehender Paladin werdet Ihr im Wald von Elwynn auf die Probe gestellt. Henze wurde verletzt, als er unerlaubte Aktivitäten auf einer Insel beobachtete. Helft ihm herauszufinden, wie weit sich die Defias dort ausgebreitet haben."},{t="Eindringlinge in Elwynn",b="Henze entdeckte Defias Rogue Wizards, die auf der Insel geheime Papiere studierten, doch seine Verletzungen hindern ihn am Kämpfen. Ihr werdet ausgesandt, um die abtrünnigen Zauberwirker zu besiegen und ihre Schrift zu beschaffen. Bringt die Informationen dann sicher zu Gazin Tenorm nach Sturmwind."},{t="Die Verteidigung des Königreichs",b="Die Schrift der Defias bestätigt, dass die Bruderschaft nahe gelegene Gebiete bedroht, darunter die Heldenwache. Bringt die gestohlenen Informationen zur Kathedrale des Lichts. Eure Rückkehr beweist Eure Hingabe an das Licht und dass Henze überlebt hat."}},faq={{q="Wer ist an dieser Quest beteiligt?",a="Ihr begegnet Henze Faulk, der verletzt auf einer Insel im Wald von Elwynn liegt. Meldet Euch danach bei Gazin Tenorm in der Kathedrale des Lichts in Sturmwind.",al={"wer vergibt diese quest","wer vergibt tome of divinity","wo gibt es tome of divinity"}},{q="Wer ist Henze?",a="Henze ist ein Verbündeter bei den Paladinprüfungen, der verletzt wurde, als er Aktivitäten der Defias beobachtete. Da er nicht kämpfen kann, schickt er Euch los, um Beweise für die Unterwanderung durch die Bruderschaft zu sichern.",al={"wer ist henze","henze faulk hintergrundgeschichte","wer ist der verletzte mann"}},{q="Wer ist Gazin Tenorm?",a="Gazin Tenorm ist Henzes Freund und ein Freund von Duthorian Rall. Er ist nahe dem Altar in der Kathedrale des Lichts in Sturmwind zu finden. Er ist den Defias bei der Heldenwache nur knapp entkommen und möchte wissen, dass Henze in Sicherheit ist.",al={"wer ist gazin tenorm","wo ist gazin tenorm","gazin sturmwind"}},{q="Warum sind Defias Rogue Wizards auf der Insel tätig?",a="Die Bruderschaft der Defias hat im gesamten Wald von Elwynn Stellungen. Ihre abtrünnigen Zauberer studieren Pläne und koordinieren Einsätze, und ihre Dokumente zeigen, was sie in der Region vorhaben.",al={"warum sind defias in elwynn","defias rogue wizards","schrift der defias"}},{q="Was ist die Heldenwache?",a="Die Heldenwache ist ein Ort im Wald von Elwynn, der durch die Einsätze der Defias bedroht wird. Gazin Tenorm hofft, sie vor weiterem Schaden zu bewahren, indem die abtrünnigen Zauberer in der Nähe aufgehalten und ihre Papiere beschafft werden.",al={"was ist die heldenwache","heldenwache elwynn","ist die heldenwache sicher"}},{q="Was ist die Schrift der Defias?",a="Die Schrift der Defias besteht aus schriftlichen Befehlen oder Briefwechseln, die Defias Rogue Wizards bei sich tragen. Sie beweist ihre Unterwanderung und beschreibt ihre unmittelbar bevorstehenden Vorhaben im Wald von Elwynn.",al={"was ist die schrift der defias","was sind die papiere","defias papiere elwynn"}}},fp="20,201,17.181.0,22.251.1,21.219.1,30.143.0,13.167.0,20.207.0,53.176.0,22.187.0,26.169.0"}
P.entries["quest:1788"] = {n="Der Foliant der Offenbarung",s="In Sturmwind stellen sich Paladine in The Tome of Divinity einer Glaubensprüfung. Ein Initiand beweist seine Beherrschung des Symbols des Lebens, indem er einen gefallenen Verbündeten wiederbelebt, und erhält dann Duthorian Ralls Segen zur Wiederbelebung.",h="In Sturmwind stellen sich Paladine in The Tome of Divinity einer Glaubensprüfung.",kw={"duthorian","duthorian rall","henze","paladin","wiederbelebung","sturmwind","symbol des lebens","the tome of divinity","tome of divinity"},ang={["class:Paladin"]="Für Euch als Paladin markiert diese Prüfung den Übergang zum wahren Dienst am Licht. Ihr meistert die heilige Macht, gefallene Gefährten ins Leben zurückzuholen.",["faction:Alliance"]="Als Verteidiger der Allianz werdet Ihr unter den Paladinen von Sturmwind an der Kathedrale des Lichts ausgebildet. Ihre Arbeit bewahrt das Leben der Verteidiger der Allianz und stärkt die Verteidigung des Königreichs."},sec={{t="Rückkehr zur Kathedrale",b="Nachdem ein angehender Paladin den gefallenen Henze im Feld mit dem Symbol des Lebens wiederbelebt hat, kehrt er zur Kathedrale des Lichts in Sturmwind zurück. Die von der Insel geborgenen Defias-Papiere sollen über Gazin Tenorm an die Berater des Königs gelangen. Zunächst erwartet Duthorian Rall die Nachricht vom Erfolg des Initianden."},{t="Die Gabe der Wiederbelebung",b="Das Licht anzurufen, um die Toten wiederzubeleben, ist keine geringe Gabe. Für Duthorian Rall beweist die Beherrschung des Symbols des Lebens, dass ein Initiand den Glauben und die geistige Stärke für eine der höchsten Berufungen des Paladinordens besitzt: die Wiederbelebung. Mit der Beherrschung dieses Ritus kann der Paladin Verbündete auf Schlachtfeldern im gesamten Königreich beschützen."}},faq={{q="Was ist The Tome of Divinity?",a="The Tome of Divinity ist eine abschließende Prüfung für Paladine, die lernen, das Heilige Licht zu wirken. Hier erstattet ein Initiand Duthorian Rall Bericht, nachdem er bewiesen hat, dass er das Licht kanalisieren kann, um Gefallene wiederzubeleben.",al={"tome of divinity","was ist diese quest","tome of divinity paladin"}},{q="Wer ist Duthorian Rall?",a="Duthorian Rall ist ein hochrangiger Paladinlehrer an der Kathedrale des Lichts in Sturmwind. Er beaufsichtigt die Paladininitianden und beurteilt, ob sie bereit sind, heilige Riten zu wirken.",al={"wer ist duthorian","duthorian rall rolle","wo ist duthorian"}},{q="Was ist das Symbol des Lebens?",a="Das Symbol des Lebens ist ein heiliger Fokus, mit dem das Licht angerufen wird, um die Toten wiederzubeleben. Seine Macht zu meistern beweist, dass ein Initiand bereit ist, die Wiederbelebungskraft des Paladins einzusetzen.",al={"symbol des lebens zweck","was bewirkte das symbol des lebens"}},{q="Wer war Henze?",a="Henze ist ein Verbündeter, der im Feld fiel und während der Prüfungen eines Initianden mit dem Symbol des Lebens wiederbelebt wurde. Die Tat zeigte die Entschlossenheit und den Glauben des Paladins, den Tod rückgängig zu machen.",al={"wer ist henze","henze geschichte","henze paladinquest"}},{q="Wie erlangt ein Paladin die Macht der Wiederbelebung?",a="Die Wiederbelebung ist eine der höchsten Ehren eines Paladins. Durch tiefen Glauben und Einklang mit dem Heiligen Licht lernt ein Paladin, gefallene Gefährten von der Schwelle des Todes zurückzurufen.",al={"paladin wiederbelebung hintergrund","wie beleben paladine wieder"}},{q="Warum wird das Schriftstück zu den Beratern des Königs gebracht?",a="Bei dem Schriftstück handelt es sich um die Defias-Papiere von der Insel. Sobald Duthorian Rall sie durchgesehen hat, wird Gazin Tenorm sie zu den Beratern des Königs bringen, als Beweis dafür, dass die Defias Elwynn unterwandert haben.",al={"berater des königs schriftstück","welches schriftstück geht nach sturmwind"}}},fp="20,206,23.298.0,24.328.0,29.203.0,22.163.0,27.176.0,14.174.0,50.175.0,53.198.0"}
P.entries["quest:179"] = {n="Zwergenausstatter",s="Im Coldridgetal bietet Sten Starkarm neuen Rekruten einen Handel an. Jagt Wölfe wegen ihres zähen Fleisches, und er versorgt Euch mit robusten Handschuhen gegen die Kälte Dun Moroghs.",h="Im Coldridgetal bietet Sten Starkarm neuen Rekruten einen Handel an.",kw={"ambossar","das coldridgetal","dun morogh","zwergenausstatter","erfrierungen","handschuhe","sten starkarm","zähes wolfsfleisch"},ang={["race:Dwarf"]="Als junger Bronzebeard-Zwerg im Coldridgetal lernt Ihr, das Lager zu versorgen und die Kälte der Berge zu achten.",["race:Gnome"]="Als Gnom, der bei seinen zwergischen Vettern in Dun Morogh Zuflucht sucht, braucht Ihr neben einem scharfen Verstand zweckmäßige Bergkleidung, um Ambossars Kälte zu überstehen."},sec={{t="Ein fairer Handel in Coldridge",b="Die Kälte erreicht jeden Pfad durch das Coldridgetal. Vor Ambossar bittet Sten Starkarm neue Rekruten, in den Schneewehen Wölfe zu jagen und ihr zähes Fleisch zum Außenposten zu bringen. Im Gegenzug gibt er ihnen Handschuhe, die ihre Hände vor der Kälte schützen."},{t="Von den Gaben des Tals",b="Wölfe bedrohen die Zwergenspäher und die jungen Gnome, die im Tal ausgebildet werden. Doch sie ernähren auch die Garnison in Ambossar. Die Jagd auf sie macht die Pfade zwischen den örtlichen Lagern etwas sicherer. Starkarms Handel stellt Rekruten im Kampf gegen die heimische Tierwelt auf die Probe und liefert Nahrung für die kommenden bitterkalten Nächte."}},faq={{q="Wer ist Sten Starkarm?",a="Sten Starkarm ist ein Zwerg, der vor Ambossar im Coldridgetal stationiert ist. Er kümmert sich um neu eingetroffene Rekruten und bietet ihnen praktische Ausrüstung im Austausch für die Jagd auf heimisches Wild.",al={"sten starkarm","wer vergibt zwergenausstatter","ambossar ausstatter"}},{q="Warum braucht Sten Wolfsfleisch?",a="Der Außenposten von Ambossar ist auf die Jagd vor Ort angewiesen, um seine Vorräte aufzufüllen. Wolfsfleisch ernährt die Truppen und Ausbilder, die in dem abgeschiedenen, verschneiten Tal leben.",al={"warum wolfsfleisch","zähes wolfsfleisch","wofür ist das fleisch"}},{q="Wo findet Ihr die Wölfe für diese Aufgabe?",a="Wölfe durchstreifen die verschneiten Lichtungen im gesamten Coldridgetal, besonders jenseits des Haupthofs von Ambossar und entlang der Pfade zu den entlegenen Lagern.",al={"wo sind wölfe","wölfe fundorte coldridge","wo fleisch bekommen"}},{q="Welche Belohnung bietet Sten?",a="Sten gibt Rekruten ein Paar warme Handschuhe, die ihre Hände vor den eisigen Winden Dun Moroghs schützen.",al={"zwergenausstatter belohnung","welche handschuhe gibt es","questbelohnung"}},{q="Gilt Wolfsfleisch unter Zwergen als gutes Essen?",a="Wolfsfleisch ist zäh, grob und schwer zu kauen, doch im rauen Bergklima Dun Moroghs schätzen Zwerge herzhafte, sättigende Kost mehr als erlesene Speisen. Geschmort oder über einem Lagerfeuer gebraten ernährt es die Garnison.",al={"ist wolfsfleisch lecker","zwerg wolfsfleisch","wolf essen"}},{q="Können auch Gnome diese Quest erledigen?",a="Ja. Gnome, die im Coldridgetal an der Seite ihrer zwergischen Verbündeten ausgebildet werden, trotzen denselben beißenden Winden und brauchen warme Kleidung.",al={"gnom zwergenausstatter","können gnome handschuhe bekommen","gnom kaltes wetter"}}},fx={cf6e8786={q="Was machen die Wölfe im Coldridgetal?",a="Zerlumpte junge Wölfe und zerlumpte Holzwölfe streifen als einheimische Raubtiere durch die gefrorenen Klippen des Coldridgetals. Obwohl sie ein natürlicher Teil der rauen Gebirgsökologie von Dun Morogh sind, macht sie ihr aggressives Herumstreunen direkt vor Ambossar zu einer ständigen Plage für junge Rekruten und zu einer praktischen Quelle für frische Vorräte für den Außenposten.",al={"warum sind hier wölfe","coldridgetal wölfe","wolfbedrohung dun morogh"}}},fp="18,156,25.245.0,21.291.0,21.170.0,29.156.0,43.147.0,30.94.0,48.192.0,29.122.0"}
P.entries["quest:1791"] = {n="Der Windbehüter",s="Im Norden suchen Krieger, die die Berserkerhaltung meistern, den Windbehüter. Nach dem Ringkampf auf Prügel-Eiland schickt Klannoc Macleod sie los, eine Waffe zu finden, die ihres Zorns würdig ist.",h="Im Norden suchen Krieger, die die Berserkerhaltung meistern, den Windbehüter.",kw={"alteracgebirge","bath'rah","berserkerhaltung","cyclonian","prügel-eiland","klannoc macleod","tarrens mühle","the affray","der windbehüter"},ang={["class:Warrior"]="Als Krieger habt Ihr auf Prügel-Eiland die Berserkerhaltung gemeistert. Nun sucht Ihr eine mächtige Waffe, die mithilfe elementarer Handwerkskunst geschmiedet wird.",["race:Troll"]="Als Troll könnt Ihr sehen, wie Trollschamanen und Waffenschmiede inmitten der zerfallenen Ruinen Lordaerons mystisches Wissen bewahren. Krieger jeder Herkunft verehren dieses Wissen."},sec={{t="Eine Waffe für einen Berserker",b="Ihr habt den Ringkampf auf Prügel-Eiland überstanden und von Klannoc Macleod die Berserkerhaltung erlernt. Nun schickt er Euch über Kontinente hinweg, weit fort von der Küste des Brachlands, um einen einsamen Handwerker zu finden, der eine außergewöhnliche Waffe schmieden kann."},{t="The Hermit am Flussufer",b="Bath'rah der Windbehüter lebt am Fluss, der nach Norden an Tarrens Mühle vorbeifließt. Sein Lager liegt zwischen steinernen Ruinen in umkämpftem Land zwischen dem Alteracgebirge und den verseuchten Westlichen Pestländern. Der Trolleinsiedler fertigt Waffen und beherrscht mächtigen Elementarschamanismus. Er wartet auf Krieger, die entschlossen sind, eine Waffe von großer Macht zu schmieden."}},faq={{q="Wer schickt Euch zum Windbehüter?",a="Klannoc Macleod schickt Euch nach Norden, nachdem Ihr den Affray auf Prügel-Eiland überstanden und die Berserkerhaltung erlernt habt.",al={"questgeber","wer vergibt der windbehüter","klannoc macleod quest"}},{q="Wer ist Bath'rah der Windbehüter?",a="Bath'rah ist ein Trolleinsiedler, meisterhafter Waffenschmied und mächtiger Schamane, der in der Wildnis zwischen dem Alteracgebirge und den Westlichen Pestländern lebt.",al={"wer ist bathrah","bathrah der windbehüter hintergrund","bath'rahs identität"}},{q="Wo genau befindet sich Bath'rah?",a="Bath'rah lagert bei uralten Ruinen am Ostufer des Flusses, der nach Norden an Tarrens Mühle vorbeifließt, nahe der Grenze zwischen Alterac und den Westlichen Pestländern.",al={"wo ist bath'rah","bathrah aufenthaltsort","bathrah finden"}},{q="Warum schickt Klannoc Krieger zu Bath'rah?",a="Klannoc Macleod schickt Krieger zu Bath'rah, weil jene, die die Berserkerhaltung meistern, eine außergewöhnliche Waffe brauchen. Bath'rah versteht sich sowohl auf das Schmieden als auch auf Elementarschamanismus.",al={"warum zu bathrah gehen","was ist der zweck dieser quest","windbehüter zweck"}},{q="Was folgt nach dem Gespräch mit Bath'rah?",a="Nach dem Gespräch mit Bath'rah stellt Ihr Euch dem Elementar Cyclonian und sammelt seltene Materialien, um eine mächtige Waffe zu fertigen.",al={"was folgt nach dem windbehüter","cyclonian nächste quest","windbehüter fortsetzung"}},{q="Ist diese Reise für Reisende aus dem Brachland sicher?",a="Die Reise ist gefährlich. Ihr reist durch das Vorgebirge des Hügellands in die umkämpften nördlichen Lande, wo Euch Verstecke des Syndikats, aggressive Raubtiere der Berge und die tödliche Seuche der Westlichen Pestländer bedrohen.",al={"ist es gefährlich","tarrens mühle fluss gefahr"}}},fx={ff43a27e={q="Warum schickt Klannoc Euch zu Bath'rah, anstatt selbst zu gehen?",a="Klannoc Macleod sucht nicht für sich selbst nach einer legendären Waffe; er dient als erfahrener Mentor auf den Übungsplätzen auf dem Prügel-Eiland. Da er gesehen hat, wie Ihr The Affray überlebt und die Berserkerhaltung gemeistert habt, glaubt er, dass Ihr bereit für eine Waffe seid, die Eurem neu entfesselten Zorn würdig ist. Die lange Pilgerreise zu dem weit entfernten Einsiedler Bath'rah ist eine Prüfung für die eigene Entschlossenheit und das Wachstum eines Kriegers.",al={"warum ich the windwatcher","warum krieger senden","warum klannoc spieler sendet"}}},fp="15,172,24.223.0,27.334.0,38.107.0,32.154.0,34.157.0,43.170.0,40.114.1,60.218.0"}
P.entries["quest:1792"] = {n="Wirbelwaffe",s="Die erwählte Waffe eines Kriegers erwartet den Sturm, den Cyclonian hinterlassen hat. Das Wirbelherz kann den Zorn des Elementars in ein geschmiedetes Gefäß binden.",h="Die erwählte Waffe eines Kriegers erwartet den Sturm, den Cyclonian hinterlassen hat.",kw={"cyclonian","elementar","sturm","gefäß","kriegerwaffe","wirbelherz","wirbelwaffe"},ang={["class:Warrior"]="Als Krieger könnt Ihr eine Waffe erringen, die von Cyclonians tobender Sturmkraft erfüllt ist."},sec={{t="Den Sturm einbinden",b="Nachdem Cyclonian gefallen ist und der Krieger sein Herz an sich genommen hat, bereitet ein Handwerker eine Waffe vor, die die Macht des Sturms aufnehmen soll. Das Herz wird mit der erwählten Waffe verschmolzen und macht das geschmiedete Metall zu einem Kanal für elementaren Zorn."},{t="Die Macht Cyclonians",b="Cyclonians Herz birgt die Gewalt heulender Winde und tobender Sturmböen. In eine geschmiedete Waffe gebunden, verleiht es dem Träger neben seinem eigenen Kampfgeschick die lebendige Macht des Sturms. Jeder Schlag trägt die Kraft des besiegten Elementars, dessen Sturm nun in den Händen seines Bezwingers wütet."}},faq={{q="Was ist die Quest Wirbelwaffe?",a="Ein Krieger kann Cyclonians Wirbelherz in eine erwählte Waffe binden und so die Macht des Elementars mit seiner eigenen Stärke vereinen.",al={"was ist die wirbelwaffe","geschichte der wirbelwaffe","was ist diese quest"}},{q="Wer ist Cyclonian?",a="Cyclonian ist eine elementare Manifestation von Wind und Sturm. Sein Sieg über ihn bringt das Wirbelherz hervor, das urtümliche Windenergie in eine physische Waffe binden kann.",al={"wer ist cyclonian","geschichte von cyclonian","was ist cyclonian"}},{q="Was ist das Wirbelherz?",a="Das Wirbelherz ist Cyclonians Kern, der nach dem Sieg über den Elementar geborgen wird. Es birgt den Zorn des Sturms und kann in ein geschmiedetes Gefäß gebunden werden, das der Krieger erwählt hat.",al={"was ist das wirbelherz","cyclonians herz","herz von cyclonian"}},{q="Wie wird die Waffe gestärkt?",a="Der Krieger erwählt eine geschmiedete Waffe und lässt Cyclonians Wirbelherz darin binden. Der Zorn des Elementars durchströmt daraufhin den Stahl.",al={"wie wird die wirbelwaffe hergestellt","gefäß der wahl","wirbelwaffe schmieden"}},{q="Welche Waffen stehen zur Wahl?",a="Ein Krieger erwählt die Waffe, die Cyclonians Sturmessenz aufnehmen soll.",al={"welche waffe steht zur wahl","wirbelwaffen zur auswahl","welche waffen werden angeboten"}},{q="Warum ist Cyclonians Macht begehrt?",a="Krieger streben nach Cyclonians Macht, um durch ihre Waffen über den Zorn eines lebendigen Sturms zu gebieten.",al={"warum will ein krieger die wirbelwaffe","bedeutung der wirbelwaffe"}}},fp="16,137,18.211.0,22.301.0,35.131.0,17.155.0,28.169.0,28.139.0,40.73.0,38.91.0"}
P.entries["quest:1793"] = {n="Der Foliant der Tapferkeit",s="In Sturmwind und Eisenschmiede stellen sich junge Paladine der Allianz einer Prüfung von Mut und Pflichtgefühl. Ihre Mentoren verlangen den Beweis, dass sie geschickt kämpfen und die Unschuldigen beschützen können.",h="In Sturmwind und Eisenschmiede stellen sich junge Paladine der Allianz einer Prüfung von Mut und...",kw={"kathedrale des lichts","duthorian rall","heiliges licht","eisenschmiede","paladinprüfung","silver hand","tiza kriegshammer","foliant der ehre"},ang={["class:Paladin"]="Als Paladin stellt Ihr Euch einem Ritus, der von Euch verlangt, die Pflicht gegenüber anderen über Eure eigene Sicherheit zu stellen, während Ihr zu einem vertrauenswürdigen Verteidiger des Heiligen Lichts heranwachst.",["faction:Alliance"]="Als Streiter der Allianz bereitet Ihr Euch darauf vor, Siedlungen gegen Bedrohungen zu verteidigen, die von örtlichen Banditen bis zu monströsen Eindringlingen reichen.",["race:Dwarf"]="Als Zwerg werdet Ihr in Eisenschmiede ausgebildet, wo Mentoren wie Tiza Kriegshammer von Euch verlangen, zu zeigen, dass Eure Standhaftigkeit einem heiligen Ziel dient.",["race:Human"]="Als Mensch stellt Ihr Euch dieser Prüfung unter Duthorian Ralls Aufsicht in der Kathedrale des Lichts. Sie trägt Sturmwinds Hingabe an die Gründungsideale der Silver Hand in sich."},sec={{t="Der Maßstab eines Paladins",b="Junge Paladine in Sturmwind und Eisenschmiede müssen sich schrecklichen Gefahren stellen, ohne zu wanken. Ihre Ausbilder prüfen ihre Entschlossenheit in der Kathedrale des Lichts und der Hall of Mysteries. Drachen und Dämonen können jene bedrohen, die sich nicht selbst verteidigen können. Die Paladine müssen ihnen zur Seite stehen."},{t="Tugenden des Ordens",b="Ein heiliger Krieger braucht Tapferkeit ebenso wie Waffe und Schild. Die Prüfung lehrt Paladine, dass Stärke ohne einen festen Eid zum Schutz der Hilflosen wenig bedeutet. Wenn Gefahr die Allianz bedroht, müssen ihre Verteidiger standhalten und jene schützen, die ihrer Obhut anvertraut sind."}},faq={{q="Welchen Zweck hat der Foliant der Ehre?",a="Der Foliant der Tapferkeit prüft, ob ein Paladin der Allianz den Mut und die selbstlose Entschlossenheit besitzt, die Schutzbedürftigen zu beschützen. Mentoren des Heiligen Lichts beurteilen anhand dieser Prüfung, ob ein Initiand bereit ist, im Orden aufzusteigen.",al={"was ist der foliant der ehre","zweck des folianten der ehre","warum den folianten der ehre absolvieren"}},{q="Wer leitet Paladine bei dieser Prüfung an?",a="Hochrangige Paladine in den Hauptstädten der Allianz führen Initianden durch die Prüfung. Duthorian Rall ruft sie aus der Kathedrale des Lichts in Sturmwind, während Tiza Kriegshammer dies aus der Hall of Mysteries in Eisenschmiede tut.",al={"wer vergibt den folianten der ehre","questgeber des folianten der ehre","wer beginnt den folianten der ehre"}},{q="Wohin führt diese Prüfung?",a="Der erste Ruf führt zu einer Reihe von Prüfungen, die die Entschlossenheit eines Paladins auf die Probe stellen. Sie führen den Initianden in Gefahr, um das Reich und die Unschuldigen zu verteidigen.",al={"was folgt auf den folianten der ehre","folgequest des folianten der ehre","questreihe des folianten der ehre"}},{q="Warum wird bei Paladinen so viel Wert auf Tapferkeit gelegt?",a="Tapferkeit hilft einem Paladin, den Glauben zu bewahren und andere zu beschützen, wenn Schrecken wie Dämonen oder Drachen drohen. Ohne Mut kann Furcht den Geist eines Kriegers brechen.",al={"warum tapferkeit","warum mut für paladine wichtig ist"}},{q="Legen zwergische und menschliche Paladine dieselbe Prüfung ab?",a="Menschliche Paladine werden in der Kathedrale des Lichts in Sturmwind ausgebildet, während Zwerge in Eisenschmiede lernen. Beide Traditionen lehren Mut, Pflichtgefühl und den Schutz der Hilflosen im Zeichen des Lichts.",al={"ist es für zwerge anders","eisenschmiede foliant der ehre","sturmwind foliant der ehre"}},{q="Welche grundlegenden Lehren vermittelt die Prüfung?",a="Die Prüfung lehrt Paladine, Gefahren mutig zu begegnen, die Schwachen zu schützen und den Glauben zu bewahren, wenn der Schrecken kommt.",al={"lehren des folianten der ehre","was lehrt der foliant"}}},fx={["81822402"]={q="Warum wollen die Paladinmeister, dass Ihr diese Prüfung ablegt?",a="Die Zeiten in Azeroth werden immer gefährlicher, bedroht durch drohende Übel wie Dämonen und Drachen. Obwohl Ihr bereits bewiesen habt, dass das Heilige Licht auf Euren Ruf antwortet, wissen Duthorian Rall und Tiza Kriegshammer, dass reiner Glaube allein nicht ausreicht. Sie müssen die Härte unter Eurer Haut prüfen, um sicherzustellen, dass Ihr über den unerschütterlichen Mut verfügt, der von einem wahren Paladin verlangt wird, bevor größere Gefahren Eure Heimat treffen.",al={"warum prüfung ablegen","duthorian rall motiv","tiza kriegshammer prüfung warum"}},f91e68e3={q="Warum müsst Ihr diese Prüfung ablegen und nicht hochrangige Paladine oder Wachen?",a="Diese Reise ist kein Verteidigungsauftrag, den Stadtwachen oder erfahrene Ritter für Euch erledigen können. Es ist ein persönliches Initiationsritus. Die Meister müssen sehen, wie Euer eigener Geist sich in Notzeiten behauptet, und Eure persönliche Fähigkeit testen, die Schwachen zu beschützen, an Eurem Glauben festzuhalten und angesichts des Terrors standhaft zu bleiben.",al={"warum ich foliant der ehre","warum spieler ehre senden","warum können wachen das nicht"}}},fp="17,169,24.280.0,20.264.0,41.213.0,35.206.0,27.154.0,50.154.0,52.176.0,44.106.0"}
P.entries["quest:1795"] = {n="Die Bindung",s="Oberhalb von Ratschet stellen sich Hexenmeister dem Ritus, der einen Teufelsjäger ihrem Willen unterwirft. Strahad Farsan nutzt das wiederhergestellte Tome of the Cabal, um einen aggressiven Dämon aus dem Nether zu ziehen, und beobachtet dann, wie der Hexenmeister ihn im Kampf bezwingt.",h="Oberhalb von Ratschet stellen sich Hexenmeister dem Ritus, der einen Teufelsjäger ihrem Willen unterwirft.",kw={"brachland","teufelsjäger","ratschet","strahad farsan","beschwörung","die bindung","tome of the cabal","hexenmeister"},ang={["class:Warlock"]="Für Euch als Hexenmeister ist die Bindung eines Teufelsjägers ein entscheidender Meilenstein. Der Hund ist ein auf Magiebekämpfung spezialisiertes Raubtier, das Zauber verschlingen und feindliche Zauberwirker zum Schweigen bringen kann.",["faction:Alliance"]="Als Hexenmeister der Allianz reist Ihr von Sturmwind über das Meer ins neutrale Ratschet, wo Strahad das gefährliche Beschwörungsritual überwacht.",["faction:Horde"]="Als Hexenmeister der Horde reist Ihr ins Herz des Brachlands, um Eure Herrschaft über den Nether zu beweisen und den Hund vor Strahad auf neutralem Boden zu binden."},sec={{t="Der Kreis der Kabale",b="Auf Kalimdors Klippen oberhalb des Goblinhafens Ratschet leitet Strahad Farsan gefährliche Prüfungen in der Dämonenbeschwörung. Zunächst sammelt ein Hexenmeister die Fragmente und Reagenzien, die zur Wiederherstellung des uralten Tome of the Cabal nötig sind. Dann bereitet Strahad die Bindungsstätte vor. Er zeichnet eine innere Glyphe der Eindämmung, während seine Akolythen Macht durch verzauberte Stäbe kanalisieren, um den äußeren Kreis zu vollenden. Gemeinsam schirmen die Kreise alles, was hervortritt, von der Siedlung unterhalb ab."},{t="Den Jäger unterwerfen",b="Das Tome of the Cabal enthält die Worte, die eine Brücke in den Wirbelnden Nether öffnen. Teufelsjäger sind unersättliche Dämonenhunde, die nach arkaner Macht hungern und sich an magischer Energie laben. Weder sanfte Bezauberung noch gutes Zureden können einen von ihnen binden. Der Hexenmeister muss die beschworene Bestie im Kampf gewaltsam bezwingen und ihren Willen brechen, bevor sie ihren rechtmäßigen Meister anerkennt. Wer diesen Zusammenstoß überlebt, beweist, dass er den Hund gegen feindliche Zauberwirker einsetzen kann."}},faq={{q="Welchen Zweck hat dieses Ritual?",a="Das Ritual ermöglicht es einem Hexenmeister, einen Teufelsjäger zu beschwören und seinem Willen zu unterwerfen. Das Lesen aus dem vervollständigten Tome of the Cabal innerhalb von Strahad Farsans Beschwörungskreis zieht den Dämon aus dem Nether. Der Hexenmeister muss ihn im Kampf besiegen, um sich seine dauerhaften Dienste zu sichern.",al={"warum diese quest machen","ziel der teufelsjägerquest","zweck der bindung"}},{q="Wer ist Strahad Farsan?",a="Strahad Farsan ist ein versierter menschlicher Hexenmeister, dessen Turm oberhalb von Ratschet im Brachland steht. Sein tiefes Wissen um dunkle Beschwörungskünste veranlasst Lehrmeister der Allianz und der Horde, ihre vielversprechendsten Schüler im Stillen zu ihm zu schicken, damit sie unter seiner Anleitung fortgeschrittene Bindungsriten erlernen.",al={"wer ist strahad","strahad farsans geschichte","questgeber strahad"}},{q="Warum muss ein Hexenmeister den Dämon töten, statt ihn zu versklaven?",a="Ein Teufelsjäger ist ein aggressives Raubtier, das Magie verschlingt und sich nur absoluter Überlegenheit beugt. Der Hexenmeister muss ihn im körperlichen und magischen Kampf bezwingen, seine Wildheit gewaltsam brechen und seinem Geist Autorität einprägen, damit er künftigen Beschwörungen gehorcht.",al={"warum teufelsjäger töten","teufelsjäger versklaven möglich","kampf gegen teufelsjäger"}},{q="Können Hexenmeister der Horde und der Allianz dieses Ritual hier durchführen?",a="Ja. Hexenmeister der Allianz und der Horde folgen unterschiedlichen Schritten, um das Tome of the Cabal wiederherzustellen, doch beide werden schließlich zur letzten Beschwörung zu Strahad Farsan oberhalb von Ratschet geschickt.",al={"nur für die horde","nur für die allianz","wer erhält diese quest"}},{q="Was geschieht, wenn der Teufelsjäger den Beschwörer besiegt?",a="Fällt der Beschwörer, wird der Teufelsjäger in den Nether verbannt und das Ritual scheitert. Hexenmeister, die ihre Niederlage überleben, können von Strahad ein neues Exemplar des Tome of the Cabal erhalten und es mit der richtigen Vorbereitung erneut versuchen.",al={"was passiert beim sterben","scheitern der bindung","ritual erneut versuchen"}},{q="Was unterscheidet Teufelsjäger von anderen Dämonen?",a="Teufelsjäger sind Dämonenhunde, die ihre Beute anhand magischer Ausstrahlungen aufspüren. Sie verlassen sich weniger auf rohe Gewalt oder Schattenzauber, sondern wittern Zauberei, verschlingen aktive Verzauberungen und stören feindliche Zauberwirker. Das macht sie zu wertvollen Begleitern gegen rivalisierende Magieanwender.",al={"was macht ein teufelsjäger","geschichte der teufelsjäger","warum teufelsjäger"}}},fx={b1095368={q="Warum will Strahad Farsan, dass Ihr den Felhunter beschwört?",a="Strahad Farsan benutzt Euch nicht, um Besorgungen zu machen – er bildet Euch aus, um größere dämonische Magie zu beherrschen. Er glaubt, dass jeder Hexenmeister einen Felhunter unter seinem Befehl haben sollte, da die zerstörerischen Kräfte der Kreatur die Gefahr, eine zu binden, bei weitem überwiegen. Nachdem er Eure Sammlung der Materialien und das Tome of the Cabal geleitet hat, geht es ihm darum, Euer Potenzial zu testen und zu sehen, ob Ihr die Prüfung überleben könnt, um unter den furchterregendsten Praktizierenden der Ära zu stehen.",al={"warum will strahad das","strahad farsan motiv","warum felhunter für strahad beschwören"}},["44d888c5"]={q="Warum müsst Ihr dem Felhunter selbst gegenübertreten, anstatt dass Strahad das tut?",a="Ein beschworener Dämon kann nicht einfach in Eurem Namen besiegt werden. Die Unterwerfung eines Schergen aus dem Wirbelnden Nether erfordert den Beweis Eures persönlichen Willens und Eurer Dominanz über die Kreatur; wenn Strahad oder seine Akolythen ihn besiegen würden, würde kein Band der Knechtschaft zu Euch entstehen. Strahad und seine Assistenten kanalisieren die größeren Beschwörungskreise, um den Bruch einzudämmen, aber die wilde Kraft der Bestie im Kampf zu brechen, ist eine Prüfung, die nur der zukünftige Meister bestehen kann.",al={"warum kann strahad nicht kämpfen","warum muss ich den felhunter töten","warum muss ich alleine gegen den dämon kämpfen"}},["6bf7b15d"]={q="Was ist der beschworene Felhunter und woher kommt er?",a="Ihr steht einem bösartigen, räuberischen Dämon gegenüber, der mithilfe der Beschwörungen innerhalb des Tome of the Cabal direkt aus dem Wirbelnden Nether gezogen wurde. Felhunter sind monströse Bestien, die vom Geschmack arkaner und magischer Energien angezogen werden, die sie eifrig verfolgen, absaugen und stören. Da sie von Natur aus gefräßige Unholde sind, wird die Kreatur, die in den Beschwörungskreis gezogen wird, Euch sofort nach ihrer Materialisierung angreifen und verlangen, dass Ihr sie im Kampf überwältigt, bevor ihr Geist an Euren Dienst gebunden werden kann.",al={"was ist der beschworene felhunter","gegen was kämpfe ich","felhunter lore"}}},fp="11,217,18.453.0,22.442.0,35.259.0,22.292.0,66.256.0,62.183.0,51.213.0,54.277.0"}
P.entries["quest:1796"] = {n="Komponenten für die verzauberte Goldblutrobe",s="In Ratschet sucht Menara Leerbringer Roben von Arcana für ein Gewand, das mächtige Verzauberungen tragen soll.",h="In Ratschet sucht Menara Leerbringer Roben von Arcana für ein Gewand, das mächtige Verzauberungen tragen soll.",kw={"brachland","blutrobe","verzauberte goldblutrobe","menara leerbringer","roben von arcana","schneiderei","hexenmeisterquest"},ang={["class:Warlock"]="Als Hexenmeister lernt Ihr bei der Herstellung der Verzauberten Goldblutrobe, mächtige Artefakte auf einer starken, sorgfältig vorbereiteten Grundlage zu erschaffen.",["profession:Tailoring"]="Als Schneider braucht Ihr das seltene Muster für Roben von Arcana sowie Geschick im Umgang mit Spinnenseide und vielen Ballen feiner Seide.",["race:Orc"]="Als Orc-Hexenmeister bietet Euch das Sammeln von Materialien für unscheinbare Roben einen stilleren Weg, Teufelsenergie zu meistern, fern von neugierigen Blicken und dem Schatten der dämonischen Vergangenheit Eures Volkes.",["race:Undead"]="Als Verlassene reist Ihr womöglich weit ins sonnengebleichte Brachland, um von Menara zu lernen und Eure gebrechliche sterbliche Hülle gegen Eure unberechenbaren Künste zu stärken."},sec={{t="Ein Gefäß für Arcana",b="Menara Leerbringer bittet Hexenmeister, die nach größerer Macht streben, ihr Roben von Arcana zu bringen. Sie braucht ein Gewand, das stark genug ist, dunkle Magie zu halten. Die Stärke eines Relikts hängt von der Kunstfertigkeit, Seltenheit und Mühe ab, die in seinen Materialien stecken. Gewöhnliche Lumpen würden starken Verzauberungen nicht standhalten, also muss die Robe fein gearbeitet und bereit sein, sie aufzunehmen."},{t="Handwerk und Ehrgeiz",b="Menara bewundert Hexenmeister, die die Robe selbst weben, doch Ehrgeiz bedeutet ihr mehr als Stolz. Ihr könnt die Seide selbst nähen, einen geschickten Handwerker beauftragen oder die Robe auf dem Markt kaufen. Wie auch immer Ihr sie beschafft, das fertige Gewand ist bereit, zu einem spezialisierten Werkzeug zur Beherrschung der Teufelsmagie zu werden."}},faq={{q="Warum braucht Menara Leerbringer gerade Roben von Arcana?",a="Mächtige Verzauberungen brauchen ein Gewand, das mit Kunstfertigkeit aus seltenen Materialien gefertigt wurde. Menara nutzt die Roben von Arcana als Grundlage für die Kräfte, die sie darin binden will.",al={"warum roben von arcana","warum diese robe","zweck der robe"}},{q="Wo befindet sich Menara Leerbringer?",a="Menara Leerbringer lebt in Ratschet, dem Goblinhafen im Brachland. Sie unterweist Hexenmeister, die ihre Kunst weiterentwickeln und spezialisierte Ausrüstung herstellen wollen.",al={"menara leerbringer standort","wo ist menara","menara leerbringer wo"}},{q="Muss ich die Roben von Arcana selbst schneidern?",a="Nein. Menara achtet jene, die die Robe selbst herstellen, doch sie nimmt auch eine an, die durch Handel erworben oder von einem anderen Handwerker gekauft wurde. Ihr könnt sie auf jedem praktikablen Weg beschaffen.",al={"schneiderei nötig","roben kaufen möglich","schneiderei erforderlich"}},{q="Woher stammt das Muster für Roben von Arcana?",a="Das seltene Muster lässt sich bei Kultisten und dunklen Zauberwirkern finden. Dark Strand Voidcallers am Turm von Althalaxx in Dunkelküste und Defias Enchanters im Dämmerwald gehören zu jenen, die es bei sich tragen.",al={"roben von arcana muster","wie muster erhalten","schneiderrezept fundort"}},{q="Was geschieht mit den Roben von Arcana nach der Abgabe?",a="Menara nimmt die Roben als Material für das anschließende Ritual der magischen Durchdringung. Wenn Ihr sie tragt, während Ihr sie ihr bringt, nimmt sie Euch diese sofort ab, sodass Ihr bis zum Abschluss der späteren Schritte ohne Bruststück bleibt.",al={"gehen die roben verloren","robe verschwunden","was geschieht mit der robe"}},{q="Was ist die Verzauberte Goldblutrobe?",a="Die Verzauberte Goldblutrobe ist ein spezialisiertes Gewand für Hexenmeister mittleren Ranges. Dunkle Komponenten und schützende Verzauberungen stärken die Widerstandskraft und die Reserven dunkler Energie ihres Trägers.",al={"was ist die blutrobe","blutrobe hintergrund","verzauberte goldblutrobe"}}},fx={["44990969"]={q="Warum will Menara Leerbringer, dass dies getan wird?",a="Menara Leerbringer dient als Mentorin, die ehrgeizige Hexenmeister zu größerer Meisterschaft der dunklen Künste führt. Sie sucht keine Roben für ihre eigene Garderobe; stattdessen testet sie Eure Hingabe und Euren Einfallsreichtum, während sie Euch beibringt, mächtige Hexenmeistergewänder zu schmieden. Vielversprechende Praktizierende dazu anzuleiten, fel-Kräfte durch maßgeschneiderte Fokussierungen zu kanalisieren, stärkt die Reihen ihres schattenhaften Handwerks.",al={"warum hilft mir menara","menara leerbringer motiv","warum die roben machen"}}},fp="43,102,18.345.0,18.279.0,61.164.0,35.149.0,47.174.0,53.189.0,58.211.0,37.187.0"}
P.entries["quest:1798"] = {n="Die Suche nach Strahad",s="Hexenmeister suchen Strahad Farsan in Ratschet auf, um von ihm die Beschwörung von Teufelsjägern zu lernen. Unterhalb des Goblinhafens eröffnet sein Wissen einen Weg zu gefährlicheren Dämonen.",h="Hexenmeister suchen Strahad Farsan in Ratschet auf, um von ihm die Beschwörung von Teufelsjägern zu lernen.",kw={"teufelsjäger","gakin der dunkelbinder","ratschet","die suche nach strahad","sturmwind","strahad farsan","brachland","hexenmeister"},ang={["class:Warlock"]="Als Hexenmeister lasst Ihr einfache Dämonen und Sukkuben hinter Euch, wenn Ihr lernt, den listigen, magieentziehenden Teufelsjäger zu beschwören.",["faction:Alliance"]="Als Hexenmeister der Allianz überquert Ihr das große Meer ins zerklüftete, von der Horde beherrschte Kernland Kalimdors, um Strahad zu erreichen."},sec={{t="Ein Ruf übers Meer",b="Gakin der Dunkelbinder schickt Euch von Sturmwind aus, um die Beschwörung eines Teufelsjägers zu erlernen. Er leitet Hexenmeister im Slaughtered Lamb unter dem Magierviertel an, doch die Riten erfordern Wissen, das ihm fehlt. Also überquert Ihr das große Meer nach Kalimdor, wo ein anderer Hexenmeister den Weg kennen könnte."},{t="Der Hermit von Ratschet",b="Strahad Farsan lebt in den trockenen Hügeln oberhalb von Ratschet, dem Goblinhafen. Als menschlicher Hexenmeister und Gakins ebenbürtiger Gefährte in ihrer geheimen Kabale wirkt er von neutralem Gebiet aus. Dort erregt er seltener die Aufmerksamkeit von Magistraten der Allianz, Inquisitoren der Kirche und Wachposten der Horde. Hexenmeister kommen in der Hoffnung, Dämonen zu beherrschen, die Mana entziehen."}},faq={{q="Wer schickt Euch auf die Suche nach Strahad?",a="Gakin der Dunkelbinder schickt Euch vom Slaughtered Lamb in Sturmwinds Magierviertel aus, sobald Ihr bereit seid, die Beschwörung eines Teufelsjägers zu erlernen.",al={"wer vergibt die suche nach strahad","questgeber","gakin"}},{q="Wo befindet sich Strahad Farsan?",a="Strahad Farsan lebt im Brachland, auf den Anhöhen über Ratschet, dem Goblinhafen.",al={"strahads standort","wo ist strahad","strahad finden"}},{q="Warum muss ein Hexenmeister der Allianz den weiten Weg ins Brachland auf sich nehmen?",a="Gakin kann in Sturmwind weder das Wissen noch die Materialien für die Beschwörungsriten eines Teufelsjägers bereitstellen. Strahad Farsan besitzt dieses Wissen und wirkt von neutralem Gebiet nahe Ratschet aus, fernab der prüfenden Blicke örtlicher Autoritäten.",al={"warum ins brachland","warum kalimdor","warum ratschet"}},{q="Welche Fähigkeit lässt sich durch diese Quest schließlich erlernen?",a="Das Gespräch mit Strahad beginnt eine Questreihe, die zum Tome of the Cabal und zum Bindungsritual zur Beschwörung eines Teufelsjägers als Begleiter führt.",al={"für welchen begleiter","welche belohnung","teufelsjägerquest"}},{q="Ist Strahad Farsan der Horde feindlich gesinnt?",a="Nein. Strahad lebt auf neutralem Goblingebiet und unterweist Hexenmeister der Allianz und der Horde in der Beschwörung von Teufelsjägern, während er Verbindungen zu verschiedenen Kabalen pflegt.",al={"strahad nur für allianz","horde strahad"}},{q="Was geschieht nach Eurem Gespräch mit Strahad?",a="Strahad bittet Euch, die Bestandteile für ein Bindungsritual zu sammeln, und beginnt damit eine Questreihe, in der der Tome of the Cabal eine Rolle spielt.",al={"nächste quest","was nach die suche nach strahad","tome of the cabal"}}},fx={["034d02a4"]={q="Warum möchte Gakin der Dunkelbinder, dass Ihr Strahad aufsucht?",a="Gakin urteilt, dass Eure Macht weit genug gewachsen ist, um einen Teufelsjäger zu befehligen, doch ihm fehlen die arkanen Reagenzien und rituellen Komponenten, die erforderlich sind, um Euch unter Sturmwind auszubilden. Anstatt Eure Ausbildung ins Stocken geraten zu lassen, schickt er Euch zu Strahad Farsan, einem vertrauenswürdigen Kollegen aus ihrem inneren Zirkel, der über das nötige Wissen und die Materialien auf der anderen Seite des Meeres verfügt.",al={"warum zu strahad schicken","gakin dunkelbinder motiv","warum gakin euch wegschickt"}}},fp="15,164,24.279.0,21.315.0,30.135.0,32.89.0,71.205.0,47.132.0,39.152.0,40.114.0"}
P.entries["quest:18"] = {n="Bruderschaft der Diebe",s="Jenseits des östlichen Flusses von Nordhain beginnt die Bruderschaft der Defias, das Tal heimzusuchen. Deputy Willem schickt Rekruten gegen die Räuber aus, deren rote Sackleinenkopftücher Sturmwind den ersten klaren Hinweis auf ihre organisierte Präsenz geben.",h="Jenseits des östlichen Flusses von Nordhain beginnt die Bruderschaft der Defias, das Tal heimzusuchen.",kw={"kopftücher","bruderschaft der diebe","defias","deputy willem","elwynn","nordhain","armee von sturmwind"},ang={["class:Rogue"]="Angehenden Schurken gewähren die Defias einen Einblick in organisierte Verbrechernetzwerke, die im Verborgenen im Herzland der Menschen wirken.",["faction:Alliance"]="Die Behörden von Sturmwind verlassen sich auf neu eingetroffene Rekruten der Allianz, um den Frieden in Nordhain zu wahren, während das reguläre Militär des Königreichs dünn verteilt ist.",["race:Human"]="Menschen, die ihre Ausbildung in Nordhain beginnen, zeigen die Defias, wie die Sicherheit des Königreichs Sturmwind von innen heraus schwindet."},sec={{t="Banditen im Tal",b="Das Nordhaintal ist seit Langem eine sichere Zuflucht im Wald von Elwynn. Sturmwind beschützt es, und Rekruten sowie Kleriker des Heiligen Lichts werden dort ausgebildet. Doch in letzter Zeit sind die Wachen des Tals dünn besetzt. Vagabunden und Diebe überqueren den östlichen Fluss und verstecken sich nahe den Wäldern. Sie errichten kleine Lager in der Nähe der Abtei.\n\nDeputy Willem sorgt für Ordnung, doch die Wachen können nicht jeden Winkel des Tals im Auge behalten. Er braucht Freiwillige, die helfen, die Stellung zu halten."},{t="Das purpurrote Zeichen",b="Die Gesetzlosen ziehen gemeinsam umher und tragen einheitliche rote Sackleinenkopftücher. Sie nennen sich die Bruderschaft der Defias, und die Tücher kennzeichnen ihre Zugehörigkeit. Deputy Willem schickt Rekruten aus, um die Räuber zurückzudrängen und ihre Masken einzusammeln. Er hofft, ihren Vormarsch zu bremsen und herauszufinden, wie weit die Defias bereits ins Herzland des Königreichs vorgedrungen sind."}},faq={{q="Wer ist die Bruderschaft der Defias?",a="Die Bruderschaft der Defias ist eine organisierte Bande von Räubern und Gesetzlosen, die im gesamten Wald von Elwynn und in Westfall aktiv ist. Zunächst sehen die Behörden von Nordhain in ihnen dreiste Diebe, doch die Banditen tragen einheitliche rote Sackleinenmasken und folgen einer gemeinsamen Führung.",al={"wer sind die defias","was ist die bruderschaft der defias","geschichte der defias"}},{q="Warum bittet Deputy Willem Rekruten um Hilfe, statt die Armee von Sturmwind einzusetzen?",a="Die Armee von Sturmwind und die Stadtwachen sind im ganzen Königreich dünn verteilt. In benachbarten Regionen wachsen die Unruhen, und die Anführer von Sturmwind stehen unter Druck. Die örtlichen Ordnungshüter wenden sich an eifrige Freiwillige und unerfahrene Rekruten, um die Banditen zurückzudrängen.",al={"warum willem hilfe braucht","wo sind die wachen von sturmwind","warum keine armee"}},{q="Woher kommen diese Diebe?",a="Die Diebe sammeln sich jenseits des Flusses östlich der Abtei. Sie schleichen am Rand der örtlichen Gehöfte und um Lagerplätze nahe dem Weinberg herum.",al={"wo sind die banditen","defias standort nordhain"}},{q="Warum tragen die Diebe rote Sackleinenkopftücher?",a="Das rote Sackleinenkopftuch kennzeichnet die Zugehörigkeit eines Diebes zur Bruderschaft der Defias und verbirgt seine Identität. Es zeigt diese Zugehörigkeit auch anderen Gesetzlosen in den Gebieten der Menschen.",al={"warum rote kopftücher","bedeutung der roten masken","rotes sackleinen"}},{q="Was geschieht nach Abschluss dieser Quest?",a="Deputy Willem und die Einheimischen erkennen bald, dass die Bedrohung durch die Banditen weiter nach Nordhain hineinreicht. Die Rekruten helfen dann Milly Osworth mit ihrer verwüsteten Ernte und spüren Garrick Padfoot auf, einen bestimmten Rädelsführer.",al={"what comes next","nach bruderschaft der diebe"}},{q="Weiß Deputy Willem, wer die Defias anführt?",a="Willem kennt nicht die ganze Reichweite der Organisation. Er weiß, dass die Räuber sich Bruderschaft der Defias nennen, und vermutet, dass ihre Anwesenheit nahe der Abtei Unheil für Sturmwind verheißt.",al={"kennt willem vancleef","wer führt die defias in nordhain an"}}},fx={e491bbee={q="Warum will Deputy Willem, dass Ihr gegen die Diebe kämpft?",a="Deputy Willem ist damit beauftragt, die Abtei von Nordhain und das umliegende Tal zu schützen. Eine dreiste Verbrecherbande namens The Defias Brotherhood hat sich in die östlichen Wälder jenseits des Flusses geschlichen und bedroht die Sicherheit der Abtei und der örtlichen Arbeiter. Willem will, dass sie sofort unterdrückt werden, bevor sie einen stärkeren Stützpunkt gewinnen oder einen direkten Angriff auf das Tal starten.",al={"warum will willem das","willem motiv","warum hier die defias stoppen"}},["4db9a478"]={q="Wer sind die Diebe jenseits des Flusses?",a="Ihr werdet gegen die Defias-Schläger ausgesandt, Gesetzlose der The Defias Brotherhood, die ihr Lager in den Wäldern jenseits des Baches östlich der Abtei von Nordhain aufgeschlagen haben. Sie haben sich in der Nähe der Weinberge und der umliegenden Felder versammelt, spähen das Tal aus und belästigen die Einheimischen, während sie eine bewaffnete Präsenz direkt unter der Nase von Sturmwind aufbauen.",al={"wer sind die diebe","gegen wen kämpfe ich","defias in nordhain"}}},fp="22,232,21.429.0,17.331.0,31.244.0,82.243.0,36.135.0,44.181.0,41.205.0,45.186.0"}
P.entries["quest:180"] = {n="GESUCHT: Leutnant Fangor",s="In Seenhain ist ein Kopfgeld auf Leutnant Fangor ausgesetzt. Magistrat Solomon sucht Jäger, um die Schattenfellgnolle aufzuhalten, die ins Rotkammgebirge vordringen. Fangor dient dem abtrünnigen Zauberer Morganth, und sein Tod würde dessen Streitkräften einen Schlag versetzen.",h="In Seenhain ist ein Kopfgeld auf Leutnant Fangor ausgesetzt.",kw={"fangor","gnoll","seenhain","leutnant fangor","magistrat solomon","morganth","rotkammgebirge","schattenfell"},ang={["faction:Alliance"]="Für die Allianz ist Seenhain ein wichtiger Stützpunkt im Rotkammgebirge. Fangors Beseitigung würde verhindern, dass die Siedlung abgeschnitten wird.",["race:Human"]="Als Mensch erlebt Ihr Sturmwinds Vernachlässigung des Rotkammgebirges am eigenen Leib. Sich den Gnollhäuptlingen entgegenzustellen, ist für Eure Heimat eine Frage des Überlebens."},sec={{t="Eine Stadt unter Belagerung",b="Seenhain sieht sich wachsender Gefahr gegenüber. Sturmwinds Armee ist überlastet, und König Varian Wrynn ist auf mysteriöse Weise abwesend. Hochlord Bolvar Fordragon hat Grenzsiedlungen wie das Rotkammgebirge sich selbst überlassen.\n\nDer Schattenfellklan überfällt Handelsrouten, brennt Gehöfte nieder und rückt gegen die Stadtgrenze vor. Magistrat Solomon schlägt Kopfgelder an, um Söldnerklingen dorthin zu locken, wo königliche Soldaten nicht marschieren."},{t="Morganths Leutnant",b="Leutnant Fangor führt die Schattenfellgnolle als Morganths Vollstrecker an. Morganth ist ein abtrünniger dunkler Zauberer, der sich in den Hügeln des Rotkammgebirges versteckt. Unter Fangor schlagen die Gnolle gemeinsam zu, statt sich wie Aasfresser zu zerstreuen.\n\nIhre Angriffe drohen Seenhain vom Wald von Elwynn abzuschneiden. Fangors abgetrennte Tatze würde Magistrat Solomon beweisen, dass Morganths brutale Vorhut gebrochen wurde."}},faq={{q="Wer ist Leutnant Fangor?",a="Leutnant Fangor führt die Schattenfellgnolle im Rotkammgebirge an. Er koordiniert ihre Überfälle und setzt den Willen Morganths durch, eines dunklen Zauberers, der Seenhain bedroht.",al={"leutnant fangor","wer ist fangor","fangors geschichte"}},{q="Wer hat das Kopfgeld auf Leutnant Fangor ausgesetzt?",a="Magistrat Solomon, das Stadtoberhaupt von Seenhain, hat das Kopfgeld ausgesetzt. Er will die Grenzen des Rotkammgebirges gegen feindselige Gnolle und dunkle Zauberwirker verteidigen.",al={"wer hat das kopfgeld ausgesetzt","wer will fangors tod","magistrat solomon fangor"}},{q="Warum schickt Sturmwind keine Soldaten gegen die Gnolle?",a="Sturmwind ist durch König Varian Wrynns plötzliches Verschwinden und innere Unruhen gelähmt. Hochlord Bolvar Fordragon und das House of Nobles haben sich geweigert, reguläre Armeeeinheiten in abgelegene Städte wie Seenhain zu entsenden. Deshalb heuert Magistrat Solomon Abenteurer als Söldner an.",al={"warum keine wache aus sturmwind","wo sind sturmwinds soldaten","warum hilft die armee nicht"}},{q="Welcher Beweis ist nötig, um das Kopfgeld zu erhalten?",a="Magistrat Solomon verlangt Leutnant Fangors abgetrennte Tatze als Beweis dafür, dass der Kriegsherr der Schattenfellgnolle getötet wurde.",al={"fangor beweis","fangors tatze","welcher gegenstand zur abgabe"}},{q="Wer ist Morganth, und warum folgt Fangor ihm?",a="Morganth ist ein abtrünniger menschlicher Zauberwirker, der von einem Turm im Rotkammgebirge aus dunkle Magie praktiziert. Er hat die Schattenfellgnolle seinem Willen unterworfen und setzt Leutnant Fangor als Vollstrecker ein, um das Umland zu terrorisieren.",al={"wer ist morganth","warum folgen gnolle morganth","fangor morganth"}},{q="Was sind die Schattenfellgnolle?",a="Die Schattenfellgnolle sind ein wilder Gnollklan in den zerklüfteten Felsen und Wäldern des Rotkammgebirges. Ihre Angriffslust und ihre brutalen Hinterhalte plagen die Siedler von Seenhain seit Jahren.",al={"schattenfellklan","gnolle im rotkammgebirge","geschichte der schattenfellgnolle"}}},fp="26,257,18.402.0,21.382.0,26.162.0,45.146.0,57.268.0,43.113.0,48.221.0,31.175.0"}
P.entries["quest:1801"] = {n="Foliant der Kabale",s="Im Brachland schickt Strahad Farsan Hexenmeister der Horde nach Osten, um ein verlorenes Zauberbuch zu suchen. Seine Riten lehren, wie man einen Teufelsjäger beschwört und bindet, und die Suche führt zunächst zum Kartographen Jorah Annison in Unterstadt.",h="Im Brachland schickt Strahad Farsan Hexenmeister der Horde nach Osten, um ein verlorenes Zauberbuch zu suchen.",kw={"brachland","teufelsjäger","jorah annison","ratschet","strahad farsan","foliant der kabale","unterstadt","hexenmeisterquest"},ang={["class:Warlock"]="Als Hexenmeister der Horde müsst Ihr diesen Initiationsritus vollziehen, um einen Teufelsjäger zu zähmen. Die Reise führt durch Kalimdor und die Östlichen Königreiche, während Ihr vergessene Ritualkomponenten sammelt.",["faction:Horde"]="Als Mitglied der Horde seht Ihr, wie Kalimdors dunkle Zauberwirker unter den Ruinen von Lordaeron mit okkulten Gelehrten der Verlassenen zusammenarbeiten."},sec={{t="Die Jagd nach uraltem Wissen",b="Strahad Farsan warnt, dass die Beschwörung eines Teufelsjägers mehr als gewöhnliche Teufelsmagie erfordert. Diese Raubtiere nähren sich von magischen Energien und widerstehen gewöhnlichen Beschwörungskreisen. Ein Initiant benötigt besondere Kreise und ein uraltes Zauberbuch namens Foliant der Kabale. Die ersten Hexenmeister, die einen Teufelsjäger ohne fremde Hilfe banden, haben es verfasst. Seine Riten und Siegel zeigen, wie man den gefährlichen Dämon versklavt."},{t="Der Kartograph von Unterstadt",b="Unter den Hexenmeistern in Kalimdor gibt es keine Exemplare des Folianten der Kabale mehr. Deshalb schickt Strahad seinen Schüler über das Meer zu Jorah Annison in Unterstadt. Annison ist ein königlicher Kartograph, der Lordaeron kartiert, doch er weiß viel über uralte und obskure Texte. Er gibt zu, dass ihn das Kartenzeichnen zermürbt. Sein wahrer Wissensdurst gilt seltenen Geschichtswerken, okkulten Erzählungen und Abhandlungen über dunkle Magie."}},faq={{q="Was ist der Foliant der Kabale?",a="Der Foliant der Kabale ist ein seltenes okkultes Zauberbuch, verfasst von den ersten Hexenmeistern, die einen Teufelsjäger ohne fremde Hilfe beschworen und banden. Seine genauen Anweisungen, Schutzzauber und Riten ermöglichen es, eine dieser magieverschlingenden Bestien sicher nach Azeroth zu bringen.",al={"foliant der kabale hintergrundgeschichte","was ist dieses buch","foliant der kabale"}},{q="Warum schickt Strahad Farsan Euch nach Unterstadt?",a="Strahad und seine Akolythen im Brachland besitzen kein Exemplar des Folianten der Kabale. Er schickt Euch zu Jorah Annison, einem Kartographen aus Unterstadt und Gelehrten seltener, uralter Bücher, der vielleicht weiß, wo es zu finden ist.",al={"warum nach unterstadt","strahad farsan unterstadt","warum jorah aufsuchen"}},{q="Wer ist Jorah Annison?",a="Jorah Annison ist ein Gelehrter der Verlassenen, der in Unterstadt arbeitet. Die Kartographie ist sein Handwerk, doch seine Leidenschaft gilt obskuren Texten, nekromantischen Abhandlungen und uralter Literatur.",al={"wer ist jorah","jorah annison hintergrundgeschichte"}},{q="Warum braucht man ein besonderes Buch, um einen Teufelsjäger zu beschwören?",a="Teufelsjäger nähren sich von arkanen und anderen magischen Energien, weshalb gewöhnliche dämonische Kreise sie nicht sicher beschwören können. Der Foliant der Kabale beschreibt die nötigen Schutzmaßnahmen, um einen zu binden, bevor er den Beschwörer verschlingt.",al={"warum braucht teufelsjäger ein buch","warum ist teufelsjäger schwer zu beschwören"}}},fx={["9f4798be"]={q="Warum will Strahad Farsan, dass dies getan wird?",a="Strahad Farsan überwacht Euren Fortschritt als ehrgeiziger Hexenmeister, der würdig ist, größere dämonische Macht auszuüben. Das Beschwören und Unterwerfen eines Felhunters ist ein gefährlicher Initiationsritus, der testet, ob ein Praktizierender eine Kreatur meistern kann, die darauf ausgelegt ist, sich von roher magischer Essenz zu ernähren. Strahad ist bereit, seine Akolythen und Magiekreise für das Bindungsritual zur Verfügung zu stellen, aber Ihr müsst zuerst das alte Wissen beschaffen, das erforderlich ist, um die Beschwörung überhaupt möglich zu machen.",al={"strahad farsan motiv","warum hilft strahad","strahad grund"}},["5aabed1a"]={q="Warum schickt Strahad Farsan Euch, anstatt selbst zu gehen?",a="Die Prüfung ist ganz allein an Euch zu beweisen. Ein Hexenmeister muss Einfallsreichtum, Widerstandsfähigkeit und persönliche Herrschaft über die dunklen Künste demonstrieren, um eine Bestie zu binden, die so gefährlich ist wie ein Felhunter. Strahad und seine Akolythen müssen außerdem am Beschwörungskreis über Ratschet bleiben, um die komplexen Schutzzauber und Rituale vorzubereiten, die benötigt werden, wenn Ihr mit dem geborgenen Text zurückkehrt.",al={"warum mich senden","warum geht strahad nicht","warum muss ich in die unterstadt"}}},fp="17,208,28.379.0,29.377.0,30.249.0,50.201.0,21.175.0,51.203.0"}
P.entries["quest:1802"] = {n="Foliant der Kabale",s="Von Eisenschmiede führt Euch die Suche nach dem Folianten der Kabale zu einem verschollenen Manuskript und einem gesunkenen Schiff. Seine verstreuten Seiten enthalten Riten zur Bindung eines Teufelsjägers.",h="Von Eisenschmiede führt Euch die Suche nach dem Folianten der Kabale zu einem verschollenen Manuskript und...",kw={"der azurschacht","teufelsjäger","eisenschmiede","krom starkarm","schimmliger foliant","spalthufhöhle","strahad farsan","zerlumptes manuskript","foliant der kabale"},ang={["class:Warlock"]="Für Euch als Hexenmeister ist die Bergung der zerrissenen Hälften des Grimoires ein Übergangsritus. Seine Seiten enthalten die Beschwörungsriten, die nötig sind, um einen Teufelsjäger aus dem Nether herbeizurufen und zu versklaven.",["faction:Alliance"]="Als Magiekundiger der Allianz könnt Ihr Euch auf Kontakte in Eisenschmiede wie Krom Starkarm verlassen, um seltene dämonische Relikte über Kontinente hinweg aufzuspüren, ohne offen den Verdacht von Kirche oder Krone zu erregen."},sec={{t="Ein geteiltes Grimoire",b="Vom Folianten der Kabale wurde nur ein einziges Exemplar geschrieben. Gewalt riss ihn auseinander und schändete seine Seiten, sodass die Überreste in ferne Winkel der Welt gelangten. Ein zerlumptes Manuskript überquerte das Meer nach Kalimdor, wo Zentaurenclans es an sich nahmen. Die andere Hälfte wurde von Lordaeron nach Khaz Modan verschifft, doch das Schiff sank, bevor es den Hafen erreichte."},{t="Über Meer und Schlucht",b="Zwei Gefahren bewachen die fehlenden Seiten. Die auf See verlorenen Seiten wurden an der Küste von Hillsbrad westlich von Süderstade angespült. Küstenmurlocs nahe dem Azurschacht nahmen die durchnässten Relikte und Wrackteile an sich. Die trockene Hälfte ruht in einer uralten Truhe tief in den Zentaurenhöhlen der Spalthufhöhle in Tausend Nadeln. Sobald die Teile vereint sind, kann Krom Starkarm den verschollenen Text untersuchen, bevor dieser zu Strahad Farsan zurückkehrt."}},faq={{q="Was ist der Foliant der Kabale?",a="Der Foliant der Kabale ist ein seltenes dämonisches Grimoire, von dem nur ein einziges Exemplar existiert. Sein arkanes Wissen enthält die Beschwörungsformeln und Bindungsriten, die Hexenmeister brauchen, um einen Teufelsjäger aus dem Twisting Nether zu beschwören und zu unterwerfen.",al={"foliant der kabale hintergrund","was ist dieses buch","foliant kabale"}},{q="Wer ist Krom Starkarm und warum will er den Folianten?",a="Krom Starkarm ist ein Zwerg aus Eisenschmiede, der seltene und vergessene Texte studiert. Er verrät Hexenmeistern der Allianz, wo die Teile des Folianten gelandet sind, und bittet lediglich darum, sie nach ihrer Bergung studieren zu dürfen.",al={"wer ist krom starkarm","warum will krom das buch","krom starkarm eisenschmiede"}},{q="Wo sind die beiden Teile des Buches gelandet?",a="Der Schimmlige Foliant wurde an der Küste von Hillsbrad westlich von Süderstade nahe dem Azurschacht angespült, wo Küstenmurlocs ihn bargen. Das Zerlumpte Manuskript liegt in einer ramponierten Truhe tief in einer Zentaurenhöhle der Spalthufhöhle in Tausend Nadeln auf Kalimdor.",al={"wo sind die teile des folianten","buchfundorte","zerlumptes manuskript fundort"}},{q="Warum wurde der Foliant überhaupt auseinandergerissen?",a="Vom Folianten der Kabale wurde nur ein einziges Exemplar niedergeschrieben. Irgendwann in seiner düsteren Vergangenheit schändete ihn jemand absichtlich, riss einen großen Teil aus dem Einband und brachte ihn nach Kalimdor. Der Rest ging auf einer Seereise zum Hafen von Menethil verloren.",al={"warum wurde das buch zerrissen","wer hat den folianten geschändet"}},{q="Wer ist Strahad Farsan und was hat er mit dieser Quest zu tun?",a="Strahad Farsan ist ein erfahrener Hexenmeister, der nahe Ratschet im Brachland lebt. Er weist angehende Beschwörer an, den Folianten zu bergen und unter seiner Anleitung die Riten zur Beschwörung und Bindung eines Teufelsjägers zu erlernen.",al={"wer ist strahad","strahad farsan","strahads verbindung"}},{q="Warum ist der Schimmlige Foliant mit Meeresschmutz bedeckt?",a="Der Schimmlige Foliant befand sich an Bord eines Schiffes, das von der Küste Lordaerons zum Hafen von Menethil segelte, doch das Schiff kam nie an. Sein Wrack trieb nahe der Küste von Hillsbrad, wo Küstenmurlocs beim Azurschacht die feuchten, schimmligen Seiten einsammelten.",al={"warum ist der schimmlige foliant nass","hillsbrad foliant murlocs"}}},fx={["7c4e226c"]={q="Was ist der Schimmlige Foliant?",a="Der Schimmlige Foliant repräsentiert die wasserdurchtränkten Überreste der primären Bindung des Tome of the Cabal. Er ging auf See vor der Küste des Vorgebirges des Hügellands verloren, als ein Transportschiff auf dem Weg zum Hafen von Menethil sank. Ihn zurückzuholen bedeutet, den Kern der finsteren Lehren des Grimoires wiederherzustellen.",al={"schimmliger foliant","was ist der schimmlige foliant","warum schimmligen folianten finden"}},aa350fa4={q="Was ist das Zerlumpte Manuskript?",a="Das Zerlumpte Manuskript ist der Abschnitt, der aus dem ursprünglichen Tome of the Cabal herausgerissen wurde, bevor das Buch verloren ging. Weit über das Meer getragen, landete es in den Händen der Galak-Zentauren in Tausend Nadeln und enthält die fehlenden Riten, die benötigt werden, um den vollständigen Text zusammenzusetzen.",al={"zerlumptes manuskript","was ist das zerlumpte manuskript","zentauren manuskript"}}},fp="17,155,18.334.0,21.405.0,30.210.0,51.185.0,44.251.0,47.236.0,66.207.0,43.231.0"}
P.entries["quest:1803"] = {n="Foliant der Kabale",s="In Unterstadt suchen Hexenmeister der Horde für Jorah Annison die verstreuten Hälften des Folianten der Kabale. Einst in Lordaeron verwahrt, wurde das Grimoire auseinandergerissen, und seine Überreste liegen an den feindseligen Gewässern der Östlichen Königreiche und tief in Kalimdors Zentaurengebieten.",h="In Unterstadt suchen Hexenmeister der Horde für Jorah Annison die verstreuten Hälften des Folianten der...",kw={"galak","jorah annison","lordaeron","schimmliger foliant","süderstade","spalthufhöhle","zerlumptes manuskript","tausend nadeln","foliant der kabale","hexenmeisterquest"},ang={["class:Warlock"]="Als Hexenmeister holt Ihr den Folianten der Kabale als Übergangsritus für einen bereits erfahrenen Praktizierenden zurück. Sein verlorenes arkanes Wissen aus Lordaeron kann Euer Beschwörungsrepertoire erweitern.",["faction:Horde"]="Als Mitglied der Horde verfolgt Ihr die Spur des Manuskripts durch die Schluchten von Tausend Nadeln. Die Streitkräfte der Horde am Freiwindposten führen unablässig Krieg gegen die einheimischen Zentauren.",["race:Undead"]="Als Untoter bergt Ihr einen Folianten, der einst vor dem Fall des Königreichs in Lordaeron verwahrt wurde. Seine Rückkehr bringt okkultes Erbe aus Euren früheren menschlichen Leben zurück."},sec={{t="Ein geteiltes Erbe",b="Der Foliant der Kabale ruhte einst in Lordaerons Bibliothek. Jemand schändete das finstere Grimoire, riss fast die Hälfte seiner Seiten heraus und teilte es entzwei. Der erhaltene gebundene Text wurde in die Zwergenhallen von Eisenschmiede geschickt. Doch sein Transportschiff erlitt an der felsigen Küste westlich von Süderstade Schiffbruch, und die Seiten verrotten nun im seichten Wasser unter plündernden Murlocs."},{t="Über Kontinente verstreut",b="Die andere Hälfte gelangte von Lordaeron ins südliche Kalimdor. Tief in der Spalthufhöhle in Tausend Nadeln gehen die Galak-Zentauren grob mit dem Manuskript um. Ihr sucht die feuchte Küste von Hillsbrad nach dem Schimmligen Folianten ab und betretet dann staubige, wilde Zentaurenschluchten für das Zerlumpte Manuskript. Sobald beide Überreste Jorah Annison erreichen, ist der legendäre dunkle Text wieder vollständig und lesbar."}},faq={{q="Was ist der Foliant der Kabale?",a="Der Foliant der Kabale ist ein arkanes Grimoire dämonischer Rituale, das einst in Lordaerons Hauptstadt verwahrt wurde. Jemand schändete es und teilte es entzwei, bevor es über zwei Kontinente verstreut verloren ging.",al={"foliant der kabale hintergrund","was ist dieses buch","foliant der kabale"}},{q="Warum liegt ein Teil des Buches bei Süderstade?",a="Nachdem der Foliant geschändet worden war, sollte sein erhaltener gebundener Teil zu Gelehrten in Eisenschmiede gebracht werden. Das Schiff erlitt an der Küste westlich von Süderstade Schiffbruch, wodurch das Buch zwischen den dortigen Murlocs strandete.",al={"warum süderstade","schimmliger foliant herkunft","küste westlich von süderstade"}},{q="Wie gelangten die Seiten zu den Zentauren in Tausend Nadeln?",a="Etwa die Hälfte der Seiten wurde in Lordaeron aus dem ursprünglichen Folianten gerissen und fortgeschmuggelt. Durch Handel, Plünderung oder wandernde Hände gelangte das Zerlumpte Manuskript tief in die Spalthufhöhle, wo die Galak-Zentauren es in einer Truhe aufbewahren.",al={"warum haben zentauren es","tausend nadeln seiten","spalthufhöhle buch"}},{q="Wer ist Jorah Annison?",a="Jorah Annison ist ein Hexenmeister der Verlassenen im Magieviertel von Unterstadt. Er leitet aufstrebende Hexenmeister der Horde an, während sie vergessenes, verbotenes Wissen bergen und ihre Beherrschung dämonischer Kräfte vertiefen.",al={"jorah annison hintergrund","wer ist jorah"}},{q="Wer hat den Folianten ursprünglich geschändet?",a="Wer den Folianten geschändet hat, bleibt unbekannt. Jorah Annison beklagt den Schaden und fragt sich, wer einem Text von solcher okkulten Macht so etwas antun könnte.",al={"wer zerriss das buch","wer stahl die seiten","schänder des folianten"}},{q="Was macht Jorah mit dem Buch, sobald Ihr beide Teile zurückbringt?",a="Wenn Ihr sowohl den Schimmligen Folianten als auch das Zerlumpte Manuskript bringt, fügt Jorah Annison sie zu einem Band zusammen und liest seine Seiten. Er bereitet Euch auf die nächsten Schritte Eurer dämonischen Riten vor.",al={"was geschieht nach der abgabe","wiederhergestellter foliant"}}},fx={a3cceb5d={q="Warum will Jorah Annison das Tome of the Cabal?",a="Jorah Annison ist ein Hexenmeister-Gelehrter der Verlassenen, der sich dem Aufspüren verlorener fel-Überlieferungen widmet, die einst in Lordaeron beherbergt waren. Die Wiederherstellung des zerbrochenen Tome of the Cabal ermöglicht es ihm, seine okkulten Geheimnisse aus erster Hand zu studieren, während er vielversprechende Hexenmeister bei der Beherrschung gefährlicher, fortgeschrittener Beschwörungen anleitet.",al={"warum will jorah das","jorah annison motiv","warum tome of the cabal sammeln"}},["2b99c3ce"]={q="Was ist das Zerlumpte Manuskript?",a="Das Zerlumpte Manuskript ist die fehlende Hälfte des Tome of the Cabal, die herausgerissen wurde, als das Buch in Lordaeron geschändet wurde. Durch unbekannte Hände überquerten diese gestohlenen Seiten das Meer nach Kalimdor und landeten schließlich verschlossen in einer Truhe bei den Galak-Zentauren von Tausend Nadeln.",al={"was ist zerlumpte manuskript","zerlumpte manuskript lore","nutzen von zerlumptem manuskript"}},["968099ef"]={q="Was ist der Schimmlige Foliant?",a="Der Schimmlige Foliant enthält die geborgenen Überreste des Originaltextes, der für den Transfer nach Eisenschmiede bestimmt war. Er ging bei einem Schiffbruch an der Küste nahe Süderstade verloren und wurde von Murlocs geplündert; er birgt eine unverzichtbare Hälfte der Rituale der Cabal.",al={"was ist schimmliger foliant","schimmliger foliant lore","nutzen von schimmliger foliant"}}},fp="17,258,16.353.0,27.374.1,30.177.0,44.194.0,62.240.0,21.187.0,43.151.0,64.187.0"}
P.entries["quest:1804"] = {n="Foliant der Kabale",s="Im Brachland erwartet Strahad Farsan den Folianten und die Stäbe, die zur Bindung eines Felhunters nötig sind. Der Hexenmeister bringt sie, damit sein Zirkel den Ritus vorbereiten kann.",h="Im Brachland erwartet Strahad Farsan den Folianten und die Stäbe, die zur Bindung eines Felhunters nötig sind.",kw={"brachland","dragonmaw","felhunter","krom starkarm","ratschet","stäbe der kanalisierer","strahad farsan","foliant der kabale","sumpfland"},ang={["class:Warlock"]="Als Hexenmeister markiert die Unterwerfung eines Felhunters Euren Übergang von Pakten mit Wichteln und Leerwandlern zur Beherrschung räuberischer Dämonen, die arkane Magie verschlingen sollen.",["faction:Alliance"]="Als Beschwörer der Allianz reist Ihr zwischen Eisenschmiede, den nebligen Mooren des Sumpflands und Ratschet, dem neutralen Goblinhafen in Kalimdor.",["race:Dwarf"]="Als Zwerg kennt Ihr den Wert sorgfältiger Bewahrung. In Eisenschmiedes Hall of Explorers setzt Krom Starkarm zerstörte Relikte wieder zusammen."},sec={{t="Eine widerwillige Übergabe",b="Krom Starkarm bindet die zerfledderten Überreste des Folianten der Kabale in Eisenschmiedes Hall of Explorers. Der Zwergengelehrte trennt sich nur widerwillig von dem seltenen Werk, nachdem er sich eine Kopie hat versprechen lassen. Er gibt dem Hexenmeister auch ein frisches Schreiben von Strahad Farsan. Der Foliant enthält Riten zum Öffnen eines Zugangs zum Nether, doch Pergament allein kann sie nicht vollziehen."},{t="Gestohlene Relikte der Dragonmaw",b="Strahads Akolythen brauchen Werkzeuge, um die Energien zur Bindung eines Felhunters zu bündeln. Krom schickt den Hexenmeister ins Sumpfland, wo Zauberwirker der Dragonmaw Stäbe der Kanalisierer tragen. Die feindseligen Orcs bewachen die Stäbe. Ihnen entrissen, geben die Stäbe Strahads Zirkel ein Leitmedium, um den Riss zu kontrollieren und die beschworenen Energien zu stabilisieren."},{t="Zurück ins Brachland",b="An Strahads Turm über Ratschet vollenden der wiederhergestellte Foliant und die Stäbe der Kanalisierer die schwierigen Vorbereitungen. Der Text ist übersetzt und die Instrumente sind bereit. Strahad bereitet den gefährlichen Bindungsritus vor, bei dem der Wille des Beschwörers auf einen Hund der Brennenden Legion trifft."}},faq={{q="Warum braucht Strahad Stäbe der Kanalisierer?",a="Strahads Akolythen nutzen die Stäbe, um die Energien zur Beschwörung und Bindung eines Felhunters zu bündeln und zu stabilisieren. Das hilft zu verhindern, dass das Portal zusammenbricht oder außer Kontrolle gerät.",al={"warum stäbe der kanalisierer","zweck der stäbe der kanalisierer","wozu dienen die stäbe"}},{q="Wo findet man die Stäbe der Kanalisierer?",a="Orcische Zauberwirker der Dragonmaw im Sumpfland tragen die Stäbe der Kanalisierer, besonders in den von ihnen besetzten Sümpfen und Ruinen.",al={"wo bekommt man stäbe der kanalisierer","wer lässt stäbe der kanalisierer fallen","fundort der stäbe der kanalisierer"}},{q="Warum war Krom Starkarm an einem Hexenmeisterritual beteiligt?",a="Krom Starkarm ist ein meisterhafter Forscher in Eisenschmiede, der sich auf das Übersetzen, Bewahren und Wiederherstellen beschädigter alter Handschriften versteht. Sein Interesse an seltenen Altertümern führte dazu, dass er die verderbten Seiten des Folianten der Kabale wiederherstellte.",al={"warum krom","warum hilft ein zwerg aus eisenschmiede einem hexenmeister","krom starkarm hexenmeister"}},{q="Was geschieht, nachdem man Strahad den Folianten und die Stäbe übergeben hat?",a="Nachdem Ihr Strahad den Folianten und die Stäbe übergeben habt, beginnt er oben auf seinem Turm mit dem Bindungsritus. Ihr stellt Euch dem beschworenen Felhunter und versucht, ihn zu unterwerfen.",al={"was geschieht als nächstes","nächste quest nach foliant der kabale drei","was macht strahad"}},{q="Wer ist Strahad Farsan?",a="Strahad Farsan ist ein mächtiger Hexenmeister in einem einsamen Turm auf den Klippen über Ratschet im Brachland. Erfahrene Hexenmeister in ganz Kalimdor und den Östlichen Königreichen erkennen seine Meisterschaft der Dämonologie an.",al={"strahad farsan hintergrundgeschichte","wer ist strahad","kerl über ratschet"}},{q="Wird der Foliant der Kabale auch von der Horde genutzt?",a="Hexenmeister der Horde folgen ihren eigenen Riten des Folianten der Kabale, mit Hinweisen auf andere Kontakte in Kalimdor und Unterstadt statt auf Krom Starkarm in Eisenschmiede.",al={"horde foliant der kabale","machen orcs diese quest"}}},fx={["7a279078"]={q="Warum müsst Ihr den Dragonmaw-Clan im Sumpfland jagen?",a="Der Überrest des Dragonmaw-Clans, der sich im Sumpfland verschanzt hat, führt immer noch mächtige dunkle Magie, die von ihrer früheren Herrschaft übrig geblieben ist. Krom weiß, dass ihre Zauberwirker die spezialisierten Stäbe der Kanalisierung tragen, die benötigt werden, um Strahads Beschwörungskreis zu verankern. Um die Fokussierungen zu beanspruchen, müsst Ihr sie diesen feindseligen Orc-Zauberern direkt entreißen.",al={"warum dragonmaw orcs","sumpfland dragonmaw hexenmeister","wer hat stäbe der kanalisierung"}}},fp="17,143,19.338.0,30.322.0,19.270.1,41.163.0,39.125.0,51.223.0,55.138.1,22.203.0,51.163.0"}
P.entries["quest:1805"] = {n="Foliant der Kabale",s="Strahad Farsans Arbeit am Folianten der Kabale führt nun in feindliches Gebiet. Nachdem Ihr Jorah Annison geholfen habt, den Folianten wiederherzustellen, müsst Ihr drei Rods of Channeling erbeuten und sie zu Strahad nach Ratschet bringen.",h="Strahad Farsans Arbeit am Folianten der Kabale führt nun in feindliches Gebiet.",kw={"lager der grollhauer","dragonmaw","teufelsjäger","jorah annison","ratschet","rute des kanalisierens","strahad farsan","foliant der kabale","sumpfland"},ang={["class:Warlock"]="Als Hexenmeister steht Euch eine Prüfung Eurer Entschlossenheit bevor. Gefährliche Ritualreagenzien in feindlichen Ländern zu beschaffen, erfordert das Wissen und den Mut, einen räuberischen Teufelsjäger an Euren Dienst zu binden.",["faction:Horde"]="Als Mitglied der Horde stellt Ihr Euch im Sumpfland abtrünnigen Dragonmaw, erbitterten Feinden von Thralls Horde. Ihre Kanalisierungsstäbe zu erbeuten, dient den Interessen der Horde.",["race:Orc"]="Als Orc erinnert Euch der Kampf gegen abtrünnige Dragonmaw im Sumpfland an den dunklen, reuelosen Pfad, den die Horde mühsam hinter sich ließ.",["race:Undead"]="Als Untoter könnt Ihr Jorah Annisons Arbeit in Unterstadt sehen. Hexenmeister der Verlassenen studieren verbotene arkane Schriften, um in der Praxis die Oberhand zu gewinnen."},sec={{t="Geheimnisse des Rekonstruierten Folianten",b="In Unterstadt untersucht Jorah Annison die geborgenen Fragmente des Folianten der Kabale. Der Gelehrte der Verlassenen setzt dessen unheimliche Passagen zusammen und begrüßt das seltene Wissen, das sie bergen. Dann überbringt Jorah eine dringende Nachricht von Strahad Farsan. Wissen allein kann keinen Teufelsjäger binden; ein Hexenmeister braucht präzise Instrumente, um dämonische Macht in einem Bindungskreis zu bündeln."},{t="Vorstoß ins Sumpfland",b="Strahad benötigt drei Rods of Channeling, die abtrünnige Orcs des Dragonmaw-Klans bei sich tragen. Sie hausen in den Ruinen des Lagers der Grollhauer im Sumpfland, weit entfernt von den Ländern der Horde. Ihr müsst umkämpftes Gebiet betreten und Euch den Überresten des Klans stellen, die die moderne Horde hassen und Forscher der Allianz abschlachten."},{t="Rückkehr nach Ratschet",b="Mit den gesicherten Stäben und dem Rekonstruierten Folianten kehrt Ihr über das Meer zu Strahad Farsans Turm oberhalb von Ratschet zurück. Strahad begrüßt Euch mit grimmiger Genugtuung. Die Komponenten des Rituals sind beisammen, und eine gefährliche Willensprüfung gegen eine Bestie aus dem Wirbelnden Nether steht bevor."}},faq={{q="Was ist der Zweck dieser Quest?",a="Ihr bringt den wiederhergestellten Folianten der Kabale und drei Rods of Channeling zu Strahad Farsan oberhalb von Ratschet, dem dritten Schritt der Questreihe für Hexenmeister der Horde zur Beschwörung eines Teufelsjägers.",al={"warum diese quest machen","zweck der quest","wozu dient der foliant der kabale"}},{q="Wer ist Jorah Annison?",a="Jorah Annison ist ein Hexenmeister und Gelehrter der Verlassenen im Magieviertel von Unterstadt. Jorah untersucht esoterische und dunkle Schriften und hilft anderen Praktizierenden, zerrissene Zauberbücher wie den Folianten der Kabale zusammenzusetzen.",al={"wer ist jorah","jorah annison geschichte"}},{q="Warum werden Rods of Channeling benötigt?",a="Die Stäbe geben einem Hexenmeister präzise Kontrolle, wenn er einen Teufelsjäger beschwört und unterwirft. Sie bündeln die Macht des Rituals und formen seinen Beschwörungskreis, damit der Hexenmeister den Dämon bezwingt, statt verschlungen zu werden.",al={"warum rods of channeling","zweck der stäbe"}},{q="Wo befinden sich die Dragonmaw-Orcs für diese Quest?",a="Der Dragonmaw-Klan hält das Lager der Grollhauer im Sumpfland besetzt, jenseits des Meeres in Khaz Modan. Seine Knochenwächter tragen die Kanalisierungsstäbe.",al={"wo dragonmaw finden","dragonmaw standort sumpfland","lager der grollhauer"}},{q="Wer ist Strahad Farsan?",a="Strahad Farsan ist ein menschlicher Hexenmeister, der mit den dunklen Zauberwirkern der Horde verbündet ist. Er wirkt in einem einsamen Turm auf den Klippen oberhalb von Ratschet, dem Goblinhafen im Brachland.",al={"wer ist strahad","strahad farsan ratschet"}},{q="Was geschieht nach Abschluss dieser Quest?",a="Eure Lieferung führt zur Quest „The Binding“. Strahad weist Euch dann an, einen Beschwörungskreis zu ziehen und Euch einem beschworenen Teufelsjäger im magischen Kampf zu stellen, um die Bestie zu beherrschen.",al={"what comes next","nächste quest nach dem folianten"}}},fx={["9475dbd0"]={q="Warum hilft Euch Jorah Annison?",a="Jorah Annison ist ein Kartograph der Verlassenen im Magieviertel der Unterstadt, der nach langem Erschöpfen der spärlichen Auswahl an Geographie-Texten vor Ort hungrig nach arkanem und esoterischem Lesematerial ist. Im Austausch für die Gelegenheit, das rekonstruierte Tome of the Cabal zu studieren, gibt er Anweisungen von Strahad Farsan weiter und verrät Euch, wo Ihr die seltenen Kanalisierungsstäbe erwerben könnt, die Ihr für Eure Ausbildung benötigt.",al={"warum hilft jorah","jorah annison motiv","was will jorah"}},cff1ec65={q="Warum haben die Dragonmaw-Orcs die Stäbe der Kanalisierung?",a="Der abtrünnige Dragonmaw-Clan unterhält Festungen im gesamten Sumpfland und beherbergt dunkle Zauberwirker und Knochenwächter, die finstere Magien praktizieren, die sich von der modernen Horde unterscheiden. Sie benutzen mächtige Kanalisierungsstäbe, um rohe magische Energien zu fokussieren und zu binden, was ihre Lager zu den besten Orten macht, um die arkanen Foki zu bergen, die Strahad für Beschwörungsrituale benötigt.",al={"dragonmaw orcs sumpfland","wer hat die stäbe der kanalisierung","warum dragonmaw orcs"}}},fp="17,208,33.368.0,25.304.0,17.280.1,34.167.0,21.220.0,34.198.0,52.137.0,22.164.0,41.162.1"}
P.entries["quest:1806"] = {n="Die Prüfung der Rechtschaffenheit",s="An Jordan Stillbrunns Schmiede vor Eisenschmiede bringt Ihr die Materialien für den Kriegshammer eines Paladins. In den Östlichen Königreichen und Kalimdor gesammelt, helfen sie, aus einem Lehrling einen anerkannten Streiter des Lichts zu machen.",h="An Jordan Stillbrunns Schmiede vor Eisenschmiede bringt Ihr die Materialien für den Kriegshammer eines...",kw={"bosch verigan","dun morogh","schmiede","hammer","eisenschmiede","jordan stillbrunn","paladin","prüfung der rechtschaffenheit","verigan"},ang={["class:Paladin"]="Als Paladin verdient Ihr Euch durch Eure gefährlichen Reisen durch ferne Lande Verigans Faust, eine Waffe im Dienste der Rechtschaffenheit.",["profession:Blacksmithing"]="Als Schmied erkennt Ihr, wie Jordan Stillbrunns meisterhafte Arbeit rohem Stahl und geborgenen Materialien einen heiligen Zweck verleiht.",["race:Dwarf"]="Als Zwerg tragt Ihr einen Hammer, der das Andenken an Bosch Verigan bewahren soll, einen hochgeschätzten Zwergenpaladin, der die Widerstandskraft von Khaz Modan verkörperte."},sec={{t="Die Ehrengabe eines Schmieds",b="Jordan Stillbrunn arbeitet an seiner Schmiede vor den Toren von Eisenschmiede. Er beneidet Paladine, die durch die Lande ziehen, ist jedoch stolz darauf, ihrer Sache zu dienen. Ihr bringt ihm seltene Materialien, die aus finsteren Krypten, versunkenen Ruinen und gefährlichen Minen geborgen wurden. Mit ihnen hält der Meisterschmied sein Versprechen und schmiedet eine Waffe, die eines wahren Verteidigers würdig ist."},{t="Das Vermächtnis von Bosch Verigan",b="Jordan Stillbrunn nennt den fertigen Kriegshammer Verigans Faust, nach Bosch Verigan, einem hochgeschätzten Zwergenpaladin und seinem lieben Freund. In seinem eigenen Namen und dem seiner Frau legt er die heilige Waffe in die Hände eines jungen Streiters. Durch sie bestehen das Andenken und die Tapferkeit seines gefallenen Freundes gegen die Finsternis fort, die Azeroth bedroht."}},faq={{q="Was geschieht in diesem Schritt der Quest?",a="Jordan Stillbrunn verarbeitet die von Euch gesammelten Komponenten an seinem Amboss und bearbeitet heißes Metall in seiner Schmiede mit Hammerschlägen. Wenn die Arbeit getan ist, überreicht er Euch die fertige Waffe.",al={"prüfung der rechtschaffenheit ende","jordan schmiedet waffe","verigan zwischensequenz"}},{q="Wer ist Bosch Verigan?",a="Bosch Verigan war ein hochgeschätzter Zwergenpaladin und ein enger Freund von Jordan Stillbrunn. Jordan benannte den neu geschmiedeten Zweihandhammer nach ihm und ehrte damit seine Hingabe an das Heilige Licht.",al={"wer ist verigan","verigans faust namensgeber","bosch verigan"}},{q="Wo wird der Hammer geschmiedet?",a="Jordan Stillbrunn schmiedet den Hammer direkt vor den großen Toren von Eisenschmiede in den verschneiten Gipfeln von Dun Morogh. Dort stehen seine Schmiede und sein Amboss.",al={"jordan stillbrunn standort","wo ist die schmiede","dun morogh amboss"}},{q="Warum brauchte Jordan seltene Materialien aus aller Welt?",a="Jordan Stillbrunn brauchte seltene Materialien aus gefährlichen Orten auf der ganzen Welt, um eine Waffe von außergewöhnlicher Balance und heiliger Resonanz zu schmieden. Die Erze, das Holz und die Edelsteine wurden benötigt, um einen Hammer zu fertigen, der dem heiligen Zorn eines Paladins standhalten konnte.",al={"warum gathering materials","questkomponenten prüfung der rechtschaffenheit"}},{q="Kämpft Jordan Stillbrunn auch selbst in Schlachten?",a="Jordan Stillbrunn ist ein Schmied, kein wandernder Krieger. Er beneidet jene, die durch die Lande ziehen, doch das Schmieden von Waffen für Verteidiger des Lichts erfüllt ihn mit Stolz und Sinn.",al={"ist jordan ein krieger","jordan stillbrunn kämpfer"}},{q="Was bedeutet es für einen Paladin, diesen Hammer zu erhalten?",a="Der Erhalt des Hammers markiert das Ende der langen Prüfungen eines Paladins. Er zeigt, dass der Träger den Mut, die Ausdauer und die heilige Überzeugung besitzt, in Azeroths gefährlichsten Winkeln für das Licht einzutreten.",al={"verigans faust bedeutung","paladin initiationsritus"}}},fx={["49955bc3"]={q="Warum will Jordan Stillbrunn diesen Hammer schmieden?",a="Jordan Stillbrunn gibt zu, einen Anflug von Neid zu verspüren, wenn er die gewagten Heldentaten von Champions in ganz Azeroth sieht, da er eher Schmied als Abenteurer ist. Indem er Verigans Faust aus den seltenen Komponenten schmiedet, die Ihr gesammelt habt, kann er einem Verteidiger das Licht direkt unterstützen und auf seine eigene, lebenswichtige Weise dazu beitragen, das Reich sicher zu halten.",al={"jordan stillbrunn motiv","warum die waffe schmieden","warum schmiedet jordan den hammer"}}},fp="25,221,17.330.0,27.317.0,43.161.0,21.181.0,35.137.0,59.239.0,50.168.0,54.191.0"}
P.entries["quest:181"] = {n="Der Blick zu den Sternen",s="In Dunkelhain sucht Viktori Prism'Antras das letzte Teil für sein Teleskop. Sein Gestell ist fertig, doch kein Glas vor Ort ist groß genug für die Linse, die seine Pläne erfordern.",h="In Dunkelhain sucht Viktori Prism'Antras das letzte Teil für sein Teleskop.",kw={"cog","dunkelhain","der blick zu den sternen","monokel","teleskop","viktori prism'antras","ogerhort vul'gol","zzarc'vul"},ang={["faction:Alliance"]="Als Reisender der Allianz könnt Ihr sehen, wie Dunkelhain den Schrecken und Bestien ringsum standhält. Viktoris Streben nach den Sternen ist ein kleines Zeichen für das Durchhaltevermögen der Zivilbevölkerung.",["profession:Engineering"]="Als Ingenieur könnt Ihr die Kühnheit würdigen, mit einem gewaltigen Ogermonokel die Anforderungen an eine astronomische Linse zu erfüllen.",["race:Gnome"]="Als Gnom wisst Ihr, dass Erfindungsgeist einen unwahrscheinlichen Fund in ein nützliches Bauteil verwandeln kann. Viktoris Teleskoppläne verlangen eine Linse aus dem Monokel eines Ogers."},sec={{t="Das letzte Teil",b="Viktori Prism'Antras baut in Dunkelhain ein Teleskop nach Plänen von Cog Glitzspinner, einem Gnomeningenieur. Messingrohre und stabile Halterungen hat er aus örtlichen Beständen zusammengetragen. Doch der Entwurf verlangt eine ungewöhnlich große Fokussierlinse. Vergrößerungsgläser und optische Bauteile von Händlern aus Sturmwind sind zu klein, daher sucht Viktori das benötigte Teil abseits gewöhnlicher Materialien."},{t="Das Okular des Ogers",b="Am Ogerhort Vul'Gol drängen sich feindselige Oger in den südlichen Hügeln. Einer von ihnen, Zzarc'Vul, trägt ein Glasmonokel, das groß genug für Viktoris Teleskop ist. Es Zzarc'Vul abzunehmen, würde Viktori die Linse verschaffen, die Cogs Pläne verlangen. Dann könnte er das Teleskop fertigstellen und in den Himmel über dem schattigen Blätterdach des Dämmerwalds blicken."}},faq={{q="Wer ist Viktori Prism'Antras?",a="Viktori Prism'Antras ist ein Astronom und Gelehrter, der in einer Hütte oben am Hügel in Dunkelhain lebt. Obwohl Düsternis über dem Dämmerwald liegt, widmet er sich weiterhin der Fertigstellung seines Teleskops und dem Studium der Sterne.",al={"wer ist viktori","viktori prism'antras"}},{q="Wo kann ich Zzarc'Vul finden?",a="Zzarc'Vul befindet sich im Ogerhort Vul'Gol im südlichen Dämmerwald. Er durchstreift das Lager und das Höhlennetz im schwer bewachten Gebiet der Oger.",al={"zzarc'vul fundort","wo ist der oger","ogermonokel fundort"}},{q="Warum besitzt ein Oger ein Monokel?",a="Zzarc'Vul trägt ein übergroßes Monokel. Es ist die einzige Linse in der Gegend, die groß genug ist, um Cogs Teleskopplänen zu entsprechen.",al={"warum ogermonokel","ogermonokel hintergrund"}},{q="Was geschieht, sobald das Gerät fertiggestellt ist?",a="Mit dem Monokel kann Viktori die letzte Linse des Teleskops einsetzen. Sobald das Gerät fertig ist, kann er sich wieder dem Studium der Sterne über dem trostlosen Wald widmen.",al={"teleskop fertig","questabschluss"}},{q="Wer hat das Teleskop entworfen?",a="Cog, ein Gnomeningenieur, hat das Teleskop entworfen. Seine Pläne verlangen besondere Bauteile, ein Metallgestell und eine Linse, die weit größer ist als gewöhnliche zwergische oder gnomische Brillen.",al={"cogs baupläne","wer hat das teleskop gebaut"}},{q="Kann man den Ogerhort Vul'Gol gefahrlos allein betreten?",a="Nein. Feindselige Oger bevölkern den Ogerhort Vul'Gol, patrouillieren in Gruppen und bewachen schmale Pfade. Tief im Inneren nach Zzarc'Vul zu suchen, ist für einen einzelnen Reisenden gefährlich.",al={"vul'gol schwierigkeit","ogerhort sicher"}}},fx={ac1c4dd0={q="Warum will Viktori Prism'Antras, dass dies erledigt wird?",a="Viktori ist ein exzentrischer Gelehrter, der sich dem Bau eines speziellen Apparats zur Sternenbeobachtung nach den Bauplänen von Cog widmet. Er hat beträchtliche Anstrengungen unternommen, um empfindliche Teile zu sammeln, aber seinem Entwurf fehlt noch ein Objektiv von ausreichender Größe, um in den Himmel zu spähen. Sobald das Teleskop vollständig zusammengebaut ist, wird er endlich in der Lage sein, seine astronomische Forschung aus dem Düsteren von Dunkelhain wieder aufzunehmen.",al={"warum viktori ein monokel braucht","viktori prism'antras ziel","look to the stars motiv"}},f331a2d2={q="Wozu dient das Ogermonokel?",a="Die Baupläne für Viktoris Gerät zur Sternenbeobachtung erfordern ein ungewöhnlich großes optisches Objektiv. Anstatt in der schattigen Isolation von Dämmerwald eines von Grund auf neu zu schleifen, erkannte Viktori, dass das übergroße Monokel, das der Oger Zzarc'Vul trägt, genau die Abmessungen und das fokussierende Glas bietet, die zur Vervollständigung des Apparats benötigt werden.",al={"zweck des ogermonokels","warum das monokel des ogers","wofür wird das monokel verwendet"}},bbeac028={q="Wer ist Zzarc'Vul?",a="Zzarc'Vul ist ein bekannter Oger, der unter seinesgleichen im Ogerhort Vul'Gol in den südlichen Hügeln von Dämmerwald lebt. Im Gegensatz zu seinen brutalen Gefährten trägt er ein riesiges Monokel, das die Aufmerksamkeit von Viktori Prism'Antras auf sich gezogen hat, was ihn zum letzten Hindernis zwischen dem Gelehrten und seinem fertiggestellten Teleskop macht.",al={"wer ist zzarcvul","wer ist der oger","ziel zzarc'vul"}}},fp="17,161,15.381.0,19.316.1,28.197.0,27.130.0,35.114.0,42.145.0,27.166.0,42.159.0"}
P.entries["quest:1818"] = {n="Gespräch mit Dillinger",s="In Brills Taverne Zur Galgenschlinge schickt Austil de Mon Kämpfer auf eine gefährliche Mission für Lady Sylvanas. Die Weisung führt kampftaugliche Rekruten zu Todeswache Dillinger am westlichen Ende des Dorfes.",h="In Brills Taverne Zur Galgenschlinge schickt Austil de Mon Kämpfer auf eine gefährliche Mission für Lady...",kw={"austil de mon","brill","todeswache dillinger","gespräch mit dillinger","tirisfal","ulag the cleaver","unterstadt"},ang={["class:Warrior"]="Die Befehlshaber der Todeswachen schätzen Kampfgeist, daher stellt Dillingers Ruf Euer Kampfgeschick an der Front auf die Probe.",["faction:Horde"]="Den Verteidigungsaufrufen aus Unterstadt zu folgen, stärkt den Zusammenhalt zwischen den Verbündeten der Horde in Kalimdor und den neu aufgenommenen Verlassenen.",["race:Undead"]="Als frisch befreiter Verlassener beweist Ihr mit Eurer Antwort auf Dillingers Ruf entscheidend Eure Hingabe an die Dunkle Fürstin und die Verteidigung von Tirisfal."},sec={{t="Ein Ruf an die Front",b="In der Taverne Zur Galgenschlinge in Brill sucht Kriegerlehrer Austil de Mon Kämpfer, die bereit sind, der Dunklen Fürstin zu dienen. Wenn die Todeswachen fähige Hände brauchen, schickt er unerprobte Rekruten ins Feld. Todeswache Dillinger wacht über die Sicherheit am Westrand von Brill und hat für eine dringende Aufgabe jemanden mit kriegerischem Können angefordert."},{t="Die Treuen auf Probe",b="Die Verlassenen müssen ihre militärische Überlegenheit an der Front von Tirisfal ständig unter Beweis stellen. Nahe dem Friedhof von Brill kümmert sich Dillinger um örtliche Übergriffe. Euch bei ihm zu melden, stellt Euer Kampfgeschick und Eure Treue zur neu geschmiedeten Nation der Verlassenen auf die Probe."}},faq={{q="Wer schickt mich auf diese Mission?",a="Austil de Mon, der Kriegerlehrer in Brills Taverne Zur Galgenschlinge, erkennt potenzielle Soldaten und schickt sie zur Unterstützung von Todeswache Dillinger.",al={"questgeber","austil de mon","wer startet gespräch mit dillinger"}},{q="Wo ist Todeswache Dillinger zu finden?",a="Todeswache Dillinger ist am Westrand von Brill in Tirisfal stationiert, nahe dem Friedhofseingang.",al={"dillinger standort","wo ist dillinger","dillinger finden"}},{q="Welchen Zweck hat die Meldung bei Dillinger?",a="Dillinger braucht einen kampftauglichen Streiter für eine Kampfmission, um Brill zu verteidigen und seine Treue zur Sache der Verlassenen zu beweisen.",al={"warum mit dillinger sprechen","dillinger zweck"}},{q="Welchen Auftrag hält Dillinger bereit?",a="Wenn Ihr Euch bei Todeswache Dillinger meldet, gibt er Euch den Auftrag, Ulag das Spaltbeil zu jagen, eine gefährliche Bedrohung.",al={"was will dillinger","nächste quest dillinger"}},{q="Erhalten auch andere Völker der Horde diese Weisung?",a="Jeder Krieger der Horde, dem die Amtsträger von Unterstadt vertrauen, kann den Auftrag übernehmen, doch er soll hauptsächlich das Kampfgeschick von Rekruten bei der Verteidigung von Tirisfal prüfen.",al={"nur für untote","können orcs das machen"}},{q="Warum schickt mich ein Kriegerlehrer zu Dillinger?",a="Austil de Mon bildet in Brills Taverne Zur Galgenschlinge Krieger aus. Er schickt Abenteurer, die gerade die nötigen Fähigkeiten erworben haben, zu Befehlshabern der Todeswachen, die sofort tatkräftige Unterstützung brauchen.",al={"warum start in unterstadt","austil de mon rolle"}}},fx={["277a5d32"]={q="Warum schickt Austil de Mon Euch zu Dillinger?",a="Austil de Mon fungiert als Zwischenhändler und weist aufstrebenden Verlassenen, die nach höherem Ansehen streben, den Weg dorthin, wo ihre kriegerischen Talente dem Reich dienen können. Indem er fähige Hände aus Brills Taverne Zur Galgenschlinge hinaus und aufs Feld unter das Kommando von Todeswache Dillinger leitet, stellt er sicher, dass die Siedlungen an vorderster Front Verstärkung erhalten, während er zugleich prüft, ob Ihr echten Wert und Hingabe für die Sache von Fürstin Sylvanas besitzt.",al={"austil de mon motiv","warum zu dillinger schicken","austil de mon grund"}}},fp="20,190,22.325.0,20.240.0,29.140.0,40.106.0,46.126.0,45.116.1,40.169.0,48.148.0"}
P.entries["quest:1819"] = {n="Ulag der Spalter",s="Unter einem Mausoleum nördlich von Brill wartet Ulag der Spalter als Prüfung für junge Verlassene. Todeswache Dillinger schickt Euch, den Gefangenen zu befreien und Euch ihm im Kampf zu stellen.",h="Unter einem Mausoleum nördlich von Brill wartet Ulag der Spalter als Prüfung für junge Verlassene.",kw={"brill","todeswache dillinger","dillinger","mausoleum","geißel","totenkopfstein","ulag","ulag der spalter"},ang={["class:Warrior"]="Als Krieger der Verlassenen stellt Ihr Euch einer frühen Mutprobe gegen einen mächtigen Streiter der Geißel, der noch immer unter der Kontrolle des Lichkönigs steht.",["race:Undead"]="Als Untoter erkennt Ihr an Ulags Schicksal den Schrecken der Geißelherrschaft: Manche Verlassene konnten sich befreien, während andere dem Lichkönig weiterhin als Sklaven dienen."},sec={{t="Ein gefesselter Geißelknecht",b="Nachdem die Geißel über Lordaeron hinweggefegt war, nahmen die Verlassenen einen ungewöhnlichen untoten Krieger gefangen, der sich Ulag der Spalter nannte. Sein Verstand blieb klar, doch der Lichkönig hielt seinen Geist weiterhin in mentaler Knechtschaft. Unter einem Mausoleum nördlich von Brill banden ihn die Verlassenen mit einem magischen Siegel. Sie hofften, zu ergründen, wie die Geißel einen Geist in Ketten legt, und Ulag aus ihrer Gewalt zu befreien."},{t="Die Prüfung des Henkers",b="Die Verlassenen konnten Ulag nicht vom Befehl des Lichkönigs befreien. Nun macht Todeswache Dillinger den Gefangenen zur Kampfprüfung für aufstrebende Krieger der Verlassenen. Rührt den Totenkopfstein vor der Krypta an, und die Schutzzauber brechen und befreien Ulag aus seinem Gefängnis. Ein Krieger muss ihm mit einer Axt entgegentreten. Der Tod wird ihn endlich erlösen."}},faq={{q="Wer ist Ulag der Spalter?",a="Ulag der Spalter war ein untoter Krieger, den die Verlassenen während des Einfalls der Geißel in Tirisfal gefangen nahmen. Er behielt seinen Verstand und seine Identität, blieb aber unter dem Befehl des Lichkönigs.",al={"ulag hintergrundgeschichte","wer ist ulag","ulag der spalter identität"}},{q="Warum wurde Ulag unter dem Mausoleum eingesperrt?",a="Die Verlassenen versiegelten Ulag unter dem Mausoleum, um die Kontrolle des Lichkönigs über seinen Geist zu untersuchen. Sie hofften, die mentale Bindung zu durchtrennen, doch es gelang ihnen nicht.",al={"warum ist ulag eingesperrt","mausoleum gefangener tirisfal"}},{q="Warum wollen die Todeswachen Ulag jetzt töten lassen?",a="Die Verlassenen konnten Ulag nicht aus der Gewalt des Lichkönigs befreien und entschieden, dass nur noch der Tod ihm Gnade gewähren konnte. Todeswache Dillinger machte die Hinrichtung zu einer Prüfung von Mut und Disziplin für angehende Krieger.",al={"warum ulag töten","grund für ulags tötung"}},{q="Wie wird Ulag herbeigerufen?",a="Ulag wird unter einem Mausoleum unmittelbar nördlich von Brill gefangen gehalten. Berührt den Totenkopfstein nahe der Gruft, um das magische Siegel zu brechen, und Ulag erhebt sich zum Angriff.",al={"wie ulag herbeirufen","wo ist ulag","ulag totenkopfstein"}},{q="Wer erteilt den Auftrag, Ulag zu töten?",a="Todeswache Dillinger bewacht die Straße, die im Westen aus Brill in Tirisfal hinausführt. Er schickt Krieger der Verlassenen, die weitere Unterweisung suchen, in den Kampf gegen Ulag.",al={"questgeber ulag","wer schickt zu ulag"}},{q="Was geschieht nach Ulags Niederlage?",a="Nachdem Ihr Ulags Tod bestätigt habt, erkennt Todeswache Dillinger Euren Mut an und schickt Euch zu Coleman Heller in Brill, um Eure Ausbildung fortzusetzen.",al={"nach ulag","ulag folgequest"}}},fx={["6de55395"]={q="Warum lässt Todeswache Dillinger Euch gegen Ulag antreten, anstatt sich selbst darum zu kümmern?",a="Todeswache Dillinger stellt Euer Können auf die Probe. Ulag war kein unbedeutender Diener der Geißel, und sich ihm allein zu stellen, beweist, ob Ihr über das Geschick, den Mut und die Entschlossenheit verfügt, die von einem wahren Krieger im Dienste von Lady Sylvanas verlangt werden. Dillinger bewacht Brill und überwacht Eure Ausbildung; der Gang in die Gruft dient als Eure Prüfung durch Kampf, um zu zeigen, dass Ihr einer fortgeschrittenen Ausbildung würdig seid.",al={"warum ich dillinger","warum ulag selbst töten","warum spieler zu ulag schicken"}}},fp="16,162,22.371.0,23.315.0,24.188.0,44.142.0,44.196.0,21.142.0,33.146.0,36.146.0"}
P.entries["quest:182"] = {n="Die Trollhöhle",s="Im südlichen Coldridgetal schickt Grelin Weißbart Euch gegen Frostmane-Welpen aus, die sich in einer Höhle niederlassen. Ihr wachsendes Lager bedroht nahe gelegene zwergische Gehöfte.",h="Im südlichen Coldridgetal schickt Grelin Weißbart Euch gegen Frostmane-Welpen aus, die sich in einer Höhle...",kw={"das coldridgetal","dun morogh","frostmane","grelin weißbart","troggs","trolle","welpe"},ang={["class:Hunter"]="Als Jäger könnt Ihr die Bergklüfte rund um die südliche Höhle als hartes Bewährungsgelände nutzen und feindselige Beute aus den Berghöhen aufscheuchen.",["race:Dwarf"]="Als Bronzebeard-Zwerg stellt Ihr Euch einer Bedrohung des Grenzlands und einer uralten Bergfehde, wenn Ihr gegen Frostmane-Kriegsbanden zu den Waffen greift.",["race:Gnome"]="Als Gnom, der nach dem Fall Gnomeregans in Dun Morogh Zuflucht sucht, könnt Ihr Euren zwergischen Gastgebern mit Verstand und Waffen gegen die umliegenden Bedrohungen helfen."},sec={{t="Augen in der Kälte",b="Grelin beobachtet das gefrorene Tal von einer Klippe aus, während Eisenschmiedes Soldaten auf den Schneefeldern gegen Troggs kämpfen. Er und sein Bruder Senir kamen auf Befehl der Gebirgsbehörden, um herauszufinden, ob die einheimischen Eistrolle das Kernland bedrohten. Jetzt hält Grelin allein Wache und verfolgt ihre Bewegungen entlang der südlichen Zugänge."},{t="Ein Präventivschlag",b="Grelin entdeckte, dass sich der örtliche Frostmane-Klan in einer tiefen Höhle am südlichen Gebirgskamm des Coldridgetals niederließ. Er hält eine vollständige Mobilisierung für eine Verschwendung zwergischer Streitkräfte und heuert deshalb fähige Freiwillige vor Ort an, um die aggressiven Welpen zu dezimieren. Die Reihen der jungen Kämpfer zu lichten, könnte das Lager schwächen, bevor die Frostmane koordinierte Überfälle auf nahe gelegene zwergische Gehöfte beginnen."}},faq={{q="Warum schickt Eisenschmiede keine regulären Soldaten, um sich um diese Trolle zu kümmern?",a="Der Senat und das Militär von Eisenschmiede sind durch die plötzliche, verheerende Trogginvasion in ganz Dun Morogh überlastet. Späher wie Grelin Weißbart heuern unabhängige Abenteurer an, um kleinere Bedrohungen wie Trollkriegsbanden zu bekämpfen.",al={"warum keine zwergenarmee","wo sind die wachen","warum abenteurer anheuern"}},{q="Wer sind die Frostmanetrolle?",a="Die Frostmane sind ein einheimischer Stamm von Eistrollen aus den eisigen Bergklüften Dun Moroghs. Schon lange streiten sie mit Bronzebeard-Zwergen und Gebirgsjägern um Jagdgründe, Gebiete und uralte Gebirgspässe.",al={"frostmane-klan","trolle in dun morogh","wer sind die frostmane"}},{q="Wo liegt die Trollhöhle?",a="Die Höhle liegt am südlichen Gebirgskamm des Coldridgetals, südlich von Grelin Weißbarts Beobachtungslager.",al={"lage der trollhöhle","wo ist die höhle","wo sind die welpen"}},{q="Wer ist Grelin Weißbart?",a="Grelin Weißbart ist ein Späher aus Eisenschmiede, der im Coldridgetal stationiert ist. Sein Bruder Senir erkundet andere Teile Dun Moroghs, während Grelin feindselige Trollgruppen beobachtet und den Anführern der Zwerge Bericht erstattet.",al={"grelin","questgeber","weißbart"}},{q="Warum nimmt Grelin gezielt Frostmane-Welpen ins Visier?",a="Grelin nimmt die Frostmane-Welpen ins Visier, weil ihre Siedlung im südlichen Coldridgetal wächst und auch jugendliche Krieger zu ihren Bewohnern zählen. Diese jungen Kämpfer zu töten, könnte verhindern, dass die Bande stark genug wird, um zwergische Versorgungslinien zu bedrohen.",al={"warum welpen","warum junge trolle angreifen"}},{q="Was geschieht nach der Dezimierung der Trolle in der Höhle?",a="Nachdem Ihr die Trolle in der Höhle dezimiert habt, schlagen sie nachts zurück. Sie überfallen Grelins Lager und stehlen sein persönliches Feldtagebuch, das Ihr aus den Tiefen ihrer Höhlen zurückholen müsst.",al={"was kommt danach","folgequest der trollhöhle"}}},fx={["9e422164"]={q="Warum will Grelin Weißbart, dass man sich um die Trolle kümmert?",a="Grelin und sein Bruder Senir wurden durch Das Coldridgetal entsandt, um zu beurteilen, ob die einheimischen Frostmähneneistrolle eine ernsthafte Bedrohung für das Reich darstellen. Da der Senat von Eisenschmiede bereits durch den Aufstand der Troggs andernorts überlastet ist, hofft Grelin, diese Ansammlung im Keim zu ersticken, bevor sie zu einer Krise eskaliert, die reguläre Truppen erfordert.",al={"warum die trolle töten","grelin weißbart motiv","warum die trollhöhle säubern"}}},fp="14,158,16.322.0,19.361.0,70.225.0,29.210.0,32.115.0,25.201.0,53.251.0,36.171.1"}
P.entries["quest:1820"] = {n="Gespräch mit Coleman",s="In Brill schickt Todeswache Dillinger bewährte Kämpfer zu Coleman Heller, damit sie ihm helfen. Ihr Treffen in der Taverne eröffnet eine private Angelegenheit rund um die alten Ländereien der Agamands.",h="In Brill schickt Todeswache Dillinger bewährte Kämpfer zu Coleman Heller, damit sie ihm helfen.",kw={"agamand","brill","coleman heller","todeswache dillinger","verlassene","taverne zur galgenfrist","horde","tirisfal"},ang={["faction:Horde"]="Als Reisender der Horde, der hilft, Lordaeron zu sichern, findet Ihr durch Begegnungen mit Brills Bewohnern Zugang zu Aufgaben in ganz Tirisfal.",["race:Undead"]="Viele Verlassene hegen neben ihrer Treue zur Dark Lady auch persönlichen Groll. Coleman Hellers Anliegen zeigen, wie persönlicher Verlust und die Verteidigung Tirisfals miteinander verbunden sind."},sec={{t="Ein Wort der Wache",b="Ihr habt geholfen, ernste Bedrohungen nahe Brill einzudämmen, darunter Ulag das Spaltbeil. Deshalb vertraut Todeswache Dillinger auf Eure Stärke. Er bewacht die Straßen in den Ort und wählt aus, wer Aufgaben jenseits der üblichen Patrouillen übernehmen kann. Da er Euch für bereit hält, verweist er Euch an Leute, die besondere Hilfe brauchen."},{t="Eine persönliche Fehde",b="Nicht jeder Kampf in Tirisfal beginnt mit Befehlen aus Unterstadt. Die überlebenden Untoten Lordaerons hegen noch immer Groll um die Ländereien, Familien und Vermögen, die sie zurückließen. Coleman Heller wartet in der Taverne 'Zur Galgenfrist' auf einen Kämpfer, der gegen Bedrohungen nahe ehemaliger Siedlungen wie Agamands Mühlen vorgehen will."}},faq={{q="Wo finde ich Coleman Heller?",a="Coleman Heller wartet in der Taverne 'Zur Galgenfrist' im Osten von Brill in Tirisfal.",al={"coleman heller standort","wo ist coleman heller","heller in brill finden"}},{q="Wer schickt Euch zum Gespräch mit Coleman?",a="Todeswache Dillinger bewacht den Weg nach Brill. Er schickt Euch zu Coleman, nachdem Ihr Euer Kampfgeschick bewiesen habt.",al={"wer vergibt gespräch mit coleman","dillinger quest"}},{q="Welche Arbeit hat Coleman Heller?",a="Coleman Heller sucht einen fähigen Kämpfer, um Rache an Feinden der Verlassenen zu nehmen. Dabei geht es um Angelegenheiten rund um die alten Besitztümer der Agamands.",al={"was will coleman","coleman heller aufgabe"}},{q="Welche Voraussetzungen müssen erfüllt sein, um diese Aufgabe zu erhalten?",a="Todeswache Dillinger verweist Euch an Coleman, nachdem Ihr Ulag das Spaltbeil besiegt und den Verlassenen Eure Treue und Euer Kampfgeschick bewiesen habt.",al={"voraussetzungen für gespräch mit coleman","ulag voraussetzung"}},{q="Gewährt diese Mission unmittelbar nennenswerte Belohnungen?",a="Das Gespräch mit Heller in der Taverne führt Euch zu seinen persönlichen Anliegen. Das Treffen allein bringt weder nennenswerte Ausrüstung noch Geld.",al={"gespräch mit coleman belohnungen","lohnt sich die aufgabe"}},{q="Was ist die Taverne 'Zur Galgenfrist'?",a="Die Taverne 'Zur Galgenfrist' ist Brills zentrales Gasthaus, in dem sich die örtlichen Untoten versammeln und ausruhen. Sie ist auch ein zwangloser Treffpunkt für private Aufträge.",al={"brill taverne","taverne zur galgenfrist"}}},fx={["75bd5c35"]={q="Warum will Todeswache Dillinger, dass ich mit Coleman spreche?",a="Todeswache Dillinger erkennt an, dass Ihr Eure Stärke und Loyalität gegenüber der Dunklen Fürstin unter Beweis gestellt habt, indem Ihr die Bedrohungen in Brill bewältigt habt. Coleman Heller hat persönliche Beschwerden und benötigt einen fähigen Kämpfer, um an den Feinden der Verlassenen Rache zu üben. Indem er Euch an ihn verweist, stellt Dillinger sicher, dass fähige Champions ihre Mitbürger unterstützen und gleichzeitig die Sicherheit des Reiches insgesamt fördern.",al={"warum zu coleman schicken","dillinger motiv sprich mit coleman","warum coleman heller treffen"}},["5d6ae549"]={q="Warum schickt mich Todeswache Dillinger, anstatt Colemans Bitte selbst zu bearbeiten?",a="Dillinger ist eine Todeswache, die stationiert ist, um den Stadtperimeter von Brill gegen unmittelbare Bedrohungen wie die Geißel zu bewachen. Er kann seinen Posten nicht verlassen, um die persönlichen Vendetten oder privaten Anliegen der örtlichen Stadtbewohner zu lösen. Ihr habt Euer kämpferisches Können und Eure Unabhängigkeit unter Beweis gestellt, was Euch zum idealen Agenten macht, um Coleman Heller direkt zu unterstützen.",al={"warum ich coleman","warum nicht dillinger","warum dillinger euch schickt"}}},fp="18,175,21.290.0,18.327.0,34.97.0,33.109.0,45.140.0,57.133.0,53.136.0,32.143.0"}
P.entries["quest:1821"] = {n="Agamand-Erbstücke",s="Bei Agamands Mühlen schickt Coleman Heller Euch auf die Suche nach Erbstücken in der Familiengruft. Er gibt den Agamands die Schuld an seinem Tod und verlangt nach den Waffen ihrer Ahnen.",h="Bei Agamands Mühlen schickt Coleman Heller Euch auf die Suche nach Erbstücken in der Familiengruft.",kw={"gruft der familie agamand","agamand-erbstücke","agamands mühlen","coleman heller","erbstückwaffe","geißel","tirisfal"},ang={["class:Rogue"]="Als Schurke wisst Ihr, wie man an lauernden Ghulen vorbeischleicht und uralte Waffen aus bewachten Grabkammern entwendet.",["faction:Horde"]="Als Angehöriger der Horde helft Ihr, den Einfluss der Geißel im Norden von Tirisfal zu schwächen und das Land für Reisende sicherer zu machen.",["race:Undead"]="Als Untoter wisst Ihr, wie Groll aus dem sterblichen Leben unter den Verlassenen über den Tod hinaus fortbestehen kann."},sec={{t="Der bittere Groll eines Dieners",b="Bevor der Dritte Krieg Lordaeron verwüstete, diente Coleman Heller der wohlhabenden Familie Agamand bei ihren Mühlen in Tirisfal. Heller gibt seinen einstigen Herren die Schuld an seinem Tod. Nun unter den Verlassenen zum Untod erweckt, betrachtet er den Niedergang der Agamands mit boshafter Genugtuung. Die einst stolze Familie ist zu geistlosen Dienern geworden, die dem Lichkönig versklavt sind."},{t="Die Entweihung der Gruft",b="Heller schickt Euch in die Gruft der Familie Agamand unter den nördlichen Klippen der Mühlen. Rastlose Tote und verbliebene Angehörige der Geißel durchstreifen ihre steinernen Hallen. Er will, dass Ihr vier Relikte an Euch nehmt: das Schwert, die Axt, den Dolch und den Streitkolben der Familie Agamand. Ihr Verlust würde der Blutlinie ihre verbliebene Ehre nehmen."}},faq={{q="Wer war Coleman Heller zu Lebzeiten?",a="Vor dem Einfall der Geißel in Lordaeron diente Coleman Heller der wohlhabenden Familie Agamand bei Agamands Mühlen. Er starb während der Katastrophe und gibt seinen einstigen Herren die Schuld, wobei er diesen Groll bis in den Untod trägt.",al={"wer ist coleman heller","colemans vorgeschichte","hellers geschichte"}},{q="Warum will Coleman Heller die Erbstücke?",a="Heller sinnt auf Rache an seinen einstigen Herren. Er will das Schwert, die Axt, den Dolch und den Streitkolben ihrer Ahnen, um der gefallenen Familie ihre letzte Ehre und ihr Andenken zu nehmen.",al={"warum erbstücke stehlen","colemans beweggrund","warum waffen nehmen"}},{q="Was ist mit der Familie Agamand geschehen?",a="Die Familie Agamand kam um, als die Geißel über Tirisfal hinwegfegte. Sie wurden als geistlose untote Sklaven erweckt, an den Lichkönig gebunden, und durchstreifen ihre verfallenen Mühlen und ihre Gruft.",al={"schicksal der agamands","leben die agamands","was sind die agamands jetzt"}},{q="Wo liegt die Gruft der Familie Agamand?",a="Die Gruft der Familie Agamand liegt am nördlichen Rand von Agamands Mühlen, in felsigen Klippen über den verseuchten Gehöften im Norden von Tirisfal.",al={"lage der gruft","wo ist die gruft","agamand gruft karte"}},{q="Welche Waffen werden in der Gruft aufbewahrt?",a="Die Gruft birgt vier Waffen der Ahnen: das Schwert der Familie Agamand, die Axt der Familie Agamand, den Dolch der Familie Agamand und den Streitkolben der Familie Agamand.",al={"welche erbstücke","vier erbstücke","waffen der agamands"}},{q="Warum greifen die Verlassenen die Agamands an, wenn beide untot sind?",a="Die Verlassenen haben einen freien Willen und kämpfen um ihr eigenes Überleben. Die untoten Agamands bleiben geistlose Sklaven der Geißel und dienen dem Lichkönig, den die Verlassenen verachten.",al={"untote gegen untote","warum gegen agamands kämpfen","konflikt zwischen verlassenen und geißel"}}},fx={c3afbf3e={q="Was wird Coleman Heller mit den Agamand Heirlooms tun?",a="Für Coleman Heller repräsentieren die vier Waffen – das Schwert der Familie Agamand, die Axt, der Dolch und der Streitkolben – die letzten Überreste des Stolzes und der Abstammung seiner ehemaligen Meister. Indem er ihr Grab schändet und sie an sich nimmt, raubt er den verfluchten Ländereien von Agamand die letzten Überreste von Ehre und Erinnerung und erklärt, dass die Familie tatsächlich nicht mehr existiert.",al={"nutzen der agamand heirlooms","wofür sind die heirlooms","zweck der waffen der familie agamand"}},c1f9d064={q="Wer bewacht die Gruft der Familie Agamand?",a="Die Gruft und die umliegenden Mühlen sind von gedankenlosen Schergen der Geißel befallen, einschließlich der wiederbelebten Überreste der Familie Agamand selbst. An den Willen des Lichkönigs gebunden, statt freiwillige Verlassene zu sein, lauern diese Untoten in den dunklen Gräbern ihrer Vorfahren und bewachen die Familienreliquien erbittert gegen jeden Eindringling.",al={"feinde in der agamandgruft","wer beschützt die heirlooms","monster in der agamandgruft"}}},fp="17,153,25.355.0,21.292.0,33.208.0,45.158.0,36.182.0,42.149.0,39.145.0,63.162.0"}
P.entries["quest:1824"] = {n="Prüfung auf dem Feld der Riesen",s="In Camp Taurajo schickt Ruga Rachtotem Kriegeraspiranten nach Süden gegen einen ungewohnten Feind. Sie haben eine halbe Stunde, um auf dem Feld der Riesen Silithiden zu erschlagen und mit mehreren zuckenden Fühlern zurückzukehren.",h="In Camp Taurajo schickt Ruga Rachtotem Kriegeraspiranten nach Süden gegen einen ungewohnten Feind.",kw={"brachland","camp taurajo","feld der riesen","ruga rachtotem","silithiden","zuckender fühler","kriegerprüfung"},ang={["class:Warrior"]="Als Krieger stellt Ihr Euch diesem Übergangsritus etwa auf Eurer zwanzigsten Stufe. Er prüft, wie schnell Ihr ausschwärmende Feinde bezwingen und einer strengen Zeitbegrenzung standhalten könnt.",["faction:Horde"]="Als Mitglied der Horde stellt Ihr Euch den Silithiden, die sich im südlichen Brachland ausbreiten. Diese Prüfungen liefern auch Erkenntnisse über eine schleichende Bedrohung.",["race:Tauren"]="Als Verteidiger der Tauren helft Ihr, die Jagdgründe um Camp Taurajo zu schützen, indem Ihr Euch der Entweihung auf dem Feld der Riesen und dem dort eindringenden unnatürlichen Schwarm entgegenstellt."},sec={{t="Prüfung von Schnelligkeit und Stahl",b="Ruga Rachtotem prüft aufstrebende Krieger in Camp Taurajo im Kampf gegen einen ungewohnten Feind. Die Kriegerausbilder der Horde verlangen mehr als Kampfgeschick: Aspiranten müssen die Kreaturen erschlagen und innerhalb einer halben Stunde frische Fühler zurückbringen. Der Lauf durch das südliche Brachland stellt ihre Schnelligkeit und Entschlossenheit auf die Probe. Die Fühler müssen noch zucken, wenn sie Taurajo erreichen."},{t="Ungebetene Eindringlinge",b="Auf dem Feld der Riesen erheben sich Silithidenbauten unter gewaltigen versteinerten Rippenbögen. Diese seltsamen, kriechenden Insekten sind erst kürzlich im Brachland aufgetaucht und beunruhigen die Jäger und Schamanen der Tauren, die über die Savannen wachen. Ruga sagt, ihre Anwesenheit verheiße nichts Gutes für Kalimdor. Die Prüfung erprobt die Kampfinstinkte eines jungen Kriegers und liefert Erkenntnisse über eine wachsende Bedrohung für das Land."}},faq={{q="Warum gibt es eine Zeitbegrenzung für die Fühler?",a="Ruga Rachtotem verlangt, dass die Fühler noch zucken, wenn Krieger sie nach Camp Taurajo bringen. Damit bleiben ihnen nur dreißig Minuten für die Jagd und die Rückkehr. Ihre Frische beweist, dass der Aspirant einen Silithiden im direkten Kampf erschlagen und die Fühler keinem toten Exemplar entnommen hat.",al={"warum zeitbegrenzung","zeitlimit zuckende fühler","wie viel zeit"}},{q="Welche Kreaturen leben auf dem Feld der Riesen?",a="Auf dem Feld der Riesen leben bizarre, aggressive, grabende Silithiden. Sie haben unter uralten Fossilien gewaltige Hügel und Bauten angelegt, stören das örtliche ökologische Gleichgewicht und versetzen die Horde in Unruhe.",al={"was sind die insekten","feld der riesen gegner","was sind silithiden"}},{q="Wer ist Ruga Rachtotem?",a="Ruga Rachtotem ist ein Kriegerausbilder der Tauren in Camp Taurajo im südlichen Brachland. Er beaufsichtigt Prüfungen für Krieger der Horde, die einen höheren Rang anstreben, und erprobt ihr Geschick, ihre Widerstandskraft und ihre Schnelligkeit.",al={"ruga","wer vergibt die quest","ruga rachtotem hintergrund"}},{q="Wo liegt das Feld der Riesen?",a="Das Feld der Riesen liegt direkt südlich von Camp Taurajo, neben der Straße vor dem südlichen Pass nach Tausend Nadeln. Hoch aufragende Rippenbögen von Skeletten und Silithidenhügel prägen das Feld.",al={"wo ist das feld der riesen","feld der riesen lage","wo sind die insekten"}},{q="Wohin führt diese Ausbildungsreihe als Nächstes?",a="Sobald ein Krieger die zuckenden Fühler rechtzeitig zurückbringt, schickt Ruga ihn zu Thun'grim Brandblick, einem betagten Orcschmied, der auf einem Hügel östlich des Wegekreuzes lebt. Thun'grim fertigt Rüstungen für bewährte Krieger an.",al={"nächste quest","was kommt danach","kriegerquestreihe fortsetzung"}},{q="Warum machen sich die Tauren wegen der Insekten Sorgen?",a="Ruga sagt, Silithiden seien unnatürliche Neuankömmlinge im Brachland, deren Ankunft nichts Gutes für das Land verheiße. Er vermutet, dass ihre aggressiven Grabungen und ihre Ausbreitung auf eine größere Gefahr unter dem Sand hindeuten.",al={"warum sorgen sich die tauren","insekten als vorboten","silithidenbedrohung"}}},fx={["5312a899"]={q="Warum will Ruga Rachtotem, dass dies erledigt wird?",a="Ruga Rachtotem testet Eure kriegerische Entschlossenheit als Teil Eurer Kriegerausbildung, während er ein Auge auf eine aufkommende Bedrohung hat. Seltsame insektoide Kreaturen sind kürzlich im Feld der Riesen aufgetaucht und haben die örtlichen Tauren beunruhigt. Indem er Euch schickt, um sie schnell auszudünnen und frische Trophäen zurückzubringen, bevor sie aufhören zu zucken, testet Ruga Euer kämpferisches Können, Eure Geschwindigkeit und Eure Ausdauer im Feld.",al={"ruga rachtotem motiv","warum prüfung am feld der riesen","warum schickt ruga euch"}},["2d3c0cc0"]={q="Warum braucht Ruga Rachtotem Euch anstelle der Lagerwachen?",a="Diese Mission ist ein persönlicher Initiationsritus, der speziell für einen aufstrebenden Krieger unter Rugas Obhut entwickelt wurde. Die Lagerwachen sind damit beschäftigt, Camp Taurajo zu verteidigen und die nahegelegenen Grenzen zu beobachten, wohingegen das Überleben harter, einsamer Prüfungen gegen gefährliche Raubtiere die Art und Weise ist, wie Ihr beweist, dass Ihr bereit seid, den größeren Pfad des Kriegers zu beschreiten.",al={"warum ich prüfung der riesen","warum einen abenteurer zu ruga schicken"}}},fp="28,195,25.345.0,19.367.0,42.255.0,43.184.0,22.200.0,37.185.0,41.211.0,47.197.0"}
P.entries["quest:1825"] = {n="Gespräch mit Thun'grim",s="Nach der Prüfung am Feld der Riesen ruft Thun'grim Brandblick Krieger in sein Lager im Brachland. Der Orc-Schmied bietet jenen maßgefertigte Rüstungen an, die ihre Tapferkeit bewiesen haben, und schickt sie los, Materialien für Brutal Armor zu sammeln.",h="Nach der Prüfung am Feld der Riesen ruft Thun'grim Brandblick Krieger in sein Lager im Brachland.",kw={"brachland","brutal armor","das wegekreuz","firegaze","rachtotem","ruga","thun'grim","krieger"},ang={["class:Warrior"]="Als Krieger seid Ihr vom unerfahrenen Kämpfer zum anerkannten Champion aufgestiegen und habt Euch eine maßgeschmiedete Rüstung verdient.",["faction:Horde"]="Als Mitglied der Horde könnt Ihr darauf zählen, dass ihre Rüstungsschmiede ihre grimmigsten Verteidiger für deren Taten im Grenzland ausrüsten.",["profession:Blacksmithing"]="Als Schmied erkennt Ihr Thun'grim Firegazes traditionelle orkische Überzeugung, dass meisterhaft gefertigte Rüstungen durch kriegerische Prüfungen verdient werden müssen, statt mit Münzen gekauft zu werden."},sec={{t="Der Ruf des Schmieds",b="Die Nachricht von der Prüfung der Krieger erreicht Thun'grim Brandblick, nachdem sie Ruga Rachtotem ihre Ausdauer und Kampfkunst bewiesen haben. Sein Lager liegt auf einem Bergrücken östlich des Wegekreuzes. Thun'grim will ihnen eine außergewöhnliche Kettenrüstung schmieden."},{t="Der Anspruch eines Meisters",b="Thun'grim Brandblick behält seine Schmiede Kriegern vor, die seinen hohen Ansprüchen genügen. Er erwartet, dass der Stahl dem Geist seines Trägers entspricht. Wer sein Lager erreicht, hat als Krieger einfache Milizübungen hinter sich gelassen und kann die mühsame Suche nach seltenen Materialien in ganz Kalimdor aufnehmen."}},faq={{q="Wer ist Thun'grim Brandblick?",a="Thun'grim Brandblick ist ein angesehener Orc-Schmied mit einem Lager auf einem felsigen Bergrücken östlich des Wegekreuzes im Brachland. Er fertigt maßgeschneiderte Rüstungen für Krieger der Horde, die ihre Tapferkeit in gefährlichen Prüfungen beweisen.",al={"wer ist thungrim","thungrim hintergrundgeschichte","thungrim firegaze"}},{q="Warum schickt Ruga Rachtotem mich zu ihm?",a="Ruga Rachtotem schickt Euch zu Thun'grim, weil Ihr die Silithiden im Südlichen Brachland überlebt habt und einfachen Prüfungen entwachsen seid. Der Schmied bietet Euch als Anerkennung für Euren Dienst an der Horde eine eigens angefertigte Rüstung an.",al={"warum mit thungrim sprechen","ruga schickt mich"}},{q="Wo finde ich Thun'grims Lager?",a="Thun'grims Lager liegt auf den hohen Klippen östlich des Wegekreuzes im Brachland.",al={"wo ist thungrim","thungrim standort","thungrim firegaze finden"}},{q="Was geschieht nach dem Gespräch mit Thun'grim?",a="Mit dem Gespräch mit Thun'grim beginnt die Arbeit an Brutal Armor. Ihr reist durch ferne Länder, um Materialien für einen maßgefertigten Kettenharnisch zu sammeln, darunter rauchige Eisenbarren und Eisenbarren.",al={"nächste quest nach thungrim","was will thungrim"}},{q="Ist diese Quest für alle Klassen verfügbar?",a="Nein. Nur Krieger der Horde dürfen diese Rüstungsarbeit übernehmen.",al={"auch für andere klassen","nur für krieger"}},{q="Welche Prüfung war vor diesem Treffen erforderlich?",a="Bevor Ihr Thun'grim trefft, reist Ihr ins Südliche Brachland und besteht die Prüfung am Feld der Riesen. Das Sammeln zuckender Silithidenfühler beweist Eure Ausdauer im Kampf.",al={"vorausgesetzte quest","was geschah davor"}}},fx={["2df90612"]={q="Warum schickt Ruga Rachtotem Euch, anstatt selbst zu gehen?",a="Ruga Rachtotem überwacht die Ausbildung und Prüfung aufstrebender Krieger der Horde von seinem Posten in Camp Taurajo aus. Thun'grim Brandblick hat sich speziell an Euch gewandt, nachdem er von Eurer Tapferkeit und Euren Prüfungen im Brachland gehört hat. Ruga gibt die Aufforderung lediglich weiter, damit Ihr Rüstung beanspruchen könnt, die nach Eurem persönlichen Maß geschmiedet wurde.",al={"warum schickt ruga mich","warum ich ruga rachtotem","warum braucht ruga mich"}}},fp="20,226,21.244.0,19.287.0,26.204.0,39.207.0,34.77.0,43.186.0,39.54.0,44.173.0"}
P.entries["quest:183"] = {n="Der Eberjäger",s="Im Coldridgetal bittet Talin Keeneye junge Rekruten, die Felseneber zu dezimieren, die die Pfade bedrohen. Dann können erfahrene Jäger ungestört auf Fährtensuche gehen.",h="Im Coldridgetal bittet Talin Keeneye junge Rekruten, die Felseneber zu dezimieren, die die Pfade bedrohen.",kw={"ambossar","eberjäger","das coldridgetal","felseneber","dun morogh","jagd","talin keeneye"},ang={["class:Hunter"]="Als Jäger könnt Ihr Talin Keeneyes schlichten Ansatz bei der Fährtensuche beherzigen: Zielt genau, achtet die Bestien und lichtet das Unterholz, wenn das Wild feindselig wird.",["race:Dwarf"]="Das Leben in den Bergen bedeutet, das Land mit wilden Tieren zu teilen. Als junger Zwerg ist das Dezimieren der aggressiven Felseneber rund um Ambossar eine Bewährungsprobe für Euch jenseits der Schmiede.",["race:Gnome"]="Als gnomischer Flüchtling, frisch aus Gnomeregan eingetroffen, ist die Begegnung mit Dun Moroghs wilden Ebern für Euch ein harter Einstieg ins Leben im rauen Zwergenland."},sec={{t="Ein überfülltes Tal",b="Das Coldridgetal bietet jungen Gebirgsjägern und Gelehrten aus Eisenschmiede einen ruhigen, geschützten Ort zum Üben. Während des harten Winters haben sich kleine Felseneber im ganzen Tal vermehrt. Ihre Angriffe bedrohen nun alle auf den verschneiten Pfaden."},{t="Fürsorge im Schnee",b="Die Jagd liefert Zwergen Fleisch, Häute und Übung im Gelände. Wenn sich das Wild stark vermehrt und jeden sofort angreift, stellt eine Bestandsminderung das Gleichgewicht wieder her. Indem junge Abenteurer die Felseneber an den Hängen des Tals dezimieren, beweisen sie ihre Kampfbereitschaft. Die örtlichen Jäger gewinnen Raum, um auf Fährtensuche zu gehen, ohne überwältigt zu werden."}},faq={{q="Wer ist Talin Keeneye?",a="Talin Keeneye ist ein zwergischer Jäger, der im Coldridgetal nahe Ambossar stationiert ist. Er spürt Wild im Schnee auf und lehrt unerfahrene Abenteurer, mit feindseligen Bestien umzugehen.",al={"talin keeneye","wer vergibt den auftrag der eberjäger","eberjäger npc"}},{q="Warum sind die Felseneber ein solches Problem?",a="Kleine Felseneber haben sich im Coldridgetal ungewöhnlich stark vermehrt und greifen ohne Anlass an. Ihre große Zahl macht Reisen und Jagd für die Einheimischen gefährlich.",al={"warum eber töten","eberproblem coldridgetal","warum sind eber gefährlich"}},{q="Wo sind die Felseneber zu finden?",a="Kleine Felseneber durchstreifen die offenen, verschneiten Ebenen und lichten Wälder rund um Ambossar im gesamten Coldridgetal.",al={"wo sind die eber","felseneber fundort","kleiner felseneber karte"}},{q="Hängt dieser Auftrag mit einer größeren Bedrohung im Tal zusammen?",a="Nein. Troggs bedrängen die zwergischen Außenposten, doch die Felseneber sind ein örtliches Problem mit Wildtieren. Ihre Zahl zu verringern macht die Fußpfade sicherer und lässt Talin ungestört jagen.",al={"gibt es einen folgeauftrag","eberjäger auftragsreihe","geschichte hinter den ebern"}},{q="Was macht Felseneber für das Leben in Dun Morogh geeignet?",a="Felseneber sind zähe Schweine mit dicker Haut, die den eisigen Temperaturen Dun Moroghs trotzen. Ihre Angriffslust und scharfen Hauer helfen ihnen, im gefrorenen Boden nach Nahrung zu suchen und sich gegen Raubtiere der Berge zu verteidigen.",al={"felseneber hintergrundgeschichte","zwerge eber","dun morogh tierwelt"}},{q="Warum tötet Talin Keeneye die Eber nicht selbst?",a="Talin sagt, die aggressiven Eber hätten seine Jagdausflüge unangenehm gefährlich gemacht. Er bittet eifrige Neuankömmlinge, die durch Ambossar kommen, ihre Zahl zu verringern, damit er wieder wie gewohnt auf Fährtensuche gehen kann.",al={"warum braucht talin hilfe","talin faul","warum kann talin sie nicht jagen"}}},fx={aa61ef91={q="Warum will Talin Keeneye, dass die kleinen Krag Eber ausgedünnt werden?",a="Talin Keeneye betrachtet die Eberjagd als einen schönen Zeitvertreib, aber die schiere Anzahl der kleinen Krag Eber, die das Coldridgetal befallen, hat seinen Sport ruiniert. Ihre aggressive Natur und ihre explosionsartige Anzahl haben seine tägliche Routine eher gefährlich als entspannt gemacht. Indem Ihr ein Dutzend der Biester ausdünnt, stellt Ihr etwas Sicherheit im Tal wieder her, sodass er seine Jagd genießen kann, ohne ständig umschwärmt zu werden.",al={"warum eber töten","talin keeneye motiv","warum muss talin eber tot sehen"}},cf0c4f7e={q="Was sind kleine Krag Eber und warum sind sie im Coldridgetal?",a="Kleine Krag Eber sind die robusten, einheimischen Schweine von Dun Morogh, die von Natur aus mit dickem Fell und hitzigem Temperament ausgestattet sind, um im frostigen Bergland zu überleben. Das Coldridgetal bietet reichlich Nahrung entlang der verschneiten Ausläufer, aber in letzter Zeit ist ihre Population so dramatisch angestiegen, dass sie überall umherstreifen und jeden aggressiv angreifen, der sich nähert.",al={"was sind krag eber","warum sind hier eber","lore der kleinen krag eber"}}},fp="15,143,16.234.0,17.295.0,21.165.0,38.164.0,34.116.0,57.168.0,43.204.0,49.186.0"}
P.entries["quest:1838"] = {n="Brutale Rüstung",s="Im nördlichen Brachland stellt sich ein Krieger Thun'grim Firegazes Prüfung. Der fast blinde Schmied schickt erfahrene Krieger der Horde durch ferne Länder, um seltene Zutaten und Schmelzmittel zu beschaffen. Bringt ihm, was seine Schriftrolle verlangt, und er kann beginnen, eine vollständige Garnitur brutaler Kriegsausrüstung zu schmieden.",h="Im nördlichen Brachland stellt sich ein Krieger Thun'grim Firegazes Prüfung.",kw={"brachland","brutale rüstung","brutal hauberk","phlogiston","pulverisierter azurit","rauchiger eisenblock","thun'grim firegaze","kriegerquest"},ang={["class:Warrior"]="Als Krieger der Horde beweist Ihr Eure Tapferkeit und Ausdauer auf mehreren Kontinenten, um eine maßgefertigte Kampfrüstung zu verdienen.",["faction:Horde"]="Als Mitglied der Horde seht Ihr, wie Schmiede der Orcs, Tauren, Trolle und Verlassenen ihre unterschiedlichen Handwerkstraditionen in einem Rüstungsset vereinen.",["profession:Blacksmithing"]="Als Schmied könnt Ihr sehen, wie Thun'grims Schriftrolle rauchiges Eisen, pulverisierten Azurit und Phlogiston verbindet, um die gewöhnliche Eisenverhüttung zu verfeinern."},sec={{t="Der Ruf eines Meisters",b="Im nördlichen Brachland lauscht Thun'grim Brandblick auf Nachrichten vom Krieg. Das Augenlicht des erfahrenen Orcschmieds schwindet, doch keine Hand an der Schmiede ist geschickter. Gerüchte berichten ihm von einem Krieger, dessen Stärke und Tapferkeit die gewöhnlicher Soldaten übertreffen. So macht sich Thun'grim daran, ein Kettengewand für die härtesten Schlachten in Kalimdor und den Östlichen Königreichen zu schmieden."},{t="Die Suche über Kontinente",b="Thun'grims Rüstung erfordert mehr als gewöhnliches Erz. Vom schwindenden Augenlicht geleitet, verfasst er im Feuerschein eine genaue Schriftrolle für das zentrale Bruststück. Sie verlangt veredeltes Eisen, rauchige Eisenbarren von grabenden Kobolden, von Bergleuten jenseits des Meeres bearbeiteten pulverisierten Azurit und eine unbeständige Phiole mit Phlogiston. Nur ein Krieger, der für Prüfungen in fernen Ländern bereit ist, kann alle benötigten Materialien sammeln."},{t="Der erste Hammerschlag",b="Thun'grims seltene Materialien bilden den Anfang eines weit größeren Unterfangens. Sobald sie eintreffen, heizt er seinen Schmelzofen an und schmiedet das Brutal Hauberk. Doch der alte Schmied erkennt, dass er allein eine so ehrgeizige Rüstungsgarnitur nicht vollenden kann. Das vollständige Set verlangt nach erfahrenen Handwerkern der anderen Völker der Horde: einem Helmformer der Tauren, einem Handschuhmacher der Trolle und einem Beinschienenschmied der Untoten, die über die Kontinente verstreut zu finden sind."}},faq={{q="Wer ist Thun'grim Brandblick?",a="Thun'grim Brandblick ist ein erfahrener Orcschmied, der auf einem Hügel über dem nördlichen Brachland lebt. Sein Augenlicht schwindet, doch sein Gespür am Amboss bleibt scharf. Er fertigt mächtige Kettengewänder nach Maß für Krieger der Horde, die für ihre Tapferkeit bekannt sind.",al={"wer ist thungrim","thun'grim firegaze geschichte","thungrim hintergrundgeschichte"}},{q="Was ist die Brutale Rüstung?",a="Die Brutale Rüstung ist ein für den Kampf geschmiedetes Kettengewand für erfahrene Krieger der Horde. Schmiede der Horde vereinen ihr Können für dieses Set, dessen Teile gefährliche Reisen erfordern, um seltene alchemistische Reagenzien, gereinigte Erze und uralte Techniken aufzuspüren.",al={"was ist die brutale rüstung","brutale rüstung set geschichte","krieger rüstungsquestreihe"}},{q="Warum braucht Thun'grim so ungewöhnliche Zutaten?",a="Thun'grim braucht ungewöhnliche Zutaten, weil gewöhnliches Eisen zu spröde ist, um den schweren Schlägen standzuhalten, denen ein Champion an vorderster Front ausgesetzt ist. Er verwendet pulverisierten Azurit, rauchige Eisenbarren und unbeständiges Phlogiston als Fluss- und Härtungsmittel, um dem Metall mehr Widerstandskraft und Festigkeit zu verleihen.",al={"warum pulverisierter azurit","warum phlogiston","wofür sind die reagenzien"}},{q="Schmiedet Thun'grim das gesamte Set selbst?",a="Nein. Thun'grim schmiedet das zentrale Kettenhemd, während andere Schmiede der Horde den passenden Helm, die Handschuhe und die Beinschützer anfertigen. Zu ihnen gehören Orm Stonehoof, Ula'elek und Velora Nachtens.",al={"fertigt thungrim alles selbst","wer fertigt die teile der brutalen rüstung"}},{q="Wohin führt diese Questreihe als Nächstes?",a="Die Prüfung führt zum Schmieden des Brutal Hauberk. Dann öffnet sich der Weg zu Schmieden in Donnerfels, Sen'jin und Unterstadt, um die übrigen Teile des brutalen Kettengewands zu erhalten.",al={"was kommt nach der brutalen rüstung","brutale rüstung folgequest"}},{q="Warum muss ein Krieger für diese Materialien so weit reisen?",a="Die Reise prüft die kämpferische Ausdauer und den Einfallsreichtum eines Kriegers. Um sich einer meisterlich geschmiedeten Rüstung würdig zu erweisen, muss ein Krieger feindliches Gebiet durchqueren, gefährliche Minen betreten und schwer zugängliche Bestandteile sammeln.",al={"warum in die östlichen königreiche reisen","warum so viele materialien"}}},fx={["31952f55"]={q="Warum will Thun'grim Brandblick diese Rüstung herstellen?",a="Thun'grim hat von Eurem wachsenden Ruhm in der gesamten Horde gehört und möchte eine Rüstung anfertigen, die Eurer Stärke würdig ist. Für den alternden, fast blinden Schmied ist es eine Ehre und ein Beweis für sein eigenes Handwerk, legendäre Rüstungen zu schmieden, um einen aufstrebenden Krieger auf seiner Reise zu begleiten.",al={"warum hilft mir thungrim","thun'grim firegaze motiv","warum brutal armor herstellen"}},["8131a754"]={q="Warum muss Thun'grim Euch die Materialien sammeln lassen?",a="Thun'grim ist ein betagter Orc, dessen Sehkraft fast erloschen ist; er hat sich mehrere Nächte lang abgemüht, nur um Eure Anweisungen zu schreiben. Das Sammeln gefährlicher Reagenzien aus entfernten Minen und von wilden Tieren übersteigt seine physischen Fähigkeiten bei weitem und erfordert einen bewährten Krieger, um die Reise zu unternehmen.",al={"warum muss ich die materialien holen","warum ich brutal armor","warum braucht thungrim meine hilfe"}}},fp="12,277,18.352.0,26.396.0,30.377.1,26.247.0,21.225.0,49.278.0,44.174.1,38.183.1,61.213.0"}
P.entries["quest:1839"] = {n="Ula'elek und die brutalen Stulpen",s="In Sen'jin wartet Ula'elek darauf, die Brutal Gauntlets für Euch zu schmieden. Thun'grim Brandblick schickt Euch aus dem Brachland an Durotars Südküste.",h="In Sen'jin wartet Ula'elek darauf, die Brutal Gauntlets für Euch zu schmieden.",kw={"brutal gauntlets","dunkelspeer","durotar","sen'jin","brachland","thun'grim firegaze","ula'elek","krieger"},ang={["class:Warrior"]="Als Krieger der Horde markiert das Zusammentragen der Brutal Armor Euren Weg zum kampferprobten Champion an vorderster Front.",["faction:Horde"]="Als Mitglied der Horde seht Ihr, wie Orc-Schmiede im Brachland und Troll-Schmiede in Durotar zusammenarbeiten. Ihr Handwerk hält Thralls junges Bündnis zusammen.",["race:Troll"]="Als Troll seht Ihr, wie Ula'eleks Schmiedekunst der Dunkelspeer und seine Verbundenheit mit den Geistern die Kriegsanstrengungen der Horde unterstützen."},sec={{t="Eine Reise zur Küste",b="Thun'grim Brandblick schickt Euch nach Osten, nachdem Ihr im Brachland Euren Mut bewiesen und begonnen habt, das Set der Brutal Armor zusammenzutragen. Der erfahrene Orc-Schmied vertraut auf geschickte Handwerker in den Ländern der Horde, um dessen Teile zu schmieden. Für die schweren Kettenstulpen schickt er Euch an Durotars felsige Südküste."},{t="Die Augen der Loa",b="In Sen'jin arbeitet der Troll-Rüstungsschmied Ula'elek unter seinen Verwandten von den Dunkelspeer. Thun'grim hat ihm von Euren Taten berichtet, und Ula'elek sagt, die Geister hätten Eure Triumphe im Kampf beobachtet. Für einen Krieger, der einen Platz unter der Elite der Horde sucht, gehen feine Handwerkskunst und spirituelle Anerkennung Hand in Hand."}},faq={{q="Wer vergibt die Quest Ula'elek und die brutalen Stulpen?",a="Thun'grim Brandblick, ein Orc-Rüstungsschmied auf den Bergen im Brachland, schickt Euch los, um die Stulpen zu beschaffen.",al={"questgeber","wer startet ula'elek und die brutalen stulpen","thun'grim firegaze quest"}},{q="Wo kann ich Ula'elek finden?",a="Ula'elek arbeitet in Sen'jin an Durotars Südküste.",al={"ula'elek standort","wo ist ula'elek","ulaelek senjin"}},{q="Was ist das Set der Brutal Armor?",a="Brutal Armor ist ein maßgefertigtes Kettenrüstungsset für erfahrene Krieger der Horde um ihre dreißigste Saison. Verbündete Schmiede in ganz Kalimdor fertigen seine Teile.",al={"brutal armor","was sind brutal gauntlets","krieger klassenrüstung dreißig"}},{q="Was geschieht nach der Ankunft bei Ula'elek?",a="Nachdem Ula'elek Euch begrüßt und Eure Taten im Kampf gewürdigt hat, bittet er Euch, exotische Materialien für die Brutal Gauntlets zu sammeln, beginnend mit Satyr Hooves.",al={"nächste quest","nach dem gespräch mit ula'elek","satyr hooves quest"}},{q="Warum schickt Thun'grim Euch zu einem Troll-Rüstungsschmied?",a="Thun'grim verteilt das Schmieden des Sets der Brutal Armor auf die besten spezialisierten Schmiede der Horde. Der Dunkelspeer-Handwerker Ula'elek fertigt die Stulpen.",al={"warum ula'elek","warum nach sen'jin gehen","trollschmied brutal armor"}},{q="Gibt es für Spieler der Allianz ein Gegenstück zu dieser Quest?",a="Krieger der Allianz stellen sich einer ähnlichen kämpferischen Prüfung, um klassenspezifische Rüstung zu fertigen. Die Questreihe der Brutal Armor und Ula'eleks Arbeit gehören zur Horde.",al={"allianz brutal gauntlets","allianz gegenstück"}}},fx={a664db53={q="Warum muss Thun'grim Brandblick Euch nach Sen'jin schicken?",a="Thun'grim Brandblick leitet Euer Wachstum als aufstrebender Krieger der Horde. Während er Eure Ausbildung überwacht, erfordert die alte Kunst des Schmiedens von Brutal Armor die speziellen Talente anderer Handwerker in den Ländern der Horde. Ula'elek in Sen'jin ist ein geschickter Rüstungsschmied der Dunkelspeer, der auf die Geister eingestimmt ist und dafür geeignet ist, die Handschuhe zu schmieden. Thun'grim schickt Euch persönlich, nicht nur, um das Stück in Auftrag zu geben, sondern um Eure Hingabe zu beweisen und das Vertrauen des Rüstungsschmieds direkt zu verdienen.",al={"warum ich ula'elek","warum kann thungrim keine handschuhe herstellen","warum krieger nach durotar schicken"}}},fp="33,148,22.282.0,19.294.0,54.98.0,26.62.0,29.140.0,37.157.0,50.147.0,53.141.0"}
P.entries["quest:184"] = {n="Brauenwirbels Urkunde",s="Bauer Brauenwirbel und Verna wurden von ihrem Hof vertrieben, während Banditen der Defias ihre Landurkunde durch den Wald von Elwynn tragen. Bringt sie Bauer Brauenwirbel nahe der Grenze nach Westfall zurück, damit das Paar seinen Anspruch auf den geraubten Hof behält.",h="Bauer Brauenwirbel und Verna wurden von ihrem Hof vertrieben, während Banditen der Defias ihre Landurkunde...",kw={"defias","elwynn","brauenwirbel","theodore brauenwirbel","verna brauenwirbel","westfall","westfall urkunde"},ang={["class:Paladin"]="Als Paladin erfüllt Ihr mit der Rückgabe einer gestohlenen Urkunde an Flüchtlinge Eure heiligen Gelübde, die Wehrlosen zu verteidigen und Gerechtigkeit in gesetzlose Grenzgebiete zu bringen.",["faction:Alliance"]="Die Not der Brauenwirbels zeigt, dass die Krone von Sturmwind ihre steuerzahlenden Bürger jenseits der befestigten Mauern der Hauptstadt nicht schützen konnte."},sec={{t="Eine Spur auf gestohlenem Papier",b="Eine von Theodore und Verna Brauenwirbel unterzeichnete Urkunde taucht bei Banditen der Defias in Elwynn auf. Eine krakelige Notiz auf der Rückseite besagt, dass die Banditen den betagten Bauern von seinem Grund vertrieben haben. Sie brachten die Urkunde über den Fluss nach Elwynn, um sie zu kopieren und Ansprüche auf weitere geraubte Ländereien zu fälschen. Laut der Notiz sind die Brauenwirbels gleich hinter der Grenze an der Straße gestrandet, nachdem ihr Wagen kaputtging."},{t="Die Not der Bauern Westfalls",b="Die Defias haben Dutzende Familien in Westfall von ihrem angestammten Land vertrieben. Mit Gewalt und falschen Besitzansprüchen reißen sie weitere Höfe für die Bruderschaft an sich, während Theodore und Verna ihren eigenen Hof zur Sicherheit verlassen. Ihre rechtmäßige Urkunde wahrt ihren Anspruch, falls die Ordnung jemals in die Provinz zurückkehrt."}},faq={{q="Wo finde ich diese Urkunde?",a="Banditen der Bruderschaft der Defias tragen die Urkunde im Süden und Westen des Waldes von Elwynn bei sich, auch nahe Jerods Anlegestelle und in örtlichen Lagern.",al={"urkunde als beute","wie bekommt man brauenwirbels urkunde","wo gibt es die urkunde als beute"}},{q="Wo ist Bauer Brauenwirbel?",a="Bauer Brauenwirbel und seine Frau Verna sind neben ihrem kaputten Wagen an der Hauptstraße gleich hinter der Grenze nach Westfall gestrandet, kurz nachdem Ihr die Brücke vom Wald von Elwynn nach Westen überquert habt.",al={"brauenwirbels standort","wo brauenwirbels urkunde abgeben","wo ist der bauer"}},{q="Warum wollten die Defias die Urkunde überhaupt haben?",a="Eine Notiz auf der Rückseite besagt, dass die Banditen Brauenwirbels rechtmäßige Urkunde kopieren und Ansprüche auf andere Grundstücke fälschen wollen. Gefälschte Dokumente würden ihre Kontrolle über geraubte Höfe festigen.",al={"warum stahlen banditen die urkunde","warum wollen die defias urkunden"}},{q="Kehren die Brauenwirbels auf ihren Hof zurück?",a="Das Paar flieht wegen der Gesetzlosigkeit und der Banditenangriffe aus der Region. Mit ihrer Urkunde können sie ihr Land rechtmäßig zurückfordern, falls Westfall jemals befriedet wird.",al={"kehren die brauenwirbels heim","was geschieht mit brauenwirbels hof"}},{q="Warum schützt Sturmwind diese Höfe nicht?",a="Sturmwinds Schutz hat durch das plötzliche Verschwinden von König Varian Wrynn und innenpolitische Spannungen nachgelassen. Da die Mittel der Krone auf die Hauptstadt konzentriert sind, müssen sich Randgebiete wie Westfall allein der erstarkenden Bruderschaft der Defias stellen.",al={"warum keine wachen in westfall","warum ignoriert sturmwind westfall"}},{q="Welche Verbindung besteht in dieser Quest zwischen Elwynn und Westfall?",a="Das Netzwerk der Defias reicht vom Wald von Elwynn über den Fluss bis nach Westfall. Ihre dortige Präsenz zeigt, wie weit ihr Einfluss in die Kerngebiete des Königreichs reicht.",al={"warum war die urkunde in elwynn","verbindung zwischen den gebieten"}}},fx={["9b306b68"]={q="Warum sollte ich Brauenwirbels Urkunde zurückgeben?",a="Die Urkunde selbst ist nur ein lebloses Stück Papier, aber die Nachricht, die auf ihrer Rückseite gekritzelt ist, enthüllt, dass Defias-Raufbolde Theodore und Verna Brauenwirbel dazu eingeschüchtert haben, ihr Land aufzugeben. Die Diebe wollten sie als Vorlage verwenden, um Ansprüche auf andere Grundstücke zu fälschen. Sie an die flüchtenden Brauenwirbels zurückzubringen, gibt einer ehrlichen Bauernfamilie den einzigen Eigentumsnachweis, den sie noch haben, und bietet ihnen Hoffnung, ihr gestohlenes Erbe eines Tages zurückzufordern, falls jemals wieder Frieden in Westfall einkehren sollte.",al={"warum die urkunde zurückgeben","motiv für westfall-urkunde","zweck der brauenwirbel-urkunde"}}},fp="15,233,22.376.0,32.287.0,26.131.0,25.172.0,52.174.0,42.161.0,43.239.0,65.165.0"}
P.entries["quest:1840"] = {n="Orm Steinhuf und der brutale Helm",s="In Donnerfels kann Orm Stonehoof den Brutal Helm schmieden. Thun'grim Brandblick schickt Krieger dafür zu ihm.",h="In Donnerfels kann Orm Stonehoof den Brutal Helm schmieden.",kw={"rüstungsquest","brutal helm","orm stonehoof","thun'grim firegaze","donnerfels","krieger"},ang={["class:Warrior"]="Als Krieger werdet Ihr zu einem der besten Meisterschmiede der Horde geschickt, um einen schweren Kopfschutz zu erhalten.",["faction:Horde"]="Als Mitglied der Horde seht Ihr, wie orkische Waffenmeister im Brachland mit Handwerkern der Tauren hoch oben in Donnerfels zusammenarbeiten."},sec={{t="Eine Empfehlung in Eisen",b="Krieger, die sich bewähren und im Brachland Teile der Brutal Armor sammeln, werden nach Donnerfels geschickt. Thun'grim Brandblick ist ein geschickter Rüstungsschmied, doch die Arbeit übersteigt inzwischen sein handwerkliches Können. Also verweist er die Krieger an Orm Stonehoof, dessen Können in ganz Kalimdor bekannt ist. Orm kann aus seltenen Trophäen wilder Bestien robuste Helme formen."},{t="Der Handwerker am Teich",b="Orm Stonehoof lebt und arbeitet auf den hohen Klippen von Mulgore, nahe dem Teich unterhalb des großen zentralen Totems von Donnerfels. Wenn ein Krieger mit einer Empfehlung von Thun'grim Brandblick eintrifft, legt Orm seine übliche Arbeit beiseite. Er bespricht mit ihm die schwer zu beschaffenden Bestandteile für einen Helm, der für die Frontlinien der Horde geeignet ist."}},faq={{q="Wer ist Orm Stonehoof?",a="Orm Stonehoof ist ein geschickter Rüstungsschmied der Tauren, der in Donnerfels lebt. Thun'grim Brandblick schickt Krieger zu ihm, weil er sich auf das Schmieden von Schlachthelmen versteht.",al={"orm stonehoof","wer ist orm"}},{q="Wo ist Orm Stonehoof zu finden?",a="Orm Stonehoof arbeitet nahe dem Teich unterhalb des großen zentralen Totems von Donnerfels.",al={"wo ist orm","orm stonehoof standort","orm finden"}},{q="Warum schickt Thun'grim Brandblick Euch nach Donnerfels?",a="Thun'grim Brandblick kann den Brustpanzer und andere Teile des Brutal-Sets herstellen, doch Orm Stonehoof besitzt das Können, den Brutal Helm zu schmieden.",al={"warum donnerfels","warum orm aufsuchen"}},{q="Was ist der Brutal Helm?",a="Der Brutal Helm ist ein Kopfschutz für Krieger der Horde, die den Rang eines Veteranen erreicht haben. Für seine Herstellung braucht es gefährliche Materialien von Bestien aus ganz Kalimdor.",al={"brutal helm quest","was ist brutal helm"}},{q="Worum bittet Orm als Nächstes?",a="Orm Stonehoof bittet Euch, Bestientrophäen für den Helm zu sammeln, angefangen mit einem Chimaeric Horn von einer wilden Chimäre.",al={"nächste quest","nach orm stonehoof","chimaeric horn quest"}},{q="Kann jede Klasse diese Quest annehmen?",a="Nein. Diese Questreihe ist für Krieger, die in ihrer Kampfausbildung fortgeschritten sind und Thun'grims erste Rüstungsarbeiten abgeschlossen haben.",al={"nur für krieger","wer kann diese quest machen"}}},fx={["528c5ae8"]={q="Warum möchte Thun'grim Brandblick, dass Ihr Orm Stonehoof aufsucht?",a="Thun'grim Brandblick hat Euer Training als Krieger angeleitet, doch die Anfertigung eines Brutal Helm erfordert einen Meisterhandwerker, dessen Talent gewöhnliche Schmiedekunst übertrifft. Da Thun'grim Orm Stonehoofs unübertroffenes Geschick bei der Verarbeitung von Metall und Knochen erkennt, schickt er Euch zu dem Tauren-Handwerker nach Donnerfels, damit Ihr Euch ein Rüstungsteil verdienen könnt, das Eurer wachsenden Stärke und Eurem Dienst für die Horde würdig ist.",al={"motiv von thungrim firegaze","warum zu orm stonehoof","grund für thungrims brutal helm"}}},fp="33,113,24.351.0,23.298.0,21.152.0,33.78.0,54.136.0,24.149.0,27.115.1,30.115.0"}
P.entries["quest:1841"] = {n="Velora Nachtens und die brutalen Beinschützer",s="Thun'grim Brandblick schickt Krieger der Horde über das große Meer, um Velora Nachtens und die Brutalen Beinschützer zu suchen. In Unterstadt schmiedet die Schmiedin der Verlassenen die Rüstung mit der Handwerkskunst, die sie aus ihrem sterblichen Leben bewahrt hat. Ihre Arbeit hilft, eine widerstandsfähige Rüstung für die Krieger der Horde zu vervollständigen.",h="Thun'grim Brandblick schickt Krieger der Horde über das große Meer, um Velora Nachtens und die Brutalen...",kw={"brutal armor","brutale beinschützer","lordaeron","thun'grim firegaze","handwerksviertel","unterstadt","velora nachtens","kriegerquest"},ang={["class:Warrior"]="Als Krieger erreicht Ihr etwa auf Stufe dreißig einen Meilenstein in den Rüstungsprüfungen der Horde und reist für besondere Klassenrüstung über Kalimdor hinaus.",["faction:Horde"]="Als Mitglied der Horde beteiligt Ihr Euch an einer Arbeit, die Orks, Trolle und Tauren aus Kalimdor mit Handwerkern der Verlassenen in den Östlichen Königreichen zusammenführt.",["race:Undead"]="Als Verlassene könnt Ihr sehen, wie Velora Nachtens die verfeinerten Fertigkeiten und das künstlerische Erbe des gefallenen Lordaeron fortführt."},sec={{t="Eine Reise über das Meer",b="Thun'grim Brandblick schickt Euch ostwärts über das große Meer, um einen Schmied für die Brutalen Beinschützer zu finden. Ihr habt dem erfahrenen Schmied während seiner Wacht im Brachland Euren Mut bewiesen, und nun weist er Euch den Weg zur sagenumwobenen Brutal Armor. Thun'grim kann die gesamte Rüstung nicht allein herstellen, deshalb ist er auf geschickte Verbündete in der ganzen Horde angewiesen. Für die Beinschienen braucht es eine Handwerkerin im unterirdischen Reich der Verlassenen, deren Werk schon vor dem Fall der Menschheit im Norden verehrt wurde."},{t="Die Kunst von Velora Nachtens",b="Velora Nachtens arbeitet im Handwerksviertel von Unterstadt, wo ihr altes Handwerk noch immer der Horde dient. Bevor die Geißelung des Nordens ihr sterbliches Leben beendete, gehörte sie zu den führenden Rüstungsschmiedinnen des Königreichs Lordaeron. Ihre Heimat wurde verderbt, und sie wurde zu einer der Verlassenen. Der Tod nahm ihr nicht die Meisterschaft im Umgang mit Metall. Nun setzt sie ihre menschliche Handwerkskunst für die Krieger der Horde ein und begegnet ihrem untoten Dasein mit trockenem, makabrem Witz."}},faq={{q="Wer ist Velora Nachtens?",a="Velora Nachtens wurde einst als eine der besten Rüstungsschmiedinnen im Königreich Lordaeron gefeiert. Nach dem Dritten Krieg erhob sie sich als eine der Verlassenen und ließ sich im Handwerksviertel von Unterstadt nieder, wo sie noch immer ihr Handwerk für die Horde ausübt.",al={"velora nachtens hintergrundgeschichte","wer ist velora","verlassene schmiedin velora"}},{q="Warum schickt Thun'grim mich nach Unterstadt?",a="Thun'grim Brandblick schickt Euch nach Unterstadt, weil die vollständige Brutal Armor geschickte Handwerker aus der ganzen Horde erfordert. Er kennt Veloras Ruf als Rüstungsschmiedin und schickt Euch nach Lordaeron, um die Beinschützer bei ihr in Auftrag zu geben.",al={"warum nach unterstadt","thun'grim unterstadt quest","brachland nach unterstadt krieger"}},{q="Wo finde ich Velora Nachtens in Unterstadt?",a="Velora Nachtens arbeitet im Handwerksviertel von Unterstadt, an den Schmieden zwischen Schmieden und anderen Handwerksmeistern, die Fürstin Sylvanas Windläufer dienen.",al={"velora nachtens standort","wo ist velora nachtens","velora nachtens finden"}},{q="Was folgt nach dem Gespräch mit Velora Nachtens?",a="Velora bittet Euch, im Sumpfland Schienbeinknochen von Dragonmaw-Orks für Eure Brutalen Beinschützer zu sammeln.",al={"nächste quest nach velora","dragonmaw shinbones quest","was will velora"}},{q="Hat Velora Dialoge über ihr untotes Dasein?",a="Ja. Velora scherzt trocken darüber, ob sie die Rüstung für Euch anfertigt oder umgekehrt. Sie sagt, sie habe ihren Sinn für Humor etwa zu der Zeit verloren, als sie ihren Geruchssinn verlor und aufhörte zu atmen.",al={"velora witze","untote schmiedin dialog","velora humor"}},{q="Ist Brutal Armor nur für Krieger?",a="Ja. Die Prüfungen für die Brutal Armor, darunter die Suche nach Velora Nachtens für die Beinschützer, sind für Krieger der Horde bestimmt, die in die Reihen der Erfahrenen aufsteigen.",al={"können andere klassen brutal armor erhalten","quest nur für krieger brutal armor"}}},fx={["7eb107f7"]={q="Warum möchte Thun'grim Brandblick, dass Ihr dies tut?",a="Thun'grim Brandblick hilft Euch dabei, Eure vollständige Rüstung der Brutal Armor zu schmieden, ein Ritus des kriegerischen Fortschritts für vielversprechende Krieger der Horde. Während Thun'grim selbst einige Komponenten herstellen kann, übersteigt die spezialisierte Handwerkskunst, die für die Beinschützer erforderlich ist, seine persönlichen Schmiedetechniken, was ihn dazu veranlasst, Euch an Velora Nachtens zu verweisen, die als eine der besten Rüstungsschmiede von Lordaeron bekannt ist.",al={"thungrim firegaze beweggrund","warum brutale beinschützer herstellen","warum zu velora nachtens schicken"}}},fp="38,276,24.449.0,29.426.0,21.257.0,40.228.0,48.145.0,43.98.1,49.198.0,34.141.0"}
P.entries["quest:1842"] = {n="Satyrhufe",s="In Sen'jin schickt Ula'elek Krieger nach Norden ins Eschental, um Satyrhufe zu sammeln. Er braucht ihre seltsame Macht, um brutale Stulpen zu schmieden.",h="In Sen'jin schickt Ula'elek Krieger nach Norden ins Eschental, um Satyrhufe zu sammeln.",kw={"eschental","brutal gauntlets","durotar","hufe","satyr","sen'jin","ula'elek","ungespalten"},ang={["class:Warrior"]="Als Krieger stellt Ihr Euch bei Eurem Aufstiegsritus listigen dämonischen Angreifern, die Euch aus dem Hinterhalt überfallen. Die Prüfung stellt Eure Widerstandskraft im Kampf auf die Probe und bringt Euch eine eigens für Euch gefertigte Rüstung ein.",["faction:Horde"]="Als Krieger der Horde verlasst Ihr Durotars trockene Ebenen und reist tief in das umkämpfte Gebiet der Nachtelfen im Eschental.",["race:Troll"]="Als Troll erkennt Ihr in Ula'eleks Methoden das Handwerk der Dunkelspeere. Er entzieht gefallenen magischen Feinden rohe Essenz, statt sich allein auf herkömmliche Schmiedekunst zu verlassen."},sec={{t="Verdorbene Essenz nutzbar machen",b="Ula'elek schickt Euch in die uralten Wälder des Eschentals, um zu sammeln, was sein Handwerk erfordert. Dämonische Verderbnis haftet noch immer an den dortigen Satyrzirkeln. Für eine Rüstung, die es mit Kalimdors wildesten Kräften aufnehmen soll, braucht er mehr als Eisen und Leder."},{t="Aufgebläht von Eschentals Magie",b="Im nordöstlichen Eschental nähren sich Satyrn von der verbliebenen Reinheit des Waldes und verdrehen sie zu unheilvoller Macht. Jenen, die am meisten davon aufnehmen, wachsen geschwollene Hufe ohne die übliche Spaltung. Ula'elek will diese konzentrierte Magie entziehen und in seine Stulpen einweben."}},faq={{q="Warum braucht Ula'elek Satyrhufe?",a="Ula'elek braucht die Hufe, um die brutalen Stulpen, die er fertigt, mit Macht zu erfüllen. Er will ihnen die Waldmagie entziehen, die die Satyrn abgesaugt und verdorben haben.",al={"warum satyrhufe","zweck der hufe","wozu dienen die hufe"}},{q="Wo sind die Satyrn zu finden?",a="Satyrn leben im nordöstlichen Eschental zwischen verderbten uralten Ruinen. Dort saugen sie die verbliebene Magie aus den Tiefen des Waldes ab.",al={"wo sind satyrn","satyrfundort","wo satyrhufe finden"}},{q="Was macht einen ungespaltenen Huf besonders?",a="Ein Huf ohne Spaltung kennzeichnet einen Satyr, der sich an der reinen Magie des Eschentals überfressen hat. Die gestohlene Macht lässt seine Füße anschwellen.",al={"hintergrund ungespaltener hufe","warum ungespalten","geschwollene hufe"}},{q="Wer ist Ula'elek?",a="Ula'elek ist ein geschickter Rüstungshandwerker der Dunkelspeertrolle in Sen'jin im südlichen Durotar. Er hilft Kriegern, Ausrüstung für ihre Prüfungen herzustellen.",al={"wer ist ulaelek","questgeber","troll in sen'jin"}},{q="Welche Rüstung schmiedet Ula'elek?",a="Ula'elek fertigt ein Paar Brutal Gauntlets an. Dieser schwere Handschutz wird für aufstrebende Krieger der Horde mit gestohlener Magie erfüllt.",al={"was sind brutal gauntlets","stulpenquest","belohnungsrüstung"}},{q="Dienen die Satyrn hier der Brennenden Legion?",a="Ja. Satyrn sind uralte Nachtelfen, die durch dämonische Pakte verwandelt wurden. Die Zirkel, die noch in Kalimdors Wäldern hausen, nutzen weiterhin Teufelsverderbnis im Dienst dämonischer Mächte.",al={"zugehörigkeit der satyrn","gehören satyrn zur legion"}}},fx={["749a1d7b"]={q="Warum befinden sich die Satyrn im nordöstlichen Eschental?",a="Satyrn suchen das nordöstliche Eschental heim, um sich an der Reinheit des uralten Waldes zu laben. Indem sie seine verborgenen Zauber aussaugen und korrumpieren, stärken sie ihre bösartigen Rituale und verzerren ihre eigenen Körper. Diejenigen, die sich am meisten an der natürlichen Magie des Eschentals gütlich tun, entwickeln groteske, geschwollene, nicht gespaltene Hufe und werden zu lebendigen Gefäßen konzentrierter arkaner Stärke.",al={"warum satyrn im eschental","hintergrund zu satyrhufen","wen für hufen jagen"}}},fp="12,136,28.233.0,30.265.0,36.148.0,27.122.0,36.127.0,16.130.0,31.126.0,44.167.0"}
P.entries["quest:1843"] = {n="Brutale Stulpen",s="In Durotar hat Ula'elek Brutale Stulpen für einen erfahrenen Krieger der Horde vollendet. Seltene Materialien aus fernen Ländern flossen in die Arbeit ein, die sowohl dem Schöpfer als auch dem Träger Ehre bringen soll.",h="In Durotar hat Ula'elek Brutale Stulpen für einen erfahrenen Krieger der Horde vollendet.",kw={"rüstung schmieden","brutale stulpen","durotar","horde","satyr hooves","ula'elek","kriegerrüstung"},ang={["class:Warrior"]="Als Krieger tragt Ihr Stulpen, die für schwere Nahkämpfe gefertigt wurden. Sie kennzeichnen einen Schritt hin zu disziplinierter militärischer Führung.",["faction:Horde"]="Als Mitglied der Horde tragt Ihr die Tradition und den kriegerischen Stolz Eurer Handwerker in die Schlacht. Ihre Arbeit birgt spirituelle Bedeutung und Ehre."},sec={{t="Das Meisterwerk eines Handwerkers",b="In Durotar lässt Ula'elek seine Abstammung und sein Können in eine Rüstung für einen erfahrenen Frontkrieger einfließen. Er formt brutale Stulpen aus gehärteten Trophäen, die gefährlichen Feinden abgenommen wurden. Die fertige Rüstung kann heftigen Hieben standhalten und die Angriffe des Trägers verstärken."},{t="Die Ehre der Ahnen",b="Unter Orcs und Trollen tragen erlesene Waffen und Rüstungen das Ansehen der Schmiede und den Geist des Schöpfers in die Schlacht. Wenn Ula'elek die fertigen Stulpen überreicht, vertraut er einem Krieger das Erbe seiner Ahnen an. Er erwartet von einem Champion, der sie trägt, dieser Handwerkskunst mit Mut, kriegerischer Disziplin und Stärke gerecht zu werden."}},faq={{q="Wer ist Ula'elek?",a="Ula'elek ist ein Handwerker aus Durotar, der maßgefertigte Rüstungen für Krieger der Horde herstellt. Er verlangt exotische Materialien, damit seine Arbeit seinem Handwerk und den Traditionen seiner Ahnen Ehre erweist.",al={"ulaelek","wer gibt brutale stulpen","questgeber"}},{q="Warum wurden Satyr Hooves für diese Stulpen benötigt?",a="Satyr Hooves sind geschwollen und ungespalten und bergen Macht, die der Magie des Eschentals entzogen wurde. Ula'elek zieht diese Macht heraus und überträgt sie auf die Stulpen, wodurch er ihnen große magische Kraft verleiht.",al={"warum satyr hooves","satyrteile","verwendete materialien"}},{q="Was bedeutet es für Ula'elek, die Stulpen zu tragen?",a="Für Ula'elek sind die Stulpen das vollendetste Werk seiner Handwerkskunst. Sie einem würdigen Krieger zu übergeben, ehrt sein Handwerk und seine Ahnen und verbindet seine Arbeit mit den Siegen der Horde in der Schlacht.",al={"ahnen ehren","ula'elek ehre"}},{q="Wo findet diese Aufgabe statt?",a="Die Schmiedearbeit endet in Durotar, der kargen Heimat der Orcs und Dunkelspeertrolle. Dort prüft Ula'elek die beschafften Materialien und überreicht die fertige Rüstung.",al={"ort","wo wird brutale stulpen abgegeben"}},{q="Ist diese Prüfung für alle Abenteurer gedacht?",a="Die Prüfung richtet sich an Frontkrieger, die ihre Ausdauer und ihre Hingabe an die Kriegskunst bewiesen haben. Sie kennzeichnet ihren Aufstieg in die Reihen erfahrenerer Kämpfer der Horde.",al={"nur für krieger","klassenvoraussetzung"}},{q="Was folgt nach dem Erhalt der Stulpen?",a="Mit dem Erhalt der Stulpen ist diese Handwerksprüfung abgeschlossen. Der Krieger ist gerüstet, sich auf Azeroths kriegsgezeichneten Schlachtfeldern größeren Bedrohungen zu stellen.",al={"nächste quest","folgequest von brutale stulpen"}}},fp="16,172,25.252.0,15.308.0,16.160.0,49.172.0,52.179.0,32.161.0,43.165.0,41.142.0"}
P.entries["quest:1844"] = {n="Schimärenhorn",s="Im Verbrannten Tal prüft eine leidende Schimärenmatriarchin Stärke und Gnade eines Horde-Kriegers. Orm Stonehoof braucht ihr Horn für den Brutal Helm, und die Jagd wird die Entschlossenheit des Kriegers beweisen.",h="Im Verbrannten Tal prüft eine leidende Schimärenmatriarchin Stärke und Gnade eines Horde-Kriegers.",kw={"brutal helm","das verbrannte tal","schimärenmatriarchin","schimärenhorn","galvanisiertes horn","orm stonehoof","steinkrallengebirge","donnerfels","kriegerquest"},ang={["class:Warrior"]="Als Krieger beweist Ihr Euer Können, indem Ihr an einem brutalen Ort ein einzelgängerisches Alphatier jagt. Damit erwerbt Ihr das Recht, den Brutal Helm zu tragen.",["faction:Horde"]="Als Mitglied der Horde reist Ihr von Sonnenfels in die umkämpfte Wildnis des Steinkrallengebirges. Dort schmiedet Ihr die Waffen, die zur Verteidigung Kalimdors benötigt werden.",["race:Tauren"]="Als Tauren hört Ihr die Ehrfurcht in Orm Stonehoofs Worten. Selbst im Kampf ehrt es die Earth Mother, das Leiden einer gequälten Bestie zu beenden."},sec={{t="Eine Prüfung der Entschlossenheit",b="Orm Stonehoof wird den Brutal Helm für Krieger der Horde schmieden, doch der Brauch verlangt einen Beweis, bevor er beginnt. Metall und Münzen allein genügen nicht. Ein Krieger muss sein Können im Kampf beweisen und sich den Narben stellen, die ein verheerender Konflikt hinterlassen hat."},{t="Die Narben des Verbrannten Tals",b="Das Verbrannte Tal liegt im südwestlichen Steinkrallengebirge, unter Asche begraben. Einst üppig und grün, wurde das Tal zu einer rauchenden Einöde niedergebrannt. Noch immer durchstreifen Bestien seine rußbedeckten Krater, von Schmerz und Wut entstellt. Mächtige Schimären nisten zwischen toten Bäumen und sengenden Dampfschloten."},{t="Gnade im Kampf",b="Für den Tauren-Schmied wird das Horn der Schimärenmatriarchin für den Helm benötigt und beweist die Stärke eines Kriegers. Doch die Jagd beendet auch ihre Qualen. Indem der Krieger die Matriarchin fällt, erweist er einem wilden Geist Gnade, den die Zerstörung seiner Heimat in den Wahnsinn getrieben hat."}},faq={{q="Wer ist Orm Stonehoof?",a="Orm Stonehoof ist ein geschickter Tauren-Schmied in Donnerfels, der erfahrenen Kriegern der Horde hilft, ihre Klassenrüstung herzustellen, darunter den Brutal Helm.",al={"orm stonehoof hintergrundgeschichte","wer ist orm stonehoof","donnerfels schmied orm"}},{q="Warum will Orm das Galvanisierte Horn?",a="Orm will das Galvanisierte Horn, weil es ein widerstandsfähiger Bestandteil des Brutal Helm ist. Es zu erbeuten beweist auch den Mut des Kriegers, ein gefährliches Alpharaubtier in tückischem Gelände aufzuspüren und zu besiegen.",al={"galvanisiertes horn verwendung","warum galvanisiertes horn beschaffen","brutal helm horn"}},{q="Was sind Schimären im Steinkrallengebirge?",a="Schimären sind große, zweiköpfige geflügelte Bestien, die in Kalimdor heimisch sind. Feuer und Zerstörung im Verbrannten Tal haben die dort überlebenden Schimären in einen gewalttätigen Wahnsinn getrieben.",al={"steinkrallengebirge schimären","schimären hintergrundgeschichte","was sind schimären"}},{q="Wie fügt sich diese Quest in die Kriegerausbildung ein?",a="Etwa in ihrer dreißigsten Saison suchen Krieger der Horde Spezialisten wie Orm Stonehoof auf, um sich gefährlichen Prüfungen zu stellen. Wer diese Prüfungen besteht, erwirbt das Recht, das schwere, stachelbesetzte Rüstungsset Brutal Armor zu tragen, das für die Champions des Schlachtfelds gefertigt wird.",al={"krieger brutal helm questreihe","stufe dreißig kriegerquest donnerfels","brutal armor questreihe"}},{q="Warum stellt Orm die Jagd als einen Akt der Gnade dar?",a="Die Kultur der Tauren ehrt den Einklang mit der Erde und ihren Geschöpfen. Die Bewohner des Verbrannten Tals leiden unter der Verwüstung ihres Landes, weshalb das Töten der Matriarchin als Ende ihrer unablässigen Schmerzen gilt, nicht als sinnloses Abschlachten.",al={"warum gnade für die matriarchin","sie von ihrem elend befreien"}}},fx={["3a1b9e89"]={q="Wozu dient das Galvanisierte Horn?",a="Das Galvanisierte Horn erfüllt für Orm Stonehoof einen doppelten Zweck. Materiell liefert es das gewaltige, gehärtete Horn, das zum Schmieden Eures Brutal Helm benötigt wird. Ritualistisch dient es als physischer Beweis dafür, dass Ihr den aschfahlen Einöden des verbrannten Tals getrotzt, einer wahnsinnigen Chimärenmatriarchin gegenübergetreten seid und sowohl kriegerische Stärke als auch die Gnade bewiesen habt, ihr die Erlösung zu gewähren.",al={"verwendung des galvanisierten horns","warum brauche ich das galvanisierte horn","galvanisiertes horn für brutal helm"}},["241e9666"]={q="Wen sollt Ihr im verbrannten Tal jagen?",a="Ihr seid ausgesandt, um eine Chimärenmatriarchin zu jagen, die inmitten der Ruinen des verbrannten Tals haust. Einst ein üppiges Hochlandtal, wurde das Tal durch feurige Zerstörung völlig entweiht, was die überlebenden Bestien vor Qual und Verzweiflung in den Wahnsinn trieb. Die Matriarchin ist eine dieser majestätischen Raubtiere, die nun endlos in der verpesteten Asche leidet, bis Ihr ihr ein ehrenvolles Ende bereitet.",al={"ziel chimärenmatriarchin","wen im verbrannten tal töten","ziel chimaeric horn"}},c3120874={q="Warum schickt Orm Euch, anstatt selbst zu gehen?",a="Orm Stonehoof stellt Euren Geist auf die Probe und bittet nicht um einen routinemäßigen Botengang. Der Brutal Helm ist ein traditionelles, mächtiges Rüstungsteil, das nur Kriegern vorbehalten ist, die ihre Entschlossenheit, ihr kriegerisches Können und ihre Fähigkeit zu ehrenvoller Gnade bewiesen haben. Indem Ihr das Biest selbst in den feindseligen Einöden des verbrannten Tals jagt, beweist Ihr Orm, dass Ihr würdig seid, sein Werk zu tragen.",al={"warum schickt orm mich","warum kann orm die matriarchin nicht jagen","warum braucht orm einen abenteurer"}}},fp="14,196,17.218.0,29.281.0,15.257.0,21.146.0,38.193.0,33.157.0,46.227.0,47.231.0"}
P.entries["quest:1845"] = {n="Brutaler Helm",s="In Donnerfels schließt Orm Stonehoof die Kriegerprüfung mit dem Brutalen Helm ab. Nach dem Sammeln seltener Bestientrophäen in ganz Kalimdor erhält ein angehender Krieger als Anerkennung einen gehörnten Helm, der seine Stärke ehrt.",h="In Donnerfels schließt Orm Stonehoof die Kriegerprüfung mit dem Brutalen Helm ab.",kw={"brutaler helm","chimaeric horn","erdenmutter","die anhöhe der jäger","orm stonehoof","donnerfels","krieger"},ang={["class:Warrior"]="Als Krieger der Horde besteht Ihr einen entscheidenden Ritus und legt schwere Rüstung an, die aus wilden Bestien geschmiedet und von erfahrenen Ausbildern gesegnet wurde.",["faction:Horde"]="Unter dem Banner der Horde beweist Ihr die körperliche Ausdauer und das Jagdgeschick, die Eure Anführer verlangen.",["race:Tauren"]="In Donnerfels spiegelt Euer Helm die Tradition der Tauren wider, Jagdtrophäen unter dem Segen der Erdenmutter in schützende Kriegsausrüstung zu verwandeln."},sec={{t="Der Ritus eines Kriegers",b="Orm Stonehoof ist ein strenger Schmied in Donnerfels, der Krieger der Horde durch harte Übergangsriten führt. Die Prüfungen testen ihr Geschick im Kampf. Anwärter jagen gefährliche Kreaturen in tückischen Landen und erbeuten seltene Trophäen. Nur wer Orms hohen Ansprüchen genügt, darf vor ihn treten, um seine Rüstung zu vervollständigen."},{t="Die Gabe der Erdenmutter",b="Der Krieger beweist seine Entschlossenheit in der Wildnis, indem er Orm Stonehoof ein seltenes Horn einer Chimäre bringt. Dafür überreicht Orm den Brutalen Helm, einen schweren Kettenhelm, der die Bestie ehren und seinen Träger an vorderster Front stärken soll. Als er den Helm überreicht, erbittet Orm den Segen der Erdenmutter. Er blickt auf die größeren Taten voraus, die der Krieger in ganz Azeroth vollbringen wird."}},faq={{q="Wer bietet den Brutalen Helm an?",a="Orm Stonehoof, ein Taurenschmied in Donnerfels, überreicht den Brutalen Helm an Krieger der Horde, die seine Prüfungen bestehen.",al={"wer gibt den brutalen helm","brutaler helm npc","orm stonehoof quest"}},{q="Welche Aufgabe muss vor dem Erhalt des Helms abgeschlossen werden?",a="Bevor Ihr den Helm erhaltet, schließt Ihr die Prüfung namens Chimaeric Horn ab. Ihr jagt wilde Bestien in der Wildnis und bringt ihr Horn zu Orm Stonehoof in Donnerfels.",al={"voraussetzung für den brutalen helm","chimaeric horn quest"}},{q="Wo befindet sich Orm Stonehoof?",a="Orm Stonehoof befindet sich nahe dem Wasserbecken neben dem großen zentralen Totem in Donnerfels, der Stadt auf hohen Tafelbergen.",al={"orm stonehoof standort","wo ist orm stonehoof"}},{q="Warum ruft Orm Stonehoof die Erdenmutter an?",a="Als Tauren verehrt Orm die Erdenmutter als Schöpferin und spirituelle Hüterin der Welt. Ihr Segen für den fertigen Helm eines Kriegers spiegelt den Glauben der Tauren wider, dass Kampfkraft und spirituelle Ehrfurcht im Gleichgewicht stehen müssen.",al={"warum die erdenmutter erwähnen","erdenmutter hintergrundgeschichte"}},{q="Steht diese Prüfung jedem Abenteurer offen?",a="Nein. Die Prüfung und ihre Belohnungen aus Brutal Armor sind für Krieger der Horde bestimmt, die sich in besonderen Klassenprüfungen bewähren.",al={"kann jeder den brutalen helm erhalten","brutaler helm klasse"}},{q="Welche Bedeutung hat das Rüstungsset Brutal Armor?",a="Die Teile von Brutal Armor kennzeichnen den Aufstieg eines Kriegers vom unerfahrenen Soldaten zum Elitechampion der Horde. Sie werden aus Materialien gefertigt, die von Kalimdors wildesten Raubtieren stammen.",al={"brutal armor hintergrundgeschichte","warum heißt er brutaler helm"}}},fx={["3a1185bd"]={q="Warum belohnt Orm Stonehoof Euch mit dem Brutal Helm?",a="Orm Stonehoof verleiht den Helm nicht aus einer verzweifelten Notlage oder einer plötzlichen Krise heraus, sondern als zeremonielle Anerkennung Eurer kriegerischen Entwicklung. Indem Ihr seltene Materialien aus ganz Kalimdor gesammelt und Eure Stärke in den Kriegerprüfungen unter Beweis gestellt habt, habt Ihr gezeigt, dass Ihr bereit seid, den Mantel erfahrener Champions zu tragen. Orm ehrt diese Ausdauer und ruft den Segen der Erdenmutter an, damit Eure Rüstung Euch in den noch größeren Schlachten, die auf Euch warten, schützen möge.",al={"warum gibt orm euch den helm","motiv von orm stonehoof für brutal helm","warum brutal helm"}}},fp="11,227,16.312.0,27.358.0,27.116.0,53.168.0,31.98.0,46.223.0,37.120.0,49.179.0"}
P.entries["quest:1846"] = {n="Schienbeinknochen der Drachenmalorcs",s="Velora Nachtens schickt Krieger der Horde aus Unterstadt ins südliche Sumpfland, um Schienbeinknochen der Drachenmalorcs zu sammeln. Die dicken Knochen sollen Brutale Beinschützer gegen die Schläge verstärken, denen ein erfahrener Krieger ausgesetzt ist.",h="Velora Nachtens schickt Krieger der Horde aus Unterstadt ins südliche Sumpfland, um Schienbeinknochen der...",kw={"lager der grollhauer","brutale beinschützer","dragonmaw","schienbeinknochen","thandol-übergang","unterstadt","velora nachtens","sumpfland"},ang={["class:Warrior"]="Als Krieger prüft Ihr Eure Stärke im Feld und sammelt grausige Materialien, um stärkere Rüstung herzustellen.",["faction:Horde"]="Als Mitglied der Horde schwächt Ihr einen gefährlichen Überrest der Old Horde in Khaz Modan und stärkt Thralls Bündnis.",["race:Orc"]="Als Orc, der Orgrimmar treu ergeben ist, begegnet Ihr den uneinsichtigen Dragonmaw und dem blutigen Preis für die Erlösung Eures Volkes von seiner teuflischen Vergangenheit.",["race:Undead"]="Als Untoter seht Ihr, wie Velora Nachtens humanoide Überreste praktisch verwertet, denn die Verlassenen nutzen jede Ressource, wie grausig sie auch sein mag."},sec={{t="Ein grausiges Gerüst",b="Velora Nachtens, eine Rüstungsbauerin der Verlassenen in Unterstadt, braucht eine stabile Verstrebung für Brutale Beinschützer. Sie schickt Krieger der Horde ins Sumpfland, um dicke Knochen von den Dragonmaw-Orcs zu sammeln. Ihr dichter Knochenbau hält den schweren Schlägen stand, denen erfahrene Krieger ausgesetzt sind."},{t="Die Knochenprobe",b="Velora braucht Knochen, die standhalten. Jeder muss eine Prüfung mit bloßen Händen bestehen; alle, die zerbrechen, sind zu spröde für die Schmiede. Also durchkämmen Krieger die Lager der Abtrünnigen entlang der schroffen Felsen des Sumpflands und zerbrechen schwache Exemplare, bis acht stabile Schienbeinknochen übrig bleiben."}},faq={{q="Warum braucht Velora Nachtens ausgerechnet Schienbeinknochen von Orcs?",a="Velora braucht dicke, dichte Knochen, um die Brutalen Beinschützer zu verstärken. Sie hält den kräftigen Knochenbau der Dragonmaw-Orcs dafür für besser geeignet als gewöhnliches Wild oder aufgelesene Überreste.",al={"warum schienbeinknochen von orcs","warum dragonmaw-knochen","velora knochenrüstung"}},{q="Warum dürfen Krieger der Horde die Dragonmaw-Orcs jagen?",a="Die verbliebenen Dragonmaw im Sumpfland sind feindselige Abtrünnige, die noch immer dem dunklen Erbe des Zweiten Krieges verbunden sind. Sie schulden Thralls Horde keine Treue, daher dürfen Krieger der Horde sie als Feinde jagen.",al={"sind dragonmaw in der horde","warum dragonmaw bekämpfen","dragonmaw verhältnis zur horde"}},{q="Wo sind die Dragonmaw für diese Aufgabe zu finden?",a="Die Dragonmaw befinden sich im Sumpfland, vom Arathihochland aus südlich jenseits des Thandol-Übergangs. Krieger jagen nahe den steilen Berghängen beim Lager der Grollhauer, südwestlich der großen Straße im Norden.",al={"dragonmaw fundort","wo schienbeinknochen der drachenmalorcs finden","lager der grollhauer standort"}},{q="Warum zerbrechen während der Quest so viele Knochen?",a="Velora braucht die dichtesten Knochen für das Gerüst der Rüstung. Krieger prüfen jeden mit bloßen Händen und verwerfen alle, die unter Druck zerbrechen, denn spröde Knochen können die Beine eines Kriegers im Kampf nicht schützen.",al={"zerbrochene schienbeinknochen","warum zerbrechen schienbeinknochen","knochen auf stabilität prüfen"}},{q="Wer ist Velora Nachtens?",a="Velora Nachtens ist eine Rüstungsbauerin der Verlassenen in Unterstadt. Schroff und mit makaber trockenem Humor hilft sie Kriegern der Horde, besondere Ausrüstung für kampferprobte Veteranen herzustellen.",al={"velora nachtens hintergrundgeschichte","wer ist velora","rüstungsbauerin in unterstadt"}},{q="Welches Rüstungsteil wird aus diesen Knochen geschmiedet?",a="Die Knochen bilden das Gerüst der Brutalen Beinschützer, widerstandsfähiger Kettenbeinschützer für Krieger der Horde auf mittleren Stufen.",al={"schienbeinknochen belohnung","wozu dienen die schienbeinknochen","brutale beinschützer herstellen"}}},fx={["0579d748"]={q="Warum möchte Velora Nachtens, dass dies erledigt wird?",a="Velora Nachtens benötigt Schienbeinknochen von Dragonmaw-Orcs im Sumpfland, um Eure Brutale Beinschützer anzufertigen. Ihre stabilen Knochen liefern das Material für die Rüstung, die sie zu fertigen zugestimmt hat.",al={"motiv von velora nachtens","warum will velora schienbeinknochen","velora nachtens warum"}}},fp="19,193,19.254.0,18.232.0,55.172.0,56.195.0,44.198.0,51.185.0,21.178.0,44.95.0"}
P.entries["quest:1848"] = {n="Brutale Halsberge",s="Im ganzen Brachland bestehen Krieger der Horde eine Prüfung, bevor Thun'grim Brandblick ihnen Kettenrüstung schmiedet. Sie sammeln seltene Materialien und stellen sich gefährlichen Feinden in vielen Landen, dann bringen sie ihre Ausbeute dem zurückgezogen lebenden Schmied. Er hämmert daraus eine Rüstung für die Schlacht.",h="Im ganzen Brachland bestehen Krieger der Horde eine Prüfung, bevor Thun'grim Brandblick ihnen Kettenrüstung...",kw={"brutal armor","brutale halsberge","das wegekreuz","orcische schmiedekunst","brachland","thun'grim firegaze","kettenrüstung für krieger"},ang={["class:Warrior"]="Als junger Krieger der Horde verdient Ihr Euch die Brutale Halsberge beim Aufstieg vom unerfahrenen Rekruten zum abgehärteten Kämpfer in maßgefertigter Kettenrüstung.",["faction:Horde"]="Als Mitglied der Horde könnt Ihr ihre Tugenden kriegerischer Eigenständigkeit und Stärke in einer Halsberge aus Trophäen erkennen, die in Kalimdors Wildnis errungen wurden.",["profession:Blacksmithing"]="Als Schmied könnt Ihr von Thun'grims traditioneller orcischer Handwerkskunst lernen, bei der Kampfgeist und Widerstandskraft in Stahl gehämmert werden."},sec={{t="Das Meisterwerk eines Schmieds",b="Im nördlichen Brachland schmiedet Thun'grim Brandblick, ein Orc, nur Rüstungen für Krieger, die seine Forderungen erfüllen. Der zurückgezogen lebende Schmied schickt sie weit umher, um widerstandsfähige Bestienteile, seltenes Metall und alchemistische Reagenzien zu sammeln, bevor er seinen Blasebalg betätigt. Die fertige Halsberge schützt ihren Träger und zeugt von seiner bewiesenen Ausdauer und Entschlossenheit. Erfahrene Kämpfer in der ganzen Horde erkennen diesen hart errungenen Beweis an."},{t="In Entbehrung geschmiedet",b="Thun'grim stellt bewusst harte Forderungen. Waffen und Rüstungen der Horde sollen vom Augenblick ihrer Entstehung an den Schweiß und das Blut ihres Trägers tragen. Wenn Ihr die fertige Brutale Halsberge übergebt, spricht der Schmied kein Lob aus. Er erwartet, dass Ihr die Rüstung im brutalen Kampf erprobt und mit Geschichten von Blut und Ehre zurückkehrt."}},faq={{q="Was ist die Brutale Halsberge?",a="Die Brutale Halsberge ist ein robustes Bruststück, gefertigt von Thun'grim Brandblick, einem Orcschmied. Krieger der Horde verdienen sie sich, indem sie ihr Kampfgeschick beweisen und seltene Materialien in mehreren gefährlichen Landen sammeln.",al={"was ist die brutale halsberge","quest für die brutale halsberge","wer fertigt die brutale halsberge"}},{q="Wer ist Thun'grim Brandblick?",a="Thun'grim Brandblick ist ein erfahrener, zurückgezogen lebender Schmied auf einem Bergsporn im nördlichen Brachland, direkt östlich der Straße zwischen dem Wegekreuz und Orgrimmar. Er prüft aufstrebende Krieger und schmiedet ihnen besondere Rüstungen, wenn sie sich als würdig erweisen.",al={"wer ist thun grim","thungrim firegaze","wo ist thungrim"}},{q="Warum verlangt Thun'grim so viel Mühe, bevor er die Rüstung fertigt?",a="Die Kriegertradition der Horde schätzt Entbehrung ebenso wie Kampfgeschick. Thun'grim glaubt, dass feine Kettenrüstung jenen gebührt, die ihr eigenes Blut vergossen und die seltenen Bestandteile für ihre Fertigung mühsam gesammelt haben.",al={"warum so viele materialien sammeln","anforderungen für brutal armor","thungrims prüfungen"}},{q="Wohin führt diese Questreihe als Nächstes?",a="Nachdem Thun'grim Euch die fertige Halsberge überreicht hat, ist seine Arbeit für Euch abgeschlossen. Ihr könnt die Rüstung in ganz Kalimdor und den Östlichen Königreichen in die Schlacht tragen.",al={"was kommt nach der brutalen halsberge","nächste quest nach der brutalen halsberge","gibt es eine folgequest"}},{q="Ist die Quest für die Brutale Halsberge für die Allianz verfügbar?",a="Nein. Die Brutale Halsberge ist eine Prüfung der Horde. Krieger der Allianz durchlaufen bei den Schmieden von Eisenschmiede und den umliegenden Zwergengebieten einen eigenen kriegerischen Ritus, um ihre unverwechselbare Rüstung zu schmieden.",al={"kann die allianz die brutale halsberge erhalten","gegenstück der allianz","ist das nur für die horde"}},{q="Wo im Brachland ist Thun'grim zu finden?",a="Thun'grim lebt auf einem hohen Grat im nördlichen Brachland, direkt südlich des Dornenhügels und östlich des Wegekreuzes.",al={"thungrims standort","wo ist thungrim im brachland","wie thun grim finden"}}},fx={a5674fab={q="Warum schmiedet Thun'grim Brandblick diesen Brutal Hauberk für Euch?",a="Thun'grim Brandblick schmiedet seine Brutal Armor nicht für irgendwen. Als geehrter Meisterrüstmeister, der vielversprechende Krieger der Horde prüft, verlangt er den Beweis von Ausdauer, Stärke und roher Zähigkeit, bevor er seinen Hammer schwingt. Indem Ihr die notwendigen Materialien gesammelt und in seinem Namen Gefahren getrotzt habt, habt Ihr Euch als würdig erwiesen, seine feinste Handwerkskunst in die Schlacht zu tragen.",al={"warum ich brutal hauberk","warum fertigt thungrim die rüstung","warum brutal hauberk geben"}}},fp="14,256,21.404.0,18.329.0,27.207.0,26.253.0,68.202.0,38.162.0,54.195.0,44.109.0"}
P.entries["quest:185"] = {n="Beherrschen der Tigerjagd",s="Bei Nesingwarys Expedition lehrt Ajeck Rouack Jäger, Großkatzen aufzuspüren. Sie beginnt mit jungen Tigern nahe dem nördlichen Lager und prüft dabei die Jagd- und Fährtenlesekünste eines Neulings.",h="Bei Nesingwarys Expedition lehrt Ajeck Rouack Jäger, Großkatzen aufzuspüren.",kw={"ajeck rouack","jagd","nesingwary","schlingendorntal","beherrschen der tigerjagd","junger schlingendorntiger"},sec={{t="Erste Lektionen im Dschungel",b="Ajeck Rouack lernte als Mädchen von ihrem Vater, Tiger zu jagen. Nun gibt sie sein Handwerk an Reisende weiter, die Nesingwarys Expedition nach „Willkommen im Dschungel“ erreichen. Junge Tiger sind die erste Beute. Sie aufzuspüren und zu jagen bereitet Euch darauf vor, größere Beute zu verfolgen."},{t="Jagd auf die Streuner",b="Junge Schlingendorntiger streifen durch den Dschungel nahe dem Expeditionslager. Ajeck Rouack bittet Euch, zehn zu jagen. Sie verlangt einen Beweis Eures Könnens, bevor sie Euch weiter ausbildet."}},faq={{q="Wer bietet Euch eine Ausbildung in der Tigerjagd an?",a="Ajeck Rouack bietet Euch bei Nesingwarys Expedition im nördlichen Schlingendorntal eine Ausbildung in der Tigerjagd an.",al={"wer vergibt beherrschen der tigerjagd","ajeck rouack quest","questgeber tigerjagd"}},{q="Warum nimmt Ajeck Rouack zuerst junge Tiger ins Visier?",a="Ajeck Rouack beginnt mit jungen Tigern, weil sie diese für leichter aufzuspüren und zu jagen hält. Sie stellen Eure Fährtenlesekünste auf die Probe, bevor Ihr gefährlichere Beute verfolgt.",al={"warum junge tiger","warum bei beherrschen der tigerjagd leicht anfangen"}},{q="Wo sind die jungen Tiger zu finden?",a="Junge Schlingendorntiger streifen durch den Dschungel nahe dem Lager von Nesingwarys Expedition.",al={"wo sind junge schlingendorntiger","fundort junger tiger"}},{q="Was kommt vor dieser Jagd?",a="Ihr erreicht das Safarilager nach „Willkommen im Dschungel“, wodurch Ihr das Lager kennenlernt.",al={"beherrschen der tigerjagd voraussetzung","beherrschen der tigerjagd vorherige quest"}}},fp="13,177,27.272.0,20.170.0,41.108.0,48.162.0,33.78.0,28.92.0"}
P.entries["quest:1858"] = {n="Die Zerschmetterte Hand",s="In Orgrimmar prüft Therzok Schurken, die einen Platz in der Zerschmetterten Hand suchen. Er will, dass Tazans wiederbeschaffter Ranzen mit einem Schlüssel geöffnet wird, der einem ahnungslosen Komplizen entwendet wurde.",h="In Orgrimmar prüft Therzok Schurken, die einen Platz in der Zerschmetterten Hand suchen.",kw={"die kluft der schatten","gamon","orgrimmar","taschendiebstahl","schurke","zerschmetterte hand","tazan","therzok"},ang={["class:Rogue"]="Als Schurke lernt Ihr, Euch an einem belebten Ort an ein ahnungsloses Ziel heranzuschleichen, unbemerkt einen Schlüssel zu entwenden und wichtige Informationen zu sichern.",["faction:Horde"]="Unter der kriegerischen Ehre von Thralls neuer Horde bleibt verdeckte Aufklärung notwendig. Die Zerschmetterte Hand übernimmt sie im Stillen, tief im Inneren Orgrimmars."},sec={{t="Eine Prüfung der Finesse",b="Ihr habt Tazans verschlossenen Ranzen, doch ohne seinen Schlüssel nützt er Euch nichts. Therzok erwartet von einem Schurken, das Schloss mit Geschick zu bezwingen, statt mit roher Gewalt. Also schickt er Euch zu Gamon, einem Tauren-Trunkenbold, der häufig Orgrimmars Taverne aufsucht. Gamon lässt sich leicht ablenken und hat Tazan einst geholfen. Das macht ihn zu einem geeigneten Ziel für einen unauffälligen Diebstahl."},{t="Willkommen in den Schatten",b="Entwendet Gamon den Schlüssel, ohne die Taverne zu alarmieren. Öffnet dann den Ranzen und bringt Tazans Logbuch zu Therzok in die Kluft der Schatten. Ein sauber ausgeführter Auftrag erfüllt die Maßstäbe der Zerschmetterten Hand. Therzok erkennt Euch offiziell als einen ihrer Agenten an."}},faq={{q="Wer ist Gamon und warum hat er den Schlüssel?",a="Gamon half einst Tazan, dem Agenten, gegen den Therzok ermittelt. Als Tazan den Ranzen bei sich trug, überließ er dessen Schlüssel Gamon, einem ahnungslosen Trunkenbold, der seine Tage trinkend in Orgrimmars zentraler Taverne verbringt.",al={"warum gamon","wer hat den schlüssel","gamon schlüssel"}},{q="Was ist in Tazans Ranzen?",a="Tazans Logbuch liegt im verschlossenen Ranzen. Es enthält Informationen, die für Therzok und die Zerschmetterte Hand von Interesse sind. Seine Beschaffung prüft Eure Fähigkeit, heimlich wichtige Informationen zu sichern.",al={"tazans logbuch","ranzeninhalt","was ist im ranzen"}},{q="Was ist die Zerschmetterte Hand in Orgrimmar?",a="Die Zerschmetterte Hand war ursprünglich ein berüchtigter Orkklan aus Draenor, bekannt für Selbstverstümmelung und Skrupellosigkeit. In Orgrimmar ist sie die Gilde der Assassinen, Spione und Schurken der Horde und operiert von der unterirdischen Kluft der Schatten aus.",al={"was ist die zerschmetterte hand","zerschmetterte hand schurken","orgrimmar schurken"}},{q="Wo wirkt Therzok?",a="Therzok arbeitet von der Kluft der Schatten aus, einem düsteren Höhlennetz unter Orgrimmars felsigen Höhenzügen. Dort versammeln sich Hexenmeister, Schurken und Schattenkünste, fern vom Tageslicht.",al={"wo ist therzok","therzok standort","kluft der schatten schurkenlehrer"}},{q="Warum bricht Therzok den Ranzen nicht einfach auf?",a="Der Ranzen hat ein kompliziertes Schloss, und Therzok prüft die Disziplin eines Schurken. Die Zerschmetterte Hand schätzt präzisen Diebstahl und Finesse mehr als lärmende Zerstörung.",al={"warum taschendiebstahl","warum schlüssel nötig"}},{q="Was geschieht nach dieser Quest?",a="Mit der Übergabe von Tazans Logbuch schließt Ihr Eure Aufnahmeprüfung ab. Therzok erkennt Euch als Mitglied der Zerschmetterten Hand an und gibt Euch Werkzeuge für verdeckte Einsätze.",al={"zerschmetterte hand belohnung","ende der questreihe"}}},fx={["74a53139"]={q="Warum möchte Therzok, dass Tazans Ranzen geöffnet wird?",a="Therzok und The Shattered Hand operieren aus den Schatten von Orgrimmar und handeln mit Geheimnissen und verdeckter Sicherheit für die Horde. Tazan besaß Informationen, die für ihre Operationen entscheidend waren, aber der heikle Inhalt blieb in einem komplizierten Ranzen verschlossen. Therzok will die darin enthaltenen Informationen, ohne sie zu zerstören, und nutzt die Bergung als praktische Prüfung, um zu sehen, ob Ihr über die List, Heimlichkeit und das Geschick verfügt, die einer formellen Aufnahme in ihre Gilde würdig sind.",al={"motiv von therzok","warum den ranzen öffnen","was will therzok"}},a30dee79={q="Was ist Tazans Logbuch?",a="Tazans Logbuch enthält die schriftlichen Aufzeichnungen und geheimen Geschäfte von Tazan, einem Agenten, dessen Aktivitäten die Aufmerksamkeit von The Shattered Hand erregten. Sicher in seinem verschlossenen Ranzen verwahrt, enthält das Logbuch die entscheidenden Informationen, die Therzok benötigt. Es unversehrt zu übergeben beweist nicht nur Eure Fähigkeit, Taschen zu stehlen und knifflige Schlösser zu knacken, sondern liefert auch wertvolle Informationen direkt an die Spionagemeister von Orgrimmar.",al={"tazans logbuch","was steht im logbuch","hintergrund zu tazans logbuch"}},["1b7f194d"]={q="Warum schickt Therzok nicht die Wachen von Orgrimmar hinter Gamon her?",a="The Shattered Hand lebt von Diskretion und Geheimhaltung, weit entfernt von den offensichtlichen, ehrenhaften Methoden der Stadtwache. Die Grunts von Orgrimmar einzubeziehen, um einen betrunkenen Tavernengast wie Gamon festzunehmen, würde ein unerwünschtes öffentliches Spektakel verursachen und mögliche Verbündete von Tazan warnen. Den Diebstahl einem aufstrebenden Schurken anzuvertrauen hält die Operation unauffällig und dient gleichzeitig als stille Bewertung Eurer Finesse.",al={"warum ich","warum schurke schicken","warum keine stadtwachen"}}},fp="18,163,18.320.0,22.248.0,42.210.0,31.187.0,40.227.0,27.162.0,48.152.0,30.149.1"}
P.entries["quest:1859"] = {n="Therzok",s="In Orgrimmar erwartet Therzok einen vielversprechenden Schurken aus Durotar. Kaplak hat Euer Geschick im Umgang mit Gewalt und Heimlichkeit erkannt und schickt Euch in die Kluft der Schatten zu einem Agenten der Shattered Hand.",h="In Orgrimmar erwartet Therzok einen vielversprechenden Schurken aus Durotar.",kw={"auftragsmörder","die kluft der schatten","durotar","kaplak","orgrimmar","schurke","shattered hand","therzok"},ang={["class:Rogue"]="Als Schurke führt Euch diese Vorladung in die Shattered Hand. Eure bisher einsame Arbeit in Durotar wird nun Teil des organisierten Spionagenetzwerks der Horde.",["faction:Horde"]="Als Mitglied der Horde wisst Ihr, dass Thrall Ehre und den Geist des Kriegers predigt. Therzoks Netzwerk zeigt, dass die Horde auch auf ungesehene Klingen und heimliche Sammler von Informationen angewiesen ist."},sec={{t="Eine geflüsterte Vorladung",b="Die New Horde ehrt Thrall, doch nicht alle ihre Diener kämpfen offen unter seinem Banner. Orgrimmar erreicht die Kunde von einem Kämpfer, der Gewalt und Heimlichkeit beherrscht und bereit ist, die Regeln offener Kriegsführung zu beugen. Die Untergrundgilde wird aufmerksam."},{t="In die Kluft der Schatten",b="Kaplak schickt Euch unter Orgrimmars rote Felsklippen in die Kluft der Schatten. Dort wartet Therzok, verborgen vor den Grunts der Stadt. Einzelgängerische Beutelschneider und Hinterhaltleger werden in die Shattered Hand aufgenommen, das geheime Netzwerk der Horde aus Dolchen im Dunkeln."}},faq={{q="Wer ist Therzok?",a="In Orgrimmars Kluft der Schatten dient Therzok der Shattered Hand. Er empfängt vielversprechende junge Schurken von Durotars Übungsplätzen und nimmt sie in den Dienst der Gilde auf.",al={"wer ist therzok","therzoks geschichte","npc therzok"}},{q="Warum schickt Kaplak mich zu ihm?",a="Kaplak hat Euer Geschick im Kampf und Euer Talent für Heimlichkeit und Täuschung erkannt. Da er weiß, dass die Shattered Hand fähige Halunken sucht, schickt er Euch mit der Bitte zu Therzok, Euch anzuwerben.",al={"warum zu therzok geschickt","kaplaks quest","warum nach orgrimmar gehen"}},{q="Was ist die Shattered Hand in Orgrimmar?",a="In Orgrimmar ist die Shattered Hand eine geheime Gilde von Auftragsmördern, Spionen und Dieben, die der Horde dienen. Sie übernehmen schwierige Aufgaben, die Thralls ehrenhafte Krieger nicht offen ausführen können.",al={"was ist die shattered hand","shattered hand orgrimmar","schurkengilde der horde"}},{q="Wo liegt die Kluft der Schatten?",a="Die Kluft der Schatten ist eine Höhle unter dem Zentrum von Orgrimmar. Dunkle Gänge führen vom Tal der Stärke und vom Drag zu ihr hinab. Sie schützt die Hexenmeister und Schurken der Stadt vor den prüfenden Blicken der Öffentlichkeit.",al={"wo ist die kluft der schatten","therzok finden","standort der kluft der schatten"}},{q="Was folgt nach dem Treffen mit Therzok?",a="Nachdem Ihr Therzok begrüßt habt, erklärt er Euch die Pflichten im Dienst der Shattered Hand. Dann erteilt er Euch Aufgaben, um Euer Können, Eure Heimlichkeit und Eure Treue zum Netzwerk zu prüfen.",al={"nächste quest","was will therzok","nach therzok"}},{q="Erhalten auch andere Klassen diese Quest?",a="Nein. Nur Schurken erhalten diese Vorladung, nachdem sie ein gewisses Maß an Erfahrung gesammelt haben. Sie markiert ihren Übergang von örtlichen Scharmützeln in das Spionagenetzwerk der Horde.",al={"auch für andere klassen","nur für schurken","schurkenquest"}}},fx={["89f659b0"]={q="Warum wählt Kaplak Euch für dieses Treffen aus?",a="Kaplak wurde ausdrücklich angewiesen, nach Personen Ausschau zu halten, die Eurer Beschreibung entsprechen. Es hat sich bis zur Gilde herumgesprochen, dass Ihr Euch im Kampf behaupten könnt und nicht davor zurückschreckt, bei Bedarf Heimlichkeit, Täuschung oder weniger ehrenhafte Mittel einzusetzen. Therzok hat Geschäfte im Sinn, die jemanden mit Euren spezifischen, flexiblen Talenten erfordern.",al={"warum ich kaplak","warum zu therzok schicken","warum hat kaplak mich gewählt"}}},fp="7,190,19.238.0,24.246.0,15.172.0,31.188.0,40.190.0,37.193.0,33.157.0,33.166.0"}
P.entries["quest:186"] = {n="Beherrschen der Tigerjagd",s="Bei Nesingwarys Expedition im nördlichen Schlingendorntal schickt Ajeck Rouack Euch auf die Jagd nach ausgewachsenen Tigern. Nachdem Ihr junge Pirscher besiegt habt, lässt sie Euch gegen zehn ausgewachsene Schlingendorn-Tiger antreten.",h="Bei Nesingwarys Expedition im nördlichen Schlingendorntal schickt Ajeck Rouack Euch auf die Jagd nach...",kw={"ajeck rouack","nesingwarys expedition","schlingendorn-tiger","schlingendorntal","beherrschen der tigerjagd"},sec={{t="Jagd auf ausgewachsene Katzen",b="Ajeck Rouack schickt Euch auf die Jagd nach zehn ausgewachsenen Schlingendorn-Tigern. Euer Erfolg gegen jüngere Raubtiere hat Euch zu einer härteren Prüfung in der Wildnis des Schlingendorntals geführt. Nach dieser Jagd warten größere Herausforderungen."}},faq={{q="Wer erteilt diesen Jagdauftrag?",a="Ajeck Rouack, eine Jägerin bei Nesingwarys Expedition im nördlichen Schlingendorntal, erteilt den Jagdauftrag.",al={"wer vergibt beherrschen der tigerjagd","ajeck rouack standort","wer vergibt diese quest"}},{q="Welche Bestien sollt Ihr jagen?",a="Ihr werdet ausgesandt, um im umliegenden Dschungel zehn ausgewachsene Schlingendorn-Tiger aufzuspüren und zu erlegen.",al={"welche tiger töten","welche katzen","beherrschen der tigerjagd ziele"}},{q="Wo steht diese Prüfung im Verlauf der Jagd?",a="Diese Jagd folgt auf Eure erste Prüfung im Beherrschen der Tigerjagd und führt zu einer dritten Stufe unter Ajeck Rouacks Anleitung.",al={"was kommt vor beherrschen der tigerjagd 2","was kommt als nächstes","beherrschen der tigerjagd questreihe"}}},fp="13,191,23.212.0,22.99.0,40.89.0,38.106.0"}
P.entries["quest:1860"] = {n="Gespräch mit Jennea",s="In Sturmwind kommen angehende Magier aus Goldhain zu Jennea Haubitz, nachdem sie die Grundausbildung im Wald von Elwynn hinter sich gelassen haben. Zaldimar Wefhellt schickt sie zu ihr.",h="In Sturmwind kommen angehende Magier aus Goldhain zu Jennea Haubitz, nachdem sie die Grundausbildung im Wald...",kw={"wald von elwynn","goldhain","jennea haubitz","das magierviertel","gespräch mit jennea","sturmwind","magiersanktum","zaldimar wefhellt"},ang={["class:Mage"]="Als Magier lasst Ihr die ländliche Zauberkunst in Goldhain hinter Euch und übernehmt offizielle Aufgaben bei den Hochmagiern im Magiersanktum von Sturmwind.",["faction:Alliance"]="Als Mitglied der Allianz verlasst Ihr Euch auf die arkane Wachsamkeit der Hauptstadt, die zum Schutz des Walds von Elwynn und von Sturmwind beiträgt."},sec={{t="Ein Ruf ins Magiersanktum",b="Im Magierviertel versammelt das Magiersanktum die ranghohen Magier des Königreichs zum Studium und zur Unterweisung in den arkanen Künsten. Sie koordinieren magische Angelegenheiten im ganzen Reich, und Eure Ausbildung hat nun ihren Platz in dieser umfassenderen Arbeit."},{t="Die Sicherheit des Königreichs",b="Jennea Haubitz betreut örtliche Aufgaben, darunter Berichte zur Sicherheit des Walds von Elwynn und von Sturmwind, sowie Eure Studien. Da sie einem neu eingetroffenen Lehrling große Geheimnisse nur vorsichtig anvertraut, nimmt sie Euren Bericht als Beginn Eures Dienstes für den Zauberorden entgegen."}},faq={{q="Wer schickt mich auf diese Quest?",a="Zaldimar Wefhellt, der Magierlehrer im Gasthaus \"Zur Höhle des Löwen\" in Goldhain, schickt Euch, sobald Eure arkanen Fähigkeiten weit genug fortgeschritten sind.",al={"questgeber","wer gibt die quest","zaldimar"}},{q="Wo finde ich Jennea Haubitz?",a="Jennea Haubitz befindet sich im Magiersanktum, im Zentrum des Magierviertels von Sturmwind.",al={"jennea haubitz standort","wo ist jennea","jennea finden"}},{q="Was ist das Magiersanktum?",a="Das Magiersanktum ist ein markanter magischer Turm im Magierviertel von Sturmwind. Die Magier und arkanen Gelehrten des Königreichs nutzen ihn als Akademie, Bibliothek und Stützpunkt.",al={"was ist das magiersanktum","magierturm sturmwind"}},{q="Warum schickt Zaldimar mich zu Jennea, statt sich selbst darum zu kümmern?",a="Zaldimar lehrt junge Magier in Goldhain die Grundlagen. Ranghöhere Gelehrte wie Jennea Haubitz kümmern sich von der Hauptstadt aus um größere regionale Bedrohungen und besondere Aufgaben, die das Reich betreffen.",al={"warum nach sturmwind","warum jennea"}},{q="Was geschieht, nachdem ich mich bei Jennea Haubitz gemeldet habe?",a="Jennea schickt Euch, um rätselhafte magische Anomalien rund um den Spiegelsee im Wald von Elwynn zu untersuchen.",al={"was kommt als nächstes","folgequest","nächster schritt"}},{q="Ist diese Quest für jede Klasse verfügbar?",a="Nein. Nur Magier durchlaufen diesen Übergangsritus von der Ausbildung im Dorf in die arkane Gemeinschaft von Sturmwind.",al={"auch für andere klassen","nur für magier","klassenvoraussetzung"}}},fx={["8f9ffa7f"]={q="Warum möchte Zaldimar Wefhellt, dass Ihr mit Jennea sprecht?",a="Zaldimar Wefhellt handelt aus Sorge um die Sicherheit sowohl von Sturmwind als auch vom Wald von Elwynn. Es ist eine dringende Angelegenheit aufgekommen, die die Aufmerksamkeit fähiger Magier erfordert. Anstatt sich direkt darum zu kümmern, verweist er vielversprechende Lehrlinge an Jennea Haubitz im Magiersanktum, die die Einzelheiten dieser heiklen Mission beaufsichtigt.",al={"zaldimar beweggrund","warum jennea aufsuchen","warum zu jennea schicken"}}},fp="17,156,30.230.0,27.284.0,27.129.0,31.89.0,29.173.0,67.196.0,46.97.1,37.98.0"}
P.entries["quest:1861"] = {n="Spiegelsee",s="Im Magierviertel von Sturmwind werden angehende Magier der Allianz ausgesandt, um den Spiegelsee auf magische Verunreinigungen zu prüfen. Jennea Haubitz schickt sie südwestlich der Stadttore, um eine Probe aus der Gischt des Wasserfalls zu nehmen.",h="Im Magierviertel von Sturmwind werden angehende Magier der Allianz ausgesandt, um den Spiegelsee auf magische...",kw={"arkane verunreinigung","wald von elwynn","jennea haubitz","leylinien","spiegelsee","wasserprobe","magiersanktum"},ang={["class:Mage"]="Als Magier geht Ihr vom Studium im Magiersanktum dazu über, arkane Phänomene in der Welt zu untersuchen. Diese Arbeit bringt Euch Euren ersten eigens für Magier bestimmten Stab oder eine Kugel für die Nebenhand ein.",["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr den Magiern des Magiersanktums helfen, Elwynns natürliche Ressourcen und das Herz des Königreichs zu schützen.",["race:Human"]="Als Mensch wisst Ihr, dass der Spiegelsee Elwynns Ackerland und Wasserläufe speist, weshalb seine Reinheit für die Bürger von Sturmwind von Bedeutung ist."},sec={{t="Leylinien und wandernde Strömungen",b="Azeroths arkane Strömungen wurden von Konflikten erschüttert, die mit der Öffnung des Dunklen Portals begannen und sich durch den Dritten Krieg bis zur Schlacht am Hyjal fortsetzten. Diese Erschütterungen rissen uralte Strömungen aus ihren stabilen Bahnen.\n\nIm Magiersanktum von Sturmwind beobachten Magier wie Jennea Haubitz die Veränderungen genau. Sie fürchten, dass verlagerte arkane Macht die Wildnis erreichen und die örtlichen Ökosysteme verderben könnte."},{t="Das Wasser prüfen",b="Unterhalb der Klippen südwestlich der Tore von Sturmwind liegt der Spiegelsee, ein natürliches Wasserreservoir, das von Gebirgswasserfällen gespeist wird. Das Umland ist auf sein Wasser angewiesen.\n\nJennea schickt angehende Magier mit einem Glasfläschchen zum Fuß des Wasserfalls, wo sie frische Gischt sammeln. Das Sanktum kann dann durch Hellsicht und Reagenzientests feststellen, ob wilde Magie in die öffentliche Wasserversorgung sickert."}},faq={{q="Warum möchte Jennea Haubitz eine Wasserprobe aus dem Spiegelsee?",a="Konflikte in ganz Azeroth haben die natürlichen Leyströmungen aufgerissen. Jennea Haubitz fürchtet, dass aufgewühlte arkane Energien das Grundwasser rund um Sturmwind erreichen und allen schaden könnten, die aus dem See trinken.",al={"warum wasser aus dem spiegelsee","jennea wasserprobe","wozu dient diese quest"}},{q="Wo genau liegt der Spiegelsee?",a="Der Spiegelsee liegt im Nordwesten des Waldes von Elwynn, an den hohen Klippen südwestlich der Haupttore von Sturmwind. Die Probe stammt aus dem Becken am Fuß seines Wasserfalls.",al={"wo liegt der spiegelsee","spiegelsee lage","spiegelsee finden"}},{q="Was geschieht, wenn das Wasser verunreinigt ist?",a="Jennea fürchtet, dass der längere Genuss magisch verunreinigten Wassers jenen schaden könnte, die auf den See angewiesen sind. Die genauen Auswirkungen sind unbekannt.",al={"ist das wasser vergiftet","was wenn magie im wasser ist","auswirkungen magischer verunreinigung"}},{q="Wer kann diese Mission übernehmen?",a="Angehende Magier der Allianz übernehmen diesen Auftrag als eine ihrer ersten Feldstudien für das Magiersanktum.",al={"wer bekommt die spiegelsee-quest","ist der spiegelsee nur für magier"}},{q="Führt diese Quest zu weiteren Untersuchungen?",a="Der erste unmittelbare Auftrag, der mit Jennea Haubitz' Ruf beginnt, endet hier. Er verschafft dem Lehrling sein erstes richtiges Magierutensil und begründet seine Pflicht, im ganzen Königreich nach magischen Störungen Ausschau zu halten.",al={"was kommt nach dem spiegelsee","spiegelsee-questreihe"}},{q="Was hat die magischen Strömungen ursprünglich aus dem Gleichgewicht gebracht?",a="Jennea führt die veränderten Strömungen auf die großen mystischen Auseinandersetzungen der Welt zurück, nennt aber keine bestimmte Schlacht und kein bestimmtes Ereignis.",al={"warum sind die leylinien beschädigt","bedeutung mystischer auseinandersetzungen","was hat die magie beschädigt"}}},fx={["66ca747e"]={q="Wofür ist die Probe des Spiegelseewassers gut?",a="Jennea Haubitz benötigt die Probe, um das Wasser des Mirror Lake auf magische Verunreinigung zu testen. Massive mystische Umwälzungen in ganz Azeroth haben arkane Ströme von ihren normalen Bahnen abgelenkt, und die Magier des Magierviertels befürchten, dass diese instabilen Energien direkt in die örtliche Wasserversorgung sickern. Die Untersuchung des Seewassers wird zeigen, ob diejenigen, die daraus trinken, Gefahr laufen, magisch korrumpiert zu werden.",al={"verwendung der probe des spiegelseewassers","warum wasserprobe holen","was bewirkt die probe"}}},fp="11,190,31.402.0,18.382.0,60.200.0,29.169.0,37.139.0,31.124.0,47.206.0,67.112.0"}
P.entries["quest:187"] = {n="Beherrschen der Tigerjagd",s="Bei Nesingwarys Expedition schickt Ajeck Rouack Euch auf die Jagd nach zehn älteren Schlingendorntigern. Ihr Tod wird Euer Können vor der letzten Prüfung beweisen.",h="Bei Nesingwarys Expedition schickt Ajeck Rouack Euch auf die Jagd nach zehn älteren Schlingendorntigern.",kw={"ajeck rouack","großwildjagd","älterer schlingendorntiger","nesingwary","schlingendorntal","beherrschen der tigerjagd"},sec={{t="Eine Prüfung des Könnens",b="Ajeck Rouack schickt Euch in die Wildnis, um zehn ältere Schlingendorntiger zu jagen. Er sagt, sie seien die am schwersten aufzuspürenden und die wildesten Raubkatzen, die es zu bezwingen gilt. Ihr Tod bereitet Euch auf eine letzte Prüfung vor. Danach verspricht er, Euch vor Meister Nesingwary zum Meister der Tigerjagd auszurufen."}},faq={{q="Wer erteilt diese Prüfung?",a="Ajeck Rouack erteilt die Prüfung im Lager von Nesingwarys Expedition im nördlichen Schlingendorntal.",al={"wer vergibt beherrschen der tigerjagd","ajeck rouack quest","questgeber"}},{q="Welche Beute verfolgt Ihr?",a="Ihr jagt zehn ältere Schlingendorntiger.",al={"was töten","welche tiger","ziele für beherrschen der tigerjagd"}},{q="Warum werden gerade ältere Schlingendorntiger ausgewählt?",a="Ajeck Rouack sagt, ältere Schlingendorntiger seien die am schwersten zu findenden und die wildesten Raubkatzen der Gegend, die es zu bezwingen gilt.",al={"warum ältere tiger","schwierigkeit älterer tiger"}},{q="Was kommt vor dieser Jagd?",a="Diese Jagd folgt auf die zweite Stufe von Ajeck Rouacks Reihe „Beherrschen der Tigerjagd“.",al={"vorherige quest","voraussetzung"}}},fp="13,146,15.280.0,23.94.0,29.47.0,47.113.0,28.74.0"}
P.entries["quest:1878"] = {n="Wasserbeutelkopfgeld",s="In Gadgetzan heißt Leitungshahnmaschinist Luglunket Euch für fünf weitere Wastewander-Wasserbeutel wieder willkommen. Ein Hilfspaket mit Eurem Namen darauf wartet auf Euch.",h="In Gadgetzan heißt Leitungshahnmaschinist Luglunket Euch für fünf weitere Wastewander-Wasserbeutel wieder...",kw={"hilfspaket","leitungshahnmaschinist luglunket","tanaris","wastewander-wasserbeutel","wasserbeutelkopfgeld"},sec={{t="Wieder zurück",b="Luglunket heißt Euch wieder willkommen und bittet um fünf weitere Wastewander-Wasserbeutel. Ein Hilfspaket mit Eurem Namen darauf ist bereits beiseitegelegt."},{t="Bringt weiter Nachschub",b="Luglunket freut sich über die zurückgeholten Beutel. Jeder einzelne hält das Unheil für alle ein Stück weiter fern. Luglunket verspricht, Euch für jeweils fünf Beutel, die Ihr bringt, angemessen zu belohnen."}},faq={{q="Wer bietet dieses Kopfgeld an?",a="Luglunket, der Leitungshahnmaschinist in Gadgetzan, bietet das Kopfgeld an.",al={"wer vergibt wasserbeutelkopfgeld","luglunket quest","wer nimmt wasserbeutel an"}},{q="Wie viele Wasserbeutel werden benötigt?",a="Ihr braucht fünf Wastewander-Wasserbeutel, genauso viele wie zuvor.",al={"wie viele beutel","anzahl wasserbeutel","beutel pro abgabe"}},{q="Was hat Luglunket bereit?",a="Luglunket hat ein Hilfspaket unter Eurem Namen beiseitegelegt.",al={"was ist das hilfspaket","was bekomme ich"}},{q="Was kommt vor diesem Schritt?",a="Dies folgt auf das frühere Wasserbeutelkopfgeld, bei dem Ihr Luglunket zum ersten Mal Beutel gebracht habt.",al={"vorherige quest","was zuerst tun"}}},fp="18,141,10.135.0,16.168.1,28.63.0,34.67.0,31.55.0,28.89.0"}
P.entries["quest:1879"] = {n="Gespräch mit Bink",s="Magis Funkelmantel schickt Euch zu Bink in Eisenschmiede, deren Studien einen Arkanspezialisten erfordern.",h="Magis Funkelmantel schickt Euch zu Bink in Eisenschmiede, deren Studien einen Arkanspezialisten erfordern.",kw={"bink","dun morogh","hall of mysteries","eisenschmiede","magier","magis funkelmantel","mystic ward"},ang={["class:Mage"]="Als Magier verlasst Ihr die Grundausbildung im Tal und wendet Euch den umfassenderen Aufgaben von Eisenschmiedes arkanen Gelehrten zu.",["faction:Alliance"]="Als Mitglied der Allianz seht Ihr, wie gnomischer Intellekt und zwergische Gastfreundschaft beim Studium in der Hall of Mysteries zusammenfinden.",["race:Gnome"]="Als Gnom erlebt Ihr, wie Bink und Magis Funkelmantel nach dem Verlust Gnomeregans die gnomische Arkantradition in Eisenschmiedes gastlichen Hallen fortführen."},sec={{t="Der Ruf einer Kollegin",b="Bink sucht jemanden, der Magie wirken und ihre Arbeit unterstützen kann. Nahe Kharanos schickt Magis Funkelmantel Lehrlinge, die ihren ersten Übungen entwachsen sind, um Binks Ruf zu folgen."},{t="Die Hall of Mysteries",b="In Eisenschmiedes Mystic Ward betreibt Bink ihre Studien in der Hall of Mysteries. Gelehrte, Priester und Arkanisten kommen dort zusammen. Sie mustert jeden eintreffenden Lehrling genau, denn rohes Potenzial ohne Disziplin kann einen Zauberwirker bei arkaner Arbeit gefährlich machen."}},faq={{q="Wer vergibt diese Quest?",a="Magis Funkelmantel schickt angehende Magier der Allianz aus Dun Morogh zu Bink, sobald sie über ihre erste Ausbildung hinausgewachsen sind.",al={"questgeber","wo beginnen","wer vergibt gespräch mit bink"}},{q="Wo finde ich Bink?",a="Bink befindet sich in der Hall of Mysteries, im Mystic Ward im Norden von Eisenschmiede.",al={"binks standort","wo ist bink","bink finden"}},{q="Warum sucht Bink nur einen Magier?",a="Bink erforscht arkane Energien und empfindliche Überwachungsgeräte. Sie glaubt, dass Nichtmagier den damit verbundenen magischen Feinheiten und Gefahren nicht gewachsen sind.",al={"warum nur magier","magier als voraussetzung","bink will nur magier"}},{q="Was geschieht nach dem Treffen mit Bink?",a="Nachdem Bink Euch begrüßt und Eure Fähigkeiten eingeschätzt hat, bittet sie Euch um Hilfe bei ihren Forschungen, die mit „Magitastischer Gizmonitor“ weitergehen.",al={"nächste quest","binks folgequest","was kommt nach gespräch mit bink"}},{q="Ist diese Quest auch für andere Klassen als Magier verfügbar?",a="Nein. Binks Ruf richtet sich an Magier und führt sie von der örtlichen Anfängerausbildung zu spezialisierter Arbeit in der Hauptstadt.",al={"können andere klassen das machen","ist das nur für magier","magierspezifisch"}},{q="Was ist die Hall of Mysteries?",a="Die Hall of Mysteries ist Eisenschmiedes Zentrum für arkane und heilige Studien. Die dortigen Lehrer, Gelehrten und Forscher vertreten die magischen Künste der Zwerge und Gnome.",al={"eisenschmiede hall of mysteries","was ist die hall of mysteries"}}},fx={["96ce9827"]={q="Warum schickt Magis Funkelmantel Euch zu Bink?",a="Magis Funkelmantel ist ein Gnom-Magierlehrer, der in Kharanos stationiert ist und als Mentor für aufstrebende Zauberwirker dient. Seine Kollegin in Eisenschmiede, Bink, schickte ausdrücklich eine Nachricht, in der sie einen fähigen Magier für ein wichtiges Unterfangen anforderte. Da Magis Eure wachsende Beherrschung der arkanen Künste erkennt, schickt er Euch in die Zwergenhauptstadt, damit Ihr ihrem Ruf folgen und Eure magische Ausbildung fortsetzen könnt.",al={"warum schickt magis euch","motiv von magis funkelmantel","warum mit bink sprechen"}}},fp="15,94,21.170.0,21.245.0,21.122.0,22.75.0,31.143.0,32.134.0,52.104.0,30.162.0"}
P.entries["quest:188"] = {n="Beherrschen der Tigerjagd",s="Bei Nesingwarys Expedition schickt Euch Ajeck Rouack auf die Jagd nach einer Tigerin, die seine Jäger seit Wochen verfolgen. Sin'Dall wartet im nördlichen Schlingendorntal, und ihre Tatze wird beweisen, dass die Jagd vollendet ist.",h="Bei Nesingwarys Expedition schickt Euch Ajeck Rouack auf die Jagd nach einer Tigerin, die seine Jäger seit...",kw={"ajeck rouack","master tiger hunter","nesingwarys expedition","tatze von sin'dall","sin'dall","schlingendorntal","beherrschen der tigerjagd"},sec={{t="Die letzte Tigerin",b="Bei Nesingwarys Expedition schickt Euch Ajeck Rouack nach Euren früheren Prüfungen gegen die Tiger des Schlingendorntals auf eine letzte Jagd. Seine Jäger verfolgen Sin'Dall seit Wochen durch den Dschungel. Findet die schwer aufzuspürende Tigerin, tötet sie und bringt ihre Tatze als Beweis zurück."},{t="Meister der Tigerjagd",b="Wenn Ihr mit Sin'Dalls Tatze in Nesingwarys Lager zurückkehrt, erkennt Ajeck Rouack Euer Geschick im Fährtenlesen an. Er ernennt Euch zu einem wahren Master Tiger Hunter."}},faq={{q="Wer bietet diese Jagd an?",a="Ajeck Rouack, ein erfahrener Jäger bei Nesingwarys Expedition im nördlichen Schlingendorntal, bietet Euch diese letzte Jagd an.",al={"questgeber","wer vergibt beherrschen der tigerjagd","ajeck rouack standort"}},{q="Was ist Sin'Dall?",a="Sin'Dall ist eine schwer aufzuspürende Tigerin, die von den Jägern von Nesingwarys Expedition seit Wochen durch die Dschungel des Schlingendorntals verfolgt wird.",al={"was ist sindall","sindall hintergrundgeschichte","wer ist sin dall"}},{q="Welchen Beweis verlangt Ajeck Rouack?",a="Ajeck Rouack bittet Euch, mit Sin'Dalls Tatze als Beweis dafür zurückzukehren, dass Ihr die Tigerin bezwungen habt.",al={"was muss zurückgebracht werden","beherrschen der tigerjagd beweis","tatze von sindall"}},{q="Was geht dieser Jagd voraus?",a="Diese Jagd ist der vierte und letzte Schritt in Ajeck Rouacks Reihe. Sie folgt auf die dritte Prüfung im Beherrschen der Tigerjagd im nördlichen Schlingendorntal.",al={"voraussetzungen","beherrschen der tigerjagd questreihe","vorherige quest"}}},fp="13,188,15.256.0,19.146.1,21.118.0,17.131.0,37.87.0,24.137.0"}
P.entries["quest:1881"] = {n="Gespräch mit Anastasia",s="In Unterstadt schickt Cain Feuerlied einen vielversprechenden Magier der Verlassenen zu Anastasia Hirschbrunn. Ihre Vorladung ruft Euch ins Magieviertel zur praktischen Arbeit unter den Magiern der Verlassenen, bevor Feldforschungen in Tirisfal anstehen.",h="In Unterstadt schickt Cain Feuerlied einen vielversprechenden Magier der Verlassenen zu Anastasia Hirschbrunn.",kw={"anastasia hirschbrunn","balnirs bauernhof","cain feuerlied","magierquest","magieviertel","unterstadt"},ang={["class:Mage"]="Als Magier geht Ihr von der arkanen Grundausbildung zum aktiven Dienst für die Magier von Unterstadt über.",["race:Undead"]="Als Arkanist der Verlassenen könnt Ihr Lordaerons geistiges Erbe gegen die Gefahren einsetzen, denen es heute gegenübersteht."},sec={{t="Ein Ruf ins Magieviertel",b="Cain Feuerlied bildet junge Magier der Verlassenen in Brill aus. Erkennt er vielversprechende Anlagen bei einem Schüler, schickt er ihn nach Unterstadt. Dort studieren die Magier der Verlassenen die arkanen Künste und planen die Verteidigung in ganz Lordaeron. Cain entscheidet, welche Schüler bereit sind, erfahreneren Zauberkundigen zu dienen. Wer wahres Talent besitzt, wird zu Anastasia Hirschbrunn geschickt, die fähige Helfer im Feld braucht."},{t="Anastasia Hirschbrunns Ehrgeiz",b="Anastasia Hirschbrunn gehört zu den angesehenen Magierlehrern von Unterstadt. Sie schickt vielversprechende Schüler zur praktischen Arbeit für die Interessen und das Gebiet der Verlassenen, statt sie in Sicherheit Zauberformeln studieren zu lassen. Ihrem Ruf zu folgen, beginnt Euren Dienst unter den Magiern der Verlassenen und Eure praktische magische Arbeit in den Jahren nach der Geißel."}},faq={{q="Wer schickt Euch zu Anastasia Hirschbrunn?",a="Cain Feuerlied, Euer Magierlehrer der Verlassenen in Brill, schickt Euch zu Anastasia Hirschbrunn, sobald er Euer arkanes Talent für anspruchsvollere Arbeit in Unterstadt bereit hält.",al={"wer vergibt gespräch mit anastasia","questgeber gespräch mit anastasia","cain feuerlied vorladung"}},{q="Wo ist Anastasia Hirschbrunn zu finden?",a="Anastasia Hirschbrunn befindet sich im Magieviertel von Unterstadt, wo sie Verlassene in den arkanen Künsten unterweist.",al={"wo ist anastasia hirschbrunn","anastasia hirschbrunn aufenthaltsort","anastasia finden"}},{q="Welchen Zweck hat diese Vorladung?",a="Anastasia sucht einen fähigen Zauberwirker für praktische Arbeit jenseits der Stadtmauern. Die Feldeinsätze beginnen in Tirisfal mit Aufgaben wie der Untersuchung von Balnirs Bauernhof.",al={"warum braucht sie mich","gespräch mit anastasia zweck","was braucht anastasia"}},{q="Welche Quest folgt auf Gespräch mit Anastasia?",a="Nachdem Ihr Euch bei Anastasia gemeldet habt, schickt sie Euch zu Balnirs Bauernhof im Osten von Tirisfal, um Löwenmäulchen aus seinem Garten zu sammeln.",al={"welche quest kommt als nächstes","nächste quest nach gespräch mit anastasia","gespräch mit anastasia folgequest"}},{q="Ist diese Quest auf bestimmte Klassen beschränkt?",a="Ja. Diese Vorladung richtet sich an Magier der Verlassenen und markiert einen Schritt ihrer Klassenausbildung, wenn sie um den zehnten Zirkel erste Fertigkeiten erlangt haben.",al={"ist diese quest nur für magier","wer kann gespräch mit anastasia machen","klassenvoraussetzung"}},{q="Warum unterhalten die Magier der Verlassenen eigene Quartiere in Unterstadt?",a="Das Magieviertel bietet Arkanisten, Hexenmeistern und Forschern der Verlassenen einen Ort zum Studieren und Zaubern, abseits der Quartiere für körperliche Belange. Dort, unter Lordaeron, führen sie Traditionen aus der Zeit vor dem Dritten Krieg fort.",al={"warum magieviertel","magier der verlassenen unterstadt"}}},fx={["34129032"]={q="Warum schickt Cain Feuerlied Euch zu Anastasia Hirschbrunn?",a="Cain Feuerlied dient als Ausbilder für angehende Verlassene-Magier in Brill. Sobald Ihr ausreichende Fertigkeiten in den arkanen Künsten unter Beweis gestellt habt, ist es seine Aufgabe, vielversprechende Zauberwirker an Anastasia Hirschbrunn im Magieviertel der Unterstadt zu verweisen. Hirschbrunn koordiniert größere Unternehmungen für den magischen Orden der Verlassenen, und Cain stellt sicher, dass ihre Reihen mit fähigen Praktizierenden aufgefüllt werden, die bereit für den Dienst sind.",al={"warum schickt cain euch","motiv von cain feuerlied","warum anastasia hirschbrunn besuchen"}}},fp="20,225,27.367.0,29.353.0,47.157.0,38.120.0,36.172.0,40.134.0,41.131.0,67.206.0"}
P.entries["quest:1882"] = {n="Balnirs Bauernhof",s="Im Osten von Tirisfal können Löwenmäulchen auf Balnirs Bauernhof zeigen, wie weit die Verderbnis der Geißel reicht. Anastasia Hirschbrunn schickt junge Magier der Verlassenen los, um die Blumen zur Untersuchung in Unterstadt zu sammeln.",h="Im Osten von Tirisfal können Löwenmäulchen auf Balnirs Bauernhof zeigen, wie weit die Verderbnis der Geißel...",kw={"anastasia","balnir","bauernhof","hirschbrunn","magier","pestländer","löwenmäulchen","tirisfal","unterstadt"},ang={["class:Mage"]="Als Magier lernt Ihr früh, dass arkane Studien helfen können, fremde magische Verderbnis zu erkennen und abzuwehren.",["profession:Herbalism"]="Als Kräuterkundiger seht Ihr, wie eine Pflanze Spuren magischer Verunreinigung aufnehmen und deren Anwesenheit offenbaren kann.",["race:Undead"]="Als Verlassener müsst Ihr die Geißel von Tirisfals Grenzen fernhalten, um Euer Überleben und Eure Souveränität zu schützen."},sec={{t="Ein magisches Barometer",b="Magier der Verlassenen überwachen die Grenzgebiete auf magische Verderbnis. Anastasia Hirschbrunn schickt unerfahrene Zauberwirker zu Balnirs Bauernhof im Osten von Tirisfal, um Löwenmäulchen aus seinen Gärten zu sammeln. Die Blumen nehmen magische Energien aus dem Boden und der Luft auf. Arkanforscher in Unterstadt untersuchen sie, um festzustellen, ob die Verderbnis aus der Domäne des Lichkönigs Tirisfal erreicht hat."},{t="Die östliche Grenze",b="Balnirs Bauernhof liegt am Rand der Lichtungen, nahe der verseuchten Wildnis der Westlichen Pestländer. Die Verlassenen wissen, dass die Seuche des Lichkönigs das Land verfaulen lässt und die Verderbnis der Geißel ihre Grenzen und Sicherheit bedroht. Obwohl die Verlassenen selbst dunkle Künste wirken, plant Anastasia, die Löwenmäulchen den Apothekern zur Untersuchung zu übergeben. Gemeinsam können Magier und Alchemisten die Gefahr untersuchen und helfen, das zurückgewonnene Herzland von Lordaeron zu verteidigen."}},faq={{q="Warum will Anastasia Hirschbrunn ausgerechnet Löwenmäulchen?",a="Balnirlöwenmäulchen reagieren empfindlich auf magische Kräfte und nehmen Energie aus der Erde und der Luft auf. Ihre Untersuchung kann den Magiern der Verlassenen zeigen, ob die arkane und nekromantische Verderbnis der Pestländer Tirisfal erreicht.",al={"warum löwenmäulchen","zweck der balnirlöwenmäulchen","wozu dienen löwenmäulchen"}},{q="Wo liegt Balnirs Bauernhof?",a="Balnirs Bauernhof liegt im Osten von Tirisfal, nahe der Grenze zu den verseuchten Westlichen Pestländern. Löwenmäulchen wachsen in Beeten und Gärten rund um seine verfallenen Hofgebäude.",al={"lage von balnirs bauernhof","wo ist balnirs bauernhof","balnirs bauernhof finden"}},{q="Wer ist Anastasia Hirschbrunn?",a="Anastasia Hirschbrunn ist eine Magierin und Lehrerin der Verlassenen im Magieviertel von Unterstadt. Sie lehrt frisch erweckte untote Zauberwirker Disziplin, arkanes Gleichgewicht und die Verteidigung ihrer Grenzen gegen rivalisierende Mächte.",al={"geschichte von anastasia hirschbrunn","wer ist anastasia"}},{q="Warum wollen die Magier der Verlassenen die Seuche aufhalten?",a="Die Verlassenen betrachten die ansteckende Seuchenmagie des Lichkönigs als unkontrolliert, auch wenn sie selbst mit eigenen Seuchen und Formen der Verderbnis experimentieren. Ungehindert könnte die Geißel Tirisfal verschlingen und die Unabhängigkeit der Verlassenen bedrohen.",al={"warum die seuche aufhalten","hassen verlassene die seuche"}},{q="Was geschieht mit den Blumen, nachdem Ihr sie gesammelt habt?",a="Anastasia plant, die Löwenmäulchen den Apothekern von Unterstadt zu übergeben. Alchemisten und Magier werden sie untersuchen, um festzustellen, wie tief die Geißel den Boden und die Pflanzen verdorben hat.",al={"was macht anastasia mit den blumen","wer bekommt die löwenmäulchen"}},{q="Ist diese Quest nur für Magier?",a="Ja. Anastasia bietet diese Prüfung nur jungen Magiern der Verlassenen an, die ihre ersten Lektionen in Todesend abgeschlossen und die Hauptstadt erreicht haben, um ihr Verständnis der arkanen Theorie zu beweisen.",al={"balnirs bauernhof nur für magier","magierklassenquest"}}},fp="20,208,19.379.0,18.456.0,58.214.0,38.182.0,26.203.0,53.231.0,51.176.0,34.176.0"}
P.entries["quest:1883"] = {n="Speak with Un'thuwa",s="Un'thuwa, der Stammesmagier von Sen'jin, spürt eine Störung in Durotars magischen Strömungen und bittet Euch, mit ihm zu sprechen. Er hofft, dass Eure Hilfe ihm dabei hilft, sie zu verstehen.",h="Un'thuwa, der Stammesmagier von Sen'jin, spürt eine Störung in Durotars magischen Strömungen und bittet Euch...",kw={"störung","durotar","magische strömungen","sen'jin","stammesmagier","un'thuwa"},ang={["class:Mage"]="Als Magier sollt Ihr mit Un'thuwa sprechen, dem Stammesmagier, der eine Störung in Durotars magischen Strömungen spürt."},sec={{t="Ein Hilferuf",b="In Sen'jin bittet Un'thuwa Euch, mit ihm zu sprechen. Der Stammesmagier spürt eine Störung in Durotars magischen Strömungen und sucht Hilfe. Was er herausfinden kann, hängt vielleicht von Eurer Hilfe ab."}},faq={{q="Wer ist Un'thuwa?",a="Un'thuwa ist der Stammesmagier von Sen'jin.",al={"wer ist un'thuwa","stammesmagier von sen'jin"}},{q="Was spürt Un'thuwa?",a="Un'thuwa bemerkt eine Störung in Durotars magischen Strömungen.",al={"magische störung","durotars magie"}},{q="Warum möchte Un'thuwa mit mir sprechen?",a="Un'thuwa bittet Euch um Hilfe bei der Störung, die er in Durotars magischen Strömungen spürt.",al={"warum mit un'thuwa sprechen","un'thuwa helfen"}},{q="Was könnte geschehen, wenn ich Un'thuwa helfe?",a="Un'thuwa sagt, dass Euch mit der Zeit vielleicht weitere Geheimnisse offenbart werden.",al={"was geschieht bei hilfe","un'thuwas geheimnisse"}}},fp="19,168,14.179.0,16.47.0,25.59.0,40.86.0,38.66.0"}
P.entries["quest:1884"] = {n="Jujuhaufen",s="Auf den Echoinseln bittet Un'thuwa Euch, Zalazanes Ju-Ju-Haufen zu zerstören. Ihre Verderbnis bedroht den Fluss der Magie in Durotar.",h="Auf den Echoinseln bittet Un'thuwa Euch, Zalazanes Ju-Ju-Haufen zu zerstören.",kw={"durotar","die echoinseln","ju-ju-haufen","magie","sen'jin","verdorbene fetische","un'thuwa","zalazane"},ang={["faction:Horde"]="Un'thuwa nennt dies eine Tat für Euer Volk und sagt, Ihr habt Euch der Klassen der Horde würdig erwiesen."},sec={{t="Verdorbene Haufen",b="Von Sen'jin aus bittet Un'thuwa Euch, die Haufen zu zerstören, die Zalazane zwischen seinen Hütten auf der Hauptinsel der Echoinseln errichtet hat. Die verdorbenen Fetische verderben die Tierwelt und stärken Hexenmeister und infernalische Kreaturen. Bleiben sie unbehelligt, könnten sie den Fluss der Magie in Durotar für immer verändern."},{t="Un'thuwas Gespür",b="Un'thuwa spürt, dass die Haufen zerstört wurden. Mit der Zeit und etwas Glück, glaubt sie, wird Durotars Magie wieder normal fließen. Sie lobt Eure Tat für Euer Volk und sagt, Ihr habt Euch der Klassen der Horde würdig erwiesen."}},faq={{q="Wer hat die Ju-Ju-Haufen errichtet?",a="Zalazane, ein Hexenmeister der Echoinseln, hat die verdorbenen Haufen zwischen seinen Hütten auf der Hauptinsel errichtet.",al={"wer hat die haufen errichtet","zalazane haufen","ju-ju ursprung"}},{q="Was bewirken die Haufen?",a="Die Haufen verderben die Tierwelt und stärken Hexenmeister und infernalische Kreaturen.",al={"was sind ju-ju-haufen","wirkung der haufen","warum ju-ju zerstören"}},{q="Wo sind die Ju-Ju-Haufen?",a="Zalazane hat sie zwischen seinen Hütten auf der Hauptinsel der Echoinseln errichtet.",al={"wo sind die haufen","echoinseln haufen","ju-ju fundort"}},{q="Wer bittet mich, sie zu zerstören?",a="Un'thuwa in Sen'jin bittet Euch, die Ju-Ju-Haufen zu zerstören.",al={"wer gibt den auftrag","unthuwas bitte","wer will die haufen beseitigen"}},{q="Warum ist Durotars Magie hier von Bedeutung?",a="Die Haufen stören den normalen Fluss der Magie in Durotar. Wenn sie bestehen bleiben, könnte sich dieser Fluss für immer verändern.",al={"fluss der magie","durotars magie","warum ist magie wichtig"}}},fp="11,123,13.261.0,16.225.1,27.96.0,21.74.0,26.58.0,28.64.0,37.95.0"}
P.entries["quest:1885"] = {n="Mennet Carkad",s="In Unterstadt schickt Euch Marion Call zu Mennet Carkad, um Euch bei ihm zu melden. Tief im Schurkenviertel prüft er vielversprechende Agenten für die Todespirscher.",h="In Unterstadt schickt Euch Marion Call zu Mennet Carkad, um Euch bei ihm zu melden.",kw={"assassine","deathstalkers","schurke der verlassenen","marion call","mennet carkad","schurkenviertel","unterstadt"},ang={["class:Rogue"]="Als Schurke folgt Ihr einer Vorladung, die Euren Übergang vom unerprobten Beutelschneider zum anerkannten Deathstalker-Agenten markiert, einem Teil des elitären Schattennetzwerks der Verlassenen.",["race:Undead"]="Als Untoter wisst Ihr, dass die Todespirscher helfen, die Verlassenen am Leben zu halten. Sie jagen scharlachrote Fanatiker und Überreste der Geißel und schützen Königin Sylvanas vor verborgenen Bedrohungen."},sec={{t="Ein Ruf aus den Schatten",b="Marion Call überbringt Euch eine Vorladung von Mennet Carkad. In Unterstadt werden höhere Anführer auf verdeckte Agenten aufmerksam, und Marion überbringt die Nachricht, wenn ein Späher oder Assassine sich melden soll. Der Geheimdienst der Verlassenen ist für seine tödliche Arbeit gefürchtet. Seine Befehle zu ignorieren, ist keine wirkliche Option."},{t="Aufnahme bei den Deathstalkers",b="Mennet Carkad wartet im Schurkenviertel, wo er Rekruten beobachtet und ihre Einsatzbereitschaft beurteilt. Wer seinem Ruf folgt, muss Prüfungen zur Aufnahme bei den Todespirschern bestehen, dem gefürchteten Spionage- und Attentatszweig der Verlassenen. Wer der Dunklen Fürstin aus den Schatten heraus dienen will, muss zuerst gehorchen."}},faq={{q="Wer ist Mennet Carkad?",a="Mennet Carkad bildet Schurken aus und beaufsichtigt die Todespirscher im Schurkenviertel von Unterstadt. Er beobachtet vielversprechende verdeckte Agenten und vergibt wichtige Aufträge für die Führung der Verlassenen.",al={"mennet carkad hintergrund","wer ist carkad"}},{q="Was geschieht, wenn jemand Mennet Carkads Vorladung ignoriert?",a="Marion Call warnt Euch davor, zu fragen, was mit jenen geschehen ist, die Carkads Ruf ignoriert haben. Ihr genaues Schicksal erklärt sie nicht.",al={"carkad ignorieren","was geschieht beim ignorieren der vorladung"}},{q="Wer sind die Todespirscher?",a="Die Todespirscher sind ein Eliteorden aus Schurken, Spionen und Assassinen, die den Verlassenen dienen. Aus den Schatten von Unterstadt heraus beseitigen sie hochrangige Ziele, sammeln Informationen und verteidigen Lordaeron gegen Feinde wie den Scharlachroten Kreuzzug und die Geißel.",al={"deathstalker hintergrund","was sind die deathstalkers"}},{q="Wo finde ich Mennet Carkad?",a="Ihr findet Mennet Carkad im Schurkenviertel von Unterstadt, zwischen verdeckten Agenten, Ausbildern und Vorräten für das Handwerk der Schatten.",al={"carkad aufenthaltsort","wo ist mennet carkad"}},{q="Wer vergibt die Quest, Mennet Carkad aufzusuchen?",a="Marion Call schickt Euch aus der Taverne Zur Galgenschlinge in Brill los, um Mennet Carkad zu finden. Sie hat Eure wachsenden Fähigkeiten bemerkt und warnt Euch, dass Carkad unverzüglichen Gehorsam erwartet.",al={"wer startet diese quest","marion call quest"}},{q="Was folgt, nachdem ich mich bei Mennet Carkad gemeldet habe?",a="Wenn Ihr Euch bei Mennet Carkad meldet, führt Euch das direkt in den Dienst der Todespirscher. Eure ersten Pflichten sollen Eure Gerissenheit und Eure Treue zur Sache der Verlassenen beweisen.",al={"nächste quest nach carkad","was will carkad"}}},fx={f971228d={q="Warum schickt Euch Marion Call zu Mennet Carkad?",a="Marion Call sagt, dass Mennet Carkad auf Euch aufmerksam geworden ist und ein Treffen erwartet. Sie drängt Euch, seiner Vorladung Folge zu leisten, und gibt eine ominöse Warnung bezüglich derer ab, die sie ignoriert haben, ohne jedoch ihr Schicksal zu erklären.",al={"warum will marion call das erledigt haben","warum zu mennet carkad gehen","marion call beweggrund"}}},fp="13,149,26.283.0,25.290.0,21.185.0,56.121.0,26.257.0,31.123.0,46.161.0,44.163.0"}
P.entries["quest:1886"] = {n="Die Todespirscher",s="Mennet Carkad prüft angehende Todespirscher in Unterstadt, indem er sie auf einen reisenden Boten ansetzt. Nur die Skrupellosen finden einen Platz in Lord Varimathras' geheimem Orden.",h="Mennet Carkad prüft angehende Todespirscher in Unterstadt, indem er sie auf einen reisenden Boten ansetzt.",kw={"astor hadren","todespirscher","mennet carkad","schurkenviertel","silberwald","unterstadt","varimathras"},ang={["class:Rogue"]="Als Schurke der Verlassenen steigt Ihr mit dem Beitritt zu den Todespirschern in die höchsten Ränge des Staatsdienstes auf. Dort werden gewiefte Halunken zu eingeschworenen Werkzeugen von Varimathras und der Dark Lady.",["faction:Horde"]="Als Mitglied der Horde wisst Ihr womöglich nicht, wie sehr die Todespirscher im Verborgenen wirken. Sie unterhalten unverzichtbare Informationsnetze, während die südlichen Verbündeten der Horde von den zwielichtigeren inneren Angelegenheiten der Verlassenen weitgehend nichts ahnen.",["race:Undead"]="Als Untoter seht Ihr, wie die Todespirscher Lordaerons innere Sicherheit mit eisernem Griff durchsetzen. Sie halten nach Feinden außerhalb der Reihen der Verlassenen Ausschau und behalten mögliche Verräter im Inneren misstrauisch im Auge."},sec={{t="Eine Prüfung im Schatten",b="Im Schurkenviertel stellt Mennet Carkad jeden auf die Probe, der einen Platz unter den Todespirschern sucht. Sie dienen Varimathras als Geheimpolizei und Eliteassassinen der Verlassenen. Ein angehender Agent muss List und Diskretion zeigen und dann beweisen, dass er bereit ist, eine Zielperson auszuschalten. Carkad will die Schwachen und all jene abweisen, die zu viele Skrupel plagen."},{t="Das Abfangen",b="Astor Hadren trägt einen Brief auf der Straße zwischen Unterstadt und dem Silberwald bei sich. Carkad überlässt Euch das Vorgehen. Um Hadrens persönliches Empfehlungsschreiben zu erlangen, müsst Ihr ihn abfangen und seine Papiere an Euch bringen. Dann können die Todespirscher Euch bei Andron an seiner Stelle ausgeben."}},faq={{q="Wer sind die Todespirscher?",a="Die Todespirscher sind der geheime Orden der Verlassenen und ihre Eliteeinheit für Heimlichkeit und Meuchelmord. Vom Schurkenviertel in Unterstadt aus sammeln sie Informationen, betreiben Spionage und führen geheime Hinrichtungen durch. Sie unterstehen Lord Varimathras.",al={"geschichte der todespirscher","was sind todespirscher","untote schurken"}},{q="Wer ist Mennet Carkad?",a="Mennet Carkad ist ein Verbindungsmann der Todespirscher im Schurkenviertel von Unterstadt. Er beaufsichtigt die ersten Prüfungen und erprobt Rekruten, die in die geheimen Reihen aufgenommen werden wollen.",al={"mennet carkads rolle","wer vergibt die quest"}},{q="Warum braucht Mennet Astor Hadrens Brief?",a="Astor Hadrens Empfehlungsschreiben erlaubt es einem neuen Agenten, seinen Platz einzunehmen. Die Todespirscher können damit Andron täuschen.",al={"astor hadrens brief","warum den boten abfangen","astors empfehlungsschreiben"}},{q="Wo ist Astor Hadren unterwegs?",a="Astor Hadren reist auf der Straße zwischen Unterstadt und dem Silberwald und befördert dabei Briefe für seine Kontakte.",al={"astor hadrens route","astor hadrens aufenthaltsort","wo ist astor"}},{q="Wer ist Lord Varimathras?",a="Lord Varimathras ist ein Schreckenslord der Nathrezim, der sich mit Königin Sylvanas Windläufer verbündete, um seine eigene Existenz zu sichern. Vom Königsviertel aus beaufsichtigt er die Sicherheit, die Verteidigung und die Schurkenoperationen von Unterstadt.",al={"varimathras' rolle","schreckenslord in unterstadt"}},{q="Was folgt auf diese Prüfung?",a="Wer die Prüfung besteht, beweist seine Befähigung als Agent. Darauf folgt ein geheimer Auftrag unter falscher Identität: Astors Papiere überbringen und Androns Geschäfte unterwandern.",al={"what comes next","fortsetzung der todespirscher-questreihe"}}},fx={["1398690a"]={q="Warum will Mennet Carkad, dass dies erledigt wird?",a="Mennet Carkad leitet eine Infiltrationsoperation, bei der es darauf ankommt, Nachrichten abzufangen, die für einen Kontaktmann namens Andron bestimmt sind. Durch den Diebstahl von Astor Hadrens Brief sichert Mennet sich die Beglaubigungsschreiben, die benötigt werden, um einen Agenten unbemerkt in das Vertrauen von Andron einzuschleusen.",al={"warum benötigt mennet das","mennet carkads beweggrund","warum den brief stehlen"}},["763d70d5"]={q="Wer ist Astor Hadren?",a="Astor Hadren ist ein Kurier, der zwischen dem Silberwald und der Unterstadt unterwegs ist. Er trägt ein Empfehlungsschreiben bei sich, das für einen Kontaktmann namens Andron bestimmt ist, ohne zu ahnen, dass The Todespirscher es für ihre eigenen verdeckten Machenschaften auf seine Korrespondenz abgesehen haben.",al={"wer ist hadren","astor hadren","astor hadren als ziel"}},f8c6b26b={q="Warum schickt Mennet Carkad Euch anstelle eines etablierten Agenten?",a="Ihr versucht, Euch als würdig zu erweisen, den The Todespirscher beizutreten, den Elite-Schurken im Dienste von Lord Varimathras. Mennet setzt gezielt aufstrebende Rekruten für gefährliche, entbehrliche Feldprüfungen ein, um zu sehen, ob sie über die Gerissenheit und Tödlichkeit verfügen, die für den Orden erforderlich sind.",al={"warum ich deathstalkers","warum schickt mich mennet","warum keinen existierenden deathstalker verwenden"}}},fp="17,175,21.348.0,16.280.1,26.245.0,21.152.0,43.122.0,31.116.0,24.207.0,30.155.1"}
P.entries["quest:189"] = {n="Ohren der Bloodscalp",s="In Beutebucht bieten Ohren der Bloodscalp Kebok eine Antwort auf die wachsenden Verluste. Er bezahlt für den Beweis einer Tötung, nachdem Zusammenstöße mit dem Stamm der Bloodscalp ihn Wachen und Agenten gekostet haben.",h="In Beutebucht bieten Ohren der Bloodscalp Kebok eine Antwort auf die wachsenden Verluste.",kw={"bloodscalp","beutebucht","ohren","kebok","revilgaz","schlingendorntal","troll"},sec={{t="Steigende Kosten",b="Im Schlingendorntal töten Bloodscalp-Trolle Keboks Agenten und Wachen. Viele seiner besten Wachen sind bei Scharmützeln im Dschungel gefallen. Die steigenden Kosten lassen ihn besorgt darüber nachdenken, wie er sie Baron Revilgaz erklären soll."},{t="Ein begrenztes Kopfgeld",b="Kebok bietet Reisenden Münzen an, wenn sie im Dschungel Bloodscalp-Trolle jagen. Er bittet Euch, fünfzehn abgetrennte Ohren als Beweis für die Tötungen zurückzubringen."}},faq={{q="Wer ist Kebok?",a="Kebok ist ein Goblin in Beutebucht, dessen Agenten und Wachen im Dschungel arbeiten. Er muss Baron Revilgaz für ihre Kosten Rechenschaft ablegen.",al={"kebok","wer ist kebok","wer vergibt ohren der bloodscalp"}},{q="Warum will Kebok Ohren der Bloodscalp?",a="Bloodscalp-Trolle haben bei Scharmützeln im Dschungel Keboks Agenten und viele seiner besten Wachen getötet. Die Kosten steigen, und er muss Baron Revilgaz dafür Rechenschaft ablegen.",al={"warum ohren","warum ohren der bloodscalp","warum ohren sammeln"}},{q="Wie viele Ohren werden benötigt?",a="Kebok bittet Euch, ihm fünfzehn Ohren der Bloodscalp zu bringen, bevor er Euch bezahlt.",al={"wie viele ohren","anzahl der ohren"}},{q="Wohin führt dieses Kopfgeld als Nächstes?",a="Nachdem Kebok Euch für die Ohren der Bloodscalp bezahlt hat, wendet er sich einer weiteren örtlichen Bedrohung zu: Schädelspalter Tusks.",al={"what comes next","folgequest von ohren der bloodscalp","nächste quest"}}},fp="15,179,14.215.0,16.142.0,13.124.0,36.165.0,27.71.0,33.100.1"}
P.entries["quest:1898"] = {n="Die Todespirscher",s="In Unterstadt gehen die Todespirscher dem Verdacht auf Verrat in den Reihen der Verlassenen nach. Auf Drängen von Lord Varimathras gebt Ihr Euch als erwarteter Bote aus und befragt einen Händler, der womöglich eine fremde Fraktion unterstützt.",h="In Unterstadt gehen die Todespirscher dem Verdacht auf Verrat in den Reihen der Verlassenen nach.",kw={"andron gant","das apothekarium","astor hadren","todespirscher","spionage","verlassene","mennet carkad","unterstadt","varimathras"},ang={["class:Rogue"]="Als Schurke nutzt Ihr die Identität eines Toten, um einen unvorsichtigen Verschwörer aus der Reserve zu locken. Die Todespirscher kennen diese Methode gut.",["faction:Horde"]="Als Mitglied der Horde wisst Ihr, dass politische Intrigen bis unter Unterstadt reichen. Selbst innerhalb der Grenzen der Horde ist Vertrauen selten.",["race:Undead"]="Als Verlassener wisst Ihr, dass Wachsamkeit Überleben bedeutet. Ein Bürger, der bei der Unterstützung fremder Fraktionen ertappt wird, riskiert, von der Geheimpolizei der dunklen Herrin beseitigt zu werden."},sec={{t="Ein Netz der Täuschung",b="Auf Drängen von Lord Varimathras setzt Todespirscher Mennet Carkad eine Infiltration in Gang. Die Todespirscher überwachen die Bürger der Verlassenen ebenso aufmerksam, wie sie vor äußeren Bedrohungen schützen. Mit einem gefälschten oder erbeuteten Empfehlungsschreiben von Astor Hadren sucht Ihr den örtlichen Händler Andron Gant auf. Ihr versucht, Euch als der Kurier auszugeben, den er erwartet."},{t="Der Laden beim Apothekarium",b="Andron Gant betreibt einen Laden in der Nähe des Apothekariums. Mennet glaubt, dem Ladenbesitzer fehle der Scharfsinn, einen Hochstapler zu erkennen. Als Ihr den Brief vorzeigt, glaubt Gant an Eure Tarnung als Kurier und lässt seine Wachsamkeit sinken. Dann beginnt er, von Geschäften mit einer unbekannten dritten Partei zu erzählen."}},faq={{q="Wer ist Andron Gant?",a="Andron Gant ist ein Ladenbesitzer in Unterstadt, in der Nähe des Apothekariums. Die Todespirscher und Lord Varimathras vermuten, dass er einer unbekannten fremden Fraktion Informationen und Unterstützung zukommen lässt.",al={"andron gant","wer ist gant","wo ist andron gant"}},{q="Warum interessiert sich Lord Varimathras für diesen Händler?",a="Lord Varimathras vermutet, dass Gant mit einer Organisation außerhalb der Verlassenen zusammenarbeitet. Er will Beweise für Gants Kontakte und Absichten, um die Stadt zu schützen und umstürzlerische Bestrebungen aufzudecken.",al={"warum varimathras sich dafür interessiert","varimathras andron gant","warum andron ausspionieren"}},{q="Wie täuscht der Spieler Andron Gant?",a="Mennet Carkad gibt Euch Astor’s Letter of Introduction. Gant erwartet einen Kurier, und die Todespirscher halten ihn für leicht zu täuschen, sodass der Brief sein Vertrauen gewinnt.",al={"astors brief","wie andron gant täuschen","botentarnung"}},{q="Was für eine Gruppe sind die Todespirscher?",a="Die Todespirscher sind der Eliteorden der Schurken und der geheime Nachrichtendienst der Verlassenen. Unter Königin Sylvanas und Lord Varimathras wirken sie im Verborgenen, um Aufruhr aufzudecken, Feinde zu sabotieren und Bedrohungen in den eigenen Reihen auszuschalten.",al={"geschichte der todespirscher","wer sind die todespirscher","schurken von unterstadt"}},{q="Wo ist Andron Gant zu finden?",a="Andron Gant arbeitet in seinem Laden nahe dem Eingang zum Viertel des Apothekariums in Unterstadt. Er betreibt seine Geschäfte unter den wachsamen Augen der Royal Apothecary Society und der Todespirscher.",al={"andron gant standort","wo ist gants laden"}},{q="Was geschieht, nachdem Gant den Brief angenommen hat?",a="Gant nimmt den Brief ohne Argwohn an und hält Euch für einen Boten, der nichts zu verbergen hat. Er deutet eine Zusammenarbeit mit gemeinsamen Bekannten an und gibt Euch damit Gelegenheit, nach weiteren Beweisen für seinen Verrat zu suchen.",al={"was macht gant","gants reaktion"}}},fx={["6d39edb7"]={q="Warum möchte Mennet Carkad, dass Andron Gant untersucht wird?",a="Mennet Carkad handelt direkt auf Befehl von Lord Varimathras. Der Schreckenslord vermutet, dass Andron Gant heimlich Unterstützung und Informationen an eine unbekannte rivalisierende Fraktion aus der Unterstadt schleust. Um die Führung der Verlassenen vor interner Subversion zu schützen, benötigt Mennet definitive Beweise für Gants Verrat und die Identität der zwielichtigen Organisation, der er dient.",al={"warum andron gant untersuchen","motiv von mennet carkad","warum schickt mennet mich zu gant"}},["3bf738ba"]={q="Warum schickt Mennet Carkad Euch, anstatt selbst zu gehen?",a="Mennet Carkad hat Andron Gant bereits persönlich getroffen, weshalb seine eigene Anwesenheit das Scheitern der Mission bedeuten würde. Gant würde sofort einen bekannten Deathstalker-Agenten erkennen. Da Ihr Astor Hadrens Empfehlungsschreiben besitzt, hat Gant keinen Grund zu vermuten, dass Ihr etwas anderes seid als der Kurier, den er treffen sollte.",al={"warum braucht mennet mich","warum kann mennet nicht mit gant sprechen","warum einen abenteurer nutzen"}}},fp="17,205,15.336.0,30.268.1,19.183.0,52.180.0,40.165.0,33.235.0,31.181.0,43.203.1"}
P.entries["quest:1899"] = {n="Die Todespirscher",s="In Unterstadt wenden die Todespirscher Andron Gants Vertrauen gegen ihn. Im Glauben, Ihr seiet der erwartete Bote, übergibt Gant Euch ein Geschäftsbuch für seine geheimen Kontakte. Ihr bringt es zu Mennet Carkad im Schurkenviertel und ebnet damit den Weg für weitergehende verdeckte Arbeit im Dienst des Verlassenenstaates.",h="In Unterstadt wenden die Todespirscher Andron Gants Vertrauen gegen ihn.",kw={"andron gant","meuchelmörder","todespirscher","spionage","geschäftsbuch","mennet carkad","schurkenviertel","unterstadt"},ang={["class:Rogue"]="Als Schurke in Unterstadt könnt Ihr Eure Verschwiegenheit beweisen, indem Ihr vertrauliche Nachrichten für Mennet Carkad überbringt, ohne unerwünschte Aufmerksamkeit zu erregen.",["race:Undead"]="Als Untoter wisst Ihr, dass die Sicherheit Unterstadts eine Frage des Überlebens ist. Eure Hilfe für die Todespirscher stärkt die Kontrolle der Dark Lady über die Hauptstadt gegenüber lebenden Eindringlingen und rivalisierenden Untoten."},sec={{t="Ein Bote im Schatten",b="Andron Gant hält in Unterstadt Namen und Informationen in einem persönlichen Geschäftsbuch fest. Im Glauben, Ihr seiet der erwartete Bote, übergibt er Euch das Geschäftsbuch zur Weitergabe an seine geheimen Kontakte. Gant bittet darum, künftige Nachrichten vom selben Boten überbringen zu lassen. Er weiß nicht, dass das Geschäftsbuch für die Todespirscher bestimmt ist."},{t="Geheimnisse im Schurkenviertel",b="Mennet Carkad nimmt Gants Geschäftsbuch im Schurkenviertel entgegen und findet mehr nützliche Informationen darin als erwartet. Die Einzelheiten liefern Carkad Anhaltspunkte, um die Ermittlungen der Todespirscher auszuweiten. Das Reich der Verlassenen ist wachsam, und diese Aufzeichnungen könnten helfen, Umtriebe innerhalb seiner Grenzen und Bedrohungen von außerhalb aufzudecken, bevor sie die Hauptstadt erreichen."}},faq={{q="Was steht in Androns Geschäftsbuch?",a="Andron Gants Geschäftsbuch enthält brisante Informationen und Aufzeichnungen, die er zusammengetragen hat. Mennet Carkad findet darin mehr Einzelheiten und wertvolle Erkenntnisse, als die Todespirscher erwartet hatten.",al={"andron geschäftsbuch inhalt","was steht im geschäftsbuch","todespirscher geschäftsbuch"}},{q="Wer sind die Todespirscher?",a="Die Todespirscher sind die Geheimorganisation und Meuchelmördergilde der Verlassenen. Vom Schurkenviertel in Unterstadt aus dienen sie Fürstin Sylvanas Windläufer als Augen, Ohren und verborgene Dolche. Sie kümmern sich in ganz Lordaeron um Spionage, Informationsbeschaffung und gezielte Meuchelmorde.",al={"todespirscher hintergrund","wer sind die todespirscher","unterstadt schurken"}},{q="Warum will Gant künftig denselben Boten einsetzen?",a="Gant will künftige vertrauliche Dokumente einem Boten anvertrauen, dem er vertraut. Derselbe Bote wahrt ihre bestehende Zusammenarbeit und verringert das Risiko von Diebstahl oder Manipulation.",al={"gants zuneigung","andron gant vertrauen","gant bote"}},{q="Wer ist Mennet Carkad?",a="Mennet Carkad ist ein Agent der Todespirscher im Schurkenviertel. Er koordiniert örtliche Agenten, sammelt Informationen aus dem Einsatzgebiet von Informanten wie Andron Gant und leitet verdeckte Aufträge in der gesamten Hauptstadt und den umliegenden Gebieten.",al={"mennet carkad hintergrund","wer ist carkad"}},{q="Wo liegt das Schurkenviertel?",a="Das Schurkenviertel liegt im südlichen Bezirk von Unterstadt. Es ist der Hauptstützpunkt für verdeckt operierende Agenten, Diebe und Meuchelmörder der Verlassenen, mit Übungsplätzen und dunklen Nischen abseits der öffentlichen Plätze der oberen Ruinen.",al={"schurkenviertel lage","wo ist das schurkenviertel","unterstadt schurkenviertel"}},{q="Warum brauchen die Verlassenen einen Inlandsgeheimdienst?",a="Die Verlassenen brauchen einen Inlandsgeheimdienst, um Umtriebe innerhalb der Grenzen Lordaerons aufzudecken. Die Todespirscher helfen der jungen Nation, Bedrohungen durch die Geißel, den Scharlachroten Kreuzzug, misstrauische Überreste der Allianz, Unterwanderung und Aufstände zu überstehen.",al={"warum es todespirscher gibt","verlassene spione","unterstadt geheimdienst"}}},fx={["63e535f7"]={q="Warum möchte Andron Gant, dass das Hauptbuch überbracht wird?",a="Andron Gant glaubt, Ihr seid der Bote, der von den geheimen Kontakten geschickt wurde, die er mit Informationen versorgt hat. Er übergibt das Hauptbuch für sie und bittet darum, dass Ihr wieder geschickt werdet, falls sie die Vereinbarung fortsetzen möchten, ohne jemals zu ahnen, dass es direkt an die Todespirscher geht.",al={"warum das hauptbuch abliefern","andron gant motiv","warum kooperiert andron"}}},fp="17,280,24.297.0,35.334.1,27.170.0,26.272.0,55.170.0,21.242.0,37.231.0,57.245.0"}
P.entries["quest:19"] = {n="Tharil'zun",s="Nahe Burg Steinwacht nimmt Marschall Marris Tharil'zun ins Visier, dessen Vorläufer die Straßen unsicher machen. Sein Tod ist ein entscheidender Schritt, um den Griff des Schwarzfelsklans über das nördliche Rotkammgebirge zu brechen, und sein abgetrennter Kopf, nach Seenhain gebracht, bedeutet einen hart erkämpften Sieg für die dortige Wache.",h="Nahe Burg Steinwacht nimmt Marschall Marris Tharil'zun ins Visier, dessen Vorläufer die Straßen unsicher...",kw={"blackrock","seenhain","marschall marris","vorläufer","rotkammgebirge","steinwacht","burg steinwacht","tharil'zun","tharilzun"},ang={["faction:Alliance"]="Seenhain ist weitgehend isoliert und erhält keine direkte Verstärkung aus Sturmwind. Das Kopfgeld auf Tharil'zun ist eine entscheidende Maßnahme vor Ort, um eine Belagerung der Stadt zu verhindern.",["race:Human"]="Als Mensch erinnert Euch die Präsenz des Schwarzfelsklans im Rotkammgebirge an die First and Second Wars. Indem Ihr Tharil'zun tötet, erobert Ihr Land zurück, das dem Königreich entrissen wurde.",["race:Orc"]="Als Orc stellt Ihr Euch Tharil'zun, einem der finsteren Überbleibsel der Old Horde unter dem Banner des Schwarzfelsklans, der Herren dient, die Thralls neue Ordnung jenseits des Meeres ablehnen."},sec={{t="Der Weg nach Steinwacht",b="Der Weg zwischen Seenhain und Burg Steinwacht ist durch plötzliche Hinterhalte gefährlich geworden. Vorläufer und Abtrünnige des Schwarzfelsklans durchstreifen die felsigen Kämme, schneiden Kundschaftern den Weg ab und bedrohen Verstärkung auf dem Weg zur Festung. Marschall Marris nennt Tharil'zun als den Kommandanten, der diese Angriffe lenkt. Er sagt, Tharil'zun müsse ausgeschaltet werden, sonst könnte Seenhain vollständig eingekesselt werden."},{t="Die Vorläufer enthaupten",b="Tharil'zun ist ein gefährlicher Schlachtfeldanführer, grausam und gerissen, der verstreute Orcplünderer zu einer schlagkräftigen Truppe vereint. Ihn im Schatten von Steinwacht zu erreichen, bedeutet, sich durch verschanzte Außenposten des Schwarzfelsklans zu kämpfen. Sein Tod bricht den Zusammenhalt der Vorläuferpatrouillen und ebnet der Allianz den Weg, sich der Garnison in der Burg zu stellen."}},faq={{q="Wer ist Tharil'zun?",a="Tharil'zun ist ein mächtiger Kommandant der Schwarzfelsorcs, der die Vorläufer und Abtrünnigen anführt, die auf den Pfaden zwischen Seenhain und Burg Steinwacht Hinterhalte legen.",al={"wer ist tharilzun","tharil'zun hintergrundgeschichte","tharilzun boss"}},{q="Wo ist Tharil'zun zu finden?",a="Tharil'zun befindet sich nahe Burg Steinwacht im nordöstlichen Rotkammgebirge und befehligt Vorläufer, die an den umliegenden Pässen und Außenposten patrouillieren.",al={"wo ist tharil'zun","tharilzun aufenthaltsort","tharil'zun finden"}},{q="Warum will Marschall Marris seinen Kopf?",a="Marris sieht in Tharil'zun den gerissenen Taktiker hinter den Hinterhalten, die das Rotkammgebirge heimsuchen. Er fordert Tharil'zuns Kopf, um die Führung der Vorläufer auszuschalten und zu beweisen, dass die Bedrohung beseitigt wurde.",al={"warum tharilzun töten","tharilzun kopfgeld grund"}},{q="Was geschieht nach Tharil'zuns Niederlage?",a="Tharil'zuns Niederlage lähmt die Koordination der Vorläufer, sodass Seenhains Verteidiger und Abenteurer tiefer in Burg Steinwacht vordringen und sich der Hauptgarnison des Schwarzfelsklans stellen können.",al={"quest nach tharilzun","was folgt auf tharil'zun"}},{q="Warum sind Schwarzfelsorcs im Rotkammgebirge?",a="Überreste des Schwarzfelsklans zogen aus der Brennenden Steppe nach Süden ins Rotkammgebirge. Sie befestigten alte Außenposten der Menschen wie Burg Steinwacht, um die Östlichen Königreiche zu bedrohen, während Sturmwinds Truppen an zu vielen Fronten gebunden sind.",al={"warum sind schwarzfelsorcs im rotkammgebirge","steinwacht orcs hintergrund"}},{q="Welche Voraussetzung muss vor der Jagd auf Tharil'zun erfüllt werden?",a="Bevor Marschall Marris Euch auf Tharil'zun ansetzt, verlangt er, dass Ihr Euch bewährt, indem Ihr in 'Blackrock Menace' die Reihen der eindringenden Streitkräfte lichtet.",al={"tharilzun voraussetzung","wie tharilzun quest freischalten"}}},fx={["3b83e264"]={q="Warum benötigt Marschall Marris Tharil'zuns Kopf?",a="Marschall Marris fordert Tharil'zuns Kopf als definitiven Beweis für den Tod des Kriegsherrn. Tharil'zun ist ein gerissener und bösartiger Anführer, der Hinterhalte gegen die Verteidiger von Seenhain leitet, und Marris kann es sich nicht leisten, sich auf Gerüchte oder falsche Berichte zu verlassen, wenn die Sicherheit der gesamten Region am seidenen Faden hängt.",al={"wozu dient tharilzuns kopf","zweck von tharilzuns kopf","warum tharilzuns kopf mitnehmen"}},["66abe4be"]={q="Warum schickt Marschall Marris Euch anstatt der Stadtwache?",a="Die örtliche Garnison von Seenhain ist bis an ihre absolute Belastungsgrenze beansprucht. Da Sturmwind Verstärkungen zurückhält und Orc-Hinterhalte bis dicht an die Stadt heranreichen, kann Marschall Marris keine Männer entbehren, um tief in das Gebiet von Steinwacht vorzustoßen. Er muss sich auf erfahrene, unabhängige Abenteurer verlassen, um hochrangige gegnerische Kommandanten auszuschalten.",al={"warum einen abenteurer schicken","warum nicht die wachen vom rotkammgebirge","warum braucht marris mich"}}},fp="10,267,22.374.0,27.334.0,18.149.0,30.130.0,38.197.0,42.184.0,45.212.0,62.141.0"}
P.entries["quest:190"] = {n="Beherrschen der Pantherjagd",s="Bei Nesingwarys Expedition prüft Sire S. J. Erlgadin jene, die an Hemets Jagd teilnehmen wollen. Sie müssen zehn junge Panther erlegen, um ihr Geschick im Fährtenlesen zu beweisen.",h="Bei Nesingwarys Expedition prüft Sire S.",kw={"hemet","nesingwary","beherrschen der pantherjagd","sire s. j. erlgadin","schlingendorntal","junge panther"},sec={{t="Eine Schar erlesener Jäger",b="Hemet Nesingwary hat erfahrene Großwildjäger im nördlichen Schlingendorntal versammelt. Sire S. J. Erlgadin verlangt von Neuankömmlingen, ihr Können bei der Pantherjagd zu beweisen, bevor sie sich der Jagdgesellschaft anschließen."},{t="Den Schleichern auf der Spur",b="Bevor Erlgadin Neuankömmlingen größeres Wild anvertraut, stellt er sie auf die Probe. Sie müssen zehn junge Panther finden und töten. Die Schleicher zu finden, ist nur die halbe Herausforderung."}},faq={{q="Wer stellt diese Jagdaufgabe?",a="Sire S. J. Erlgadin stellt die Aufgabe im Lager von Nesingwarys Expedition im nördlichen Schlingendorntal. Er prüft Neuankömmlinge, die sich Hemets Jagdgesellschaft anschließen wollen.",al={"beherrschen der pantherjagd questgeber","wer startet beherrschen der pantherjagd","erlgadin quest"}},{q="Welche Beute muss gejagt werden?",a="Jäger müssen im umliegenden Dschungeldickicht zehn junge Panther aufspüren und töten.",al={"was muss für beherrschen der pantherjagd getötet werden","beherrschen der pantherjagd ziel","junge panther"}},{q="Warum stellt Sire S. J. Erlgadin diese Prüfung?",a="Hemet Nesingwary hat eine erfahrene Jagdgesellschaft versammelt. Erlgadin verlangt von Neuankömmlingen, ihr Können bei der Pantherjagd zu beweisen, bevor sie an der Jagd teilnehmen.",al={"warum junge panther töten","zweck von beherrschen der pantherjagd"}},{q="Was folgt nach Abschluss dieser Jagd?",a="Nach dieser ersten Prüfung stellt Sire S. J. Erlgadin in „Beherrschen der Pantherjagd zwei“ eine schwierigere Jagdaufgabe.",al={"beherrschen der pantherjagd nächste quest","was folgt nach beherrschen der pantherjagd"}}},fp="15,166,24.181.0,21.163.0,33.161.0,27.79.0,45.135.0,43.87.0"}
P.entries["quest:191"] = {n="Beherrschen der Pantherjagd",s="Bei Nesingwarys Expedition fordert Sire S. J. Erlgadin Euch auf, Euch unter den erfahrenen Jägern zu beweisen. Nach Eurer Jagd auf junge Panther schickt er Euch ins Schlingendorntal, um zehn ausgewachsene Bestien zu jagen.",h="Bei Nesingwarys Expedition fordert Sire S.",kw={"großwild","erlgadin","jagd","beherrschung","nesingwary","panther","schlingendorntal"},sec={{t="Ein höherer Maßstab",b="Eure Jagd auf junge Panther ist beendet, und Sire S. J. Erlgadin legt einen höheren Maßstab an. Er fordert Euch auf, zu beweisen, dass Ihr mit den erfahrenen Großwildjägern der Expedition mithalten könnt. Also zieht Ihr los, um zehn ausgewachsene Panther aufzuspüren und zu erlegen, die stärker und gefährlicher sind als ihre jungen Artgenossen."}},faq={{q="Wer stellt diese Prüfung?",a="Sire S. J. Erlgadin, ein Jäger bei Nesingwarys Expedition im nördlichen Schlingendorntal, beaufsichtigt diesen Abschnitt der Jagd.",al={"wer vergibt beherrschen der pantherjagd","erlgadin quest","questgeber"}},{q="Welche Beute sollt Ihr jagen?",a="Ihr sollt zehn ausgewachsene Panther im umliegenden Dschungel aufspüren und erlegen. Sie sind zäher als die jüngeren Panther, die Ihr zuvor gejagt habt.",al={"welche panther töten","welche bestien","beherrschen der pantherjagd ziel"}},{q="Was geht dieser Herausforderung voraus?",a="Eine frühere Prüfung, ebenfalls mit dem Titel Beherrschen der Pantherjagd, stellte Euer Können gegen jüngere Dschungelpanther auf die Probe.",al={"vorherige quest","vorheriger schritt","beherrschen der pantherjagd voraussetzung"}},{q="Welchen Zweck hat die Jagd auf diese Panther?",a="Sire S. J. Erlgadin fordert Euch auf, Euer Können und Euren Mut zu beweisen, damit Ihr mit den erfahrenen Großwildjägern der Expedition jagen und Zeit verbringen könnt.",al={"warum panther töten","erlgadins beweggrund","nesingwarys absicht"}}},fp="15,204,17.279.0,22.120.0,34.140.0,33.97.0,46.144.0"}
P.entries["quest:1918"] = {n="Das beschmutzte Element",s="Am Mystralsee hinterlassen erschlagene Wassergeister leuchtende Kugeln aus verdorbenem Wasser. Ihr bringt eine zu Mastok Wutfauch am Splitterholzposten, um zu erfahren, was den See und seine Geister vergiftet hat.",h="Am Mystralsee hinterlassen erschlagene Wassergeister leuchtende Kugeln aus verdorbenem Wasser.",kw={"eschental","beschmutzte wasserkugel","verderbte elementare","der irdene ring","mastok wutfauch","mystralsee","splitterholzposten"},ang={["class:Shaman"]="Als Schamane hört Ihr den Schmerz in den entstellten Geistern des Mystralsees und wisst, dass der Irdene Ring eingreifen muss.",["faction:Horde"]="Als Mitglied der Horde wisst Ihr, dass der Splitterholzposten keine elementare Gefahr in seiner unmittelbaren Umgebung dulden kann, während Schildwachen der Allianz und Furbolgs die Nachschubwege der Horde bedrohen.",["race:Tauren"]="Als Tauren fühlt Ihr Euch durch Eure Kultur zutiefst verpflichtet, die verderbten Gewässer des Landes zu heilen, wodurch die Wiederherstellung des Mystralsees zu einer dringenden spirituellen Aufgabe wird."},sec={{t="Verdorbene Wasser des Mystralsees",b="Im südlichen Zentrum des Eschentals sind die Wasserelementare des Mystralsees gewalttätig geworden und sichtlich verderbt. Wenn sie erschlagen werden, hinterlassen sie seltsame, leuchtende Kugeln aus fauliger Flüssigkeit statt reiner Elementaressenz. Die Kugeln bergen die Verderbnis, die sich über den See gelegt hat. Hier wirkt mehr als natürliche Aggression zur Revierverteidigung."},{t="Rat am Splitterholzposten",b="Am Splitterholzposten suchen Späher der Horde Rat bei Mastok Wutfauch, der den Außenposten leitet. Angewidert von der abscheulichen Probe gibt Mastok zu, dass er Soldat ist, kein Gelehrter. Gewöhnlicher Stahl kann krankes Wasser nicht heilen, also verweist er Euch an die Elementarspezialisten des Irdenen Rings."}},faq={{q="Was steckt in der Beschmutzten Wasserkugel?",a="Die Beschmutzte Wasserkugel enthält eine widerliche, konzentrierte Probe der Verderbnis, die den Mystralsee vergiftet. Sie entsteht aus erschlagenen Elementaren und zeigt, dass ihre geistige Verderbnis eine greifbare und mächtige Form angenommen hat.",al={"inhalt der beschmutzten wasserkugel","was ist in der wasserkugel","mystralsee wasserkugel"}},{q="Wo beginnt diese Quest?",a="Ihr findet die Kugel beim Kampf gegen erzürnte oder beschmutzte Wasserelementare am Mystralsee im südlichen Zentrum des Eschentals.",al={"wo ist die wasserkugel zu finden","wie beginnt das beschmutzte element","questbeginn"}},{q="Warum will Mastok Wutfauch nichts damit zu tun haben?",a="Mastok Wutfauch ist ein Offizier der Horde, der sich am Splitterholzposten um das militärische Überleben und die Logistik kümmert. Die Untersuchung kranker magischer Gewässer liegt ihm nicht, also verweist er Euch an den Irdenen Ring.",al={"wer ist mastok","warum mit mastok sprechen","mastok wutfauchs rolle"}},{q="Welches Interesse hat der Irdene Ring daran?",a="Der Irdene Ring ist ein Schamanenorden, der die Elemente erforscht, besänftigt und ihre Harmonie wiederherstellt. Verderbte Elementare wie jene am Mystralsee fallen unter seine geistige Fürsorge.",al={"warum der irdene ring","verbindung zum irdenen ring","wer ist der irdene ring"}},{q="Wohin führt die Untersuchung als Nächstes?",a="Mastok verweist Euch an Je'neu Sancrea, einen Schamanen des Irdenen Rings, der an der Westküste des Eschentals bei Zoram'gar Strand stationiert ist. Je'neu kann das verdorbene Relikt untersuchen.",al={"what comes next","nächste quest nach dem beschmutzten element","wohin geht es als nächstes"}}},fp="20,197,30.323.0,30.288.1,40.214.0,28.114.0,53.201.0,44.190.0,39.164.1"}
P.entries["quest:192"] = {n="Beherrschen der Pantherjagd",s="Im Schlingendorntal führt Euch Beherrschen der Pantherjagd auf die Jagd nach den tödlichsten Panthern. Nach Euren früheren Prüfungen sind nun zehn Shadowmaw Panthers Eure Beute.",h="Im Schlingendorntal führt Euch Beherrschen der Pantherjagd auf die Jagd nach den tödlichsten Panthern.",kw={"großwild","nesingwary","beherrschen der pantherjagd","shadowmaw panther","sire s. j. erlgadin","schlingendorntal"},ang={["class:Hunter"]="Als Jäger stellt Ihr Euch Erlgadins Herausforderung, bei der Euer Ruf als Großwildjäger auf dem Spiel steht. Er erwartet, dass Ihr die wildesten Raubtiere des Dschungels aufspürt und erlegt."},sec={{t="Die tödlichste Beute",b="Sire S. J. Erlgadin nennt Shadowmaw Panthers die gefährlichsten Raubkatzen im Dschungel des Schlingendorntals. Um Euch als Pirscher zu beweisen, kriecht Ihr durch dichtes Unterholz und spürt zehn schwer fassbare Bestien auf. Ihre Wildheit macht es schwerer, sie zu töten, als sie zu finden."}},faq={{q="Wer bietet diese Jagd an?",a="Sire S. J. Erlgadin bietet diese Jagd im Lager von Nesingwarys Expedition im nördlichen Schlingendorntal an.",al={"wer vergibt beherrschen der pantherjagd","questgeber beherrschen der pantherjagd","wer vergibt diese quest"}},{q="Welche Bestien jagt Ihr?",a="Ihr jagt zehn Shadowmaw Panthers, die Erlgadin als die tödlichsten Panther im ganzen Schlingendorntal bezeichnet.",al={"was muss getötet werden","ziel von beherrschen der pantherjagd","welche panther"}},{q="Wo steht diese Jagd innerhalb der Jagdprüfungen?",a="Dies ist die dritte Prüfung der Pantherjagd, nach der zweiten Prüfung von Beherrschen der Pantherjagd und vor der vierten.",al={"welche quest kommt davor","questreihe beherrschen der pantherjagd","vorausgesetzte quest"}}},fp="15,145,20.247.0,21.103.0,28.101.0,42.102.0"}
P.entries["quest:1920"] = {n="Investigate the Blue Recluse",s="Jennea Haubitz bittet Euch, seltsame unsichtbare Kreaturen in der Taverne Blue Recluse zu untersuchen. Sie fürchtet, dass sich dort ein Manariss geöffnet hat.",h="Jennea Haubitz bittet Euch, seltsame unsichtbare Kreaturen in der Taverne Blue Recluse zu untersuchen.",kw={"blue recluse","inkantation der manifestation","eindämmungstruhe","unsichtbare kreaturen","jennea haubitz","mage quarter","manariss"},ang={["class:Mage"]="Als Magier bringt Ihr die gefangenen Kreaturen zu Jennea Haubitz, damit sie untersucht werden können."},sec={{t="Im Blue Recluse",b="Jennea Haubitz meldet eine Störung im Blue Recluse im Mage Quarter. Unsichtbare Kreaturen streifen nun durch die Taverne, und sie fürchtet, dass sich ein Manariss gebildet hat. Ihr sollt die Kreaturen sichtbar machen und in Eindämmungstruhen einfangen. Jennea braucht die gefangenen Kreaturen für ihre Studien."}},faq={{q="Was geschieht im Blue Recluse?",a="Unsichtbare Kreaturen streifen durch das Blue Recluse, und Jennea Haubitz fürchtet, dass sich dort ein Manariss gebildet hat.",al={"störung im blue recluse","was stimmt in der taverne nicht"}},{q="Wer hat mich zur Untersuchung geschickt?",a="Jennea Haubitz bittet Euch, die Störung im Blue Recluse zu untersuchen.",al={"wer hat mich gebeten","jennea blue recluse"}},{q="Warum will Jennea die Kreaturen haben?",a="Jennea will die Kreaturen untersuchen, um herauszufinden, warum sie aufgetaucht sind.",al={"warum sie einfangen","wozu dienen die kreaturen"}},{q="Wie mache ich die Kreaturen sichtbar?",a="Die Inkantation der Manifestation macht die Kreaturen in der Taverne sichtbar.",al={"inkantation verwenden","kreaturen sichtbar machen"}},{q="Was fürchtet Jennea, ist geschehen?",a="Jennea fürchtet, dass sich im Blue Recluse ein Manariss gebildet hat.",al={"manariss taverne","riss im blue recluse"}}},fp="28,133,19.289.0,38.105.0,27.74.0,35.66.0,36.77.0,35.56.0"}
P.entries["quest:193"] = {n="Beherrschen der Pantherjagd",s="Bei Nesingwarys Expedition stellt Sire S. J. Erlgadin Euch eine letzte Prüfung. Ihr habt bereits Panther gejagt, doch die Gruppe der Expedition konnte Bhag'thera nicht finden. Bringt den Fangzahn des Raubtiers zurück, um Euer Können als Meister der Jagd zu beweisen.",h="Bei Nesingwarys Expedition stellt Sire S.",kw={"bhag'thera","fangzahn von bhag'thera","nesingwarys expedition","beherrschen der pantherjagd","sire s. j. erlgadin","schlingendorntal"},sec={{t="Der schwer fassbare Pirscher",b="Bei Nesingwarys Expedition stellt Sire S. J. Erlgadin Euch eine letzte Aufgabe. Bhag'thera durchstreift noch immer das Schlingendorntal, außerhalb der Reichweite der Expeditionsgruppe. Spürt den großen Panther auf und bringt seinen Fangzahn als Beweis Eures Könnens zurück."}},faq={{q="Wer bietet diese Jagd an?",a="Sire S. J. Erlgadin bietet diese Jagd bei Nesingwarys Expedition im nördlichen Schlingendorntal an.",al={"questgeber","wer vergibt beherrschen der pantherjagd","erlgadin quest"}},{q="Welche Bestie jagt Ihr?",a="Ihr jagt Bhag'thera, einen großen Panther, der durch den Dschungel streift und sich der Gruppe der Expedition bisher entzogen hat.",al={"was ist das ziel","wer ist bhag'thera","panther jagdziel"}},{q="Welche Trophäe wird verlangt?",a="Sire S. J. Erlgadin verlangt den Fangzahn von Bhag'thera als Beweis dafür, dass Ihr die Bestie besiegt habt.",al={"welcher beweis","welcher gegenstand","bhag'thera trophäe"}},{q="Was ging dieser Jagd voraus?",a="Diese Jagd folgt auf die dritte Prüfung der Questreihe Beherrschen der Pantherjagd und baut auf Euren früheren Pantherjagden auf.",al={"vorherige quest","beherrschen der pantherjagd voraussetzung"}}},fp="15,243,19.234.0,21.94.0,27.105.0,24.88.0,27.103.0"}
P.entries["quest:1938"] = {n="Urs Abhandlung über Schattenmagie",s="High Sorcerer Andromath sucht in Sturmwind nach Urs Abhandlung über Schattenmagie. Morganth stahl den verbotenen Folianten und brachte ihn zum Turm von Ilgalar im Rotkammgebirge.",h="High Sorcerer Andromath sucht in Sturmwind nach Urs Abhandlung über Schattenmagie.",kw={"andromath","ilgalar","morganth","shadow magic","sturmwind","abhandlung","ur","magiersanktum"},ang={["class:Mage"]="Als Magier seht Ihr, wie ernst Sturmwinds Magier die Disziplin innerhalb ihres Ordens nehmen. Sie vertrauen Euch an, die Gefahr einzudämmen, die ein Gefährte hinterlassen hat, der sich verbotener Schattenmagie zuwandte.",["class:Warlock"]="Als Hexenmeister begehrt Ihr vielleicht die Macht der Beschwörung aus anderen Ebenen und der dunklen Zauberei, die in Urs Abhandlungen versiegelt ist. Die Kirin Tor und Sturmwinds Magier fürchten diese Mächte.",["faction:Alliance"]="Als Mitglied der Allianz helft Ihr durch die Bergung des gestohlenen Folianten, das Rotkammgebirge vor Morganths wachsender magischer Bedrohung und Sturmwind vor abtrünniger Arkankunst zu schützen."},sec={{t="Zerwürfnis im Turm",b="Drei vielversprechende Magier studierten gemeinsam im Magiersanktum von Sturmwind. Morganth wandte sich trotz ihrer verzweifelten Warnungen den dunklen Künsten und der Schattenmagie zu. Der magische Orden der Stadt verbannte ihn. Bevor er ging, stahl er ein gefährliches Werk von Ur, einem berüchtigten Erzmagier, dessen Studien über die orthodoxe Arkankunst hinausreichten."},{t="Unterschlupf des gefallenen Magiers",b="Morganth besetzte den Turm von Ilgalar in den Höhen des Rotkammgebirges, fernab der Aufsicht Sturmwinds. High Sorcerer Andromath fürchtet das Wissen des Folianten in den Händen eines Verstoßenen, der verbotene Zauberei praktiziert. Deshalb schickt er Abenteurer der Allianz in den Turm, um ihn zurückzuholen, bevor seine Schutzzauber fallen."},{t="Unversehrte Schutzzauber",b="Urs Abhandlung kehrte mit unversehrten Schutzzaubern ins Magiersanktum zurück. High Sorcerer Andromath ist sehr erleichtert. Er hatte befürchtet, Morganth hätte die Schutzzauber aufgelöst oder das Buch unerreichbar versteckt. Die Siegel hielten stand und bewahrten die verheerenden Geheimnisse auf seinen Seiten vor dem abtrünnigen Zauberer."}},faq={{q="Wer hat die Abhandlung verfasst?",a="Ur verfasste die Abhandlung. Der legendäre Magier aus Dalaran war für seine esoterischen Forschungen über Wesen anderer Ebenen und Schattenmagie bekannt.",al={"wer ist ur","verfasser der abhandlung","urs abhandlung verfasser"}},{q="Wer hat Urs Abhandlung über Schattenmagie gestohlen?",a="Morganth stahl Urs Abhandlung über Schattenmagie. Er war ein Magier aus Sturmwind, der sich der dunklen Magie zuwandte und aus dem Magiersanktum verbannt wurde.",al={"wer hat das buch gestohlen","wer hat die abhandlung genommen","morganth buch"}},{q="Wo wird das Buch aufbewahrt?",a="Das Buch befindet sich in der Bibliothek des Turms von Ilgalar, hoch im Rotkammgebirge, wo Morganth seine neue Zuflucht errichtete.",al={"wo ist die abhandlung","turm von ilgalar fundort des buches","wo findet man urs abhandlung"}},{q="Konnte Morganth das Buch lesen?",a="Nein. High Sorcerer Andromath bestätigt, dass die Schutzsiegel des Buches bei seiner Rückkehr noch unversehrt waren, also hat Morganth es nie geöffnet.",al={"hat morganth das buch geöffnet","wurde die abhandlung geöffnet","sind die siegel gebrochen"}},{q="Warum wollen die Magier von Sturmwind das Buch zurück?",a="Sturmwinds Magier wollen das Buch zurück, weil seine tiefgründigen Geheimnisse der Schattenmagie Ungeübte ins Verderben stürzen können. Sie fürchten sich davor, es Morganth zu überlassen, einem Verstoßenen, der verbotene Zauberei praktiziert.",al={"warum das buch zurückholen","warum ist die abhandlung gefährlich","andromaths ziel"}},{q="Wer vergibt diese Quest?",a="High Sorcerer Andromath vergibt sie im Magiersanktum im Magierviertel von Sturmwind.",al={"questgeber","wo erhält man die quest für urs abhandlung","andromath quest"}}},fx={["705e1c6d"]={q="Was ist Urs Abhandlung über Schattenmagie?",a="Es ist ein mächtiger und gefährlicher Wälzer, der die dunklen Geheimnisse der Schattenmagie erforscht. Er wurde von dem Magier des Kirin Tor, Ur, verfasst und seine Tiefen sind nicht für Ungeschulte gedacht, da das Eindringen in sein verbotenes Wissen direkt ins Verderben und in den Ruin führen kann. Um seinen Missbrauch zu verhindern, haben die Magier von Sturmwind den Band mit magischen Siegeln belegt.",al={"urs abhandlung über schattenmagie","was ist die abhandlung","was bewirkt urs abhandlung"}}},fp="29,173,21.306.0,22.300.0,12.300.1,23.129.0,40.138.0,23.129.0,37.130.1,49.191.0,21.87.0"}
P.entries["quest:1939"] = {n="Zaubermeister Andromath",s="Im Magiersanktum von Sturmwind werden vielversprechende Magier der Allianz zur Turmspitze gerufen. Andromath wirkt außerhalb des zerstörten Dalaran unter den führenden Erzmagiern des Königreichs.",h="Im Magiersanktum von Sturmwind werden vielversprechende Magier der Allianz zur Turmspitze gerufen.",kw={"andromath","arkan","dalaran","jennea haubitz","das magierviertel","sturmwind","magiersanktum"},ang={["class:Mage"]="Als Magier geht Ihr von gewöhnlichen Zauberübungen bei Jennea Haubitz zu gefährlichen Spezialkenntnissen an der Seite eines der führenden Erzmagier Sturmwinds über.",["faction:Alliance"]="Als Mitglied der Allianz seid Ihr auf Sturmwinds Magiersanktum angewiesen, um Magier auszubilden und übernatürlichen Bedrohungen entgegenzutreten, während Dalarans überlebende Magier ihre zerstörte Stadt wiederaufbauen."},sec={{t="Vorladung zum Turm",b="Jennea Haubitz, die Lehrlingskoordinatorin im Magierviertel von Sturmwind, schickt vielversprechende Zauberwirker zur Spitze des Magiersanktums. Zaubermeister Andromath, einer der erfahrensten noch aktiven Praktizierenden der arkanen Künste in den südlichen Königreichen, möchte Magier treffen, die für größere Verantwortung bereit sind."},{t="Ein Meister außerhalb Dalarans",b="Dalarans Magokratie wurde im Dritten Krieg zerstört, und die überlebenden Zauberer sind mit dem Wiederaufbau beschäftigt. Ohne einfachen Zugang zu den Bibliotheken der Violetten Zitadelle vertraut die Allianz auf erfahrene Erzmagier in Sturmwind, um uralte Bedrohungen zu erforschen und Forschungen zu schattenhaften, verbotenen Künsten zu leiten."}},faq={{q="Wer ist Zaubermeister Andromath?",a="Oben im Magiersanktum von Sturmwind wirkt Zaubermeister Andromath als erfahrener Magier. Außerhalb Dalarans zählen ihn seine Fachgenossen zu den mächtigsten und gelehrtesten Zauberwirkern der Welt.",al={"wer ist andromath","andromaths geschichte","zaubermeister von sturmwind"}},{q="Wo kann ich Zaubermeister Andromath finden?",a="Andromath befindet sich an der Spitze des Magiersanktums, des gewundenen Turms im Magierviertel von Sturmwind.",al={"andromaths standort","wo ist andromath","zaubermeister andromath finden"}},{q="Warum schickt mich Jennea Haubitz zu ihm?",a="Jennea Haubitz schickt vielversprechende Zauberwirker, die über die Grundausbildung hinausgewachsen sind, zu Andromath, damit sie weiterführenden Rat erhalten und spezialisierte, gefährliche Forschung betreiben.",al={"warum mit andromath sprechen","jennea haubitz weiterleitung"}},{q="Wobei braucht Andromath Hilfe?",a="Andromath ruft fähige Magier dazu auf, dunkle arkane Geheimnisse zu ergründen und dabei unter anderem den gefährlichen historischen Band Ur’s Treatise on Shadow Magic zu beschaffen.",al={"andromaths questreihe","was will andromath"}},{q="Warum wird Dalaran als „abgeschottet“ beschrieben?",a="Jenneas Worte spiegeln wider, wie sehr sich die Kirin Tor seit dem Dritten Krieg zurückgezogen haben. Nachdem die Geißel und die Brennende Legion Dalaran verwüstet hatten, wandten sich die überlebenden Zauberer dem Wiederaufbau im Inneren zu, sodass sich nur wenige mit äußeren Angelegenheiten befassten.",al={"warum ist dalaran abgeschottet","dalarans zustand","was ist mit dalaran geschehen"}},{q="Ist diese Quest ausschließlich für Magier?",a="Ja. Die Vorladung gehört zum Ausbildungsweg von Magiern der Allianz, die ihre Kunst weiterentwickeln.",al={"auch für nichtmagier möglich","quest nur für magier"}}},fx={["56d3f2e8"]={q="Warum schickt mich Jennea Haubitz, anstatt sich selbst darum zu kümmern?",a="Jennea Haubitz dient als Ausbilderin im Magiersanktum und führt angehende Anwender der arkanen Künste. High Sorcerer Andromath hat ausdrücklich darum gebeten, mit Euch zu sprechen, einem versierten und aufstrebenden Magier, der für fortgeschrittenere Angelegenheiten bereit ist, anstatt die Mentoren der Akademie von ihren Lehrverpflichtungen abzuhalten.",al={"warum schickt sie mich","warum geht jennea nicht selbst","warum will andromath mich"}}},fp="23,179,20.301.0,24.281.0,31.191.0,41.104.0,42.142.0,35.154.1,42.229.0,33.87.0"}
P.entries["quest:194"] = {n="Beherrschen der Raptorenjagd",s="In seinem Lager im nördlichen Schlingendorntal prüft Hemet Nesingwary Euer Jagdgeschick. Er bittet Euch, zehn Stranglethorn Raptors zu finden und zu erlegen.",h="In seinem Lager im nördlichen Schlingendorntal prüft Hemet Nesingwary Euer Jagdgeschick.",kw={"großwildjäger","hemet nesingwary","beherrschen der raptorenjagd","schlingendorntal raptor","schlingendorntal"},ang={["class:Hunter"]="Als Jäger stellt Ihr Euch Hemet Nesingwarys Prüfungen in der Wildnis. Dort beweist Ihr Euer Können im Fährtenlesen und Eure Treffsicherheit."},sec={{t="Eine Prüfung des Könnens",b="Nach Welcome to the Jungle prüft Hemet Nesingwary Euer Können beim Fährtenlesen und Jagen im Dschungel. Er gibt Euch weder eine Karte noch eine Wegbeschreibung. Die Stranglethorn Raptors zu finden, ist Teil der Prüfung, und Ihr müsst zehn dieser wilden Bestien erlegen."}},faq={{q="Wer stellt diese Jagdaufgabe?",a="Hemet Nesingwary, der berühmte Großwildjäger, stellt die Aufgabe in seinem Expeditionslager im nördlichen Schlingendorntal.",al={"wer vergibt beherrschen der raptorenjagd","questgeber beherrschen der raptorenjagd","hemet nesingwary raptoren"}},{q="Welche Bestien sollt Ihr aufspüren?",a="Ihr sollt zehn Stranglethorn Raptors aufspüren und erlegen, die im Dschungel verstreut leben.",al={"welche raptoren","was für beherrschen der raptorenjagd töten","ziel von beherrschen der raptorenjagd"}},{q="Warum verrät Hemet Euch nicht, wo die Raptoren leben?",a="Hemet glaubt, dass das Aufspüren der Beute die halbe Prüfung auf dem Weg zum wahren Großwildjäger ist. Deshalb überlässt er Euch die Suche.",al={"wo sind die raptoren","warum kein fundort der raptoren","fundorte der raptoren"}},{q="Welcher Schritt kommt vor dieser Prüfung?",a="Diese Prüfung folgt auf Eure erste Begrüßung in der Wildnis, Welcome to the Jungle.",al={"voraussetzung für beherrschen der raptorenjagd","vorherige quest beherrschen der raptorenjagd","beginn der questreihe beherrschen der raptorenjagd"}}},fp="14,134,15.245.0,33.122.0,40.92.0,57.120.0,34.80.0"}
P.entries["quest:1940"] = {n="Makellose Spinnenseide",s="In Sturmwind schickt High Sorcerer Andromath aufstrebende Magier der Allianz für makellose Spinnenseide in den Dämmerwald. Sie bringen acht Proben zu Wynne Larson ins Magierviertel, wo sie eine Adeptenrobe webt.",h="In Sturmwind schickt High Sorcerer Andromath aufstrebende Magier der Allianz für makellose Spinnenseide in...",kw={"andromath","aas-einsiedlerspinne","dämmerwald","larsons gewänder","magierroben","makellose spinnenseide","magiersanktum","wynne larson"},ang={["class:Mage"]="Als Magier steigt Ihr durch diesen Ritus vom Lehrling zum Adepten auf. Jeder Magier aus Sturmwind trägt Roben, deren Fäden er selbst unter Gefahren beschafft hat.",["faction:Alliance"]="Als Untertan der Allianz verlasst Ihr die Zuflucht Sturmwinds und zieht in den gefährlichen Dämmerwald, um einen seltenen Rohstoff aus der Region zu sammeln.",["profession:Tailoring"]="Als Schneider könnt Ihr sehen, wie Wynne Larson hochwertige Fasern wild lebender Ungeheuer zu Stoff verarbeitet, der Verzauberungen besser aufnimmt als gewöhnliche Wolle oder Leinen."},sec={{t="Gewänder des Adepten",b="High Sorcerer Andromath würdigt den Abschluss der Lehrzeit eines Magiers mit Gewändern, die einem Adepten gebühren. Im Magiersanktum zeigt sich das Können eines Magiers an seinen Roben. Daher muss jeder Magier makellose Seide von gefährlichen Spinnen sammeln und dabei sowohl Geschick im Einsatz als auch Urteilsvermögen beweisen."},{t="Der Webstuhl des Dämmerwalds",b="Aas-Einsiedlerspinnen suchen die düsteren Wälder des Dämmerwalds heim, und gewöhnliche Marktstände verkaufen ihre Seide nicht. Ihr sammelt acht erlesene Proben und bringt sie quer durch Sturmwind zu Larsons Gewänder im Magierviertel. Dort webt Wynne Larson die zarten Fäden zu einer Robe von arkaner Bedeutung."}},faq={{q="Wer schickt Magier auf diesen Auftrag?",a="High Sorcerer Andromath entsendet Zauberwirker, die ihre Hingabe bewiesen haben. Er leitet das Magiersanktum in Sturmwind.",al={"wer vergibt makellose spinnenseide","questgeber makellose spinnenseide","andromath quest"}},{q="Wo wird die Seide gewonnen?",a="Ihr sammelt die Seide von Aas-Einsiedlerspinnen in den heimgesuchten Wäldern und auf den von Spinnweben überzogenen Lichtungen des Dämmerwalds.",al={"wo gibt es makellose seide","fundort spinnen","fundort aas-einsiedlerspinnen"}},{q="Wer fertigt die Robe aus der Seide?",a="Wynne Larson webt die Robe bei Larsons Gewänder im Magierviertel von Sturmwind.",al={"wer webt die seide","wynne larson","larsons gewänder"}},{q="Warum verwenden Magier Spinnenseide für Gewänder?",a="Makellose Spinnenseide ist widerstandsfähig und fein verwoben. Sie ergibt einen leichten Stoff, der feine Verzauberungen aufnehmen kann, ohne einen Zauberwirker zu beschweren.",al={"warum spinnenseide","spinnenseide magische roben"}},{q="Was folgt auf die Übergabe der Seide?",a="Nachdem Wynne die Seide begutachtet und an ihrem Webstuhl gearbeitet hat, überreicht sie dem Magier das fertige Astral Knot Garment.",al={"nächste quest nach makellose spinnenseide","was geschieht als nächstes"}},{q="Ist jede Spinnenseide aus dem Dämmerwald geeignet?",a="Nein. Larsons Gewänder benötigt für seine feinen Verzauberungen makellose Proben, die sorgfältig von Aas-Einsiedlerspinnen gewonnen wurden. Gröbere Spinnweben genügen nicht.",al={"ist gewöhnliche spinnenseide verwendbar","makellose und normale seide"}}},fx={a495a13a={q="Warum schickt Euch High Sorcerer Andromath los, um Seide zu sammeln?",a="High Sorcerer Andromath sieht Eure unerschütterliche Hingabe an die arkanen Künste und glaubt, dass es an der Zeit ist, dass Eure Kleidung Eure wachsende Meisterschaft widerspiegelt. Anstatt Euch ein fertiges Gewand auszuhändigen, erwartet das Magiersanktum von Euch, dass Ihr es Euch verdient, indem Ihr den Gefahren des Dämmerwalds trotzt, um die seltenen Materialien zu sammeln, die für ein Gewand eines Adepten benötigt werden.",al={"warum andromath seide will","andromaths motiv","warum gibt andromath diese quest"}},["8d44c073"]={q="Welche Kreaturen müsst Ihr für die Seide jagen?",a="Ihr werdet ausgesandt, um die Aas-Einsiedlerspinnen zu jagen, die in den dunklen Wäldern des Dämmerwalds lauern. Diese giftigen Spinnentiere spinnen einen außergewöhnlich haltbaren und resonanten Faden, doch nur ihre feinsten, makellosen Stränge eignen sich zum Weben eines verzauberten Gewandes.",al={"wen muss ich für makellose seide jagen","welche spinnen lassen die seide fallen","aas-einsiedlerspinne dämmerwald"}}},fp="20,201,22.284.0,20.289.0,35.133.0,28.102.0,34.79.0,42.150.0,37.113.0,44.141.0"}
P.entries["quest:1941"] = {n="Managewirkte Robe",s="In Sturmwind präsentiert Wynne Larson stolz ihre fertige Managewirkte Robe als Aushängeschild für den Laden ihrer Familie. Sie hat sie aus feinen Materialien für einen nun abgeschlossenen Auftrag gewebt.",h="In Sturmwind präsentiert Wynne Larson stolz ihre fertige Managewirkte Robe als Aushängeschild für den Laden...",kw={"lehrlingsrobe","tuchhändler","larson clothiers","das magierviertel","managewirkte robe","sturmwind","schneider","wynne larson"},ang={["class:Mage"]="Als Magier, der in Sturmwinds Türmen studiert, tragt Ihr eine maßgeschneiderte Managewirkte Robe als Zeichen Eures Übergangs zu ernsthafter Feldforschung und eigenständiger Zauberkunst.",["faction:Alliance"]="Wenn Ihr einen vielversprechenden Champion über einen örtlichen Laden in der Hauptstadt ausrüstet, helft Ihr, Sturmwinds Ansehen und Eigenständigkeit in unruhige Gebiete zu tragen.",["profession:Tailoring"]="Wynne Larsons Arbeit zeigt den hohen Standard menschlicher Schneiderkunst. Sie verwebt weltliche Materialien, um unberechenbare arkane Macht nutzbar zu machen und zu zügeln."},sec={{t="Larsons Schneiderei",b="Im Magierviertel von Sturmwind fertigt Larson Clothiers Gewänder für Zauberwirker, die unberechenbaren Energien gegenüberstehen. Feine magische Roben erfordern seltene Materialien, sorgfältige Nadelarbeit und Fäden, die mystischer Resonanz standhalten. Wynne Larson ist auf jedes Stück aus ihrem Laden stolz. Jede Robe, die im Einsatz getragen wird, trägt den Namen Larson."},{t="Gewebte Zauberkunst",b="Die Managewirkte Robe bietet Tragekomfort, Bewegungsfreiheit und zweckmäßige Widerstandsfähigkeit für Reisen durch umkämpfte Lande. Sobald Ihr die benötigten Bestandteile abliefert, setzt Wynne Larson selbst den letzten Stich und präsentiert das fertige Gewand. Es ist ein vortreffliches Beispiel für Larsons Schneiderkunst, das Bewunderung wecken und den Namen des Ladens im ganzen Königreich bekannt machen soll."}},faq={{q="Wer fertigt die Managewirkte Robe?",a="Wynne Larson fertigt die Managewirkte Robe bei Larson Clothiers im Magierviertel von Sturmwind.",al={"wer fertigt die managewirkte robe","wynne larson robe","larson clothiers"}},{q="Warum möchte Wynne Larson, dass Ihr die Robe mit Stolz tragt?",a="Wynne betrachtet die Robe als eine ihrer besten Schöpfungen. Sie bittet Abenteurer, von Larson Clothiers zu erzählen, wenn andere die Handwerkskunst bewundern, und so als lebende Werbung für ihren Laden zu wirken.",al={"warum anderen von larson erzählen","larson werbung","wynne dialog"}},{q="Wo befindet sich Larson Clothiers?",a="Larson Clothiers liegt im Magierviertel von Sturmwind, nahe den Akademien und Heiligtümern, in denen sich Zauberwirker der Allianz versammeln.",al={"larson laden standort","wo ist wynne larson","schneiderei im magierviertel"}},{q="Was für ein Gewand ist eine Managewirkte Robe?",a="Die Managewirkte Robe ist ein verzaubertes Stoffgewand für Magiekundige. Sie ist so geschneidert, dass sie mystische Energien kanalisiert und auf gefährlichen Reisen zweckmäßig bleibt.",al={"managewirkte robe hintergrundgeschichte","was ist die managewirkte robe","was bewirkt die robe"}},{q="Ist dies Teil einer längeren Questreihe?",a="Ja. Dies ist der Abschluss einer Magierquestreihe, die bei Jennea Haubitz beginnt. Nachdem Ihr einen Manariss im Blue Recluse untersucht habt, sammelt Ihr Leinen und aufgeladene Rissedelsteine, damit Wynne Larson Eure Robe fertigen kann.",al={"managewirkte robe questreihe","robe questreihe","ende der questreihe"}},{q="Welche Fraktion kann diese Quest annehmen?",a="Nur Mitglieder der Allianz können sie annehmen. Wynne Larson arbeitet ausschließlich in Sturmwind, der Hauptstadt der Allianz.",al={"allianz oder horde robe","kann die horde die managewirkte robe erhalten","fraktionsvoraussetzung"}}},fp="14,176,16.323.0,13.352.0,30.94.0,59.193.0,34.127.0,41.162.0,35.182.0,38.114.0"}
P.entries["quest:1942"] = {n="Astralknotengewand",s="In Sturmwind webt Wynne Larson makellose Spinnenseide zu einem Gewand für gefährliche Reisen und Empfänge der feinen Gesellschaft. Ein Abenteurer bringt ihr seltene Seide aus der Wildnis, und sie verarbeitet sie zu einem magischen Gewebe.",h="In Sturmwind webt Wynne Larson makellose Spinnenseide zu einem Gewand für gefährliche Reisen und Empfänge der...",kw={"astralknotengewand","stoffrüstung","das magierviertel","makellose spinnenseide","seidenrobe","sturmwind","schneiderei","wynne larson"},ang={["class:Mage"]="Als Magier erkennt Ihr in diesem Gewand die arkane Würde Sturmwinds, mit praktischen Verzauberungen für Reisen jenseits der befestigten Mauern des Königreichs.",["faction:Alliance"]="Als Streiter der Allianz findet Ihr Handwerkskunst aus Sturmwind, die sich gleichermaßen für königliche Hallen und gefährliche Fronten eignet.",["profession:Tailoring"]="Wynne Larsons Arbeit veredelt makellose Spinnenseide zu prächtiger Mode."},sec={{t="Der Witz einer Weberin",b="Im Magierviertel von Sturmwind versorgen Schneider die arkane Elite und Adlige auf Besuch. Wynne Larson webt makellose Spinnenseide zu strapazierfähigen, verzauberten Gewändern. Ihr verspielter Humor zeigt sich, wenn sie scherzt, einige kostbare Reste für ihre eigene Garderobe zurückzubehalten, bevor sie ihr fertiges Werk übergibt."},{t="Vielseitige Eleganz",b="Stofftragende Zauberwirker schätzen das Astralknotengewand für seine Widerstandskraft und Eleganz. Seine Seide stammt von gefährlichen Spinnen, und sein Gewebe ist dafür gemacht, Kämpfen standzuhalten. Es bewahrt das gepflegte Erscheinungsbild, das bei förmlichen Banketten in Burg Sturmwind erwartet wird."}},faq={{q="Was ist das Astralknotengewand?",a="Wynne Larson fertigt das Astralknotengewand in Sturmwind aus makelloser Spinnenseide. Es ist für stofftragende Zauberkundige gedacht, die sich Kämpfen stellen oder Anlässe der feinen Gesellschaft besuchen.",al={"was ist das astralknotengewand","astralknotenrobe","astralknotengewänder"}},{q="Wer fertigt das Astralknotengewand?",a="Wynne Larson, eine Schneiderin im Magierviertel von Sturmwind, fertigt das Gewand, wenn sie die benötigten exotischen Materialien erhält.",al={"wer fertigt astralknoten","wynne larson quest","astralknoten schneider"}},{q="Welche Materialien werden benötigt, um dieses Gewand fertigzustellen?",a="Das Gewand erfordert makellose Spinnenseide, die von tödlichen Spinnen in den wilden Regionen der Welt gesammelt wird. Die Schneiderkunst bewahrt die natürliche Festigkeit der Seide und ihre Eignung für Verzauberungen.",al={"materialien für astralknoten","benötigte spinnenseide","wie wird es hergestellt"}},{q="Warum scherzt Wynne Larson darüber, übrig gebliebene Seide zu behalten?",a="Wynne scherzt darüber, das Gewand kurz zu schneidern, damit sie einige Reste der seltenen, begehrten Spinnenseide behalten kann. Sie liefert das fertige Werk vollständig ab.",al={"hat sie meine seide gestohlen","wynne larson scherz","kurze robe"}},{q="Wo in Sturmwind findet diese Schneiderarbeit statt?",a="Die Schneiderarbeit findet im Magierviertel von Sturmwind statt, einem Viertel voller Gelehrter, Arkanisten und Gewandschneider, die sich auf verzauberte Stoffe verstehen.",al={"wo ist wynne larson","astralknoten ort","wo astralknoten abgeben"}},{q="Wer trägt üblicherweise das Astralknotengewand?",a="Magier der Allianz bevorzugen das Astralknotengewand wegen seines leichten, schützenden Gewebes und seines würdevollen Erscheinungsbilds.",al={"wer nutzt astralknoten","für welche klasse ist das","wer trägt es"}}},fx={["96918ee1"]={q="Warum fertigt Wynne Larson das Astral Knot Garment an?",a="Wynne Larson ist eine geschickte Schneiderin in Sturmwind, die sich bereit erklärt, das Gewand als Krönung Eurer Bemühungen zu weben. Nachdem sie Euch durch gefährliche Länder geschickt hat, um seltene Komponenten wie Makellose Spinnenseide zu sammeln, ist sie stolz darauf, außergewöhnliche Kleidung für Magieanwender zu fertigen, die praktischen Schutz mit exquisiter, formeller Eleganz verbindet.",al={"warum fertigt wynne larson das gewand an","wynne larson motiv astral knot garment","warum fertigt wynne das gewand"}}},fp="19,217,14.294.0,18.245.0,32.180.0,35.110.0,53.172.0,56.144.0,50.134.0,44.102.0"}
P.entries["quest:1943"] = {n="Gespräch mit Deino",s="In Orgrimmar ruft Deino vielversprechende Magier der Horde dazu auf, ihre Kunst voranzubringen. Die Trollmagierin wirkt im Tal der Geister und sucht einen Adepten für wichtige Aufgaben. Ihr Ruf eröffnet einen Weg zu tieferen Studien und Pflichten in ganz Kalimdor.",h="In Orgrimmar ruft Deino vielversprechende Magier der Horde dazu auf, ihre Kunst voranzubringen.",kw={"anastasia hirschbrunn","darkbriar lodge","deino","magierquest","orgrimmar","quithas","tal der geister","waters of xavian"},ang={["class:Mage"]="Als Magier vertieft Ihr Eure arkane Ausbildung und begegnet hochrangigen Zauberwirkern in Orgrimmar.",["faction:Horde"]="Als Mitglied der Horde folgt Ihr einem Ruf, der Ausbilder in Lordaeron und Durotar mit Orgrimmars arkanen Anführern verbindet.",["race:Troll"]="Als Troll erlebt Ihr die konzentrierte arkane Disziplin, die einige wenige unter den Dunkelspeer ausüben."},sec={{t="Ein Ruf nach Orgrimmar",b="Magier der Horde verfeinern ihre arkanen Fähigkeiten unter der Obhut ihrer Ausbilder. Wenn ein Schüler für anspruchsvollere Aufgaben bereit ist, weist ein Mentor wie Anastasia Hirschbrunn in der Unterstadt den Weg nach Orgrimmar. Dort, im Trollviertel, warten Fachwissen und gefährliche Aufgaben."},{t="Das Tal der Geister und die Darkbriar Lodge",b="Deino lebt in der Darkbriar Lodge im Tal der Geister von Orgrimmar. Neben den vielen Hexendoktoren und Priestern studieren nur wenige Dunkelspeer arkane Magie, was Deino zu einer Autorität in der Hauptstadt macht. Ihre Arbeit betrifft Magier der Horde über örtliche Belange hinaus. Sie sucht ehrgeizige Zauberwirker, die bereit sind, sich fern der Heimat Gefahren zu stellen."}},faq={{q="Wer schickt Euch zu Deino?",a="Magierlehrer wie Anastasia Hirschbrunn im Magieviertel der Unterstadt schicken angehende Magier nach Orgrimmar, sobald deren Fähigkeiten ausreichen.",al={"questgeber","wer startet das","wo gibt es gespräch mit deino"}},{q="Wo finde ich Deino?",a="Ihr findet Deino in der Darkbriar Lodge im Tal der Geister auf der Westseite von Orgrimmar.",al={"deino standort","wo ist deino","darkbriar lodge standort"}},{q="Warum braucht Deino Unterstützung?",a="Deino beaufsichtigt Forschungen und Aufgaben, die für Magier der Horde wichtig sind. Sie schickt fähige Zauberwirker in gefährliche Länder, um seltene magische Ressourcen zu suchen.",al={"warum deino hilfe braucht","was will deino"}},{q="Was geschieht, nachdem ich mich bei Deino gemeldet habe?",a="Wenn Ihr Euch bei Deino meldet, erklärt sie ihre Arbeit und schickt Euch los, um die Waters of Xavian zu sammeln.",al={"nächste quest","was kommt danach","folgequest"}},{q="Ist diese Quest für alle Klassen verfügbar?",a="Nein. Nur Magier der Horde erhalten Deinos Ruf als Teil ihrer Klassenausbildung.",al={"nur für magier","auch für hexenmeister","klassenbeschränkung"}},{q="Sind Trollmagier in der Horde weit verbreitet?",a="Arkane Magie ist unter Dunkelspeertrollen weniger verbreitet als Schamanismus, Voodoo oder der Dienst an den Loa. Deino zeigt, dass einige Trolle das formale Studium arkaner Kräfte gemeistert haben.",al={"trolle mit arkaner magie","geschichte der dunkelspeermagier"}}},fx={["2e9f17ef"]={q="Warum schicken die Magierlehrer Euch zu Deino?",a="Während Eure Beherrschung der arkanen Künste wächst, erkennen Eure Mentoren in den Hauptstädten, dass tiefere Geheimnisse jenseits der Standardausbildung auf Euch warten. Die Troll-Magierin Deino in Orgrimmar beaufsichtigt fortgeschrittene Unternehmungen, die für die kollektive Gesellschaft der Magier in der Horde von entscheidender Bedeutung sind. Lehrer wie Anastasia Hirschbrunn in der Unterstadt verweisen vielversprechende Praktizierende an sie, damit Ihr zu Angelegenheiten beitragen könnt, die für Euer gemeinsames Handwerk lebenswichtig sind.",al={"warum zu deino schicken","motiv von anastasia hirschbrunn","warum schickt mich anastasia hirschbrunn"}}},fp="16,223,22.271.0,41.309.0,34.140.0,23.98.0,31.142.0,38.93.0,39.79.0,36.175.0"}
P.entries["quest:1944"] = {n="Wasser von Xavian",s="In Eschental sucht Deino Wasser aus Xavian, um die verbliebene arkane Macht der Stadt zu erforschen. Sie schickt ihren Lehrling aus, eine Probe aus dem Becken unterhalb ihres höchsten Wasserfalls zu schöpfen.",h="In Eschental sucht Deino Wasser aus Xavian, um die verbliebene arkane Macht der Stadt zu erforschen.",kw={"eschental","deino","fläschchen","magierquest","orgrimmar","satyr","splintertree","wasser von xavian","xavian"},ang={["class:Mage"]="Als Magier der Horde erforscht Ihr arkane Reagenzien, indem Ihr Euch in die feindliche Wildnis wagt, um sie zu sammeln.",["faction:Horde"]="Als Mitglied der Horde könnt Ihr den Splitterholzposten als nächstgelegenen Ausgangspunkt im östlichen Eschental nutzen, bevor Ihr durch die von Satyren heimgesuchte Wildnis um Xavian reist."},sec={{t="Die Neugier einer Magierin",b="Deino, eine Trollmagierin im Tal der Geister in Orgrimmar, durchsucht Kalimdor nach ursprünglichen arkanen Spuren. Nun gilt ihre Aufmerksamkeit Xavian, einer uralten Nachtelfenstadt unter dem östlichen Blätterdach von Eschental. Gelehrte sagen, dass die Stadt vor der Zerschlagung großes magisches Wissen beherbergte. Sie glauben, dass ihre Gewässer noch immer arkane Macht bergen, die heutige Magier zu verstehen hoffen."},{t="Die Ruinen von Xavian",b="Xavian liegt in Trümmern, überrannt von wilden, verderbten Satyren, die ihr Gebiet gegen Außenstehende verteidigen. Um das Wasser zu erreichen, passiert Ihr Satyrnaar und durchquert gefährliche Wasserläufe, wobei Ihr umherstreifenden Bestien und dämonischen Wächtern ausweicht. Deino benötigt eine Probe aus dem Becken am Fuße des höchsten Wasserfalls der Stadt."}},faq={{q="Wer ist Deino?",a="Deino ist eine Trollmagierlehrerin und Gelehrte im Tal der Geister in Orgrimmar. Sie unterrichtet Magier der Horde und erforscht Relikte der uralten Magie Kalimdors.",al={"wer vergibt wasser von xavian","deino orgrimmar"}},{q="Wo liegt Xavian?",a="Xavian ist eine verfallene Stadt im Nordosten von Eschental, nördlich vom Splitterholzposten und nordwestlich von Satyrnaar.",al={"xavian standort","wo liegt xavian","xavian finden"}},{q="Warum will Deino dieses Wasser?",a="Deino will die verbliebene arkane Macht des Wassers erforschen. Gelehrte sagen, dass Xavian großes magisches Wissen beherbergte, und sie benötigt eine frische Probe von der Quelle des Wasserfalls, um deren Eigenschaften zu untersuchen.",al={"warum wasser aus xavian holen","zweck des wassers aus xavian"}},{q="Welche Gefahren bewachen die Ruinen von Xavian?",a="Satyren haben Xavian überrannt. Diese dämonischen, verderbten Wesen verabscheuen ungebetene Besucher und verteidigen ihr Gebiet gegen Eindringlinge.",al={"xavian feinde","wer kontrolliert xavian"}},{q="Wo genau wird die Wasserprobe gesammelt?",a="Ihr entnehmt die Probe dem Becken am Fuße von Xavians höchstem Wasserfall und füllt sie in Deinos Fläschchen.",al={"wasserfall standort","wo fläschchen füllen","xavian wasserfall"}},{q="Wie geht es weiter, nachdem Ihr Deino die Probe gebracht habt?",a="Nachdem Ihr die Probe zurückgebracht habt, schickt Deino Euch aus, die Dryaden in Eschental zu studieren.",al={"wasser von xavian folgequest","nächste quest nach wasser von xavian"}}},fx={["6a4223ea"]={q="Wozu dient die Wasserprobe von Xavian?",a="Die uralte Stadt Xavian ist unter Gelehrten für ihr vergessenes Wissen legendär, und ihr Wasser soll über gewaltige magische Kräfte verfügen. Deino möchte eine unverfälschte Probe, die direkt vom Fuß des höchsten Wasserfalls der Stadt geschöpft wurde, damit sie ihre verborgenen arkanen Eigenschaften zurück in Orgrimmar untersuchen kann.",al={"was bewirkt xavian-wasser","warum xavian-wasser sammeln","verwendung der xavian-wasserprobe"}}},fp="16,174,18.362.0,19.301.0,13.145.0,24.105.0,31.190.0,39.119.0,44.109.0,52.78.1"}
P.entries["quest:1945"] = {n="Lachende Schwestern",s="Im Eschental wird Dryadenhaar für eine machtvolle Robe gesucht. Am Wegekreuz braucht der erfahrene Trollschneider Kil'hala die verzauberten Locken, um eine Magierrobe zu weben, während Magier der Horde gegen die einheimischen Verteidiger des Waldes vorrücken.",h="Im Eschental wird Dryadenhaar für eine machtvolle Robe gesucht.",kw={"eschental","das wegekreuz","deino","dryade","haar","kil'hala","lachende schwestern","rajenbaum","hexenmeisterrobe"},ang={["class:Mage"]="Als Magier erlebt Ihr, wie die heiligen Waldgeister des Eschentals für arkane Handwerkskunst ausgebeutet werden, als Teil eines Initiationsritus.",["faction:Horde"]="Als Mitglied der Horde greift Ihr die Dryaden des Eschentals an und verschärft den Konflikt mit den heiligen Waldhütern, die mit den Nachtelfen verbündet sind.",["profession:Tailoring"]="Als Schneider erlebt Ihr die seltene Kunst, lebendige magische Fasern zu Stoffrüstung zu verweben, durch die anspruchsvolle Technik, die Kil'hala am Wegekreuz ausübt."},sec={{t="Das Arkane verweben",b="Nachdem Ihr Wasser aus Xavian beschafft habt, schickt Deino in Orgrimmar angehende Magier los, ihre eigenen verzauberten Gewänder herzustellen. Diese arkanen Gewänder benötigen Materialien, die von roher Magie berührt wurden. Dryadenlocken tragen die uralte Lebenskraft des Waldes in sich und geben Magiern, was sie zum Weben kunstvoller Roben brauchen, die Zauberwirker schützen und stärken."},{t="Pirsch bei Rajenbaum",b="Nahe Rajenbaum im Eschental suchen Magier nach den Lachenden Schwestern. Diese flinken Dryaden sind mit den Nachtelfen verbündet und verteidigen ihre Haine erbittert gegen Holzfäller und Fremde. Sie werden ihr Haar den Zauberwirkern der Horde nicht freiwillig geben. Also werden die Locken unter den uralten Bäumen mit Gewalt genommen."},{t="Das Vorrecht von The Weaver",b="Die Locken gelangen südwärts über die Grenze zur staubigen Siedlung des Wegekreuzes im Brachland. Dort nimmt der Trollschneider Kil'hala sie ohne Reue entgegen. Kil'hala nimmt den Verlust der Waldkreaturen mit einem Hauch Ironie zur Kenntnis und verarbeitet dann die verzauberten Strähnen. Die Macht der Horde verlangt Entschlossenheit."}},faq={{q="Wer erteilt die Quest zur Jagd auf die Lachenden Schwestern?",a="Deino, ein Trollmagier in Darkbriar Lodge in Orgrimmar, schickt Magier los, alles Nötige für ihre Magierklassenroben zu sammeln.",al={"wer gibt die quest lachende schwestern","lachende schwestern questgeber","deino quest"}},{q="Was sind die Lachenden Schwestern?",a="Die Lachenden Schwestern sind Dryaden, Töchter des Halbgottes Cenarius. Mit den Oberkörpern von Nachtelfenfrauen und rehkalbähnlichen Unterkörpern schützen sie die Wälder und heiligen Lichtungen des Eschentals.",al={"was ist eine lachende schwester","lachende schwester dryade","sind lachende schwestern dryaden"}},{q="Wo sind die Lachenden Schwestern zu finden?",a="Sie streifen durch den Wald nahe Rajenbaum und die Lichtung der Laughing Sister im mittleren Eschental, nicht weit von der Handelsstraße.",al={"lachende schwestern fundort","wo sind lachende schwestern","wo lachende schwestern finden"}},{q="Warum braucht Kil'hala Dryadenhaar?",a="Dryadenhaar trägt eine natürliche Verzauberung in sich und eignet sich deshalb als Garn für Kil'halas besondere Roben, die mit Magie schwingen und den arkanen Künsten dienen.",al={"warum dryadenhaar","warum haar der lachenden schwestern","wofür ist das haar"}},{q="Wo liefere ich das gesammelte Haar ab?",a="Bringt das Haar zu Kil'hala, einem Schneider am Wegekreuz im Brachland.",al={"wo ist kilhala","lachende schwestern abgeben","wegekreuz schneider hexenmeister"}},{q="Was geschieht, nachdem Kil'hala das Haar entgegengenommen hat?",a="Kil'hala bearbeitet das Haar kurz und bietet dann Nether-lace Garment an, um die Robe fertigzustellen.",al={"nächste quest nach lachende schwestern","nach lachende schwestern","nether-lace garment folgequest"}}},fx={["6db1d5c5"]={q="Warum schickt Euch Deino los, um die Laughing Sisters zu jagen?",a="Deino belohnt Eure fortwährenden Dienste für die Magier der Horde, indem sie die Anfertigung spezieller Roben in die Wege leitet. Anstatt sie Euch einfach zu schenken, verlangt sie, dass Ihr die exotischen magischen Reagenzien selbst sammelt, und schickt Euch tief in das Eschental, um den Verteidigern des Waldes Dryadenhaar abzuringen.",al={"warum will deino haare der laughing sisters","deino motiv laughing sisters","warum laughing sisters haare sammeln"}}},fp="16,223,18.311.0,18.298.0,24.301.0,51.117.0,30.188.0,40.127.0,34.161.0,49.69.0,43.89.0"}
P.entries["quest:1946"] = {n="Netherspitzengewand",s="Am Wegekreuz verwebt Kil'hala Dryadenhaar zu verzaubertem Stoff für Zauberwirker. Dieses Gewand vollendet seine spezialisierte Arbeit im Brachland.",h="Am Wegekreuz verwebt Kil'hala Dryadenhaar zu verzaubertem Stoff für Zauberwirker.",kw={"eschental","brachland","das wegekreuz","deino","kil'hala","laughing sisters","magier","netherspitze"},ang={["class:Mage"]="Als Magier erhaltet Ihr ein Gewand, geprägt von Prüfungen in der Wildnis des Eschentals und Kil'halas Handwerkskunst unter Deinos Anleitung.",["faction:Horde"]="Als Mitglied der Horde helft Ihr, ihre Zauberwirker mit Materialien aus Kalimdors heiligen Wäldern auszustatten. Diese Arbeit ist Teil des anhaltenden Ringens zwischen der Horde und den Verteidigern der Wälder des Eschentals.",["profession:Tailoring"]="Als Schneider könnt Ihr sehen, wie Dryadenhaar zu Stoff mit innewohnendem magischem Schutz wird."},sec={{t="Das Weben der Netherspitze",b="Am Wegekreuz im Brachland webt Kil'hala Netherspitze aus den Locken der Laughing Sisters. Die Dryaden leben im Eschental, wo ihr Haar für sein Handwerk gesammelt wird. Er bindet den Waldzauber dieser seltenen, resonanten Locken in bequemen und strapazierfähigen Stoff."},{t="Gunst in Orgrimmar",b="Kil'hala strebt mit seinem Handwerk nach mehr als guter Arbeit. Er hofft, die Gunst von Deino zu gewinnen, einer angesehenen Trollmagierin im Tal der Geister in Orgrimmar. Indem er außergewöhnliche Gewänder für angehende Zauberkundige fertigt, hofft er, Deinos Wohlwollen zu gewinnen und zu bewahren."}},faq={{q="Was ist Netherspitze?",a="Netherspitze ist ein verzauberter Stoff, den Kil'hala aus den Haarsträhnen der Laughing Sisters webt. Der Stoff ist widerstandsfähig und trägt ihren Waldzauber in sich.",al={"netherspitzenstoff","was ist das netherspitzengewand"}},{q="Wer fertigt das Netherspitzengewand?",a="Kil'hala fertigt das Gewand an seinem Arbeitsplatz am Wegekreuz im Brachland, sobald er das benötigte Dryadenhaar aus dem Eschental hat.",al={"wer fertigt netherspitze","kil'hala netherspitze"}},{q="Warum erwähnt Kil'hala Deino?",a="Deino ist eine angesehene Trollmagierin, die im Tal der Geister in Orgrimmar lebt. Kil'hala hofft, ihre Gunst zu bewahren, und glaubt, dass Eure Zufriedenheit mit seiner Schneiderkunst ein gutes Licht auf ihn werfen wird.",al={"wer ist deino","warum deino erwähnen"}},{q="Woher stammen die Materialien für das Gewand?",a="Das Grundmaterial des Gewands ist Haar der Laughing Sisters, Dryaden, die überall in den Wäldern des Eschentals zu finden sind.",al={"netherspitze materialien","dryadenhaar stoff"}},{q="Für wen wird dieses Gewand gefertigt?",a="Das Gewand ist vor allem für Zauberwirker bestimmt, insbesondere für Magier in der Ausbildung. Seine Roben kanalisieren arkane Energien, ohne die Bewegung einzuschränken.",al={"wer trägt das netherspitzengewand","netherspitze klasse"}},{q="Wo befindet sich Kil'hala?",a="Kil'hala lebt am Wegekreuz, der zentralen Siedlung im Herzen des Brachlands.",al={"kil'hala standort","wo ist kil'hala"}}},fp="19,144,23.287.0,20.243.0,20.151.0,35.126.0,32.185.0,50.112.0,29.132.0,26.85.0"}
P.entries["quest:1947"] = {n="Reise in die Marschen",s="Eure Klasse schickt Euch in die Düstermarschen, wo Tabethas Wissen Euch helfen kann, Euren Zauberstab zu erlangen.",h="Eure Klasse schickt Euch in die Düstermarschen, wo Tabethas Wissen Euch helfen kann, Euren Zauberstab zu...",kw={"hütte","düstermarschen","reise in den sumpf","die stonemaul ruinen","tabetha","theramore","zauberstab"},sec={{t="Tabethas Hütte",b="Westlich von Theramore und direkt nördlich der Stonemaul Ruinen lebt Tabetha in einer Hütte. Eure Klasse bittet Euch, mit der Einsiedlerin zu sprechen und von ihrem umfassenden Wissen zu lernen."}},faq={{q="Wer ist Tabetha?",a="Tabetha ist eine Einsiedlerin in den Düstermarschen, die für ihr umfassendes Wissen bekannt ist.",al={"tabetha","einsiedlerin im sumpf","wer ist die einsiedlerin"}},{q="Wo steht Tabethas Hütte?",a="Tabethas Hütte steht westlich von Theramore und direkt nördlich der Stonemaul Ruinen.",al={"tabethas standort","wo ist tabetha","tabethas hütte"}},{q="Warum werde ich zu Tabetha geschickt?",a="Ein Gespräch mit Tabetha ist Euer erster Schritt, um den Zauberstab Eurer Klasse zu erlangen.",al={"warum tabetha","zauberstabquest","meinen zauberstab erlangen"}}},fp="20,98,19.164.0,15.70.0,29.79.0,31.69.0"}
P.entries["quest:195"] = {n="Beherrschen der Raptorenjagd",s="Im Schlingendorntal schickt Hemet Nesingwary Jäger auf die Jagd nach tödlicherer Beute. Nach ihrer ersten Raptorjagd bittet er sie, zehn Lashtail Raptors aufzuspüren und zu erlegen.",h="Im Schlingendorntal schickt Hemet Nesingwary Jäger auf die Jagd nach tödlicherer Beute.",kw={"basislager grom'gol","hemet nesingwary","jagd","lashtail raptor","beherrschen der raptorenjagd","schlingendorntal"},ang={["class:Hunter"]="Als Jäger stellt Ihr in Hemet Nesingwarys Prüfungen Eure Disziplin gegen die tödlicheren Raubtiere auf die Probe, die das Schlingendorntal durchstreifen."},sec={{t="Eine größere Herausforderung",b="Nördlich des Basislagers Grom'gol schickt Hemet Nesingwary Jäger ins dichte Dschungeldickicht. Nach ihrer ersten Raptorjagd erwartet er, dass sie ihre Konzentration und ihr Geschick an tödlicherer Beute beweisen. Zehn wilde Lashtail Raptors müssen aufgespürt und erlegt werden."},{t="Trophäen über dem Kamin",b="Hemet Nesingwary begrüßt die aus dem Dschungel zurückkehrenden Jäger mit herzlicher Anerkennung. Für den erfahrenen Jäger sind diese gefährlichen Raubtiere würdige Beute und Trophäen für den Platz über dem Kamin. Er bereitet den Jäger auf größere Herausforderungen vor."}},faq={{q="Wer bietet diese Jagdherausforderung an?",a="Hemet Nesingwary, der berühmte Großwildjäger, bietet die Herausforderung in seinem Expeditionslager im nördlichen Schlingendorntal an.",al={"wer startet beherrschen der raptorenjagd 2","beherrschen der raptorenjagd questgeber","wo beherrschen der raptorenjagd annehmen"}},{q="Welche Beute sollt Ihr jagen?",a="Ihr müsst zehn Lashtail Raptors im Dschungel aufspüren und erlegen.",al={"welche raptoren töten","welche raptorenquest","lashtail raptor jagdziel"}},{q="Wo sind die Lashtail Raptors zu finden?",a="Lashtail Raptors streifen durch das wilde Dickicht des nördlichen Schlingendorntals, besonders nördlich des Basislagers Grom'gol.",al={"wo sind lashtail raptors","lashtail raptor fundort","wo lashtails finden"}},{q="Wo steht diese Jagd in Nesingwarys Prüfungen?",a="Dies ist die zweite Prüfung in Nesingwarys Raptorenreihe. Sie folgt auf die einführende Jagd Beherrschen der Raptorenjagd und führt zu einem dritten Teil der Herausforderung.",al={"was kommt vor dieser raptorjagd","beherrschen der raptorenjagd abfolge","raptorenquestreihe"}}},fp="14,160,19.240.0,23.221.1,34.122.0,40.59.0,37.110.0,50.147.0"}
P.entries["quest:1950"] = {n="Der Knüller schlechthin",s="Nahe der Illusionenrennbahn hat Magus Tirth die Worte vergessen, die seine versiegelte Geldkassette öffnen. Sein Lehrling Johnson ist irgendwo an der Rennstrecke verschwunden, und Tirth braucht das Zauberbuch darin.",h="Nahe der Illusionenrennbahn hat Magus Tirth die Worte vergessen, die seine versiegelte Geldkassette öffnen.",kw={"der knüller schlechthin","johnson","magus tirth","illusionenrennbahn","die schimmernde ebene","geldkassette","tausend nadeln","zauberstab quest"},ang={["class:Mage"]="Als Magier erfahrt Ihr im Umgang mit Tirth, welche Gefahren Verwandlungsflüche bergen und wie zerstreut mächtige Gelehrte sein können."},sec={{t="Ein Magus und sein Gedächtnis",b="Magus Tirth lebt auf dem rissigen Salzboden der Schimmernden Ebene in Tausend Nadeln. Er ist ein exzentrischer Zauberwirker, dessen arkanes Wissen und Bücher Magier anziehen, die sich weiterbilden wollen. Geduld hilft im Umgang mit ihm. Tirth verlässt sich bei alltäglichen Einzelheiten auf einen Assistenten, selbst bei den gesprochenen Passwörtern, die seine arkanen Vorräte schützen. Nun ist ein Buch der Macht weggeschlossen, und die magischen Worte sind ihm völlig entfallen."},{t="Falsches Spiel",b="Die Goblins und Gnome, die die Illusionenrennbahn betreiben, können Euch erzählen, was mit Johnson, dem Lehrling von Magus Tirth, geschehen ist. Tirth verwandelte Johnson in ein gewöhnliches Huhn, und nun wandert der Lehrling über die Salzebene, unfähig zu sprechen. Wenn Ihr Euch nähert, lichtet sich der magische Nebel für einen Augenblick. Johnson kann das fehlende Passwort herausgackern."}},faq={{q="Wer ist Magus Tirth?",a="Magus Tirth ist ein zurückgezogen lebender menschlicher Zauberer nahe der Illusionenrennbahn auf der Schimmernden Ebene in Tausend Nadeln. Magier suchen sein fortgeschrittenes arkanes Wissen, um ihre Kunst zu verfeinern.",al={"tirth hintergrund","wer ist magus tirth","tirth schimmernde ebene"}},{q="Warum braucht Tirth das Passwort für seine eigene Kassette?",a="Tirth verschloss seine Geldkassette mit einer gesprochenen Formel und verließ sich darauf, dass sein Assistent sich solche alltäglichen Einzelheiten merkte. Als sein Lehrling verschwand, vergaß Tirth die Worte.",al={"warum tirth die worte vergaß","tirth geldkassette passwort"}},{q="Wohin ist der Lehrling verschwunden?",a="Johnson wandert nahe der Rennstrecke östlich von Tirths Lager umher. Ihn zu finden ist schwieriger, weil Tirth ihn in ein Huhn verwandelt hat.",al={"tirths assistenten finden","wo ist lehrling johnson","johnson aufenthaltsort"}},{q="Warum wurde der Lehrling in ein Huhn verwandelt?",a="Tirth verfluchte Johnson und vergaß dann, dass er es getan hatte. Als er erfuhr, was aus seinem Assistenten geworden war, nahm er vage an, Johnson habe es als undankbarer Schüler verdient.",al={"warum johnson ein huhn ist","tirth verwandlung lehrling"}},{q="Was befindet sich in Tirths Geldkassette?",a="Tirths Geldkassette enthält ein Buch der Rituale, Anleitungen, die für die Weiterbildung eines Magiers unerlässlich sind, und magische Gerätschaften.",al={"tirth geldkassette inhalt","welches buch ist in der truhe"}},{q="Wer kann diese Aufgabe übernehmen?",a="Nur Magier, die besondere Unterweisung und Materialien zur Herstellung eines mächtigen Zauberstabs suchen, können sich dieser Prüfung stellen.",al={"können nichtmagier der knüller schlechthin erledigen","ist diese quest nur für magier"}}},fx={["25c94f6f"]={q="Warum schickt Euch Magus Tirth, anstatt den Lehrling selbst zu finden?",a="Magus Tirth hat nicht die Absicht, selbst die schimmernde Ebene zu durchkämmen, wenn Ihr diejenige Person seid, die um sein Wissen bettelt. Ihr kamt auf der Suche nach seinem seltenen magischen Folianten, und da er ohne seinen vermissten Assistenten die verbale Inkantation zum Öffnen seiner eigenen magisch versiegelten Geldkassette nicht mehr weiß, macht er die Hilfe für ihn zum Preis für seine Unterstützung.",al={"warum schickt sie mich","warum findet tirth johnson nicht","warum muss ich den lehrling finden"}}},fp="13,192,22.417.0,9.319.1,19.165.0,48.164.0,28.119.1,45.169.1,33.123.0,28.105.0"}
P.entries["quest:1959"] = {n="Meldung bei Anastasia",s="In ganz Kalimdor und den Östlichen Königreichen werden Magier der Horde nach Unterstadt gerufen. Anastasia Hirschbrunn hat dort eine unbekannte magische Störung gespürt und braucht fähige Zauberwirker, um ihr nachzugehen.",h="In ganz Kalimdor und den Östlichen Königreichen werden Magier der Horde nach Unterstadt gerufen.",kw={"anastasia hirschbrunn","cain feuerlied","investigate the alchemist shop","magier","magieviertel","meldung bei anastasia","thurston xane","un'thuwa","unterstadt","uthel'nay"},ang={["class:Mage"]="Als Magier der Horde verlasst Ihr Euren regionalen Ausbildungsposten und reist nach Unterstadt. Tiefere arkane Geheimnisse und Gefahren liegen unter den Ruinen von Lordaeron.",["faction:Horde"]="Der Ruf bringt Verlassene und andere Magier der Horde zusammen, um ihre gemeinsamen Interessen zu schützen.",["race:Undead"]="Als Verlassener werdet Ihr ins Magieviertel von Unterstadt gerufen, um Euer junges Königreich vor arkanen Bedrohungen innerhalb seiner Mauern zu schützen."},sec={{t="Ein Ruf zur Arkanmagie",b="Magier der Horde in ganz Kalimdor und den Östlichen Königreichen hören denselben Ruf. Er erreicht jene, die auf den Höhen von Donnerfels studieren, in Durotars staubiger Hitze und inmitten der Ruinen von Lordaeron. Die Magier von Unterstadt haben eine unerklärliche Störung in ihrem Herrschaftsgebiet gespürt. Sie brauchen Hilfe, um herauszufinden, was sie bedeutet."},{t="Die Magierin von Unterstadt",b="Anastasia Hirschbrunn wacht im Magieviertel von Unterstadt über arkane Angelegenheiten. Die Magier dort haben seltsame Energien innerhalb der Stadt entdeckt, doch niemand weiß, ob die Magie harmlos oder feindselig ist. Anastasia braucht einen fähigen Magier, der der Sache im Stillen nachgeht. Die Untersuchung beginnt im Apothekarium."}},faq={{q="Wer ist Anastasia Hirschbrunn?",a="Anastasia Hirschbrunn ist eine Magierin der Verlassenen und Mentorin der arkanen Künste im Magieviertel von Unterstadt. Sie leitet neue Zauberwirker an und hält in der Hauptstadt der Verlassenen nach arkanen Störungen Ausschau.",al={"anastasia hirschbrunn hintergrundgeschichte","wer ist anastasia","hirschbrunn unterstadt"}},{q="Wo befindet sich Anastasia Hirschbrunn?",a="Anastasia Hirschbrunn befindet sich im Magieviertel, im nördlichen Bogen von Unterstadt. Sie gehört zu den Magielehrern und arkanen Forschern der Stadt.",al={"wo ist anastasia","hirschbrunn standort","anastasia unterstadt karte"}},{q="Warum werden Magier aus Donnerfels oder dem Brachland nach Unterstadt gerufen?",a="Die Magier von Unterstadt haben eine ungewöhnliche Störung entdeckt, und die Interessen der Horde in Lordaeron könnten gefährdet sein. Mentoren in Kalimdor schicken vielversprechende Schüler dorthin, um zu helfen und Erfahrungen mit komplexen magischen Phänomenen zu sammeln.",al={"warum nach unterstadt reisen","warum bei anastasia melden","donnerfels magierquest"}},{q="Was für eine Störung untersucht Anastasia?",a="Magier haben unerklärliche magische Schwankungen innerhalb von Unterstadt entdeckt. Anastasia Hirschbrunn weiß nicht, ob die Energie feindselig, zufällig entstanden oder harmlos ist, und beginnt deshalb eine behutsame Untersuchung.",al={"was für eine störung","magische störung unterstadt","was stimmt in unterstadt nicht"}},{q="Wer vergibt diese Quest?",a="Magierlehrer der Horde können Euch zu Anastasia schicken, sobald Ihr genug Erfahrung habt. Dazu gehören Uthel'nay in Orgrimmar, Thurston Xane in Donnerfels, Cain Feuerlied in Brill und Un'Thuwa in Sen'jin.",al={"wer vergibt meldung bei anastasia","questgeber meldung bei anastasia"}},{q="Was geschieht nach der Meldung bei Anastasia?",a="Nachdem Ihr mit Anastasia gesprochen habt und von ihr unterrichtet wurdet, schickt sie Euch los, um die Störung im Apothekarium der Stadt zu untersuchen. Ihr beginnt mit Investigate the Alchemist Shop.",al={"nächste quest nach meldung bei anastasia","meldung bei anastasia folgequest"}}},fx={["22ef3f4a"]={q="Warum schicken Euch die Magierlehrer zu Anastasia Hirschbrunn, anstatt sich selbst darum zu kümmern?",a="Eure Lehrer werden benötigt, um angehende Zauberwirker zu unterrichten und die mystische Aufsicht über die Siedlungen in Kalimdor aufrechtzuerhalten. Als die Nachricht eintraf, dass die Magier der Verlassenen Unterstützung bei der Untersuchung einer arkanen Anomalie in der Unterstadt benötigten, suchten die Lehrer nach fähigen, aufstrebenden Praktizierenden, die für Außeneinsätze bereit waren, anstatt ihre Lehrposten aufzugeben.",al={"warum schickt man mich zu anastasia","warum können die lehrer nicht in die unterstadt","warum soll ich mich bei anastasia melden"}}},fp="19,196,20.293.0,25.285.0,26.179.0,36.146.0,80.216.0,52.196.0,21.204.0,42.176.0"}
P.entries["quest:196"] = {n="Beherrschen der Raptorenjagd",s="Im Schlingendorntal schickt Euch Hemet Nesingwary auf die Jagd nach Jungle Stalkers. Zehn wachsame Raptoren stehen zwischen Euch und seiner bisher besten Jagd.",h="Im Schlingendorntal schickt Euch Hemet Nesingwary auf die Jagd nach Jungle Stalkers.",kw={"großwildjäger","arena der gurubashi","hemet nesingwary","jungle stalkers","beherrschen der raptorenjagd","schlingendorntal"},ang={["class:Hunter"]="Als Jäger stellt das Aufspüren wachsamer Jungle Stalkers Euer Geschick im Umgang mit Beute und Eure Treffsicherheit in der Wildnis unter Hemet Nesingwarys Aufsicht auf die Probe."},sec={{t="Eine listige Beute",b="Hemet Nesingwary schickt Euch auf die Jagd nach Jungle Stalkers, einer anspruchsvolleren Beute als den zuvor gejagten Raptoren. Sie sind wachsam und schwer aufzuspüren oder zu erlegen. Findet und erlegt zehn im Dschungel und kehrt dann ins Lager zurück. Hemet wird Euch einen Hinweis auf seine bisher beste Jagd geben."}},faq={{q="Wer bietet diese Jagd an?",a="Hemet Nesingwary, der Großwildjäger, bietet diese Jagd von seinem Lager im nördlichen Schlingendorntal aus an.",al={"questgeber","wer startet beherrschen der raptorenjagd 3","hemet nesingwary jagd"}},{q="Welche Bestien sollt Ihr aufspüren?",a="Ihr sollt zehn Jungle Stalkers aufspüren und töten, eine wachsame und schwer fassbare Raptorenart.",al={"welcher raptor","gesuchter raptor","welche raptoren töten"}},{q="Wo findet man Jungle Stalkers?",a="Jungle Stalkers durchstreifen das Schlingendorntal, besonders nördlich und westlich der Arena der Gurubashi.",al={"jungle stalker fundort","wo streifen jungle stalkers umher","jungle stalkers finden"}},{q="Was geht dieser Herausforderung voraus?",a="Diese Jagd folgt auf die zweite Stufe der Prüfungen im Beherrschen der Raptorenjagd, während Hemet Nesingwary sich weiter den örtlichen Raptorenarten widmet.",al={"vorausgesetzte quest","vorheriges beherrschen der raptorenjagd","welche quest kommt davor"}}},fp="14,128,14.247.0,21.101.0,39.87.0,32.90.0,33.127.0"}
P.entries["quest:1960"] = {n="Untersuchungen im Alchemistenladen",s="In Algernons Laden streifen unsichtbare Kreaturen zwischen den Alchemikalien umher. Anastasia Hirschbrunn schickt Magier der Horde, um sie sichtbar zu machen und einzufangen, bevor sie Schaden anrichten.",h="In Algernons Laden streifen unsichtbare Kreaturen zwischen den Alchemikalien umher.",kw={"algernon","anastasia hirschbrunn","das apothekarium","inkantation der manifestation","eindämmungskassette","magieviertel","rissbrut","unterstadt"},ang={["class:Mage"]="Als Magier erprobt Ihr Eure Beherrschung arkaner Kräfte mit Manifestationsinkantationen und Eindämmungsgefäßen und setzt dabei mehr als bloße Zerstörungskraft ein.",["race:Undead"]="Als Verlassene erlebt Ihr, wie die arkanen Gelehrten von Unterstadt die Stadt vor magischer Unterwanderung schützen, neben Apothekern, die sich auf Alchimie und Seuchenherstellung konzentrieren."},sec={{t="Eine Störung im Apothekarium",b="Anastasia Hirschbrunn schickt arkane Initianden, um eine Störung im Apothekarium zu untersuchen. Unsichtbare magische Kreaturen streifen zwischen Kesseln und Reagenzien durch Algernons Alchimieladen. Die Magierlehrerin von Unterstadt vermutet einen Riss im Fluss der Magie. Die Kreaturen müssen eingefangen werden, bevor sie schweren Schaden anrichten."},{t="Manifestation und Eindämmung",b="Anastasia gibt ihren Schülern eine Inkantation der Manifestation, um die unsichtbaren Kreaturen sichtbar zu machen, und robuste Eindämmungskassetten, um sie festzuhalten. Gewöhnliche Aufspürmethoden können Wesen aus reiner, roher arkaner Kraft nicht finden. Sobald die Rissbruten sichtbar sind, müssen sie geschwächt und in den Kassetten versiegelt werden, bevor sie sich weiter auflösen oder den arbeitenden Alchimisten schaden können."},{t="Unfall oder arkaner Angriff?",b="Anastasia will erfahren, woher die Kreaturen stammen. Ein spontaner Riss im Fluss der Magie ist beunruhigend, doch ein absichtlich verursachter Riss könnte einen koordinierten magischen Angriff auf die Hauptstadt der Verlassenen bedeuten. Die Gelehrten von Unterstadt werden die gefangenen Kreaturen untersuchen und feststellen, ob das Apothekarium einen Unfall erlitten hat oder einer gezielten Bedrohung gegenübersteht."}},faq={{q="Wer vergibt diese Quest und wo ist diese Person zu finden?",a="Anastasia Hirschbrunn, die Magierlehrerin, bietet diese Quest im Magieviertel von Unterstadt an.",al={"questgeber","wo anfangen","anastasias standort"}},{q="Wo befindet sich die Störung?",a="Die Störung befindet sich in Algernons Alchimieladen im Apothekarium von Unterstadt.",al={"wohin gehen","standort des alchimieladens","wo ist algernon"}},{q="Was sind das für Kreaturen, die durch den Laden streifen?",a="Die Kreaturen sind Rissbruten, unsichtbare Wesen aus konzentrierter magischer Energie, die durch eine Anomalie im örtlichen Fluss der Magie erschienen sind.",al={"was sind die monster","unsichtbare kreaturen","rissbruten"}},{q="Wie fangt Ihr die Kreaturen ein?",a="Ihr rezitiert die Inkantation der Manifestation im Laden, um die Rissbruten sichtbar zu machen, schwächt sie mit Zaubern und fangt sie dann mit einer Eindämmungskassette ein.",al={"wie einfangen","kassette benutzen","wie abschließen"}},{q="Warum will Anastasia diese Kreaturen lebend gefangen nehmen?",a="Anastasia und die Gelehrten von Unterstadt brauchen lebende Exemplare, um herauszufinden, ob der Riss in der Magie natürlich entstand oder durch einen absichtlichen Angriff einer äußeren magischen Macht auf die Stadt.",al={"warum einfangen","zweck der eindämmungskassetten","warum untersuchen"}},{q="Können auch andere Klassen als Magier diese Quest annehmen?",a="Nur Magier der Horde können teilnehmen; dies ist Teil ihrer frühen Ausbildung.",al={"nur magier","wer kann diese quest annehmen"}}},fx={["20993eae"]={q="Wozu dient die Inkantation der Manifestation?",a="Die Inkantation der Manifestation ist ein Zauberspruch, der auf eine Schriftrolle geschrieben und von Anastasia Hirschbrunn bereitgestellt wurde, um das Unsichtbare zu offenbaren. Die Wesen, die in Algernons Laden spuken, bestehen aus reiner magischer Energie und sind für das bloße Auge von Natur aus unsichtbar. Das Lesen der Inkantation innerhalb des Ladens reißt ihren Schleier der Verborgenheit weg und zwingt sie zur physischen Manifestation, sodass Ihr sie bekämpfen und unterwerfen könnt.",al={"zweck der inkantation der manifestation","warum inkantation der manifestation benutzen","was bewirkt die inkantation"}},["355e23e2"]={q="Wozu dient die Truhe mit Verwahrungskästen?",a="Die Truhe mit Verwahrungskästen enthält speziell geschützte Gefäße, die dazu gefertigt wurden, rohe magische Wesen zu binden. Da die Rissbruten im Apothekarium nicht einfach mit der Hand getragen werden können, müsst Ihr diese arkanen Kästen einsetzen, sobald die Kreaturen im Kampf geschwächt sind, um sie sicher darin einzuschließen, damit sie transportiert werden können, ohne sich aufzulösen.",al={"truhe mit verwahrungskästen","was sind verwahrungskästen","zweck von verwahrungskästen"}},["01d568c5"]={q="Wozu dient der Gefüllte Verwahrungskasten?",a="Jeder Gefüllte Verwahrungskasten enthält eine lebende Rissbrut, die aus Algernons Laden gefangen wurde. Anastasia Hirschbrunn benötigt drei dieser gefangenen Wesen, die unversehrt zurückgebracht werden müssen, damit die größten arkanen Gelehrten der Unterstadt sie untersuchen können, um herauszufinden, ob ihre plötzliche Manifestation ein versehentlicher Riss im Gefüge der Magie oder ein gezielter Angriff war.",al={"verwendung gefüllter verwahrungskasten","warum gefüllte kästen bringen","zweck gefüllter verwahrungskasten"}}},fp="30,153,33.330.0,29.345.0,27.342.1,46.83.0,33.88.0,42.144.0,33.149.0,55.184.0,43.69.0"}
P.entries["quest:1961"] = {n="Materialsammlung",s="In Unterstadt schickt Materialsammlung neue Magier der Horde in den Silberwald, um Manasmaragde aus Dalaran zu beschaffen. Sie brauchen auch Leinen für ihre ersten echten Magierroben.",h="In Unterstadt schickt Materialsammlung neue Magier der Horde in den Silberwald, um Manasmaragde aus Dalaran...",kw={"mühlenbern","anastasia hirschbrunn","manaedelstein aus dalaran","materialsammlung","josef gregorian","leinenstoff","magieviertel","spellfire robes","unterstadt"},ang={["class:Mage"]="Als Magier der Horde erreicht Ihr einen Meilenstein, wenn Ihr schlichte Lehrlingskleidung gegen maßgeschneiderte Roben eintauscht, in die erbeutete arkane Macht eingewoben ist.",["profession:Tailoring"]="Als Schneider verbindet Ihr schlichten Leinenstoff mit mächtigen Manasmaragden, um beständige verzauberte Gewänder herzustellen.",["race:Undead"]="Als Untoter erlebt Ihr die rücksichtslose Haltung der Verlassenen. Gemeinsame arkane Philosophien mit Dalarans Zauberern bringen keine Gnade, wenn diese sich als zu schwach erweisen, den Silberwald zu halten."},sec={{t="Ein Ritus arkanen Ranges",b="Initianden aus Unterstadt sammeln einen einfachen Leinenballen und mächtige Manasmaragde aus Dalaran für ihre ersten echten Roben. Diese Roben kennzeichnen ihren Rang und persönlichen Wert. Anastasia Hirschbrunn weist die Novizen an, die Rohstoffe für ein verzaubertes Gewebe zu sammeln."},{t="Pragmatismus der Verlassenen",b="Die Manasmaragde können weder gekauft noch heraufbeschworen werden. Magier aus Dalaran sind im ganzen Silberwald stationiert, besonders nahe Mühlenbern, und die Edelsteine müssen ihnen abgenommen werden. Anastasia Hirschbrunn sagt, Dalarans arkane Philosophien gleichen denen der Verlassenen. Doch Gefühlsduselei hat in Unterstadt keinen Platz. Für die Verlassenen verwirken Zauberer, die zu schwach sind, ihre Relikte zu verteidigen, ihre Schätze und ihr Leben."},{t="Der Schneider des Magieviertels",b="Josef Gregorian ist ein Schneider im Magieviertel von Unterstadt, zu dem der gesammelte Stoff und die Edelsteine gebracht werden. Ihm fehlt das magische Talent, um die makellose Qualität der verzauberten Steine Dalarans zu beurteilen. Doch er besitzt das seltene handwerkliche Geschick, ihre rohe Macht in die Roben einzuweben."}},faq={{q="Welchen Zweck hat Materialsammlung?",a="Der Ritus kennzeichnet den Übergang eines Magiers der Horde zu seinen ersten förmlichen, verzauberten Roben. Das Leinen und die Manasmaragde gehen an Josef Gregorian, einen Schneider, der daraus die Roben fertigt.",al={"warum materialsammlung erledigen","materialsammlung quest zweck","magierrobenquest unterstadt"}},{q="Warum schickt Anastasia Hirschbrunn Euch los, um Magier aus Dalaran zu jagen?",a="Die im ganzen Silberwald stationierten Zauberer aus Dalaran tragen veredelte Manasmaragde bei sich, die starke magische Ströme kanalisieren. Anastasia Hirschbrunn erkennt die gemeinsamen arkanen Philosophien, glaubt aber, dass jene, die sich nicht verteidigen können, ihr Leben und ihre Ressourcen an die Verlassenen verwirken.",al={"warum magier aus dalaran töten","dalaran manasmaragde hintergrund","warum magier im silberwald"}},{q="Wo befinden sich die Zauberer aus Dalaran?",a="Zauberer aus Dalaran sind im ganzen Silberwald stationiert, besonders nahe Mühlenbern und auf dem Gelände südöstlich des Grabmals.",al={"wo manasmaragde aus dalaran finden","magier im silberwald standort","magier von mühlenbern"}},{q="Wer ist Josef Gregorian?",a="Josef Gregorian ist ein untoter Schneider im Magieviertel von Unterstadt. Er ist kein arkaner Zauberwirker, ist aber auf das Nähen verzauberter Gewänder wie Spellfire Robes spezialisiert.",al={"josef gregorian unterstadt","wer ist der schneider im magieviertel","gregorian schneider"}},{q="Welche Roben werden aus diesen Materialien gefertigt?",a="Josef Gregorian näht aus dem Leinen und den Manasmaragden aus Dalaran Spellfire Robes. Das Gewand kennzeichnet den Übergang vom Lehrling zum anerkannten Magier.",al={"welche robe gibt es","spellfire robes belohnung","materialsammlung belohnungsrobe"}},{q="Warum widerstrebt es Anastasia ein wenig, Magier aus Dalaran zu töten?",a="Anastasia Hirschbrunn widerstrebt das Töten, weil Magier aus Dalaran viele arkane Überzeugungen und Philosophien mit den Magiern der Verlassenen teilen. Dennoch wiegen Überleben und Notwendigkeit schwerer als Gefühle.",al={"hirschbrunn gefühle zu dalaran","magier der verlassenen gegen dalaran","anastasia hirschbrunn hintergrund"}}},fx={e61c0dee={q="Wozu dient der Leinenstoff?",a="Der Leinenstoff dient als profane Grundlage für Eure Spellfire Robes. Josef Gregorian, der Schneider im Magieviertel der Unterstadt, verwebt den Stoff zu feinen Kleidungsstücken, bevor er magische Reagenzien in die Fäden einwebt, um sie zu stärken.",al={"verwendung von leinenstoff","warum leinenstoff","wofür ist leinen"}},["8f9ef647"]={q="Wozu dient der Manaedelstein aus Dalaran?",a="Manaedelsteine aus Dalaran enthalten rohe arkane Energie, die von den Magiern der Kirin Tor kanalisiert wurde. Josef Gregorian näht sie direkt in Eure Roben ein, um den Stoff mit der magischen Kraft zu durchdringen, die erforderlich ist, um wahre Spellfire-Kleidung zu schmieden.",al={"verwendung manaedelstein aus dalaran","warum manaedelsteine aus dalaran","wofür sind die manaedelsteine"}},["608132d5"]={q="Wer sind die Magier aus Dalaran im Silberwald?",a="Es handelt sich um menschliche Zauberer, die Dalaran treu ergeben sind und um Mühlenbern im östlichen Silberwald stationiert sind. Obwohl ihre arkanes Disziplin die der Magier der Verlassenen widerspiegelt, bedroht ihre Anwesenheit direkt die Herrschaft der Unterstadt über die Region, was sie zu erstklassigen Zielen für ambitionierte Lehrlinge macht.",al={"dalaran-magier im silberwald","wer sind die magier aus dalaran","dalaran-menschen im silberwald"}},["1cfe23fe"]={q="Warum schickt Anastasia Hirschbrunn einen Lehrling, anstatt sich selbst darum zu kümmern?",a="Der Erhalt Eurer ersten Magierroben ist ein Initiationsritus. Anastasia Hirschbrunn erwartet, dass Ihr Euren Wert und Euren arkanen Status beweist, indem Ihr Rivalen die Reagenzien durch Willenskraft und persönliche Stärke abnehmt.",al={"warum ich materialien sammeln","warum lehrling schicken","warum holt anastasia die edelsteine nicht selbst"}}},fp="19,166,25.248.0,26.389.0,31.272.0,43.168.0,57.270.0,38.132.0,23.168.0,44.147.0,67.184.0"}
P.entries["quest:1962"] = {n="Roben des Zauberfeuers",s="In Unterstadt markieren die Roben des Zauberfeuers den Weg eines jungen Magiers der Horde zur Meisterschaft. Josef Gregorian vollendet sie, nachdem der Lehrling seltene Komponenten aus dem ganzen Reich herbeigeschafft hat.",h="In Unterstadt markieren die Roben des Zauberfeuers den Weg eines jungen Magiers der Horde zur Meisterschaft.",kw={"arkane roben","gathering materials","josef gregorian","magierquest","magieviertel","roben des zauberfeuers","unterstadt"},ang={["class:Mage"]="Als Magier der Horde erhaltet Ihr diese Roben im Rahmen eines frühen Übergangsritus. Ihr maßgeschneiderter Stoff hält unberechenbaren Feuer- und Arkanenergien stand.",["profession:Tailoring"]="Als Schneider erkennt Ihr, wie exotische Reagenzien gewöhnlichen Stoff gegen mächtige magische Ströme widerstandsfähig machen.",["race:Undead"]="Als Zauberwirker der Verlassenen in Unterstadt führt Ihr die arkane Disziplin nach Dalarans Vorbild fort. Eure Kunst verbindet alte magische Traditionen mit Eurem neuen Dasein in den Ruinen Lordaerons."},sec={{t="Das Gewand eines Magiers",b="In Lordaeron braucht Ihr mehr als gewöhnlichen Stoff, um Eure wachsende Magie zu kanalisieren und Euch vor ihr zu schützen. Josef Gregorian ist ein Schneider im Magieviertel von Unterstadt. Er fertigt magische Gewänder aus besonderen Materialien, die vielversprechende Zauberwirker der Horde zusammentragen. Die letzten Stiche markieren Euren Übergang von einfachen Zauberformeln zur Arkan- und Feuermagie."},{t="Gewebte Macht",b="Josef Gregorian benötigt alchemistische und arkane Komponenten, um Roben zu fertigen, die mächtige Magie bündeln. Ihr beschafft die Materialien in gefährlichen Prüfungen und bringt sie zu seinem Refugium in Unterstadt. Dort webt Gregorian sie zusammen. Die Roben kennzeichnen Euer wachsendes Ansehen und bieten Euch als angehendem Magier Schutz."}},faq={{q="Welchen Zweck hat die Quest Roben des Zauberfeuers?",a="Diese Roben vollenden einen frühen Übergangsritus für Magier der Horde. Nachdem Ihr die Materialien für die Schneiderei gesammelt habt, erhaltet Ihr von Josef Gregorian eigens verzauberte Roben.",al={"roben des zauberfeuers zweck","was bewirken die roben des zauberfeuers","warum diese quest machen"}},{q="Wer ist Josef Gregorian?",a="Josef Gregorian ist ein Schneider der Verlassenen im Magieviertel von Unterstadt. Er näht die ersten richtigen Klassengewänder für frisch ausgebildete Magier, die Anastasia Hirschbrunn zu ihm schickt.",al={"wer ist josef","wer fertigt die robe","josef gregorian unterstadt"}},{q="Wo findet diese Quest statt?",a="Ihr trefft Josef Gregorian in seiner Schneiderei im Magieviertel von Unterstadt.",al={"roben des zauberfeuers ort","wo roben des zauberfeuers abgeben"}},{q="Warum müsst Ihr für diese Quest nicht aufbrechen, um eine weitere Aufgabe zu erledigen?",a="Ihr habt die Materialien im vorherigen Auftrag Gathering Materials gesammelt. Gebt Josef die Reagenzien, und er webt das Gewand und überreicht Euch die fertigen Roben.",al={"warum geht es sofort","wie roben des zauberfeuers abschließen","robe automatisch abschließen"}},{q="Können auch andere Klassen als Magier diese Roben erhalten?",a="Nein. Nur Magier, die mit der Horde verbündet sind, können diese verzauberten Roben erhalten.",al={"nur für magier","können hexenmeister sie erhalten","wer kann roben des zauberfeuers machen"}},{q="Welche Materialien wurden zur Herstellung dieser Roben benötigt?",a="Die Roben erfordern seltene, zuvor gesammelte Materialien, darunter Leinenstoff und Manasteine aus Dalaran, die den Magiern der Kirin Tor im Silberwald abgenommen wurden.",al={"was wird für die robe benötigt","robe zutaten","gathering materials abgeben"}}},fx={c778cc7d={q="Warum schnei-dert Euch Josef Gregorian die Spellfire Robes?",a="Josef Gregorian dient als Mentor für aufstrebende Magier der Verlassenen und der Horde im Magieviertel. Indem er die gesammelten Reagenzien in geeignete verzauberte Gewänder einwebt, stellt er sicher, dass Ihr angemessen ausgerüstet seid, um die arkanen Kräfte zu kanalisieren und zu ertragen, die Euer wachsendes Handwerk erfordert.",al={"warum macht josef die roben","motiv von josef gregorian","warum hilft josef dir"}}},fp="15,180,17.341.0,11.308.0,49.164.0,23.172.0,33.77.0,62.164.0,48.71.0,49.146.0"}
P.entries["quest:1963"] = {n="Die Zerschmetterte Hand",s="In Orgrimmar prüft Therzok Schurken, die Aufnahme in die geheimnisvolle Zerschmetterte Hand suchen. Ihre Prüfung führt sie zu Tazan, einem Trollschmuggler, und seinem verschlossenen Ranzen.",h="In Orgrimmar prüft Therzok Schurken, die Aufnahme in die geheimnisvolle Zerschmetterte Hand suchen.",kw={"die kluft der schatten","orgrimmar","ratschet","schurke","ranzen","zerschmetterte hand","tazan","therzok"},ang={["class:Rogue"]="Als Schurke der Horde tretet Ihr der Zerschmetterten Hand durch einen Ritus bei, der rücksichtslose Effizienz, Meuchelmord und Nutzen höher schätzt als offenen Kampf.",["faction:Horde"]="Als Mitglied der Horde erlebt Ihr, wie die Zerschmetterte Hand Thralls vorsichtige Vision für die junge Horde im Stillen infrage stellt."},sec={{t="Schatten in der Kluft",b="Die Zerschmetterte Hand operiert von der Kluft der Schatten unter Orgrimmar aus. Dieser Orden von Attentätern und Dieben hält an alten orkischen Traditionen fest. Kriegshäuptling Thrall führt die junge Horde mit Ehre, Diplomatie und Umsicht. Doch die Anführer der Zerschmetterten Hand glauben, dass Zurückhaltung ihr Volk schwächt, und wollen durch verdeckte Gewalt die kriegerische Vorherrschaft wiederherstellen. Sie setzen Messer und Gift ein, wenn ein Sturmangriff auf dem Schlachtfeld scheitern könnte."},{t="Das Schicksal eines Schmugglers",b="Therzok prüft Schurken, indem er sie auf Tazan ansetzt, einen Troll, der nahe Ratschet im Brachland tätig ist. Tazan handelt mit Küstenpiraten und trägt Informationen bei sich, die die Gilde begehrt. Seinen verschlossenen Ranzen zu beschaffen, beweist, dass ein Schurke seiner Beute auch jenseits der Stadtmauern nachstellen kann. Ihn zu öffnen erfordert eine weitere Fertigkeit."}},faq={{q="Was ist die Zerschmetterte Hand in Orgrimmar?",a="Die Zerschmetterte Hand ist eine geheime Gilde der Horde aus Schurken, Spähern und Attentätern mit Sitz in Orgrimmars Kluft der Schatten. Einst ein alter orkischer Klan, bekannt für brutale Selbstverstümmelung, sammelt sie heute Informationen und führt Morde aus. Ihre Mitglieder ziehen rücksichtslosen Pragmatismus Thralls vorsichtiger Diplomatie vor.",al={"wer ist die zerschmetterte hand","schurken der zerschmetterten hand","zweck der zerschmetterten hand"}},{q="Wer ist Therzok?",a="Therzok ist ein Auftraggeber der Zerschmetterten Hand in der Kluft der Schatten. Er prüft angehende Schurken auf die von der Gilde geforderte Gerissenheit und Tödlichkeit und zweifelt offen an Thralls Zurückhaltung.",al={"therzoks rolle","wer ist der questgeber","therzok orgrimmar"}},{q="Warum will Therzok Tazan tot sehen?",a="Tazan ist ein Trollschmuggler, der nahe Ratschet mit den Southsea pirates handelt. Er trägt Informationen in einem Ranzen bei sich, die die Zerschmetterte Hand für ihre verdeckte Arbeit begehrt.",al={"warum tazan töten","tazans geschichte","was hat tazan getan"}},{q="Wo befindet sich Tazan?",a="Tazan ist im Brachland tätig, nahe der Küste und den von Piraten heimgesuchten Gebieten südlich von Ratschet.",al={"tazans aufenthaltsort","wo ist tazan","tazan finden"}},{q="Was geschieht nach der Beschaffung von Tazans Ranzen?",a="Als der Ranzen zurückgebracht wird, stellt Therzok fest, dass er verschlossen ist. Er ist über Tazans Tod erfreut, braucht aber noch die Informationen darin, also wird das Öffnen zu einer weiteren Prüfung im Schlösserknacken.",al={"nächste quest","verschlossener ranzen","was tun mit dem ranzen"}},{q="Weiß Thrall von den Methoden der Zerschmetterten Hand?",a="Die Zerschmetterte Hand dient dem Namen nach der Horde, doch ihre Mitglieder arbeiten im Verborgenen und verachten Thralls vorsichtige Führung. Sie bauen heimlich Informationsnetze auf und versuchen, Bedrohungen zu beseitigen, bevor die Diplomatie des Kriegshäuptlings ihr Handeln verzögern kann.",al={"thrall und die zerschmetterte hand","billigt es der kriegshäuptling","thrall schurken"}}},fx={["6c6760e5"]={q="Was befindet sich in Tazans Ranzen?",a="Therzok sucht nach dem Ranzen, weil er wertvolle Informationen enthält. Tazan handelt direkt mit den Südmeerfreibeutern, die in der Nähe von Ratschet operieren, und jegliche Korrespondenz oder Aufzeichnungen, die er bei sich trägt, könnten der The Shattered Hand einen Vorteil gegenüber den Bewegungen der Piraten entlang der Küste verschaffen. Leider ist der Beutel sicher verschlossen, was ihn nutzlos macht, bis Ihr einen Weg findet, ihn zu öffnen.",al={"tazans ranzen","was ist tazans ranzen","zweck von tazans ranzen"}},fc6df596={q="Wer ist Tazan?",a="Tazan ist ein Troll-Schurke, der illegale Geschäfte mit den Piraten südlich von Ratschet betreibt. Da er im Brachland außerhalb der Reichweite der Gesetze von Orgrimmar operiert, handelt er mit Geheimnissen und Schmuggelware, was die Aufmerksamkeit der The Shattered Hand auf sich zog. Seine Geschäfte mit Gesetzlosen machen ihn zu einem erstklassigen Ziel für die Eliminierung.",al={"wer ist tazan","tazan als ziel","warum tazan töten"}},beb36990={q="Warum schickt Therzok Euch, anstatt sich selbst um Tazan zu kümmern?",a="The Shattered Hand operiert streng geheim aus den Tiefen der Kluft und verbirgt ihre rücksichtslosen Methoden vor den wachsamen Augen von Kriegshäuptling Thrall. Therzok kann keine offiziellen Wachen der Horde aussenden oder hochrangige Gildenmitglieder bei belanglosen Außeneinsätzen entlarven. Stattdessen nutzt er den Auftrag als Initiationsprüfung, um zu testen, ob Ihr über die tödliche Gerissenheit verfügt, die erforderlich ist, um ihrer Untergrundbruderschaft zu dienen.",al={"warum schickt man mich","warum will therzok dich","warum tötet er tazan nicht selbst"}}},fp="18,160,20.413.0,17.294.1,40.297.0,15.174.0,33.163.0,23.83.0,46.188.1,52.240.0"}
P.entries["quest:197"] = {n="Beherrschen der Raptorenjagd",s="Im Schlingendorntal schickt Euch Hemet Nesingwary auf die Jagd nach dem Raptor, der selbst ihm entkommen ist. Nach Euren Prüfungen gegen geringere Bestien sollt Ihr Tethis aufspüren und seine Kralle zu Hemet bringen.",h="Im Schlingendorntal schickt Euch Hemet Nesingwary auf die Jagd nach dem Raptor, der selbst ihm entkommen ist.",kw={"ajeck rouack","arena der gurubashi","hemet nesingwary","beherrschen der raptorenjagd","schlingendorntal","kralle von tethis","tethis"},sec={{t="Das gerissene Raubtier des Tals",b="Hemet Nesingwary erzählt Euch von Tethis, einem bösartigen Raptor, der jedem Jäger entkommen ist, selbst dem Expeditionsleiter. Ajeck Rouack gab der Bestie ihren Namen. Unter den Raptoren des Schlingendorntals ist Tethis die größte Herausforderung für einen Jäger."},{t="Die Kralle erbeuten",b="Tethis streift nördlich der Arena der Gurubashi umher. Bringt Hemet eine Kralle des erlegten Raptors, und er wird Euch als Meister der Raptorenjagd anerkennen. Kein anderer Großwildjäger hat diese Tat vollbracht."}},faq={{q="Wer schickt Euch auf die Jagd nach Tethis?",a="Hemet Nesingwary schickt Euch von seinem Expeditionslager im nördlichen Schlingendorntal auf die Jagd nach Tethis, nachdem Ihr Eure Fährtenlesekunst an gewöhnlichen Dschungelraptoren bewiesen habt.",al={"wer vergibt beherrschen der raptorenjagd","beherrschen der raptorenjagd questgeber","wer will tethis tot sehen"}},{q="Wo ist Tethis zu finden?",a="Tethis durchstreift den Dschungel rund um die Arena der Gurubashi, meist im Dickicht nördlich des Kolosseums.",al={"tethis aufenthaltsort","wo ist tethis","wo tethis finden"}},{q="Welchen Beweis verlangt Hemet für die erlegte Beute?",a="Hemet verlangt Tethis' Kralle als Beweis dafür, dass Ihr den Raptor zur Strecke gebracht habt.",al={"was hemet bringen","tethis beweis","beherrschen der raptorenjagd abgabegegenstand"}},{q="Wer gab dem Raptor ursprünglich den Namen Tethis?",a="Ajeck Rouack, einer der Jäger in Nesingwarys Expeditionslager, gab dem Raptor den Namen Tethis.",al={"wer gab tethis seinen namen","herkunft von tethis' namen"}}},fp="14,192,29.229.0,18.187.0,29.173.0,26.100.0,42.77.0,39.98.0"}
P.entries["quest:1978"] = {n="Die Todespirscher",s="In Unterstadt heißen die Todespirscher einen neuen Agenten in ihren Reihen willkommen. Ihr bringt Androns Geschäftsbuch zu Varimathras als Beweis für die verdeckten Aktivitäten des Syndikats.",h="In Unterstadt heißen die Todespirscher einen neuen Agenten in ihren Reihen willkommen.",kw={"alterac","androns geschäftsbuch","todespirscher","hall of the dark lady","mennet carkad","syndikat","unterstadt","varimathras"},ang={["class:Rogue"]="Als Schurke tretet Ihr dem Spezialkader der Verlassenen als Agent des staatlichen Geheimdienstes bei, nicht als einfacher Beutelschneider.",["faction:Horde"]="Als Mitglied der Horde helft Ihr, die nördlichen Gebiete vor Sabotage zu schützen, indem Ihr die menschlichen Überreste von Alterac überwacht.",["race:Undead"]="Als Verlassener gelobt Ihr, Lordaerons zerbrechliche Souveränität vor menschlichen Überlebenden und lauernden Verrätern zu schützen."},sec={{t="Aufnahme in die Schatten",b="Mennet Carkad heißt Euch bei den Todespirschern willkommen, nachdem Ihr Andron Gants Aufzeichnungen aufgedeckt habt. Der Orden dient Fürstin Sylvanas in ganz Lordaeron als ihre Augen, Ohren und Dolche. Seine Agenten nutzen Aufklärung, rücksichtslose Effizienz und Heimlichkeit, um Bedrohungen zu beseitigen, bevor sie entstehen. Die Anerkennung durch den Orden markiert Euren ersten Schritt im Dienst der Verlassenen."},{t="Die Verbindung zum Syndikat",b="Androns Geschäftsbuch enthüllt geheime Verbindungen zwischen örtlichen Agenten und dem Syndikat. Einst die adelige Aristokratie von Alterac, wandte sich das Syndikat Banditentum und Unterwanderung zu, nachdem sein Reich im Zweiten Krieg gefallen war. Carkad reagiert auf die Nachricht mit Überraschung und Verachtung. Die gefallenen Lords von Alterac sind in ihrem Kampf um die Rückgewinnung der Macht zu kleinlichen Verschwörungen herabgesunken."},{t="Audienz beim Schreckenslord",b="Ihr überbringt das brisante Geschäftsbuch an Varimathras im Königsviertel von Unterstadt. Der Kommandant der Nathrezim beaufsichtigt unter Sylvanas Windläufer die taktische Aufklärung der Verlassenen. Erfreut über die Initiative der Todespirscher würdigt Varimathras Euer Können und erklärt, seine Geheimdienstabteilung könne jemanden gebrauchen, der Ergebnisse liefert."}},faq={{q="Was sind die Todespirscher?",a="Die Todespirscher sind der Orden der Spione, Kundschafter und Meuchelmörder der Verlassenen mit Sitz im Schurkenviertel von Unterstadt. Ihre Agenten arbeiten in ganz Lordaeron, um politische Rivalen auszuschalten, feindliche Fraktionen zu infiltrieren und das Reich der Verlassenen vor äußeren Bedrohungen und innerer Unterwanderung zu schützen.",al={"wer sind die todespirscher","geschichte der todespirscher","meuchelmörder der verlassenen"}},{q="Warum ist das Syndikat beteiligt?",a="Androns Geschäftsbuch enthüllt geheime Verbindungen zum Syndikat, der vertriebenen Aristokratie von Alterac, die sich nun dem organisierten Banditentum verschrieben hat. Die Verlassenen beobachten die Überreste von Alterac in ihrem Gebiet, wo Agenten des Syndikats Gelegenheiten suchen, verlorenes Land zurückzuerobern und Ressourcen im gesamten nördlichen Lordaeron zu plündern.",al={"warum das syndikat","verbindung zu alterac","geschäftsbuch des syndikats"}},{q="Warum direkt an Varimathras berichten?",a="Varimathras berät Königin Sylvanas in taktischen Fragen und beaufsichtigt die Sicherheit und den Geheimdienst von Unterstadt. Erkenntnisse über fremde Verschwörungen, darunter die verdeckten Aktivitäten des Syndikats, gehen zur Prüfung und für weiterreichende militärische und diplomatische Maßnahmen an ihn.",al={"warum varimathras","wer ist varimathras","rolle des schreckenslords"}},{q="Wer war Mennet Carkad?",a="Mennet Carkad ist ein ranghoher Führungsoffizier und Kontaktmann der Todespirscher in Unterstadt. Er beaufsichtigt Feldagenten, beurteilt Rekruten und sichtet Geheimdienstinformationen, bevor er entscheidende Erkenntnisse entlang der Befehlskette weiterleitet.",al={"rolle von mennet carkad","questgeber carkad"}},{q="Wo findet diese Audienz statt?",a="Die Audienz findet in der Hall of the Dark Lady im Königsviertel von Unterstadt statt. Varimathras steht neben Königin Sylvanas Windläufer im Herzen des Machtzentrums der Verlassenen.",al={"wo ist varimathras","standort der hall of the dark lady"}},{q="Was geschieht nach dem Beitritt zu den Todespirschern?",a="Nachdem Eure Eignung feststeht und Ihr Mennet Carkad und Varimathras Eure Zuverlässigkeit bewiesen habt, erkennen Euch die Verlassenen als vertrauenswürdigen Feldagenten an. Künftige Aufklärungs- und Mordaufträge können Euch durch die umkämpften Gebiete Lordaerons führen.",al={"fortsetzung der questreihe der todespirscher","wie geht es weiter"}}},fx={["123798f3"]={q="Warum möchte Mennet Carkad, dass Androns Geschäftsbuch an Varimathras ausgeliefert wird?",a="Das Geschäftsbuch enthüllt, dass das Syndikat – die gefallenen Adligen von Alterac – sich gegen die Verlassenen verschworen hat. Die Aufdeckung ihres Verrats ist ein Sieg im Bereich Vital Intelligence für The Todespirscher, und Mennet weiß, dass solch dringende Nachrichten, die die Sicherheit von Lordaeron betreffen, direkt in die Hände von Lord Varimathras gelegt werden müssen, der die Operationen des Ordens beaufsichtigt.",al={"warum geschäftsbuch ausliefern","mennet carkad motiv","warum syndikat an varimathras melden"}},b0e675df={q="Warum schickt Mennet Euch, anstatt selbst Bericht bei Varimathras zu erstatten?",a="Ihr wart derjenige, der die Verschwörer aufgespürt und Androns Geschäftsbuch vor Ort sichergestellt hat. Mennet glaubt, es sei nur angemessen, dass Ihr die Informationen persönlich überbringt, was es Euch ermöglicht, den Ruhm vor Lord Varimathras zu ernten und Eure formelle Aufnahme in die Reihen von The Todespirscher zu markieren.",al={"warum ich deathstalkers","warum schickt mich mennet","warum geschäftsbuch selbst ausliefern"}}},fp="17,155,26.343.0,24.340.1,27.317.0,27.280.0,30.283.0,35.236.0,22.208.0,36.180.0,45.249.0"}
P.entries["quest:198"] = {n="Vorräte für den Gefreiten Thorsen",s="Krazek braucht in Beutebucht einen Kurier, der Vorräte nach Norden zu Gefreitem Thorsen bringt. Trollangriffe haben die regelmäßigen Lieferungen zu Lieutenant Dorens Lager nahe der nördlichen Grenze zum Erliegen gebracht.",h="Krazek braucht in Beutebucht einen Kurier, der Vorräte nach Norden zu Gefreitem Thorsen bringt.",kw={"beutebucht","dämmerwald","goblinnachschub","krazek","kurzen","lieutenant doren","gefreiter thorsen","schlingendorntal"},ang={["faction:Alliance"]="Als Soldat der Allianz bewacht Ihr mit Lieutenant Dorens Männern den nördlichen Zugang vom Dämmerwald ins Schlingendorntal. Ihr seid auf Goblinnachschub angewiesen, um Eure Stellung zu halten."},sec={{t="Eine unterbrochene Route",b="Lieutenant Dorens Männer bewachen die Grenze zwischen dem Schlingendorntal und dem Dämmerwald. Krazek organisiert regelmäßige Lieferungen für sie, doch die örtlichen Trolle greifen immer wieder an. Die üblichen Lieferungen sind gefährlich geworden, also heuert der Goblinhändler Euch an, ein Paket entlang der Dschungelstraße nach Norden zu bringen. Gefreiter Thorsen kann es im Lager nordwestlich der Straße oder entlang seiner Patrouillenroute im Süden entgegennehmen."},{t="Der wahre Inhalt",b="Gefreiter Thorsens Lieferung enthält Landminen, obwohl sie als verschiedenster Goblinnachschub deklariert ist. Er sagt, der Sprengstoff werde helfen, den Posten gegen Colonel Kurzen und seine Männer zu verteidigen."}},faq={{q="Wer schickt diese Vorräte?",a="Krazek, ein Goblinhändler, der in Beutebucht Geschäfte macht, organisiert die Vorräte und stellt sie bereit.",al={"wer gibt thorsen vorräte","krazek lieferung","wer startet vorräte für den gefreiten thorsen"}},{q="Warum haben sich die Vorräte verspätet?",a="Angriffe der örtlichen Trolle im Schlingendorntal haben die regelmäßigen Lieferungen unterbrochen, sodass Lieutenant Dorens Männer auf ihre planmäßigen Waren warten.",al={"warum verspätet","trollangriffe lieferung","warum wurde es nicht geliefert"}},{q="Wo ist Gefreiter Thorsen zu finden?",a="Gefreiter Thorsen ist in Lieutenant Dorens Lager zu finden, nordwestlich der Hauptstraße nahe dem Zugang vom Dämmerwald ins Schlingendorntal. Er patrouilliert auch auf dem Pfad direkt südlich des Lagers.",al={"wo ist thorsen","thorsen aufenthaltsort","gefreiten thorsen finden"}},{q="Was geschieht, wenn die Vorräte verloren gehen?",a="Krazek warnt, dass jeder, der die Lieferung nicht abliefert, finanziell dafür haftet und ihm Schadenersatz schuldet.",al={"was passiert bei verlust der vorräte","krazek schadenersatz","krazek im stich lassen"}}},fp="27,181,17.387.0,28.190.1,30.90.0,35.142.0,35.182.0,38.120.0"}
P.entries["quest:199"] = {n="Eine dunkle Bedrohung",s="Am Steinwerkdamm bedroht Sabotage das Bauwerk, das die Wasser von Loch Modan zurückhält. Ihr findet ein Fass nahe dem Ufer und bringt sein sonderbar riechendes Pulver zu Chefingenieur Hinderweir VII.",h="Am Steinwerkdamm bedroht Sabotage das Bauwerk, das die Wasser von Loch Modan zurückhält.",kw={"eine dunkle bedrohung","hinderweir","loch modan","sabotage","der steinwerkdamm","sonderbar riechendes pulver","verdächtiges fass"},ang={["profession:Engineering"]="Als Ingenieur erkennt Ihr die Gefahr instabiler Pulver, die gezielt an den Belastungspunkten eines großen Damms deponiert wurden.",["race:Dwarf"]="Als Zwerg kennt Ihr den Steinwerkdamm als eine der größten Bauleistungen der Zwerge von Eisenschmiede. Jede Bedrohung des Damms gefährdet die Sicherheit und den Stolz von Khaz Modan.",["race:Gnome"]="Als Gnom schätzt Ihr die Präzision zwergischer Ingenieurbauten. Das macht die chemische Natur dieser plumpen Sabotage besonders besorgniserregend."},sec={{t="Eine verdächtige Entdeckung",b="Gerüchte über Sabotage haben das Ufer rund um den Steinwerkdamm erreicht. Nahe dem Wasser liegt ein Fass, das dort nicht hingehört. Darin befindet sich sonderbares, stechend riechendes Pulver, weit entfernt von den Vorräten zur Instandhaltung des Damms."},{t="Alarm am Damm",b="Chefingenieur Hinderweir VII. ist alarmiert, als Ihr ihm eine Probe bringt. Seine Reaktion bestätigt die schlimmsten Befürchtungen in Loch Modan: Eine fremde Macht schmiedet ein Komplott gegen den Damm. Nun ist die Untersuchung dringend, denn es geht um die Verteidigung der Region."}},faq={{q="Was ist das sonderbar riechende Pulver?",a="Das sonderbar riechende Pulver im Fass ist ein Sprengstoff oder alchemistisches Mittel, das nahe dem Fuß des Steinwerkdamms deponiert wurde. Es beweist, dass ein Feind plant, das Bauwerk zu zerstören oder zu schwächen.",al={"sonderbares pulver","was ist im fass","verdächtiges fass pulver"}},{q="Wer ist Chefingenieur Hinderweir VII.?",a="Chefingenieur Hinderweir VII. ist der zwergische Meisteringenieur, der für die Instandhaltung, Unversehrtheit und Sicherheit des Steinwerkdamms in Loch Modan verantwortlich ist.",al={"wer ist hinderweir","chefingenieur hinderweir","dammingenieur"}},{q="Wo befindet sich das verdächtige Fass?",a="Das verdächtige Fass ist am Ufer nahe dem Fundament des Steinwerkdamms im Norden von Loch Modan versteckt.",al={"fundort des fasses","wo ist das fass","fass loch modan"}},{q="Warum ist der Steinwerkdamm ein Angriffsziel?",a="Der Steinwerkdamm hält den gewaltigen Stausee von Loch Modan zurück. Sollte er brechen, würden verheerende Fluten durch das tiefer gelegene Sumpfland tosen, Handelswege der Allianz lahmlegen und zwergische Besitzungen in ganz Khaz Modan verwüsten.",al={"warum den damm zerstören","sabotage am damm","bedrohung für loch modan"}},{q="Wer hat das verdächtige Fass hier zurückgelassen?",a="Agenten, die die zwergischen Lande destabilisieren wollen, haben das Fass dort platziert. Chefingenieur Hinderweir hat eine umfassendere Untersuchung eingeleitet, um herauszufinden, wer hinter dem Komplott steckt.",al={"wer hat das fass platziert","saboteure","wer hat das pulver deponiert"}},{q="Was sollte ich tun, nachdem ich das Pulver eingesammelt habe?",a="Bringt die Probe zu Chefingenieur Hinderweir VII. oben auf dem Steinwerkdamm, damit er sie untersuchen und eine Reaktion vorbereiten kann.",al={"was als nächstes","pulver abgeben","mit wem sprechen"}}},fp="19,205,22.211.0,16.224.1,36.192.0,37.149.0,37.114.0,43.219.0,36.151.0,45.119.0"}
P.entries["quest:1998"] = {n="Fenwick Thatros",s="In Unterstadt schickt Mennet Carkad vielversprechende Schurken auf Lord Varimathras' Befehl los, um Fenwick Thatros zu töten. Thatros steht im Verdacht, an den Ufern des Silberwalds unabhängige Untote zu sammeln. Sein Tod beweist den Todespirschern die Fähigkeiten eines Agenten und eröffnet den Zugang zu fortgeschrittener Ausbildung im Handwerk.",h="In Unterstadt schickt Mennet Carkad vielversprechende Schurken auf Lord Varimathras' Befehl los, um Fenwick...",kw={"deathstalkers","fenwick thatros","der lordameresee","mennet carkad","schurkenviertel","silberwald","unterstadt","varimathras"},ang={["class:Rogue"]="Als Schurke beweist Ihr mit diesem Auftrag Eure Heimlichkeit und tödliche Präzision. Danach vertrauen die Todespirscher Euch womöglich weiterführende Mittel ihres Handwerks an.",["race:Undead"]="Als einer der Verlassenen wisst Ihr, dass rivalisierende untote Fraktionen so nahe an Capital City keine Souveränität beanspruchen können. Fenwick Thatros' Kopf ist eine politische Notwendigkeit."},sec={{t="Ein Befehl des Schreckenslords",b="Im Schurkenviertel von Unterstadt verwaltet Mennet Carkad die Aufträge der Todespirscher und bildet Schurken aus. Die Todespirscher sind der verschwiegene Geheimdienst der Verlassenen. Lord Varimathras hat Fenwick Thatros zum vorrangigen Ziel erklärt, ein Auftrag, der für unerfahrene Rekruten zu ernst ist. Thatros hat unter abtrünnigen Untoten im Silberwald Fuß gefasst. Wenn man sie gewähren lässt, könnten ihre unabhängigen Anführer die Herrschaft der Verlassenen über die alten Ländereien Lordaerons bedrohen."},{t="Der verfallene Steg am Lordameresee",b="Späher der Todespirscher haben Fenwick Thatros nahe einem verfallenen Steg am Lordameresee im Silberwald ausgemacht. Um ihn zu erreichen, müsst Ihr Wildnis durchqueren, die wilde Tiere, Gnolle der Rot Hide und Überreste der Geißel für sich beanspruchen. Varimathras verlangt einen Beweis für die Tötung: Thatros' abgetrennten Kopf. Bringt ihn zurück, und Ihr könnt Euch Zugang zu weiterführenden verdeckten Einsätzen verdienen."}},faq={{q="Wer ist Fenwick Thatros?",a="Fenwick Thatros führt Untote nahe dem Lordameresee im Silberwald an. Er befehligt Gruppen von Untoten, die Unterstadt nicht verbunden oder feindlich gesinnt sind, anders als die Verlassenen, die Lady Sylvanas dienen. Lord Varimathras hat seine Hinrichtung angeordnet.",al={"fenwick hintergrundgeschichte","wer ist thatros","fenwick thatros hintergrund"}},{q="Warum will Varimathras Fenwick Thatros tot sehen?",a="Varimathras will Fenwick Thatros tot sehen, weil er versprengte Untote im Silberwald gegen die Verlassenen vereinen könnte. Rivalisierende Anführer, die Sylvanas' Herrschaft über die Region bedrohen, müssen beseitigt werden, um die Grenzen von Unterstadt zu sichern.",al={"varimathras thatros","warum fenwick töten"}},{q="Wer sind die Todespirscher?",a="Die Todespirscher sind der Dienst der Verlassenen für Spionage, Meuchelmord und Aufklärung. Von ihrem Sitz im Schurkenviertel von Unterstadt aus sind sie in ganz Lordaeron tätig, um innere Bedrohungen zu beseitigen, rivalisierende Fraktionen auszuspionieren und Gebiete für die Dark Lady zu sichern.",al={"deathstalkers hintergrundgeschichte","was sind die deathstalkers","untote schurken fraktion"}},{q="Wo befindet sich Fenwick Thatros?",a="Berichte der Todespirscher verorten Fenwick Thatros nahe einem verfallenen Steg am Ufer des Lordameresees im nordöstlichen Silberwald.",al={"wo ist fenwick","fenwick steg standort","thatros lordameresee"}},{q="Was bringt der Abschluss dieser Mission bei den Todespirschern ein?",a="Fenwick Thatros zu töten beweist Mennet Carkad und den Todespirschern Euer Können und Eure Treue. Sobald Ihr bewiesen habt, dass man Euch vertrauen kann, bietet Carkad Euch eine spezialisierte Ausbildung in den Schattenkünsten an.",al={"fenwick belohnung hintergrundgeschichte","was kommt nach fenwick"}},{q="Wer ist Mennet Carkad?",a="Mennet Carkad bildet Schurken aus und kümmert sich im Schurkenviertel von Unterstadt um die Angelegenheiten der Todespirscher. Er beaufsichtigt Agenten im Einsatz und vergibt Aufträge, die der Sicherheit des Reichs der Verlassenen dienen.",al={"mennet carkad","wer vergibt die fenwick quest"}}},fx={eac48585={q="Warum benötigt Mennet Carkad Fenwicks Kopf?",a="Fenwick Thatros stellt eine organisierte Bedrohung dar, die direkt an den Grenzen des Silberwalds lauert. Mennet Carkad verlangt seinen abgetrennten Kopf als unumstößlichen Beweis dafür, dass der untote Schurkenkommandant eliminiert wurde. Bei den verdeckten Operationen der The Todespirscher und Lord Varimathras reicht das Wort eines Assassinen niemals ohne eine physische Trophäe aus, um den Erfolg zu bestätigen.",al={"wofür ist fenwicks kopf","warum fenwicks kopf nehmen","zweck von fenwicks kopf"}},bc8ca6fa={q="Warum wählt Mennet Carkad Euch für diese Mission aus?",a="Mennet Carkad fungiert als Ausbilder und Kontaktperson für die Todespirscher im Schurkenviertel. Wenn Lord Varimathras eine chirurgische Tötung anordnet, sind gewöhnliche Stadtwachen für die heimliche Aufklärung außerhalb der Stadt ungeeignet. Mennet wählt Euch gezielt aus, weil Ihr Talent in den Schattenkünsten gezeigt habt, und nutzt diesen kritischen Auftrag, um zu beurteilen, ob Ihr bereit für eine fortgeschrittene Ausbildung unter den Eliteagenten der Verlassenen seid.",al={"warum werde ich geschickt","warum wählt mich mennet aus","warum keine wachen der deathstalkers schicken"}}},fp="15,300,28.448.0,30.338.0,23.232.0,47.226.0,26.253.0,33.122.0,62.190.0,21.177.0"}
P.entries["quest:1999"] = {n="Werkzeuge des Handwerks",s="In Unterstadt werden Schurken der Horde ausgeschickt, um einen Bericht aus Mühlenbern zu stehlen. Lord Varimathras befiehlt ihnen, Schlossknackwerkzeuge zu beschaffen und durch Erkenntnisse über die Kirin Tor mehr über Dalarans Zustand zu erfahren.",h="In Unterstadt werden Schurken der Horde ausgeschickt, um einen Bericht aus Mühlenbern zu stehlen.",kw={"mühlenbern","dalaran","deathstalkers","estelle gendry","kirin tor","schlossknacken","mennet carkad","schurkenviertel","unterstadt","varimathras"},ang={["class:Rogue"]="Als Schurke der Horde beweist Ihr Euren Wert mit fachgerechtem Schlossknackwerkzeug, Heimlichkeit und Fingerspitzengefühl statt mit roher Gewalt.",["faction:Horde"]="Als Mitglied der Horde helft Ihr, im Silberwald Informationen über die Menschen zu beschaffen und die Stellung der Horde im gesamten nördlichen Lordaeron gegen die Überreste der Allianz zu stärken.",["race:Undead"]="Als Untoter helft Ihr den Verlassenen, die Magier der Kirin Tor zu überlisten, die Lordaeron zurückerobern wollen."},sec={{t="Mühlenbern im Blick",b="Das Verhör eines Gefangenen führt die Todespirscher zu Informationen, die in Mühlenbern verborgen sind. Der Silberwald bleibt eine unsichere Frontlinie, und menschliche Magier bewachen die Nachrichtenverbindungen des Dorfes unerbittlich. Lord Varimathras befiehlt Mennet Carkad, einem Führungsoffizier der Todespirscher, vielversprechende Agenten an den Wachposten der Kirin Tor vorbeizuführen und den Statusbericht von Dalaran zu bergen."},{t="Die Kunst des Einbruchs",b="Infiltration und Schlossknacken stellen Fertigkeiten auf die Probe, die über das Meucheln hinausgehen. Bevor sie das Gebiet der Kirin Tor betreten, holen sich Agenten spezialisiertes Diebeswerkzeug von Estelle Gendry. Wer die gesicherte Truhe in Mühlenbern öffnet, beweist, dass er mehr als Straßenbrutalität beherrscht und den Verlassenen als Spion dienen kann."}},faq={{q="Wer befiehlt diese Mission?",a="Mennet Carkad, ein Schurke der Todespirscher im Schurkenviertel von Unterstadt, vergibt den Auftrag. Lord Varimathras erteilt den Befehl und überwacht die Informationsbeschaffung der Verlassenen.",al={"wer vergibt werkzeuge des handwerks","questgeber","mennet carkad quest"}},{q="Was ist der Statusbericht von Dalaran?",a="Der Statusbericht von Dalaran ist eine versiegelte Depesche der Kirin Tor über die Zustände in Dalaran. Die Verhörspezialisten der Todespirscher erfuhren seinen Aufbewahrungsort von einem Gefangenen, was zeigt, wie ungeschützt wichtige Informationen über die südlichen Nachbarn der Verlassenen sind.",al={"was sind die dokumente","kirin tor papiere","statusbericht"}},{q="Wo wird der Bericht aufbewahrt?",a="Der Bericht liegt in einer verschlossenen Truhe im Außenposten der Kirin Tor in Mühlenbern im südlichen Silberwald.",al={"wo sind die dokumente","truhe in mühlenbern fundort","wo ist der statusbericht"}},{q="Wer stellt die Schlossknackwerkzeuge bereit?",a="Estelle Gendry, eine Ausstatterin im Schurkenviertel von Unterstadt, stellt das Diebeswerkzeug bereit, das zum Öffnen der verschlossenen Truhe benötigt wird.",al={"wo gibt es werkzeuge","estelle gendrys rolle","ausstatter werkzeuge"}},{q="Warum ist Dalaran gerade jetzt für die Verlassenen wichtig?",a="Dalarans überlebende Zauberer bauen ihre Stadt auf der dem Silberwald gegenüberliegenden Seite des Lordameresees wieder auf. Die Verlassenen beobachten die Kirin Tor, um ihre Besitzungen in Lordaeron zu schützen.",al={"warum ist dalaran wichtig","verlassene gegen dalaran","bedrohung durch die kirin tor"}},{q="Welche Voraussetzung muss vor dieser Mission erfüllt werden?",a="Agenten müssen zuerst den Mordauftrag Fenwick Thatros abschließen und ein Ziel im Silberwald jagen, bevor Mennet Carkad ihnen heikle Infiltrationsaufträge anvertraut.",al={"voraussetzung","welche quest kommt davor","fenwick thatros quest"}}},fx={["77cf7ea8"]={q="Warum will Mennet Carkad, dass dies erledigt wird?",a="Lord Varimathras beauftragte die Todespirscher damit, den Bericht zu beschaffen, nachdem er dessen Verbleib aus einem Gefangenen herausgepresst hatte. Als Agent im Schurkenviertel führt Mennet Carkad die Anweisungen des Schreckenslords aus und stellt gleichzeitig Eure aufkeimenden Fähigkeiten in Infiltration und Spionage auf die Probe.",al={"warum will mennet carkad das","mennet carkad beweggrund","warum statusbericht von dalaran bergen"}},["9b719de0"]={q="Gegen wen werdet Ihr in Mühlenbern ausgesandt?",a="Euer Ziel ist die in Mühlenbern im Silberwald stationierte Kirin Tor. Diese menschlichen Magier unterhalten eine Enklave in der Nähe der wiederaufgebauten Stadt Dalaran und bewahren vertrauliche Informationen über den aktuellen Zustand der zerstörten Stadt vor den Verlassenen.",al={"wer besitzt den bericht","ziel von tools of the trade","wen greift ihr an"}},["6507a470"]={q="Warum benötigt Mennet Carkad Euch für diese Mission?",a="Die Mission dient als Initiationsritus. Nachdem Ihr durch die Ausschaltung von Fenwick Thatros grundlegende Eignung bewiesen habt, hat Mennet Euch ausgewählt, um zu beweisen, dass Ihr das heiklere Handwerk der Todespirscher beherrscht – das sich auf Verstohlenheit, Schlossknacken und Infiltration statt auf rohe Gewalt stützt.",al={"warum werde ich ausgesandt","warum ich mennet carkad","warum können the deathstalkers den bericht nicht holen"}}},fp="18,191,17.363.0,21.305.0,24.170.0,34.238.0,25.104.0,35.129.0,51.176.0,63.178.0"}
P.entries["quest:2"] = {n="Klaue von Scharfkralle",s="In Eschental gefährden Scharfkralles Angriffe die Nachschubwege der Horde. Bringt seine Klaue zu Senani Donnerherz am Splitterholzposten als Beweis dafür, dass das Raubtier gefallen ist.",h="In Eschental gefährden Scharfkralles Angriffe die Nachschubwege der Horde.",kw={"eschental","ashenvale hunt","hippogryph","peons","senani donnerherz","scharfkralle","splitterholzposten","warsong"},ang={["class:Hunter"]="Als Jäger stellt Ihr Eure Fährtenlesekunst und Treffsicherheit gegen Scharfkralle auf die Probe, ein gefürchtetes fliegendes Raubtier unter Eschentals dichtem Blätterdach.",["faction:Horde"]="Als Mitglied der Horde helft Ihr, die Wege für die Holzfällerarbeiten von Warsong zu sichern. Ihr schützt Peons, die zwischen vorgeschobenen Außenposten und dem Splitterholzposten unterwegs sind.",["race:Orc"]="Als Orc erleichtert Ihr dem Kriegshymnenklan die harte Arbeit der Holzgewinnung, indem Ihr eine Bedrohung aus der Luft aus dem Wald beseitigt.",["race:Tauren"]="Als Tauren folgt Ihr Senani Donnerherzens Jagd und messt Euch mit den wildesten Bestien der Natur, wie es die Tradition der Tauren verlangt."},sec={{t="Eine Geißel der Waldpfade",b="Scharfkralle jagt auf den Wegen zum Splitterholzposten, während die Horde in Eschental nach Ressourcen sucht. Der aggressive Hippogryph greift Peons und Kuriere an, die zwischen vorgeschobenen Holzfällerlagern und dem Außenposten unterwegs sind. Seine Angriffe behindern die Arbeit der Horde in der Region. Auch Schildwachen der Nachtelfen und gefährliche Wildtiere bedrohen die Neuankömmlinge."},{t="Beweis der Jagd",b="Senani Donnerherz, eine Taurenjägerin, führt Jäger der Horde gegen die tödlichsten Raubtiere Eschentals. Scharfkralles Klaue beweist, dass der Hippogryph gefallen ist. Bringt die Trophäe zum Splitterholzposten. Die Verteidiger des Außenpostens ehren die Jagd, und verängstigte Arbeiter können mit weniger Furcht durch die Wälder gehen."}},faq={{q="Was ist Scharfkralle?",a="Scharfkralle ist ein wilder, räuberischer Hippogryph, der in Eschental jagt. Er überfällt Reisende, die den Wald durchqueren.",al={"wer ist scharfkralle","scharfkralle gegner","was für eine bestie ist scharfkralle"}},{q="Warum will Senani Donnerherz die Klaue?",a="Senani Donnerherz will die Klaue als Beweis dafür, dass Scharfkralle getötet wurde. Das Raubtier bedroht Arbeiter und Nachschubwege der Horde.",al={"warum klaue abgeben","senani donnerherz trophäe","zweck der klaue von scharfkralle"}},{q="Wo gebe ich die Klaue von Scharfkralle ab?",a="Bringt die Klaue zu Senani Donnerherz am Splitterholzposten im östlichen Eschental.",al={"wo abgeben","wer nimmt die klaue","abgabeort der klaue"}},{q="Wie hilft Scharfkralles Tod der Horde?",a="Scharfkralle greift Peons an, die zwischen abgelegenen Sägewerken und dem Splitterholzposten unterwegs sind. Sein Tod macht den Transport von Vorräten und Holz sowie die Wege der Boten sicherer.",al={"warum scharfkralle töten hintergrund","interesse der horde an scharfkralle"}},{q="Gehört diese Quest zu einer größeren Reihe?",a="Ja. Sie gehört zur Eschental Hunt, Senani Donnerherzens Reihe von Bestienjagden. Die Reihe endet mit The Hunt Completed.",al={"ashenvale hunt questreihe","questreihe scharfkralle"}},{q="Wer ist Senani Donnerherz?",a="Senani Donnerherz ist eine Taurenjägerin am Splitterholzposten. Sie wacht über das Gleichgewicht des Waldes und stellt Jäger der Horde gegen Eschentals gefährlichste Kreaturen auf die Probe.",al={"senani hintergrund","wer ist senani"}}},fp="17,164,30.325.0,17.293.0,19.118.0,43.127.0,37.80.0,43.153.0,37.124.0,27.165.0"}
P.entries["quest:20"] = {n="Bedrohung durch den Schwarzfelsklan",s="Die Schwarzfelsorcs im Rotkammgebirge drängen von Norden und Südosten vor, und Seenhain wird belagert. Marschall Marris bittet Euch, ihre Reihen zu lichten und ihre kampferprobten Äxte zurückzubringen.",h="Die Schwarzfelsorcs im Rotkammgebirge drängen von Norden und Südosten vor, und Seenhain wird belagert.",kw={"äxte","blackrock","brennende steppe","seenhain","marris","orcs","rotkammgebirge","steinwacht","tharil'zun"},ang={["class:Warrior"]="Als Krieger stellt Ihr Eure Kampfdisziplin und Stärke an der Front auf die Probe, wenn Ihr erfahrenen Schwarzfelsplünderern Schild an Schild gegenübersteht.",["faction:Alliance"]="Für die Allianz hilft die Verteidigung von Seenhain, Sturmwinds südliche Grenze gegen Widersacher aus der alten Welt zu halten.",["race:Human"]="Als Mensch erfüllt Euch die Begegnung mit dem Schwarzfelsklan im Rotkammgebirge mit bitterem Schmerz. Sie zerstörten das ursprüngliche Königreich Sturmwind im Ersten Krieg."},sec={{t="Eine Stadt unter Belagerung",b="Seenhain droht von mehreren Seiten Gefahr, doch die Schwarzfelsorcs sind die größte Bedrohung. Sie kamen aus der feurigen Brennenden Steppe nach Süden und durchstreifen nun die schroffen Pässe des Rotkammgebirges. Nachdem sie Festungen eingenommen haben, halten sie die Stadtbewohner in Seenhain eingeschlossen. Handel, Nahrungssuche und Reisen auf den nördlichen Straßen sind vollständig unterbunden."},{t="Schlag gegen die Vorhut",b="Marschall Marris befehligt die bedrängte Wache von Seenhain, kann aber keine Soldaten für einen Angriff auf die Stellungen der Orcs entbehren. Also ruft er Euch auf, ihre vorgeschobenen Späher und Fußsoldaten anzugreifen. Ihre groben, kampferprobten Äxte sollen ihren Tod beweisen. Marris hofft, die Reihen der Eindringlinge bei Steinwacht im Norden und in den zerklüfteten Winkeln des südöstlichen Rotkammgebirges zu lichten."}},faq={{q="Woher kamen diese Schwarzfelsorcs?",a="Sie marschierten aus der Brennenden Steppe durch schroffe Gebirgspässe nach Süden, wo ihre angestammte Hochburg rund um den Schwarzfels liegt.",al={"woher kommen die orcs","schwarzfelsinvasion rotkammgebirge","warum sind orcs im rotkammgebirge"}},{q="Wer erteilt diesen Auftrag?",a="Marschall Marris, der ranghöchste Offizier von Seenhain, erteilt den Befehl. Er ist dafür verantwortlich, die Stadt zu verteidigen und die Ordnung aufrechtzuerhalten, während sie immer stärker eingekesselt wird.",al={"wer vergibt bedrohung durch den schwarzfelsklan","bedrohung durch den schwarzfelsklan questgeber","marschall marris quest"}},{q="Wo sind die eindringenden Schwarzfelsorcs zu finden?",a="Die eindringenden Schwarzfelsorcs halten das nördliche Hochland um Burg Steinwacht und Stützpunkte im südöstlichen Winkel des Rotkammgebirges.",al={"wo sind schwarzfelsorcs","kampferprobte axt fundorte","orclager rotkammgebirge"}},{q="Warum verlangt Marschall Marris kampferprobte Äxte?",a="Die kampferprobten Äxte liefern Marschall Marris einen handfesten Beweis, dass Ihr die Schwarzfelsplünderer bekämpft und getötet habt, die das Tal bedrohen.",al={"warum äxte","todesbeweis","kampferprobte axt zweck"}},{q="Was geschieht, nachdem diese Späher besiegt sind?",a="Nachdem die Vorhut geschwächt ist, befiehlt Marschall Marris einen Angriff auf Tharil'zun, den örtlichen Anführer der Schwarzfelsorcs, der sich in den Bergen verschanzt hat.",al={"was folgt auf bedrohung durch den schwarzfelsklan","nächste quest nach bedrohung durch den schwarzfelsklan","wer führt die orcs an"}},{q="Gehören die Orcs zu Thralls Horde?",a="Nein. Der Schwarzfelsklan hier besteht aus Überresten der Old Horde. Sie stehen der Allianz weiterhin gewaltsam feindselig gegenüber und handeln unabhängig von Thralls neuer Horde in Kalimdor.",al={"sind das orcs der horde","gehört der schwarzfelsklan zu thralls horde","freundliche orcs im rotkammgebirge"}}},fx={ded9bd4b={q="Warum will Marschall Marris, dass die Schwarzfelsorcs getötet werden?",a="Der Schwarzfelsklan ist aus der Brennende Steppe herabgestiegen, hat Burg Steinwacht eingenommen und marodiert durch das Land nördlich von Seenhain. Ihre ständigen Überfälle haben die Bürger der Stadt effektiv innerhalb ihrer Grenzen gefangen gehalten, wie Vieh eingepfercht. Marschall Marris will diese erstickende Belagerung brechen, die nördlichen Grenzen der Region sichern und auskundschaftende Kriegstrupps eliminieren, bevor Seenhain vollständig überrannt wird.",al={"motiv von marris","warum blackrock-orcs töten","warum blackrock menace"}},["29f2a399"]={q="Wer sind die Schwarzfelsinvasoren, die Seenhain bedrohen?",a="Ihr werdet gegen die Schwarzfelsorcs entsandt, Überreste der Alten Horde, die aus der Brennende Steppe herabgestiegen sind. Nachdem sie Burg Steinwacht im Norden beansprucht haben, marodieren sie aktiv durch die Wildnis und haben begonnen, Außenposten in den südöstlichen Ausläufern des Rotkammgebirge zu errichten, um Seenhain zu erdrosseln und ihren territorialen Griff über die Berge auszuweiten.",al={"wer sind die blackrock-orcs","wer ist das ziel","orcs in burg steinwacht"}},e27bf976={q="Warum benötigt Marschall Marris Abenteurer anstatt der Wache von Seenhain?",a="Die örtliche Garnison von Seenhain ist bis zum Äußersten angespannt. Da die Armee von Sturmwind abwesend ist und keine Verstärkung schickt, können es sich Marris und seine wenigen verbliebenen Wachen nicht leisten, in die Wildnis auszurücken, ohne die Stadt völlig wehrlos zurückzulassen. Um die vorrückenden Invasoren zurückzuschlagen, ist er auf fähige unabhängige Söldner und Abenteurer angewiesen.",al={"warum kämpft die wache nicht","warum ich marris","warum braucht man abenteurer"}}},fp="16,173,18.325.0,21.350.0,41.140.0,21.166.0,42.141.0,48.129.0,45.137.1,44.164.0"}
P.entries["quest:200"] = {n="Buchmacher Herod",s="Ein Informationsleck lässt Lieutenant Doren in seinen Reihen nach einem Verräter suchen. Kurzen hat Thorsens Geheimnis erfahren, und Doren will die Aufzeichnungen von Buchmacher Herod, Kurzens Logistikoffizier, aus Kurzens Truppenlager beschaffen.",h="Ein Informationsleck lässt Lieutenant Doren in seinen Reihen nach einem Verräter suchen.",kw={"buchmacher herod","colonel kurzen","kurzens truppenlager","lieutenant doren","schlingendorntal","thorsen"},ang={["faction:Alliance"]="Lieutenant Doren und seine Männer dienten einst unter Colonel Kurzen, bevor sie sich von ihm lossagten. Nun suchen sie in ihren eigenen Reihen nach einem Spion."},sec={{t="Ein Leck in den Reihen",b="Lieutenant Doren vermutet einen Verräter unter seinen Männern. Kurzen hat Thorsens Geheimnis erfahren, und das Informationsleck bedroht ihre Operationen. Deshalb muss Doren dessen Ursprung finden. Thorsen hielt über Buchmacher Herod, den Logistikoffizier des Colonels, eine Verbindung in Kurzens Truppenlager aufrecht. Herods schriftliche Aufzeichnungen könnten zeigen, wie die Operation aufgedeckt wurde."},{t="Das Logistikbüro",b="Buchmacher Herods Papiere befinden sich in Kurzens Truppenlager. Als Doren unter Kurzen diente, lag Herods Büro im obersten Stockwerk des einzigen zweistöckigen Hauses im Lager. Nachschubanforderungen und Nachrichten von Colonel Kurzen könnten offenbaren, wie Thorsens Geheimnis verraten wurde."}},faq={{q="Wer ist Buchmacher Herod?",a="Buchmacher Herod ist der Logistikoffizier von Colonel Kurzens Männern. Er beaufsichtigt den Nachschub und den Lagerbetrieb in Kurzens Truppenlager. Einst diente er Thorsen als Kontaktmann im Lager.",al={"herods rolle","wer ist der buchmacher","buchmacher herod hintergrundgeschichte"}},{q="Warum will Lieutenant Doren Herods Aufzeichnungen?",a="Lieutenant Doren vermutet, dass ein Spion ihr Lager verraten hat, nachdem Colonel Kurzen Thorsens Geheimnis erfahren hatte. Er hofft, dass Herods Logistikprotokolle und Korrespondenz zeigen, wie die Informationen nach außen gelangten.",al={"warum herods aufzeichnungen beschaffen","doren spion","wie wurde thorsen entlarvt"}},{q="Wo befinden sich Buchmacher Herods Aufzeichnungen?",a="Herods Büro liegt im obersten Stockwerk des einzigen zweistöckigen Hauses in Kurzens Truppenlager. Doren glaubt, dass seine Aufzeichnungen wahrscheinlich noch dort sind.",al={"wo sind die aufzeichnungen","herods büro standort","zweistöckiges haus kurzen"}},{q="Was geht dieser Untersuchung voraus?",a="Die Untersuchung folgt auf Jungle Secrets. Dort kommt Lieutenant Doren zu dem Schluss, dass jemand Thorsens Geheimnis an Kurzens Männer verraten haben muss.",al={"vorherige quest","buchmacher herod voraussetzung"}}},fp="12,196,19.321.0,20.258.0,20.170.0,47.187.0,41.141.0,37.141.0"}
P.entries["quest:201"] = {n="Untersuchung des Lagers",s="Krazek hat gehört, dass Hemet Nesingwary möglicherweise im Schlingendorntal ist. Er bittet Euch, das Jägerlager nahe dem Nazferitisee zu finden und den Bericht zu bestätigen.",h="Krazek hat gehört, dass Hemet Nesingwary möglicherweise im Schlingendorntal ist.",kw={"beutebucht","hemet nesingwary","jägerlager","untersuchung des lagers","krazek","der nazferitisee","schlingendorntal","venture company"},ang={["class:Hunter"]="Als Jäger könnte Euch die Versammlung unter Hemet Nesingwarys Führung anlocken, von der die Gerüchte erzählen. Dort könnt Ihr Eure Fähigkeiten im Spurenlesen und Schießen im Dschungel auf die Probe stellen.",["race:Dwarf"]="Als Zwerg könntet Ihr stolz auf Hemet Nesingwary sein, einen der berühmtesten zwergischen Scharfschützen und Abenteurer. Seine gemeldete Anwesenheit in der fernen südlichen Wildnis des Schlingendorntals könnte Eure Neugier wecken."},sec={{t="Berichte aus dem Dschungel",b="Berichten aus Beutebucht zufolge liegt im nördlichen Schlingendorntal ein Jägerlager. Krazek hat gehört, es liege am Fluss, gleich hinter dem Schürfgebiet der Venture Company nahe dem Nazferitisee. Im Dschungel herrscht Gesetzlosigkeit, und es gibt viele Gefahren und widerstreitende Interessen. Ein bewaffnetes Lager erregt Aufmerksamkeit."},{t="Ein berühmter Scharfschütze",b="Hemet Nesingwary könnte unter den Jägern im Lager sein. Der berühmte Zwergenscharfschütze ist in allen Landen als herausragender Entdecker mit einflussreichen Verbindungen bekannt. Krazek schickt Euch flussaufwärts, um herauszufinden, ob der legendäre Jäger eingetroffen ist."}},faq={{q="Wer erteilt den Auftrag, das Lager zu untersuchen?",a="Krazek, ein Agent in Beutebucht, schickt Euch los, um das Lager zu finden und seinen Standort zu melden.",al={"wer will das lager untersuchen lassen","wer hat diese quest gegeben","krazek beutebucht"}},{q="Wer ist Hemet Nesingwary?",a="Hemet Nesingwary ist ein berühmter zwergischer Großwildjäger und Entdecker. Berichten aus Beutebucht zufolge lagert er mit anderen Jägern nahe dem Nazferitisee, und sein Ruf und seine Verbindungen haben Interesse geweckt.",al={"hemet nesingwary schlingendorntal","wer ist hemet nesingwary","berühmter zwergenjäger schlingendorntal"}},{q="Wo liegt das Jägerlager?",a="Das Jägerlager liegt flussaufwärts von den Bergbaubetrieben der Venture Company, am Nazferitisee im nördlichen Schlingendorntal.",al={"standort des jägerlagers","wo ist nesingwarys lager","wo ist das lager flussaufwärts"}},{q="Warum interessiert sich Krazek für dieses Jägerlager?",a="Berichten zufolge könnte Hemet Nesingwary im Lager sein. Sein Einfluss und seine Verbindungen machen Krazek vorsichtig und neugierig.",al={"warum interessiert sich krazek dafür","warum die jäger untersuchen","krazeks beweggrund"}},{q="In welcher Beziehung stehen die Jäger zur Venture Company?",a="Die Jäger gehören nicht zur Venture Company. Ihr Lager liegt flussaufwärts vom Bergbaubetrieb der Firma nahe dem Nazferitisee, der als Orientierungspunkt dient.",al={"verbindung zur venture company","gehören die jäger zur venture company","venture company nazferitisee"}},{q="Wem erstattet Ihr Bericht, nachdem Ihr das Lager gefunden habt?",a="Nachdem Ihr das Lager am Fluss gefunden und ausgekundschaftet habt, kehrt nach Süden nach Beutebucht zurück und erstattet Krazek direkt Bericht.",al={"was tun nach dem finden des lagers","wem bericht erstatten","wo untersuchung des lagers abgeben"}}},fp="20,145,21.270.0,19.230.0,43.87.0,24.198.0,35.129.0,46.112.0,57.154.0,45.101.0"}
P.entries["quest:202"] = {n="Colonel Kurzen",s="Im Rebellenlager schickt Euch Lieutenant Doren gegen Colonel Kurzen und seine innere Wache. Ihre Niederlage könnte das Überleben der Rebellen sichern.",h="Im Rebellenlager schickt Euch Lieutenant Doren gegen Colonel Kurzen und seine innere Wache.",kw={"colonel kurzen","kurzen","lieutenant doren","rebellenlager","stockpile","schlingendorntal"},ang={["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr durch Kurzens Ausschaltung helfen, die Herrschaft eines abtrünnigen Offiziers aus Sturmwind über das nördliche Schlingendorntal zu brechen."},sec={{t="Das Herz von Stockpile",b="Lieutenant Dorens Überläufer stehen im letzten Kampf gegen ihren ehemaligen Kommandanten. Ihr habt geholfen, Kurzens Elitespezialisten niederzuringen, doch die Rebellen bleiben in Gefahr, solange er seine Dschungelredoute hält. Doren schickt Euch in die Höhle Stockpile, wo Kurzen an der Seite seiner Unterhäuptlinge und Eliteeinheiten seine Truppen befehligt."},{t="Schlag gegen den Schlangenkopf",b="Lieutenant Doren braucht einen Beweis dafür, dass Kurzen gefallen ist. Er bittet Euch, den Kopf des abtrünnigen Colonels zurückzubringen und seine Eliteeinheiten und Unterhäuptlinge zu besiegen. Die Konfrontation in der Höhle bietet den Rebellen ihre einzige Chance, inmitten der Gefahren des nördlichen Schlingendorntals aufzuatmen."}},faq={{q="Wer erteilt diesen Auftrag?",a="Nachdem Ihr Special Forces abgeschlossen habt, schickt Euch Lieutenant Doren vom Rebellenlager im nördlichen Schlingendorntal aus los.",al={"wer vergibt die quest","questgeber","wo gibt es colonel kurzen"}},{q="Wo befindet sich Colonel Kurzen?",a="Kurzen befehligt seine Truppen tief im Höhlensystem Stockpile, innerhalb von Kurzens Lager im nördlichen Schlingendorntal.",al={"wo ist kurzen","kurzens standort","wie findet man colonel kurzen"}},{q="Welchen Beweis verlangt Lieutenant Doren?",a="Lieutenant Doren bittet Euch, Kurzens Kopf als Beweis für den Tod des abtrünnigen Kommandanten zurückzubringen und seine Eliteeinheiten und Unterhäuptlinge zu besiegen.",al={"welcher beweis wird benötigt","kurzens beweis","abzugebender gegenstand"}},{q="Was ging dieser Konfrontation voraus?",a="In Special Forces habt Ihr Kurzens spezialisierte Kämpfer geschwächt. Dann habt Ihr Euch seiner zentralen Befehlsstruktur zugewandt.",al={"voraussetzungsquest","was ist die vorherige quest","questreihe vor kurzen"}}},fp="14,137,26.318.0,27.260.0,22.113.0,32.123.0,41.139.0,36.127.0"}
P.entries["quest:203"] = {n="Die zweite Rebellion",s="Im Rebellenlager im nördlichen Schlingendorntal ruft Sergeant Yohwa gegen Colonel Kurzens Übermacht um Hilfe. Im Verhältnis von zehn zu eins unterlegen, können die Rebellen keinen langen, offenen Krieg führen. Sie schlagen schnell und im Verborgenen zu, in der Hoffnung, Kurzens Reihen zu lichten und den Druck auf ihre Zuflucht zu mindern.",h="Im Rebellenlager im nördlichen Schlingendorntal ruft Sergeant Yohwa gegen Colonel Kurzens Übermacht um Hilfe.",kw={"colonel kurzen","dschungelkämpfer","kurzen","rebellenlager","sergeant yohwa","special forces","schlingendorntal","yohwa"},sec={{t="Ein aussichtsloser Kampf",b="Im Rebellenlager stehen die Rebellen Colonel Kurzens Streitmacht gegenüber, mit mindestens zehn Feinden für jeden der Ihren. Sergeant Yohwa weiß, dass der Colonel ein brillanter militärischer Taktiker ist. Ein offener Zermürbungskrieg ließe den Rebellen keine Chance.\n\nAlso wenden sie Kurzens verdeckte Methoden gegen ihn selbst an. Sie schlagen schnell in seinem Lager zu und fliehen dann, bevor starke Verstärkung eingreifen kann."},{t="Angriff auf das Lager",b="Sergeant Yohwa bittet Euch, nach Osten in Kurzens Festung vorzustoßen und ein beträchtliches Kontingent seiner Dschungelkämpfer auszuschalten. Ihre Überzahl setzt das Rebellenlager schwer unter Druck. Lichtet ihre Reihen, und die Zuflucht kann aufatmen."}},faq={{q="Wer ist Sergeant Yohwa?",a="Sergeant Yohwa ist eine Offizierin im Rebellenlager im nördlichen Schlingendorntal. Sie koordiniert verdeckte Angriffe auf Colonel Kurzens Heer.",al={"yohwa","wer vergibt die zweite rebellion","sergeant yohwa"}},{q="Wo liegt Colonel Kurzens Lager?",a="Colonel Kurzens Lager liegt östlich des Rebellenlagers, inmitten der dichten Wildnis des nördlichen Schlingendorntals.",al={"kurzens lager standort","wo sind die dschungelkämpfer","kurzen standort"}},{q="Warum setzen die Rebellen auf verdeckte Taktiken statt auf offenen Krieg?",a="Die Rebellen stehen mindestens zehn Kämpfern von Colonel Kurzen für jeden der Ihren gegenüber. Gegen einen brillanten Militärstrategen ist ein offener Angriff unmöglich, also verlassen sie sich auf schnelle Guerillaangriffe.",al={"warum verdeckt","warum kurzen nicht offen bekämpfen","taktiken der rebellen"}},{q="Was folgt auf Die zweite Rebellion?",a="Nachdem Ihr Kurzens Dschungelkämpfer niedergestreckt habt, bietet Sergeant Yohwa den nächsten Schritt an: Special Forces.",al={"nächste quest","was kommt nach der zweiten rebellion","folgequest der zweiten rebellion"}}},fp="20,293,15.380.0,21.217.0,22.140.0,39.112.0,60.200.0,38.97.0"}
P.entries["quest:2038"] = {n="Bingles' verschwundene Werkzeuge",s="Am Südostufer von Loch Modan sitzt Bingles Blastenheimer fest, nachdem Troggs seine Ausrüstung gestohlen haben. Ihr könnt seine Werkzeuge und Blastencapper-Sprengsätze zurückholen, damit er seinen Gyrokopter reparieren und wieder in den Kampf um Gnomeregan ziehen kann.",h="Am Südostufer von Loch Modan sitzt Bingles Blastenheimer fest, nachdem Troggs seine Ausrüstung gestohlen...",kw={"bingles","blastencapper","blastenheimer","gnomeregan","gyrokopter","hammer","loch modan","schraubenzieher","der loch","trogg","schraubenschlüssel"},ang={["faction:Alliance"]="Als Mitglied der Allianz sichert Ihr die Wasserwege und unterstützt die Bemühungen zur Rückeroberung der verlorenen Gebiete von Khaz Modan, indem Ihr einem anderen Piloten in Loch Modan helft.",["profession:Engineering"]="Als Ingenieur wisst Ihr, dass Spezialwerkzeuge und instabile Sprengsätze wie der Blastenheimer Blastencapper in Trogg-Händen gefährlich und ein Affront gegen die Handwerkskunst sind.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass die Troggs auf den Inseln des Lochs den örtlichen Handel und Reiseverkehr bedrohen. Jeder Schlag gegen ihre Lager hilft den Mountaineers.",["race:Gnome"]="Als Gnom bringt Ihr Euer Volk mit jedem zurückgeholten Werkzeug einer Gegenoffensive aus der Luft gegen die Troggs und Lepragnome näher, die Gnomeregan ersticken."},sec={{t="Ein nasser Absturz",b="Bingles Blastenheimer stürzt mit seinem Gyrokopter in die kalten Gewässer von Loch Modan. Benommen schleppt er sich ans Ufer, und Troggs von den Inseln in der Seemitte fallen über ihn her. Sie stehlen seine wertvollsten Habseligkeiten."},{t="Gnomischer Erfindergeist unter Belagerung",b="Die Troggs verteilen Bingles’ Ausrüstung auf ihre Insellager. Unter den gestohlenen Dingen sind ein Schraubenschlüssel, ein Schraubenzieher und ein Hammer sowie seine instabile Erfindung mit hoher Sprengkraft, der Blastenheimer Blastencapper. In den Händen der Troggs bringen die Sprengsätze Reisende in unmittelbare Gefahr."},{t="Für Gnomeregan",b="Bingles kämpft darum, seine Heimat Gnomeregan von unterirdischen Troggs und verstrahlten Lepragnomen zu befreien. Er stellt sich einen entscheidenden Luftangriff vor, doch ohne seine Werkzeuge und Blastencapper kann er seine Flugmaschine nicht wieder aufbauen. Sein Feldzug bleibt im Schilf stecken."}},faq={{q="Warum sitzt Bingles Blastenheimer in Loch Modan fest?",a="Bingles Blastenheimer sitzt nach dem Absturz seines Gyrokopters in Loch Modan fest. Mühsam schleppt er sich ans Südostufer, wo Troggs von den nahen Inseln ihn überfallen und seine Werkzeuge und experimentellen Sprengsätze stehlen.",al={"warum ist bingles hier","wie ist bingles abgestürzt","bingles absturz"}},{q="Welche Vorräte haben die Troggs gestohlen?",a="Die Troggs stehlen Bingles’ Schraubenschlüssel, Schraubenzieher, Hammer und seinen Spezialsprengsatz, den Blastenheimer Blastencapper.",al={"was haben die troggs gestohlen","bingles vorräte","welche gegenstände bingles"}},{q="Wohin haben die Troggs Bingles’ Ausrüstung gebracht?",a="Die Troggs bringen Bingles’ Ausrüstung in ihre Lager auf Inseln im nördlichen Teil des Lochs. Sie verteilen die Werkzeuge und Sprengsätze entlang der felsigen Ufer.",al={"wo sind bingles werkzeuge","lage der trogginsel","wo ist der blastencapper"}},{q="Was ist der Blastencapper?",a="Der Blastenheimer Blastencapper ist ein Sprengsatz, den Bingles für Luftangriffe gegen die Feinde entwickelt hat, die Gnomeregan besetzen.",al={"was ist der blastencapper","blastenheimer blastencapper","bingles sprengsatz"}},{q="Welche Bewegung meint Bingles?",a="Bingles meint die Rückeroberung Gnomeregans. Er hofft, einen Luftangriff gegen die unterirdischen Troggs und Lepragnome anzuführen, die die gnomische Hauptstadt besetzt halten.",al={"welche bewegung","für gnomeregan","bingles anliegen"}},{q="Warum kann Bingles die Vorräte nicht selbst zurückholen?",a="Bingles kann die Vorräte nicht zurückholen, weil er nach dem Absturz allein und unbewaffnet ist und sein Gyrokopter außer Reichweite liegt. Offenes Wasser zu überqueren, um sich ohne Waffen oder Fluggerät aggressiven Troggs zu stellen, wäre für einen einsamen Ingenieur Selbstmord.",al={"warum holt bingles sie nicht","warum wartet bingles"}}},fx={["008fc445"]={q="Warum möchte Bingles Blastenheimer, dass seine Vorräte geborgen werden?",a="Bingles ist mit seiner Flugmaschine in Der Loch abgestürzt, während er sie testete, aber der Verlust seiner Ausrüstung gefährdet mehr als nur seine Bergung. Er hat spezialisierte Werkzeuge und firmeneigene Blastenheimer Blastencapper-Sprengstoffe speziell für die gnomische Luftoffensive zur Rückeroberung von Gnomeregan angefertigt. Ohne seine Werkzeuge zum Wiederaufbau und seine Munition zum Abwerfen kann der Versuch, die Troggs und die Lepragnome, die seine Heimat besetzen, zu bombardieren, nicht fortgesetzt werden.",al={"motiv von bingles","warum braucht bingles seine werkzeuge","warum bingles helfen"}},["0d3e655b"]={q="Wer hat Bingles' Vorräte genommen und warum sind sie hier?",a="Troggs, die die Inseln von Loch Modan befallen haben, haben Bingles kurz nach seinem Absturz überfallen und seine Ausrüstung geplündert. Diese primitiven unterirdischen Bestien wurden während der Ausgrabungen der Zwerge in ganz Khaz Modan freigelegt. Angetrieben von einem gewalttätigen territorialen Instinkt und einem Hang dazu, sich glänzende mechanische Kuriositäten zu schnappen, schleppten sie Bingles' Werkzeugkasten und die flüchtigen Sprengstoffe zurück in ihre Lager am See.",al={"wer hat bingles werkzeuge gestohlen","troggs in loch modan bingles","warum sind troggs auf den inseln"}}},fp="25,227,14.206.0,29.266.0,14.264.0,52.217.0,40.116.0,40.153.0,26.129.0,38.157.0,48.233.0"}
P.entries["quest:2039"] = {n="Sucht Bingles",s="In Eisenschmiede beginnt Gnoarn die Suche für „Sucht Bingles“, nachdem über eine Woche jede Nachricht ausblieb. Bingles Blastenheimer verschwand während eines Flugs zum gefallenen Gnomeregan, und Suchende werden an die Ufer von Loch Modan geschickt. Dort ist Bingles am Leben und braucht Hilfe bei der Bergung mechanischer Ausrüstung.",h="In Eisenschmiede beginnt Gnoarn die Suche für „Sucht Bingles“, nachdem über eine Woche jede Nachricht...",kw={"bingles","blastenheimer","flugmaschine","gnoarn","gnomeregan","eisenschmiede","loch modan","aufklärung","tüftlerstadt"},ang={["faction:Alliance"]="Als Späher der Allianz helft Ihr, die Nachrichtenverbindung zwischen den Hallen von Eisenschmiede und den Einsätzen vor Ort in ganz Loch Modan wiederherzustellen.",["profession:Engineering"]="Als Ingenieur kennt Ihr die Gefahren der gnomischen Luftfahrt, bei der eine verlorene Flügelmutter oder eine Triebwerksexplosion zum Außeneinsatz gehört.",["race:Gnome"]="Als Gnom helft Ihr mit der Rettung von Bingles, die Hoffnung auf die Rückeroberung Gnomeregans am Leben zu halten, bei der jeder Späher und jede Flugmaschine zählt."},sec={{t="Ein vermisster Pilot",b="Der Gnomenflieger Bingles Blastenheimer wurde aus Tüftlerstadt in Eisenschmiede entsandt, um die verstrahlten Ruinen von Gnomeregan aus der Luft auszukundschaften. Mehr als eine Woche ist ohne Nachricht vergangen. Gnoarn fürchtet, Bingles könnte sich selbst vom Himmel gesprengt haben, eine Gefahr der Gnomeningenieurskunst. Seinem letzten Bericht zufolge befand er sich irgendwo über den Gewässern von Loch Modan."},{t="Unten am Loch",b="Suchende finden Bingles lebend am Ufer von Loch Modan, weit entfernt von einem tragischen Trümmerhaufen. Seine lange Abwesenheit beunruhigt ihn nicht, und er ist leicht gekränkt, weil jemand an seinen Flugkünsten gezweifelt hat. Statt umgehend zurückzukehren und Gnoarn Bericht zu erstatten, bittet er seinen Retter, Werkzeuge und Blastencapper-Sprengstoffe zurückzuholen, die Troggs gestohlen haben. Er braucht sie, um seine Pflichten für die Gnomenbewegung wieder aufzunehmen."}},faq={{q="Wer ist Bingles Blastenheimer?",a="Bingles Blastenheimer ist ein exzentrischer Gnomenflieger und Mechaniker. Er wurde entsandt, um das gefallene Gnomeregan aus der Luft auszukundschaften, und stürzte dann nahe Loch Modan ab.",al={"wer ist bingles","bingles blastenheimer hintergrundgeschichte","wer ist der pilot"}},{q="Warum flog Bingles über Gnomeregan?",a="Nachdem Gnomeregan den Troggs und der Strahlung zum Opfer gefallen war, behielten die Anführer und Tüftler der Gnome die Stadt im Auge. Bingles überflog die Stadt, um feindliche Stellungen und die Lage vor Ort auszukundschaften und so zur Rückeroberung ihrer Heimat beizutragen.",al={"bingles mission","warum flog bingles","gnomeregan aufklärung"}},{q="Wo befindet sich Bingles?",a="Bingles befindet sich am südöstlichen Ufer von Loch Modan und versucht, seine abgestürzte Flugmaschine wieder in Ordnung zu bringen.",al={"wo ist bingles","sucht bingles fundort","wo bingles finden"}},{q="Wer ist Gnoarn?",a="Gnoarn ist ein gnomischer Koordinator in Tüftlerstadt in Eisenschmiede. Er behält gnomisches Personal und dessen Einsätze im Blick und beginnt die Suche, als Bingles nicht planmäßig zurückkehrt.",al={"wer ist gnoarn","questgeber gnoarn"}},{q="Was geschieht, nachdem Bingles gefunden wurde?",a="Nachdem Bingles gefunden wurde, können Abenteurer seinen Schraubenschlüssel, Schraubenzieher, Hammer und seine Blastencapper-Sprengstoffe von Troggs auf den Inseln des Lochs zurückholen.",al={"was folgt nach sucht bingles","flügelmutter quest","bingles folgequest"}},{q="Hat sich Bingles beim Absturz verletzt?",a="Bingles ist unverletzt, doch sein Stolz ist angekratzt, weil Gnoarn an seinen Flugkünsten gezweifelt hat. Er konzentriert sich darauf, die Werkzeuge und Sprengstoffe zurückzubekommen, die ihm die Troggs gestohlen haben.",al={"ist bingles verletzt","ist bingles gestorben"}}},fx={b67b7bf8={q="Warum will Gnoarn, dass Bingles gefunden wird?",a="Bingles wurde auf einen kritischen Aufklärungsflug über das gefallene Gnomeregan geschickt und hat sich seit mehr als einer Woche nicht zurückgemeldet. Angesichts der unberechenbaren Natur gnomischer Maschinen und Bingles' Hang zur Katastrophe befürchtet Gnoarn, dass der Pilot sich irgendwo in der Wildnis in die Luft gesprengt hat. Er braucht jemanden, der die Region in der Nähe von Loch Modan, wo Bingles zuletzt gesehen wurde, durchsucht, um sein Schicksal zu bestimmen.",al={"warum bingles finden","motiv von gnoarn","warum suchen nach bingles schicken"}}},fp="12,264,15.329.0,16.390.0,29.150.0,39.209.0,25.95.0,14.162.0,35.144.0,31.170.0"}
P.entries["quest:204"] = {n="Schlechte Medizin",s="Im Rebellenlager im nördlichen Schlingendorntal sucht Sergeant Yohwa einen Weg, Colonel Kurzens Streitmacht zu schwächen. Seine Medizinmänner heilen seine Soldaten und vergiften Yohwas Kämpfer, und der Widerstand braucht ihre Heilmittel und Gifte.",h="Im Rebellenlager im nördlichen Schlingendorntal sucht Sergeant Yohwa einen Weg, Colonel Kurzens Streitmacht...",kw={"dschungelheilmittel","kurzen","kurzen compound","medizinmänner","rebellenlager","sergeant yohwa","schlingendorntal","giftfarnextrakt"},ang={["faction:Alliance"]="Wenn die Allianz Kurzens Versorgung mit Heilmitteln unterbindet, können mehr Kämpfer des Rebellenlagers den Kampf gegen seine Streitmacht überleben."},sec={{t="Dem Stützpunkt die Unterstützung entziehen",b="Colonel Kurzens Medizinmänner heilen seine Soldaten und vergiften Yohwas Kämpfer mit Giftfarnextrakt. Sergeant Yohwa bittet Euch, ihre Vorräte aus dem Kurzen Compound zu beschaffen. Die Heilmittel können verwundete Kämpfer im Rebellenlager versorgen. Eine Probe des Giftfarnextrakts ermöglicht es dem Widerstand, das Gift zu untersuchen und eigene Gegenmittel herzustellen."}},faq={{q="Wer bietet diesen Auftrag an?",a="Im Rebellenlager im nördlichen Schlingendorntal bittet Sergeant Yohwa Euch, die medizinischen Vorräte zu beschaffen.",al={"wer vergibt schlechte medizin","schlechte medizin questgeber","yohwa quest"}},{q="Warum braucht Sergeant Yohwa Dschungelheilmittel?",a="Kurzens Medizinmänner verwenden Dschungelheilmittel, um ihre Soldaten zu heilen. Der Widerstand braucht die Heilmittel, um seine verwundeten Kämpfer zu versorgen.",al={"warum dschungelheilmittel benötigt","dschungelheilmittel zweck"}},{q="Wofür wird der Giftfarnextrakt verwendet?",a="Kurzens Streitkräfte verwenden Giftfarnextrakt, um Yohwas Kämpfer zu vergiften. Yohwa braucht eine Probe, damit das Lager das Gift untersuchen und Gegenmittel herstellen kann.",al={"warum giftfarnextrakt","extrakt verwendung"}},{q="Wo werden diese medizinischen Vorräte aufbewahrt?",a="Die Vorräte befinden sich im Kurzen Compound. Medizinmänner tragen die Heilmittel bei sich, während Vorratskisten im Lager die Giftfarnextrakte enthalten.",al={"wo dschungelheilmittel finden","extrakt fundort"}}},fp="12,226,32.332.0,27.106.0,45.130.0,40.149.0,38.148.0"}
P.entries["quest:2040"] = {n="Unterirdischer Angriff",s="Shoni die Schtille schickt Abenteurer der Allianz in die Todesminen, um einen Energiekern zu erbeuten. Die vertriebenen Gnome brauchen ihn, um Bohrer durch das Gestein rund um Gnomeregan zu treiben und ihre Heimat zurückzuerobern.",h="Shoni die Schtille schickt Abenteurer der Allianz in die Todesminen, um einen Energiekern zu erbeuten.",kw={"die todesminen","gnoamsprenkelspross","gnomeregan","goblin-schredder","gyrodrillmatic","shoni die schtille","troggs","unterirdischer angriff"},ang={["faction:Alliance"]="Als Abenteurer der Allianz stärkt Ihr Sturmwinds Verbindung zu seinen vertriebenen gnomischen Verbündeten und greift die Nachschublinie der Defias an.",["profession:Engineering"]="Als Ingenieur wisst Ihr den kühnen Plan zu schätzen, den Energiekern eines Goblin-Schredders zu erbeuten und damit präzise gnomische Grabungsmaschinen anzutreiben.",["race:Gnome"]="Als vertriebener gnomischer Abenteurer helft Ihr, einen Energiekern für Bohrer zu bergen, die die Felswände Eurer gefallenen Heimat durchbrechen und die Troggs aus Gnomeregan vertreiben helfen können."},sec={{t="Verzweifelter Erfindergeist",b="Gnomische Tüftler flohen durch Khaz Modan und Sturmwind, nachdem primitive Troggs Gnomeregan zu Fall gebracht hatten. Shoni die Schtille plant bereits, wie sie das Gestein rund um ihre verlorene Heimat durchbrechen können. Ihre Gyrodrillmatic Excavationators brauchen gewaltige Energie, um sich durch das unterirdische Gestein zu bohren. In den Ländern der Menschen gibt es keine örtlichen Stromnetze, also haben sich die Gnome schwerer Goblin-Maschinerie aus der kriminellen Unterwelt zugewandt."},{t="Die Gießereien der Defias plündern",b="In den Schächten der Todesminen in Westfall beschäftigt Edwin van Cleefs Bruderschaft der Defias Goblin-Ingenieure, die Kriegsmaschinen bauen. Eine dieser Maschinen ist ein funktionstüchtiger Goblin-Schredder, ein schwerfälliger Automat. Shoni schickt Agenten der Allianz aus, um ihn zu zerstören oder zu zerlegen und sein spezialisiertes Herzstück zu bergen, das Gnoamsprenkelspross. Die vertriebenen Gnome brauchen diese Goblin-Energieversorgung, um ihre Bohrer durch das unterirdische Gestein zu treiben und ihre Gegenoffensive zur Rückeroberung von Gnomeregan einzuleiten."}},faq={{q="Wer vergibt die Quest Unterirdischer Angriff?",a="Shoni die Schtille, eine gnomische Ingenieurin im Zwergendistrikt von Sturmwind, schickt Euch los. Andere Gnome verweisen Abenteurer oft an sie, nachdem sie von ihren ehrgeizigen Plänen erzählt haben.",al={"questgeber unterirdischer angriff","wer vergibt unterirdischer angriff","shoni quest"}},{q="Wo finde ich das Gnoamsprenkelspross?",a="Ihr bergt das Gnoamsprenkelspross aus einem funktionstüchtigen Goblin-Schredder tief in den Gießereistollen der Todesminen in Westfall.",al={"gnoamsprenkelspross fundort","wo ist gnoamsprenkelspross","schredderteil todesminen"}},{q="Warum braucht Shoni Teile eines Goblin-Schredders?",a="Gnomische Gyrodrillmatic Excavationators brauchen eine leistungsstarke, tragbare Energieversorgung, um die verstärkten unterirdischen Begrenzungen rund um Gnomeregan zu durchbrechen. Der Hochleistungskern, der den Goblin-Schredder der Defias antreibt, liefert die mechanische Kraft, die diese Bohrer benötigen.",al={"warum goblinteile","warum schredder-energieversorgung","gnoamsprenkelspross zweck"}},{q="Was ist das übergeordnete Ziel dieser Mission?",a="Die vertriebenen Gnome wollen schwere Bohrmaschinen antreiben, sich durch das Gestein rund um das besetzte Gnomeregan graben und die dortigen Troggs mit einem Überraschungsangriff treffen.",al={"warum unterirdischer angriff","gnomeregan zurückerobern quest","angriffsplan der gnome"}},{q="Was ist Gnomeregan zugestoßen, dass dieser Angriff geplant wurde?",a="Eine unterirdische Invasion der Troggs drang aus den Tiefen unter Gnomeregan empor und überrannte die Stadt. Giftige Strahlung verseuchte sie während der chaotischen Verteidigung und zwang die Überlebenden, als Flüchtlinge nach Eisenschmiede und Sturmwind zu fliehen.",al={"warum fiel gnomeregan","was geschah mit gnomeregan","trogg-invasion"}},{q="Sind die Bruderschaft der Defias und die Troggs verbündet?",a="Nein, die Bruderschaft der Defias und die Troggs haben keine Verbindung zueinander. Die Defias heuerten Goblin-Tüftler an, um in Westfall Kriegsmaschinen zu bauen, und Shoni nutzt ihre Gießerei in den Todesminen als Quelle leistungsstarker Goblin-Technik.",al={"defias und troggs","sind troggs mit defias verbündet"}}},fx={["41842bc5"]={q="Was ist der Gnoamsprenkelspross?",a="Der Gnoamsprenkelspross ist eine intakte, hocheffiziente Energiezelle der Goblins, die in dem Schredder untergebracht ist, der tief in den Todesminen operiert. Shoni die Schtille beabsichtigt, diesen Energiekern direkt in die Gyrodrillmatic Excavationators der Gnome zu integrieren. Diese schweren Bohrmaschinen benötigen enorme Energie, um sich durch die dichte, felsige unterirdische Umrandung zu bohren, die Gnomeregan abschirmt, und so einen Eingang für die Angriffstruppen der Gnome zu schaffen, die darauf warten, ihre Heimat zurückzuerobern.",al={"was ist gnoamsprenkelspross","zweck von sprenkelspross","was macht die schredder-energiezelle"}},["37ad24fa"]={q="Warum schickt Shoni Euch hinter dem Goblin-Schredder in den Todesminen her?",a="The Defias Brotherhood setzt fortschrittliche Goblin-Technik ein, einschließlich eines voll funktionsfähigen Holz- und Bergbauschredders, um ihre geheimen Operationen unter Mondbruch auszugraben und zu konstruieren. Da diese Kriegsmaschinen bemerkenswert starke Energiekerne verwenden, identifizierte Shoni diese Maschine als erstklassiges Ziel zur Bergung. Ihr werdet ausgesandt, um den Schredder tief im Inneren des Geländes zu demontieren oder zu zerstören und seine intakte Energieeinheit zu extrahieren, bevor die Bruderschaft sie weiter nutzen kann.",al={"wer ist das ziel in den todesminen","warum schredder töten","warum gibt es einen schredder in den todesminen"}}},fp="19,187,21.404.0,28.462.0,40.170.0,43.120.0,49.243.0,41.178.0,67.215.0,49.212.0"}
P.entries["quest:2041"] = {n="Sprecht mit Shoni",s="In Eisenschmiede werden Reisende der Allianz nach Sturmwind geschickt, um Shoni die Schtille zu finden, deren Einheit sich auf Gnomeregan vorbereitet.",h="In Eisenschmiede werden Reisende der Allianz nach Sturmwind geschickt, um Shoni die Schtille zu finden, deren...",kw={"die tiefenbahn","der zwergendistrikt","gnomeregan","gyrodrillmatic excavationator","eisenschmiede","shoni die schtille","sturmwind","tüftlerstadt","underground assault"},ang={["faction:Alliance"]="Als Reisender der Allianz könnt Ihr die Tiefenbahn nutzen, um Personal zwischen Eisenschmiede und Sturmwind zu befördern.",["profession:Engineering"]="Als Ingenieur erkennt Ihr, dass Shonis Projekt Gyrodrillmatic Excavationators erfordert, komplexe gnomische Maschinen für den Tunnelbau tief unter der Erde.",["race:Gnome"]="Als Gnom in Eisenschmiede könnt Ihr helfen, Eure verstrahlte Heimat zurückzugewinnen, indem Ihr Shonis Befehlen folgt und Euch der Rückeroberung von Gnomeregan anschließt."},sec={{t="Ein Ruf aus der Tüftlerstadt",b="Nachdem Gnomeregan der Strahlung zum Opfer gefallen war, errichteten überlebende Gnome ein Exilviertel in Eisenschmiede. Seine Ingenieure, Tüftler und Strategen suchen weiter nach einem Weg zurück in ihre verlorene Heimat. Die Tüftlerstadt leitet die Bemühungen, doch die Vorbereitungen reichen über Khaz Modan hinaus. Nun werden Abenteurer nach Süden nach Sturmwind geschickt, wo militärische Ausrüstung für den Kampf unter Tage vorbereitet wird."},{t="Unterirdische Ambitionen",b="Im Zwergendistrikt von Sturmwind befehligt Shoni die Schtille eine Elitetruppe, die für unterirdische Angriffe ausgebildet ist. Ihre Mineure brauchen Gyrodrillmatic Excavationators, um sich zu den von Troggs gehaltenen Sektoren vorzugraben. Die Tiefenbahn verläuft unter den Bergen zwischen Eisenschmiede und Sturmwind und macht die Reise zu Shoni einfach."}},faq={{q="Wer ist Shoni die Schtille?",a="Shoni die Schtille ist eine gnomische Offizierin in Sturmwind. Sie befehligt eine Einheit für unterirdische Angriffe, die schwere Grabungsmaschinen baut und einsetzt, um bei der Rückeroberung von Gnomeregan zu helfen.",al={"wer ist shoni","shoni die schtille","wer ist der npc"}},{q="Wo kann ich Shoni die Schtille finden?",a="Shoni befindet sich im Zwergendistrikt von Sturmwind, nahe den Schmiedekunstlehrern und Schmieden, nur wenige Schritte von der Tiefenbahnhaltestelle entfernt.",al={"wo ist shoni","shoni standort","shoni koordinaten"}},{q="Wie komme ich von Eisenschmiede nach Sturmwind?",a="Der schnellste Weg von Eisenschmiede nach Sturmwind führt über die Tiefenbahn im Nordosten der Tüftlerstadt. Sie bringt Reisende unter den Bergen hindurch direkt in den Zwergendistrikt von Sturmwind.",al={"reise nach sturmwind","eisenschmiede nach sturmwind","wie nach sturmwind gelangen"}},{q="Wobei braucht Shoni Hilfe?",a="Shoni rüstet eine Truppe für unterirdische Angriffe aus und braucht Bauteile für ihre Gyrodrillmatic Excavationators. Diese Bemühungen führen Abenteurer schließlich nach Westfall und in die Todesminen.",al={"shoni questziel","was will shoni"}},{q="Ist diese Quest erforderlich, um Underground Assault anzunehmen?",a="Nein. Dies ist eine optionale Hinführungsquest. Ihr könnt direkt in den Zwergendistrikt von Sturmwind gehen und mit Shoni sprechen, um Underground Assault anzunehmen.",al={"ist sprecht mit shoni pflicht","direkt zu shoni gehen"}},{q="Wie hängt das mit Gnomeregan zusammen?",a="Die Anführer der Gnome sammeln Truppen und Grabungstechnik, um die Verteidigung von Gnomeregan zu durchbrechen. Shonis Team entwickelt die unterirdischen Bohrer, die nötig sind, um in die verseuchte Stadt einzudringen.",al={"warum gnomeregan","verbindung zu den gnomen"}}},fx={["3fdd7df6"]={q="Warum schickt Euch der Questgeber zu Shoni die Schtille?",a="Die Gnome kämpfen einen schweren Kampf, um ihre gefallene Heimat Gnomeregan zurückzuerobern. Shoni die Schtille befehligt eine unterirdische Angriffstruppe, die spezialisierte Gyrodrillmatic Excavationators für die Kriegsanstrengungen vorbereitet, aber ihren Operationen in Sturmwind fehlen Arbeitskräfte. Das Hauptkommando in Eisenschmiede benötigt fähige Abenteurer, die bereit sind, nach Süden zu reisen und ihr kritisches Ingenieursprojekt zu unterstützen, bevor ihre Offensive voranschreiten kann.",al={"warum mit shoni sprechen","warum zu shoni schicken","warum shoni besuchen"}}},fp="16,117,22.360.0,22.321.0,25.171.0,35.133.0,41.188.0,31.179.0,50.139.0,36.189.0"}
P.entries["quest:205"] = {n="Troll-Hexerei",s="Bruder Nimetz schickt Euch ins Gebiet der Schädelspalter, um zu erfahren, was Colonel Kurzen verdorben hat. Nach Kurzen's Mystery bittet er Euch, Fetische von den Zauberwirkern des Stammes zu sammeln.",h="Bruder Nimetz schickt Euch ins Gebiet der Schädelspalter, um zu erfahren, was Colonel Kurzen verdorben hat.",kw={"bruder nimetz","colonel kurzen","mystiker","rebellenlager","schädelspalter","schlingendorntal","troll-hexerei","hexendoktor"},ang={["faction:Alliance"]="Als Reisender der Allianz könnt Ihr Bruder Nimetz im Rebellenlager helfen, herauszufinden, was Colonel Kurzen verdorben hat."},sec={{t="Der Verderbnis auf der Spur",b="Bruder Nimetz vermutet, dass dunkle Trollmagie hinter Colonel Kurzens Abstieg ins Böse steckt. Aus dem Dschungel geborgene Legenden haben ihn auf die Spur des zweiten Trollstammes weiter südlich geführt. Deshalb bittet er Euch, ins Gebiet der Schädelspalter vorzudringen und ihren Hexendoktoren und Mystikern Fetische abzunehmen. Er wird die darin enthaltene Magie im Rebellenlager untersuchen."}},faq={{q="Wer vergibt die Quest Troll-Hexerei?",a="Bruder Nimetz vergibt Troll-Hexerei im Rebellenlager im nördlichen Schlingendorntal.",al={"troll-hexerei questgeber","wer startet troll-hexerei","wo gibt es troll-hexerei"}},{q="Warum will Bruder Nimetz Fetische der Schädelspalter?",a="Bruder Nimetz will die dunklen magischen Gegenstände untersuchen und herausfinden, ob Trollhexerei Colonel Kurzens Abstieg ins Böse erklärt.",al={"warum braucht bruder nimetz fetische","zweck von troll-hexerei","kurzens verderbnis fetische"}},{q="Welche Gegner tragen die Fetische?",a="Hexendoktoren und Mystiker der Schädelspalter tragen im Gebiet der Schädelspalter Fetische bei sich.",al={"wer lässt schädelspalterfetische fallen","welche trolle haben fetische","troll-hexerei herkunft der fetische"}},{q="Welche Quest geht Troll-Hexerei voraus?",a="Troll-Hexerei folgt auf Kurzen's Mystery und setzt Bruder Nimetz' Untersuchung zum Wahnsinn des Colonels fort.",al={"troll-hexerei questreihe","was kommt vor troll-hexerei","voraussetzung für troll-hexerei"}}},fp="14,183,25.327.0,35.85.0,52.134.0,33.96.0,35.112.0"}
P.entries["quest:206"] = {n="Mai'Zoth",s="In den östlichen Bergen des Schlingendorntals hütet Mai'Zoth ein Relikt, das Gedanken verdrehen soll. Bruder Nimetz glaubt, dass der Ogermagier Colonel Kurzen verdorben hat, und will das Relikt bergen lassen, bevor ein weiterer Kommandant dasselbe Schicksal erleidet.",h="In den östlichen Bergen des Schlingendorntals hütet Mai'Zoth ein Relikt, das Gedanken verdrehen soll.",kw={"bruder nimetz","kurzen","mai'zoth","maizoth","gedankenauge","ogerhügel","rebellenlager","schlingendorntal"},ang={["faction:Alliance"]="Bruder Nimetz wirkt vom Rebellenlager im nördlichen Schlingendorntal aus. Er sucht Streiter der Allianz, die dem verborgenen Bösen ein Ende setzen, das Kurzen verdorben hat."},sec={{t="Die Quelle der Verderbnis",b="Bruder Nimetz glaubt, dass die Macht hinter Kurzens Rebellion fortbesteht. Seine Nachforschungen weisen auf Mai'Zoth hin, einen Ogermagier, der in einem Ogerhügel in den östlichen Höhen des Schlingendorntals lebt. Nimetz sagt, Mai'Zoth habe Kurzens Gedanken durch Zauberei verzerrt. Solange Mai'Zoth lebt, könnte ein weiterer Kommandant derselben Verderbnis anheimfallen."},{t="Das Relikt sichern",b="Bruder Nimetz bittet Euch, Mai'Zoth zu töten und ihm das Gedankenauge abzunehmen. Bringt das Artefakt zum Rebellenlager."},{t="Nach der Übergabe",b="Bruder Nimetz segnet jeden, der ihm das Gedankenauge bringt. Er will dessen Macht erforschen und herausfinden, ob sie dem Guten dienen kann. Falls nicht, muss es seinen Worten nach zerstört werden."}},faq={{q="Wer ist Mai'Zoth?",a="Mai'Zoth ist ein Ogermagier, der in einem Ogerhügel in den östlichen Bergen des Schlingendorntals lebt. Bruder Nimetz glaubt, dass Mai'Zoths Zauberei den Geist von Colonel Kurzen verdorben hat.",al={"wer ist maizoth","maizoth hintergrund","ogermagier maizoth"}},{q="Was ist das Gedankenauge?",a="Mai'Zoth besitzt das Gedankenauge, ein Artefakt, dem gedankenbeherrschende Magie nachgesagt wird. Er nutzt es, um andere zu verderben und zu beeinflussen.",al={"gedankenauge hintergrund","was ist das artefakt","gedankenauge"}},{q="Warum will Bruder Nimetz Mai'Zoth töten lassen?",a="Bruder Nimetz fürchtet, Mai'Zoths Verderbnis könnte jemand anderen in einen weiteren Kurzen verwandeln, und will den Oger deshalb töten lassen.",al={"nimetz beweggrund","warum maizoth töten","grund für die jagd auf maizoth"}}},fp="8,232,24.322.0,18.112.0,18.166.1,16.175.0,23.130.0,44.115.0"}
